class V2InvariantError(ValueError):
    """The frozen V2 protocol or one of its evidence bindings differs."""


class V2IntegrityStop(RuntimeError):
    """A durable attempt exists but scientific continuation must stop."""

    boundary_code_chain: tuple[str, ...] = ()


def _clear_exception_retention(
    error: BaseException, seen: set[int] | None = None
) -> None:
    if seen is None:
        seen = set()
    identity = id(error)
    if identity in seen:
        return
    seen.add(identity)
    if isinstance(error, BaseExceptionGroup):
        for member in error.exceptions:
            _clear_exception_retention(member, seen)
    for linked in (error.__cause__, error.__context__):
        if linked is not None:
            _clear_exception_retention(linked, seen)
    observed = error.__traceback__
    if observed is not None:
        traceback.clear_frames(observed)
    error.__traceback__ = None
    error.__cause__ = None
    error.__context__ = None


def _redacted_failure(error: BaseException, code: str) -> V2IntegrityStop:
    """Drop traceback-held live owners while retaining one bounded failure code."""

    code = _text(code, "redacted failure code", 128)
    _clear_exception_retention(error)
    return V2IntegrityStop(code)


def _is_cleanup_boundary_code(value: object) -> bool:
    return (
        type(value) is str
        and _BOUNDARY_FAILURE_CODE_RE.fullmatch(value) is not None
        and value in _CLEANUP_BOUNDARY_CODES
    )


def _extract_cleanup_boundary_codes(error: BaseException) -> tuple[str, ...]:
    """Extract only allowlisted codes from exact redacted cleanup failures."""

    codes: list[str] = []
    observed_errors: set[int] = set()
    truncated = False

    def append(value: object) -> None:
        nonlocal truncated
        if value == _BOUNDARY_CODE_CHAIN_TRUNCATED:
            truncated = True
            return
        if not _is_cleanup_boundary_code(value) or value in codes:
            return
        if len(codes) >= _MAX_BOUNDARY_CODE_CHAIN:
            truncated = True
            return
        codes.append(value)

    def visit(observed: BaseException) -> None:
        identity = id(observed)
        if identity in observed_errors:
            return
        observed_errors.add(identity)
        if type(observed) is V2IntegrityStop:
            chain = observed.boundary_code_chain
            if (
                type(chain) is tuple
                and chain
                and all(_is_cleanup_boundary_code(value) for value in chain)
            ):
                for value in chain:
                    append(value)
            elif (
                len(observed.args) == 1
                and _is_cleanup_boundary_code(observed.args[0])
            ):
                append(observed.args[0])
        if isinstance(observed, BaseExceptionGroup):
            for member in observed.exceptions:
                visit(member)

    visit(error)
    if truncated:
        return (
            *codes[: _MAX_BOUNDARY_CODE_CHAIN - 1],
            _BOUNDARY_CODE_CHAIN_TRUNCATED,
        )
    return tuple(codes)


def _redacted_cleanup_failure(
    error: BaseException, code: str
) -> V2IntegrityStop:
    """Drop live owners while retaining a bounded cleanup boundary-code chain."""

    code = _text(code, "cleanup boundary failure code", 128)
    if not _is_cleanup_boundary_code(code):
        raise ValueError("cleanup boundary failure code is not allowlisted")
    extracted = _extract_cleanup_boundary_codes(error)
    truncated = _BOUNDARY_CODE_CHAIN_TRUNCATED in extracted
    codes = [code]
    for value in extracted:
        if value == _BOUNDARY_CODE_CHAIN_TRUNCATED:
            continue
        if value not in codes:
            codes.append(value)
    if truncated or len(codes) > _MAX_BOUNDARY_CODE_CHAIN:
        chain = (
            *codes[: _MAX_BOUNDARY_CODE_CHAIN - 1],
            _BOUNDARY_CODE_CHAIN_TRUNCATED,
        )
    else:
        chain = tuple(codes)
    _clear_exception_retention(error)
    redacted = V2IntegrityStop(">".join(chain))
    redacted.boundary_code_chain = chain
    return redacted


class RunMode(str, Enum):
    QUALIFICATION = "qualification"
    EVALUATION = "evaluation"


def _text(value: object, label: str, maximum: int = 16_384) -> str:
    if type(value) is not str or not value or len(value) > maximum:
        raise ValueError(f"{label} must be nonempty bounded text")
    if value != unicodedata.normalize("NFC", value):
        raise ValueError(f"{label} must be NFC-normalized")
    return value


def _ref(value: object, label: str) -> str:
    if type(value) is not str or _REF_RE.fullmatch(value) is None:
        raise ValueError(f"{label} must be a lowercase sha256 reference")
    return value


def _raw_digest(value: object, label: str) -> str:
    if type(value) is not str or _RAW_DIGEST_RE.fullmatch(value) is None:
        raise ValueError(f"{label} must be a lowercase SHA-256 digest")
    return value


def _integer(
    value: object,
    label: str,
    *,
    minimum: int = 0,
    maximum: int | None = None,
) -> int:
    if type(value) is not int or value < minimum:
        raise ValueError(f"{label} must be an integer of at least {minimum}")
    if maximum is not None and value > maximum:
        raise ValueError(f"{label} exceeds {maximum}")
    return value


def _finite(value: object, label: str) -> float:
    if type(value) not in (int, float) or isinstance(value, bool):
        raise TypeError(f"{label} must be numeric")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{label} must be finite")
    return result


def _validate_json(value: object, *, depth: int = 0) -> None:
    if depth > 64:
        raise ValueError("canonical JSON exceeds the depth ceiling")
    if value is None or type(value) in (bool, int, str):
        if type(value) is str and value != unicodedata.normalize("NFC", value):
            raise ValueError("canonical JSON text must be NFC-normalized")
        return
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("canonical JSON cannot contain non-finite numbers")
        return
    if type(value) is list:
        for item in value:
            _validate_json(item, depth=depth + 1)
        return
    if type(value) is dict:
        if any(type(key) is not str for key in value):
            raise TypeError("canonical JSON object keys must be text")
        for key, item in value.items():
            _validate_json(key, depth=depth + 1)
            _validate_json(item, depth=depth + 1)
        return
    raise TypeError("canonical JSON contains an unsupported type")


def canonical_json_bytes(value: object) -> bytes:
    _validate_json(value)
    return json.dumps(
        value,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def canonical_ref(domain: str, value: object) -> str:
    domain = _text(domain, "content-reference domain", 512)
    return "sha256:" + hashlib.sha256(
        domain.encode("utf-8") + b"\x00" + canonical_json_bytes(value)
    ).hexdigest()


def domain_ref(domain: bytes, value: object) -> str:
    if type(domain) is not bytes or not domain:
        raise TypeError("digest domain must be nonempty bytes")
    return "sha256:" + hashlib.sha256(domain + canonical_json_bytes(value)).hexdigest()


def content_ref(value: object) -> str:
    """Match Angler's canonical JSON content-reference convention."""

    return "sha256:" + hashlib.sha256(canonical_json_bytes(value)).hexdigest()


def raw_sha256(value: bytes) -> str:
    if type(value) is not bytes:
        raise TypeError("raw SHA-256 input must be bytes")
    return hashlib.sha256(value).hexdigest()


def sha256_file(path: str | Path) -> tuple[str, int]:
    target = Path(path)
    digest = hashlib.sha256()
    total = 0
    with target.open("rb") as handle:
        while True:
            block = handle.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
            total += len(block)
    return digest.hexdigest(), total


def _canonical_mapping(value: object, label: str) -> dict[str, object]:
    if type(value) is dict:
        result = dict(value)
    elif isinstance(value, Mapping):
        result = dict(value)
    else:
        method = getattr(value, "to_canonical", None)
        if not callable(method):
            method = getattr(value, "to_payload", None)
        if not callable(method):
            raise TypeError(f"{label} lacks a canonical projection")
        result = method()
        if type(result) is not dict:
            raise TypeError(f"{label} canonical projection must be an exact object")
    canonical_json_bytes(result)
    return result


def _canonical_object_bytes(value: object, label: str) -> bytes:
    method = getattr(value, "canonical_bytes", None)
    if callable(method):
        result = method()
        if type(result) is not bytes or not result:
            raise ValueError(f"{label} canonical bytes are invalid")
        return result
    return canonical_json_bytes(_canonical_mapping(value, label))


def validate_arm(value: object) -> Arm:
    if value not in ARMS:
        raise ValueError("arm is not declared by V2")
    return value  # type: ignore[return-value]


def validate_family(value: object) -> Family:
    if value not in FAMILIES:
        raise ValueError("family is not declared by V2")
    return value  # type: ignore[return-value]


def validate_phase(value: object) -> Phase:
    if value not in PHASES:
        raise ValueError("phase is not declared by V2")
    return value  # type: ignore[return-value]


def validate_purpose(value: object) -> Purpose:
    if value not in ("qualification", "evaluation"):
        raise ValueError("purpose is not declared by V2")
    return value  # type: ignore[return-value]


def safe_component(value: object, label: str = "path component") -> str:
    if type(value) is not str or _SAFE_COMPONENT_RE.fullmatch(value) is None:
        raise ValueError(f"{label} is not one safe path component")
    if value in (".", ".."):
        raise ValueError(f"{label} cannot traverse")
    return value


def seed_commitment(raw_seed: bytes) -> str:
    if type(raw_seed) is not bytes or len(raw_seed) != 32:
        raise ValueError("replicate seed must contain exactly 32 bytes")
    return "sha256:" + hashlib.sha256(REPLICATE_SEED_DOMAIN + raw_seed).hexdigest()


def qualification_replicate_commitment() -> str:
    return seed_commitment(QUALIFICATION_RAW_KEY)


def validate_evaluation_seed_commitments(
    commitments: Sequence[str],
) -> tuple[str, str, str]:
    values = tuple(commitments)
    if len(values) != 3:
        raise ValueError("evaluation requires exactly three seed commitments")
    for value in values:
        _ref(value, "evaluation seed commitment")
    if len(set(values)) != 3:
        raise V2InvariantError("evaluation seed commitments are not distinct")
    if qualification_replicate_commitment() in values:
        raise V2InvariantError("evaluation seed reuses the qualification commitment")
    overlap = set(values) & CONSUMED_SEED_COMMITMENTS
    if overlap:
        raise V2InvariantError("evaluation seed commitment was already consumed")
    return values  # type: ignore[return-value]


def derive_family_seed(raw_key: bytes, family: Family, role: str) -> int:
    if type(raw_key) is not bytes or len(raw_key) != 32:
        raise ValueError("raw key must contain exactly 32 bytes")
    family = validate_family(family)
    roles = {
        "symbolic-demonstration-transfer": frozenset({"adaptation"}),
        "glyph-machine": frozenset({"adaptation", "surface"}),
        "causal-operator": frozenset({"adaptation", "development", "final"}),
    }
    if role not in roles[family]:
        raise ValueError("role is not declared for this family")
    message = f"{PROTOCOL_IDENTITY}\x00{family}\x00{role}".encode("utf-8")
    return int.from_bytes(hmac.new(raw_key, message, hashlib.sha256).digest()[:8], "big")


def control_selection_index(public_task_ref: str, proposal_count: int) -> int:
    public_task_ref = _ref(public_task_ref, "public task reference")
    proposal_count = _integer(
        proposal_count, "proposal count", minimum=2, maximum=64
    )
    value = hashlib.sha256(
        CONTROL_INDEX_DOMAIN + public_task_ref.encode("ascii")
    ).digest()
    return int.from_bytes(value, "big") % proposal_count


def expected_live_paths() -> tuple[Path, ...]:
    return (
        STATE_ROOT,
        SCRATCH_ROOT,
        MANIFEST_PATH,
        QUALIFICATION_RESULT_PATH,
        EVALUATION_RESULT_PATH,
        SEALED_SEED_PATH,
        QUALIFICATION_RELEASE_CLAIM_PATH,
        EVALUATION_ADMISSION_CLAIM_PATH,
    )


def assert_all_live_paths_absent(paths: Sequence[Path] | None = None) -> None:
    selected = expected_live_paths() if paths is None else tuple(paths)
    if not selected or len(set(selected)) != len(selected):
        raise ValueError("live-path inventory must be nonempty and unique")
    for path in selected:
        if not isinstance(path, Path) or not path.is_absolute():
            raise ValueError("live-path inventory contains a non-absolute path")
        try:
            os.lstat(path)
        except FileNotFoundError:
            continue
        raise V2InvariantError(f"one-use live path already exists: {path}")


def validate_frozen_construction_sources(
    source_inventory: Sequence[Mapping[str, object]],
) -> dict[str, str]:
    """Join construction authority to the already-captured source bytes."""

    rows = tuple(source_inventory)
    if len(rows) != len(SOURCE_MANIFEST_INVENTORY):
        raise V2InvariantError("frozen construction source inventory differs")
    observed: dict[str, str] = {}
    for raw in rows:
        if not isinstance(raw, Mapping):
            raise TypeError("frozen construction source row differs")
        row = dict(raw)
        if set(row) != {"bytes", "mode", "path", "sha256"}:
            raise V2InvariantError("frozen construction source row differs")
        path = row["path"]
        digest = row["sha256"]
        if type(path) is not str or path in observed:
            raise V2InvariantError("frozen construction source path differs")
        observed[path] = _raw_digest(
            digest, f"frozen construction source {path} digest"
        )
    expected = {
        str(ACTIVE_LEAF_PATH.relative_to(REPOSITORY_ROOT)): (
            CURRENT_AUTHORIZED_LEAF_SHA256
        ),
        str(R2_RUNNER_PATH.relative_to(REPOSITORY_ROOT)): FROZEN_R2_RUNNER_SHA256,
        str(EVALUATOR_PATH.relative_to(REPOSITORY_ROOT)): (
            FROZEN_V2_EVALUATOR_SHA256
        ),
    }
    failures = {
        path: (observed.get(path), digest)
        for path, digest in expected.items()
        if observed.get(path) != digest
    }
    if failures:
        raise V2IntegrityStop("frozen construction source authority changed")
    return {path: observed[path] for path in sorted(expected)}


