def _stable_regular_bytes(
    path: Path,
    *,
    expected_mode: int,
    expected_owner_uid: int | None = None,
    expected_owner_gid: int | None = None,
    maximum_bytes: int,
    label: str,
) -> bytes:
    if not path.is_absolute() or type(expected_mode) is not int:
        raise ValueError(f"{label} path/mode differs")
    maximum_bytes = _integer(
        maximum_bytes, f"{label} maximum bytes", minimum=1
    )
    if (expected_owner_uid is None) != (expected_owner_gid is None):
        raise ValueError(f"{label} owner boundary differs")
    owner_uid = (
        os.geteuid()
        if expected_owner_uid is None
        else _integer(expected_owner_uid, f"{label} owner uid", minimum=0)
    )
    owner_gid = (
        os.getegid()
        if expected_owner_gid is None
        else _integer(expected_owner_gid, f"{label} owner gid", minimum=0)
    )
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(path, flags)
    try:
        opened = os.fstat(descriptor)
        current = os.lstat(path)
        if (
            not stat.S_ISREG(opened.st_mode)
            or stat.S_IMODE(opened.st_mode) != expected_mode
            or opened.st_nlink != 1
            or opened.st_uid != owner_uid
            or opened.st_gid != owner_gid
            or (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino)
            or not 1 <= opened.st_size <= maximum_bytes
        ):
            raise V2IntegrityStop(f"{label} metadata differs")
        chunks = bytearray()
        while len(chunks) <= maximum_bytes:
            block = os.read(
                descriptor,
                min(1024 * 1024, maximum_bytes + 1 - len(chunks)),
            )
            if not block:
                break
            chunks.extend(block)
        after = os.fstat(descriptor)
        latest = os.lstat(path)
        if (
            len(chunks) != opened.st_size
            or len(chunks) > maximum_bytes
            or (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns)
            != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
            or (after.st_dev, after.st_ino) != (latest.st_dev, latest.st_ino)
        ):
            raise V2IntegrityStop(f"{label} changed while read")
    finally:
        os.close(descriptor)
    return bytes(chunks)


def _source_inventory_snapshot(
    repository_root: str | Path = REPOSITORY_ROOT,
    *,
    injected_root: bool = False,
    expected_owner_uid: int | None = None,
    expected_owner_gid: int | None = None,
) -> list[dict[str, object]]:
    root = Path(repository_root)
    if not root.is_absolute() or type(injected_root) is not bool:
        raise ValueError("source inventory root differs")
    if not injected_root and root != REPOSITORY_ROOT:
        raise V2InvariantError("source inventory escaped the literal repository")
    root_resolved = root.resolve(strict=True)
    if root_resolved != root:
        raise V2InvariantError("source inventory root aliases another path")
    if (
        tuple(sorted(SOURCE_MANIFEST_INVENTORY)) != SOURCE_MANIFEST_INVENTORY
        or len(set(SOURCE_MANIFEST_INVENTORY)) != len(SOURCE_MANIFEST_INVENTORY)
    ):
        raise V2InvariantError("source inventory is not exact, sorted, and unique")
    rows: list[dict[str, object]] = []
    identities: set[tuple[int, int]] = set()
    for relative in SOURCE_MANIFEST_INVENTORY:
        relative_path = Path(relative)
        if relative_path.is_absolute() or ".." in relative_path.parts:
            raise V2InvariantError("source inventory path traverses")
        target = root / relative_path
        resolved = target.resolve(strict=True)
        if resolved != target or root_resolved not in resolved.parents:
            raise V2InvariantError("source inventory path escaped its root")
        raw = _stable_regular_bytes(
            target,
            expected_mode=0o664,
            expected_owner_uid=expected_owner_uid,
            expected_owner_gid=expected_owner_gid,
            maximum_bytes=4 * 1024 * 1024,
            label=f"source inventory {relative}",
        )
        metadata = os.lstat(target)
        identity = (int(metadata.st_dev), int(metadata.st_ino))
        if identity in identities:
            raise V2IntegrityStop("source inventory contains an inode alias")
        identities.add(identity)
        rows.append(
            {
                "bytes": len(raw),
                "mode": "0664",
                "path": relative,
                "sha256": hashlib.sha256(raw).hexdigest(),
            }
        )
    expected_consumed = {
        str(CONSUMED_BASE_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_BASE_MANIFEST_SHA256
        ),
        str(CONSUMED_PREDECESSOR_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_PREDECESSOR_MANIFEST_SHA256
        ),
        str(CONSUMED_R2_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_R2_MANIFEST_SHA256
        ),
        str(CONSUMED_R3_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_R3_MANIFEST_SHA256
        ),
        str(CONSUMED_R4_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_R4_MANIFEST_SHA256
        ),
        str(CONSUMED_R5_MANIFEST_PATH.relative_to(REPOSITORY_ROOT)): (
            CONSUMED_R5_MANIFEST_SHA256
        ),
    }
    observed_consumed = {
        str(row["path"]): str(row["sha256"])
        for row in rows
        if row["path"] in expected_consumed
    }
    if observed_consumed != expected_consumed:
        raise V2IntegrityStop("consumed source manifest identity changed")
    validate_frozen_construction_sources(rows)
    return rows


