def validate_foundation_mirror_preflight_receipt(
    receipt: FoundationMirrorPreflightReceipt | Mapping[str, object],
    *,
    source_inventory: Sequence[Mapping[str, object]] | None = None,
    repository_root: str | Path = REPOSITORY_ROOT,
    injected_root: bool = False,
) -> dict[str, object]:
    """Validate one public preflight receipt against the current source bytes."""

    if type(receipt) is FoundationMirrorPreflightReceipt:
        value = receipt.to_canonical()
        observed = receipt
    elif isinstance(receipt, Mapping):
        value = dict(receipt)
        observed = FoundationMirrorPreflightReceipt.from_canonical(value)
    else:
        raise TypeError("foundation preflight receipt differs")
    sources = (
        [dict(row) for row in source_inventory]
        if source_inventory is not None
        else _source_inventory_snapshot(
            repository_root, injected_root=injected_root
        )
    )
    if (
        len(sources) != len(SOURCE_MANIFEST_INVENTORY)
        or observed.source_count != len(sources)
        or observed.source_inventory_ref
        != canonical_ref("source-inventory", sources)
    ):
        raise V2IntegrityStop("foundation preflight source inventory changed")
    if not injected_root:
        scratch = Path("/opt/angler/scratch")
        metadata = os.lstat(scratch)
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or scratch.resolve(strict=True) != scratch
            or metadata.st_uid != os.geteuid()
            or metadata.st_gid != os.getegid()
            or stat.S_IMODE(metadata.st_mode) != 0o700
        ):
            raise V2IntegrityStop("foundation preflight host scratch changed")
        _require_absent(
            scratch / FOUNDATION_PREFLIGHT_PRIVATE_ROOT.name,
            "foundation preflight private host path",
        )
        closure = _canonical_mapping(
            value["host_closure"], "foundation preflight host closure"
        )
        if (
            closure["host_scratch_device"] != int(metadata.st_dev)
            or closure["host_scratch_inode"] != int(metadata.st_ino)
            or closure["host_scratch_uid"] != int(metadata.st_uid)
            or closure["host_scratch_gid"] != int(metadata.st_gid)
            or closure["host_scratch_mode"]
            != f"{stat.S_IMODE(metadata.st_mode):04o}"
        ):
            raise V2IntegrityStop("foundation preflight host identity changed")
    return value


