def _evaluation_admission_boundary(
    *,
    manifest_ref: str,
    manifest_sha256: str,
    qualification_result_ref: str,
    qualification_result_sha256: str,
    qualification_release_ref: str,
    source_seal_ref: str,
) -> dict[str, object]:
    payload = {
        "identity": EVALUATION_IDENTITY,
        "manifest_ref": _ref(manifest_ref, "admission manifest ref"),
        "manifest_sha256": _raw_digest(
            manifest_sha256, "admission manifest digest"
        ),
        "protocol_identity": PROTOCOL_IDENTITY,
        "qualification_release_ref": _ref(
            qualification_release_ref, "admission qualification release"
        ),
        "qualification_result_ref": _ref(
            qualification_result_ref, "admission qualification result"
        ),
        "qualification_result_sha256": _raw_digest(
            qualification_result_sha256, "admission qualification result digest"
        ),
        "source_seal_ref": _ref(source_seal_ref, "admission source seal"),
    }
    return {
        **payload,
        "preseed_boundary_ref": canonical_ref(
            "evaluation-preseed-boundary", payload
        ),
    }


def _validated_evaluation_admission_boundary(
    boundary: Mapping[str, object],
) -> dict[str, object]:
    value = dict(boundary)
    expected_keys = {
        "preseed_boundary_ref",
        "identity",
        "manifest_ref",
        "manifest_sha256",
        "protocol_identity",
        "qualification_release_ref",
        "qualification_result_ref",
        "qualification_result_sha256",
        "source_seal_ref",
    }
    if set(value) != expected_keys:
        raise V2InvariantError("evaluation admission boundary fields differ")
    expected = _evaluation_admission_boundary(
        manifest_ref=value["manifest_ref"],  # type: ignore[arg-type]
        manifest_sha256=value["manifest_sha256"],  # type: ignore[arg-type]
        qualification_result_ref=value["qualification_result_ref"],  # type: ignore[arg-type]
        qualification_result_sha256=value["qualification_result_sha256"],  # type: ignore[arg-type]
        qualification_release_ref=value["qualification_release_ref"],  # type: ignore[arg-type]
        source_seal_ref=value["source_seal_ref"],  # type: ignore[arg-type]
    )
    if value != expected:
        raise V2IntegrityStop("evaluation admission boundary digest differs")
    return value


def _validate_seed_seal_receipt(
    receipt: Mapping[str, object],
    *,
    boundary: Mapping[str, object],
    expected_seed_path: str | Path = SEALED_SEED_PATH,
) -> dict[str, object]:
    value = dict(receipt)
    seed_path = Path(expected_seed_path)
    if not seed_path.is_absolute():
        raise ValueError("expected seed receipt path must be absolute")
    expected_keys = {
        "preseed_boundary_ref",
        "artifact_bytes",
        "artifact_device",
        "artifact_inode",
        "artifact_mode",
        "artifact_path",
        "artifact_sha256",
        "commitments",
        "evaluator_commitments_ref",
        "identity",
        "manifest_ref",
        "manifest_sha256",
        "protocol_identity",
        "qualification_release_ref",
        "qualification_result_ref",
        "qualification_result_sha256",
        "schema",
        "seed_seal_ref",
        "source_seal_ref",
    }
    if set(value) != expected_keys:
        raise V2IntegrityStop("seed seal receipt fields differ")
    if (
        value["schema"] != SEED_SEAL_RECEIPT_SCHEMA
        or value["identity"] != EVALUATION_IDENTITY
        or value["protocol_identity"] != PROTOCOL_IDENTITY
        or value["artifact_path"] != str(seed_path)
        or value["artifact_mode"] != "0600"
        or type(value["artifact_bytes"]) is not int
        or not 1 <= value["artifact_bytes"] <= MAXIMUM_SEALED_SEED_BYTES
        or type(value["artifact_device"]) is not int
        or value["artifact_device"] < 0
        or type(value["artifact_inode"]) is not int
        or value["artifact_inode"] < 1
    ):
        raise V2IntegrityStop("seed seal receipt identity/metadata differs")
    for name in ("artifact_sha256", "manifest_sha256", "qualification_result_sha256"):
        _raw_digest(value[name], f"seed seal {name}")
    commitments = validate_evaluation_seed_commitments(value["commitments"])
    _ref(value["evaluator_commitments_ref"], "seed evaluator commitments ref")
    for name in (
        "preseed_boundary_ref",
        "manifest_ref",
        "qualification_release_ref",
        "qualification_result_ref",
        "seed_seal_ref",
        "source_seal_ref",
    ):
        _ref(value[name], f"seed seal {name}")
    for name in (
        "preseed_boundary_ref",
        "manifest_ref",
        "manifest_sha256",
        "qualification_release_ref",
        "qualification_result_ref",
        "qualification_result_sha256",
        "source_seal_ref",
    ):
        if value[name] != boundary[name]:
            raise V2IntegrityStop("seed seal receipt boundary differs")
    payload = dict(value)
    observed_ref = payload.pop("seed_seal_ref")
    if observed_ref != canonical_ref("evaluation-seed-seal", payload):
        raise V2IntegrityStop("seed seal receipt ref differs")
    if tuple(value["commitments"]) != commitments:
        raise V2IntegrityStop("seed seal commitment order differs")
    return value


def _rejoin_sealed_seed_artifact_metadata(
    receipt: Mapping[str, object],
    *,
    expected_seed_path: str | Path = SEALED_SEED_PATH,
) -> dict[str, object]:
    """Bind the live seed inode and size to its public receipt without reading it."""

    value = dict(receipt)
    target = Path(str(value.get("artifact_path")))
    expected = Path(expected_seed_path)
    if target != expected or not target.is_absolute() or not expected.is_absolute():
        raise V2IntegrityStop("sealed seed metadata path differs")
    try:
        if target.resolve(strict=True) != target:
            raise V2IntegrityStop("sealed seed metadata path aliases")
        metadata = os.lstat(target)
    except OSError as error:
        raise V2IntegrityStop("sealed seed metadata is unavailable") from error
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_IMODE(metadata.st_mode) != 0o600
        or metadata.st_nlink != 1
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
        or int(metadata.st_dev) != value.get("artifact_device")
        or int(metadata.st_ino) != value.get("artifact_inode")
        or int(metadata.st_size) != value.get("artifact_bytes")
        or not 1 <= metadata.st_size <= MAXIMUM_SEALED_SEED_BYTES
    ):
        raise V2IntegrityStop("sealed seed metadata differs from receipt")
    return {
        "artifact_bytes": int(metadata.st_size),
        "artifact_device": int(metadata.st_dev),
        "artifact_inode": int(metadata.st_ino),
        "artifact_path": str(target),
        "seed_seal_ref": _ref(value.get("seed_seal_ref"), "sealed seed metadata ref"),
    }


def build_evaluation_admission_claim(
    *,
    boundary: Mapping[str, object],
    seed_receipt: Mapping[str, object],
    evaluator_commitments: Mapping[str, object],
    expected_seed_path: str | Path = SEALED_SEED_PATH,
) -> dict[str, object]:
    boundary_value = _validated_evaluation_admission_boundary(boundary)
    receipt = _validate_seed_seal_receipt(
        seed_receipt,
        boundary=boundary_value,
        expected_seed_path=expected_seed_path,
    )
    commitments = _canonical_mapping(
        evaluator_commitments, "admission evaluator commitments"
    )
    commitments_ref = canonical_ref("evaluator-commitments", commitments)
    if (
        commitments_ref != receipt["evaluator_commitments_ref"]
        or commitments.get("identity") != EVALUATION_IDENTITY
        or commitments.get("protocol_identity") != PROTOCOL_IDENTITY
        or commitments.get("purpose") != "evaluation"
        or commitments.get("replicate_commitments") != receipt["commitments"]
    ):
        raise V2IntegrityStop("admission evaluator commitments differ")
    payload = {
        **boundary_value,
        "evaluator_commitments": commitments,
        "evaluator_commitments_ref": commitments_ref,
        "schema": EVALUATION_ADMISSION_SCHEMA,
        "seed_artifact_sha256": receipt["artifact_sha256"],
        "seed_commitments": list(receipt["commitments"]),
        "seed_seal_receipt": receipt,
        "seed_seal_ref": receipt["seed_seal_ref"],
    }
    return {
        **payload,
        "admission_ref": canonical_ref("evaluation-admission", payload),
    }


def validate_evaluation_admission_claim(
    claim: Mapping[str, object],
    *,
    boundary: Mapping[str, object],
    seed_receipt: Mapping[str, object],
    evaluator_commitments: Mapping[str, object],
    expected_seed_path: str | Path = SEALED_SEED_PATH,
) -> dict[str, object]:
    expected = build_evaluation_admission_claim(
        boundary=boundary,
        seed_receipt=seed_receipt,
        evaluator_commitments=evaluator_commitments,
        expected_seed_path=expected_seed_path,
    )
    value = dict(claim)
    if value != expected:
        raise V2IntegrityStop("evaluation admission claim differs")
    return value


def publish_evaluation_admission_claim_create_once(
    claim: Mapping[str, object],
    *,
    boundary: Mapping[str, object],
    seed_receipt: Mapping[str, object],
    evaluator_commitments: Mapping[str, object],
    path: str | Path = EVALUATION_ADMISSION_CLAIM_PATH,
    seed_path: str | Path = SEALED_SEED_PATH,
    injected_paths: bool = False,
) -> tuple[dict[str, object], str]:
    if type(injected_paths) is not bool:
        raise TypeError("evaluation admission injection flag differs")
    target = Path(path)
    expected_path = target if injected_paths else EVALUATION_ADMISSION_CLAIM_PATH
    value = validate_evaluation_admission_claim(
        claim,
        boundary=boundary,
        seed_receipt=seed_receipt,
        evaluator_commitments=evaluator_commitments,
        expected_seed_path=seed_path,
    )
    return _publish_canonical_create_once(
        target,
        value,
        expected_path=expected_path,
        mode=0o600,
        expected_parent_mode=(
            stat.S_IMODE(os.lstat(target.parent).st_mode)
            if injected_paths
            else 0o700
        ),
        maximum_bytes=4 * 1024 * 1024,
        label="evaluation admission claim",
    )


def _fsync_directory(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _require_owned_directory(
    path: Path,
    *,
    expected_mode: int,
    empty: bool | None = None,
    label: str,
) -> tuple[str, int, int]:
    identity = _private_root_identity(path, label)
    if identity[0] != str(path) or stat.S_IMODE(os.lstat(path).st_mode) != expected_mode:
        raise V2IntegrityStop(f"{label} metadata differs")
    if empty is not None and (next(path.iterdir(), None) is None) is not empty:
        raise V2IntegrityStop(f"{label} emptiness differs")
    return identity


def _create_private_directory_once(path: Path, *, parent_mode: int = 0o700) -> Path:
    if (
        not path.is_absolute()
        or path.parent == path
        or "." in path.parts
        or ".." in path.parts
    ):
        raise ValueError("private directory path differs")
    _require_owned_directory(
        path.parent,
        expected_mode=parent_mode,
        label="private directory parent",
    )
    try:
        os.mkdir(path, 0o700)
    except FileExistsError as error:
        raise V2IntegrityStop(f"one-use directory already exists: {path}") from error
    os.chmod(path, 0o700)
    _fsync_directory(path.parent)
    _require_owned_directory(path, expected_mode=0o700, empty=True, label="private directory")
    return path


def _write_private_bytes_create_once(
    path: Path,
    value: bytes,
    *,
    maximum_bytes: int,
) -> None:
    """Publish one bounded private file without a replace or symlink window."""

    if (
        not path.is_absolute()
        or path.parent == path
        or "." in path.parts
        or ".." in path.parts
        or type(value) is not bytes
        or not 1 <= len(value) <= maximum_bytes
    ):
        raise ValueError("private byte publication inputs differ")
    _require_owned_directory(
        path.parent,
        expected_mode=0o700,
        label="private byte publication parent",
    )
    flags = os.O_CREAT | os.O_EXCL | os.O_WRONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags, 0o600)
    created = os.fstat(descriptor)
    try:
        if (
            not stat.S_ISREG(created.st_mode)
            or created.st_nlink != 1
            or created.st_uid != os.geteuid()
            or created.st_gid != os.getegid()
        ):
            raise V2IntegrityStop("private byte file metadata differs")
        view = memoryview(value)
        offset = 0
        while offset < len(view):
            written = os.write(descriptor, view[offset:])
            if written <= 0:
                raise OSError("private byte publication made no progress")
            offset += written
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    _fsync_directory(path.parent)
    final = os.lstat(path)
    reopened = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        reopened_metadata = os.fstat(reopened)
        observed = bytearray()
        while len(observed) <= maximum_bytes:
            chunk = os.read(reopened, min(1024 * 1024, maximum_bytes + 1 - len(observed)))
            if not chunk:
                break
            observed.extend(chunk)
    finally:
        os.close(reopened)
    if (
        stat.S_IMODE(final.st_mode) != 0o600
        or final.st_nlink != 1
        or (final.st_dev, final.st_ino) != (created.st_dev, created.st_ino)
        or (reopened_metadata.st_dev, reopened_metadata.st_ino)
        != (created.st_dev, created.st_ino)
        or bytes(observed) != value
    ):
        raise V2IntegrityStop("private byte publication verification differs")


def _replace_private_bytes_durable(
    path: Path,
    value: bytes,
    *,
    maximum_bytes: int,
) -> None:
    """Atomically replace one owned lineage snapshot and fsync its directory."""

    if (
        not path.is_absolute()
        or type(value) is not bytes
        or not 1 <= len(value) <= maximum_bytes
    ):
        raise ValueError("private byte replacement inputs differ")
    _require_owned_regular_file(
        path,
        expected_mode=0o600,
        label="private byte replacement target",
    )
    pending = path.with_name(path.name + ".pending")
    _require_absent(pending, "private byte replacement pending file")
    _write_private_bytes_create_once(
        pending,
        value,
        maximum_bytes=maximum_bytes,
    )
    os.replace(pending, path)
    _fsync_directory(path.parent)
    _require_owned_regular_file(
        path,
        expected_mode=0o600,
        label="private byte replacement result",
    )
    if path.read_bytes() != value:
        raise V2IntegrityStop("private byte replacement content differs")


def _read_private_bytes_bounded(
    path: Path,
    *,
    maximum_bytes: int,
    label: str,
) -> bytes:
    """Read one exact owned private file without following path substitutions."""

    maximum_bytes = _integer(
        maximum_bytes, f"{label} maximum bytes", minimum=1
    )
    identity = _require_owned_regular_file(
        path, expected_mode=0o600, label=label
    )
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        opened = os.fstat(descriptor)
        if (int(opened.st_dev), int(opened.st_ino)) != identity[1:]:
            raise V2IntegrityStop(f"{label} inode changed while opening")
        output = bytearray()
        while len(output) <= maximum_bytes:
            block = os.read(
                descriptor,
                min(1024 * 1024, maximum_bytes + 1 - len(output)),
            )
            if not block:
                break
            output.extend(block)
    finally:
        os.close(descriptor)
    value = bytes(output)
    if not value or len(value) > maximum_bytes:
        raise V2IntegrityStop(f"{label} is empty or exceeds its byte ceiling")
    return value


def _remove_exact_private_tree(path: Path, *, expected_parent: Path) -> None:
    """Remove one explicitly named disposable owned tree and prove absence."""

    if (
        not path.is_absolute()
        or path.parent != expected_parent
        or safe_component(path.name, "disposable private tree name") != path.name
    ):
        raise V2IntegrityStop("disposable private tree path differs")
    _require_owned_directory(
        expected_parent,
        expected_mode=0o700,
        label="disposable private tree parent",
    )
    identity = _private_root_identity(path, "disposable private tree")
    if identity[0] != str(path):
        raise V2IntegrityStop("disposable private tree is not canonical")
    shutil.rmtree(path)
    _fsync_directory(expected_parent)
    try:
        os.lstat(path)
    except FileNotFoundError:
        return
    raise V2IntegrityStop("disposable private tree remains after cleanup")


def validate_live_parent_boundary(
    *,
    environment: Mapping[str, str] | None = None,
    expected_environment: Mapping[str, str] | None = None,
    executable: str | Path | None = None,
    runner_path: str | Path | None = None,
    working_directory: str | Path | None = None,
    interface_inventory: Callable[[], Sequence[tuple[int, str]]] | None = None,
    text_reader: Callable[[Path], str] | None = None,
    namespace_reader: Callable[[Path], str] | None = None,
    gpu_inventory_runner: Callable[..., object] | None = None,
    gpu_process_runner: Callable[..., object] | None = None,
    require_unassigned_zero_processes: bool = False,
    hostname_reader: Callable[[], str] | None = None,
    python_version_reader: Callable[[], str] | None = None,
    distribution_reader: Callable[[str], str] | None = None,
    torch_module: object | None = None,
    temporary_directory_state: Literal["absent", "owned-empty"] = "owned-empty",
    activate_cuda_runtime: bool = True,
    inherited_worker_parent_attestor: Callable[
        ..., Mapping[str, object]
    ]
    | None = None,
) -> dict[str, object]:
    """Validate the exact offline host/GPU/software boundary for one live phase."""

    observed_environment = dict(os.environ if environment is None else environment)
    frozen_environment = dict(
        _frozen_parent_environment()
        if expected_environment is None
        else expected_environment
    )
    if observed_environment != frozen_environment:
        raise V2IntegrityStop("live parent environment differs")
    if type(require_unassigned_zero_processes) is not bool:
        raise TypeError("live GPU-process requirement differs")
    if type(temporary_directory_state) is not str or temporary_directory_state not in (
        "absent",
        "owned-empty",
    ):
        raise ValueError("live temporary-directory state differs")
    if type(activate_cuda_runtime) is not bool:
        raise TypeError("live CUDA-runtime phase differs")
    expected_temporary_state = (
        "owned-empty" if activate_cuda_runtime else "absent"
    )
    if temporary_directory_state != expected_temporary_state:
        raise ValueError("live CUDA/temporary-directory phase differs")
    observed_executable = Path(sys.executable if executable is None else executable)
    observed_runner = Path(__file__ if runner_path is None else runner_path).resolve()
    observed_cwd = Path.cwd() if working_directory is None else Path(working_directory)
    if (
        observed_executable != ANGLER_PYTHON
        or observed_runner != RUNNER_PATH
        or observed_cwd != REPOSITORY_ROOT
    ):
        raise V2IntegrityStop("live executable/cwd differs")
    temporary = Path(observed_environment["TMPDIR"])
    if temporary_directory_state == "absent":
        _require_owned_directory(
            SCRATCH_ROOT.parent,
            expected_mode=0o700,
            label="live scratch parent",
        )
        _require_absent(SCRATCH_ROOT, "live scratch root")
        _require_absent(temporary, "live temporary directory")
    else:
        _require_owned_directory(
            temporary,
            expected_mode=0o700,
            empty=True,
            label="live temporary directory",
        )
    inventory = interface_inventory or socket.if_nameindex
    read_text = text_reader or (lambda path: path.read_text(encoding="ascii"))
    read_namespace = namespace_reader or os.readlink
    interfaces = tuple(inventory())
    ipv4 = tuple(
        line
        for line in read_text(Path("/proc/net/route")).splitlines()[1:]
        if line.strip()
    )
    ipv6 = tuple(
        tuple(line.split())
        for line in read_text(Path("/proc/net/ipv6_route")).splitlines()
        if line.strip()
    )
    namespace = read_namespace(Path("/proc/self/ns/net"))
    if (
        interfaces != ((1, "lo"),)
        or ipv4
        or not ipv6
        or any(len(row) != 10 or row[-1] != "lo" for row in ipv6)
        or read_text(Path("/sys/class/net/lo/operstate")).strip() != "unknown"
        or re.fullmatch(r"net:\[[0-9]+\]", namespace) is None
    ):
        raise V2IntegrityStop("live parent is not loopback-only")
    inherited_worker_parent = _attest_v2_inherited_worker_parent(
        namespace,
        attestor=inherited_worker_parent_attestor,
        interface_inventory=lambda: interfaces,
        text_reader=read_text,
        namespace_reader=read_namespace,
    )
    hostname = (hostname_reader or socket.gethostname)()
    python_version = (python_version_reader or platform.python_version)()
    if hostname != EXPECTED_HOSTNAME or python_version != EXPECTED_PYTHON_VERSION:
        raise V2IntegrityStop("live host/Python identity differs")
    distribution = distribution_reader or distribution_version
    try:
        distributions = {
            name: distribution(name) for name in EXPECTED_PARENT_DISTRIBUTIONS
        }
    except PackageNotFoundError as error:
        raise V2IntegrityStop("live dependency is absent") from error
    if distributions != dict(EXPECTED_PARENT_DISTRIBUTIONS):
        raise V2IntegrityStop("live dependency versions differ")
    completed = (gpu_inventory_runner or subprocess.run)(
        (
            "/usr/bin/nvidia-smi",
            "--query-gpu=uuid,name,pci.bus_id,compute_cap,memory.total,memory.free",
            "--format=csv,noheader,nounits",
        ),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    output = getattr(completed, "stdout", None)
    if type(output) is not str:
        raise V2IntegrityStop("physical GPU inventory is absent")
    physical: dict[str, dict[str, object]] = {}
    for line in output.splitlines():
        fields = tuple(item.strip() for item in line.split(","))
        if len(fields) != 6 or fields[0] in physical:
            raise V2IntegrityStop("physical GPU inventory is malformed")
        physical[fields[0]] = {
            "compute_capability": fields[3],
            "free_mib": int(fields[5]),
            "name": fields[1],
            "pci_bus_id": fields[2],
            "total_mib": int(fields[4]),
        }
    expected_physical = {
        ASSIGNED_GPU_UUID: {
            "compute_capability": "12.0",
            "name": "NVIDIA GeForce RTX 5080",
            "pci_bus_id": "00000000:01:00.0",
            "total_mib": 16_303,
        },
        UNASSIGNED_GPU_UUID: {
            "compute_capability": "12.0",
            "name": "NVIDIA GeForce RTX 5070",
            "pci_bus_id": "00000000:05:00.0",
            "total_mib": 12_227,
        },
    }
    if set(physical) != set(expected_physical) or any(
        {key: item for key, item in physical[uuid].items() if key != "free_mib"}
        != expected
        for uuid, expected in expected_physical.items()
    ):
        raise V2IntegrityStop("physical GPU identity differs")
    if int(physical[ASSIGNED_GPU_UUID]["free_mib"]) < 14_336:
        raise V2IntegrityStop("assigned GPU free-memory floor is not met")
    unassigned_compute_processes = 0
    if require_unassigned_zero_processes:
        process_completed = (gpu_process_runner or subprocess.run)(
            (
                "/usr/bin/nvidia-smi",
                "--query-compute-apps=gpu_uuid,pid",
                "--format=csv,noheader,nounits",
            ),
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        )
        process_output = getattr(process_completed, "stdout", None)
        if type(process_output) is not str:
            raise V2IntegrityStop("physical GPU process inventory is absent")
        process_rows: list[tuple[str, int]] = []
        for line in process_output.splitlines():
            if not line.strip():
                continue
            fields = tuple(item.strip() for item in line.split(","))
            if len(fields) != 2 or fields[0] not in expected_physical:
                raise V2IntegrityStop("physical GPU process inventory differs")
            try:
                pid = int(fields[1])
            except ValueError as error:
                raise V2IntegrityStop(
                    "physical GPU process PID differs"
                ) from error
            if pid < 1:
                raise V2IntegrityStop("physical GPU process PID differs")
            process_rows.append((fields[0], pid))
        unassigned_compute_processes = sum(
            uuid == UNASSIGNED_GPU_UUID for uuid, _pid in process_rows
        )
        if (
            len(set(process_rows)) != len(process_rows)
            or unassigned_compute_processes != 0
            or any(
                uuid == ASSIGNED_GPU_UUID and pid != os.getpid()
                for uuid, pid in process_rows
            )
        ):
            raise V2IntegrityStop("GPU compute-process ownership differs")
    configured = (
        int(observed_environment["OMP_NUM_THREADS"])
        + int(observed_environment["MKL_NUM_THREADS"])
        + int(observed_environment["OPENBLAS_NUM_THREADS"])
        + 2
        + 2
    )
    if configured != MAXIMUM_CONFIGURED_POOLS:
        raise V2IntegrityStop("configured worker-pool sum differs")
    if torch_module is None:
        import torch as torch_module  # type: ignore[no-redef]
    cuda = getattr(torch_module, "cuda", None)
    required = (
        getattr(torch_module, "set_num_threads", None),
        getattr(torch_module, "set_num_interop_threads", None),
        getattr(torch_module, "get_num_threads", None),
        getattr(torch_module, "get_num_interop_threads", None),
    )
    if cuda is None or not all(callable(item) for item in required):
        raise V2IntegrityStop("Torch resource boundary differs")
    if required[2]() != 2:
        required[0](2)
    if required[3]() != 1:
        required[1](1)
    if required[2]() != 2 or required[3]() != 1:
        raise V2IntegrityStop("Torch CPU pools differ")
    cudnn_version = getattr(
        getattr(getattr(torch_module, "backends", None), "cudnn", None),
        "version",
        None,
    )
    if (
        str(getattr(torch_module, "__version__", "")) != EXPECTED_TORCH_VERSION
        or getattr(getattr(torch_module, "version", None), "cuda", None)
        != EXPECTED_CUDA_VERSION
        or not callable(cudnn_version)
        or cuda.device_count() != 1
    ):
        raise V2IntegrityStop("Torch/CUDA build identity differs")
    common = {
        "configured_pool_sum": configured,
        "environment_sha256": hashlib.sha256(
            canonical_json_bytes(observed_environment)
        ).hexdigest(),
        "hostname": hostname,
        "inherited_worker_parent": inherited_worker_parent,
        "interfaces": [list(item) for item in interfaces],
        "network_namespace": namespace,
        "physical_gpus": [
            {**expected_physical[uuid], "uuid": uuid}
            for uuid in sorted(expected_physical)
        ],
        "unassigned_compute_processes": unassigned_compute_processes,
        "python": python_version,
        "python_executable": str(observed_executable),
        "runner": str(observed_runner),
        "software": {
            "cuda": EXPECTED_CUDA_VERSION,
            "distributions": distributions,
            "torch": EXPECTED_TORCH_VERSION,
        },
        "temporary_directory": str(temporary),
    }
    if not activate_cuda_runtime:
        _require_absent(SCRATCH_ROOT, "post-check live scratch root")
        _require_absent(temporary, "post-check live temporary directory")
        return common
    if cudnn_version() != EXPECTED_CUDNN_RUNTIME or not cuda.is_available():
        raise V2IntegrityStop("Torch/CUDA/cuDNN runtime identity differs")
    cuda.set_device(0)
    if cuda.current_device() != 0 or cuda.get_device_name(0) != (
        "NVIDIA GeForce RTX 5080"
    ):
        raise V2IntegrityStop("logical CUDA device differs")
    _require_owned_directory(
        temporary,
        expected_mode=0o700,
        empty=True,
        label="post-check live temporary directory",
    )
    return {
        **common,
        "logical_cuda_device": 0,
        "software": {
            "cuda": EXPECTED_CUDA_VERSION,
            "cudnn_runtime": EXPECTED_CUDNN_RUNTIME,
            "distributions": distributions,
            "torch": EXPECTED_TORCH_VERSION,
        },
    }


def validate_live_parent_boundary_rejoin(
    precreate: Mapping[str, object],
    activated: Mapping[str, object],
) -> None:
    """Rejoin side-effect-free host facts to the activated CUDA boundary."""

    common_keys = {
        "configured_pool_sum",
        "environment_sha256",
        "hostname",
        "inherited_worker_parent",
        "interfaces",
        "network_namespace",
        "physical_gpus",
        "python",
        "python_executable",
        "runner",
        "temporary_directory",
        "unassigned_compute_processes",
    }
    if set(precreate) != common_keys | {"software"} or set(activated) != (
        common_keys | {"logical_cuda_device", "software"}
    ):
        raise V2IntegrityStop("live parent phase fields differ")
    activated_software = activated.get("software")
    if type(activated_software) is not dict or set(activated_software) != {
        "cuda",
        "cudnn_runtime",
        "distributions",
        "torch",
    }:
        raise V2IntegrityStop("activated live software boundary differs")
    expected_precreate = {
        key: activated[key] for key in common_keys
    }
    expected_precreate["software"] = {
        key: activated_software[key]
        for key in ("cuda", "distributions", "torch")
    }
    if dict(precreate) != expected_precreate:
        raise V2IntegrityStop("live parent changed across CUDA activation")


def load_qualification_release_claim(
    manifest: Mapping[str, object],
    manifest_sha256: str,
    source_seal: Mapping[str, object],
    *,
    path: str | Path = QUALIFICATION_RELEASE_CLAIM_PATH,
    repository_root: str | Path = REPOSITORY_ROOT,
    injected_paths: bool = False,
) -> tuple[dict[str, object], str]:
    target = Path(path)
    if (
        not target.is_absolute()
        or (not injected_paths and target != QUALIFICATION_RELEASE_CLAIM_PATH)
    ):
        raise V2InvariantError("qualification release load path differs")
    value, raw = _read_canonical_artifact(
        target,
        expected_mode=0o600,
        maximum_bytes=64 * 1024,
        label="qualification release claim",
    )
    return (
        validate_qualification_release_claim(
            value,
            manifest,
            manifest_sha256,
            source_seal,
            repository_root=repository_root,
            injected_root=injected_paths,
        ),
        hashlib.sha256(raw).hexdigest(),
    )


def load_qualification_result(
    *,
    expected_source_seal_ref: str,
    expected_qualification_release_ref: str,
    path: str | Path = QUALIFICATION_RESULT_PATH,
    injected_paths: bool = False,
) -> tuple[dict[str, object], str]:
    target = Path(path)
    if (
        not target.is_absolute()
        or (not injected_paths and target != QUALIFICATION_RESULT_PATH)
    ):
        raise V2InvariantError("qualification result load path differs")
    value, raw = _read_canonical_artifact(
        target,
        expected_mode=0o600,
        maximum_bytes=MAXIMUM_RESULT_BYTES,
        label="qualification result",
    )
    validated = validate_run_result(value)
    if (
        validated.get("purpose") != "qualification"
        or validated.get("identity") != QUALIFICATION_IDENTITY
        or validated.get("authorization_ref")
        != _ref(
            expected_qualification_release_ref,
            "qualification result release authorization",
        )
        or validated.get("integrity", {}).get("source_seal_ref")
        != _ref(expected_source_seal_ref, "qualification source seal")
    ):
        raise V2IntegrityStop("qualification result chain differs")
    return validated, hashlib.sha256(raw).hexdigest()


def load_evaluation_result(
    *,
    expected_source_seal_ref: str,
    expected_admission_ref: str,
    path: str | Path = EVALUATION_RESULT_PATH,
    injected_paths: bool = False,
) -> tuple[dict[str, object], str]:
    target = Path(path)
    if (
        not target.is_absolute()
        or (not injected_paths and target != EVALUATION_RESULT_PATH)
    ):
        raise V2InvariantError("evaluation result load path differs")
    value, raw = _read_canonical_artifact(
        target,
        expected_mode=0o600,
        maximum_bytes=MAXIMUM_RESULT_BYTES,
        label="evaluation result",
    )
    validated = validate_run_result(value)
    if (
        validated.get("purpose") != "evaluation"
        or validated.get("identity") != EVALUATION_IDENTITY
        or validated.get("authorization_ref")
        != _ref(expected_admission_ref, "evaluation result admission")
        or validated.get("integrity", {}).get("source_seal_ref")
        != _ref(expected_source_seal_ref, "evaluation source seal")
    ):
        raise V2IntegrityStop("evaluation result chain differs")
    return validated, hashlib.sha256(raw).hexdigest()


def load_evaluation_admission_claim(
    *,
    path: str | Path = EVALUATION_ADMISSION_CLAIM_PATH,
    seed_path: str | Path = SEALED_SEED_PATH,
    injected_paths: bool = False,
) -> tuple[dict[str, object], str]:
    target = Path(path)
    if (
        not target.is_absolute()
        or (not injected_paths and target != EVALUATION_ADMISSION_CLAIM_PATH)
    ):
        raise V2InvariantError("evaluation admission load path differs")
    value, raw = _read_canonical_artifact(
        target,
        expected_mode=0o600,
        maximum_bytes=4 * 1024 * 1024,
        label="evaluation admission claim",
    )
    if type(value.get("seed_seal_receipt")) is not dict or type(
        value.get("evaluator_commitments")
    ) is not dict:
        raise V2IntegrityStop("evaluation admission material differs")
    boundary = {
        name: value.get(name)
        for name in (
            "preseed_boundary_ref",
            "identity",
            "manifest_ref",
            "manifest_sha256",
            "protocol_identity",
            "qualification_release_ref",
            "qualification_result_ref",
            "qualification_result_sha256",
            "source_seal_ref",
        )
    }
    validated = validate_evaluation_admission_claim(
        value,
        boundary=boundary,
        seed_receipt=value["seed_seal_receipt"],
        evaluator_commitments=value["evaluator_commitments"],
        expected_seed_path=seed_path,
    )
    return validated, hashlib.sha256(raw).hexdigest()


def _require_empty_evaluator_private_paths(
    *,
    cwd: str | Path = EVALUATOR_CWD,
    tmpdir: str | Path = EVALUATOR_TMP,
    injected_paths: bool = False,
) -> dict[str, object]:
    working = Path(cwd)
    temporary = Path(tmpdir)
    if (
        type(injected_paths) is not bool
        or (not injected_paths and (working != EVALUATOR_CWD or temporary != EVALUATOR_TMP))
        or working == temporary
    ):
        raise V2InvariantError("evaluator private path boundary differs")
    identities = (
        _require_owned_directory(
            working,
            expected_mode=0o700,
            empty=True,
            label="evaluator private cwd",
        ),
        _require_owned_directory(
            temporary,
            expected_mode=0o700,
            empty=True,
            label="evaluator private tmp",
        ),
    )
    if identities[0][1:] == identities[1][1:]:
        raise V2IntegrityStop("evaluator private paths alias")
    return {
        "cwd": identities[0][0],
        "cwd_device": identities[0][1],
        "cwd_inode": identities[0][2],
        "tmpdir": identities[1][0],
        "tmpdir_device": identities[1][1],
        "tmpdir_inode": identities[1][2],
    }


def _validate_private_worker_boundary(
    *,
    require_qualification_result: bool,
    environment: Mapping[str, str] | None = None,
    executable: str | Path | None = None,
    working_directory: str | Path | None = None,
    interface_inventory: Callable[[], Sequence[tuple[int, str]]] | None = None,
    text_reader: Callable[[Path], str] | None = None,
    namespace_reader: Callable[[Path], str] | None = None,
) -> dict[str, object]:
    if type(require_qualification_result) is not bool:
        raise TypeError("worker phase flag differs")
    expected_environment = _frozen_evaluator_environment()
    expected_environment["TMPDIR"] = str(EVALUATOR_TMP)
    observed_environment = dict(os.environ if environment is None else environment)
    observed_executable = Path(sys.executable if executable is None else executable)
    observed_cwd = Path.cwd() if working_directory is None else Path(working_directory)
    if (
        observed_environment != expected_environment
        or observed_executable != ANGLER_PYTHON
        or observed_cwd != EVALUATOR_CWD
        or os.geteuid() != 1000
        or os.getegid() != 1000
    ):
        raise V2IntegrityStop("private worker process boundary differs")
    _require_owned_directory(
        EVALUATOR_CWD,
        expected_mode=0o700,
        label="private worker cwd",
    )
    _require_owned_directory(
        EVALUATOR_TMP,
        expected_mode=0o700,
        label="private worker tmp",
    )
    inventory = interface_inventory or socket.if_nameindex
    read_text = text_reader or (lambda path: path.read_text(encoding="ascii"))
    read_namespace = namespace_reader or os.readlink
    interfaces = tuple(inventory())
    routes = tuple(
        line
        for line in read_text(Path("/proc/net/route")).splitlines()[1:]
        if line.strip()
    )
    namespace = read_namespace(Path("/proc/self/ns/net"))
    if (
        interfaces != ((1, "lo"),)
        or routes
        or re.fullmatch(r"net:\[[0-9]+\]", namespace) is None
    ):
        raise V2IntegrityStop("private worker is not loopback-only")
    manifest, manifest_sha256, source_seal = load_source_manifest()
    release, _release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    result: dict[str, object] | None = None
    result_sha256: str | None = None
    if require_qualification_result:
        result, result_sha256 = load_qualification_result(
            expected_source_seal_ref=source_seal["source_seal_ref"],  # type: ignore[arg-type]
            expected_qualification_release_ref=release["release_ref"],  # type: ignore[arg-type]
        )
    else:
        try:
            os.lstat(QUALIFICATION_RESULT_PATH)
        except FileNotFoundError:
            pass
        else:
            raise V2IntegrityStop("qualification worker started after result publication")
    return {
        "manifest": manifest,
        "manifest_sha256": manifest_sha256,
        "qualification_release": release,
        "qualification_result": result,
        "qualification_result_sha256": result_sha256,
        "source_seal": source_seal,
    }


_LIVE_PHASE_PATH_KEYS = frozenset(
    {
        "evaluation_admission",
        "evaluation_result",
        "evaluation_runtime",
        "manifest",
        "qualification_release",
        "qualification_result",
        "qualification_runtime",
        "scratch_root",
        "sealed_root",
        "seed",
        "state_root",
    }
)


def _live_phase_paths(
    overrides: Mapping[str, str | Path] | None = None,
) -> dict[str, Path]:
    values = {
        "evaluation_admission": EVALUATION_ADMISSION_CLAIM_PATH,
        "evaluation_result": EVALUATION_RESULT_PATH,
        "evaluation_runtime": EVALUATION_RUNTIME_ROOT,
        "manifest": MANIFEST_PATH,
        "qualification_release": QUALIFICATION_RELEASE_CLAIM_PATH,
        "qualification_result": QUALIFICATION_RESULT_PATH,
        "qualification_runtime": QUALIFICATION_RUNTIME_ROOT,
        "scratch_root": SCRATCH_ROOT,
        "sealed_root": STATE_ROOT / "sealed",
        "seed": SEALED_SEED_PATH,
        "state_root": STATE_ROOT,
    }
    if overrides is not None:
        if set(overrides) != _LIVE_PHASE_PATH_KEYS:
            raise ValueError("injected live phase path inventory differs")
        values = {name: Path(path) for name, path in overrides.items()}
    if set(values) != _LIVE_PHASE_PATH_KEYS or any(
        not path.is_absolute()
        or "." in path.parts
        or ".." in path.parts
        or path.resolve(strict=False) != path
        for path in values.values()
    ):
        raise V2InvariantError("live phase paths differ")
    if len(set(values.values())) != len(values):
        raise V2IntegrityStop("live phase paths alias lexically")
    exact_relationships = {
        "sealed_root": values["state_root"] / "sealed",
        "qualification_runtime": values["state_root"] / "qualification-v1",
        "evaluation_runtime": values["state_root"] / "evaluation-v1",
        "qualification_release": (
            values["sealed_root"] / "qualification-release-claim-v1.json"
        ),
        "seed": values["sealed_root"] / "evaluation-seeds-v1.json",
        "evaluation_admission": (
            values["sealed_root"] / "evaluation-admission-claim-v1.json"
        ),
    }
    if any(values[name] != expected for name, expected in exact_relationships.items()):
        raise V2IntegrityStop("live phase path hierarchy differs")
    return values


def _require_absent(path: Path, label: str) -> None:
    try:
        os.lstat(path)
    except FileNotFoundError:
        return
    raise V2IntegrityStop(f"{label} is already present")


def _exact_child_names(path: Path, expected: set[str], label: str) -> None:
    _require_owned_directory(path, expected_mode=0o700, label=label)
    observed = {item.name for item in path.iterdir()}
    if observed != expected:
        raise V2IntegrityStop(f"{label} child inventory differs")


def _require_owned_regular_file(
    path: Path, *, expected_mode: int, label: str
) -> tuple[str, int, int]:
    metadata = os.lstat(path)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or stat.S_IMODE(metadata.st_mode) != expected_mode
        or metadata.st_nlink != 1
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
        or path.resolve(strict=True) != path
    ):
        raise V2IntegrityStop(f"{label} metadata differs")
    return str(path), int(metadata.st_dev), int(metadata.st_ino)


def _require_non_aliasing_existing_paths(
    paths: Mapping[str, Path],
) -> None:
    identities: set[tuple[int, int]] = set()
    resolved: set[str] = set()
    for label, path in paths.items():
        metadata = os.lstat(path)
        if stat.S_ISLNK(metadata.st_mode):
            raise V2IntegrityStop(f"{label} is a symlink")
        current_resolved = str(path.resolve(strict=True))
        current_identity = (int(metadata.st_dev), int(metadata.st_ino))
        if (
            current_resolved != str(path)
            or current_resolved in resolved
            or current_identity in identities
        ):
            raise V2IntegrityStop("live phase existing paths alias")
        resolved.add(current_resolved)
        identities.add(current_identity)


def _validate_retained_runtime_from_result(
    *,
    purpose: Purpose,
    runtime_root: Path,
    state_root: Path,
    result: Mapping[str, object],
) -> dict[str, object]:
    """Rejoin the exact genesis and retained persistent baselines at a phase gate."""

    purpose = validate_purpose(purpose)
    validated = validate_run_result(result, state_root=state_root)
    if validated["purpose"] != purpose:
        raise V2IntegrityStop("retained runtime result purpose differs")
    observed_ledger = audit_evidence_ledger(
        runtime_root / "attempt-evidence.sqlite3",
        expected_attempts=(72 if purpose == "qualification" else 918),
    )
    if observed_ledger != validated["integrity"]["ledger"]:
        raise V2IntegrityStop("retained evidence ledger witness differs")
    _exact_child_names(
        runtime_root,
        {"arm-runtime", "attempt-evidence.sqlite3", "cognee-scopes", "genesis"},
        f"{purpose} runtime",
    )
    genesis_root = runtime_root / "genesis"
    arm_runtime = runtime_root / "arm-runtime"
    cognee_scopes = runtime_root / "cognee-scopes"
    _exact_child_names(
        genesis_root,
        {"binding.json", "core-state.pt", "learner-snapshot.pt"},
        f"{purpose} genesis",
    )
    for name in ("binding.json", "core-state.pt", "learner-snapshot.pt"):
        _require_owned_regular_file(
            genesis_root / name,
            expected_mode=0o600,
            label=f"{purpose} genesis {name}",
        )
    binding, _raw = _read_canonical_artifact(
        genesis_root / "binding.json",
        expected_mode=0o600,
        maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
        label=f"{purpose} genesis binding",
    )
    core_bytes = binding.get("core_state_bytes")
    core_digest = binding.get("core_state_sha256")
    if type(core_bytes) is not int or type(core_digest) is not str:
        raise V2IntegrityStop("retained genesis binding differs")
    helpers = _load_approved_r2_low_level_helpers()
    bundle = helpers["FreshGenesisBundle"](
        genesis_root,
        core_bytes,
        core_digest,
    )
    _call_r2_low_level(bundle.validate_artifacts)
    _require_owned_directory(
        cognee_scopes,
        expected_mode=0o700,
        empty=True,
        label=f"{purpose} retained Cognee scopes",
    )
    frozen = _canonical_mapping(
        validated["frozen_adaptation"], "retained frozen adaptation"
    )
    wrappers = frozen.get("baseline_seals")
    expected_count = 2 if purpose == "qualification" else 6
    if type(wrappers) is not list or len(wrappers) != expected_count:
        raise V2IntegrityStop("retained baseline inventory differs")
    seals: list[dict[str, object]] = []
    for wrapped in wrappers:
        row = _canonical_mapping(wrapped, "retained baseline wrapper")
        seal = _canonical_mapping(row.get("seal"), "retained baseline seal")
        seals.append(seal)
    expected_roots = {Path(str(seal["root"])) for seal in seals}
    _exact_child_names(
        arm_runtime,
        {path.name for path in expected_roots},
        f"{purpose} retained arm runtime",
    )
    if {path.parent for path in expected_roots} != {arm_runtime}:
        raise V2IntegrityStop("retained baseline parent differs")
    root_identities: set[tuple[int, int]] = set()
    for seal in seals:
        root = Path(str(seal["root"]))
        replicate = _ref(
            seal.get("replicate_commitment"), "retained baseline replicate"
        )
        arm = seal.get("arm")
        if arm not in STATEFUL_ARMS or root.name != _v2_lineage_slug(
            purpose, replicate, arm
        ):
            raise V2IntegrityStop("retained baseline path identity differs")
        identity = _private_root_identity(root, "retained baseline root")
        if identity[1:] in root_identities:
            raise V2IntegrityStop("retained baseline roots alias")
        root_identities.add(identity[1:])
        _exact_child_names(
            root,
            {
                "cognitive.sqlite3",
                "learner-state.bin",
                "qwen-execution-journal.sqlite3",
            },
            "retained baseline",
        )
        for name in (
            "cognitive.sqlite3",
            "learner-state.bin",
            "qwen-execution-journal.sqlite3",
        ):
            _require_owned_regular_file(
                root / name,
                expected_mode=0o600,
                label=f"retained baseline {name}",
            )
        paths = helpers["ClonePaths"](
            root=root,
            store=root / "cognitive.sqlite3",
            journal=root / "qwen-execution-journal.sqlite3",
            learner=root / "learner-state.bin",
        )
        observed = _call_r2_low_level(helpers["_closed_baseline_hashes"], paths)
        if observed != seal.get("hashes"):
            raise V2IntegrityStop("retained baseline hashes differ")
    return {
        "baseline_roots": sorted(str(path) for path in expected_roots),
        "genesis_root": str(genesis_root),
        "purpose": purpose,
    }


def validate_live_phase_topology(
    phase: Literal["pre-qualification", "pre-seed", "pre-evaluation"],
    *,
    path_overrides: Mapping[str, str | Path] | None = None,
) -> dict[str, object]:
    paths = _live_phase_paths(path_overrides)
    if phase not in ("pre-qualification", "pre-seed", "pre-evaluation"):
        raise ValueError("live topology phase differs")
    manifest = paths["manifest"]
    metadata = os.lstat(manifest)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_IMODE(metadata.st_mode) != 0o664
        or metadata.st_nlink != 1
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
        or manifest.resolve(strict=True) != manifest
    ):
        raise V2IntegrityStop("source manifest metadata differs")
    if phase == "pre-qualification":
        for name in (
            "state_root",
            "scratch_root",
            "qualification_result",
            "evaluation_result",
        ):
            _require_absent(paths[name], f"pre-qualification {name}")
        return {"phase": phase, "state": "ABSENT", "scratch": "ABSENT"}
    _exact_child_names(
        paths["state_root"],
        {"qualification-v1", "sealed"},
        "V2 state root",
    )
    _exact_child_names(
        paths["sealed_root"],
        (
            {"qualification-release-claim-v1.json"}
            if phase == "pre-seed"
            else {
                "evaluation-admission-claim-v1.json",
                "evaluation-seeds-v1.json",
                "qualification-release-claim-v1.json",
            }
        ),
        "V2 sealed root",
    )
    _exact_child_names(
        paths["scratch_root"],
        set(_frozen_manifest_topology()["scratch_children"]),
        "V2 scratch root",
    )
    for child in _frozen_manifest_topology()["scratch_children"]:
        _require_owned_directory(
            paths["scratch_root"] / str(child),
            expected_mode=0o700,
            label=f"V2 scratch {child}",
        )
    _require_owned_directory(
        EVALUATOR_CWD if path_overrides is None else paths["scratch_root"] / "evaluator-cwd",
        expected_mode=0o700,
        empty=True,
        label="V2 evaluator cwd",
    )
    _require_owned_directory(
        EVALUATOR_TMP if path_overrides is None else paths["scratch_root"] / "evaluator-tmp",
        expected_mode=0o700,
        empty=True,
        label="V2 evaluator tmp",
    )
    _require_owned_directory(
        paths["qualification_runtime"],
        expected_mode=0o700,
        label="qualification runtime",
    )
    qualification_runtime_children = {
        "arm-runtime",
        "attempt-evidence.sqlite3",
        "cognee-scopes",
        "genesis",
    }
    _exact_child_names(
        paths["qualification_runtime"],
        qualification_runtime_children,
        "qualification runtime",
    )
    for child in ("arm-runtime", "cognee-scopes", "genesis"):
        _require_owned_directory(
            paths["qualification_runtime"] / child,
            expected_mode=0o700,
            label=f"qualification runtime {child}",
        )
    _require_owned_regular_file(
        paths["qualification_runtime"] / "attempt-evidence.sqlite3",
        expected_mode=0o600,
        label="qualification evidence ledger",
    )
    _require_owned_regular_file(
        paths["qualification_release"],
        expected_mode=0o600,
        label="qualification release claim",
    )
    _require_owned_regular_file(
        paths["qualification_result"],
        expected_mode=0o600,
        label="qualification result",
    )
    qualification_result, _qualification_result_raw = _read_canonical_artifact(
        paths["qualification_result"],
        expected_mode=0o600,
        maximum_bytes=MAXIMUM_RESULT_BYTES,
        label="qualification result",
    )
    retained = _validate_retained_runtime_from_result(
        purpose="qualification",
        runtime_root=paths["qualification_runtime"],
        state_root=paths["state_root"],
        result=qualification_result,
    )
    if phase == "pre-seed":
        for name in ("seed", "evaluation_admission", "evaluation_runtime", "evaluation_result"):
            _require_absent(paths[name], f"pre-seed {name}")
    else:
        for name in ("evaluation_runtime", "evaluation_result"):
            _require_absent(paths[name], f"pre-evaluation {name}")
        for name in ("seed", "evaluation_admission"):
            _require_owned_regular_file(
                paths[name],
                expected_mode=0o600,
                label=f"pre-evaluation {name}",
            )
        admission, _admission_sha256 = load_evaluation_admission_claim(
            path=paths["evaluation_admission"],
            seed_path=paths["seed"],
            injected_paths=path_overrides is not None,
        )
        _rejoin_sealed_seed_artifact_metadata(
            admission["seed_seal_receipt"],
            expected_seed_path=paths["seed"],
        )
    existing_paths = {
        "manifest": paths["manifest"],
        "qualification_result": paths["qualification_result"],
        "qualification_release": paths["qualification_release"],
        "qualification_runtime": paths["qualification_runtime"],
        "qualification_arm_runtime": (
            paths["qualification_runtime"] / "arm-runtime"
        ),
        "qualification_cognee_scopes": (
            paths["qualification_runtime"] / "cognee-scopes"
        ),
        "qualification_evidence": (
            paths["qualification_runtime"] / "attempt-evidence.sqlite3"
        ),
        "qualification_genesis": paths["qualification_runtime"] / "genesis",
        "scratch_root": paths["scratch_root"],
        "sealed_root": paths["sealed_root"],
        "state_root": paths["state_root"],
        **{
            f"scratch_{name}": paths["scratch_root"] / name
            for name in _frozen_manifest_topology()["scratch_children"]
        },
    }
    if phase == "pre-evaluation":
        existing_paths.update(
            {
                "evaluation_admission": paths["evaluation_admission"],
                "evaluation_seed": paths["seed"],
            }
        )
    _require_non_aliasing_existing_paths(existing_paths)
    return {
        "phase": phase,
        "qualification_retained": retained,
        "scratch_children": sorted(item.name for item in paths["scratch_root"].iterdir()),
        "state_children": sorted(item.name for item in paths["state_root"].iterdir()),
    }


def _validate_evaluator_launch_topology(
    purpose: Purpose,
    replicate_commitments: Sequence[str],
) -> dict[str, object]:
    """Validate the exact post-product, pre-attempt topology seen by a worker."""

    purpose = validate_purpose(purpose)
    replicates = tuple(replicate_commitments)
    expected_count = 1 if purpose == "qualification" else 3
    if len(replicates) != expected_count or len(set(replicates)) != expected_count:
        raise V2IntegrityStop("evaluator launch replicate inventory differs")
    for value in replicates:
        _ref(value, "evaluator launch replicate")
    if purpose == "qualification" and replicates != (
        qualification_replicate_commitment(),
    ):
        raise V2IntegrityStop("qualification launch replicate differs")
    if purpose == "evaluation":
        validate_evaluation_seed_commitments(replicates)

    expected_state = {"qualification-v1", "sealed"}
    expected_sealed = {"qualification-release-claim-v1.json"}
    runtime_root = QUALIFICATION_RUNTIME_ROOT
    if purpose == "evaluation":
        expected_state.add("evaluation-v1")
        expected_sealed.update(
            {
                "evaluation-admission-claim-v1.json",
                "evaluation-seeds-v1.json",
            }
        )
        runtime_root = EVALUATION_RUNTIME_ROOT
    _exact_child_names(STATE_ROOT, expected_state, "evaluator launch state root")
    _exact_child_names(
        STATE_ROOT / "sealed", expected_sealed, "evaluator launch sealed root"
    )
    _exact_child_names(
        SCRATCH_ROOT,
        set(_frozen_manifest_topology()["scratch_children"]),
        "evaluator launch scratch root",
    )
    for child in _frozen_manifest_topology()["scratch_children"]:
        _require_owned_directory(
            SCRATCH_ROOT / str(child),
            expected_mode=0o700,
            label=f"evaluator launch scratch {child}",
        )
    _require_owned_directory(
        EVALUATOR_CWD,
        expected_mode=0o700,
        empty=True,
        label="evaluator launch cwd",
    )
    _require_owned_directory(
        EVALUATOR_TMP,
        expected_mode=0o700,
        empty=True,
        label="evaluator launch tmp",
    )
    _exact_child_names(
        runtime_root,
        {"arm-runtime", "attempt-evidence.sqlite3", "cognee-scopes", "genesis"},
        f"{purpose} launch runtime",
    )
    _require_owned_regular_file(
        runtime_root / "attempt-evidence.sqlite3",
        expected_mode=0o600,
        label=f"{purpose} launch evidence ledger",
    )
    _require_owned_directory(
        runtime_root / "cognee-scopes",
        expected_mode=0o700,
        empty=True,
        label=f"{purpose} launch Cognee scopes",
    )
    genesis_root = runtime_root / "genesis"
    _exact_child_names(
        genesis_root,
        {"binding.json", "core-state.pt", "learner-snapshot.pt"},
        f"{purpose} launch genesis",
    )
    for name in ("binding.json", "core-state.pt", "learner-snapshot.pt"):
        _require_owned_regular_file(
            genesis_root / name,
            expected_mode=0o600,
            label=f"{purpose} launch genesis {name}",
        )
    binding, _raw = _read_canonical_artifact(
        genesis_root / "binding.json",
        expected_mode=0o600,
        maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
        label=f"{purpose} launch genesis binding",
    )
    core_bytes = binding.get("core_state_bytes")
    core_digest = binding.get("core_state_sha256")
    if type(core_bytes) is not int or type(core_digest) is not str:
        raise V2IntegrityStop("evaluator launch genesis binding differs")
    helpers = _load_approved_r2_low_level_helpers()
    bundle = helpers["FreshGenesisBundle"](genesis_root, core_bytes, core_digest)
    _call_r2_low_level(bundle.validate_artifacts)

    arm_runtime = runtime_root / "arm-runtime"
    expected_slugs = {
        _v2_lineage_slug(purpose, replicate, arm)
        for replicate in replicates
        for arm in STATEFUL_ARMS
    }
    _exact_child_names(arm_runtime, expected_slugs, f"{purpose} launch lineages")
    for slug in expected_slugs:
        root = arm_runtime / slug
        _exact_child_names(
            root,
            {
                "cognitive.sqlite3",
                "learner-state.bin",
                "qwen-execution-journal.sqlite3",
            },
            f"{purpose} launch lineage",
        )
        for name in (
            "cognitive.sqlite3",
            "learner-state.bin",
            "qwen-execution-journal.sqlite3",
        ):
            _require_owned_regular_file(
                root / name,
                expected_mode=0o600,
                label=f"{purpose} launch lineage {name}",
            )
    if purpose == "qualification":
        for path, label in (
            (QUALIFICATION_RESULT_PATH, "qualification result"),
            (SEALED_SEED_PATH, "evaluation seed"),
            (EVALUATION_ADMISSION_CLAIM_PATH, "evaluation admission"),
            (EVALUATION_RUNTIME_ROOT, "evaluation runtime"),
            (EVALUATION_RESULT_PATH, "evaluation result"),
        ):
            _require_absent(path, f"qualification launch {label}")
    else:
        _require_absent(EVALUATION_RESULT_PATH, "evaluation launch result")
        manifest, manifest_sha256, source_seal = load_source_manifest()
        release, _release_sha256 = load_qualification_release_claim(
            manifest, manifest_sha256, source_seal
        )
        qualification, _qualification_sha256 = load_qualification_result(
            expected_source_seal_ref=source_seal["source_seal_ref"],
            expected_qualification_release_ref=release["release_ref"],
        )
        _validate_retained_runtime_from_result(
            purpose="qualification",
            runtime_root=QUALIFICATION_RUNTIME_ROOT,
            state_root=STATE_ROOT,
            result=qualification,
        )
        for path, label in (
            (SEALED_SEED_PATH, "evaluation seed"),
            (EVALUATION_ADMISSION_CLAIM_PATH, "evaluation admission"),
        ):
            _require_owned_regular_file(
                path, expected_mode=0o600, label=f"evaluation launch {label}"
            )
    return {
        "lineage_count": len(expected_slugs),
        "purpose": purpose,
        "runtime_root": str(runtime_root),
    }


def validate_live_terminal_topology() -> dict[str, object]:
    """Reopen the complete durable chain and exact post-evaluation topology."""

    manifest, manifest_sha256, source_seal = load_source_manifest()
    release, release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    qualification, qualification_sha256 = load_qualification_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_qualification_release_ref=release["release_ref"],
    )
    admission, admission_sha256 = load_evaluation_admission_claim()
    expected_boundary = _evaluation_admission_boundary(
        manifest_ref=manifest["manifest_ref"],
        manifest_sha256=manifest_sha256,
        qualification_result_ref=qualification["result_ref"],
        qualification_result_sha256=qualification_sha256,
        qualification_release_ref=release["release_ref"],
        source_seal_ref=source_seal["source_seal_ref"],
    )
    if any(admission.get(name) != value for name, value in expected_boundary.items()):
        raise V2IntegrityStop("terminal evaluation admission chain differs")
    _rejoin_sealed_seed_artifact_metadata(admission["seed_seal_receipt"])
    seed_verification = verify_evaluation_seed_artifact_isolated(
        admission, admission_sha256
    )
    evaluation, evaluation_sha256 = load_evaluation_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_admission_ref=admission["admission_ref"],
    )

    _exact_child_names(
        STATE_ROOT,
        {"evaluation-v1", "qualification-v1", "sealed"},
        "terminal V2 state root",
    )
    _exact_child_names(
        STATE_ROOT / "sealed",
        {
            "evaluation-admission-claim-v1.json",
            "evaluation-seeds-v1.json",
            "qualification-release-claim-v1.json",
        },
        "terminal V2 sealed root",
    )
    _exact_child_names(
        SCRATCH_ROOT,
        set(_frozen_manifest_topology()["scratch_children"]),
        "terminal V2 scratch root",
    )
    for child in _frozen_manifest_topology()["scratch_children"]:
        _require_owned_directory(
            SCRATCH_ROOT / str(child),
            expected_mode=0o700,
            label=f"terminal V2 scratch {child}",
        )
    _require_owned_directory(
        EVALUATOR_CWD,
        expected_mode=0o700,
        empty=True,
        label="terminal evaluator cwd",
    )
    _require_owned_directory(
        EVALUATOR_TMP,
        expected_mode=0o700,
        empty=True,
        label="terminal evaluator tmp",
    )
    qualification_retained = _validate_retained_runtime_from_result(
        purpose="qualification",
        runtime_root=QUALIFICATION_RUNTIME_ROOT,
        state_root=STATE_ROOT,
        result=qualification,
    )
    evaluation_retained = _validate_retained_runtime_from_result(
        purpose="evaluation",
        runtime_root=EVALUATION_RUNTIME_ROOT,
        state_root=STATE_ROOT,
        result=evaluation,
    )
    for path, label in (
        (QUALIFICATION_RELEASE_CLAIM_PATH, "terminal qualification release"),
        (QUALIFICATION_RESULT_PATH, "terminal qualification result"),
        (SEALED_SEED_PATH, "terminal evaluation seed"),
        (EVALUATION_ADMISSION_CLAIM_PATH, "terminal evaluation admission"),
        (EVALUATION_RESULT_PATH, "terminal evaluation result"),
        (QUALIFICATION_EVIDENCE_LEDGER_PATH, "terminal qualification ledger"),
        (EVALUATION_EVIDENCE_LEDGER_PATH, "terminal evaluation ledger"),
    ):
        _require_owned_regular_file(path, expected_mode=0o600, label=label)
    existing_paths = {
        "manifest": MANIFEST_PATH,
        "state_root": STATE_ROOT,
        "sealed_root": STATE_ROOT / "sealed",
        "scratch_root": SCRATCH_ROOT,
        "qualification_release": QUALIFICATION_RELEASE_CLAIM_PATH,
        "qualification_result": QUALIFICATION_RESULT_PATH,
        "qualification_runtime": QUALIFICATION_RUNTIME_ROOT,
        "qualification_arm_runtime": QUALIFICATION_RUNTIME_ROOT / "arm-runtime",
        "qualification_cognee_scopes": (
            QUALIFICATION_RUNTIME_ROOT / "cognee-scopes"
        ),
        "qualification_genesis": QUALIFICATION_RUNTIME_ROOT / "genesis",
        "qualification_ledger": QUALIFICATION_EVIDENCE_LEDGER_PATH,
        "evaluation_seed": SEALED_SEED_PATH,
        "evaluation_admission": EVALUATION_ADMISSION_CLAIM_PATH,
        "evaluation_result": EVALUATION_RESULT_PATH,
        "evaluation_runtime": EVALUATION_RUNTIME_ROOT,
        "evaluation_arm_runtime": EVALUATION_RUNTIME_ROOT / "arm-runtime",
        "evaluation_cognee_scopes": EVALUATION_RUNTIME_ROOT / "cognee-scopes",
        "evaluation_genesis": EVALUATION_RUNTIME_ROOT / "genesis",
        "evaluation_ledger": EVALUATION_EVIDENCE_LEDGER_PATH,
        **{
            f"scratch_{name}": SCRATCH_ROOT / str(name)
            for name in _frozen_manifest_topology()["scratch_children"]
        },
        **{
            f"qualification_baseline_{ordinal}": Path(path)
            for ordinal, path in enumerate(
                qualification_retained["baseline_roots"]
            )
        },
        **{
            f"evaluation_baseline_{ordinal}": Path(path)
            for ordinal, path in enumerate(evaluation_retained["baseline_roots"])
        },
    }
    _require_non_aliasing_existing_paths(existing_paths)
    state_scratch_bytes = _bounded_no_follow_state_scratch_bytes(
        STATE_ROOT, SCRATCH_ROOT
    )
    return {
        "admission_sha256": admission_sha256,
        "evaluation_result_ref": evaluation["result_ref"],
        "evaluation_result_sha256": evaluation_sha256,
        "qualification_result_sha256": qualification_sha256,
        "qualification_release_sha256": release_sha256,
        "seed_artifact_sha256": seed_verification["artifact_sha256"],
        "seed_seal_ref": seed_verification["seed_seal_ref"],
        "source_manifest_sha256": manifest_sha256,
        "state_scratch_bytes": state_scratch_bytes,
    }


def create_qualification_live_roots_once() -> None:
    """Create only the exact root topology after the live boundary is announced."""

    validate_live_phase_topology("pre-qualification")
    _create_private_directory_once(STATE_ROOT, parent_mode=0o775)
    _create_private_directory_once(STATE_ROOT / "sealed")
    _create_private_directory_once(SCRATCH_ROOT, parent_mode=0o700)
    for name in _frozen_manifest_topology()["scratch_children"]:
        _create_private_directory_once(SCRATCH_ROOT / str(name))


def publish_reviewed_source_manifest(
    expected_sha256: str,
    preflight_receipt: FoundationMirrorPreflightReceipt | Mapping[str, object],
) -> dict[str, object]:
    """Explicit pre-live publication; candidate generation itself remains read-only."""

    expected = _raw_digest(expected_sha256, "reviewed source manifest digest")
    assert_all_live_paths_absent()
    candidate = build_source_manifest_candidate(preflight_receipt)
    raw = canonical_json_bytes(candidate)
    if hashlib.sha256(raw).hexdigest() != expected:
        raise V2IntegrityStop("reviewed source manifest digest differs")
    _value, observed = publish_source_manifest_create_once(candidate)
    if observed != expected:
        raise V2IntegrityStop("published source manifest digest differs")
    loaded, loaded_sha256, source_seal = load_source_manifest()
    if loaded != candidate or loaded_sha256 != expected:
        raise V2IntegrityStop("published source manifest revalidation differs")
    return {
        "manifest_ref": loaded["manifest_ref"],
        "path": str(MANIFEST_PATH),
        "sha256": loaded_sha256,
        "source_seal_ref": source_seal["source_seal_ref"],
    }


def _reload_evaluation_admission_boundary() -> dict[str, object]:
    """Reopen the complete qualified chain that authorizes seed admission."""

    manifest, manifest_sha256, source_seal = load_source_manifest()
    release, _release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    qualification, qualification_sha256 = load_qualification_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_qualification_release_ref=release["release_ref"],
    )
    return _evaluation_admission_boundary(
        manifest_ref=manifest["manifest_ref"],
        manifest_sha256=manifest_sha256,
        qualification_result_ref=qualification["result_ref"],
        qualification_result_sha256=qualification_sha256,
        qualification_release_ref=release["release_ref"],
        source_seal_ref=source_seal["source_seal_ref"],
    )


def prepare_evaluation_admission_live() -> dict[str, object]:
    """Seal fresh seeds and publish their exact post-qualification admission."""

    host = validate_live_parent_boundary(require_unassigned_zero_processes=True)
    validate_live_phase_topology("pre-seed")
    manifest, manifest_sha256, source_seal = load_source_manifest()
    release, _release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    qualification, qualification_sha256 = load_qualification_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],  # type: ignore[arg-type]
        expected_qualification_release_ref=release["release_ref"],  # type: ignore[arg-type]
    )
    boundary = _evaluation_admission_boundary(
        manifest_ref=manifest["manifest_ref"],  # type: ignore[arg-type]
        manifest_sha256=manifest_sha256,
        qualification_result_ref=qualification["result_ref"],  # type: ignore[arg-type]
        qualification_result_sha256=qualification_sha256,
        qualification_release_ref=release["release_ref"],  # type: ignore[arg-type]
        source_seal_ref=source_seal["source_seal_ref"],  # type: ignore[arg-type]
    )
    worker = create_evaluation_seed_seal_isolated(boundary)
    primary: BaseException | None = None
    publication: tuple[dict[str, object], str] | None = None
    claim: dict[str, object] | None = None
    try:
        claim = build_evaluation_admission_claim(
            boundary=boundary,
            seed_receipt=worker.seed_receipt,
            evaluator_commitments=worker.evaluator_commitments,
        )
        worker.revalidate(claim["admission_ref"])  # type: ignore[arg-type]
        current_manifest, current_sha256, current_seal = load_source_manifest()
        current_release, _ = load_qualification_release_claim(
            current_manifest, current_sha256, current_seal
        )
        current_qualification, current_qualification_sha256 = (
            load_qualification_result(
                expected_source_seal_ref=current_seal["source_seal_ref"],  # type: ignore[arg-type]
                expected_qualification_release_ref=current_release["release_ref"],  # type: ignore[arg-type]
            )
        )
        current_boundary = _evaluation_admission_boundary(
            manifest_ref=current_manifest["manifest_ref"],  # type: ignore[arg-type]
            manifest_sha256=current_sha256,
            qualification_result_ref=current_qualification["result_ref"],  # type: ignore[arg-type]
            qualification_result_sha256=current_qualification_sha256,
            qualification_release_ref=current_release["release_ref"],  # type: ignore[arg-type]
            source_seal_ref=current_seal["source_seal_ref"],  # type: ignore[arg-type]
        )
        if current_boundary != boundary:
            raise V2IntegrityStop("admission durable boundary changed before publish")
    except BaseException as error:
        primary = error
    cleanup: BaseException | None = None
    try:
        worker.close()
    except BaseException as error:
        cleanup = error
    if primary is not None and cleanup is not None:
        raise BaseExceptionGroup(
            "evaluation admission and commitment-worker cleanup failed",
            [primary, cleanup],
        )
    if primary is not None:
        raise primary.with_traceback(primary.__traceback__)
    if cleanup is not None:
        raise cleanup.with_traceback(cleanup.__traceback__)
    if claim is None:
        raise V2IntegrityStop("evaluation admission claim is absent")
    if _reload_evaluation_admission_boundary() != boundary:
        raise V2IntegrityStop("admission durable boundary changed after worker close")
    publication = publish_evaluation_admission_claim_create_once(
        claim,
        boundary=boundary,
        seed_receipt=worker.seed_receipt,
        evaluator_commitments=worker.evaluator_commitments,
    )
    if _reload_evaluation_admission_boundary() != boundary:
        raise V2IntegrityStop("admission durable boundary changed after publish")
    loaded, admission_sha256 = load_evaluation_admission_claim()
    if loaded != publication[0] or admission_sha256 != publication[1]:
        raise V2IntegrityStop("evaluation admission post-publication differs")
    validate_live_phase_topology("pre-evaluation")
    if _reload_evaluation_admission_boundary() != boundary:
        raise V2IntegrityStop("admission durable boundary changed during topology rejoin")
    return {
        "admission_ref": claim["admission_ref"],
        "admission_sha256": admission_sha256,
        "host_environment_sha256": host["environment_sha256"],
        "seed_commitments": list(worker.seed_receipt["commitments"]),
        "seed_seal_ref": worker.seed_receipt["seed_seal_ref"],
    }


