def _load_approved_r2_low_level_helpers() -> dict[str, object]:
    """Load only reviewed identity-neutral mechanics from the frozen source."""

    observed, _ = sha256_file(R2_RUNNER_PATH)
    if observed != FROZEN_R2_RUNNER_SHA256:
        raise V2IntegrityStop("approved low-level helper source changed")
    from experiments.runners import high_level_multidomain_v1_r2 as predecessor

    helpers = {
        name: getattr(predecessor, name, None)
        for name in _APPROVED_R2_LOW_LEVEL_HELPERS
    }
    if (
        tuple(sorted(helpers)) != _APPROVED_R2_LOW_LEVEL_HELPERS
        or any(value is None for value in helpers.values())
        or set(helpers) & _PROHIBITED_R2_EXPERIMENT_SURFACES
    ):
        raise V2IntegrityStop("approved low-level helper surface differs")
    return helpers


def _call_r2_low_level(helper: object, *args: object, **kwargs: object) -> object:
    if not callable(helper):
        raise TypeError("approved low-level helper is not callable")
    try:
        return helper(*args, **kwargs)
    except (V2InvariantError, V2IntegrityStop):
        raise
    except BaseException as error:
        raise V2IntegrityStop("approved low-level integrity helper stopped") from error


def neutral_feedback_source_ref(index: int) -> str:
    index = _integer(index, "neutral fixture index", maximum=11)
    return "sha256:" + hashlib.sha256(
        NEUTRAL_FIXTURE_FEEDBACK_DOMAIN + f"{index:02d}".encode("ascii")
    ).hexdigest()


def neutral_presentation(index: int) -> str:
    index = _integer(index, "neutral presentation index", maximum=11)
    sentinel = f"NEUTRAL_CONTROL_SENTINEL_{index:02d}"
    return "\n".join(
        (
            "Neutral control presentation",
            "Disposition: NOT_APPLICABLE",
            "Selected trace:",
            sentinel,
            "Executor status: NOT_APPLICABLE",
            "Objective outcome: NOT_APPLICABLE",
            "Objective feedback:",
            sentinel,
            "Child competence update: NOT_APPLICABLE",
        )
    )


def build_neutral_fixture_chain(
    *,
    bootstrap_episode_ref: str,
    competence_state_digest: str,
    model_ref: str,
    encoder_ref: str,
) -> tuple[object, ...]:
    """Construct the exact twelve canonical neutral CognitiveEpisode values."""

    from angler.cognition.contracts import CognitiveEpisode, ProspectiveCommitment

    parent_ref = _ref(bootstrap_episode_ref, "bootstrap episode reference")
    state_ref = _ref(competence_state_digest, "competence state digest")
    model_ref = _ref(model_ref, "model reference")
    encoder_ref = _ref(encoder_ref, "encoder reference")
    episodes: list[object] = []
    for index in range(12):
        prefix = f"V2_NEUTRAL_CONTROL_FIXTURE_{index:02d}"
        proposals = (
            f"{prefix}_PROPOSAL_A",
            f"{prefix}_PROPOSAL_B",
        )
        selected = index % 2
        episode = CognitiveEpisode(
            task_id=prefix,
            request=f"{prefix}_REQUEST",
            recalled_refs=(),
            proposals=proposals,
            selected_index=selected,
            commitment=ProspectiveCommitment(
                parent_event_ref=parent_ref,
                task_id=prefix,
                candidate_index=selected,
                candidate_trace=proposals[selected],
                predicted_score=0.0,
                uncertainty=1.0,
                horizon=1,
                competence_state_digest=state_ref,
            ),
            response=f"{prefix}_RESPONSE",
            observations=(f"{prefix}_OBSERVATION",),
            outcome="success" if index % 2 == 0 else "failure",
            feedback_text=f"{prefix}_FEEDBACK",
            feedback_source_ref=neutral_feedback_source_ref(index),
            parent_state_digest=state_ref,
            child_state_digest=state_ref,
            model_ref=model_ref,
            encoder_ref=encoder_ref,
            supporting_evidence_refs=(),
        )
        encoded = episode.canonical_bytes()
        restored = CognitiveEpisode.from_json(encoded)
        if restored != episode or restored.episode_ref != episode.episode_ref:
            raise V2InvariantError("neutral fixture failed canonical round trip")
        episodes.append(episode)
        parent_ref = episode.episode_ref
    validate_neutral_fixture_chain(
        episodes,
        bootstrap_episode_ref=bootstrap_episode_ref,
        competence_state_digest=competence_state_digest,
        model_ref=model_ref,
        encoder_ref=encoder_ref,
    )
    return tuple(episodes)


def validate_neutral_fixture_chain(
    episodes: Sequence[object],
    *,
    bootstrap_episode_ref: str,
    competence_state_digest: str,
    model_ref: str,
    encoder_ref: str,
) -> dict[str, object]:
    from angler.cognition.contracts import CognitiveEpisode

    values = tuple(episodes)
    if len(values) != 12 or any(type(item) is not CognitiveEpisode for item in values):
        raise V2InvariantError("neutral chain must contain twelve exact episodes")
    parent = _ref(bootstrap_episode_ref, "bootstrap episode reference")
    state_ref = _ref(competence_state_digest, "competence state digest")
    model_ref = _ref(model_ref, "model reference")
    encoder_ref = _ref(encoder_ref, "encoder reference")
    refs: list[str] = []
    byte_hashes: list[str] = []
    for index, episode in enumerate(values):
        prefix = f"V2_NEUTRAL_CONTROL_FIXTURE_{index:02d}"
        proposals = (f"{prefix}_PROPOSAL_A", f"{prefix}_PROPOSAL_B")
        selected = index % 2
        expected = {
            "task_id": prefix,
            "request": f"{prefix}_REQUEST",
            "recalled_refs": (),
            "proposals": proposals,
            "selected_index": selected,
            "response": f"{prefix}_RESPONSE",
            "observations": (f"{prefix}_OBSERVATION",),
            "outcome": "success" if index % 2 == 0 else "failure",
            "feedback_text": f"{prefix}_FEEDBACK",
            "feedback_source_ref": neutral_feedback_source_ref(index),
            "parent_state_digest": state_ref,
            "child_state_digest": state_ref,
            "model_ref": model_ref,
            "encoder_ref": encoder_ref,
            "supporting_evidence_refs": (),
            "visibility": "LEARNER_VISIBLE",
        }
        for name, expected_value in expected.items():
            if getattr(episode, name, None) != expected_value:
                raise V2InvariantError(f"neutral fixture {index:02d} {name} differs")
        commitment = episode.commitment
        if (
            commitment.parent_event_ref != parent
            or commitment.task_id != prefix
            or commitment.candidate_index != selected
            or commitment.candidate_trace != proposals[selected]
            or commitment.predicted_score != 0.0
            or commitment.uncertainty != 1.0
            or commitment.horizon != 1
            or commitment.competence_state_digest != state_ref
        ):
            raise V2InvariantError("neutral fixture commitment differs")
        raw = episode.canonical_bytes()
        if episode.episode_ref != "sha256:" + hashlib.sha256(raw).hexdigest():
            raise V2InvariantError("neutral fixture ref does not bind canonical bytes")
        refs.append(episode.episode_ref)
        byte_hashes.append(hashlib.sha256(raw).hexdigest())
        parent = episode.episode_ref
    if len(set(refs)) != 12:
        raise V2InvariantError("neutral fixture references are not unique")
    payload = {
        "bootstrap_episode_ref": bootstrap_episode_ref,
        "episode_byte_sha256": byte_hashes,
        "episode_refs": refs,
        "presentation_sha256": [
            hashlib.sha256(neutral_presentation(i).encode("utf-8")).hexdigest()
            for i in range(12)
        ],
        "schema": NEUTRAL_FIXTURE_CHAIN_SCHEMA,
    }
    return {**payload, "chain_ref": canonical_ref("neutral-fixture-chain", payload)}


@dataclass(frozen=True, slots=True)
class AdaptationDonorBinding:
    """Public provenance joining one IO resolution to one admitted task."""

    task_id: str
    public_task_ref: str
    attempt_receipt_ref: str
    stage_ref: str
    attempt_final_ref: str
    replicate_commitment: str
    family: Family
    source_adaptation_ordinal: int
    resolution_ref: str
    proposal_admitted: bool = True
    arm: Arm = "IO_FULL_ORDINARY_12"
    phase: Phase = "adaptation"

    def __post_init__(self) -> None:
        _ref(self.task_id, "donor task id")
        _ref(self.public_task_ref, "donor public task ref")
        _ref(self.attempt_receipt_ref, "donor attempt receipt ref")
        _ref(self.stage_ref, "donor stage ref")
        _ref(self.attempt_final_ref, "donor final ref")
        _ref(self.replicate_commitment, "donor replicate commitment")
        validate_family(self.family)
        _integer(
            self.source_adaptation_ordinal,
            "source adaptation ordinal",
            maximum=14,
        )
        _ref(self.resolution_ref, "donor resolution ref")
        if type(self.proposal_admitted) is not bool:
            raise TypeError("donor proposal admission must be bool")
        if (
            not self.proposal_admitted
            or self.arm != "IO_FULL_ORDINARY_12"
            or self.phase != "adaptation"
        ):
            raise ValueError("donor binding must be one admitted IO adaptation")

    @classmethod
    def from_attempt(cls, attempt: "AttemptFinal") -> "AdaptationDonorBinding":
        if type(attempt) is not AttemptFinal:
            raise TypeError("donor provenance must be an exact finalized attempt")
        stage = attempt.stage
        observation = attempt.observation
        if (
            stage.phase != "adaptation"
            or stage.arm != "IO_FULL_ORDINARY_12"
            or not observation.proposal_admitted
            or observation.resolution_ref is None
        ):
            raise V2InvariantError("donor attempt is not an admitted IO adaptation")
        return cls(
            task_id=stage.task_id,
            public_task_ref=stage.public_task_ref,
            attempt_receipt_ref=attempt.attempt_receipt_ref,
            stage_ref=stage.stage_ref,
            attempt_final_ref=attempt.final_ref,
            replicate_commitment=stage.replicate_commitment,
            family=stage.family,
            source_adaptation_ordinal=stage.task_ordinal,
            resolution_ref=observation.resolution_ref,
        )

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "attempt_final_ref": self.attempt_final_ref,
            "attempt_receipt_ref": self.attempt_receipt_ref,
            "family": self.family,
            "phase": self.phase,
            "proposal_admitted": self.proposal_admitted,
            "public_task_ref": self.public_task_ref,
            "replicate_commitment": self.replicate_commitment,
            "resolution_ref": self.resolution_ref,
            "source_adaptation_ordinal": self.source_adaptation_ordinal,
            "stage_ref": self.stage_ref,
            "task_id": self.task_id,
        }


@dataclass(frozen=True, slots=True)
class DonorCatalogEntry:
    record_ref: str
    acquisition_ref: str
    source_contract: str
    source_ref: str
    replicate_commitment: str
    family: Family
    source_adaptation_ordinal: int
    acquired_ordinal: int
    attempt_receipt_ref: str
    public_task_ref: str
    record_bytes_sha256: str
    public_record_text: str

    def __post_init__(self) -> None:
        for label, value in (
            ("record_ref", self.record_ref),
            ("acquisition_ref", self.acquisition_ref),
            ("source_ref", self.source_ref),
            ("replicate_commitment", self.replicate_commitment),
            ("attempt_receipt_ref", self.attempt_receipt_ref),
            ("public_task_ref", self.public_task_ref),
        ):
            _ref(value, label)
        if self.source_contract != "ANG-CTR-PROSPECTIVE-RESOLUTION-001@0.1.0":
            raise ValueError("donor source contract is not an observed resolution")
        validate_family(self.family)
        _integer(
            self.source_adaptation_ordinal,
            "source adaptation ordinal",
            maximum=14,
        )
        _integer(self.acquired_ordinal, "acquired ordinal")
        _raw_digest(self.record_bytes_sha256, "record bytes sha256")
        _text(self.public_record_text, "public donor record text", 16_384)

    def to_canonical(self) -> dict[str, object]:
        return {
            "acquired_ordinal": self.acquired_ordinal,
            "acquisition_ref": self.acquisition_ref,
            "attempt_receipt_ref": self.attempt_receipt_ref,
            "family": self.family,
            "public_record_text_sha256": hashlib.sha256(
                self.public_record_text.encode("utf-8")
            ).hexdigest(),
            "public_task_ref": self.public_task_ref,
            "record_bytes_sha256": self.record_bytes_sha256,
            "record_ref": self.record_ref,
            "replicate_commitment": self.replicate_commitment,
            "source_adaptation_ordinal": self.source_adaptation_ordinal,
            "source_contract": self.source_contract,
            "source_ref": self.source_ref,
        }


@dataclass(frozen=True, slots=True)
class DonorCatalog:
    replicate_commitment: str
    entries: tuple[DonorCatalogEntry, ...]
    excluded_counts: tuple[tuple[str, int], ...]

    def __post_init__(self) -> None:
        _ref(self.replicate_commitment, "catalog replicate commitment")
        if type(self.entries) is not tuple or any(
            type(item) is not DonorCatalogEntry for item in self.entries
        ):
            raise TypeError("catalog entries must be exact immutable values")
        expected = tuple(
            sorted(
                self.entries,
                key=lambda item: (item.acquired_ordinal, item.record_ref),
            )
        )
        if expected != self.entries:
            raise V2InvariantError("catalog entries are not canonically ordered")
        if any(
            item.replicate_commitment != self.replicate_commitment
            for item in self.entries
        ):
            raise V2InvariantError("catalog contains another replicate")
        if len({item.record_ref for item in self.entries}) != len(self.entries):
            raise V2InvariantError("catalog contains duplicate record refs")
        if len({item.acquisition_ref for item in self.entries}) != len(self.entries):
            raise V2InvariantError("catalog contains duplicate acquisition refs")
        if (
            type(self.excluded_counts) is not tuple
            or tuple(sorted(self.excluded_counts)) != self.excluded_counts
            or any(
                type(name) is not str
                or type(count) is not int
                or count < 0
                for name, count in self.excluded_counts
            )
        ):
            raise ValueError("catalog exclusion accounting is not canonical")
        for family in FAMILIES:
            pool = self.family_pool(family)
            if len(pool) < 12:
                raise V2InvariantError(
                    f"donor catalog has fewer than 12 eligible {family} records"
                )
            early, late = temporal_strata(pool)
            if len(early) < 6 or len(late) < 6:
                raise V2InvariantError("donor temporal stratum has fewer than six records")

    def family_pool(self, family: Family) -> tuple[DonorCatalogEntry, ...]:
        family = validate_family(family)
        return tuple(item for item in self.entries if item.family == family)

    @property
    def catalog_ref(self) -> str:
        return canonical_ref("donor-catalog", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "entries": [item.to_canonical() for item in self.entries],
            "excluded_counts": dict(self.excluded_counts),
            "replicate_commitment": self.replicate_commitment,
            "schema": DONOR_CATALOG_SCHEMA,
        }


def build_donor_catalog(
    acquisition_items: Sequence[object],
    admitted_io_adaptation: Sequence["AttemptFinal"],
    *,
    replicate_commitment: str,
    expected_next_ordinal: int,
) -> DonorCatalog:
    """Join the complete canonical acquisition head to admitted IO receipts."""

    from angler.cognition.contracts import (
        CognitiveMemoryKind,
        EpistemicStatus,
    )
    from angler.memory.cognitive_acquisition import CognitiveAcquisition

    replicate_commitment = _ref(
        replicate_commitment, "catalog replicate commitment"
    )
    expected_next_ordinal = _integer(
        expected_next_ordinal, "catalog acquisition head next ordinal", minimum=1
    )
    attempts = tuple(admitted_io_adaptation)
    if any(type(item) is not AttemptFinal for item in attempts):
        raise TypeError("donor inputs must be exact finalized attempts")
    bindings = tuple(AdaptationDonorBinding.from_attempt(item) for item in attempts)
    by_source: dict[str, AdaptationDonorBinding] = {}
    binding_task_ids: set[str] = set()
    binding_public_refs: set[str] = set()
    binding_receipt_refs: set[str] = set()
    binding_family_ordinals: set[tuple[Family, int]] = set()
    for binding in bindings:
        if binding.replicate_commitment != replicate_commitment:
            raise V2InvariantError("donor binding belongs to another replicate")
        if binding.resolution_ref in by_source:
            raise V2InvariantError("resolution ref joins multiple adaptation attempts")
        if (
            binding.task_id in binding_task_ids
            or binding.public_task_ref in binding_public_refs
            or binding.attempt_receipt_ref in binding_receipt_refs
            or (binding.family, binding.source_adaptation_ordinal)
            in binding_family_ordinals
        ):
            raise V2InvariantError("admitted IO donor provenance is not one-to-one")
        by_source[binding.resolution_ref] = binding
        binding_task_ids.add(binding.task_id)
        binding_public_refs.add(binding.public_task_ref)
        binding_receipt_refs.add(binding.attempt_receipt_ref)
        binding_family_ordinals.add(
            (binding.family, binding.source_adaptation_ordinal)
        )

    entries: list[DonorCatalogEntry] = []
    excluded: Counter[str] = Counter()
    seen_ordinals: set[int] = set()
    seen_acquisition_refs: set[str] = set()
    seen_record_refs: set[str] = set()
    for item in acquisition_items:
        ordinal = getattr(item, "ordinal", None)
        acquisition_ref = getattr(item, "acquisition_ref", None)
        record_ref = getattr(item, "record_ref", None)
        acquisition = getattr(item, "acquisition", None)
        if (
            type(ordinal) is not int
            or ordinal < 0
            or type(acquisition) is not CognitiveAcquisition
        ):
            raise TypeError("catalog input is not a canonical acquisition item")
        _ref(acquisition_ref, "catalog acquisition ref")
        _ref(record_ref, "catalog record ref")
        if ordinal in seen_ordinals:
            raise V2InvariantError("catalog input repeats an acquisition ordinal")
        if acquisition_ref in seen_acquisition_refs or record_ref in seen_record_refs:
            raise V2InvariantError("catalog input repeats an acquisition or record ref")
        seen_ordinals.add(ordinal)
        seen_acquisition_refs.add(acquisition_ref)
        seen_record_refs.add(record_ref)
        raw_acquisition = acquisition.canonical_bytes()
        restored = CognitiveAcquisition.from_json(raw_acquisition)
        if (
            restored != acquisition
            or acquisition.ordinal != ordinal
            or acquisition.acquisition_ref != acquisition_ref
            or acquisition.record.record_ref != record_ref
            or acquisition_ref
            != "sha256:" + hashlib.sha256(raw_acquisition).hexdigest()
        ):
            raise V2InvariantError("catalog acquisition binding differs")
        if acquisition.source_contract != (
            "ANG-CTR-PROSPECTIVE-RESOLUTION-001@0.1.0"
        ):
            excluded["SOURCE_CONTRACT"] += 1
            continue
        binding = by_source.get(acquisition.source_ref)
        if binding is None:
            excluded["NOT_ADMITTED_IO_ADAPTATION"] += 1
            continue
        record = acquisition.record
        if record.kind is not CognitiveMemoryKind.EPISODIC:
            excluded["KIND"] += 1
            continue
        if record.epistemic_status is not EpistemicStatus.OBSERVED:
            excluded["EPISTEMIC_STATUS"] += 1
            continue
        if record.visibility != "LEARNER_VISIBLE":
            excluded["VISIBILITY"] += 1
            continue
        if record.confidence_ppm is not None:
            excluded["CONFIDENCE_PRESENT"] += 1
            continue
        if acquisition.source_ref not in record.provenance_refs:
            raise V2InvariantError("donor record omits its canonical source ref")
        raw_record = record.canonical_bytes()
        if record.record_ref != "sha256:" + hashlib.sha256(raw_record).hexdigest():
            raise V2InvariantError("donor record ref does not bind canonical bytes")
        entries.append(
            DonorCatalogEntry(
                record_ref=record.record_ref,
                acquisition_ref=acquisition.acquisition_ref,
                source_contract=acquisition.source_contract,
                source_ref=acquisition.source_ref,
                replicate_commitment=replicate_commitment,
                family=binding.family,
                source_adaptation_ordinal=binding.source_adaptation_ordinal,
                acquired_ordinal=record.acquired_ordinal,
                attempt_receipt_ref=binding.attempt_receipt_ref,
                public_task_ref=binding.public_task_ref,
                record_bytes_sha256=hashlib.sha256(raw_record).hexdigest(),
                public_record_text=record.content,
            )
        )
    if seen_ordinals != set(range(expected_next_ordinal)):
        raise V2InvariantError("catalog input does not cover the complete acquisition head")
    used_sources = [item.source_ref for item in entries]
    if Counter(used_sources) != Counter({value: 1 for value in by_source}):
        raise V2InvariantError(
            "eligible donor pool does not exactly cover admitted IO resolutions"
        )
    if len(entries) + sum(excluded.values()) != expected_next_ordinal:
        raise V2InvariantError("catalog inclusion/exclusion accounting does not close")
    return DonorCatalog(
        replicate_commitment=replicate_commitment,
        entries=tuple(
            sorted(entries, key=lambda item: (item.acquired_ordinal, item.record_ref))
        ),
        excluded_counts=tuple(sorted(excluded.items())),
    )


def temporal_strata(
    pool: Sequence[DonorCatalogEntry],
) -> tuple[tuple[DonorCatalogEntry, ...], tuple[DonorCatalogEntry, ...]]:
    values = tuple(
        sorted(pool, key=lambda item: (item.acquired_ordinal, item.record_ref))
    )
    if len(values) < 12 or len({item.record_ref for item in values}) != len(values):
        raise V2InvariantError("temporal pool is insufficient or non-unique")
    split = len(values) // 2
    early, late = values[:split], values[split:]
    if len(early) < 6 or len(late) < 6:
        raise V2InvariantError("temporal strata require at least six records each")
    return early, late


def _vector(value: object, label: str) -> tuple[float, ...]:
    if type(value) not in (tuple, list):
        raise TypeError(f"{label} must be a finite numeric vector")
    row = tuple(_finite(item, label) for item in value)
    if not row or math.sqrt(sum(item * item for item in row)) == 0.0:
        raise ValueError(f"{label} must be nonzero")
    return row


def cosine_similarity(left: Sequence[float], right: Sequence[float]) -> float:
    a = _vector(left, "left embedding")
    b = _vector(right, "right embedding")
    if len(a) != len(b):
        raise ValueError("embedding dimensions differ")
    denominator = math.sqrt(sum(x * x for x in a)) * math.sqrt(
        sum(y * y for y in b)
    )
    result = sum(x * y for x, y in zip(a, b, strict=True)) / denominator
    if not math.isfinite(result) or not -1.0000001 <= result <= 1.0000001:
        raise V2InvariantError("cosine similarity is not finite and bounded")
    return max(-1.0, min(1.0, result))


@dataclass(frozen=True, slots=True)
class RankedDonor:
    entry: DonorCatalogEntry
    score_hex: str
    stratum: Literal["early", "late"]

    def __post_init__(self) -> None:
        if type(self.entry) is not DonorCatalogEntry:
            raise TypeError("ranked donor entry differs")
        try:
            score = float.fromhex(self.score_hex)
        except (TypeError, ValueError) as error:
            raise ValueError("ranked donor score is not canonical hex") from error
        if not math.isfinite(score):
            raise ValueError("ranked donor score is not finite")
        if self.stratum not in ("early", "late"):
            raise ValueError("ranked donor temporal stratum differs")

    def to_canonical(self) -> dict[str, object]:
        return {
            "record_ref": self.entry.record_ref,
            "score_hex": self.score_hex,
            "stratum": self.stratum,
        }


@dataclass(frozen=True, slots=True)
class RankedSelectionPlan:
    task_id: str
    public_task_ref: str
    target_family: Family
    mode: Literal["cross-low", "same-low", "same-high"]
    catalog_ref: str
    task_embedding_sha256: str
    record_embeddings_sha256: str
    population: tuple[RankedDonor, ...]
    selected: tuple[RankedDonor, ...]

    def __post_init__(self) -> None:
        _ref(self.task_id, "selection-plan task id")
        _ref(self.public_task_ref, "selection-plan public task ref")
        target = validate_family(self.target_family)
        if self.mode not in ("cross-low", "same-low", "same-high"):
            raise ValueError("selection-plan mode differs")
        _ref(self.catalog_ref, "selection-plan catalog ref")
        _raw_digest(self.task_embedding_sha256, "selection-plan task embedding")
        _raw_digest(
            self.record_embeddings_sha256, "selection-plan record embeddings"
        )
        source_family = CROSS_FAMILY[target] if self.mode == "cross-low" else target
        if (
            type(self.population) is not tuple
            or len(self.population) < 12
            or any(
                type(item) is not RankedDonor
                or item.entry.family != source_family
                for item in self.population
            )
            or len({item.entry.record_ref for item in self.population})
            != len(self.population)
        ):
            raise V2InvariantError("selection-plan population differs")
        expected: list[RankedDonor] = []
        for stratum in ("early", "late"):
            rows = sorted(
                (item for item in self.population if item.stratum == stratum),
                key=lambda item: (float.fromhex(item.score_hex), item.entry.record_ref),
            )
            if len(rows) < 6:
                raise V2InvariantError("selection-plan stratum has fewer than six")
            expected.extend(rows[-3:] if self.mode == "same-high" else rows[:3])
        expected.sort(
            key=lambda item: (
                item.entry.source_adaptation_ordinal,
                item.entry.acquired_ordinal,
                item.entry.record_ref,
            )
        )
        if self.selected != tuple(expected):
            raise V2InvariantError("selection-plan chosen donors differ from frozen policy")

    @property
    def selection_ref(self) -> str:
        return canonical_ref("ranked-selection-plan", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "catalog_ref": self.catalog_ref,
            "mode": self.mode,
            "population": [item.to_canonical() for item in self.population],
            "public_task_ref": self.public_task_ref,
            "record_embeddings_sha256": self.record_embeddings_sha256,
            "selected": [item.to_canonical() for item in self.selected],
            "target_family": self.target_family,
            "task_embedding_sha256": self.task_embedding_sha256,
            "task_id": self.task_id,
        }


def build_ranked_selection_plan(
    *,
    task: object,
    catalog: DonorCatalog,
    mode: Literal["cross-low", "same-low", "same-high"],
    task_embedding: Sequence[float],
    record_embeddings: Mapping[str, Sequence[float]],
) -> RankedSelectionPlan:
    canonical = _task_canonical(task)
    if type(catalog) is not DonorCatalog:
        raise TypeError("selection catalog differs")
    target_family = validate_family(canonical["family"])
    source_family: Family = (
        CROSS_FAMILY[target_family] if mode == "cross-low" else target_family
    )  # type: ignore[assignment]
    early, late = temporal_strata(catalog.family_pool(source_family))
    task_row = _vector(task_embedding, "selection task embedding")
    population: list[RankedDonor] = []
    embedding_payload: list[dict[str, object]] = []
    for name, entries in (("early", early), ("late", late)):
        for entry in entries:
            try:
                row = _vector(
                    record_embeddings[entry.record_ref], "selection record embedding"
                )
            except KeyError as error:
                raise V2InvariantError("selection record embedding is absent") from error
            score = cosine_similarity(task_row, row)
            population.append(RankedDonor(entry, score.hex(), name))  # type: ignore[arg-type]
            embedding_payload.append(
                {"record_ref": entry.record_ref, "vector": [item.hex() for item in row]}
            )
    population_rows = tuple(population)
    # Construct the exact policy selection, then let the value revalidate it.
    expected: list[RankedDonor] = []
    for stratum in ("early", "late"):
        rows = sorted(
            (item for item in population_rows if item.stratum == stratum),
            key=lambda item: (float.fromhex(item.score_hex), item.entry.record_ref),
        )
        expected.extend(rows[-3:] if mode == "same-high" else rows[:3])
    expected.sort(
        key=lambda item: (
            item.entry.source_adaptation_ordinal,
            item.entry.acquired_ordinal,
            item.entry.record_ref,
        )
    )
    return RankedSelectionPlan(
        task_id=str(canonical["task_id"]),
        public_task_ref=public_task_ref(canonical),
        target_family=target_family,
        mode=mode,
        catalog_ref=catalog.catalog_ref,
        task_embedding_sha256=hashlib.sha256(
            canonical_json_bytes([item.hex() for item in task_row])
        ).hexdigest(),
        record_embeddings_sha256=hashlib.sha256(
            canonical_json_bytes(
                sorted(embedding_payload, key=lambda item: item["record_ref"])
            )
        ).hexdigest(),
        population=population_rows,
        selected=tuple(expected),
    )


def select_ranked_donors(
    catalog: DonorCatalog,
    *,
    target_family: Family,
    mode: Literal["cross-low", "same-low", "same-high"],
    task_embedding: Sequence[float],
    record_embeddings: Mapping[str, Sequence[float]],
) -> tuple[RankedDonor, ...]:
    if type(catalog) is not DonorCatalog:
        raise TypeError("catalog must be an exact DonorCatalog")
    target_family = validate_family(target_family)
    if mode not in ("cross-low", "same-low", "same-high"):
        raise ValueError("donor selection mode differs")
    source_family: Family = (
        CROSS_FAMILY[target_family]  # type: ignore[assignment]
        if mode == "cross-low"
        else target_family
    )
    pool = catalog.family_pool(source_family)
    early, late = temporal_strata(pool)
    task_row = _vector(task_embedding, "task embedding")
    selected: list[RankedDonor] = []
    for name, stratum in (("early", early), ("late", late)):
        ranked: list[tuple[float, str, DonorCatalogEntry]] = []
        for entry in stratum:
            try:
                row = record_embeddings[entry.record_ref]
            except KeyError as error:
                raise V2InvariantError("donor embedding is absent") from error
            score = cosine_similarity(task_row, row)
            ranked.append((score, entry.record_ref, entry))
        ranked.sort(key=lambda item: (item[0], item[1]))
        chosen = ranked[-3:] if mode == "same-high" else ranked[:3]
        if mode == "same-high":
            chosen.sort(key=lambda item: (item[0], item[1]))
        selected.extend(
            RankedDonor(entry, score.hex(), name)  # type: ignore[arg-type]
            for score, _, entry in chosen
        )
    if len(selected) != 6 or len({item.entry.record_ref for item in selected}) != 6:
        raise V2InvariantError("donor selector did not produce six unique records")
    selected.sort(
        key=lambda item: (
            item.entry.source_adaptation_ordinal,
            item.entry.acquired_ordinal,
            item.entry.record_ref,
        )
    )
    return tuple(selected)


def validate_disjoint_same_family_selections(
    low: Sequence[RankedDonor], high: Sequence[RankedDonor]
) -> None:
    low_refs = {item.entry.record_ref for item in low}
    high_refs = {item.entry.record_ref for item in high}
    if len(low_refs) != 6 or len(high_refs) != 6 or low_refs & high_refs:
        raise V2InvariantError("same-family high/low controls are not disjoint")


@dataclass(frozen=True, slots=True)
class HistoryPresentation:
    slot: int
    record_ref: str
    acquisition_ref: str | None
    source_ref: str
    raw_record_sha256: str
    presented_text: str
    neutral: bool
    padding_atoms: int = 0

    def __post_init__(self) -> None:
        _integer(self.slot, "history slot", maximum=11)
        _ref(self.record_ref, "history record ref")
        if self.acquisition_ref is not None:
            _ref(self.acquisition_ref, "history acquisition ref")
        _ref(self.source_ref, "history source ref")
        _raw_digest(self.raw_record_sha256, "history raw record sha256")
        _text(self.presented_text, "history presented text", 32_768)
        if type(self.neutral) is not bool:
            raise TypeError("history neutral flag must be bool")
        _integer(self.padding_atoms, "history padding atoms", maximum=512)
        if not self.neutral and self.acquisition_ref is None:
            raise V2InvariantError("real presentation lacks its acquisition binding")

    def with_padding(self, count: int) -> "HistoryPresentation":
        count = _integer(count, "history padding atoms", maximum=512)
        if self.padding_atoms != 0:
            raise V2IntegrityStop("history presentation cannot be repadded")
        return HistoryPresentation(
            slot=self.slot,
            record_ref=self.record_ref,
            acquisition_ref=self.acquisition_ref,
            source_ref=self.source_ref,
            raw_record_sha256=self.raw_record_sha256,
            presented_text=self.presented_text + PADDING_ATOM * count,
            neutral=self.neutral,
            padding_atoms=count,
        )

    def to_canonical(self) -> dict[str, object]:
        return {
            "acquisition_ref": self.acquisition_ref,
            "neutral": self.neutral,
            "padding_atoms": self.padding_atoms,
            "presented_text_sha256": hashlib.sha256(
                self.presented_text.encode("utf-8")
            ).hexdigest(),
            "raw_record_sha256": self.raw_record_sha256,
            "record_ref": self.record_ref,
            "source_ref": self.source_ref,
            "slot": self.slot,
        }


@dataclass(frozen=True, slots=True)
class HistoryPlan:
    arm: Arm
    task_id: str
    presentations: tuple[HistoryPresentation, ...]
    selection_rows: tuple[RankedDonor, ...] = ()
    selection_plan: RankedSelectionPlan | None = None

    def __post_init__(self) -> None:
        validate_arm(self.arm)
        _ref(self.task_id, "history-plan task id")
        if self.arm == "N0_NATIVE_NO_HISTORY":
            if self.presentations or self.selection_rows or self.selection_plan is not None:
                raise V2InvariantError("N0 cannot contain a persistent history plan")
            return
        if (
            type(self.presentations) is not tuple
            or len(self.presentations) != 12
            or tuple(item.slot for item in self.presentations) != tuple(range(12))
            or len({item.record_ref for item in self.presentations}) != 12
        ):
            raise V2InvariantError("history plan must contain twelve ordered unique slots")
        expected_real = {
            "F0_NEUTRAL_FORMATTED_12": 0,
            "X0_CROSS_FAMILY_LOW_6_NEUTRAL_6": 6,
            "S0_SAME_FAMILY_LOW_6_NEUTRAL_6": 6,
            "S1_SAME_FAMILY_HIGH_6_NEUTRAL_6": 6,
            "O0_ORDINARY_FROZEN_12": 12,
            "IN_FULL_NEUTRAL_12": 0,
            "IO_FULL_ORDINARY_12": 12,
        }[self.arm]
        if sum(not item.neutral for item in self.presentations) != expected_real:
            raise V2InvariantError("history plan real/neutral density differs")
        if self.arm in {
            "X0_CROSS_FAMILY_LOW_6_NEUTRAL_6",
            "S0_SAME_FAMILY_LOW_6_NEUTRAL_6",
            "S1_SAME_FAMILY_HIGH_6_NEUTRAL_6",
        }:
            if (
                type(self.selection_plan) is not RankedSelectionPlan
                or self.selection_plan.task_id != self.task_id
                or self.selection_plan.selected != self.selection_rows
                or len(self.selection_rows) != 6
                or tuple(item.record_ref for item in self.presentations[::2])
                != tuple(item.entry.record_ref for item in self.selection_rows)
                or any(not self.presentations[index].neutral for index in range(1, 12, 2))
            ):
                raise V2InvariantError("controlled six-real/six-neutral layout differs")
            expected_mode = {
                "X0_CROSS_FAMILY_LOW_6_NEUTRAL_6": "cross-low",
                "S0_SAME_FAMILY_LOW_6_NEUTRAL_6": "same-low",
                "S1_SAME_FAMILY_HIGH_6_NEUTRAL_6": "same-high",
            }[self.arm]
            if self.selection_plan.mode != expected_mode:
                raise V2InvariantError("controlled history selection mode differs")
        elif self.selection_rows or self.selection_plan is not None:
            raise V2InvariantError("selection rows belong only to ranked controls")

    @property
    def evidence_texts(self) -> tuple[str, ...]:
        return tuple(item.presented_text for item in self.presentations)

    @property
    def plan_ref(self) -> str:
        return canonical_ref("history-plan", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "presentations": [item.to_canonical() for item in self.presentations],
            "schema": HISTORY_PLAN_SCHEMA,
            "selection": [item.to_canonical() for item in self.selection_rows],
            "selection_plan": (
                None if self.selection_plan is None else self.selection_plan.to_canonical()
            ),
            "selection_plan_ref": (
                None if self.selection_plan is None else self.selection_plan.selection_ref
            ),
            "task_id": self.task_id,
        }


def _validated_neutral_chain_from_episodes(
    neutral_episodes: Sequence[object],
) -> tuple[tuple[object, ...], dict[str, object]]:
    episodes = tuple(neutral_episodes)
    if len(episodes) != 12:
        raise ValueError("neutral history requires twelve fixture episodes")
    first = episodes[0]
    commitment = getattr(first, "commitment", None)
    chain = validate_neutral_fixture_chain(
        episodes,
        bootstrap_episode_ref=getattr(commitment, "parent_event_ref", None),
        competence_state_digest=getattr(first, "parent_state_digest", None),
        model_ref=getattr(first, "model_ref", None),
        encoder_ref=getattr(first, "encoder_ref", None),
    )
    return episodes, chain


def neutral_history_plan(
    task_id: str,
    arm: Literal["F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"],
    neutral_episodes: Sequence[object],
) -> HistoryPlan:
    _ref(task_id, "neutral history task id")
    if arm not in ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"):
        raise ValueError("neutral history arm differs")
    episodes, _chain = _validated_neutral_chain_from_episodes(neutral_episodes)
    presentations: list[HistoryPresentation] = []
    for index, episode in enumerate(episodes):
        raw = _canonical_object_bytes(episode, "neutral episode")
        record_ref = getattr(episode, "episode_ref", None)
        _ref(record_ref, "neutral episode ref")
        presentations.append(
            HistoryPresentation(
                slot=index,
                record_ref=record_ref,
                acquisition_ref=None,
                source_ref=record_ref,
                raw_record_sha256=hashlib.sha256(raw).hexdigest(),
                presented_text=neutral_presentation(index),
                neutral=True,
            )
        )
    return HistoryPlan(arm=arm, task_id=task_id, presentations=tuple(presentations))


def ranked_control_history_plan(
    task_id: str,
    arm: Literal[
        "X0_CROSS_FAMILY_LOW_6_NEUTRAL_6",
        "S0_SAME_FAMILY_LOW_6_NEUTRAL_6",
        "S1_SAME_FAMILY_HIGH_6_NEUTRAL_6",
    ],
    selection_plan: RankedSelectionPlan,
    neutral_episodes: Sequence[object],
) -> HistoryPlan:
    _ref(task_id, "controlled history task id")
    if arm not in {
        "X0_CROSS_FAMILY_LOW_6_NEUTRAL_6",
        "S0_SAME_FAMILY_LOW_6_NEUTRAL_6",
        "S1_SAME_FAMILY_HIGH_6_NEUTRAL_6",
    }:
        raise ValueError("ranked history arm differs")
    if type(selection_plan) is not RankedSelectionPlan:
        raise TypeError("ranked control requires one sealed selection plan")
    rows = selection_plan.selected
    episodes, _chain = _validated_neutral_chain_from_episodes(neutral_episodes)
    if len(rows) != 6 or len(episodes) != 12:
        raise ValueError("ranked control requires six real and twelve fixture inputs")
    presentations: list[HistoryPresentation] = []
    for slot in range(12):
        if slot % 2 == 0:
            entry = rows[slot // 2].entry
            presentations.append(
                HistoryPresentation(
                    slot=slot,
                    record_ref=entry.record_ref,
                    acquisition_ref=entry.acquisition_ref,
                    source_ref=entry.source_ref,
                    raw_record_sha256=entry.record_bytes_sha256,
                    presented_text=entry.public_record_text,
                    neutral=False,
                )
            )
        else:
            episode = episodes[slot]
            raw = _canonical_object_bytes(episode, "neutral episode")
            presentations.append(
                HistoryPresentation(
                    slot=slot,
                    record_ref=getattr(episode, "episode_ref", None),
                    acquisition_ref=None,
                    source_ref=getattr(episode, "episode_ref", None),
                    raw_record_sha256=hashlib.sha256(raw).hexdigest(),
                    presented_text=neutral_presentation(slot),
                    neutral=True,
                )
            )
    return HistoryPlan(
        arm=arm,
        task_id=task_id,
        presentations=tuple(presentations),
        selection_rows=rows,
        selection_plan=selection_plan,
    )


def recall_history_plan(
    task_id: str,
    arm: Literal[
        "F0_NEUTRAL_FORMATTED_12",
        "O0_ORDINARY_FROZEN_12",
        "IN_FULL_NEUTRAL_12",
        "IO_FULL_ORDINARY_12",
    ],
    recall_capture: "FrozenRecallCapture",
    *,
    neutral: bool,
) -> HistoryPlan:
    """Bind one exact canonical recall batch to its model-facing view."""

    _ref(task_id, "recall history task id")
    if arm not in {
        "F0_NEUTRAL_FORMATTED_12",
        "O0_ORDINARY_FROZEN_12",
        "IN_FULL_NEUTRAL_12",
        "IO_FULL_ORDINARY_12",
    }:
        raise ValueError("recall history arm differs")
    if neutral != arm.startswith(("F0_", "IN_")):
        raise V2InvariantError("recall history neutral semantics differ")
    if (
        type(recall_capture) is not FrozenRecallCapture
        or recall_capture.task_id != task_id
        or recall_capture.kind != ("neutral" if neutral else "ordinary")
    ):
        raise V2InvariantError("recall capture does not bind requested history")
    plan = HistoryPlan(
        arm=arm,
        task_id=task_id,
        presentations=recall_capture.presentations,
    )
    recall_capture.validates_plan(plan)
    return plan


@dataclass(frozen=True, slots=True)
class PresentedRecallItem:
    """Field-compatible canonical recall item with only ``text`` replaced."""

    canonical_item: object = field(repr=False, compare=False)
    presented_text: str
    raw_record_sha256: str
    padding_atoms: int = 0

    def __post_init__(self) -> None:
        _text(self.presented_text, "presented recall text", 32_768)
        _raw_digest(self.raw_record_sha256, "presented raw record sha256")
        _integer(self.padding_atoms, "presented padding atoms", maximum=512)
        record = getattr(self.canonical_item, "record", None)
        raw = _canonical_object_bytes(record, "presented canonical record")
        if hashlib.sha256(raw).hexdigest() != self.raw_record_sha256:
            raise V2InvariantError("presented item raw record digest differs")
        _ref(getattr(self.canonical_item, "record_ref", None), "presented record ref")
        _ref(
            getattr(self.canonical_item, "acquisition_ref", None),
            "presented acquisition ref",
        )
        _ref(
            getattr(self.canonical_item, "source_ref", None),
            "presented source ref",
        )

    @property
    def text(self) -> str:
        return self.presented_text

    def __getattr__(self, name: str) -> object:
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self.canonical_item, name)


@dataclass(frozen=True, slots=True)
class PresentedRecallBatch:
    items: tuple[PresentedRecallItem, ...]
    rejected: tuple[str, ...]

    def __post_init__(self) -> None:
        if type(self.items) is not tuple or len(self.items) != 12 or any(
            type(item) is not PresentedRecallItem for item in self.items
        ):
            raise V2InvariantError("presented recall batch requires twelve exact items")
        refs = tuple(getattr(item, "record_ref", None) for item in self.items)
        if len(set(refs)) != 12:
            raise V2InvariantError("presented recall refs are not unique")
        if type(self.rejected) is not tuple or any(
            type(value) is not str for value in self.rejected
        ):
            raise TypeError("presented rejected refs must be immutable text")


class AcquisitionMemoryPresentationProxy:
    """Delegate acquisition memory behavior while replacing recall item text.

    This proxy does not alter canonical records, refs, acquisition provenance,
    temporal state, adjacency, projection, or backend behavior.
    """

    def __init__(
        self,
        source: object,
        plan: HistoryPlan,
        *,
        expected_record_refs: Sequence[str] | None = None,
    ) -> None:
        if plan.arm not in TWELVE_SLOT_ARMS:
            raise ValueError("presentation proxy requires a twelve-slot plan")
        if not callable(getattr(source, "recall", None)):
            raise TypeError("presentation source lacks recall")
        self._source = source
        self._plan = plan
        self._presentations = {
            item.record_ref: item for item in plan.presentations
        }
        refs = (
            tuple(item.record_ref for item in plan.presentations)
            if expected_record_refs is None
            else tuple(expected_record_refs)
        )
        for value in refs:
            _ref(value, "expected presentation record ref")
        if len(refs) != 12 or len(set(refs)) != 12:
            raise V2InvariantError("presentation proxy expected refs differ")
        self._expected_record_refs = refs
        self._calls = 0

    @property
    def source(self) -> object:
        """Preserve the wrapped acquisition service's canonical store identity."""

        return getattr(self._source, "source")

    @property
    def wrapped_memory(self) -> object:
        return self._source

    @property
    def plan(self) -> HistoryPlan:
        return self._plan

    @property
    def presentation_calls(self) -> int:
        return self._calls

    @property
    def backend(self) -> object:
        return getattr(self._source, "backend")

    def _present(self, batch: object) -> PresentedRecallBatch:
        items = getattr(batch, "items", None)
        rejected = getattr(batch, "rejected", ())
        if type(items) is not tuple or type(rejected) is not tuple:
            raise V2InvariantError("canonical recall batch shape differs")
        refs = tuple(getattr(item, "record_ref", None) for item in items)
        if refs != self._expected_record_refs:
            raise V2InvariantError("live recall differs from frozen presentation order")
        output: list[PresentedRecallItem] = []
        for item, expected in zip(items, self._plan.presentations, strict=True):
            if (
                getattr(item, "record_ref", None) != expected.record_ref
                or getattr(item, "acquisition_ref", None)
                != expected.acquisition_ref
                or getattr(item, "source_ref", None) != expected.source_ref
            ):
                raise V2InvariantError("presented recall provenance differs")
            raw = _canonical_object_bytes(
                getattr(item, "record", None), "presented canonical record"
            )
            if hashlib.sha256(raw).hexdigest() != expected.raw_record_sha256:
                raise V2InvariantError("presented raw record changed")
            output.append(
                PresentedRecallItem(
                    canonical_item=item,
                    presented_text=expected.presented_text,
                    raw_record_sha256=expected.raw_record_sha256,
                    padding_atoms=expected.padding_atoms,
                )
            )
        self._calls += 1
        return PresentedRecallBatch(tuple(output), rejected)

    async def recall(self, *args: object, **kwargs: object) -> PresentedRecallBatch:
        result = self._source.recall(*args, **kwargs)
        if inspect.isawaitable(result):
            result = await result
        return self._present(result)

    def recall_from_hits(
        self, *args: object, **kwargs: object
    ) -> PresentedRecallBatch:
        method = getattr(self._source, "recall_from_hits", None)
        if not callable(method):
            raise TypeError("presentation source lacks recall_from_hits")
        result = method(*args, **kwargs)
        if inspect.isawaitable(result):
            raise TypeError("recall_from_hits must remain synchronous")
        return self._present(result)

    def __getattr__(self, name: str) -> object:
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self._source, name)


class _FrozenHitAcquisitionMemory:
    """Force one precommitted canonical hit order without changing projections."""

    def __init__(
        self,
        memory: object,
        *,
        expected_query: str,
        hits: Sequence[object],
        expected_record_refs: Sequence[str],
        expected_presentations: Sequence[HistoryPresentation],
        replay_frozen_origin: bool = False,
    ) -> None:
        from angler.memory.cognitive_acquisition_graph import AcquisitionReferenceHit

        if not all(
            callable(getattr(memory, name, None))
            for name in (
                "recall_from_hits",
                "retry_pending_projections",
                "assert_synchronized",
            )
        ):
            raise TypeError("frozen-hit memory lacks acquisition behavior")
        expected_query = _text(expected_query, "frozen-hit query", 16_384)
        frozen_hits = tuple(hits)
        refs = tuple(expected_record_refs)
        presentations = tuple(expected_presentations)
        if (
            len(frozen_hits) != RECALL_SLOTS
            or any(type(item) is not AcquisitionReferenceHit for item in frozen_hits)
            or tuple(item.record_ref for item in frozen_hits) != refs
            or len(refs) != RECALL_SLOTS
            or len(set(refs)) != RECALL_SLOTS
            or len(presentations) != RECALL_SLOTS
            or any(type(item) is not HistoryPresentation for item in presentations)
            or tuple(item.record_ref for item in presentations) != refs
        ):
            raise V2IntegrityStop("frozen-hit memory population differs")
        for value in refs:
            _ref(value, "frozen-hit record ref")
        if type(replay_frozen_origin) is not bool:
            raise TypeError("frozen-hit origin mode differs")
        self._memory = memory
        self._expected_query = expected_query
        self._hits = frozen_hits
        self._expected_record_refs = refs
        self._expected_bindings = tuple(
            (item.record_ref, item.acquisition_ref, item.source_ref)
            for item in presentations
        )
        self._replay_frozen_origin = replay_frozen_origin
        self._calls = 0

    @property
    def source(self) -> object:
        return getattr(self._memory, "source")

    @property
    def backend(self) -> object:
        return getattr(self._memory, "backend")

    @property
    def calls(self) -> int:
        return self._calls

    def _resolve(
        self,
        *,
        limit: int,
        world_time: int | None,
        frozen_origin: bool,
    ) -> object:
        if limit != RECALL_SLOTS or frozen_origin is not False:
            raise V2IntegrityStop("frozen-hit recall coordinates differ")
        batch = self._memory.recall_from_hits(
            self._hits,
            limit=RECALL_SLOTS,
            world_time=world_time,
            frozen_origin=self._replay_frozen_origin,
        )
        items = getattr(batch, "items", None)
        rejected = getattr(batch, "rejected", None)
        if (
            type(items) is not tuple
            or tuple(getattr(item, "record_ref", None) for item in items)
            != self._expected_record_refs
            or tuple(
                (
                    getattr(item, "record_ref", None),
                    getattr(item, "acquisition_ref", None),
                    getattr(item, "source_ref", None),
                )
                for item in items
            )
            != self._expected_bindings
            or rejected != ()
        ):
            raise V2IntegrityStop("frozen-hit canonical replay differs")
        self._calls += 1
        return batch

    async def recall(
        self,
        query: str,
        *,
        limit: int = RECALL_SLOTS,
        allowed_visibility: Sequence[str] = ("LEARNER_VISIBLE",),
        world_time: int | None = None,
        frozen_origin: bool = False,
    ) -> object:
        if (
            query != self._expected_query
            or tuple(allowed_visibility) != ("LEARNER_VISIBLE",)
        ):
            raise V2IntegrityStop("frozen-hit recall query/visibility differs")
        return self._resolve(
            limit=limit,
            world_time=world_time,
            frozen_origin=frozen_origin,
        )

    def recall_from_hits(
        self,
        hits: Sequence[object],
        *,
        limit: int = RECALL_SLOTS,
        allowed_visibility: Sequence[str] = ("LEARNER_VISIBLE",),
        world_time: int | None = None,
        frozen_origin: bool = False,
    ) -> object:
        if tuple(hits) != self._hits or tuple(allowed_visibility) != (
            "LEARNER_VISIBLE",
        ):
            raise V2IntegrityStop("frozen-hit replay input differs")
        return self._resolve(
            limit=limit,
            world_time=world_time,
            frozen_origin=frozen_origin,
        )

    def __getattr__(self, name: str) -> object:
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self._memory, name)


def _history_plan_from_recall_batch(
    *,
    task_id: str,
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
    batch: object,
) -> HistoryPlan:
    task_id = _ref(task_id, "stateful history task id")
    items = getattr(batch, "items", None)
    rejected = getattr(batch, "rejected", None)
    neutral = arm == "IN_FULL_NEUTRAL_12"
    if type(items) is not tuple or len(items) != RECALL_SLOTS or rejected != ():
        raise V2IntegrityStop("stateful history batch differs")
    presentations: list[HistoryPresentation] = []
    for index, item in enumerate(items):
        raw = _canonical_object_bytes(
            getattr(item, "record", None), "stateful history record"
        )
        presentations.append(
            HistoryPresentation(
                slot=index,
                record_ref=_ref(
                    getattr(item, "record_ref", None),
                    "stateful history record ref",
                ),
                acquisition_ref=_ref(
                    getattr(item, "acquisition_ref", None),
                    "stateful history acquisition ref",
                ),
                source_ref=_ref(
                    getattr(item, "source_ref", None),
                    "stateful history source ref",
                ),
                raw_record_sha256=hashlib.sha256(raw).hexdigest(),
                presented_text=(
                    neutral_presentation(index)
                    if neutral
                    else _text(
                        getattr(item, "text", None),
                        "stateful ordinary history text",
                        32_768,
                    )
                ),
                neutral=neutral,
            )
        )
    return HistoryPlan(
        arm=arm,
        task_id=task_id,
        presentations=tuple(presentations),
    )


def _unpadded_prompt_plan(
    *,
    task_text: str,
    history_plan: HistoryPlan,
    tokenize_chat_prompt: Callable[[str], Sequence[int]],
) -> PromptPlan:
    if history_plan.arm not in STATEFUL_ARMS or not callable(tokenize_chat_prompt):
        raise TypeError("unpadded stateful prompt inputs differ")
    prompt = build_v1_proposal_prompt(task_text, history_plan.evidence_texts)
    token_ids = tuple(tokenize_chat_prompt(prompt))
    if (
        not token_ids
        or len(token_ids) > MAXIMUM_INPUT_TOKENS
        or any(type(value) is not int or value < 0 for value in token_ids)
    ):
        raise V2IntegrityStop("unpadded stateful prompt tokens differ")
    return PromptPlan(
        arm=history_plan.arm,
        task_id=history_plan.task_id,
        history_plan=history_plan,
        prompt=prompt,
        prompt_ref=content_ref({"prompt": prompt}),
        token_ids=token_ids,
        padding_atoms=0,
        target_tokens=len(token_ids),
    )


def build_v1_proposal_prompt(
    task_text: str, evidence_texts: tuple[str, ...]
) -> str:
    """Call the frozen V1 prompt constructor without importing it at module load."""

    from angler.runtime.qwen_cognitive import build_qwen_procedure_proposal_prompt

    return build_qwen_procedure_proposal_prompt(
        _text(task_text, "public task text", 16_384),
        evidence_texts,
        count=PROPOSAL_COUNT,
    )


def frozen_qwen_chat_token_ids(
    tokenizer: object,
    prompt: str,
    *,
    enable_thinking: bool = False,
) -> tuple[int, ...]:
    """Tokenize one final chat rendering exactly as ``LocalQwenIO`` does."""

    apply = getattr(tokenizer, "apply_chat_template", None)
    if not callable(apply) or not callable(tokenizer):
        raise TypeError("tokenizer lacks the frozen chat/tokenization API")
    rendered = apply(
        [{"role": "user", "content": prompt}],
        tokenize=False,
        add_generation_prompt=True,
        enable_thinking=enable_thinking,
    )
    if type(rendered) is not str or not rendered:
        raise V2InvariantError("chat template did not return one rendering")
    encoded = tokenizer(rendered, return_tensors="pt")
    try:
        input_ids = encoded["input_ids"]
        attention_mask = encoded["attention_mask"]
    except (KeyError, TypeError) as error:
        raise V2InvariantError("tokenizer omitted aligned generation tensors") from error

    ids_value = input_ids.tolist() if callable(getattr(input_ids, "tolist", None)) else input_ids
    mask_value = (
        attention_mask.tolist()
        if callable(getattr(attention_mask, "tolist", None))
        else attention_mask
    )
    if (
        type(ids_value) not in (tuple, list)
        or len(ids_value) != 1
        or type(ids_value[0]) not in (tuple, list)
        or type(mask_value) not in (tuple, list)
        or len(mask_value) != 1
        or type(mask_value[0]) not in (tuple, list)
        or len(ids_value[0]) != len(mask_value[0])
    ):
        raise V2InvariantError("tokenizer generation rows are not one aligned row")
    selected = tuple(
        int(token)
        for token, mask in zip(ids_value[0], mask_value[0], strict=True)
        if int(mask) == 1
    )
    if not selected or any(type(token) is not int or token < 0 for token in selected):
        raise V2InvariantError("tokenizer produced invalid prompt token IDs")
    return selected


@dataclass(frozen=True, slots=True)
class PromptPlan:
    arm: Arm
    task_id: str
    history_plan: HistoryPlan
    prompt: str
    prompt_ref: str
    token_ids: tuple[int, ...] = field(repr=False)
    padding_atoms: int
    target_tokens: int

    def __post_init__(self) -> None:
        validate_arm(self.arm)
        _ref(self.task_id, "prompt-plan task id")
        if (
            type(self.history_plan) is not HistoryPlan
            or self.history_plan.arm != self.arm
            or self.history_plan.task_id != self.task_id
        ):
            raise ValueError("prompt plan requires its matching history plan")
        _text(self.prompt, "proposal prompt", 131_072)
        _ref(self.prompt_ref, "proposal prompt ref")
        if self.prompt_ref != content_ref({"prompt": self.prompt}):
            raise V2InvariantError("proposal prompt ref differs")
        if (
            type(self.token_ids) is not tuple
            or not self.token_ids
            or any(type(value) is not int or value < 0 for value in self.token_ids)
        ):
            raise ValueError("prompt token IDs are not exact")
        _integer(self.padding_atoms, "prompt padding atoms", maximum=512)
        _integer(
            self.target_tokens,
            "prompt target tokens",
            minimum=1,
            maximum=MAXIMUM_INPUT_TOKENS,
        )
        if len(self.token_ids) != self.target_tokens:
            raise V2InvariantError("prompt did not reach the exact target")
        if self.arm == "N0_NATIVE_NO_HISTORY":
            if self.padding_atoms != 0 or self.history_plan.presentations:
                raise V2InvariantError("native no-history prompt acquired history/padding")
        elif self.history_plan.presentations[-1].padding_atoms != self.padding_atoms:
            raise V2InvariantError("prompt/history padding evidence differs")

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "history_plan_ref": self.history_plan.plan_ref,
            "native_evidence_sha256": (
                hashlib.sha256(
                    NO_PERSISTENT_RECALLED_EVIDENCE_V1.encode("utf-8")
                ).hexdigest()
                if self.arm == "N0_NATIVE_NO_HISTORY"
                else None
            ),
            "padding_atoms": self.padding_atoms,
            "prompt_ref": self.prompt_ref,
            "schema": PROMPT_PLAN_SCHEMA,
            "target_tokens": self.target_tokens,
            "task_id": self.task_id,
            "token_ids_sha256": hashlib.sha256(
                canonical_json_bytes(list(self.token_ids))
            ).hexdigest(),
        }

    @property
    def plan_ref(self) -> str:
        return canonical_ref("prompt-plan", self.to_canonical())


def native_prompt_plan(
    *,
    task_id: str,
    task_text: str,
    tokenize_chat_prompt: Callable[[str], Sequence[int]],
) -> PromptPlan:
    """Freeze the native no-history proposal prompt before its model call."""

    task_id = _ref(task_id, "native prompt task id")
    if not callable(tokenize_chat_prompt):
        raise TypeError("native prompt tokenizer must be callable")
    history = HistoryPlan(
        arm="N0_NATIVE_NO_HISTORY",
        task_id=task_id,
        presentations=(),
    )
    prompt = build_v1_proposal_prompt(
        task_text, (NO_PERSISTENT_RECALLED_EVIDENCE_V1,)
    )
    token_ids = tuple(tokenize_chat_prompt(prompt))
    if not token_ids or any(type(value) is not int or value < 0 for value in token_ids):
        raise V2InvariantError("native prompt tokenizer returned invalid IDs")
    if len(token_ids) > MAXIMUM_INPUT_TOKENS:
        raise V2InvariantError("native prompt exceeds the input-token ceiling")
    return PromptPlan(
        arm="N0_NATIVE_NO_HISTORY",
        task_id=task_id,
        history_plan=history,
        prompt=prompt,
        prompt_ref=content_ref({"prompt": prompt}),
        token_ids=token_ids,
        padding_atoms=0,
        target_tokens=len(token_ids),
    )


@dataclass(frozen=True, slots=True)
class PairEqualityEvidence:
    left_arm: Arm
    right_arm: Arm
    task_id: str
    history_text_equal: bool
    prompt_bytes_equal: bool
    token_ids_equal: bool
    padding_atoms_equal: bool
    proposal_sets_equal: bool | None = None

    def __post_init__(self) -> None:
        pair = (self.left_arm, self.right_arm)
        if pair not in (
            ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"),
            ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"),
        ):
            raise ValueError("pair-equality arm pair differs")
        _ref(self.task_id, "pair-equality task id")
        values = (
            self.history_text_equal,
            self.prompt_bytes_equal,
            self.token_ids_equal,
            self.padding_atoms_equal,
        )
        if any(type(value) is not bool for value in values):
            raise TypeError("pair-equality evidence must use exact booleans")
        if not all(values):
            raise V2InvariantError("paired proposal preimage equality failed")
        if self.proposal_sets_equal is not None and type(
            self.proposal_sets_equal
        ) is not bool:
            raise TypeError("proposal equality must be bool or None")
        if self.proposal_sets_equal is False:
            raise V2IntegrityStop("paired greedy proposal sets differ")

    @property
    def equality_ref(self) -> str:
        return canonical_ref("pair-equality", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "history_text_equal": self.history_text_equal,
            "left_arm": self.left_arm,
            "padding_atoms_equal": self.padding_atoms_equal,
            "prompt_bytes_equal": self.prompt_bytes_equal,
            "proposal_sets_equal": self.proposal_sets_equal,
            "right_arm": self.right_arm,
            "schema": PAIR_EQUALITY_SCHEMA,
            "task_id": self.task_id,
            "token_ids_equal": self.token_ids_equal,
        }


def plan_equalized_prompts(
    *,
    task_text: str,
    history_plans: Mapping[Arm, HistoryPlan],
    tokenize_chat_prompt: Callable[[str], Sequence[int]],
) -> tuple[dict[Arm, PromptPlan], tuple[PairEqualityEvidence, PairEqualityEvidence]]:
    """Pre-plan all seven padded proposal prompts before any generation."""

    if not callable(tokenize_chat_prompt):
        raise TypeError("tokenize_chat_prompt must be callable")
    plans = dict(history_plans)
    if set(plans) != set(TWELVE_SLOT_ARMS):
        raise V2InvariantError("prompt planner requires all seven twelve-slot arms")
    task_ids = {plan.task_id for plan in plans.values()}
    if (
        len(task_ids) != 1
        or any(arm != plan.arm for arm, plan in plans.items())
        or any(
            item.padding_atoms != 0
            for plan in plans.values()
            for item in plan.presentations
        )
    ):
        raise V2InvariantError("prompt plans do not bind one exact task/arm matrix")
    if plans["F0_NEUTRAL_FORMATTED_12"].evidence_texts != plans[
        "IN_FULL_NEUTRAL_12"
    ].evidence_texts:
        raise V2InvariantError("F0/IN unpadded evidence differs")
    if plans["O0_ORDINARY_FROZEN_12"].evidence_texts != plans[
        "IO_FULL_ORDINARY_12"
    ].evidence_texts:
        raise V2InvariantError("O0/IO unpadded evidence differs")

    unpadded: dict[Arm, tuple[str, tuple[int, ...]]] = {}
    for arm in TWELVE_SLOT_ARMS:
        prompt = build_v1_proposal_prompt(task_text, plans[arm].evidence_texts)
        ids = tuple(tokenize_chat_prompt(prompt))
        if not ids or any(type(value) is not int or value < 0 for value in ids):
            raise V2InvariantError("prompt tokenizer returned invalid IDs")
        unpadded[arm] = (prompt, ids)
    target = max(len(ids) for _, ids in unpadded.values()) + PADDING_TARGET_MARGIN
    if target > MAXIMUM_INPUT_TOKENS:
        raise V2InvariantError("padding target exceeds the input-token ceiling")

    output: dict[Arm, PromptPlan] = {}
    for arm in TWELVE_SLOT_ARMS:
        base = plans[arm]
        chosen: PromptPlan | None = None
        for count in range(MAXIMUM_PADDING_ATOMS + 1):
            presentations = list(base.presentations)
            presentations[-1] = presentations[-1].with_padding(count)
            candidate_history = HistoryPlan(
                arm=base.arm,
                task_id=base.task_id,
                presentations=tuple(presentations),
                selection_rows=base.selection_rows,
                selection_plan=base.selection_plan,
            )
            prompt = build_v1_proposal_prompt(
                task_text, candidate_history.evidence_texts
            )
            token_ids = tuple(tokenize_chat_prompt(prompt))
            if any(type(value) is not int or value < 0 for value in token_ids):
                raise V2InvariantError("prompt tokenizer returned invalid IDs")
            if len(token_ids) == target:
                chosen = PromptPlan(
                    arm=arm,
                    task_id=base.task_id,
                    history_plan=candidate_history,
                    prompt=prompt,
                    prompt_ref=content_ref({"prompt": prompt}),
                    token_ids=token_ids,
                    padding_atoms=count,
                    target_tokens=target,
                )
                break
        if chosen is None:
            raise V2InvariantError("padding planner cannot reach the exact target")
        output[arm] = chosen

    equality: list[PairEqualityEvidence] = []
    for left, right in (
        ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"),
        ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"),
    ):
        left_plan, right_plan = output[left], output[right]
        equality.append(
            PairEqualityEvidence(
                left_arm=left,
                right_arm=right,
                task_id=left_plan.task_id,
                history_text_equal=(
                    left_plan.history_plan.evidence_texts
                    == right_plan.history_plan.evidence_texts
                ),
                prompt_bytes_equal=(left_plan.prompt == right_plan.prompt),
                token_ids_equal=(left_plan.token_ids == right_plan.token_ids),
                padding_atoms_equal=(
                    left_plan.padding_atoms == right_plan.padding_atoms
                ),
            )
        )
    if {len(plan.token_ids) for plan in output.values()} != {target}:
        raise V2InvariantError("twelve-slot prompt token counts are not equal")
    return output, (equality[0], equality[1])


def bind_paired_proposal_sets(
    evidence: PairEqualityEvidence,
    left_proposals: Sequence[str],
    right_proposals: Sequence[str],
) -> PairEqualityEvidence:
    left = tuple(left_proposals)
    right = tuple(right_proposals)
    if len(left) != PROPOSAL_COUNT or len(right) != PROPOSAL_COUNT:
        raise V2InvariantError("paired proposal set cardinality differs")
    return PairEqualityEvidence(
        left_arm=evidence.left_arm,
        right_arm=evidence.right_arm,
        task_id=evidence.task_id,
        history_text_equal=evidence.history_text_equal,
        prompt_bytes_equal=evidence.prompt_bytes_equal,
        token_ids_equal=evidence.token_ids_equal,
        padding_atoms_equal=evidence.padding_atoms_equal,
        proposal_sets_equal=left == right,
    )


def _task_canonical(task: object) -> dict[str, object]:
    value = _canonical_mapping(task, "public evaluation task")
    expected = {
        "family",
        "ordinal",
        "payload",
        "phase",
        "protocol_identity",
        "public_task_ref",
        "replicate",
        "replicate_commitment",
        "task_id",
    }
    if set(value) != expected:
        raise V2InvariantError("public task fields differ from the frozen evaluator")
    family = validate_family(value["family"])
    phase = validate_phase(value["phase"])
    ordinal = _integer(value["ordinal"], "public task ordinal", maximum=14)
    replicate_commitment = _ref(
        value["replicate_commitment"], "public task replicate commitment"
    )
    task_id = _ref(value["task_id"], "public task id")
    public_ref = _ref(value["public_task_ref"], "public task ref")
    if value["protocol_identity"] != PROTOCOL_IDENTITY:
        raise V2InvariantError("public task protocol identity differs")
    payload = value["payload"]
    if type(payload) is not dict or payload.get("family") != family:
        raise V2InvariantError("public task payload/family binding differs")
    canonical_json_bytes(payload)
    label = value["replicate"]
    if type(label) is not str or re.fullmatch(
        r"(?:qualification|replicate)-[0-9]{2}", label
    ) is None:
        raise ValueError("public task replicate label differs")
    expected_public_ref = domain_ref(
        PUBLIC_TASK_DOMAIN,
        {
            "family": family,
            "ordinal": ordinal,
            "payload": payload,
            "phase": phase,
            "protocol_identity": PROTOCOL_IDENTITY,
            "replicate": label,
            "replicate_commitment": replicate_commitment,
        },
    )
    if public_ref != expected_public_ref:
        raise V2InvariantError("public task ref does not bind its public payload")
    expected_task_id = domain_ref(
        TASK_ID_DOMAIN,
        {
            "family": family,
            "ordinal": ordinal,
            "phase": phase,
            "protocol_identity": PROTOCOL_IDENTITY,
            "public_task_ref": public_ref,
            "replicate": label,
        },
    )
    if task_id != expected_task_id:
        raise V2InvariantError("task id does not bind its public task ref")
    return value


def public_task_ref(task: object) -> str:
    value = _task_canonical(task)
    candidate = value.get("public_task_ref", value.get("public_commitment"))
    return _ref(candidate, "public task ref")


def _replicate_index(task: Mapping[str, object], purpose: Purpose) -> int:
    purpose = validate_purpose(purpose)
    label = task["replicate"]
    expected_prefix = "qualification-" if purpose == "qualification" else "replicate-"
    if type(label) is not str or not label.startswith(expected_prefix):
        raise V2InvariantError("task replicate label differs from purpose")
    index = int(label[-2:])
    if purpose == "qualification" and index != 1:
        raise V2InvariantError("qualification replicate must be qualification-01")
    if purpose == "evaluation" and index not in (1, 2, 3):
        raise V2InvariantError("evaluation replicate index is outside 01..03")
    return index - 1


def round_robin_tasks(
    tasks: Sequence[object], *, purpose: Purpose, phase: Phase
) -> tuple[dict[str, object], ...]:
    purpose = validate_purpose(purpose)
    phase = validate_phase(phase)
    values = tuple(_task_canonical(task) for task in tasks)
    if any(task["phase"] != phase for task in values):
        raise V2InvariantError("task phase differs from schedule phase")
    by_replicate: dict[str, list[dict[str, object]]] = defaultdict(list)
    for task in values:
        _replicate_index(task, purpose)
        by_replicate[str(task["replicate"])].append(task)
    expected_replicates = 1 if purpose == "qualification" else 3
    expected_labels = (
        {"qualification-01"}
        if purpose == "qualification"
        else {"replicate-01", "replicate-02", "replicate-03"}
    )
    if len(by_replicate) != expected_replicates or set(by_replicate) != expected_labels:
        raise V2InvariantError("schedule replicate count differs")

    expected_per_family = (
        {"adaptation": 15, "development": 1, "final": 0}
        if purpose == "qualification"
        else {"adaptation": 15, "development": 3, "final": 6}
    )[phase]
    if expected_per_family == 0:
        raise V2InvariantError("purpose does not declare tasks for this phase")

    output: list[dict[str, object]] = []
    for replicate in sorted(by_replicate):
        rows = by_replicate[replicate]
        cells: dict[tuple[Family, int], dict[str, object]] = {}
        for row in rows:
            key = (validate_family(row["family"]), int(row["ordinal"]))
            if key in cells:
                raise V2InvariantError("schedule repeats a family ordinal")
            cells[key] = row
        expected_cells = {
            (family, ordinal)
            for family in FAMILIES
            for ordinal in range(expected_per_family)
        }
        if set(cells) != expected_cells:
            raise V2InvariantError("schedule phase/family ordinal inventory differs")
        ordinals = list(range(expected_per_family))
        for ordinal in ordinals:
            for family in FAMILIES:
                try:
                    output.append(cells[(family, ordinal)])
                except KeyError as error:
                    raise V2InvariantError(
                        "schedule is not balanced round-robin by family"
                    ) from error
    if len({str(item["task_id"]) for item in output}) != len(output):
        raise V2InvariantError("schedule repeats a task identity")
    return tuple(output)


@dataclass(frozen=True, slots=True)
class ScheduledAttempt:
    purpose: Purpose
    phase: Phase
    arm: Arm
    task: dict[str, object] = field(repr=False, compare=False)
    block_ordinal: int
    arm_position: int

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        validate_phase(self.phase)
        validate_arm(self.arm)
        canonical = _task_canonical(self.task)
        if canonical != self.task or canonical["phase"] != self.phase:
            raise V2InvariantError("scheduled attempt task differs")
        _replicate_index(canonical, self.purpose)
        _integer(self.block_ordinal, "schedule block ordinal")
        _integer(self.arm_position, "schedule arm position", maximum=7)
        if self.phase == "adaptation" and self.arm not in STATEFUL_ARMS:
            raise V2InvariantError("adaptation admits only IN and IO")

    @property
    def task_id(self) -> str:
        return str(self.task["task_id"])

    @property
    def replicate_commitment(self) -> str:
        return str(self.task["replicate_commitment"])

    @property
    def family(self) -> Family:
        return validate_family(self.task["family"])

    @property
    def attempt_key(self) -> tuple[str, Arm]:
        return self.task_id, self.arm

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "arm_position": self.arm_position,
            "block_ordinal": self.block_ordinal,
            "family": self.family,
            "phase": self.phase,
            "public_task_ref": public_task_ref(self.task),
            "purpose": self.purpose,
            "replicate": self.task["replicate"],
            "replicate_commitment": self.replicate_commitment,
            "task_id": self.task_id,
        }


def development_final_schedule(
    tasks: Sequence[object], *, purpose: Purpose, phase: Literal["development", "final"]
) -> tuple[ScheduledAttempt, ...]:
    purpose = validate_purpose(purpose)
    if phase not in ("development", "final"):
        raise ValueError("eight-arm schedule is development or final only")
    ordered = round_robin_tasks(tasks, purpose=purpose, phase=phase)
    output: list[ScheduledAttempt] = []
    for block, task in enumerate(ordered):
        r = _replicate_index(task, purpose)
        p = 0 if phase == "development" else 1
        offset = (block + 3 * r + 5 * p) % len(ARMS)
        for position in range(8):
            arm = ARMS[(offset + position) % 8]
            output.append(
                ScheduledAttempt(
                    purpose=purpose,
                    phase=phase,
                    arm=arm,
                    task=task,
                    block_ordinal=block,
                    arm_position=position,
                )
            )
    return tuple(output)


def adaptation_schedule(
    tasks: Sequence[object], *, purpose: Purpose
) -> tuple[ScheduledAttempt, ...]:
    purpose = validate_purpose(purpose)
    ordered = round_robin_tasks(tasks, purpose=purpose, phase="adaptation")
    output: list[ScheduledAttempt] = []
    for global_index, task in enumerate(ordered):
        r = _replicate_index(task, purpose)
        if purpose == "qualification":
            arms: tuple[Arm, ...] = (
                ("IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12")
                if int(task["ordinal"]) == 0
                and (global_index + r) % 2 == 0
                else (
                    ("IO_FULL_ORDINARY_12", "IN_FULL_NEUTRAL_12")
                    if int(task["ordinal"]) == 0
                    else ("IO_FULL_ORDINARY_12",)
                )
            )
        else:
            arms = (
                ("IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12")
                if (global_index + r) % 2 == 0
                else ("IO_FULL_ORDINARY_12", "IN_FULL_NEUTRAL_12")
            )
        for position, arm in enumerate(arms):
            output.append(
                ScheduledAttempt(
                    purpose=purpose,
                    phase="adaptation",
                    arm=arm,
                    task=task,
                    block_ordinal=global_index,
                    arm_position=position,
                )
            )
    expected = 48 if purpose == "qualification" else 270
    if len(output) != expected:
        raise V2InvariantError("adaptation attempt schedule cardinality differs")
    return tuple(output)


@dataclass(slots=True)
class AttemptBudget:
    mode: RunMode
    proposal_ceiling: int = field(init=False)
    execution_ceiling: int = field(init=False)
    arm_task_ceiling: int = field(init=False)
    generation_ceiling: int = field(init=False)
    _proposed: set[tuple[str, Arm]] = field(default_factory=set, init=False)
    _executed: set[tuple[str, Arm]] = field(default_factory=set, init=False)
    _finished: set[tuple[str, Arm]] = field(default_factory=set, init=False)

    def __post_init__(self) -> None:
        if type(self.mode) is not RunMode:
            self.mode = RunMode(self.mode)
        if self.mode is RunMode.QUALIFICATION:
            arm_tasks, generations = 72, MAXIMUM_QUALIFICATION_GENERATIONS
        else:
            arm_tasks, generations = 918, MAXIMUM_EVALUATION_GENERATIONS
        self.proposal_ceiling = arm_tasks
        self.execution_ceiling = arm_tasks
        self.arm_task_ceiling = arm_tasks
        self.generation_ceiling = generations

    def consume_proposal(self, task_id: str, arm: Arm) -> None:
        key = (_ref(task_id, "attempt-budget task id"), validate_arm(arm))
        if key in self._proposed:
            raise V2IntegrityStop("proposal retry is forbidden")
        if len(self._proposed) >= self.proposal_ceiling:
            raise V2IntegrityStop("proposal ceiling exceeded")
        self._proposed.add(key)

    def consume_execution(self, task_id: str, arm: Arm) -> None:
        key = (_ref(task_id, "attempt-budget task id"), validate_arm(arm))
        if key not in self._proposed or key in self._executed or key in self._finished:
            raise V2IntegrityStop("execution is missing a unique proposal boundary")
        if len(self._executed) >= self.execution_ceiling:
            raise V2IntegrityStop("execution ceiling exceeded")
        if len(self._proposed) + len(self._executed) >= self.generation_ceiling:
            raise V2IntegrityStop("generation-call ceiling exceeded")
        self._executed.add(key)

    def finish(self, task_id: str, arm: Arm) -> None:
        key = (_ref(task_id, "attempt-budget task id"), validate_arm(arm))
        if key not in self._proposed or key in self._finished:
            raise V2IntegrityStop("attempt finalization is missing or duplicated")
        if len(self._finished) >= self.arm_task_ceiling:
            raise V2IntegrityStop("arm-task ceiling exceeded")
        self._finished.add(key)

    def snapshot(self) -> dict[str, int]:
        return {
            "arm_tasks": len(self._finished),
            "execution_attempts": len(self._executed),
            "generation_attempts": len(self._proposed) + len(self._executed),
            "proposal_attempts": len(self._proposed),
        }


@dataclass(frozen=True, slots=True)
class ResourceCeilings:
    maximum_wall_seconds: float = MAXIMUM_WALL_SECONDS
    maximum_rss_bytes: int = MAXIMUM_RSS_BYTES
    maximum_cuda_allocated_bytes: int = MAXIMUM_CUDA_BYTES
    maximum_cuda_reserved_bytes: int = MAXIMUM_CUDA_BYTES
    maximum_configured_pools: int = MAXIMUM_CONFIGURED_POOLS
    maximum_processes: int = MAXIMUM_PROCESSES
    maximum_state_scratch_bytes: int = MAXIMUM_STATE_SCRATCH_BYTES
    maximum_result_bytes: int = MAXIMUM_RESULT_BYTES

    def __post_init__(self) -> None:
        expected = (
            MAXIMUM_WALL_SECONDS,
            MAXIMUM_RSS_BYTES,
            MAXIMUM_CUDA_BYTES,
            MAXIMUM_CUDA_BYTES,
            MAXIMUM_CONFIGURED_POOLS,
            MAXIMUM_PROCESSES,
            MAXIMUM_STATE_SCRATCH_BYTES,
            MAXIMUM_RESULT_BYTES,
        )
        observed = (
            self.maximum_wall_seconds,
            self.maximum_rss_bytes,
            self.maximum_cuda_allocated_bytes,
            self.maximum_cuda_reserved_bytes,
            self.maximum_configured_pools,
            self.maximum_processes,
            self.maximum_state_scratch_bytes,
            self.maximum_result_bytes,
        )
        if observed != expected:
            raise ValueError("V2 resource ceilings are immutable")


@dataclass(slots=True)
class ResourceLedger:
    mode: RunMode
    ceilings: ResourceCeilings = field(default_factory=ResourceCeilings)
    started: float = field(default_factory=time.monotonic)
    generation_calls: int = 0
    embedding_rows: int = 0
    runtime_embedding_rows: int = 0
    prompt_tokens: int = 0
    output_tokens: int = 0
    peak_rss_bytes: int = 0
    peak_cuda_allocated_bytes: int = 0
    peak_cuda_reserved_bytes: int = 0
    peak_state_scratch_bytes: int = 0
    peak_processes: int = 0
    configured_pools: int = 0
    samples: int = 0
    _generation_reconciler: object | None = field(
        default=None, init=False, repr=False
    )

    def __post_init__(self) -> None:
        if type(self.mode) is not RunMode:
            self.mode = RunMode(self.mode)
        if type(self.ceilings) is not ResourceCeilings:
            raise TypeError("resource ledger ceilings differ")

    @property
    def generation_ceiling(self) -> int:
        return (
            MAXIMUM_QUALIFICATION_GENERATIONS
            if self.mode is RunMode.QUALIFICATION
            else MAXIMUM_EVALUATION_GENERATIONS
        )

    @property
    def embedding_ceiling(self) -> int:
        return (
            MAXIMUM_QUALIFICATION_EMBEDDING_ROWS
            if self.mode is RunMode.QUALIFICATION
            else MAXIMUM_EVALUATION_EMBEDDING_ROWS
        )

    @property
    def runtime_embedding_ceiling(self) -> int:
        return (
            MAXIMUM_QUALIFICATION_RUNTIME_EMBEDDING_ROWS
            if self.mode is RunMode.QUALIFICATION
            else MAXIMUM_EVALUATION_RUNTIME_EMBEDDING_ROWS
        )

    def record_generation(self, prompt_tokens: int, output_tokens: int) -> None:
        _integer(prompt_tokens, "prompt tokens", minimum=1, maximum=4096)
        _integer(
            output_tokens,
            "output tokens",
            minimum=1,
            maximum=MAXIMUM_OUTPUT_TOKENS,
        )
        if self.generation_calls >= self.generation_ceiling:
            raise V2IntegrityStop("resource generation ceiling exceeded")
        if self._generation_reconciler is not None:
            reconcile = getattr(
                self._generation_reconciler,
                "reconcile_generation",
                None,
            )
            if not callable(reconcile):
                raise V2IntegrityStop("generation reconciler boundary differs")
            reconcile(prompt_tokens, output_tokens)
        self.generation_calls += 1
        self.prompt_tokens += prompt_tokens
        self.output_tokens += output_tokens

    def _bind_generation_reconciler(self, owner: object) -> None:
        if self._generation_reconciler is not None:
            raise V2IntegrityStop("generation reconciler is already bound")
        self._generation_reconciler = owner

    def _unbind_generation_reconciler(self, owner: object) -> None:
        if self._generation_reconciler is not owner:
            raise V2IntegrityStop("generation reconciler ownership differs")
        self._generation_reconciler = None

    def record_embeddings(self, rows: int) -> None:
        rows = _integer(rows, "embedding rows", minimum=1)
        if self.embedding_rows + rows > self.embedding_ceiling:
            raise V2IntegrityStop("history-ranking embedding ceiling exceeded")
        self.embedding_rows += rows

    def record_runtime_embeddings(self, rows: int) -> None:
        rows = _integer(rows, "runtime embedding rows", minimum=1)
        if (
            rows != RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
            or self.runtime_embedding_rows + rows
            > self.runtime_embedding_ceiling
        ):
            raise V2IntegrityStop("stateful runtime embedding ceiling exceeded")
        self.runtime_embedding_rows += rows

    def record_rss_peak(self, rss_bytes: int) -> None:
        rss_bytes = _integer(rss_bytes, "observed peak RSS")
        self.peak_rss_bytes = max(self.peak_rss_bytes, rss_bytes)
        if self.peak_rss_bytes > self.ceilings.maximum_rss_bytes:
            raise V2IntegrityStop("process RSS ceiling exceeded")

    def sample_boundary(
        self,
        *,
        rss_bytes: int,
        cuda_allocated_bytes: int,
        cuda_reserved_bytes: int,
        state_scratch_bytes: int,
        process_count: int,
        configured_pools: int,
        now: float | None = None,
    ) -> None:
        values = (
            rss_bytes,
            cuda_allocated_bytes,
            cuda_reserved_bytes,
            state_scratch_bytes,
            process_count,
            configured_pools,
        )
        if any(type(value) is not int or value < 0 for value in values):
            raise ValueError("resource samples must be non-negative integers")
        wall = (time.monotonic() if now is None else _finite(now, "sample time")) - self.started
        if wall < 0:
            raise ValueError("resource sample precedes ledger start")
        self.peak_rss_bytes = max(self.peak_rss_bytes, rss_bytes)
        self.peak_cuda_allocated_bytes = max(
            self.peak_cuda_allocated_bytes, cuda_allocated_bytes
        )
        self.peak_cuda_reserved_bytes = max(
            self.peak_cuda_reserved_bytes, cuda_reserved_bytes
        )
        self.peak_state_scratch_bytes = max(
            self.peak_state_scratch_bytes, state_scratch_bytes
        )
        self.peak_processes = max(self.peak_processes, process_count)
        self.configured_pools = max(self.configured_pools, configured_pools)
        self.samples += 1
        if (
            wall > self.ceilings.maximum_wall_seconds
            or self.peak_rss_bytes > self.ceilings.maximum_rss_bytes
            or self.peak_cuda_allocated_bytes
            > self.ceilings.maximum_cuda_allocated_bytes
            or self.peak_cuda_reserved_bytes > self.ceilings.maximum_cuda_reserved_bytes
            or self.peak_state_scratch_bytes
            > self.ceilings.maximum_state_scratch_bytes
            or self.peak_processes > self.ceilings.maximum_processes
            or self.configured_pools > self.ceilings.maximum_configured_pools
        ):
            raise V2IntegrityStop("resource ceiling reached at an arm boundary")

    def to_canonical(self) -> dict[str, object]:
        wall = max(0.0, time.monotonic() - self.started)
        return {
            "configured_pools": self.configured_pools,
            "embedding_rows": self.embedding_rows,
            "generation_calls": self.generation_calls,
            "mode": self.mode.value,
            "output_tokens": self.output_tokens,
            "peak_cuda_allocated_bytes": self.peak_cuda_allocated_bytes,
            "peak_cuda_reserved_bytes": self.peak_cuda_reserved_bytes,
            "peak_processes": self.peak_processes,
            "peak_rss_bytes": self.peak_rss_bytes,
            "peak_state_scratch_bytes": self.peak_state_scratch_bytes,
            "prompt_tokens": self.prompt_tokens,
            "runtime_embedding_rows": self.runtime_embedding_rows,
            "samples": self.samples,
            "schema": RESOURCE_SCHEMA,
            "wall_seconds": wall,
        }


_FOUNDATION_MIRROR_DIGEST_DOMAIN = (
    b"project-angler.foundation-parameters.v1\x00"
)


@dataclass(frozen=True, slots=True)
class _FoundationByteMirrorRow:
    name: str
    shape: tuple[int, ...]
    dtype: str
    raw: bytes = field(repr=False)

    def __post_init__(self) -> None:
        _text(self.name, "foundation mirror parameter name", 2_048)
        if (
            any(type(value) is not int or value < 0 for value in self.shape)
            or type(self.dtype) is not str
            or not self.dtype
            or type(self.raw) is not bytes
            or not self.raw
        ):
            raise ValueError("foundation mirror row differs")


@dataclass(frozen=True, slots=True)
class _FoundationMirrorSegment:
    row_index: int
    row_offset: int
    slot_offset: int
    length: int

    def __post_init__(self) -> None:
        if (
            type(self.row_index) is not int
            or self.row_index < 0
            or type(self.row_offset) is not int
            or self.row_offset < 0
            or type(self.slot_offset) is not int
            or self.slot_offset < 0
            or type(self.length) is not int
            or self.length < 1
        ):
            raise ValueError("foundation mirror segment differs")


@dataclass(frozen=True, slots=True)
class _FoundationMirrorChunk:
    global_offset: int
    length: int
    segments: tuple[_FoundationMirrorSegment, ...]

    def __post_init__(self) -> None:
        if (
            type(self.global_offset) is not int
            or self.global_offset < 0
            or type(self.length) is not int
            or not 1 <= self.length <= FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            or type(self.segments) is not tuple
            or not self.segments
            or any(
                type(segment) is not _FoundationMirrorSegment
                for segment in self.segments
            )
        ):
            raise ValueError("foundation mirror chunk differs")


@dataclass(frozen=True, slots=True)
class _PinnedAllocatorSnapshot:
    allocations_current: int
    allocated_bytes_current: int
    active_requests_current: int
    active_bytes_current: int

    def __post_init__(self) -> None:
        if any(
            type(value) is not int or value < 0
            for value in (
                self.allocations_current,
                self.allocated_bytes_current,
                self.active_requests_current,
                self.active_bytes_current,
            )
        ):
            raise ValueError("foundation pinned allocator snapshot differs")


@dataclass(frozen=True, slots=True)
class _FoundationMirrorAuditReceipt:
    parameter_count: int
    parameter_bytes: int
    largest_parameter_bytes: int
    pinned_slot_count: int
    pinned_slot_bytes: int
    pinned_bytes: int
    vm_locked_bytes_before: int
    memlock_soft_limit_bytes: int
    rss_bytes_before: int
    rss_reservation_bytes: int
    allocator_baseline: _PinnedAllocatorSnapshot
    allocator_post_allocation: _PinnedAllocatorSnapshot
    allocator_cleanup: _PinnedAllocatorSnapshot | None
    verification_durations_ns: tuple[int, ...]
    performance_gate_passed: bool
    poisoned: bool
    closed: bool
    cleanup_proven: bool

    def __post_init__(self) -> None:
        if (
            self.parameter_count != QUALIFIED_MODEL_PARAMETER_COUNT
            or self.parameter_bytes != QUALIFIED_MODEL_PARAMETER_BYTES
            or self.largest_parameter_bytes
            != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
            or self.pinned_slot_count != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            or self.pinned_slot_bytes != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            or self.pinned_bytes != FOUNDATION_MIRROR_PINNED_BYTES
            or any(
                type(value) is not int or value < 0
                for value in (
                    self.vm_locked_bytes_before,
                    self.rss_bytes_before,
                    self.rss_reservation_bytes,
                )
            )
            or self.rss_reservation_bytes
            != (
                self.rss_bytes_before
                + QUALIFIED_MODEL_PARAMETER_BYTES
                + FOUNDATION_MIRROR_PINNED_BYTES
                + FOUNDATION_MIRROR_TRANSIENT_BYTES
            )
            or self.rss_reservation_bytes > MAXIMUM_RSS_BYTES
            or type(self.memlock_soft_limit_bytes) is not int
            or type(self.allocator_baseline) is not _PinnedAllocatorSnapshot
            or type(self.allocator_post_allocation)
            is not _PinnedAllocatorSnapshot
            or (
                self.allocator_cleanup is not None
                and type(self.allocator_cleanup)
                is not _PinnedAllocatorSnapshot
            )
            or type(self.verification_durations_ns) is not tuple
            or any(
                type(value) is not int or value < 1
                for value in self.verification_durations_ns
            )
            or type(self.performance_gate_passed) is not bool
            or type(self.poisoned) is not bool
            or type(self.closed) is not bool
            or type(self.cleanup_proven) is not bool
        ):
            raise ValueError("foundation mirror audit receipt differs")


def _pinned_allocator_snapshot_canonical(
    value: _PinnedAllocatorSnapshot,
) -> dict[str, int]:
    if type(value) is not _PinnedAllocatorSnapshot:
        raise TypeError("foundation pinned allocator receipt differs")
    return {
        "active_bytes_current": value.active_bytes_current,
        "active_requests_current": value.active_requests_current,
        "allocated_bytes_current": value.allocated_bytes_current,
        "allocations_current": value.allocations_current,
    }


def _validated_pinned_allocator_snapshot(
    value: object,
    label: str,
) -> _PinnedAllocatorSnapshot:
    row = _canonical_mapping(value, label)
    expected = {
        "active_bytes_current",
        "active_requests_current",
        "allocated_bytes_current",
        "allocations_current",
    }
    if set(row) != expected:
        raise V2InvariantError(f"{label} fields differ")
    values = tuple(row[name] for name in (
        "allocations_current",
        "allocated_bytes_current",
        "active_requests_current",
        "active_bytes_current",
    ))
    if any(type(item) is not int or item < 0 for item in values):
        raise V2InvariantError(f"{label} counters differ")
    return _PinnedAllocatorSnapshot(*values)


def validate_foundation_preflight_boundary_record(
    value: Mapping[str, object],
    *,
    expected_source_inventory_ref: str,
) -> dict[str, object]:
    """Validate the public, tensor-free closure of the private child boundary."""

    expected_source_inventory_ref = _ref(
        expected_source_inventory_ref, "preflight boundary source inventory"
    )
    row = dict(value)
    expected_keys = {
        "assigned_gpu_name",
        "assigned_gpu_uuid",
        "boundary",
        "environment_sha256",
        "host_boundary_ref",
        "hostname",
        "logical_device_count",
        "logical_device_index",
        "mount_namespace",
        "namespace_boundary_ref",
        "namespace_proof",
        "network_namespace",
        "python",
        "python_executable",
        "source_inventory_ref",
        "unassigned_compute_processes",
        "unassigned_gpu_name",
        "unassigned_gpu_uuid",
    }
    if set(row) != expected_keys:
        raise V2InvariantError("foundation preflight boundary fields differ")
    environment_sha256 = hashlib.sha256(
        canonical_json_bytes(_frozen_foundation_preflight_environment())
    ).hexdigest()
    proof = validate_foundation_preflight_namespace_proof(
        _canonical_mapping(row["namespace_proof"], "preflight namespace proof")
    )
    if (
        row["boundary"] != "FOUNDATION_MIRROR_PREFLIGHT_CHILD"
        or row["environment_sha256"] != environment_sha256
        or row["hostname"] != EXPECTED_HOSTNAME
        or row["python"] != EXPECTED_PYTHON_VERSION
        or row["python_executable"] != str(ANGLER_PYTHON)
        or row["source_inventory_ref"] != expected_source_inventory_ref
        or row["assigned_gpu_uuid"] != ASSIGNED_GPU_UUID
        or row["assigned_gpu_name"] != "NVIDIA GeForce RTX 5080"
        or row["unassigned_gpu_uuid"] != UNASSIGNED_GPU_UUID
        or row["unassigned_gpu_name"] != "NVIDIA GeForce RTX 5070"
        or row["unassigned_compute_processes"] != 0
        or row["logical_device_count"] != 1
        or row["logical_device_index"] != 0
        or type(row["mount_namespace"]) is not str
        or re.fullmatch(r"mnt:\[[0-9]+\]", row["mount_namespace"]) is None
        or type(row["network_namespace"]) is not str
        or re.fullmatch(r"net:\[[0-9]+\]", row["network_namespace"]) is None
        or row["mount_namespace"] != proof["self_mount_namespace"]
        or row["network_namespace"] != proof["self_network_namespace"]
        or row["namespace_boundary_ref"]
        != canonical_ref("foundation-preflight-namespace", proof)
    ):
        raise V2IntegrityStop("foundation preflight boundary identity differs")
    host_payload = dict(row)
    host_payload.pop("boundary")
    observed_ref = host_payload.pop("host_boundary_ref")
    if observed_ref != canonical_ref("foundation-preflight-host", host_payload):
        raise V2IntegrityStop("foundation preflight host boundary ref differs")
    return row


def validate_foundation_preflight_host_closure(
    value: Mapping[str, object],
    *,
    expected_source_inventory_ref: str,
) -> dict[str, object]:
    expected_source_inventory_ref = _ref(
        expected_source_inventory_ref, "preflight host source inventory"
    )
    row = dict(value)
    expected_keys = {
        "child_exit_terminal",
        "host_closure_ref",
        "host_live_paths_absent",
        "host_private_path_absent",
        "host_scratch_device",
        "host_scratch_gid",
        "host_scratch_identity_unchanged",
        "host_scratch_inode",
        "host_scratch_mode",
        "host_scratch_path",
        "host_scratch_uid",
        "source_inventory_ref",
        "stdout_single_canonical_receipt",
    }
    if set(row) != expected_keys:
        raise V2InvariantError("foundation preflight host closure fields differ")
    if (
        row["source_inventory_ref"] != expected_source_inventory_ref
        or row["host_scratch_path"] != "/opt/angler/scratch"
        or row["host_scratch_mode"] != "0700"
        or row["host_scratch_uid"] != 1000
        or row["host_scratch_gid"] != 1000
        or type(row["host_scratch_device"]) is not int
        or row["host_scratch_device"] < 0
        or type(row["host_scratch_inode"]) is not int
        or row["host_scratch_inode"] < 1
        or row["host_scratch_identity_unchanged"] is not True
        or row["host_private_path_absent"] is not True
        or row["host_live_paths_absent"] is not True
        or row["child_exit_terminal"] is not True
        or row["stdout_single_canonical_receipt"] is not True
    ):
        raise V2IntegrityStop("foundation preflight host closure differs")
    payload = dict(row)
    observed_ref = payload.pop("host_closure_ref")
    if observed_ref != canonical_ref("foundation-preflight-host-closure", payload):
        raise V2IntegrityStop("foundation preflight host closure ref differs")
    return row


@dataclass(frozen=True, slots=True)
class FoundationMirrorPreflightReceipt:
    """Canonical public proof that the exact source-bound mirror gate passed."""

    source_inventory_ref: str
    source_count: int
    environment_sha256: str
    hostname: str
    python: str
    python_executable: str
    mount_namespace: str
    network_namespace: str
    namespace_boundary_ref: str
    _namespace_proof_json: bytes = field(repr=False)
    assigned_gpu_uuid: str
    assigned_gpu_name: str
    unassigned_gpu_uuid: str
    unassigned_gpu_name: str
    unassigned_compute_processes: int
    logical_device_count: int
    logical_device_index: int
    host_boundary_ref: str
    host_closure_ref: str
    _host_closure_json: bytes = field(repr=False)
    verification_durations_ns: tuple[int, int, int]
    maximum_duration_ns: int
    vm_locked_bytes_before: int
    memlock_soft_limit_bytes: int
    rss_bytes_before: int
    rss_reservation_bytes: int
    allocator_baseline: _PinnedAllocatorSnapshot
    allocator_post_allocation: _PinnedAllocatorSnapshot
    allocator_cleanup: _PinnedAllocatorSnapshot

    def __post_init__(self) -> None:
        _ref(self.source_inventory_ref, "preflight source inventory ref")
        _ref(self.host_boundary_ref, "preflight host boundary ref")
        _ref(self.host_closure_ref, "preflight outer host closure ref")
        _ref(self.namespace_boundary_ref, "preflight namespace boundary ref")
        try:
            namespace_proof = json.loads(self._namespace_proof_json.decode("utf-8"))
        except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise V2InvariantError("preflight namespace proof bytes differ") from error
        namespace_proof = validate_foundation_preflight_namespace_proof(
            _canonical_mapping(namespace_proof, "preflight namespace proof")
        )
        try:
            host_closure_value = json.loads(
                self._host_closure_json.decode("utf-8")
            )
        except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise V2InvariantError("preflight host closure bytes differ") from error
        host_closure = validate_foundation_preflight_host_closure(
            _canonical_mapping(host_closure_value, "preflight host closure"),
            expected_source_inventory_ref=self.source_inventory_ref,
        )
        if (
            self.source_count != len(SOURCE_MANIFEST_INVENTORY)
            or self.environment_sha256
            != hashlib.sha256(
                canonical_json_bytes(_frozen_foundation_preflight_environment())
            ).hexdigest()
            or self.hostname != EXPECTED_HOSTNAME
            or self.python != EXPECTED_PYTHON_VERSION
            or self.python_executable != str(ANGLER_PYTHON)
            or re.fullmatch(r"mnt:\[[0-9]+\]", self.mount_namespace) is None
            or re.fullmatch(r"net:\[[0-9]+\]", self.network_namespace) is None
            or self.assigned_gpu_uuid != ASSIGNED_GPU_UUID
            or self.assigned_gpu_name != "NVIDIA GeForce RTX 5080"
            or self.unassigned_gpu_uuid != UNASSIGNED_GPU_UUID
            or self.unassigned_gpu_name != "NVIDIA GeForce RTX 5070"
            or self.unassigned_compute_processes != 0
            or self.logical_device_count != 1
            or self.logical_device_index != 0
            or type(self.verification_durations_ns) is not tuple
            or len(self.verification_durations_ns) != 3
            or any(
                type(value) is not int or value < 1
                for value in self.verification_durations_ns
            )
            or self.maximum_duration_ns != max(self.verification_durations_ns)
            or self.maximum_duration_ns > FOUNDATION_MIRROR_MAXIMUM_VERIFICATION_NS
            or any(
                type(value) is not int or value < 0
                for value in (
                    self.vm_locked_bytes_before,
                    self.rss_bytes_before,
                    self.rss_reservation_bytes,
                )
            )
            or self.rss_reservation_bytes
            != (
                self.rss_bytes_before
                + QUALIFIED_MODEL_PARAMETER_BYTES
                + FOUNDATION_MIRROR_PINNED_BYTES
                + FOUNDATION_MIRROR_TRANSIENT_BYTES
            )
            or self.rss_reservation_bytes > MAXIMUM_RSS_BYTES
            or type(self.memlock_soft_limit_bytes) is not int
            or (
                self.memlock_soft_limit_bytes != resource.RLIM_INFINITY
                and (
                    self.memlock_soft_limit_bytes
                    < self.vm_locked_bytes_before
                    or self.memlock_soft_limit_bytes
                    - self.vm_locked_bytes_before
                    < FOUNDATION_MIRROR_PINNED_BYTES
                )
            )
            or type(self.allocator_baseline) is not _PinnedAllocatorSnapshot
            or type(self.allocator_post_allocation)
            is not _PinnedAllocatorSnapshot
            or type(self.allocator_cleanup) is not _PinnedAllocatorSnapshot
        ):
            raise V2InvariantError("foundation mirror preflight receipt differs")
        baseline = self.allocator_baseline
        allocated = self.allocator_post_allocation
        cleanup = self.allocator_cleanup
        if (
            allocated.active_requests_current
            != baseline.active_requests_current + FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            or allocated.active_bytes_current
            != baseline.active_bytes_current + FOUNDATION_MIRROR_PINNED_BYTES
            or any(
                observed > expected
                for observed, expected in zip(
                    (
                        cleanup.allocations_current,
                        cleanup.allocated_bytes_current,
                        cleanup.active_requests_current,
                        cleanup.active_bytes_current,
                    ),
                    (
                        baseline.allocations_current,
                        baseline.allocated_bytes_current,
                        baseline.active_requests_current,
                        baseline.active_bytes_current,
                    ),
                    strict=True,
                )
            )
        ):
            raise V2IntegrityStop(
                "foundation mirror preflight allocator proof differs"
            )
        if (
            self.namespace_boundary_ref
            != canonical_ref("foundation-preflight-namespace", namespace_proof)
            or self.mount_namespace != namespace_proof["self_mount_namespace"]
            or self.network_namespace != namespace_proof["self_network_namespace"]
        ):
            raise V2IntegrityStop("foundation preflight namespace binding differs")
        if self.host_closure_ref != host_closure["host_closure_ref"]:
            raise V2IntegrityStop("foundation preflight host closure binding differs")
        if self.host_boundary_ref != canonical_ref(
            "foundation-preflight-host",
            self._host_boundary_payload(),
        ):
            raise V2IntegrityStop("foundation preflight host ref differs")

    def _host_boundary_payload(self) -> dict[str, object]:
        return {
            "assigned_gpu_name": self.assigned_gpu_name,
            "assigned_gpu_uuid": self.assigned_gpu_uuid,
            "environment_sha256": self.environment_sha256,
            "hostname": self.hostname,
            "logical_device_count": self.logical_device_count,
            "logical_device_index": self.logical_device_index,
            "mount_namespace": self.mount_namespace,
            "namespace_boundary_ref": self.namespace_boundary_ref,
            "namespace_proof": json.loads(
                self._namespace_proof_json.decode("utf-8")
            ),
            "network_namespace": self.network_namespace,
            "python": self.python,
            "python_executable": self.python_executable,
            "source_inventory_ref": self.source_inventory_ref,
            "unassigned_compute_processes": self.unassigned_compute_processes,
            "unassigned_gpu_name": self.unassigned_gpu_name,
            "unassigned_gpu_uuid": self.unassigned_gpu_uuid,
        }

    @classmethod
    def from_audit(
        cls,
        audit: _FoundationMirrorAuditReceipt,
        *,
        source_inventory: Sequence[Mapping[str, object]],
        boundary: Mapping[str, object],
        host_closure: Mapping[str, object],
    ) -> "FoundationMirrorPreflightReceipt":
        if type(audit) is not _FoundationMirrorAuditReceipt:
            raise TypeError("foundation mirror private audit differs")
        sources = [dict(row) for row in source_inventory]
        if (
            audit.parameter_count != QUALIFIED_MODEL_PARAMETER_COUNT
            or audit.parameter_bytes != QUALIFIED_MODEL_PARAMETER_BYTES
            or audit.largest_parameter_bytes
            != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
            or audit.pinned_slot_count != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            or audit.pinned_slot_bytes != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            or audit.pinned_bytes != FOUNDATION_MIRROR_PINNED_BYTES
            or audit.performance_gate_passed is not True
            or audit.poisoned is not False
            or audit.closed is not True
            or audit.cleanup_proven is not True
            or audit.allocator_cleanup is None
        ):
            raise V2IntegrityStop("foundation mirror private preflight did not close")
        source_inventory_ref = canonical_ref("source-inventory", sources)
        host = validate_foundation_preflight_boundary_record(
            boundary,
            expected_source_inventory_ref=source_inventory_ref,
        )
        closure = validate_foundation_preflight_host_closure(
            host_closure,
            expected_source_inventory_ref=source_inventory_ref,
        )
        return cls(
            source_inventory_ref=source_inventory_ref,
            source_count=len(sources),
            environment_sha256=host["environment_sha256"],  # type: ignore[arg-type]
            hostname=host["hostname"],  # type: ignore[arg-type]
            python=host["python"],  # type: ignore[arg-type]
            python_executable=host["python_executable"],  # type: ignore[arg-type]
            mount_namespace=host["mount_namespace"],  # type: ignore[arg-type]
            network_namespace=host["network_namespace"],  # type: ignore[arg-type]
            namespace_boundary_ref=host["namespace_boundary_ref"],  # type: ignore[arg-type]
            _namespace_proof_json=canonical_json_bytes(
                _canonical_mapping(
                    host["namespace_proof"], "preflight namespace proof"
                )
            ),
            assigned_gpu_uuid=host["assigned_gpu_uuid"],  # type: ignore[arg-type]
            assigned_gpu_name=host["assigned_gpu_name"],  # type: ignore[arg-type]
            unassigned_gpu_uuid=host["unassigned_gpu_uuid"],  # type: ignore[arg-type]
            unassigned_gpu_name=host["unassigned_gpu_name"],  # type: ignore[arg-type]
            unassigned_compute_processes=host["unassigned_compute_processes"],  # type: ignore[arg-type]
            logical_device_count=host["logical_device_count"],  # type: ignore[arg-type]
            logical_device_index=host["logical_device_index"],  # type: ignore[arg-type]
            host_boundary_ref=host["host_boundary_ref"],  # type: ignore[arg-type]
            host_closure_ref=closure["host_closure_ref"],  # type: ignore[arg-type]
            _host_closure_json=canonical_json_bytes(closure),
            verification_durations_ns=tuple(audit.verification_durations_ns),
            maximum_duration_ns=max(audit.verification_durations_ns),
            vm_locked_bytes_before=audit.vm_locked_bytes_before,
            memlock_soft_limit_bytes=audit.memlock_soft_limit_bytes,
            rss_bytes_before=audit.rss_bytes_before,
            rss_reservation_bytes=audit.rss_reservation_bytes,
            allocator_baseline=audit.allocator_baseline,
            allocator_post_allocation=audit.allocator_post_allocation,
            allocator_cleanup=audit.allocator_cleanup,
        )

    @classmethod
    def from_canonical(
        cls,
        value: Mapping[str, object],
    ) -> "FoundationMirrorPreflightReceipt":
        row = dict(value)
        expected_keys = {
            "accepted_design_sha256",
            "assigned_gpu_name",
            "assigned_gpu_uuid",
            "allocator_baseline",
            "allocator_cleanup",
            "allocator_post_allocation",
            "authorized_leaf_sha256",
            "cleanup_proven",
            "environment_sha256",
            "host_boundary_ref",
            "host_closure",
            "host_closure_ref",
            "hostname",
            "largest_parameter_bytes",
            "maximum_duration_ns",
            "maximum_verification_ns",
            "memlock_soft_limit_bytes",
            "model_ref",
            "mount_namespace",
            "namespace_boundary_ref",
            "namespace_proof",
            "network_namespace",
            "parameter_bytes",
            "parameter_count",
            "performance_gate_passed",
            "pinned_bytes",
            "pinned_slot_bytes",
            "pinned_slot_count",
            "preflight_ref",
            "protocol_identity",
            "python",
            "python_executable",
            "rss_bytes_before",
            "rss_reservation_bytes",
            "schema",
            "source_count",
            "source_inventory_ref",
            "tokenizer_ref",
            "unassigned_compute_processes",
            "unassigned_gpu_name",
            "unassigned_gpu_uuid",
            "logical_device_count",
            "logical_device_index",
            "verification_durations_ns",
            "vm_locked_bytes_before",
        }
        if set(row) != expected_keys:
            raise V2InvariantError("foundation preflight fields differ")
        if (
            row["schema"] != FOUNDATION_MIRROR_PREFLIGHT_SCHEMA
            or row["protocol_identity"] != PROTOCOL_IDENTITY
            or row["accepted_design_sha256"] != ACCEPTED_DESIGN_SHA256
            or row["authorized_leaf_sha256"] != CURRENT_AUTHORIZED_LEAF_SHA256
            or row["model_ref"] != QUALIFIED_MODEL_REF
            or row["tokenizer_ref"] != QUALIFIED_TOKENIZER_REF
            or row["parameter_count"] != QUALIFIED_MODEL_PARAMETER_COUNT
            or row["parameter_bytes"] != QUALIFIED_MODEL_PARAMETER_BYTES
            or row["largest_parameter_bytes"]
            != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
            or row["pinned_slot_count"] != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            or row["pinned_slot_bytes"] != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            or row["pinned_bytes"] != FOUNDATION_MIRROR_PINNED_BYTES
            or row["maximum_verification_ns"]
            != FOUNDATION_MIRROR_MAXIMUM_VERIFICATION_NS
            or row["performance_gate_passed"] is not True
            or row["cleanup_proven"] is not True
            or type(row["verification_durations_ns"]) is not list
            or type(row["memlock_soft_limit_bytes"]) is not int
        ):
            raise V2InvariantError("foundation preflight identity differs")
        receipt = cls(
            source_inventory_ref=_ref(
                row["source_inventory_ref"], "preflight source inventory ref"
            ),
            source_count=_integer(
                row["source_count"], "preflight source count", minimum=1
            ),
            environment_sha256=_raw_digest(
                row["environment_sha256"], "preflight environment digest"
            ),
            hostname=_text(row["hostname"], "preflight hostname", 255),
            python=_text(row["python"], "preflight Python", 64),
            python_executable=_text(
                row["python_executable"], "preflight Python executable", 4096
            ),
            mount_namespace=_text(
                row["mount_namespace"], "preflight mount namespace", 128
            ),
            network_namespace=_text(
                row["network_namespace"], "preflight network namespace", 128
            ),
            namespace_boundary_ref=_ref(
                row["namespace_boundary_ref"],
                "preflight namespace boundary ref",
            ),
            _namespace_proof_json=canonical_json_bytes(
                _canonical_mapping(
                    row["namespace_proof"], "preflight namespace proof"
                )
            ),
            assigned_gpu_uuid=_text(
                row["assigned_gpu_uuid"], "preflight assigned GPU UUID", 128
            ),
            assigned_gpu_name=_text(
                row["assigned_gpu_name"], "preflight assigned GPU name", 128
            ),
            unassigned_gpu_uuid=_text(
                row["unassigned_gpu_uuid"],
                "preflight unassigned GPU UUID",
                128,
            ),
            unassigned_gpu_name=_text(
                row["unassigned_gpu_name"],
                "preflight unassigned GPU name",
                128,
            ),
            unassigned_compute_processes=_integer(
                row["unassigned_compute_processes"],
                "preflight unassigned GPU processes",
                minimum=0,
            ),
            logical_device_count=_integer(
                row["logical_device_count"],
                "preflight logical device count",
                minimum=0,
            ),
            logical_device_index=_integer(
                row["logical_device_index"],
                "preflight logical device index",
                minimum=0,
            ),
            host_boundary_ref=_ref(
                row["host_boundary_ref"], "preflight host boundary ref"
            ),
            host_closure_ref=_ref(
                row["host_closure_ref"], "preflight host closure ref"
            ),
            _host_closure_json=canonical_json_bytes(
                _canonical_mapping(row["host_closure"], "preflight host closure")
            ),
            verification_durations_ns=tuple(row["verification_durations_ns"]),
            maximum_duration_ns=_integer(
                row["maximum_duration_ns"],
                "preflight maximum duration",
                minimum=1,
            ),
            vm_locked_bytes_before=_integer(
                row["vm_locked_bytes_before"],
                "preflight locked bytes",
                minimum=0,
            ),
            memlock_soft_limit_bytes=row["memlock_soft_limit_bytes"],
            rss_bytes_before=_integer(
                row["rss_bytes_before"], "preflight RSS", minimum=0
            ),
            rss_reservation_bytes=_integer(
                row["rss_reservation_bytes"],
                "preflight RSS reservation",
                minimum=0,
            ),
            allocator_baseline=_validated_pinned_allocator_snapshot(
                row["allocator_baseline"], "preflight allocator baseline"
            ),
            allocator_post_allocation=_validated_pinned_allocator_snapshot(
                row["allocator_post_allocation"],
                "preflight allocator post-allocation",
            ),
            allocator_cleanup=_validated_pinned_allocator_snapshot(
                row["allocator_cleanup"], "preflight allocator cleanup"
            ),
        )
        without_ref = dict(row)
        observed_ref = without_ref.pop("preflight_ref")
        if observed_ref != canonical_ref("foundation-mirror-preflight", without_ref):
            raise V2IntegrityStop("foundation preflight ref differs")
        if receipt.to_canonical() != row:
            raise V2IntegrityStop("foundation preflight canonical bytes differ")
        return receipt

    def to_canonical(self) -> dict[str, object]:
        payload = {
            "accepted_design_sha256": ACCEPTED_DESIGN_SHA256,
            "assigned_gpu_name": self.assigned_gpu_name,
            "assigned_gpu_uuid": self.assigned_gpu_uuid,
            "allocator_baseline": _pinned_allocator_snapshot_canonical(
                self.allocator_baseline
            ),
            "allocator_cleanup": _pinned_allocator_snapshot_canonical(
                self.allocator_cleanup
            ),
            "allocator_post_allocation": _pinned_allocator_snapshot_canonical(
                self.allocator_post_allocation
            ),
            "authorized_leaf_sha256": CURRENT_AUTHORIZED_LEAF_SHA256,
            "cleanup_proven": True,
            "environment_sha256": self.environment_sha256,
            "host_boundary_ref": self.host_boundary_ref,
            "host_closure": json.loads(self._host_closure_json.decode("utf-8")),
            "host_closure_ref": self.host_closure_ref,
            "hostname": self.hostname,
            "largest_parameter_bytes": QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES,
            "maximum_duration_ns": self.maximum_duration_ns,
            "maximum_verification_ns": FOUNDATION_MIRROR_MAXIMUM_VERIFICATION_NS,
            "memlock_soft_limit_bytes": self.memlock_soft_limit_bytes,
            "model_ref": QUALIFIED_MODEL_REF,
            "mount_namespace": self.mount_namespace,
            "namespace_boundary_ref": self.namespace_boundary_ref,
            "namespace_proof": json.loads(
                self._namespace_proof_json.decode("utf-8")
            ),
            "network_namespace": self.network_namespace,
            "parameter_bytes": QUALIFIED_MODEL_PARAMETER_BYTES,
            "parameter_count": QUALIFIED_MODEL_PARAMETER_COUNT,
            "performance_gate_passed": True,
            "pinned_bytes": FOUNDATION_MIRROR_PINNED_BYTES,
            "pinned_slot_bytes": FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
            "pinned_slot_count": FOUNDATION_MIRROR_PINNED_SLOT_COUNT,
            "protocol_identity": PROTOCOL_IDENTITY,
            "python": self.python,
            "python_executable": self.python_executable,
            "rss_bytes_before": self.rss_bytes_before,
            "rss_reservation_bytes": self.rss_reservation_bytes,
            "schema": FOUNDATION_MIRROR_PREFLIGHT_SCHEMA,
            "source_count": self.source_count,
            "source_inventory_ref": self.source_inventory_ref,
            "tokenizer_ref": QUALIFIED_TOKENIZER_REF,
            "unassigned_compute_processes": self.unassigned_compute_processes,
            "unassigned_gpu_name": self.unassigned_gpu_name,
            "unassigned_gpu_uuid": self.unassigned_gpu_uuid,
            "logical_device_count": self.logical_device_count,
            "logical_device_index": self.logical_device_index,
            "verification_durations_ns": list(self.verification_durations_ns),
            "vm_locked_bytes_before": self.vm_locked_bytes_before,
        }
        return {
            **payload,
            "preflight_ref": canonical_ref(
                "foundation-mirror-preflight", payload
            ),
        }


def _foundation_mirror_chunk_plan(
    byte_counts: Sequence[int],
) -> tuple[_FoundationMirrorChunk, ...]:
    counts = tuple(byte_counts)
    if not counts or any(type(value) is not int or value < 1 for value in counts):
        raise ValueError("foundation mirror byte counts differ")
    total = sum(counts)
    row_index = 0
    row_offset = 0
    global_offset = 0
    chunks: list[_FoundationMirrorChunk] = []
    while global_offset < total:
        chunk_length = min(
            FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
            total - global_offset,
        )
        slot_offset = 0
        segments: list[_FoundationMirrorSegment] = []
        while slot_offset < chunk_length:
            if row_index >= len(counts):
                raise V2IntegrityStop("foundation mirror plan ended early")
            available = counts[row_index] - row_offset
            length = min(available, chunk_length - slot_offset)
            segments.append(
                _FoundationMirrorSegment(
                    row_index=row_index,
                    row_offset=row_offset,
                    slot_offset=slot_offset,
                    length=length,
                )
            )
            slot_offset += length
            row_offset += length
            if row_offset == counts[row_index]:
                row_index += 1
                row_offset = 0
        chunks.append(
            _FoundationMirrorChunk(
                global_offset=global_offset,
                length=chunk_length,
                segments=tuple(segments),
            )
        )
        global_offset += chunk_length
    plan = tuple(chunks)
    _validate_foundation_mirror_chunk_plan(plan, counts)
    return plan


def _validate_foundation_mirror_chunk_plan(
    plan: Sequence[_FoundationMirrorChunk],
    byte_counts: Sequence[int],
) -> None:
    chunks = tuple(plan)
    counts = tuple(byte_counts)
    if not chunks or not counts:
        raise V2IntegrityStop("foundation mirror plan is empty")
    total = sum(counts)
    expected_chunk_count = math.ceil(
        total / FOUNDATION_MIRROR_PINNED_SLOT_BYTES
    )
    if len(chunks) != expected_chunk_count:
        raise V2IntegrityStop("foundation mirror chunk count differs")
    global_cursor = 0
    row_cursor = 0
    row_offsets = [0 for _ in counts]
    for chunk in chunks:
        if type(chunk) is not _FoundationMirrorChunk:
            raise V2IntegrityStop("foundation mirror chunk type differs")
        expected_length = min(
            FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
            total - global_cursor,
        )
        if (
            chunk.global_offset != global_cursor
            or chunk.length != expected_length
        ):
            raise V2IntegrityStop("foundation mirror chunk coverage differs")
        slot_cursor = 0
        for segment in chunk.segments:
            while (
                row_cursor < len(counts)
                and row_offsets[row_cursor] == counts[row_cursor]
            ):
                row_cursor += 1
            if (
                row_cursor >= len(counts)
                or segment.row_index != row_cursor
                or segment.row_offset != row_offsets[row_cursor]
                or segment.slot_offset != slot_cursor
                or segment.length
                > counts[row_cursor] - row_offsets[row_cursor]
                or segment.length > chunk.length - slot_cursor
            ):
                raise V2IntegrityStop("foundation mirror segment coverage differs")
            row_offsets[row_cursor] += segment.length
            slot_cursor += segment.length
        if slot_cursor != chunk.length:
            raise V2IntegrityStop("foundation mirror slot coverage differs")
        global_cursor += chunk.length
    if global_cursor != total or tuple(row_offsets) != counts:
        raise V2IntegrityStop("foundation mirror total coverage differs")


def _foundation_mirror_vm_locked_bytes() -> int:
    try:
        lines = Path("/proc/self/status").read_text(encoding="ascii").splitlines()
    except OSError as error:
        raise V2IntegrityStop("foundation mirror VmLck is unavailable") from error
    values = []
    for line in lines:
        match = re.fullmatch(r"VmLck:\s+([0-9]+)\s+kB", line)
        if match is not None:
            values.append(int(match.group(1)) * 1024)
    if len(values) != 1:
        raise V2IntegrityStop("foundation mirror VmLck differs")
    return values[0]


def _foundation_mirror_memlock_precheck() -> tuple[int, int]:
    locked = _foundation_mirror_vm_locked_bytes()
    try:
        soft, _hard = resource.getrlimit(resource.RLIMIT_MEMLOCK)
    except (OSError, ValueError) as error:
        raise V2IntegrityStop("foundation mirror memlock limit is unavailable") from error
    if type(soft) is not int:
        raise V2IntegrityStop("foundation mirror memlock limit differs")
    if soft != resource.RLIM_INFINITY and (
        soft < locked or soft - locked < FOUNDATION_MIRROR_PINNED_BYTES
    ):
        raise V2IntegrityStop("foundation mirror memlock reservation is unavailable")
    return locked, soft


def _foundation_mirror_allocator_snapshot(
    torch_module: object,
) -> _PinnedAllocatorSnapshot:
    try:
        stats = getattr(torch_module, "cuda").host_memory_stats()
    except BaseException as error:
        raise V2IntegrityStop(
            "foundation pinned allocator statistics are unavailable"
        ) from error
    if not isinstance(stats, Mapping):
        raise V2IntegrityStop("foundation pinned allocator statistics differ")
    keys = (
        "allocations.current",
        "allocated_bytes.current",
        "active_requests.current",
        "active_bytes.current",
    )
    values = tuple(stats.get(key) for key in keys)
    if any(type(value) is not int or value < 0 for value in values):
        raise V2IntegrityStop("foundation pinned allocator counters differ")
    return _PinnedAllocatorSnapshot(*values)


def _foundation_mirror_digest(
    rows: Sequence[_FoundationByteMirrorRow],
) -> str:
    frozen = tuple(rows)
    digest = hashlib.sha256()
    digest.update(_FOUNDATION_MIRROR_DIGEST_DOMAIN)
    digest.update(struct.pack(">Q", len(frozen)))
    for row in frozen:
        encoded_dtype = row.dtype.encode("ascii")
        digest.update(struct.pack(">Q", len(encoded_dtype)))
        digest.update(encoded_dtype)
        digest.update(struct.pack(">Q", len(row.shape)))
        for dimension in row.shape:
            digest.update(struct.pack(">Q", dimension))
        digest.update(struct.pack(">Q", len(row.raw)))
        digest.update(row.raw)
    return "sha256:" + digest.hexdigest()


def _foundation_mirror_uninitialized_bytes(length: int) -> bytes:
    """Allocate one CPython bytes payload for private fill before publication."""

    if (
        type(length) is not int
        or length < 1
        or platform.python_implementation() != "CPython"
        or sys.version_info[:3] != (3, 12, 3)
    ):
        raise V2IntegrityStop("foundation mirror canonical allocation differs")
    constructor = ctypes.pythonapi.PyBytes_FromStringAndSize
    constructor.argtypes = (ctypes.c_void_p, ctypes.c_ssize_t)
    constructor.restype = ctypes.py_object
    value = constructor(None, length)
    if type(value) is not bytes or len(value) != length:
        raise V2IntegrityStop("foundation mirror canonical allocation differs")
    return value


def _foundation_mirror_slot_region(
    slot: object,
    *,
    slot_offset: int,
    length: int,
) -> int:
    """Validate one exact pinned slot region immediately before native access."""

    import torch

    if (
        type(slot_offset) is not int
        or slot_offset < 0
        or type(length) is not int
        or length < 1
    ):
        raise V2IntegrityStop("foundation mirror pinned region differs")
    try:
        numel = slot.numel()
        nbytes = slot.nbytes
        pointer = slot.data_ptr()
        valid = (
            slot.dtype is torch.uint8
            and slot.device.type == "cpu"
            and slot.is_contiguous() is True
            and slot.is_pinned() is True
            and type(numel) is int
            and numel == FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            and type(nbytes) is int
            and nbytes == FOUNDATION_MIRROR_PINNED_SLOT_BYTES
            and type(pointer) is int
            and pointer > 0
        )
    except (AttributeError, RuntimeError, TypeError, ValueError) as error:
        raise V2IntegrityStop("foundation mirror pinned slot differs") from error
    if (
        not valid
        or slot_offset > FOUNDATION_MIRROR_PINNED_SLOT_BYTES
        or length > FOUNDATION_MIRROR_PINNED_SLOT_BYTES - slot_offset
    ):
        raise V2IntegrityStop("foundation mirror pinned region differs")
    return pointer


def _foundation_mirror_fill_bytes_from_slot(
    *,
    raw: bytes,
    row_offset: int,
    slot: object,
    slot_offset: int,
    length: int,
) -> None:
    if (
        type(raw) is not bytes
        or type(row_offset) is not int
        or row_offset < 0
        or type(slot_offset) is not int
        or slot_offset < 0
        or type(length) is not int
        or length < 1
        or row_offset + length > len(raw)
    ):
        raise V2IntegrityStop("foundation mirror canonical fill differs")
    pointer = ctypes.pythonapi.PyBytes_AsString
    pointer.argtypes = (ctypes.py_object,)
    pointer.restype = ctypes.c_void_p
    destination = pointer(raw)
    source = _foundation_mirror_slot_region(
        slot,
        slot_offset=slot_offset,
        length=length,
    )
    if (
        type(destination) is not int
        or destination < 1
        or source < 1
    ):
        raise V2IntegrityStop("foundation mirror canonical address differs")
    ctypes.memmove(
        destination + row_offset,
        source + slot_offset,
        length,
    )


_FOUNDATION_MIRROR_MEMCMP = ctypes.CDLL(None).memcmp
_FOUNDATION_MIRROR_MEMCMP.argtypes = (
    ctypes.c_void_p,
    ctypes.c_void_p,
    ctypes.c_size_t,
)
_FOUNDATION_MIRROR_MEMCMP.restype = ctypes.c_int


def _foundation_mirror_slot_matches_bytes(
    *,
    slot: object,
    slot_offset: int,
    raw: bytes,
    row_offset: int,
    length: int,
) -> bool:
    if (
        type(raw) is not bytes
        or type(slot_offset) is not int
        or slot_offset < 0
        or type(row_offset) is not int
        or row_offset < 0
        or type(length) is not int
        or length < 1
        or row_offset + length > len(raw)
    ):
        raise V2IntegrityStop("foundation mirror raw comparison differs")
    pointer = ctypes.pythonapi.PyBytes_AsString
    pointer.argtypes = (ctypes.py_object,)
    pointer.restype = ctypes.c_void_p
    expected = pointer(raw)
    observed = _foundation_mirror_slot_region(
        slot,
        slot_offset=slot_offset,
        length=length,
    )
    if (
        type(expected) is not int
        or expected < 1
        or observed < 1
    ):
        raise V2IntegrityStop("foundation mirror comparison address differs")
    return (
        _FOUNDATION_MIRROR_MEMCMP(
            observed + slot_offset,
            expected + row_offset,
            length,
        )
        == 0
    )


def _current_process_rss_bytes() -> int:
    try:
        fields = Path("/proc/self/statm").read_text(encoding="ascii").split()
        pages = int(fields[1])
        page_size = int(os.sysconf("SC_PAGE_SIZE"))
    except (IndexError, OSError, TypeError, ValueError) as error:
        raise V2IntegrityStop("current RSS is unavailable") from error
    if pages < 0 or page_size < 1:
        raise V2IntegrityStop("current RSS differs")
    return pages * page_size


def _peak_process_rss_bytes() -> int:
    observed = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    if type(observed) is not int or observed < 0:
        raise V2IntegrityStop("peak RSS is unavailable")
    return observed * 1024


class _ExactFoundationByteMirror:
    """Two-slot pinned exact mirror for collision-free CUDA pre-call scans."""

    def __init__(
        self,
        model: object,
        *,
        foundation_guard: object,
        expected_digest: str,
        resources: ResourceLedger,
    ) -> None:
        import torch

        if type(resources) is not ResourceLedger:
            raise TypeError("foundation mirror resource ledger differs")
        if any(
            not callable(value)
            for value in (
                getattr(model, "named_parameters", None),
                getattr(model, "parameters", None),
                getattr(foundation_guard, "probe", None),
                getattr(foundation_guard, "verify_boundary_digest", None),
            )
        ):
            raise TypeError("foundation mirror owner boundary is incomplete")
        self._lock = threading.Lock()
        self._owner_thread_id = threading.get_ident()
        self._model = model
        self._foundation_guard = foundation_guard
        self._resources: ResourceLedger | None = resources
        self._expected_digest = _ref(
            expected_digest, "foundation mirror digest"
        )
        self._torch_module: object | None = torch
        self._device: object | None = None
        self._rows: tuple[_FoundationByteMirrorRow, ...] = ()
        self._byte_counts: tuple[int, ...] = ()
        self._plan: tuple[_FoundationMirrorChunk, ...] = ()
        self._slots: tuple[object, ...] = ()
        self._events: tuple[object, ...] = ()
        self._copy_stream: object | None = None
        self._stream_may_have_work = False
        self._allocator_baseline: _PinnedAllocatorSnapshot | None = None
        self._allocator_post_allocation: _PinnedAllocatorSnapshot | None = None
        self._allocator_cleanup: _PinnedAllocatorSnapshot | None = None
        self._vm_locked_bytes_before = 0
        self._memlock_soft_limit_bytes = 0
        self._rss_bytes_before = 0
        self._rss_reservation_bytes = 0
        self._verification_durations_ns: list[int] = []
        self._performance_gate_passed = False
        self._poisoned = False
        self._resources_released = False
        self._cleanup_proven = False
        self._closed = False
        primary: V2IntegrityStop | None = None
        cleanup_failure: V2IntegrityStop | None = None
        try:
            self._capture_exact_canonical_rows(resources)
            return
        except BaseException as error:
            self._poisoned = True
            primary = _redacted_failure(
                error, "FOUNDATION_MIRROR_CONSTRUCTION_FAILED"
            )
        finally:
            model = None
            foundation_guard = None
            resources = None
        try:
            self.close()
        except BaseException as error:
            cleanup_failure = _redacted_failure(
                error, "FOUNDATION_MIRROR_CONSTRUCTION_CLEANUP_FAILED"
            )
        error = None
        if cleanup_failure is not None:
            raise ExceptionGroup(
                "foundation mirror construction and cleanup failed",
                [primary, cleanup_failure],
            ) from None
        raise primary from None

    @staticmethod
    def _parameter_metadata(
        torch_module: object,
        named: Sequence[tuple[str, object]],
        positional: Sequence[object],
    ) -> tuple[tuple[int, ...], object]:
        frozen_named = tuple(named)
        frozen_positional = tuple(positional)
        if (
            len(frozen_named) != QUALIFIED_MODEL_PARAMETER_COUNT
            or len(frozen_named) != len(frozen_positional)
            or any(
                type(item) is not tuple
                or len(item) != 2
                or type(item[0]) is not str
                or item[1] is not frozen_positional[index]
                for index, item in enumerate(frozen_named)
            )
        ):
            raise V2IntegrityStop("foundation mirror parameter order differs")
        cuda = getattr(torch_module, "cuda")
        if (
            cuda.is_available() is not True
            or int(cuda.device_count()) != 1
            or int(cuda.current_device()) != 0
        ):
            raise V2IntegrityStop("foundation mirror CUDA assignment differs")
        byte_counts: list[int] = []
        device: object | None = None
        for _name, parameter in frozen_named:
            try:
                count = int(parameter.numel()) * int(parameter.element_size())
                contiguous = parameter.is_contiguous()
                layout = parameter.layout
                observed_device = parameter.device
                device_type = observed_device.type
                device_index = observed_device.index
            except (AttributeError, RuntimeError, TypeError, ValueError) as error:
                raise V2IntegrityStop(
                    "foundation mirror parameter metadata differs"
                ) from error
            if (
                count < 1
                or contiguous is not True
                or layout is not getattr(torch_module, "strided")
                or device_type != "cuda"
                or device_index != 0
                or (device is not None and observed_device != device)
            ):
                raise V2IntegrityStop(
                    "foundation mirror parameter layout/device differs"
                )
            if device is None:
                device = observed_device
            byte_counts.append(count)
        counts = tuple(byte_counts)
        if (
            len(counts) != QUALIFIED_MODEL_PARAMETER_COUNT
            or sum(counts) != QUALIFIED_MODEL_PARAMETER_BYTES
            or max(counts) != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
            or max(counts) > FOUNDATION_MIRROR_PINNED_SLOT_BYTES
        ):
            raise V2IntegrityStop("foundation mirror parameter inventory differs")
        return counts, device

    @staticmethod
    def _validate_slot(torch_module: object, slot: object) -> int:
        if getattr(torch_module, "uint8", None) is not getattr(slot, "dtype", None):
            raise V2IntegrityStop("foundation mirror pinned slot differs")
        return _foundation_mirror_slot_region(
            slot,
            slot_offset=0,
            length=FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
        )

    def _assert_owned_allocator_delta(self) -> _PinnedAllocatorSnapshot:
        if self._allocator_baseline is None or self._torch_module is None:
            raise V2IntegrityStop("foundation pinned allocator baseline is absent")
        observed = _foundation_mirror_allocator_snapshot(self._torch_module)
        if (
            observed.active_requests_current
            != self._allocator_baseline.active_requests_current
            + FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            or observed.active_bytes_current
            != self._allocator_baseline.active_bytes_current
            + FOUNDATION_MIRROR_PINNED_BYTES
        ):
            raise V2IntegrityStop(
                "foundation mirror owned pinned allocation differs"
            )
        return observed

    def _begin_copy_dependency(self) -> None:
        torch_module = self._torch_module
        if (
            torch_module is None
            or self._device is None
            or self._copy_stream is None
            or len(self._events) != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
        ):
            raise V2IntegrityStop("foundation mirror copy boundary is absent")
        current_stream = torch_module.cuda.current_stream(device=self._device)
        self._stream_may_have_work = True
        self._events[0].record(current_stream)
        self._copy_stream.wait_event(self._events[0])

    def _capture_exact_canonical_rows(self, resources: ResourceLedger) -> None:
        torch_module = self._torch_module
        if (
            self._foundation_guard.verify_boundary_digest()
            != self._expected_digest
        ):
            raise V2IntegrityStop("foundation changed before mirror capture")
        named = tuple(self._model.named_parameters())
        positional = tuple(self._model.parameters())
        byte_counts, device = self._parameter_metadata(
            torch_module, named, positional
        )
        self._device = device
        self._byte_counts = byte_counts
        self._plan = _foundation_mirror_chunk_plan(byte_counts)
        self._vm_locked_bytes_before, self._memlock_soft_limit_bytes = (
            _foundation_mirror_memlock_precheck()
        )
        self._rss_bytes_before = _current_process_rss_bytes()
        self._rss_reservation_bytes = (
            self._rss_bytes_before
            + QUALIFIED_MODEL_PARAMETER_BYTES
            + FOUNDATION_MIRROR_PINNED_BYTES
            + FOUNDATION_MIRROR_TRANSIENT_BYTES
        )
        if self._rss_reservation_bytes > resources.ceilings.maximum_rss_bytes:
            raise V2IntegrityStop(
                "foundation mirror RSS reservation exceeds ceiling"
            )
        self._allocator_baseline = _foundation_mirror_allocator_snapshot(
            torch_module
        )
        slots: list[object] = []
        try:
            for _ in range(FOUNDATION_MIRROR_PINNED_SLOT_COUNT):
                slots.append(
                    torch_module.empty(
                        FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
                        dtype=torch_module.uint8,
                        device="cpu",
                        pin_memory=True,
                    )
                )
                self._slots = tuple(slots)
        finally:
            self._slots = tuple(slots)
        if len(self._slots) != FOUNDATION_MIRROR_PINNED_SLOT_COUNT:
            raise V2IntegrityStop("foundation mirror pinned slot count differs")
        slot_pointers = tuple(
            self._validate_slot(torch_module, slot) for slot in self._slots
        )
        slot_intervals = tuple(
            (
                pointer,
                pointer + FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
            )
            for pointer in slot_pointers
        )
        if any(
            left_start < right_end and right_start < left_end
            for index, (left_start, left_end) in enumerate(slot_intervals)
            for right_start, right_end in slot_intervals[index + 1 :]
        ):
            raise V2IntegrityStop("foundation mirror pinned slots alias")
        self._allocator_post_allocation = self._assert_owned_allocator_delta()
        self._copy_stream = torch_module.cuda.Stream(device=self._device)
        self._events = tuple(
            torch_module.cuda.Event(
                enable_timing=False,
                blocking=False,
                interprocess=False,
            )
            for _ in range(FOUNDATION_MIRROR_PINNED_SLOT_COUNT)
        )
        self._begin_copy_dependency()
        raw_buffers = tuple(
            _foundation_mirror_uninitialized_bytes(byte_count)
            for byte_count in byte_counts
        )
        pending: list[tuple[int, _FoundationMirrorChunk] | None] = [
            None for _ in range(FOUNDATION_MIRROR_PINNED_SLOT_COUNT)
        ]

        def drain(slot_index: int) -> None:
            item = pending[slot_index]
            if item is None:
                return
            _ordinal, chunk = item
            self._events[slot_index].synchronize()
            slot = self._slots[slot_index]
            for segment in chunk.segments:
                _foundation_mirror_fill_bytes_from_slot(
                    raw=raw_buffers[segment.row_index],
                    row_offset=segment.row_offset,
                    slot=slot,
                    slot_offset=segment.slot_offset,
                    length=segment.length,
                )
            pending[slot_index] = None

        parameters = tuple(parameter for _name, parameter in named)
        for ordinal, chunk in enumerate(self._plan):
            slot_index = ordinal % FOUNDATION_MIRROR_PINNED_SLOT_COUNT
            drain(slot_index)
            self._enqueue_verification_chunk(
                chunk,
                parameters,
                slot_index,
            )
            pending[slot_index] = (ordinal, chunk)
        for slot_index, _item in sorted(
            enumerate(pending),
            key=lambda pair: (
                pair[1][0] if pair[1] is not None else len(self._plan)
            ),
        ):
            drain(slot_index)
        self._stream_may_have_work = False
        self._rows = tuple(
            _FoundationByteMirrorRow(
                name=name,
                shape=tuple(int(value) for value in parameter.shape),
                dtype=str(parameter.dtype),
                raw=raw,
            )
            for (name, parameter), raw in zip(
                named, raw_buffers, strict=True
            )
        )
        if _foundation_mirror_digest(self._rows) != self._expected_digest:
            raise V2IntegrityStop(
                "foundation mirror digest differs from qualified foundation"
            )
        if (
            self._foundation_guard.verify_boundary_digest()
            != self._expected_digest
        ):
            raise V2IntegrityStop("foundation changed during mirror capture")
        self._allocator_post_allocation = self._assert_owned_allocator_delta()
        if _current_process_rss_bytes() > resources.ceilings.maximum_rss_bytes:
            raise V2IntegrityStop("foundation mirror RSS ceiling exceeded")
        resources.record_rss_peak(_peak_process_rss_bytes())
        named = ()
        positional = ()
        parameters = ()
        raw_buffers = ()
        pending.clear()

    def _validated_live_parameters(
        self,
    ) -> tuple[tuple[tuple[str, object], ...], tuple[object, ...]]:
        if self._model is None or self._torch_module is None:
            raise V2IntegrityStop("foundation mirror model is absent")
        named = tuple(self._model.named_parameters())
        positional = tuple(self._model.parameters())
        byte_counts, device = self._parameter_metadata(
            self._torch_module, named, positional
        )
        if (
            byte_counts != self._byte_counts
            or device != self._device
            or len(named) != len(self._rows)
        ):
            raise V2IntegrityStop("foundation mirror population changed")
        for (name, parameter), expected, byte_count in zip(
            named, self._rows, byte_counts, strict=True
        ):
            if (
                name != expected.name
                or tuple(int(value) for value in parameter.shape)
                != expected.shape
                or str(parameter.dtype) != expected.dtype
                or parameter.is_contiguous() is not True
                or byte_count != len(expected.raw)
            ):
                raise V2IntegrityStop("foundation mirror metadata differs")
        _validate_foundation_mirror_chunk_plan(self._plan, byte_counts)
        return named, positional

    def _enqueue_verification_chunk(
        self,
        chunk: _FoundationMirrorChunk,
        parameters: Sequence[object],
        slot_index: int,
    ) -> None:
        torch_module = self._torch_module
        slot = self._slots[slot_index]
        event = self._events[slot_index]
        self._stream_may_have_work = True
        with torch_module.cuda.stream(self._copy_stream):
            for segment in chunk.segments:
                source = (
                    parameters[segment.row_index]
                    .detach()
                    .reshape(-1)
                    .view(torch_module.uint8)
                )
                if int(source.numel()) != self._byte_counts[segment.row_index]:
                    raise V2IntegrityStop(
                        "foundation mirror parameter byte count changed"
                    )
                slot.narrow(
                    0, segment.slot_offset, segment.length
                ).copy_(
                    source.narrow(
                        0, segment.row_offset, segment.length
                    ),
                    non_blocking=True,
                )
                source = None
            event.record(self._copy_stream)

    def _compare_verification_chunk(
        self,
        chunk: _FoundationMirrorChunk,
        slot_index: int,
    ) -> None:
        self._events[slot_index].synchronize()
        slot = self._slots[slot_index]
        for segment in chunk.segments:
            if not _foundation_mirror_slot_matches_bytes(
                slot=slot,
                slot_offset=segment.slot_offset,
                raw=self._rows[segment.row_index].raw,
                row_offset=segment.row_offset,
                length=segment.length,
            ):
                raise V2IntegrityStop("foundation parameter bytes changed")

    def _verify_final_parameter_identity(
        self,
        initial_named: Sequence[tuple[str, object]],
    ) -> None:
        final_named, _final_positional = self._validated_live_parameters()
        if len(final_named) != len(initial_named) or any(
            final_name != initial_name or final_parameter is not initial_parameter
            for (final_name, final_parameter), (
                initial_name,
                initial_parameter,
            ) in zip(final_named, initial_named, strict=True)
        ):
            raise V2IntegrityStop("foundation mirror parameter identity changed")

    def verify_exact(self) -> str:
        named: tuple[tuple[str, object], ...] = ()
        positional: tuple[object, ...] = ()
        parameters: tuple[object, ...] = ()
        pending: list[tuple[int, _FoundationMirrorChunk] | None] = []
        if self._closed:
            raise V2IntegrityStop("foundation mirror ownership differs")
        if self._poisoned:
            raise V2IntegrityStop("foundation mirror is terminally poisoned")
        if threading.get_ident() != self._owner_thread_id:
            self._poisoned = True
            raise V2IntegrityStop("foundation mirror ownership differs")
        if not self._lock.acquire(blocking=False):
            self._poisoned = True
            raise V2IntegrityStop("foundation mirror ownership differs")
        try:
            started_ns = time.perf_counter_ns()
            if self._poisoned or self._resources_released:
                raise V2IntegrityStop("foundation mirror is terminally poisoned")
            if _current_process_rss_bytes() > MAXIMUM_RSS_BYTES:
                raise V2IntegrityStop("foundation mirror RSS ceiling exceeded")
            if self._foundation_guard.probe() != self._expected_digest:
                raise V2IntegrityStop("foundation mirror metadata changed")
            self._assert_owned_allocator_delta()
            named, positional = self._validated_live_parameters()
            parameters = tuple(parameter for _name, parameter in named)
            self._begin_copy_dependency()
            pending = [
                None for _ in range(FOUNDATION_MIRROR_PINNED_SLOT_COUNT)
            ]
            for ordinal, chunk in enumerate(self._plan):
                slot_index = ordinal % FOUNDATION_MIRROR_PINNED_SLOT_COUNT
                prior = pending[slot_index]
                if prior is not None:
                    self._compare_verification_chunk(prior[1], slot_index)
                    pending[slot_index] = None
                self._enqueue_verification_chunk(
                    chunk, parameters, slot_index
                )
                pending[slot_index] = (ordinal, chunk)
            for slot_index, item in sorted(
                enumerate(pending),
                key=lambda pair: (
                    pair[1][0]
                    if pair[1] is not None
                    else len(self._plan)
                ),
            ):
                if item is not None:
                    self._compare_verification_chunk(item[1], slot_index)
                    pending[slot_index] = None
            self._stream_may_have_work = False
            self._verify_final_parameter_identity(named)
            if self._foundation_guard.probe() != self._expected_digest:
                raise V2IntegrityStop("foundation mirror metadata changed")
            self._assert_owned_allocator_delta()
            if _current_process_rss_bytes() > MAXIMUM_RSS_BYTES:
                raise V2IntegrityStop("foundation mirror RSS ceiling exceeded")
            if self._resources is None:
                raise V2IntegrityStop("foundation mirror resource ledger is absent")
            self._resources.record_rss_peak(_peak_process_rss_bytes())
            if self._poisoned:
                raise V2IntegrityStop("foundation mirror is terminally poisoned")
            duration_ns = time.perf_counter_ns() - started_ns
            if duration_ns < 1:
                raise V2IntegrityStop("foundation mirror duration differs")
            self._verification_durations_ns.append(duration_ns)
            return self._expected_digest
        except BaseException as error:
            self._poisoned = True
            code = (
                str(error)
                if type(error) is V2IntegrityStop
                else "FOUNDATION_MIRROR_VERIFICATION_FAILED"
            )
            safe = _redacted_failure(error, code)
            error = None
            named = ()
            positional = ()
            parameters = ()
            pending.clear()
            raise safe from None
        finally:
            self._lock.release()

    def assert_first_three_performance_gate(self) -> tuple[int, int, int]:
        if (
            self._closed
            or self._poisoned
            or threading.get_ident() != self._owner_thread_id
            or self._lock.locked()
        ):
            self._poisoned = True
            raise V2IntegrityStop(
                "foundation mirror performance gate is unavailable"
            )
        durations = tuple(self._verification_durations_ns)
        if len(durations) != 3:
            self._poisoned = True
            raise V2IntegrityStop(
                "foundation mirror performance sample count differs"
            )
        if max(durations) > FOUNDATION_MIRROR_MAXIMUM_VERIFICATION_NS:
            self._poisoned = True
            raise V2IntegrityStop("foundation mirror performance gate failed")
        self._performance_gate_passed = True
        return durations

    @property
    def audit_receipt(self) -> _FoundationMirrorAuditReceipt:
        if (
            self._allocator_baseline is None
            or self._allocator_post_allocation is None
        ):
            raise V2IntegrityStop("foundation mirror audit receipt is unavailable")
        return _FoundationMirrorAuditReceipt(
            parameter_count=QUALIFIED_MODEL_PARAMETER_COUNT,
            parameter_bytes=QUALIFIED_MODEL_PARAMETER_BYTES,
            largest_parameter_bytes=QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES,
            pinned_slot_count=FOUNDATION_MIRROR_PINNED_SLOT_COUNT,
            pinned_slot_bytes=FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
            pinned_bytes=FOUNDATION_MIRROR_PINNED_BYTES,
            vm_locked_bytes_before=self._vm_locked_bytes_before,
            memlock_soft_limit_bytes=self._memlock_soft_limit_bytes,
            rss_bytes_before=self._rss_bytes_before,
            rss_reservation_bytes=self._rss_reservation_bytes,
            allocator_baseline=self._allocator_baseline,
            allocator_post_allocation=self._allocator_post_allocation,
            allocator_cleanup=self._allocator_cleanup,
            verification_durations_ns=tuple(
                self._verification_durations_ns
            ),
            performance_gate_passed=self._performance_gate_passed,
            poisoned=self._poisoned,
            closed=self._closed,
            cleanup_proven=self._cleanup_proven,
        )

    def close(self) -> None:
        if self._closed:
            return
        if threading.get_ident() != self._owner_thread_id:
            self._poisoned = True
            raise V2IntegrityStop("foundation mirror close owner differs")
        if not self._lock.acquire(blocking=False):
            self._poisoned = True
            raise V2IntegrityStop("foundation mirror close ownership differs")
        try:
            torch_module = self._torch_module
            if not self._resources_released:
                drain_failure: V2IntegrityStop | None = None
                try:
                    if (
                        self._stream_may_have_work
                        and self._copy_stream is not None
                    ):
                        self._copy_stream.synchronize()
                except BaseException as error:
                    self._poisoned = True
                    drain_failure = _redacted_cleanup_failure(
                        error, "FOUNDATION_MIRROR_CLOSE_DRAIN_FAILED"
                    )
                if drain_failure is not None:
                    raise drain_failure from None
                self._stream_may_have_work = False
                self._rows = ()
                self._plan = ()
                self._byte_counts = ()
                self._events = ()
                self._copy_stream = None
                self._slots = ()
                self._device = None
                self._model = None
                self._foundation_guard = None
                self._resources = None
                self._resources_released = True
            cleanup_failure: V2IntegrityStop | None = None
            try:
                gc.collect()
                if torch_module is not None:
                    torch_module.accelerator.empty_host_cache()
                gc.collect()
                if self._allocator_baseline is not None:
                    cleanup = _foundation_mirror_allocator_snapshot(
                        torch_module
                    )
                    if any(
                        observed > baseline
                        for observed, baseline in zip(
                            (
                                cleanup.allocations_current,
                                cleanup.allocated_bytes_current,
                                cleanup.active_requests_current,
                                cleanup.active_bytes_current,
                            ),
                            (
                                self._allocator_baseline.allocations_current,
                                self._allocator_baseline.allocated_bytes_current,
                                self._allocator_baseline.active_requests_current,
                                self._allocator_baseline.active_bytes_current,
                            ),
                            strict=True,
                        )
                    ):
                        raise V2IntegrityStop(
                            "foundation pinned allocator cleanup differs"
                        )
                    self._allocator_cleanup = cleanup
            except BaseException as error:
                self._poisoned = True
                cleanup_failure = _redacted_cleanup_failure(
                    error, "FOUNDATION_MIRROR_CLOSE_CLEANUP_FAILED"
                )
            if cleanup_failure is not None:
                raise cleanup_failure from None
            self._cleanup_proven = True
            self._closed = True
            self._torch_module = None
        finally:
            self._lock.release()


@dataclass(slots=True)
class _ActiveQwenCallContext:
    task_id: str
    arm: Arm
    stage_ref: str
    proposal_prompt_ref: str
    maximum_generation_calls: int
    maximum_embedding_rows: int
    generation_calls: int = 0
    embedding_rows: int = 0
    owner_thread_id: int = field(init=False)

    def __post_init__(self) -> None:
        self.owner_thread_id = threading.get_ident()
        _ref(self.task_id, "Qwen call-context task id")
        validate_arm(self.arm)
        _ref(self.stage_ref, "Qwen call-context stage ref")
        _ref(self.proposal_prompt_ref, "Qwen call-context proposal prompt ref")
        if self.maximum_generation_calls != 2:
            raise ValueError("Qwen call-context generation allowance differs")
        _integer(
            self.maximum_embedding_rows,
            "Qwen call-context embedding allowance",
            maximum=RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT,
        )
        expected_embedding_rows = (
            RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
            if self.arm in STATEFUL_ARMS
            else 0
        )
        if self.maximum_embedding_rows != expected_embedding_rows:
            raise ValueError("Qwen attempt runtime embedding allowance differs")


@dataclass(slots=True)
class _ActiveQwenPlanningContext:
    task_id: str
    planning_ref: str
    maximum_embedding_rows: int
    embedding_rows: int = 0
    owner_thread_id: int = field(init=False)

    def __post_init__(self) -> None:
        self.owner_thread_id = threading.get_ident()
        _ref(self.task_id, "Qwen planning-context task id")
        _ref(self.planning_ref, "Qwen planning-context ref")
        _integer(
            self.maximum_embedding_rows,
            "Qwen planning-context embedding allowance",
            minimum=1,
            maximum=MAXIMUM_EVALUATION_EMBEDDING_ROWS,
        )


class GuardedLocalQwenBoundary:
    """Instrument one exact LocalQwenIO instance at the final pre-call seam."""

    _INSTANCE_MARKER = "_angler_v2_guard_owner"

    def __init__(
        self,
        io: object,
        *,
        foundation_guard: object,
        expected_foundation_digest: str,
        resources: ResourceLedger,
        verify_source_seal: Callable[[], str],
        expected_source_seal_ref: str,
        sample_resources: Callable[[], Mapping[str, int]],
        probe_gpu: Callable[[], Mapping[str, object]],
        verify_exact_foundation: Callable[[], str] | None = None,
    ) -> None:
        from angler.runtime.situated_qwen import (
            FrozenQwenGenerationRecord,
            LocalQwenIO,
        )

        if type(io) is not LocalQwenIO:
            raise TypeError("guard requires one exact LocalQwenIO")
        if type(resources) is not ResourceLedger:
            raise TypeError("guard requires one exact V2 resource ledger")
        if any(
            not callable(value)
            for value in (
                getattr(foundation_guard, "probe", None),
                getattr(foundation_guard, "verify_boundary_digest", None),
                verify_source_seal,
                sample_resources,
                probe_gpu,
            )
        ):
            raise TypeError("Qwen pre-call guard boundary is incomplete")
        if verify_exact_foundation is None:
            verify_exact_foundation = foundation_guard.verify_boundary_digest
        if not callable(verify_exact_foundation):
            raise TypeError("exact foundation comparison boundary differs")
        instance_state = getattr(io, "__dict__", None)
        if type(instance_state) is not dict or any(
            name in instance_state
            for name in ("embed", "generate_record", self._INSTANCE_MARKER)
        ):
            raise V2IntegrityStop("LocalQwenIO methods are already shadowed")
        self.io = io
        self.foundation_guard = foundation_guard
        self.expected_foundation_digest = _ref(
            expected_foundation_digest, "guarded foundation digest"
        )
        self.resources = resources
        self.verify_source_seal = verify_source_seal
        self.expected_source_seal_ref = _ref(
            expected_source_seal_ref, "guarded source seal"
        )
        self.sample_resources = sample_resources
        self.probe_gpu = probe_gpu
        self._verify_exact_foundation = verify_exact_foundation
        self._generation_record_type = FrozenQwenGenerationRecord
        self._original_embed = io.embed
        self._original_generate_record = io.generate_record
        self._active: (
            _ActiveQwenCallContext | _ActiveQwenPlanningContext | None
        ) = None
        self._reserved_generation_calls = 0
        self._successful_generation_calls = 0
        self._reconciled_generation_calls = 0
        self._pending_generation_tokens: list[tuple[int, int]] = []
        self._poisoned = False
        self._closed = False
        if (
            io.generation_calls != 0
            or resources.generation_calls != 0
            or resources.embedding_rows != 0
            or resources.runtime_embedding_rows != 0
        ):
            raise V2IntegrityStop("Qwen/resource state was used before guard installation")
        resources._bind_generation_reconciler(self)
        setattr(io, self._INSTANCE_MARKER, self)
        setattr(io, "embed", self._guarded_embed)
        setattr(io, "generate_record", self._guarded_generate_record)
        try:
            self._pre_call_boundary()
        except BaseException:
            delattr(io, "embed")
            delattr(io, "generate_record")
            delattr(io, self._INSTANCE_MARKER)
            resources._unbind_generation_reconciler(self)
            raise

    def _validated_gpu_probe(self) -> dict[str, object]:
        value = dict(self.probe_gpu())
        expected_keys = {
            "assigned_name",
            "assigned_uuid",
            "logical_device_count",
            "logical_device_index",
            "unassigned_compute_processes",
            "unassigned_name",
            "unassigned_uuid",
        }
        if (
            set(value) != expected_keys
            or value["assigned_name"]
            != _frozen_manifest_gpu_assignment()["assigned_name"]
            or value["assigned_uuid"] != ASSIGNED_GPU_UUID
            or value["logical_device_count"] != 1
            or value["logical_device_index"] != 0
            or value["unassigned_compute_processes"] != 0
            or value["unassigned_name"]
            != _frozen_manifest_gpu_assignment()["unassigned_name"]
            or value["unassigned_uuid"] != UNASSIGNED_GPU_UUID
        ):
            raise V2IntegrityStop("Qwen pre-call GPU assignment differs")
        return value

    def _sample_resource_boundary(self) -> None:
        row = dict(self.sample_resources())
        expected = {
            "configured_pools",
            "cuda_allocated_bytes",
            "cuda_reserved_bytes",
            "process_count",
            "rss_bytes",
            "state_scratch_bytes",
        }
        if set(row) != expected:
            raise V2InvariantError("Qwen pre-call resource sample differs")
        self.resources.sample_boundary(**row)

    def _pre_call_boundary(self) -> None:
        if self._closed or self._poisoned:
            raise V2IntegrityStop("Qwen guard is closed")
        if self.verify_source_seal() != self.expected_source_seal_ref:
            raise V2IntegrityStop("Qwen pre-call source seal changed")
        self._validated_gpu_probe()
        self._sample_resource_boundary()
        if (
            self._verify_exact_foundation()
            != self.expected_foundation_digest
        ):
            raise V2IntegrityStop("Qwen pre-call foundation changed")

    def _post_call_metadata_boundary(self) -> None:
        if self.foundation_guard.probe() != self.expected_foundation_digest:
            raise V2IntegrityStop("Qwen post-call foundation metadata changed")

    def _post_context_boundary(self) -> None:
        if self.verify_source_seal() != self.expected_source_seal_ref:
            raise V2IntegrityStop("Qwen post-context source seal changed")
        self._post_call_metadata_boundary()
        self._validated_gpu_probe()
        self._sample_resource_boundary()

    def verify_phase_boundary(self) -> str:
        """Perform collision-free plus frozen-domain SHA checks between phases."""

        if self._closed or self._poisoned or self._active is not None:
            raise V2IntegrityStop("Qwen phase boundary is unavailable")
        try:
            self._assert_generation_accounting(None)
            if self.verify_source_seal() != self.expected_source_seal_ref:
                raise V2IntegrityStop("Qwen phase-boundary source seal changed")
            self._validated_gpu_probe()
            self._sample_resource_boundary()
            if (
                self._verify_exact_foundation()
                != self.expected_foundation_digest
                or self.foundation_guard.verify_boundary_digest()
                != self.expected_foundation_digest
            ):
                raise V2IntegrityStop("Qwen phase-boundary foundation changed")
            self.resources.record_rss_peak(_peak_process_rss_bytes())
            self._sample_resource_boundary()
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_PHASE_BOUNDARY_FAILED"
            ) from None
        return self.expected_foundation_digest

    def _poison(self, error: BaseException) -> None:
        self._poisoned = True
        if isinstance(error, V2IntegrityStop):
            return

    def _assert_generation_accounting(
        self,
        context: _ActiveQwenCallContext | _ActiveQwenPlanningContext | None,
    ) -> None:
        active_calls = (
            context.generation_calls
            if type(context) is _ActiveQwenCallContext
            else 0
        )
        if (
            self._reserved_generation_calls != self._successful_generation_calls
            or self._successful_generation_calls
            != self._reconciled_generation_calls + active_calls
            or len(self._pending_generation_tokens) != active_calls
            or self.resources.generation_calls != self._reconciled_generation_calls
            or self.io.generation_calls != self._successful_generation_calls
        ):
            raise V2IntegrityStop("Qwen generation accounting is not synchronized")

    def reconcile_generation(
        self, prompt_tokens: int, output_tokens: int
    ) -> None:
        if self._closed or self._poisoned or self._active is not None:
            if not self._closed:
                self._poisoned = True
            raise V2IntegrityStop("Qwen generation reconciliation phase differs")
        observed = (
            _integer(prompt_tokens, "reconciled prompt tokens", minimum=1, maximum=4096),
            _integer(
                output_tokens,
                "reconciled output tokens",
                minimum=1,
                maximum=MAXIMUM_OUTPUT_TOKENS,
            ),
        )
        if (
            not self._pending_generation_tokens
            or self._pending_generation_tokens[0] != observed
            or self.resources.generation_calls != self._reconciled_generation_calls
        ):
            self._poisoned = True
            raise V2IntegrityStop("Qwen generation token reconciliation differs")
        self._pending_generation_tokens.pop(0)
        self._reconciled_generation_calls += 1

    @contextmanager
    def attempt(
        self,
        *,
        task_id: str,
        arm: Arm,
        stage_ref: str,
        proposal_prompt_ref: str,
        maximum_generation_calls: int,
        maximum_embedding_rows: int,
    ) -> Iterable[None]:
        if self._closed or self._poisoned or self._active is not None:
            raise V2IntegrityStop("Qwen call context overlaps or follows close")
        try:
            self._assert_generation_accounting(None)
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_ATTEMPT_CONTEXT_FAILED"
            ) from None
        context = _ActiveQwenCallContext(
            task_id=task_id,
            arm=arm,
            stage_ref=stage_ref,
            proposal_prompt_ref=proposal_prompt_ref,
            maximum_generation_calls=maximum_generation_calls,
            maximum_embedding_rows=maximum_embedding_rows,
        )
        self._active = context
        try:
            yield
            if context.owner_thread_id != threading.get_ident():
                raise V2IntegrityStop("Qwen attempt thread ownership changed")
            if context.generation_calls not in (1, 2):
                raise V2IntegrityStop(
                    "Qwen attempt completed without proposal generation"
                )
            expected_embedding_rows = (
                RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
                if context.arm in STATEFUL_ARMS
                and context.generation_calls == 2
                else 0
            )
            if context.embedding_rows != expected_embedding_rows:
                raise V2IntegrityStop(
                    "Qwen attempt generation/runtime-embedding pair differs"
                )
            self._assert_generation_accounting(context)
            self._post_context_boundary()
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_ATTEMPT_CONTEXT_FAILED"
            ) from None
        finally:
            self._active = None

    @contextmanager
    def planning(
        self,
        *,
        task_id: str,
        planning_ref: str,
        maximum_embedding_rows: int,
    ) -> Iterable[None]:
        """Authorize only bounded task-agnostic history-ranking embeddings."""

        if self._closed or self._poisoned or self._active is not None:
            raise V2IntegrityStop("Qwen call context overlaps or follows close")
        try:
            self._assert_generation_accounting(None)
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_PLANNING_CONTEXT_FAILED"
            ) from None
        context = _ActiveQwenPlanningContext(
            task_id=task_id,
            planning_ref=planning_ref,
            maximum_embedding_rows=maximum_embedding_rows,
        )
        self._active = context
        try:
            yield
            if context.owner_thread_id != threading.get_ident():
                raise V2IntegrityStop("Qwen planning thread ownership changed")
            if context.embedding_rows < 1:
                raise V2IntegrityStop(
                    "Qwen planning completed without a ranking embedding"
                )
            self._assert_generation_accounting(context)
            self._post_context_boundary()
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_PLANNING_CONTEXT_FAILED"
            ) from None
        finally:
            self._active = None

    def _require_active_attempt(self) -> _ActiveQwenCallContext:
        if self._closed or self._poisoned or self._active is None:
            raise V2IntegrityStop("Qwen call occurred outside one active attempt")
        if type(self._active) is not _ActiveQwenCallContext:
            raise V2IntegrityStop("Qwen generation occurred during planning")
        if self._active.owner_thread_id != threading.get_ident():
            raise V2IntegrityStop("Qwen attempt thread ownership differs")
        return self._active

    def _require_active_embedding_context(
        self,
    ) -> _ActiveQwenCallContext | _ActiveQwenPlanningContext:
        if self._closed or self._poisoned or self._active is None:
            raise V2IntegrityStop(
                "Qwen call occurred outside one active attempt or planning context"
            )
        if self._active.owner_thread_id != threading.get_ident():
            raise V2IntegrityStop("Qwen embedding thread ownership differs")
        return self._active

    def _guarded_generate_record(self, prompt: str) -> object:
        try:
            context = self._require_active_attempt()
            prompt_ref = content_ref({"prompt": prompt})
            if (
                context.generation_calls == 0
                and prompt_ref != context.proposal_prompt_ref
            ):
                raise V2IntegrityStop(
                    "Qwen proposal prompt differs from its frozen plan"
                )
            if context.generation_calls >= context.maximum_generation_calls:
                raise V2IntegrityStop("Qwen attempt generation allowance exhausted")
            if self._reserved_generation_calls >= self.resources.generation_ceiling:
                raise V2IntegrityStop(
                    "Qwen generation ceiling reached before model call"
                )
            self._assert_generation_accounting(context)
            self._pre_call_boundary()
            self._reserved_generation_calls += 1
            context.generation_calls += 1
            result = self._original_generate_record(prompt)
            if (
                type(result) is not self._generation_record_type
                or self.io.generation_calls
                != self._successful_generation_calls + 1
                or result.prompt_ref != prompt_ref
                or not 1 <= result.prompt_tokens <= MAXIMUM_INPUT_TOKENS
                or not 1 <= len(result.generated_token_ids) <= MAXIMUM_OUTPUT_TOKENS
            ):
                raise V2IntegrityStop(
                    "Qwen generation result differs at guarded boundary"
                )
            self._successful_generation_calls += 1
            self._pending_generation_tokens.append(
                (result.prompt_tokens, len(result.generated_token_ids))
            )
            self._post_call_metadata_boundary()
            return result
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_GENERATION_BOUNDARY_FAILED"
            ) from None

    def _guarded_embed(self, texts: Sequence[str]) -> object:
        try:
            context = self._require_active_embedding_context()
            if isinstance(texts, (str, bytes)) or not isinstance(texts, Sequence):
                raise TypeError("guarded Qwen embeddings require one sequence")
            frozen_texts = tuple(texts)
            if any(type(item) is not str for item in frozen_texts):
                raise TypeError("guarded Qwen embedding texts must be exact strings")
            rows = len(frozen_texts)
            if (
                rows < 1
                or context.embedding_rows + rows > context.maximum_embedding_rows
            ):
                raise V2IntegrityStop(
                    "Qwen embedding allowance exhausted before model call"
                )
            if type(context) is _ActiveQwenPlanningContext:
                if (
                    self.resources.embedding_rows + rows
                    > self.resources.embedding_ceiling
                ):
                    raise V2IntegrityStop(
                        "Qwen ranking embedding ceiling reached before model call"
                    )
            elif (
                context.arm not in STATEFUL_ARMS
                or context.embedding_rows != 0
                or rows != RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
                or self.resources.runtime_embedding_rows + rows
                > self.resources.runtime_embedding_ceiling
            ):
                raise V2IntegrityStop(
                    "Qwen runtime embedding allowance exhausted before model call"
                )
            self._pre_call_boundary()
            if type(context) is _ActiveQwenPlanningContext:
                self.resources.record_embeddings(rows)
            else:
                self.resources.record_runtime_embeddings(rows)
            context.embedding_rows += rows
            result = self._original_embed(frozen_texts)
            shape = getattr(result, "shape", None)
            if shape is None or len(shape) != 2 or int(shape[0]) != rows:
                raise V2IntegrityStop("Qwen embedding result row count differs")
            self._post_call_metadata_boundary()
            return result
        except BaseException as error:
            self._poisoned = True
            raise _redacted_failure(
                error, "QWEN_EMBEDDING_BOUNDARY_FAILED"
            ) from None

    def close(self) -> None:
        if self._closed:
            return
        if self._active is not None:
            raise V2IntegrityStop("Qwen guard cannot close inside an active attempt")
        failures: list[BaseException] = []
        io = self.io
        resources = self.resources
        foundation_guard = self.foundation_guard
        try:
            if self._poisoned:
                raise V2IntegrityStop("Qwen guard was terminally poisoned")
            self._assert_generation_accounting(None)
            if (
                self.verify_source_seal() != self.expected_source_seal_ref
                or foundation_guard.verify_boundary_digest()
                != self.expected_foundation_digest
            ):
                raise V2IntegrityStop(
                    "Qwen final source/foundation boundary changed"
                )
            resources.record_rss_peak(_peak_process_rss_bytes())
            self._validated_gpu_probe()
            self._sample_resource_boundary()
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "QWEN_GUARD_FINAL_BOUNDARY_FAILED"
                )
            )
        instance_state = getattr(io, "__dict__", {})
        expected_instance_values = {
            self._INSTANCE_MARKER: self,
            "embed": self._guarded_embed,
            "generate_record": self._guarded_generate_record,
        }
        for name, expected in expected_instance_values.items():
            try:
                observed = instance_state.get(name)
                if (
                    observed is not expected
                    if name == self._INSTANCE_MARKER
                    else observed != expected
                ):
                    raise V2IntegrityStop(
                        "LocalQwenIO guard installation changed"
                    )
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "QWEN_GUARD_INSTALLATION_CHANGED"
                    )
                )
            finally:
                try:
                    if name in instance_state:
                        delattr(io, name)
                except BaseException as error:
                    failures.append(
                        _redacted_cleanup_failure(
                            error, "QWEN_GUARD_RESTORATION_FAILED"
                        )
                    )
        try:
            resources._unbind_generation_reconciler(self)
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(error, "QWEN_GUARD_UNBIND_FAILED")
            )
        self._closed = True
        self.io = None
        self.foundation_guard = None
        self.resources = None
        self.verify_source_seal = None
        self.sample_resources = None
        self.probe_gpu = None
        self._verify_exact_foundation = None
        self._original_embed = None
        self._original_generate_record = None
        self._generation_record_type = None
        expected_instance_values.clear()
        instance_state = None
        io = None
        resources = None
        foundation_guard = None
        if len(failures) == 1:
            raise failures[0]
        if failures:
            raise ExceptionGroup("Qwen guard close failed", failures)


_V2_FOUNDATION_OWNER_CONSTRUCTION_CAPABILITY = object()


def _rebind_successor_qwen_foundation(
    loaded: object,
    *,
    loaded_type: type,
    r2_manifest: object,
) -> object:
    """Retain verified R2 model bytes while binding the successor output cap."""

    if (
        type(loaded) is not loaded_type
        or getattr(loaded, "manifest", None) != r2_manifest
        or getattr(r2_manifest, "max_new_tokens", None) != 64
        or MAXIMUM_OUTPUT_TOKENS != 160
    ):
        raise V2IntegrityStop("successor foundation rebind source differs")
    from angler.runtime.situated_qwen import LocalQwenIO

    successor_manifest = replace(
        r2_manifest,
        max_new_tokens=MAXIMUM_OUTPUT_TOKENS,
    )
    if (
        getattr(successor_manifest, "generation_config_ref", None)
        != QUALIFIED_SUCCESSOR_GENERATION_CONFIG_REF
        or getattr(successor_manifest, "manifest_ref", None)
        != QUALIFIED_SUCCESSOR_CYCLE_MANIFEST_REF
    ):
        raise V2IntegrityStop("successor foundation manifest identity differs")
    model = getattr(loaded, "model", None)
    tokenizer = getattr(loaded, "tokenizer", None)
    successor_io = LocalQwenIO(
        model,
        tokenizer,
        embedding_batch_size=successor_manifest.embedding_batch_size,
        max_input_tokens=successor_manifest.max_input_tokens,
        max_new_tokens=successor_manifest.max_new_tokens,
        enable_thinking=False,
        model_ref=successor_manifest.model_ref,
        tokenizer_ref=successor_manifest.tokenizer_ref,
    )
    successor_manifest.assert_io(successor_io)
    rebound = replace(
        loaded,
        io=successor_io,
        manifest=successor_manifest,
    )
    if (
        type(rebound) is not loaded_type
        or getattr(rebound, "model", None) is not model
        or getattr(rebound, "tokenizer", None) is not tokenizer
        or getattr(rebound, "guard", None) is not getattr(loaded, "guard", None)
        or getattr(rebound, "production_file_evidence", None)
        is not getattr(loaded, "production_file_evidence", None)
    ):
        raise V2IntegrityStop("successor foundation rebind changed model authority")
    return rebound


@dataclass(slots=True)
class V2FoundationOwner:
    """One V2-owned qualified foundation and its exact instrumented IO seam."""

    loaded: object | None = field(repr=False)
    guard: GuardedLocalQwenBoundary | None = field(repr=False)
    _mirror: _ExactFoundationByteMirror | None = field(repr=False)
    helpers: Mapping[str, object] = field(repr=False)
    _construction_capability: object = field(repr=False)
    _closed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        if self._construction_capability is not (
            _V2_FOUNDATION_OWNER_CONSTRUCTION_CAPABILITY
        ):
            raise V2IntegrityStop(
                "foundation owner escaped its validated construction boundary"
            )

    @classmethod
    def _create_validated(
        cls,
        *,
        resources: ResourceLedger,
        verify_source_seal: Callable[[], str],
        expected_source_seal_ref: str,
        sample_resources: Callable[[], Mapping[str, int]],
        probe_gpu: Callable[[], Mapping[str, object]],
        construction_capability: object,
    ) -> "V2FoundationOwner":
        if construction_capability is not (
            _V2_FOUNDATION_OWNER_CONSTRUCTION_CAPABILITY
        ):
            raise V2IntegrityStop("foundation construction capability differs")
        if (
            type(resources) is not ResourceLedger
            or not callable(verify_source_seal)
            or not callable(sample_resources)
            or not callable(probe_gpu)
        ):
            raise TypeError("foundation validated construction boundary differs")
        expected_source_seal_ref = _ref(
            expected_source_seal_ref, "foundation source boundary ref"
        )
        helpers = _load_approved_r2_low_level_helpers()
        loaded: object | None = None
        call_guard: GuardedLocalQwenBoundary | None = None
        mirror: _ExactFoundationByteMirror | None = None
        try:
            loaded = _call_r2_low_level(
                helpers["load_qualified_qwen_foundation"], MODEL_ROOT
            )
            if (
                type(loaded) is not helpers["LoadedQwenFoundation"]
                or getattr(loaded, "production_file_identity_verified", None)
                is not True
            ):
                raise V2IntegrityStop("qualified foundation owner differs")
            expected_manifest = _call_r2_low_level(
                helpers["qualified_qwen_cycle_manifest"]
            )
            if getattr(loaded, "manifest", None) != expected_manifest:
                raise V2IntegrityStop("qualified foundation manifest differs")
            loaded = _rebind_successor_qwen_foundation(
                loaded,
                loaded_type=helpers["LoadedQwenFoundation"],
                r2_manifest=expected_manifest,
            )
            foundation_guard = getattr(loaded, "guard", None)
            expected_digest = _ref(
                getattr(foundation_guard, "initial_tensor_digest", None),
                "qualified foundation tensor digest",
            )
            mirror = _ExactFoundationByteMirror(
                getattr(loaded, "model", None),
                foundation_guard=foundation_guard,
                expected_digest=expected_digest,
                resources=resources,
            )
            call_guard = GuardedLocalQwenBoundary(
                getattr(loaded, "io", None),
                foundation_guard=foundation_guard,
                expected_foundation_digest=expected_digest,
                resources=resources,
                verify_source_seal=verify_source_seal,
                expected_source_seal_ref=expected_source_seal_ref,
                sample_resources=sample_resources,
                probe_gpu=probe_gpu,
                verify_exact_foundation=mirror.verify_exact,
            )
            return cls(
                loaded=loaded,
                guard=call_guard,
                _mirror=mirror,
                helpers=MappingProxyType(dict(helpers)),
                _construction_capability=construction_capability,
            )
        except BaseException as primary:
            safe_primary = _redacted_failure(
                primary, "QUALIFIED_FOUNDATION_CONSTRUCTION_FAILED"
            )
            cleanup_failures: list[BaseException] = []
            if call_guard is not None:
                try:
                    call_guard.close()
                except BaseException as error:
                    cleanup_failures.append(
                        _redacted_failure(
                            error, "QUALIFIED_FOUNDATION_GUARD_CLEANUP_FAILED"
                        )
                    )
            call_guard = None
            if mirror is not None:
                try:
                    mirror.close()
                except BaseException as error:
                    cleanup_failures.append(
                        _redacted_failure(
                            error, "QUALIFIED_FOUNDATION_MIRROR_CLEANUP_FAILED"
                        )
                    )
            mirror = None
            foundation_guard = None
            loaded = None
            primary = None
            try:
                cls._release_cuda()
            except BaseException as error:
                cleanup_failures.append(
                    _redacted_failure(
                        error, "QUALIFIED_FOUNDATION_CUDA_CLEANUP_FAILED"
                    )
                )
            if cleanup_failures:
                raise ExceptionGroup(
                    "qualified foundation construction cleanup failed",
                    [safe_primary, *cleanup_failures],
                ) from None
            raise safe_primary from None

    @classmethod
    def create_live(
        cls,
        *,
        resources: ResourceLedger,
        verify_source_seal: Callable[[], str],
        expected_source_seal_ref: str,
        sample_resources: Callable[[], Mapping[str, int]],
        probe_gpu: Callable[[], Mapping[str, object]],
    ) -> "V2FoundationOwner":
        validate_live_parent_boundary(require_unassigned_zero_processes=True)
        return cls._create_validated(
            resources=resources,
            verify_source_seal=verify_source_seal,
            expected_source_seal_ref=expected_source_seal_ref,
            sample_resources=sample_resources,
            probe_gpu=probe_gpu,
            construction_capability=(
                _V2_FOUNDATION_OWNER_CONSTRUCTION_CAPABILITY
            ),
        )

    @classmethod
    def create_preflight(
        cls,
        *,
        resources: ResourceLedger,
        verify_source_inventory: Callable[[], str],
        expected_source_inventory_ref: str,
        sample_resources: Callable[[], Mapping[str, int]],
        probe_gpu: Callable[[], Mapping[str, object]],
        validate_boundary: Callable[[], Mapping[str, object]],
    ) -> "V2FoundationOwner":
        """Construct only after the private preflight child validates."""

        if not callable(validate_boundary):
            raise TypeError("foundation preflight validator differs")
        boundary = validate_foundation_preflight_boundary_record(
            _canonical_mapping(
                validate_boundary(), "foundation preflight boundary"
            ),
            expected_source_inventory_ref=_ref(
                expected_source_inventory_ref,
                "foundation preflight source inventory",
            ),
        )
        return cls._create_validated(
            resources=resources,
            verify_source_seal=verify_source_inventory,
            expected_source_seal_ref=expected_source_inventory_ref,
            sample_resources=sample_resources,
            probe_gpu=probe_gpu,
            construction_capability=(
                _V2_FOUNDATION_OWNER_CONSTRUCTION_CAPABILITY
            ),
        )

    @staticmethod
    def _release_cuda() -> None:
        gc.collect()
        import torch

        if torch.cuda.is_available():
            torch.cuda.synchronize(0)
            torch.cuda.empty_cache()
            torch.cuda.ipc_collect()
            torch.cuda.synchronize(0)
            if (
                int(torch.cuda.memory_allocated(0)) != 0
                or int(torch.cuda.memory_reserved(0)) != 0
            ):
                raise V2IntegrityStop(
                    "qualified foundation CUDA allocation remains"
                )

    @property
    def io(self) -> object:
        if self._closed or self.loaded is None:
            raise V2IntegrityStop("foundation owner is closed")
        return getattr(self.loaded, "io")

    @property
    def manifest(self) -> object:
        if self._closed or self.loaded is None:
            raise V2IntegrityStop("foundation owner is closed")
        return getattr(self.loaded, "manifest")

    @property
    def foundation_guard(self) -> object:
        if self._closed or self.loaded is None:
            raise V2IntegrityStop("foundation owner is closed")
        return getattr(self.loaded, "guard")

    def close(self) -> None:
        if self._closed:
            return
        if self.guard is not None and self.guard._active is not None:
            raise V2IntegrityStop(
                "qualified foundation cannot close inside an active call"
            )
        failures: list[BaseException] = []
        call_guard = self.guard
        if call_guard is not None:
            try:
                call_guard.close()
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "QUALIFIED_FOUNDATION_GUARD_CLOSE_FAILED"
                    )
                )
            if not call_guard._closed:
                if len(failures) == 1:
                    raise failures[0]
                raise ExceptionGroup(
                    "qualified foundation guard close failed", failures
                )
            self.guard = None
        call_guard = None
        mirror = self._mirror
        if mirror is not None:
            try:
                mirror.close()
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "QUALIFIED_FOUNDATION_MIRROR_CLOSE_FAILED"
                    )
                )
            if not mirror._closed:
                if len(failures) == 1:
                    raise failures[0]
                raise ExceptionGroup(
                    "qualified foundation mirror close failed", failures
                )
            self._mirror = None
        mirror = None
        self.loaded = None
        release_succeeded = False
        try:
            self._release_cuda()
            release_succeeded = True
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "QUALIFIED_FOUNDATION_CUDA_RELEASE_FAILED"
                )
            )
        if release_succeeded:
            self._closed = True
        if len(failures) == 1:
            raise failures[0]
        if failures:
            raise ExceptionGroup("qualified foundation close failed", failures)


def _execute_foundation_mirror_preflight_injected(
    *,
    validate_boundary: Callable[[], Mapping[str, object]],
    sample_resources: Callable[[], Mapping[str, int]],
    probe_gpu: Callable[[], Mapping[str, object]],
    source_inventory_loader: Callable[[], Sequence[Mapping[str, object]]],
    owner_factory: Callable[..., V2FoundationOwner] = (
        V2FoundationOwner.create_preflight
    ),
    resources: ResourceLedger | None = None,
) -> tuple[
    _FoundationMirrorAuditReceipt,
    dict[str, object],
    list[dict[str, object]],
]:
    """Run the no-warm-up three-scan gate through an injectable child seam."""

    if any(
        not callable(value)
        for value in (
            validate_boundary,
            sample_resources,
            probe_gpu,
            source_inventory_loader,
            owner_factory,
        )
    ):
        raise TypeError("foundation preflight dependency differs")
    ledger = ResourceLedger(RunMode.QUALIFICATION) if resources is None else resources
    if type(ledger) is not ResourceLedger or ledger.mode is not RunMode.QUALIFICATION:
        raise TypeError("foundation preflight resource ledger differs")
    sources_before = [dict(row) for row in source_inventory_loader()]
    if len(sources_before) != len(SOURCE_MANIFEST_INVENTORY):
        raise V2IntegrityStop("foundation preflight source inventory differs")
    source_inventory_ref = canonical_ref("source-inventory", sources_before)
    boundary = validate_foundation_preflight_boundary_record(
        validate_boundary(),
        expected_source_inventory_ref=source_inventory_ref,
    )

    def verify_source_inventory() -> str:
        observed = [dict(row) for row in source_inventory_loader()]
        if observed != sources_before:
            raise V2IntegrityStop("foundation preflight source bytes changed")
        return source_inventory_ref

    def frozen_boundary() -> dict[str, object]:
        return validate_foundation_preflight_boundary_record(
            boundary,
            expected_source_inventory_ref=source_inventory_ref,
        )

    owner: V2FoundationOwner | None = None
    mirror: _ExactFoundationByteMirror | None = None
    primary: V2IntegrityStop | None = None
    cleanup: V2IntegrityStop | None = None
    try:
        owner = owner_factory(
            resources=ledger,
            verify_source_inventory=verify_source_inventory,
            expected_source_inventory_ref=source_inventory_ref,
            sample_resources=sample_resources,
            probe_gpu=probe_gpu,
            validate_boundary=frozen_boundary,
        )
        if type(owner) is not V2FoundationOwner or owner._closed:
            raise V2IntegrityStop("foundation preflight owner differs")
        mirror = owner._mirror
        if type(mirror) is not _ExactFoundationByteMirror:
            raise V2IntegrityStop("foundation preflight mirror differs")
        # Guard construction performed the first measured verification.
        mirror.verify_exact()
        mirror.verify_exact()
        mirror.assert_first_three_performance_gate()
        if verify_source_inventory() != source_inventory_ref:
            raise V2IntegrityStop("foundation preflight source closure differs")
    except BaseException as error:
        primary = _redacted_failure(error, "FOUNDATION_PREFLIGHT_FAILED")
    if owner is not None:
        try:
            owner.close()
        except BaseException as error:
            cleanup = _redacted_failure(
                error, "FOUNDATION_PREFLIGHT_CLEANUP_FAILED"
            )
    owner = None
    if primary is not None or cleanup is not None:
        mirror = None
        if primary is not None and cleanup is not None:
            raise ExceptionGroup(
                "foundation preflight and cleanup failed", [primary, cleanup]
            ) from None
        raise (primary if primary is not None else cleanup) from None
    if mirror is None:
        raise V2IntegrityStop("foundation preflight mirror receipt is absent")
    audit = mirror.audit_receipt
    mirror = None
    sources_after = [dict(row) for row in source_inventory_loader()]
    if sources_after != sources_before:
        raise V2IntegrityStop("foundation preflight source changed after cleanup")
    return audit, boundary, sources_after


def run_foundation_mirror_preflight_injected(
    *,
    validate_boundary: Callable[[], Mapping[str, object]],
    host_closure: Mapping[str, object],
    sample_resources: Callable[[], Mapping[str, int]],
    probe_gpu: Callable[[], Mapping[str, object]],
    source_inventory_loader: Callable[[], Sequence[Mapping[str, object]]],
    owner_factory: Callable[..., V2FoundationOwner] = (
        V2FoundationOwner.create_preflight
    ),
    resources: ResourceLedger | None = None,
) -> dict[str, object]:
    """Injectable complete preflight, including the outer host closure."""

    audit, boundary, sources = _execute_foundation_mirror_preflight_injected(
        validate_boundary=validate_boundary,
        sample_resources=sample_resources,
        probe_gpu=probe_gpu,
        source_inventory_loader=source_inventory_loader,
        owner_factory=owner_factory,
        resources=resources,
    )
    return FoundationMirrorPreflightReceipt.from_audit(
        audit,
        source_inventory=sources,
        boundary=boundary,
        host_closure=host_closure,
    ).to_canonical()


def build_foundation_mirror_child_evidence(
    *,
    audit: _FoundationMirrorAuditReceipt,
    boundary: Mapping[str, object],
    source_inventory: Sequence[Mapping[str, object]],
) -> dict[str, object]:
    """Serialize only tensor-free child evidence for the privileged wrapper."""

    if type(audit) is not _FoundationMirrorAuditReceipt:
        raise TypeError("foundation child mirror audit differs")
    sources = [dict(row) for row in source_inventory]
    source_inventory_ref = canonical_ref("source-inventory", sources)
    host = validate_foundation_preflight_boundary_record(
        boundary,
        expected_source_inventory_ref=source_inventory_ref,
    )
    if (
        audit.parameter_count != QUALIFIED_MODEL_PARAMETER_COUNT
        or audit.parameter_bytes != QUALIFIED_MODEL_PARAMETER_BYTES
        or audit.largest_parameter_bytes
        != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
        or audit.pinned_slot_count != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
        or audit.pinned_slot_bytes != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
        or audit.pinned_bytes != FOUNDATION_MIRROR_PINNED_BYTES
        or audit.allocator_cleanup is None
        or audit.performance_gate_passed is not True
        or audit.poisoned is not False
        or audit.closed is not True
        or audit.cleanup_proven is not True
    ):
        raise V2IntegrityStop("foundation child mirror audit did not close")
    mirror = {
        "allocator_baseline": _pinned_allocator_snapshot_canonical(
            audit.allocator_baseline
        ),
        "allocator_cleanup": _pinned_allocator_snapshot_canonical(
            audit.allocator_cleanup
        ),
        "allocator_post_allocation": _pinned_allocator_snapshot_canonical(
            audit.allocator_post_allocation
        ),
        "cleanup_proven": True,
        "closed": True,
        "largest_parameter_bytes": audit.largest_parameter_bytes,
        "memlock_soft_limit_bytes": audit.memlock_soft_limit_bytes,
        "parameter_bytes": audit.parameter_bytes,
        "parameter_count": audit.parameter_count,
        "performance_gate_passed": True,
        "pinned_bytes": audit.pinned_bytes,
        "pinned_slot_bytes": audit.pinned_slot_bytes,
        "pinned_slot_count": audit.pinned_slot_count,
        "poisoned": False,
        "rss_bytes_before": audit.rss_bytes_before,
        "rss_reservation_bytes": audit.rss_reservation_bytes,
        "verification_durations_ns": list(audit.verification_durations_ns),
        "vm_locked_bytes_before": audit.vm_locked_bytes_before,
    }
    payload = {
        "boundary": host,
        "mirror": mirror,
        "protocol_identity": PROTOCOL_IDENTITY,
        "schema": FOUNDATION_MIRROR_PREFLIGHT_CHILD_SCHEMA,
        "source_count": len(sources),
        "source_inventory_ref": source_inventory_ref,
    }
    return {
        **payload,
        "child_evidence_ref": canonical_ref(
            "foundation-mirror-preflight-child", payload
        ),
    }


def validate_foundation_mirror_child_evidence(
    value: Mapping[str, object],
    *,
    source_inventory: Sequence[Mapping[str, object]],
) -> tuple[_FoundationMirrorAuditReceipt, dict[str, object]]:
    row = dict(value)
    expected_keys = {
        "boundary",
        "child_evidence_ref",
        "mirror",
        "protocol_identity",
        "schema",
        "source_count",
        "source_inventory_ref",
    }
    sources = [dict(item) for item in source_inventory]
    source_inventory_ref = canonical_ref("source-inventory", sources)
    if (
        set(row) != expected_keys
        or row["schema"] != FOUNDATION_MIRROR_PREFLIGHT_CHILD_SCHEMA
        or row["protocol_identity"] != PROTOCOL_IDENTITY
        or row["source_count"] != len(sources)
        or row["source_inventory_ref"] != source_inventory_ref
    ):
        raise V2IntegrityStop("foundation child evidence identity differs")
    payload = dict(row)
    observed_ref = payload.pop("child_evidence_ref")
    if observed_ref != canonical_ref("foundation-mirror-preflight-child", payload):
        raise V2IntegrityStop("foundation child evidence ref differs")
    boundary = validate_foundation_preflight_boundary_record(
        _canonical_mapping(row["boundary"], "foundation child boundary"),
        expected_source_inventory_ref=source_inventory_ref,
    )
    mirror = _canonical_mapping(row["mirror"], "foundation child mirror")
    mirror_keys = {
        "allocator_baseline",
        "allocator_cleanup",
        "allocator_post_allocation",
        "cleanup_proven",
        "closed",
        "largest_parameter_bytes",
        "memlock_soft_limit_bytes",
        "parameter_bytes",
        "parameter_count",
        "performance_gate_passed",
        "pinned_bytes",
        "pinned_slot_bytes",
        "pinned_slot_count",
        "poisoned",
        "rss_bytes_before",
        "rss_reservation_bytes",
        "verification_durations_ns",
        "vm_locked_bytes_before",
    }
    if (
        set(mirror) != mirror_keys
        or mirror["parameter_count"] != QUALIFIED_MODEL_PARAMETER_COUNT
        or mirror["parameter_bytes"] != QUALIFIED_MODEL_PARAMETER_BYTES
        or mirror["largest_parameter_bytes"]
        != QUALIFIED_MODEL_LARGEST_PARAMETER_BYTES
        or mirror["pinned_slot_count"] != FOUNDATION_MIRROR_PINNED_SLOT_COUNT
        or mirror["pinned_slot_bytes"] != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
        or mirror["pinned_bytes"] != FOUNDATION_MIRROR_PINNED_BYTES
        or mirror["performance_gate_passed"] is not True
        or mirror["poisoned"] is not False
        or mirror["closed"] is not True
        or mirror["cleanup_proven"] is not True
        or type(mirror["verification_durations_ns"]) is not list
        or len(mirror["verification_durations_ns"]) != 3
        or type(mirror["memlock_soft_limit_bytes"]) is not int
    ):
        raise V2IntegrityStop("foundation child mirror evidence differs")
    audit = _FoundationMirrorAuditReceipt(
        parameter_count=mirror["parameter_count"],  # type: ignore[arg-type]
        parameter_bytes=mirror["parameter_bytes"],  # type: ignore[arg-type]
        largest_parameter_bytes=mirror["largest_parameter_bytes"],  # type: ignore[arg-type]
        pinned_slot_count=mirror["pinned_slot_count"],  # type: ignore[arg-type]
        pinned_slot_bytes=mirror["pinned_slot_bytes"],  # type: ignore[arg-type]
        pinned_bytes=mirror["pinned_bytes"],  # type: ignore[arg-type]
        vm_locked_bytes_before=_integer(
            mirror["vm_locked_bytes_before"],
            "foundation child locked bytes",
            minimum=0,
        ),
        memlock_soft_limit_bytes=mirror["memlock_soft_limit_bytes"],  # type: ignore[arg-type]
        rss_bytes_before=_integer(
            mirror["rss_bytes_before"], "foundation child RSS", minimum=0
        ),
        rss_reservation_bytes=_integer(
            mirror["rss_reservation_bytes"],
            "foundation child RSS reservation",
            minimum=0,
        ),
        allocator_baseline=_validated_pinned_allocator_snapshot(
            mirror["allocator_baseline"], "foundation child allocator baseline"
        ),
        allocator_post_allocation=_validated_pinned_allocator_snapshot(
            mirror["allocator_post_allocation"],
            "foundation child allocator post-allocation",
        ),
        allocator_cleanup=_validated_pinned_allocator_snapshot(
            mirror["allocator_cleanup"], "foundation child allocator cleanup"
        ),
        verification_durations_ns=tuple(mirror["verification_durations_ns"]),
        performance_gate_passed=True,
        poisoned=False,
        closed=True,
        cleanup_proven=True,
    )
    # Reuse the strict final receipt gate with a synthetic structurally valid
    # closure only after the privileged wrapper supplies its real closure.
    if (
        max(audit.verification_durations_ns)
        > FOUNDATION_MIRROR_MAXIMUM_VERIFICATION_NS
    ):
        raise V2IntegrityStop("foundation child performance gate differs")
    return audit, boundary


def run_foundation_mirror_preflight_child_injected(
    **kwargs: object,
) -> dict[str, object]:
    """Produce the one bounded child frame; it is not manifest-authorizing."""

    audit, boundary, sources = _execute_foundation_mirror_preflight_injected(
        **kwargs  # type: ignore[arg-type]
    )
    return build_foundation_mirror_child_evidence(
        audit=audit,
        boundary=boundary,
        source_inventory=sources,
    )


def validate_foundation_preflight_namespace_proof(
    value: Mapping[str, object],
) -> dict[str, object]:
    proof = dict(value)
    expected_keys = {
        "filesystem",
        "mount_device",
        "mount_id",
        "mount_options",
        "mount_parent_id",
        "mount_root",
        "mount_size_bytes",
        "mount_target",
        "parent_mount_namespace",
        "parent_network_namespace",
        "private_child_mode",
        "private_child_names",
        "private_child_owner_gid",
        "private_child_owner_uid",
        "private_root",
        "private_root_mode",
        "private_root_owner_gid",
        "private_root_owner_uid",
        "scratch_mount_mode",
        "scratch_mount_owner_gid",
        "scratch_mount_owner_uid",
        "self_mount_namespace",
        "self_network_namespace",
        "super_options",
    }
    if set(proof) != expected_keys:
        raise V2InvariantError("foundation preflight namespace proof fields differ")
    mount_options = proof["mount_options"]
    super_options = proof["super_options"]
    if (
        proof["filesystem"] != "tmpfs"
        or proof["mount_root"] != "/"
        or proof["mount_target"] != "/opt/angler/scratch"
        or proof["mount_size_bytes"] != FOUNDATION_MIRROR_PINNED_SLOT_BYTES
        or type(proof["mount_id"]) is not int
        or proof["mount_id"] < 1
        or type(proof["mount_parent_id"]) is not int
        or proof["mount_parent_id"] < 1
        or type(proof["mount_device"]) is not str
        or re.fullmatch(r"[0-9]+:[0-9]+", proof["mount_device"]) is None
        or type(mount_options) is not list
        or mount_options != sorted(set(mount_options))
        or not {"rw", "nosuid", "nodev", "noexec"}.issubset(mount_options)
        or type(super_options) is not list
        or super_options != sorted(set(super_options))
        or "rw" not in super_options
        or "mode=700" not in super_options
        or "uid=1000" not in super_options
        or "gid=1000" not in super_options
        or not (
            "size=1048576k" in super_options
            or "size=1073741824" in super_options
        )
        or proof["private_root"] != str(FOUNDATION_PREFLIGHT_PRIVATE_ROOT)
        or proof["private_child_names"] != ["cache", "tmp"]
        or any(
            proof[name] != expected
            for name, expected in (
                ("private_child_mode", "0700"),
                ("private_child_owner_gid", 1000),
                ("private_child_owner_uid", 1000),
                ("private_root_mode", "0700"),
                ("private_root_owner_gid", 1000),
                ("private_root_owner_uid", 1000),
                ("scratch_mount_mode", "0700"),
                ("scratch_mount_owner_gid", 1000),
                ("scratch_mount_owner_uid", 1000),
            )
        )
        or type(proof["self_mount_namespace"]) is not str
        or re.fullmatch(
            r"mnt:\[[0-9]+\]", proof["self_mount_namespace"]
        )
        is None
        or type(proof["parent_mount_namespace"]) is not str
        or re.fullmatch(
            r"mnt:\[[0-9]+\]", proof["parent_mount_namespace"]
        )
        is None
        or proof["self_mount_namespace"] == proof["parent_mount_namespace"]
        or type(proof["self_network_namespace"]) is not str
        or re.fullmatch(
            r"net:\[[0-9]+\]", proof["self_network_namespace"]
        )
        is None
        or type(proof["parent_network_namespace"]) is not str
        or re.fullmatch(
            r"net:\[[0-9]+\]", proof["parent_network_namespace"]
        )
        is None
        or proof["self_network_namespace"] == proof["parent_network_namespace"]
    ):
        raise V2IntegrityStop("foundation preflight namespace proof differs")
    return proof


def validate_foundation_preflight_namespace_boundary(
    *,
    parent_mount_namespace: str,
    parent_network_namespace: str,
    environment: Mapping[str, str] | None = None,
    effective_uid: int | None = None,
    effective_gid: int | None = None,
    supplementary_groups: Sequence[int] | None = None,
    namespace_reader: Callable[[Path], str] | None = None,
    status_reader: Callable[[], str] | None = None,
    mountinfo_reader: Callable[[], str] | None = None,
    validate_paths: Callable[[], Mapping[str, object] | None] | None = None,
) -> dict[str, object]:
    """Validate the unprivileged child before importing Torch or loading Qwen."""

    observed_environment = dict(os.environ if environment is None else environment)
    if observed_environment != _frozen_foundation_preflight_environment():
        raise V2IntegrityStop("foundation preflight environment differs")
    uid = os.geteuid() if effective_uid is None else effective_uid
    gid = os.getegid() if effective_gid is None else effective_gid
    groups = tuple(os.getgroups() if supplementary_groups is None else supplementary_groups)
    if uid != 1000 or gid != 1000 or groups:
        raise V2IntegrityStop("foundation preflight identity/capabilities differ")
    read_namespace = namespace_reader or os.readlink
    mount_namespace = read_namespace(Path("/proc/self/ns/mnt"))
    network_namespace = read_namespace(Path("/proc/self/ns/net"))
    if (
        re.fullmatch(r"mnt:\[[0-9]+\]", mount_namespace) is None
        or re.fullmatch(r"net:\[[0-9]+\]", network_namespace) is None
        or type(parent_mount_namespace) is not str
        or re.fullmatch(r"mnt:\[[0-9]+\]", parent_mount_namespace) is None
        or type(parent_network_namespace) is not str
        or re.fullmatch(r"net:\[[0-9]+\]", parent_network_namespace) is None
        or mount_namespace == parent_mount_namespace
        or network_namespace == parent_network_namespace
    ):
        raise V2IntegrityStop("foundation preflight namespace isolation differs")
    status = (
        Path("/proc/self/status").read_text(encoding="ascii")
        if status_reader is None
        else status_reader()
    )
    fields: dict[str, str] = {}
    for line in status.splitlines():
        if ":" not in line:
            continue
        name, raw = line.split(":", 1)
        fields[name] = raw.strip()
    if (
        fields.get("NoNewPrivs") != "1"
        or fields.get("CapEff") != "0000000000000000"
        or fields.get("CapPrm") != "0000000000000000"
        or fields.get("CapInh") != "0000000000000000"
        or fields.get("CapAmb") != "0000000000000000"
        or fields.get("CapBnd") != "0000000000000000"
    ):
        raise V2IntegrityStop("foundation preflight privilege boundary differs")
    mountinfo = (
        Path("/proc/self/mountinfo").read_text(encoding="ascii")
        if mountinfo_reader is None
        else mountinfo_reader()
    )
    matching: list[tuple[list[str], list[str], int, int, str, str]] = []
    for line in mountinfo.splitlines():
        fields = line.split()
        if "-" not in fields:
            continue
        separator = fields.index("-")
        if separator < 6 or len(fields) < separator + 4:
            continue
        if fields[4] != "/opt/angler/scratch":
            continue
        if fields[separator + 1] != "tmpfs":
            raise V2IntegrityStop("foundation preflight scratch is not tmpfs")
        matching.append(
            (
                fields[5].split(","),
                fields[separator + 3].split(","),
                int(fields[0]),
                int(fields[1]),
                fields[2],
                fields[3],
            )
        )
    if len(matching) != 1:
        raise V2IntegrityStop("foundation preflight scratch mount differs")
    (
        mount_options_raw,
        super_options_raw,
        mount_id,
        mount_parent_id,
        mount_device,
        mount_root,
    ) = matching[0]
    mount_options = set(mount_options_raw)
    super_options = set(super_options_raw)
    if (
        not {"rw", "nosuid", "nodev", "noexec"}.issubset(mount_options)
        or "rw" not in super_options
        or "mode=700" not in super_options
        or "uid=1000" not in super_options
        or "gid=1000" not in super_options
        or not (
            "size=1048576k" in super_options
            or "size=1073741824" in super_options
        )
        or mount_id < 1
        or mount_parent_id < 1
        or re.fullmatch(r"[0-9]+:[0-9]+", mount_device) is None
        or mount_root != "/"
    ):
        raise V2IntegrityStop("foundation preflight scratch mount options differ")
    if validate_paths is None:
        assert_all_live_paths_absent(
            (
                STATE_ROOT,
                MANIFEST_PATH,
                QUALIFICATION_RESULT_PATH,
                EVALUATION_RESULT_PATH,
            )
        )
        _require_absent(SCRATCH_ROOT, "foundation preflight live scratch root")
        _require_owned_directory(
            FOUNDATION_PREFLIGHT_PRIVATE_ROOT,
            expected_mode=0o700,
            label="foundation preflight private root",
        )
        _exact_child_names(
            FOUNDATION_PREFLIGHT_PRIVATE_ROOT,
            {"cache", "tmp"},
            "foundation preflight private root",
        )
        for path, label in (
            (FOUNDATION_PREFLIGHT_CACHE, "foundation preflight cache"),
            (FOUNDATION_PREFLIGHT_TMP, "foundation preflight tmp"),
        ):
            _require_owned_directory(
                path, expected_mode=0o700, empty=True, label=label
            )
        scratch_metadata = os.lstat(Path("/opt/angler/scratch"))
        private_metadata = os.lstat(FOUNDATION_PREFLIGHT_PRIVATE_ROOT)
        path_facts: Mapping[str, object] = {
            "private_child_names": ["cache", "tmp"],
            "private_child_mode": "0700",
            "private_child_owner_gid": os.getegid(),
            "private_child_owner_uid": os.geteuid(),
            "private_root": str(FOUNDATION_PREFLIGHT_PRIVATE_ROOT),
            "private_root_mode": "0700",
            "private_root_owner_gid": int(private_metadata.st_gid),
            "private_root_owner_uid": int(private_metadata.st_uid),
            "scratch_mount_mode": "0700",
            "scratch_mount_owner_gid": int(scratch_metadata.st_gid),
            "scratch_mount_owner_uid": int(scratch_metadata.st_uid),
        }
    else:
        path_facts = _canonical_mapping(
            validate_paths(), "foundation preflight path facts"
        )
    proof = {
        "filesystem": "tmpfs",
        "mount_device": mount_device,
        "mount_id": mount_id,
        "mount_options": sorted(mount_options),
        "mount_parent_id": mount_parent_id,
        "mount_root": mount_root,
        "mount_size_bytes": FOUNDATION_MIRROR_PINNED_SLOT_BYTES,
        "mount_target": "/opt/angler/scratch",
        "parent_mount_namespace": parent_mount_namespace,
        "parent_network_namespace": parent_network_namespace,
        "self_mount_namespace": mount_namespace,
        "self_network_namespace": network_namespace,
        "super_options": sorted(super_options),
        **dict(path_facts),
    }
    proof = validate_foundation_preflight_namespace_proof(proof)
    return {
        "environment_sha256": hashlib.sha256(
            canonical_json_bytes(observed_environment)
        ).hexdigest(),
        "mount_namespace": mount_namespace,
        "network_namespace": network_namespace,
        "namespace_proof": proof,
        "namespace_boundary_ref": canonical_ref(
            "foundation-preflight-namespace", proof
        ),
    }


def collect_foundation_preflight_child_boundary(
    *,
    namespace_boundary: Mapping[str, object],
    source_inventory: Sequence[Mapping[str, object]] | None = None,
    live_parent_validator: Callable[..., Mapping[str, object]] = (
        validate_live_parent_boundary
    ),
    gpu_inventory_runner: Callable[..., object] | None = None,
    gpu_process_runner: Callable[..., object] | None = None,
    torch_module: object | None = None,
) -> dict[str, object]:
    """Collect the strict public child boundary after pre-Torch isolation checks."""

    namespace = dict(namespace_boundary)
    if set(namespace) != {
        "environment_sha256",
        "mount_namespace",
        "namespace_boundary_ref",
        "namespace_proof",
        "network_namespace",
    }:
        raise V2InvariantError("foundation preflight namespace receipt differs")
    sources = (
        _source_inventory_snapshot()
        if source_inventory is None
        else [dict(row) for row in source_inventory]
    )
    source_inventory_ref = canonical_ref("source-inventory", sources)
    host = dict(
        live_parent_validator(
            environment=_frozen_foundation_preflight_environment(),
            expected_environment=_frozen_foundation_preflight_environment(),
            gpu_inventory_runner=gpu_inventory_runner,
            gpu_process_runner=gpu_process_runner,
            require_unassigned_zero_processes=True,
            torch_module=torch_module,
        )
    )
    if (
        host.get("environment_sha256") != namespace["environment_sha256"]
        or host.get("network_namespace") != namespace["network_namespace"]
    ):
        raise V2IntegrityStop("foundation preflight host/namespace join differs")
    physical = host.get("physical_gpus")
    if type(physical) is not list:
        raise V2IntegrityStop("foundation preflight GPU boundary differs")
    by_uuid = {
        item.get("uuid"): item
        for item in physical
        if type(item) is dict and type(item.get("uuid")) is str
    }
    payload = {
        "assigned_gpu_name": by_uuid.get(ASSIGNED_GPU_UUID, {}).get("name"),
        "assigned_gpu_uuid": ASSIGNED_GPU_UUID,
        "environment_sha256": namespace["environment_sha256"],
        "hostname": host.get("hostname"),
        "logical_device_count": 1,
        "logical_device_index": host.get("logical_cuda_device"),
        "mount_namespace": namespace["mount_namespace"],
        "namespace_boundary_ref": namespace["namespace_boundary_ref"],
        "namespace_proof": namespace["namespace_proof"],
        "network_namespace": namespace["network_namespace"],
        "python": host.get("python"),
        "python_executable": host.get("python_executable"),
        "source_inventory_ref": source_inventory_ref,
        "unassigned_compute_processes": host.get(
            "unassigned_compute_processes"
        ),
        "unassigned_gpu_name": by_uuid.get(UNASSIGNED_GPU_UUID, {}).get("name"),
        "unassigned_gpu_uuid": UNASSIGNED_GPU_UUID,
    }
    boundary = {
        "boundary": "FOUNDATION_MIRROR_PREFLIGHT_CHILD",
        **payload,
        "host_boundary_ref": canonical_ref(
            "foundation-preflight-host", payload
        ),
    }
    return validate_foundation_preflight_boundary_record(
        boundary,
        expected_source_inventory_ref=source_inventory_ref,
    )


def _foundation_preflight_tree_bytes(root: Path) -> int:
    """Bounded, no-follow accounting for the private tmpfs preflight tree."""

    _require_owned_directory(
        root, expected_mode=0o700, label="foundation preflight accounting root"
    )
    stack = [root]
    identities: set[tuple[int, int]] = set()
    entries = 0
    total = 0
    while stack:
        current = stack.pop()
        metadata = os.lstat(current)
        identity = (int(metadata.st_dev), int(metadata.st_ino))
        if identity in identities:
            raise V2IntegrityStop("foundation preflight tree aliases")
        identities.add(identity)
        with os.scandir(current) as iterator:
            children = tuple(iterator)
        for child in children:
            entries += 1
            if entries > 16_384:
                raise V2IntegrityStop("foundation preflight tree entry bound exceeded")
            child_metadata = child.stat(follow_symlinks=False)
            if (
                stat.S_ISLNK(child_metadata.st_mode)
                or child_metadata.st_uid != os.geteuid()
                or child_metadata.st_gid != os.getegid()
            ):
                raise V2IntegrityStop("foundation preflight tree metadata differs")
            path = Path(child.path)
            if stat.S_ISDIR(child_metadata.st_mode):
                stack.append(path)
            elif stat.S_ISREG(child_metadata.st_mode):
                if child_metadata.st_nlink != 1:
                    raise V2IntegrityStop("foundation preflight file is linked")
                total += int(child_metadata.st_size)
                if total > MAXIMUM_STATE_SCRATCH_BYTES:
                    raise V2IntegrityStop(
                        "foundation preflight private bytes exceed ceiling"
                    )
            else:
                raise V2IntegrityStop("foundation preflight tree type differs")
    return total


def _foundation_preflight_owned_process_count() -> int:
    """Count the exact child-to-sudo ownership chain, bounded by the leaf ceiling."""

    count = 0
    pid = os.getpid()
    seen: set[int] = set()
    while pid > 1:
        if pid in seen or count >= MAXIMUM_PROCESSES:
            raise V2IntegrityStop("foundation preflight process chain differs")
        seen.add(pid)
        try:
            stat_fields = Path(f"/proc/{pid}/stat").read_text(
                encoding="ascii"
            ).split()
            cmdline = Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0")
            parent = int(stat_fields[3])
        except (IndexError, OSError, ValueError) as error:
            raise V2IntegrityStop(
                "foundation preflight process chain is unavailable"
            ) from error
        count += 1
        executable = cmdline[0] if cmdline else b""
        if executable == b"/usr/bin/sudo":
            return count
        pid = parent
    raise V2IntegrityStop("foundation preflight sudo ancestor is absent")


def _foundation_preflight_resource_sample() -> dict[str, int]:
    import torch

    cuda = torch.cuda
    if (
        cuda.is_available() is not True
        or cuda.device_count() != 1
        or cuda.current_device() != 0
    ):
        raise V2IntegrityStop("foundation preflight CUDA sampler differs")
    return {
        "configured_pools": MAXIMUM_CONFIGURED_POOLS,
        "cuda_allocated_bytes": int(cuda.memory_allocated(0)),
        "cuda_reserved_bytes": int(cuda.memory_reserved(0)),
        "process_count": _foundation_preflight_owned_process_count(),
        "rss_bytes": _current_process_rss_bytes(),
        "state_scratch_bytes": _foundation_preflight_tree_bytes(
            FOUNDATION_PREFLIGHT_PRIVATE_ROOT
        ),
    }


def _foundation_preflight_gpu_probe(
    *,
    gpu_inventory_runner: Callable[..., object] | None = None,
    gpu_process_runner: Callable[..., object] | None = None,
    torch_module: object | None = None,
) -> dict[str, object]:
    inventory_completed = (gpu_inventory_runner or subprocess.run)(
        (
            "/usr/bin/nvidia-smi",
            "--query-gpu=uuid,name,pci.bus_id,compute_cap,memory.total,memory.free",
            "--format=csv,noheader,nounits",
        ),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    inventory_output = getattr(inventory_completed, "stdout", None)
    if type(inventory_output) is not str:
        raise V2IntegrityStop("foundation preflight GPU inventory is absent")
    physical: dict[str, tuple[str, str, str, int, int]] = {}
    for line in inventory_output.splitlines():
        fields = tuple(part.strip() for part in line.split(","))
        if len(fields) != 6 or fields[0] in physical:
            raise V2IntegrityStop("foundation preflight GPU inventory differs")
        physical[fields[0]] = (
            fields[1],
            fields[2],
            fields[3],
            int(fields[4]),
            int(fields[5]),
        )
    if (
        set(physical) != {ASSIGNED_GPU_UUID, UNASSIGNED_GPU_UUID}
        or physical.get(ASSIGNED_GPU_UUID)
        != (
            "NVIDIA GeForce RTX 5080",
            "00000000:01:00.0",
            "12.0",
            16_303,
            physical.get(ASSIGNED_GPU_UUID, (None, None, None, None, -1))[4],
        )
        or physical.get(UNASSIGNED_GPU_UUID)
        != (
            "NVIDIA GeForce RTX 5070",
            "00000000:05:00.0",
            "12.0",
            12_227,
            physical.get(UNASSIGNED_GPU_UUID, (None, None, None, None, -1))[4],
        )
    ):
        raise V2IntegrityStop("foundation preflight physical GPU differs")
    process_completed = (gpu_process_runner or subprocess.run)(
        (
            "/usr/bin/nvidia-smi",
            "--query-compute-apps=gpu_uuid,pid",
            "--format=csv,noheader,nounits",
        ),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    process_output = getattr(process_completed, "stdout", None)
    if type(process_output) is not str:
        raise V2IntegrityStop("foundation preflight GPU processes are absent")
    unassigned_count = 0
    process_rows: list[tuple[str, int]] = []
    for line in process_output.splitlines():
        if not line.strip():
            continue
        fields = tuple(part.strip() for part in line.split(","))
        if len(fields) != 2 or fields[0] not in physical:
            raise V2IntegrityStop("foundation preflight GPU process row differs")
        pid = _integer(
            int(fields[1]), "foundation preflight GPU PID", minimum=1
        )
        process_rows.append((fields[0], pid))
        if fields[0] == UNASSIGNED_GPU_UUID:
            unassigned_count += 1
    if (
        len(set(process_rows)) != len(process_rows)
        or unassigned_count != 0
        or any(
            uuid == ASSIGNED_GPU_UUID and pid != os.getpid()
            for uuid, pid in process_rows
        )
    ):
        raise V2IntegrityStop("foundation preflight GPU ownership differs")
    if torch_module is None:
        import torch as torch_module  # type: ignore[no-redef]
    cuda = getattr(torch_module, "cuda", None)
    if (
        cuda is None
        or cuda.is_available() is not True
        or cuda.device_count() != 1
        or cuda.current_device() != 0
        or cuda.get_device_name(0) != "NVIDIA GeForce RTX 5080"
    ):
        raise V2IntegrityStop("foundation preflight logical GPU differs")
    return {
        "assigned_name": "NVIDIA GeForce RTX 5080",
        "assigned_uuid": ASSIGNED_GPU_UUID,
        "logical_device_count": 1,
        "logical_device_index": 0,
        "unassigned_compute_processes": 0,
        "unassigned_name": "NVIDIA GeForce RTX 5070",
        "unassigned_uuid": UNASSIGNED_GPU_UUID,
    }


def foundation_mirror_preflight_child_main(
    parent_mount_namespace: str,
    parent_network_namespace: str,
) -> int:
    namespace = validate_foundation_preflight_namespace_boundary(
        parent_mount_namespace=parent_mount_namespace,
        parent_network_namespace=parent_network_namespace,
    )
    sources = _source_inventory_snapshot()
    boundary = collect_foundation_preflight_child_boundary(
        namespace_boundary=namespace,
        source_inventory=sources,
    )

    def source_loader() -> list[dict[str, object]]:
        return _source_inventory_snapshot()

    evidence = run_foundation_mirror_preflight_child_injected(
        validate_boundary=lambda: boundary,
        sample_resources=_foundation_preflight_resource_sample,
        probe_gpu=_foundation_preflight_gpu_probe,
        source_inventory_loader=source_loader,
    )
    raw = canonical_json_bytes(evidence) + b"\n"
    if len(raw) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES:
        raise V2IntegrityStop("foundation preflight child output exceeds bound")
    descriptor = sys.stdout.buffer.fileno()
    view = memoryview(raw)
    while view:
        written = os.write(descriptor, view)
        if written <= 0:
            raise OSError("foundation preflight child output was short")
        view = view[written:]
    return 0


def _frozen_foundation_preflight_root_environment() -> dict[str, str]:
    return {
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "PATH": "/usr/sbin:/usr/bin:/sbin:/bin",
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONHASHSEED": "0",
        "PYTHONNOUSERSITE": "1",
        "PYTHONPATH": f"{REPOSITORY_ROOT}:{REPOSITORY_ROOT / 'src'}",
        "PYTHONSAFEPATH": "1",
        "PYTHONUTF8": "1",
    }


def _foundation_preflight_child_argv(
    *,
    parent_mount_namespace: str,
    parent_network_namespace: str,
) -> tuple[str, ...]:
    if (
        type(parent_mount_namespace) is not str
        or re.fullmatch(r"mnt:\[[0-9]+\]", parent_mount_namespace) is None
        or type(parent_network_namespace) is not str
        or re.fullmatch(r"net:\[[0-9]+\]", parent_network_namespace) is None
    ):
        raise V2IntegrityStop(
            "foundation preflight parent namespace attestation differs"
        )
    environment = _frozen_foundation_preflight_environment()
    return (
        "/usr/bin/setpriv",
        "--reuid=1000",
        "--regid=1000",
        "--clear-groups",
        "--inh-caps=-all",
        "--ambient-caps=-all",
        "--bounding-set=-all",
        "--no-new-privs",
        "--pdeathsig=SIGKILL",
        "/usr/bin/env",
        "-i",
        *(f"{name}={environment[name]}" for name in sorted(environment)),
        str(ANGLER_PYTHON),
        str(RUNNER_PATH),
        "--foundation-mirror-preflight-child",
        parent_mount_namespace,
        parent_network_namespace,
    )


def _foundation_preflight_mount_tmpfs() -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    mount_call = libc.mount
    mount_call.argtypes = (
        ctypes.c_char_p,
        ctypes.c_char_p,
        ctypes.c_char_p,
        ctypes.c_ulong,
        ctypes.c_char_p,
    )
    mount_call.restype = ctypes.c_int
    flags = 2 | 4 | 8  # MS_NOSUID | MS_NODEV | MS_NOEXEC
    result = mount_call(
        b"tmpfs",
        b"/opt/angler/scratch",
        b"tmpfs",
        flags,
        b"size=1073741824,mode=0700,uid=1000,gid=1000",
    )
    if result != 0:
        errno = ctypes.get_errno()
        raise OSError(errno, "foundation preflight tmpfs mount failed")


def _foundation_preflight_make_private_tree() -> None:
    for path in (
        FOUNDATION_PREFLIGHT_PRIVATE_ROOT,
        FOUNDATION_PREFLIGHT_TMP,
        FOUNDATION_PREFLIGHT_CACHE,
    ):
        os.mkdir(path, mode=0o700)
        os.chown(path, 1000, 1000)
        os.chmod(path, 0o700)


def _read_foundation_preflight_child_process(
    process: subprocess.Popen[bytes],
) -> tuple[bytes, bytes]:
    if process.stdout is None or process.stderr is None:
        raise V2IntegrityStop("foundation preflight child pipes are absent")
    streams = {
        process.stdout.fileno(): bytearray(),
        process.stderr.fileno(): bytearray(),
    }
    selector = selectors.DefaultSelector()
    deadline = time.monotonic() + FOUNDATION_PREFLIGHT_TIMEOUT_SECONDS
    try:
        for descriptor in streams:
            os.set_blocking(descriptor, False)
            selector.register(descriptor, selectors.EVENT_READ)
        while selector.get_map():
            remaining = deadline - time.monotonic()
            ready = selector.select(remaining) if remaining > 0.0 else []
            if not ready:
                raise TimeoutError("foundation preflight child timed out")
            for key, _events in ready:
                descriptor = int(key.fd)
                try:
                    block = os.read(descriptor, 64 * 1024)
                except BlockingIOError:
                    continue
                if not block:
                    selector.unregister(descriptor)
                    continue
                streams[descriptor].extend(block)
                if len(streams[descriptor]) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES:
                    raise V2IntegrityStop(
                        "foundation preflight child output exceeds bound"
                    )
        remaining = deadline - time.monotonic()
        if remaining <= 0.0:
            raise TimeoutError("foundation preflight child timed out")
        process.wait(timeout=remaining)
    except BaseException as primary:
        safe = _redacted_failure(primary, "FOUNDATION_PREFLIGHT_CHILD_FAILED")
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5.0)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=5.0)
        raise safe from None
    finally:
        selector.close()
    return bytes(streams[process.stdout.fileno()]), bytes(
        streams[process.stderr.fileno()]
    )


def _foundation_preflight_host_closure(
    *,
    scratch_metadata: os.stat_result,
    source_inventory_ref: str,
) -> dict[str, object]:
    payload = {
        "child_exit_terminal": True,
        "host_live_paths_absent": True,
        "host_private_path_absent": True,
        "host_scratch_device": int(scratch_metadata.st_dev),
        "host_scratch_gid": int(scratch_metadata.st_gid),
        "host_scratch_identity_unchanged": True,
        "host_scratch_inode": int(scratch_metadata.st_ino),
        "host_scratch_mode": f"{stat.S_IMODE(scratch_metadata.st_mode):04o}",
        "host_scratch_path": "/opt/angler/scratch",
        "host_scratch_uid": int(scratch_metadata.st_uid),
        "source_inventory_ref": _ref(
            source_inventory_ref, "foundation preflight host source inventory"
        ),
        "stdout_single_canonical_receipt": True,
    }
    return {
        **payload,
        "host_closure_ref": canonical_ref(
            "foundation-preflight-host-closure", payload
        ),
    }


def _rejoin_foundation_preflight_outer_namespaces(
    receipt: Mapping[str, object],
    *,
    namespace_reader: Callable[[Path], str] | None = None,
) -> dict[str, object]:
    """Bind the child's claimed parent namespaces to this exact host."""

    row = dict(receipt)
    proof = validate_foundation_preflight_namespace_proof(
        _canonical_mapping(
            row.get("namespace_proof"),
            "foundation preflight outer namespace proof",
        )
    )
    read_namespace = namespace_reader or os.readlink
    host_mount_namespace = read_namespace(Path("/proc/self/ns/mnt"))
    host_network_namespace = read_namespace(Path("/proc/self/ns/net"))
    if (
        re.fullmatch(r"mnt:\[[0-9]+\]", host_mount_namespace) is None
        or re.fullmatch(r"net:\[[0-9]+\]", host_network_namespace) is None
        or proof["parent_mount_namespace"] != host_mount_namespace
        or proof["parent_network_namespace"] != host_network_namespace
        or proof["self_mount_namespace"] == host_mount_namespace
        or proof["self_network_namespace"] == host_network_namespace
    ):
        raise V2IntegrityStop(
            "foundation preflight outer namespace binding differs"
        )
    return row


def _foundation_preflight_root_namespace_snapshot(
    *,
    namespace_reader: Callable[[Path], str] | None = None,
) -> dict[str, str]:
    """Capture private-root and host namespace identities while privileged."""

    read_namespace = namespace_reader or os.readlink
    snapshot = {
        "self_mount_namespace": read_namespace(Path("/proc/self/ns/mnt")),
        "self_network_namespace": read_namespace(Path("/proc/self/ns/net")),
        "parent_mount_namespace": read_namespace(Path("/proc/1/ns/mnt")),
        "parent_network_namespace": read_namespace(Path("/proc/1/ns/net")),
    }
    if (
        re.fullmatch(r"mnt:\[[0-9]+\]", snapshot["self_mount_namespace"])
        is None
        or re.fullmatch(r"net:\[[0-9]+\]", snapshot["self_network_namespace"])
        is None
        or re.fullmatch(r"mnt:\[[0-9]+\]", snapshot["parent_mount_namespace"])
        is None
        or re.fullmatch(r"net:\[[0-9]+\]", snapshot["parent_network_namespace"])
        is None
        or snapshot["self_mount_namespace"]
        == snapshot["parent_mount_namespace"]
        or snapshot["self_network_namespace"]
        == snapshot["parent_network_namespace"]
    ):
        raise V2IntegrityStop("foundation preflight root namespaces differ")
    return snapshot


def foundation_mirror_preflight_root_main() -> int:
    if (
        os.geteuid() != 0
        or os.getegid() != 0
        or dict(os.environ) != _frozen_foundation_preflight_root_environment()
        or Path.cwd() != REPOSITORY_ROOT
        or Path(sys.executable) != ANGLER_PYTHON
        or Path(__file__).resolve() != RUNNER_PATH
    ):
        raise V2IntegrityStop("foundation preflight root boundary differs")
    namespaces_before = _foundation_preflight_root_namespace_snapshot()
    base = Path("/opt/angler/scratch")
    base_descriptor = os.open(
        base,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        before = os.fstat(base_descriptor)
        if (
            not stat.S_ISDIR(before.st_mode)
            or stat.S_IMODE(before.st_mode) != 0o700
            or before.st_uid != 1000
            or before.st_gid != 1000
        ):
            raise V2IntegrityStop("foundation preflight host scratch differs")
        for name, label in (
            (
                FOUNDATION_PREFLIGHT_PRIVATE_ROOT.name,
                "foundation preflight host private path",
            ),
            (SCRATCH_ROOT.name, "foundation preflight host live scratch path"),
        ):
            try:
                os.stat(name, dir_fd=base_descriptor, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise V2IntegrityStop(f"{label} exists")
        _foundation_preflight_mount_tmpfs()
        _foundation_preflight_make_private_tree()
        network = subprocess.run(
            ("/usr/sbin/ip", "link", "set", "lo", "up"),
            check=True,
            capture_output=True,
            timeout=10,
            env={},
        )
        if network.stdout or network.stderr:
            raise V2IntegrityStop("foundation preflight network setup emitted output")
        child_process = subprocess.Popen(
            _foundation_preflight_child_argv(
                parent_mount_namespace=namespaces_before[
                    "parent_mount_namespace"
                ],
                parent_network_namespace=namespaces_before[
                    "parent_network_namespace"
                ],
            ),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=REPOSITORY_ROOT,
            env=_frozen_foundation_preflight_root_environment(),
        )
        try:
            child_stdout, child_stderr = _read_foundation_preflight_child_process(
                child_process
            )
        finally:
            for stream in (child_process.stdout, child_process.stderr):
                close = getattr(stream, "close", None)
                if callable(close):
                    close()
        if (
            child_process.returncode != 0
            or child_stderr
            or not child_stdout.endswith(b"\n")
            or child_stdout.count(b"\n") != 1
            or len(child_stdout) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES
        ):
            raise V2IntegrityStop("foundation preflight child failed")
        try:
            child_value = json.loads(child_stdout[:-1].decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise V2IntegrityStop(
                "foundation preflight child output is not JSON"
            ) from error
        if (
            type(child_value) is not dict
            or canonical_json_bytes(child_value) + b"\n" != child_stdout
        ):
            raise V2IntegrityStop(
                "foundation preflight child output is not canonical"
            )
        sources = _source_inventory_snapshot(
            expected_owner_uid=1000,
            expected_owner_gid=1000,
        )
        audit, boundary = validate_foundation_mirror_child_evidence(
            child_value,
            source_inventory=sources,
        )
        namespace_proof = validate_foundation_preflight_namespace_proof(
            _canonical_mapping(
                boundary.get("namespace_proof"),
                "foundation preflight root namespace proof",
            )
        )
        namespaces_after = _foundation_preflight_root_namespace_snapshot()
        if (
            namespaces_after != namespaces_before
            or any(
                namespace_proof[name] != value
                for name, value in namespaces_before.items()
            )
        ):
            raise V2IntegrityStop(
                "foundation preflight root namespace rejoin differs"
            )
        after = os.fstat(base_descriptor)
        if (
            (after.st_dev, after.st_ino) != (before.st_dev, before.st_ino)
            or stat.S_IMODE(after.st_mode) != stat.S_IMODE(before.st_mode)
            or after.st_uid != before.st_uid
            or after.st_gid != before.st_gid
        ):
            raise V2IntegrityStop("foundation preflight host scratch changed")
        for name, label in (
            (
                FOUNDATION_PREFLIGHT_PRIVATE_ROOT.name,
                "foundation preflight escaped its mount namespace",
            ),
            (SCRATCH_ROOT.name, "foundation preflight host live scratch appeared"),
        ):
            try:
                os.stat(name, dir_fd=base_descriptor, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise V2IntegrityStop(label)
        assert_all_live_paths_absent()
        closure = _foundation_preflight_host_closure(
            scratch_metadata=before,
            source_inventory_ref=canonical_ref("source-inventory", sources),
        )
        receipt = FoundationMirrorPreflightReceipt.from_audit(
            audit,
            source_inventory=sources,
            boundary=boundary,
            host_closure=closure,
        ).to_canonical()
        raw = canonical_json_bytes(receipt) + b"\n"
        if len(raw) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES:
            raise V2IntegrityStop("foundation preflight receipt exceeds bound")
        view = memoryview(raw)
        while view:
            written = os.write(sys.stdout.buffer.fileno(), view)
            if written <= 0:
                raise OSError("foundation preflight root output was short")
            view = view[written:]
        return 0
    finally:
        os.close(base_descriptor)


def _foundation_preflight_host_argv() -> tuple[str, ...]:
    root_environment = _frozen_foundation_preflight_root_environment()
    return (
        "/usr/bin/sudo",
        "-n",
        "/usr/bin/unshare",
        "--mount",
        "--net",
        "--fork",
        "--kill-child=SIGKILL",
        "--propagation",
        "private",
        "--",
        "/usr/bin/env",
        "-i",
        *(f"{name}={root_environment[name]}" for name in sorted(root_environment)),
        str(ANGLER_PYTHON),
        str(RUNNER_PATH),
        "--foundation-mirror-preflight-root",
    )


def _terminate_foundation_preflight_process_group(
    process: subprocess.Popen[bytes],
) -> None:
    failures: list[BaseException] = []
    try:
        os.killpg(process.pid, signal.SIGTERM)
    except ProcessLookupError:
        pass
    except BaseException as error:
        failures.append(
            _redacted_failure(error, "FOUNDATION_PREFLIGHT_TERM_FAILED")
        )
    deadline = time.monotonic() + 5.0
    while time.monotonic() < deadline:
        process.poll()
        try:
            os.killpg(process.pid, 0)
        except ProcessLookupError:
            break
        except PermissionError:
            pass
        time.sleep(0.05)
    else:
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "FOUNDATION_PREFLIGHT_KILL_FAILED")
            )
        deadline = time.monotonic() + 5.0
        while time.monotonic() < deadline:
            process.poll()
            try:
                os.killpg(process.pid, 0)
            except ProcessLookupError:
                break
            except PermissionError:
                pass
            time.sleep(0.05)
        else:
            failures.append(
                V2IntegrityStop("foundation preflight process group remains live")
            )
    try:
        if process.poll() is None:
            process.wait(timeout=5.0)
    except BaseException as error:
        failures.append(
            _redacted_failure(error, "FOUNDATION_PREFLIGHT_WAIT_FAILED")
        )
    if process.poll() is None:
        failures.append(V2IntegrityStop("foundation preflight process remains live"))
    if len(failures) == 1:
        raise failures[0]
    if failures:
        raise ExceptionGroup("foundation preflight teardown failed", failures)


def _read_foundation_preflight_process(
    process: subprocess.Popen[bytes],
) -> tuple[bytes, bytes]:
    if process.stdout is None or process.stderr is None:
        raise V2IntegrityStop("foundation preflight process pipes are absent")
    descriptors = {
        process.stdout.fileno(): ("stdout", bytearray()),
        process.stderr.fileno(): ("stderr", bytearray()),
    }
    selector = selectors.DefaultSelector()
    deadline = time.monotonic() + FOUNDATION_PREFLIGHT_TIMEOUT_SECONDS
    try:
        for descriptor in descriptors:
            os.set_blocking(descriptor, False)
            selector.register(descriptor, selectors.EVENT_READ)
        while selector.get_map():
            remaining = deadline - time.monotonic()
            ready = selector.select(remaining) if remaining > 0.0 else []
            if not ready:
                raise TimeoutError("foundation preflight process timed out")
            for key, _events in ready:
                descriptor = int(key.fd)
                _name, output = descriptors[descriptor]
                try:
                    block = os.read(descriptor, 64 * 1024)
                except BlockingIOError:
                    continue
                if not block:
                    selector.unregister(descriptor)
                    continue
                output.extend(block)
                if len(output) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES:
                    raise V2IntegrityStop(
                        "foundation preflight process output exceeds bound"
                    )
        remaining = deadline - time.monotonic()
        if remaining <= 0.0:
            raise TimeoutError("foundation preflight process timed out")
        process.wait(timeout=remaining)
        try:
            os.killpg(process.pid, 0)
        except ProcessLookupError:
            pass
        else:
            raise V2IntegrityStop(
                "foundation preflight process group survived terminal output"
            )
    except BaseException as primary:
        safe = _redacted_failure(primary, "FOUNDATION_PREFLIGHT_PROCESS_FAILED")
        try:
            _terminate_foundation_preflight_process_group(process)
        except BaseException as cleanup:
            raise ExceptionGroup(
                "foundation preflight process and teardown failed",
                [safe, _redacted_failure(cleanup, "FOUNDATION_PREFLIGHT_TEARDOWN_FAILED")],
            ) from None
        raise safe from None
    finally:
        selector.close()
    return bytes(descriptors[process.stdout.fileno()][1]), bytes(
        descriptors[process.stderr.fileno()][1]
    )


def run_foundation_mirror_preflight_live(
    *,
    process_factory: Callable[..., subprocess.Popen[bytes]] = subprocess.Popen,
) -> dict[str, object]:
    """Host launcher; it creates no persistent V2 path or artifact."""

    if not callable(process_factory):
        raise TypeError("foundation preflight process factory differs")
    assert_all_live_paths_absent()
    sources_before = _source_inventory_snapshot()
    scratch = Path("/opt/angler/scratch")
    scratch_metadata = os.lstat(scratch)
    if (
        not stat.S_ISDIR(scratch_metadata.st_mode)
        or stat.S_ISLNK(scratch_metadata.st_mode)
        or stat.S_IMODE(scratch_metadata.st_mode) != 0o700
        or scratch_metadata.st_uid != os.geteuid()
        or scratch_metadata.st_gid != os.getegid()
        or scratch.resolve(strict=True) != scratch
    ):
        raise V2IntegrityStop("foundation preflight host scratch differs")
    _require_absent(
        scratch / FOUNDATION_PREFLIGHT_PRIVATE_ROOT.name,
        "foundation preflight host private path",
    )
    argv = _foundation_preflight_host_argv()
    process: subprocess.Popen[bytes] | None = None
    try:
        process = process_factory(
            argv,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=REPOSITORY_ROOT,
            env={
                "LANG": "C.UTF-8",
                "LC_ALL": "C.UTF-8",
                "PATH": "/usr/bin:/bin",
            },
            start_new_session=True,
        )
        if (
            process_factory is subprocess.Popen
            and type(process) is not subprocess.Popen
        ) or getattr(process, "args", None) != argv:
            raise V2IntegrityStop("foundation preflight process identity differs")
        try:
            stdout, stderr = _read_foundation_preflight_process(process)
        finally:
            for stream in (process.stdout, process.stderr):
                close = getattr(stream, "close", None)
                if callable(close):
                    close()
        if process.returncode != 0 or stderr:
            raise V2IntegrityStop("foundation preflight wrapper failed")
    except BaseException as primary:
        safe = _redacted_failure(primary, "FOUNDATION_PREFLIGHT_LAUNCH_FAILED")
        if process is not None and process.poll() is None:
            try:
                _terminate_foundation_preflight_process_group(process)
            except BaseException as cleanup:
                raise ExceptionGroup(
                    "foundation preflight launch and cleanup failed",
                    [safe, _redacted_failure(cleanup, "FOUNDATION_PREFLIGHT_TEARDOWN_FAILED")],
                ) from None
        raise safe from None
    process = None
    if (
        not stdout.endswith(b"\n")
        or stdout.count(b"\n") != 1
        or len(stdout) > FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES
    ):
        raise V2IntegrityStop("foundation preflight receipt framing differs")
    try:
        value = json.loads(stdout[:-1].decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise V2IntegrityStop("foundation preflight receipt is not JSON") from error
    if type(value) is not dict or canonical_json_bytes(value) + b"\n" != stdout:
        raise V2IntegrityStop("foundation preflight receipt is not canonical")
    receipt = validate_foundation_mirror_preflight_receipt(
        value,
        source_inventory=sources_before,
    )
    receipt = _rejoin_foundation_preflight_outer_namespaces(receipt)
    expected_host_closure = _foundation_preflight_host_closure(
        scratch_metadata=scratch_metadata,
        source_inventory_ref=canonical_ref("source-inventory", sources_before),
    )
    if receipt["host_closure"] != expected_host_closure:
        raise V2IntegrityStop("foundation preflight outer host closure differs")
    sources_after = _source_inventory_snapshot()
    current_scratch = os.lstat(scratch)
    if (
        sources_after != sources_before
        or (current_scratch.st_dev, current_scratch.st_ino)
        != (scratch_metadata.st_dev, scratch_metadata.st_ino)
        or stat.S_IMODE(current_scratch.st_mode)
        != stat.S_IMODE(scratch_metadata.st_mode)
        or current_scratch.st_uid != scratch_metadata.st_uid
        or current_scratch.st_gid != scratch_metadata.st_gid
    ):
        raise V2IntegrityStop("foundation preflight host closure changed")
    _require_absent(
        scratch / FOUNDATION_PREFLIGHT_PRIVATE_ROOT.name,
        "foundation preflight escaped private path",
    )
    assert_all_live_paths_absent()
    return receipt


def _hash_pairs(value: Mapping[str, str], label: str) -> tuple[tuple[str, str], ...]:
    row = dict(value)
    if set(row) != BASELINE_HASH_NAMES:
        raise ValueError(f"{label} must contain the exact baseline hash inventory")
    for name, digest in row.items():
        safe_component(name, f"{label} name")
        _raw_digest(digest, f"{label} digest")
    return tuple(sorted(row.items()))


def _retained_lineage_hash_pairs(
    value: Mapping[str, str], label: str
) -> tuple[tuple[str, str], ...]:
    row = dict(value)
    if set(row) != RETAINED_LINEAGE_HASH_NAMES:
        raise ValueError(f"{label} must contain the exact raw core-file inventory")
    for name, digest in row.items():
        safe_component(name, f"{label} name")
        _raw_digest(digest, f"{label} digest")
    return tuple(sorted(row.items()))


def _private_root_identity(path: str | Path, label: str) -> tuple[str, int, int]:
    target = Path(path)
    if not target.is_absolute():
        raise ValueError(f"{label} must be absolute")
    metadata = os.lstat(target)
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
    ):
        raise V2InvariantError(f"{label} is not one owned real directory")
    resolved = str(target.resolve(strict=True))
    return resolved, int(metadata.st_dev), int(metadata.st_ino)


@dataclass(frozen=True, slots=True)
class _RetainedScopeTreeSnapshot:
    """Deterministic byte/topology commitment for one terminal private tree."""

    tree_ref: str
    entry_count: int
    directory_count: int
    regular_file_count: int
    total_bytes: int

    def __post_init__(self) -> None:
        _ref(self.tree_ref, "retained scope tree ref")
        entries = _integer(
            self.entry_count,
            "retained scope tree entries",
            minimum=1,
            maximum=MAXIMUM_RETAINED_SCOPE_ENTRIES,
        )
        directories = _integer(
            self.directory_count,
            "retained scope tree directories",
            minimum=1,
            maximum=entries,
        )
        files = _integer(
            self.regular_file_count,
            "retained scope tree regular files",
            minimum=0,
            maximum=entries,
        )
        _integer(
            self.total_bytes,
            "retained scope tree bytes",
            minimum=0,
            maximum=MAXIMUM_STATE_SCRATCH_BYTES,
        )
        if directories + files != entries:
            raise V2InvariantError("retained scope tree counts differ")

    def to_canonical(self) -> dict[str, object]:
        return {
            "directory_count": self.directory_count,
            "entry_count": self.entry_count,
            "regular_file_count": self.regular_file_count,
            "total_bytes": self.total_bytes,
            "tree_ref": self.tree_ref,
        }


def _terminal_scope_tree_snapshot_once(
    state_root: str | Path,
) -> _RetainedScopeTreeSnapshot:
    """Commit exact owned regular-file bytes without following any alias."""

    root = Path(state_root)
    identity = _private_root_identity(root, "terminal retained scope root")
    if identity[0] != str(root):
        raise V2IntegrityStop("terminal retained scope root is not canonical")
    root_flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    try:
        root_fd = os.open(root, root_flags)
    except OSError as error:
        raise V2IntegrityStop("terminal retained scope root changed") from error
    owner = (os.geteuid(), os.getegid())
    seen: set[tuple[int, int]] = set()
    tree_digest = hashlib.sha256(b"retained-scope-tree\x00")
    total_bytes = 0
    directory_count = 0
    regular_file_count = 0
    enumerated_entries = 1

    def commit_row(row: Mapping[str, object]) -> None:
        raw = canonical_json_bytes(dict(row))
        tree_digest.update(len(raw).to_bytes(8, "big"))
        tree_digest.update(raw)

    def stable_metadata(
        first: os.stat_result, second: os.stat_result
    ) -> bool:
        return (
            first.st_dev,
            first.st_ino,
            first.st_mode,
            first.st_uid,
            first.st_gid,
            first.st_nlink,
            first.st_size,
            first.st_mtime_ns,
            first.st_ctime_ns,
        ) == (
            second.st_dev,
            second.st_ino,
            second.st_mode,
            second.st_uid,
            second.st_gid,
            second.st_nlink,
            second.st_size,
            second.st_mtime_ns,
            second.st_ctime_ns,
        )

    def validate_common(metadata: os.stat_result, label: str) -> None:
        if (
            (metadata.st_uid, metadata.st_gid) != owner
            or stat.S_ISLNK(metadata.st_mode)
            or stat.S_IMODE(metadata.st_mode) & 0o022
            or int(metadata.st_dev) != identity[1]
        ):
            raise V2IntegrityStop(f"{label} metadata differs")
        inode = (int(metadata.st_dev), int(metadata.st_ino))
        if inode in seen:
            raise V2IntegrityStop(f"{label} inode aliases another entry")
        seen.add(inode)
        if len(seen) > MAXIMUM_RETAINED_SCOPE_ENTRIES:
            raise V2IntegrityStop("retained scope entry ceiling exceeded")

    def walk(
        directory_fd: int,
        parts: tuple[str, ...],
        before: os.stat_result,
        *,
        depth: int,
    ) -> None:
        nonlocal total_bytes, directory_count, regular_file_count
        nonlocal enumerated_entries
        if depth > 64:
            raise V2IntegrityStop("retained scope depth ceiling exceeded")
        validate_common(before, "retained scope directory")
        if not stat.S_ISDIR(before.st_mode):
            raise V2IntegrityStop("retained scope directory type differs")
        relative = "." if not parts else "/".join(parts)
        if len(relative.encode("utf-8")) > 4096:
            raise V2IntegrityStop("retained scope path ceiling exceeded")
        commit_row(
            {
                "device": int(before.st_dev),
                "inode": int(before.st_ino),
                "kind": "directory",
                "mode": stat.S_IMODE(before.st_mode),
                "nlink": int(before.st_nlink),
                "path": relative,
            }
        )
        directory_count += 1
        try:
            with os.scandir(directory_fd) as iterator:
                entries: list[os.DirEntry[str]] = []
                for entry in iterator:
                    enumerated_entries += 1
                    if enumerated_entries > MAXIMUM_RETAINED_SCOPE_ENTRIES:
                        raise V2IntegrityStop(
                            "retained scope entry ceiling exceeded"
                        )
                    entries.append(entry)
                entries.sort(key=lambda item: os.fsencode(item.name))
        except OSError as error:
            raise V2IntegrityStop("retained scope directory scan failed") from error
        for entry in entries:
            name = entry.name
            try:
                encoded_name = name.encode("utf-8")
            except (AttributeError, UnicodeEncodeError) as error:
                raise V2IntegrityStop("retained scope entry name differs") from error
            if (
                type(name) is not str
                or name in ("", ".", "..")
                or "/" in name
                or name != unicodedata.normalize("NFC", name)
                or not 1 <= len(encoded_name) <= 255
            ):
                raise V2IntegrityStop("retained scope entry name differs")
            try:
                entry_before = entry.stat(follow_symlinks=False)
            except OSError as error:
                raise V2IntegrityStop(
                    "retained scope entry changed before inspection"
                ) from error
            entry_parts = (*parts, name)
            entry_relative = "/".join(entry_parts)
            if len(entry_relative.encode("utf-8")) > 4096:
                raise V2IntegrityStop("retained scope path ceiling exceeded")
            if stat.S_ISDIR(entry_before.st_mode):
                flags = root_flags
                try:
                    child_fd = os.open(name, flags, dir_fd=directory_fd)
                except OSError as error:
                    raise V2IntegrityStop(
                        "retained scope directory changed while opening"
                    ) from error
                try:
                    opened = os.fstat(child_fd)
                    if not stable_metadata(entry_before, opened):
                        raise V2IntegrityStop(
                            "retained scope directory inode changed"
                        )
                    walk(child_fd, entry_parts, opened, depth=depth + 1)
                    after = os.fstat(child_fd)
                    current = os.stat(
                        name, dir_fd=directory_fd, follow_symlinks=False
                    )
                    if not stable_metadata(opened, after) or not stable_metadata(
                        after, current
                    ):
                        raise V2IntegrityStop(
                            "retained scope directory changed during inventory"
                        )
                finally:
                    os.close(child_fd)
            elif stat.S_ISREG(entry_before.st_mode):
                flags = (
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0)
                )
                try:
                    file_fd = os.open(name, flags, dir_fd=directory_fd)
                except OSError as error:
                    raise V2IntegrityStop(
                        "retained scope file changed while opening"
                    ) from error
                try:
                    opened = os.fstat(file_fd)
                    validate_common(opened, "retained scope regular file")
                    if (
                        not stable_metadata(entry_before, opened)
                        or not stat.S_ISREG(opened.st_mode)
                        or opened.st_nlink != 1
                        or opened.st_size < 0
                    ):
                        raise V2IntegrityStop(
                            "retained scope regular file differs"
                        )
                    digest = hashlib.sha256()
                    observed_bytes = 0
                    while True:
                        chunk = os.read(file_fd, 1024 * 1024)
                        if not chunk:
                            break
                        observed_bytes += len(chunk)
                        total_bytes += len(chunk)
                        if total_bytes > MAXIMUM_STATE_SCRATCH_BYTES:
                            raise V2IntegrityStop(
                                "retained scope byte ceiling exceeded"
                            )
                        digest.update(chunk)
                    after = os.fstat(file_fd)
                    current = os.stat(
                        name, dir_fd=directory_fd, follow_symlinks=False
                    )
                    if (
                        observed_bytes != opened.st_size
                        or not stable_metadata(opened, after)
                        or not stable_metadata(after, current)
                    ):
                        raise V2IntegrityStop(
                            "retained scope file changed during inventory"
                        )
                    commit_row(
                        {
                            "bytes": observed_bytes,
                            "device": int(opened.st_dev),
                            "inode": int(opened.st_ino),
                            "kind": "regular-file",
                            "mode": stat.S_IMODE(opened.st_mode),
                            "nlink": int(opened.st_nlink),
                            "path": entry_relative,
                            "sha256": digest.hexdigest(),
                        }
                    )
                    regular_file_count += 1
                finally:
                    os.close(file_fd)
            else:
                raise V2IntegrityStop(
                    "retained scope contains an unexpected filesystem entry"
                )
        try:
            with os.scandir(directory_fd) as iterator:
                after_names_list: list[str] = []
                for item in iterator:
                    if len(after_names_list) >= len(entries):
                        raise V2IntegrityStop(
                            "retained scope directory entries changed"
                        )
                    after_names_list.append(item.name)
                after_names = tuple(sorted(after_names_list, key=os.fsencode))
        except OSError as error:
            raise V2IntegrityStop("retained scope directory rescan failed") from error
        if after_names != tuple(item.name for item in entries):
            raise V2IntegrityStop("retained scope directory entries changed")

    try:
        opened_root = os.fstat(root_fd)
        current_root = os.lstat(root)
        if (
            not stable_metadata(opened_root, current_root)
            or stat.S_IMODE(opened_root.st_mode) != 0o700
            or (int(opened_root.st_dev), int(opened_root.st_ino))
            != identity[1:]
        ):
            raise V2IntegrityStop("terminal retained scope root identity differs")
        walk(root_fd, (), opened_root, depth=0)
        final_root = os.fstat(root_fd)
        current_root = os.lstat(root)
        if not stable_metadata(opened_root, final_root) or not stable_metadata(
            final_root, current_root
        ):
            raise V2IntegrityStop(
                "terminal retained scope root changed during inventory"
            )
    finally:
        os.close(root_fd)
    tree_ref = "sha256:" + tree_digest.hexdigest()
    return _RetainedScopeTreeSnapshot(
        tree_ref=tree_ref,
        entry_count=len(seen),
        directory_count=directory_count,
        regular_file_count=regular_file_count,
        total_bytes=total_bytes,
    )


def _terminal_scope_tree_snapshot(
    state_root: str | Path,
) -> _RetainedScopeTreeSnapshot:
    """Require two identical terminal passes before accepting a tree."""

    first = _terminal_scope_tree_snapshot_once(state_root)
    second = _terminal_scope_tree_snapshot_once(state_root)
    if first != second:
        raise V2IntegrityStop("terminal retained scope changed between inventories")
    return first


def _raw_private_regular_sha256(path: Path, *, parent: Path) -> str:
    """Hash one direct owned regular file without semantic/open-database checks."""

    if not path.is_absolute() or path.parent != parent:
        raise V2IntegrityStop("retained lineage core-file path differs")
    try:
        before = os.lstat(path)
    except OSError as error:
        raise V2IntegrityStop("retained lineage core file is unavailable") from error
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or before.st_nlink != 1
        or (before.st_uid, before.st_gid) != (os.geteuid(), os.getegid())
        or stat.S_IMODE(before.st_mode) & 0o022
        or before.st_size < 0
    ):
        raise V2IntegrityStop("retained lineage core-file metadata differs")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_NONBLOCK", 0)
    )
    try:
        descriptor = os.open(path, flags)
    except OSError as error:
        raise V2IntegrityStop("retained lineage core file changed") from error
    try:
        opened = os.fstat(descriptor)
        if (
            (opened.st_dev, opened.st_ino, opened.st_mode, opened.st_size)
            != (before.st_dev, before.st_ino, before.st_mode, before.st_size)
            or not stat.S_ISREG(opened.st_mode)
        ):
            raise V2IntegrityStop("retained lineage core-file inode changed")
        digest = hashlib.sha256()
        observed = 0
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            observed += len(chunk)
            if observed > MAXIMUM_STATE_SCRATCH_BYTES:
                raise V2IntegrityStop("retained lineage core-file ceiling exceeded")
            digest.update(chunk)
        after = os.fstat(descriptor)
        current = os.lstat(path)
        stable = (
            opened.st_dev,
            opened.st_ino,
            opened.st_mode,
            opened.st_uid,
            opened.st_gid,
            opened.st_nlink,
            opened.st_size,
            opened.st_mtime_ns,
            opened.st_ctime_ns,
        )
        if (
            observed != opened.st_size
            or stable
            != (
                after.st_dev,
                after.st_ino,
                after.st_mode,
                after.st_uid,
                after.st_gid,
                after.st_nlink,
                after.st_size,
                after.st_mtime_ns,
                after.st_ctime_ns,
            )
            or stable
            != (
                current.st_dev,
                current.st_ino,
                current.st_mode,
                current.st_uid,
                current.st_gid,
                current.st_nlink,
                current.st_size,
                current.st_mtime_ns,
                current.st_ctime_ns,
            )
        ):
            raise V2IntegrityStop("retained lineage core file changed while hashing")
        return digest.hexdigest()
    finally:
        os.close(descriptor)


def _raw_retained_lineage_state(
    owner: object,
) -> tuple[
    tuple[str, int, int],
    tuple[tuple[str, str], ...],
    _RetainedScopeTreeSnapshot,
]:
    """Bind failure bytes without requiring a scientifically quiescent state."""

    if type(owner) is not V2LineageOwner:
        raise TypeError("retained lineage owner differs")
    owner._assert_binding()
    identity = _private_root_identity(owner.root, "retained lineage root")
    paths = owner.paths
    core = {
        "store": getattr(paths, "store", None),
        "journal": getattr(paths, "journal", None),
        "learner": getattr(paths, "learner", None),
    }
    if any(not isinstance(path, Path) for path in core.values()):
        raise V2IntegrityStop("retained lineage core-file inventory differs")
    hashes = _retained_lineage_hash_pairs(
        {
            name: _raw_private_regular_sha256(path, parent=owner.root)
            for name, path in core.items()
        },
        "retained lineage raw core hashes",
    )
    tree = _terminal_scope_tree_snapshot(owner.root)
    return identity, hashes, tree


@dataclass(frozen=True, slots=True)
class BaselineSeal:
    purpose: Purpose
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    root: str
    hashes: tuple[tuple[str, str], ...]
    neutral_episode_refs: tuple[str, ...]
    neutral_chain_ref: str
    bootstrap_episode_ref: str
    genesis_competence_digest: str
    model_ref: str
    encoder_ref: str
    quiescent: bool

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        _ref(self.replicate_commitment, "baseline replicate commitment")
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("baseline arm differs")
        root = Path(self.root)
        root_identity = _private_root_identity(root, "baseline root")
        if root_identity[0] != self.root:
            raise V2InvariantError("baseline root is not a canonical resolved path")
        if self.hashes != _hash_pairs(dict(self.hashes), "baseline hashes"):
            raise V2InvariantError("baseline hashes are not canonical")
        if (
            type(self.neutral_episode_refs) is not tuple
            or len(self.neutral_episode_refs) != 12
            or len(set(self.neutral_episode_refs)) != 12
        ):
            raise V2InvariantError("baseline neutral fixture refs differ")
        for value in self.neutral_episode_refs:
            _ref(value, "baseline neutral episode ref")
        for label, value in (
            ("neutral chain ref", self.neutral_chain_ref),
            ("bootstrap episode ref", self.bootstrap_episode_ref),
            ("genesis competence digest", self.genesis_competence_digest),
            ("model ref", self.model_ref),
            ("encoder ref", self.encoder_ref),
        ):
            _ref(value, label)
        if self.bootstrap_episode_ref in self.neutral_episode_refs:
            raise V2InvariantError("neutral fixture allowlist includes bootstrap")
        if self.quiescent is not True:
            raise V2InvariantError("baseline must be quiescent before sealing")

    @property
    def seal_ref(self) -> str:
        return canonical_ref("baseline-seal", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "hashes": dict(self.hashes),
            "neutral_episode_refs": list(self.neutral_episode_refs),
            "neutral_chain_ref": self.neutral_chain_ref,
            "bootstrap_episode_ref": self.bootstrap_episode_ref,
            "genesis_competence_digest": self.genesis_competence_digest,
            "model_ref": self.model_ref,
            "encoder_ref": self.encoder_ref,
            "purpose": self.purpose,
            "quiescent": self.quiescent,
            "replicate_commitment": self.replicate_commitment,
            "root": self.root,
            "schema": BASELINE_SEAL_SCHEMA,
        }


def validate_genesis_pair(
    in_hashes: Mapping[str, str],
    io_hashes: Mapping[str, str],
    *,
    in_root: str | Path,
    io_root: str | Path,
) -> dict[str, str]:
    left = dict(_hash_pairs(in_hashes, "IN genesis"))
    right = dict(_hash_pairs(io_hashes, "IO genesis"))
    if left != right:
        raise V2InvariantError("IN/IO learner/store/journal genesis differs")
    roots = (Path(in_root), Path(io_root))
    identities = (
        _private_root_identity(roots[0], "IN genesis root"),
        _private_root_identity(roots[1], "IO genesis root"),
    )
    if identities[0] == identities[1] or identities[0][0] == identities[1][0]:
        raise V2InvariantError("IN/IO mutable roots alias")
    return left


@dataclass(frozen=True, slots=True)
class CloneTerminalEvidence:
    task_id: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    source_root: str
    clone_root: str
    source_before: tuple[tuple[str, str], ...]
    source_after: tuple[tuple[str, str], ...]
    clone_before: tuple[tuple[str, str], ...]
    clone_terminal: tuple[tuple[str, str], ...]
    quiescent: bool
    cognee_scope_roots: tuple[str, ...] = ()
    allocation_ref: str | None = None

    def __post_init__(self) -> None:
        _ref(self.task_id, "clone task id")
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("clone terminal arm differs")
        roots = (Path(self.source_root), Path(self.clone_root))
        identities = (
            _private_root_identity(roots[0], "clone source root"),
            _private_root_identity(roots[1], "disposable clone root"),
        )
        if (
            identities[0][0] != self.source_root
            or identities[1][0] != self.clone_root
            or identities[0] == identities[1]
            or identities[0][0] == identities[1][0]
        ):
            raise V2InvariantError("clone root aliases its source baseline")
        for label, row in (
            ("source before", self.source_before),
            ("source after", self.source_after),
            ("clone before", self.clone_before),
            ("clone terminal", self.clone_terminal),
        ):
            if row != _hash_pairs(dict(row), label):
                raise V2InvariantError(f"{label} hashes are not canonical")
        if self.source_before != self.source_after:
            raise V2IntegrityStop("frozen source baseline changed during clone use")
        if self.clone_before != self.source_before:
            raise V2IntegrityStop("disposable clone does not match frozen baseline")
        if self.quiescent is not True:
            raise V2IntegrityStop("disposable clone was not quiescent at disposition")
        if type(self.cognee_scope_roots) is not tuple:
            raise TypeError("clone Cognee scope roots must be a tuple")
        if self.allocation_ref is not None:
            _ref(self.allocation_ref, "clone path allocation ref")
        cleanup_paths = (self.clone_root, *self.cognee_scope_roots)
        if len(set(cleanup_paths)) != len(cleanup_paths):
            raise V2InvariantError("clone cleanup paths alias lexically")
        cleanup_identities = [identities[1]]
        for value in self.cognee_scope_roots:
            path = Path(value)
            if not path.is_absolute() or str(path) != value or ".." in path.parts:
                raise V2InvariantError("clone Cognee scope path is not canonical")
            identity = _private_root_identity(path, "clone Cognee scope root")
            if identity[0] != value or identity[1:] in {
                identities[0][1:],
                identities[1][1:],
            }:
                raise V2InvariantError("clone Cognee scope aliases runtime state")
            cleanup_identities.append(identity)
        if (
            len({item[0] for item in cleanup_identities})
            != len(cleanup_identities)
            or len({item[1:] for item in cleanup_identities})
            != len(cleanup_identities)
        ):
            raise V2InvariantError("clone cleanup roots alias one another")

    @property
    def terminal_ref(self) -> str:
        return canonical_ref("clone-terminal", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "allocation_ref": self.allocation_ref,
            "clone_before": dict(self.clone_before),
            "clone_root": self.clone_root,
            "clone_terminal": dict(self.clone_terminal),
            "cognee_scope_roots": list(self.cognee_scope_roots),
            "quiescent": self.quiescent,
            "schema": CLONE_TERMINAL_SCHEMA,
            "source_after": dict(self.source_after),
            "source_before": dict(self.source_before),
            "source_root": self.source_root,
            "task_id": self.task_id,
        }


