CongruenceDisposition = Literal["UNKNOWN", "SATISFIED", "VIOLATED"]


@dataclass(frozen=True, slots=True)
class ProcedureOutcomeCongruenceWitnessV1:
    task_id: str
    arm: Arm
    attempt_receipt_ref: str
    selected_trace_ref: str | None
    execution_request_ref: str | None
    execution_receipt_ref: str | None
    response_ref: str | None
    objective_judgment_ref: str | None
    selected_trace_bound: bool | None
    response_bound: bool | None
    response_conforms: bool | None
    objective_success: bool | None
    selected_grammar_class: str | None
    response_grammar_class: str | None
    disposition: CongruenceDisposition

    def __post_init__(self) -> None:
        _ref(self.task_id, "congruence task id")
        validate_arm(self.arm)
        _ref(self.attempt_receipt_ref, "congruence attempt receipt ref")
        refs = (
            self.selected_trace_ref,
            self.execution_request_ref,
            self.execution_receipt_ref,
            self.response_ref,
            self.objective_judgment_ref,
        )
        for value in refs:
            if value is not None:
                _ref(value, "congruence artifact ref")
        booleans = (
            self.selected_trace_bound,
            self.response_bound,
            self.response_conforms,
            self.objective_success,
        )
        if any(value is not None and type(value) is not bool for value in booleans):
            raise TypeError("congruence booleans must be bool or None")
        for value in (self.selected_grammar_class, self.response_grammar_class):
            if value is not None:
                _text(value, "public grammar class", 128)
        missing = any(value is None for value in (*refs, *booleans))
        if missing:
            expected = "UNKNOWN"
        elif all(booleans):
            expected = "SATISFIED"
        else:
            expected = "VIOLATED"
        if self.disposition != expected:
            raise V2InvariantError("congruence disposition differs from evidence")

    @property
    def binding_mismatch(self) -> bool:
        return self.selected_trace_bound is False or self.response_bound is False

    @property
    def witness_ref(self) -> str:
        return canonical_ref("procedure-outcome-congruence", self.to_canonical())

    def assert_integrity(self) -> None:
        if self.binding_mismatch:
            raise V2IntegrityStop("observed selected/executed/judged binding mismatch")

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "attempt_receipt_ref": self.attempt_receipt_ref,
            "disposition": self.disposition,
            "execution_receipt_ref": self.execution_receipt_ref,
            "execution_request_ref": self.execution_request_ref,
            "objective_judgment_ref": self.objective_judgment_ref,
            "objective_success": self.objective_success,
            "response_bound": self.response_bound,
            "response_conforms": self.response_conforms,
            "response_grammar_class": self.response_grammar_class,
            "response_ref": self.response_ref,
            "schema": CONGRUENCE_WITNESS_SCHEMA,
            "selected_grammar_class": self.selected_grammar_class,
            "selected_trace_bound": self.selected_trace_bound,
            "selected_trace_ref": self.selected_trace_ref,
            "task_id": self.task_id,
        }


def make_congruence_witness(
    *,
    task_id: str,
    arm: Arm,
    attempt_receipt_ref: str,
    selected_trace_ref: str | None,
    execution_request_ref: str | None,
    execution_receipt_ref: str | None,
    response_ref: str | None,
    objective_judgment_ref: str | None,
    selected_trace_bound: bool | None,
    response_bound: bool | None,
    response_conforms: bool | None,
    objective_success: bool | None,
    selected_grammar_class: str | None,
    response_grammar_class: str | None,
) -> ProcedureOutcomeCongruenceWitnessV1:
    refs = (
        selected_trace_ref,
        execution_request_ref,
        execution_receipt_ref,
        response_ref,
        objective_judgment_ref,
    )
    booleans = (
        selected_trace_bound,
        response_bound,
        response_conforms,
        objective_success,
    )
    disposition: CongruenceDisposition
    if any(value is None for value in (*refs, *booleans)):
        disposition = "UNKNOWN"
    elif all(booleans):
        disposition = "SATISFIED"
    else:
        disposition = "VIOLATED"
    return ProcedureOutcomeCongruenceWitnessV1(
        task_id=task_id,
        arm=arm,
        attempt_receipt_ref=attempt_receipt_ref,
        selected_trace_ref=selected_trace_ref,
        execution_request_ref=execution_request_ref,
        execution_receipt_ref=execution_receipt_ref,
        response_ref=response_ref,
        objective_judgment_ref=objective_judgment_ref,
        selected_trace_bound=selected_trace_bound,
        response_bound=response_bound,
        response_conforms=response_conforms,
        objective_success=objective_success,
        selected_grammar_class=selected_grammar_class,
        response_grammar_class=response_grammar_class,
        disposition=disposition,
    )


@dataclass(frozen=True, slots=True)
class AttemptStage:
    purpose: Purpose
    phase: Phase
    task_id: str
    public_task_ref: str
    replicate: str
    replicate_commitment: str
    family: Family
    task_ordinal: int
    arm: Arm
    block_ordinal: int
    arm_position: int
    history_plan_ref: str | None
    prompt_plan_ref: str
    proposal_prompt_ref: str | None
    proposal_prompt_tokens: int | None

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        validate_phase(self.phase)
        _ref(self.task_id, "attempt-stage task id")
        _ref(self.public_task_ref, "attempt-stage public task ref")
        _ref(self.replicate_commitment, "attempt-stage replicate commitment")
        if type(self.replicate) is not str or re.fullmatch(
            r"(?:qualification|replicate)-[0-9]{2}", self.replicate
        ) is None:
            raise ValueError("attempt-stage replicate label differs")
        validate_family(self.family)
        _integer(self.task_ordinal, "attempt-stage task ordinal", maximum=14)
        validate_arm(self.arm)
        _integer(self.block_ordinal, "attempt-stage block ordinal")
        _integer(self.arm_position, "attempt-stage arm position", maximum=7)
        if self.arm == "N0_NATIVE_NO_HISTORY":
            if self.history_plan_ref is not None:
                raise V2InvariantError("N0 stage cannot claim persistent history")
            _ref(self.proposal_prompt_ref, "attempt-stage native prompt ref")
            _integer(
                self.proposal_prompt_tokens,
                "attempt-stage native prompt tokens",
                minimum=1,
                maximum=4096,
            )
        else:
            _ref(self.history_plan_ref, "attempt-stage history plan ref")
            _ref(self.proposal_prompt_ref, "attempt-stage proposal prompt ref")
            _integer(
                self.proposal_prompt_tokens,
                "attempt-stage proposal prompt tokens",
                minimum=1,
                maximum=4096,
            )
        _ref(self.prompt_plan_ref, "attempt-stage prompt plan ref")

    @classmethod
    def from_schedule(
        cls,
        scheduled: ScheduledAttempt,
        prompt_plan: PromptPlan,
    ) -> "AttemptStage":
        if type(scheduled) is not ScheduledAttempt:
            raise TypeError("scheduled attempt differs")
        if (
            type(prompt_plan) is not PromptPlan
            or prompt_plan.arm != scheduled.arm
            or prompt_plan.task_id != scheduled.task_id
        ):
            raise V2InvariantError("scheduled prompt plan differs")
        return cls(
            purpose=scheduled.purpose,
            phase=scheduled.phase,
            task_id=scheduled.task_id,
            public_task_ref=public_task_ref(scheduled.task),
            replicate=str(scheduled.task["replicate"]),
            replicate_commitment=scheduled.replicate_commitment,
            family=scheduled.family,
            task_ordinal=int(scheduled.task["ordinal"]),
            arm=scheduled.arm,
            block_ordinal=scheduled.block_ordinal,
            arm_position=scheduled.arm_position,
            history_plan_ref=(
                None
                if scheduled.arm == "N0_NATIVE_NO_HISTORY"
                else prompt_plan.history_plan.plan_ref
            ),
            prompt_plan_ref=prompt_plan.plan_ref,
            proposal_prompt_ref=prompt_plan.prompt_ref,
            proposal_prompt_tokens=len(prompt_plan.token_ids),
        )

    @property
    def stage_ref(self) -> str:
        return canonical_ref("attempt-stage", self.to_canonical())

    @property
    def attempt_receipt_ref(self) -> str:
        payload = {
            "arm": self.arm,
            "nonauthorization": (
                "LOCAL_SYNTHETIC_NONAUTHORIZING_ATTEMPT; not an Action, "
                "prospective authorization, EvaluationReceipt, PromotionDecision, "
                "or external-effect permission"
            ),
            "phase": self.phase,
            "protocol_identity": PROTOCOL_IDENTITY,
            "public_task_ref": self.public_task_ref,
            "purpose": self.purpose,
            "schema": ATTEMPT_RECEIPT_SCHEMA,
            "stage_ref": self.stage_ref,
            "task_id": self.task_id,
            "task_ordinal": self.task_ordinal,
        }
        return canonical_ref("attempt-receipt", payload)

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "arm_position": self.arm_position,
            "block_ordinal": self.block_ordinal,
            "family": self.family,
            "history_plan_ref": self.history_plan_ref,
            "phase": self.phase,
            "proposal_prompt_ref": self.proposal_prompt_ref,
            "proposal_prompt_tokens": self.proposal_prompt_tokens,
            "prompt_plan_ref": self.prompt_plan_ref,
            "protocol_identity": PROTOCOL_IDENTITY,
            "public_task_ref": self.public_task_ref,
            "purpose": self.purpose,
            "replicate": self.replicate,
            "replicate_commitment": self.replicate_commitment,
            "schema": ATTEMPT_STAGE_SCHEMA,
            "task_id": self.task_id,
        }


@dataclass(frozen=True, slots=True)
class AttemptObservation:
    """Runner-facing result of one proposal and optional execution call."""

    task_id: str
    arm: Arm
    proposal_admitted: bool
    proposals: tuple[str, ...]
    selected_index: int | None
    selected_trace: str | None
    raw_response: str
    proposal_generation_ref: str
    proposal_prompt_ref: str
    proposal_prompt_tokens: int
    proposal_output_tokens: int
    execution_request_ref: str | None
    execution_receipt_ref: str | None
    execution_prompt_ref: str | None
    execution_prompt_tokens: int | None
    execution_output_tokens: int | None
    selected_trace_bound: bool | None
    response_bound: bool | None
    selected_grammar_class: str | None
    response_grammar_class: str | None
    resolution_ref: str | None = None
    prospective_reservation_ref: str | None = None
    prospective_batch_ref: str | None = None
    recalled_record_refs: tuple[str, ...] = ()
    clone_lifecycle: CloneLifecycleEvidence | None = None

    def __post_init__(self) -> None:
        _ref(self.task_id, "attempt observation task id")
        validate_arm(self.arm)
        if type(self.proposal_admitted) is not bool:
            raise TypeError("proposal admission must be bool")
        for value in self.proposals:
            _text(value, "proposal", 8_192)
        if self.proposal_admitted:
            if (
                len(self.proposals) != PROPOSAL_COUNT
                or len(set(self.proposals)) != PROPOSAL_COUNT
                or type(self.selected_index) is not int
                or not 0 <= self.selected_index < PROPOSAL_COUNT
                or self.selected_trace != self.proposals[self.selected_index]
            ):
                raise V2InvariantError("admitted proposal selection binding differs")
            if (
                type(self.raw_response) is not str
                or len(self.raw_response) > 16_384
                or self.raw_response != unicodedata.normalize("NFC", self.raw_response)
            ):
                raise ValueError("raw response must be bounded NFC text")
            required = (
                self.execution_request_ref,
                self.execution_receipt_ref,
                self.execution_prompt_ref,
                self.execution_prompt_tokens,
                self.execution_output_tokens,
                self.selected_trace_bound,
                self.response_bound,
            )
            if any(value is None for value in required):
                raise V2InvariantError("admitted proposal lacks execution evidence")
        else:
            if (
                self.proposals
                or self.selected_index is not None
                or self.selected_trace is not None
                or self.raw_response != ""
                or any(
                    value is not None
                    for value in (
                        self.execution_request_ref,
                        self.execution_receipt_ref,
                        self.execution_prompt_ref,
                        self.execution_prompt_tokens,
                        self.execution_output_tokens,
                        self.selected_trace_bound,
                        self.response_bound,
                        self.selected_grammar_class,
                        self.response_grammar_class,
                        self.resolution_ref,
                        self.prospective_reservation_ref,
                        self.prospective_batch_ref,
                    )
                )
            ):
                raise V2InvariantError("malformed proposal acquired execution material")
        for label, value in (
            ("proposal_generation_ref", self.proposal_generation_ref),
            ("proposal_prompt_ref", self.proposal_prompt_ref),
        ):
            _ref(value, label)
        for label, value in (
            ("execution_request_ref", self.execution_request_ref),
            ("execution_receipt_ref", self.execution_receipt_ref),
            ("execution_prompt_ref", self.execution_prompt_ref),
            ("resolution_ref", self.resolution_ref),
            ("prospective_reservation_ref", self.prospective_reservation_ref),
            ("prospective_batch_ref", self.prospective_batch_ref),
        ):
            if value is not None:
                _ref(value, label)
        _integer(
            self.proposal_prompt_tokens,
            "proposal prompt tokens",
            minimum=1,
            maximum=4096,
        )
        _integer(
            self.proposal_output_tokens,
            "proposal output tokens",
            minimum=1,
            maximum=MAXIMUM_OUTPUT_TOKENS,
        )
        if self.execution_prompt_tokens is not None:
            _integer(
                self.execution_prompt_tokens,
                "execution prompt tokens",
                minimum=1,
                maximum=4096,
            )
        if self.execution_output_tokens is not None:
            _integer(
                self.execution_output_tokens,
                "execution output tokens",
                minimum=1,
                maximum=MAXIMUM_OUTPUT_TOKENS,
            )
        for value in (self.selected_trace_bound, self.response_bound):
            if value is not None and type(value) is not bool:
                raise TypeError("execution binding evidence must be bool or None")
        for value in (self.selected_grammar_class, self.response_grammar_class):
            if value is not None:
                _text(value, "public grammar class", 128)
        if (
            type(self.recalled_record_refs) is not tuple
            or len(self.recalled_record_refs) > 12
            or len(set(self.recalled_record_refs)) != len(self.recalled_record_refs)
        ):
            raise V2InvariantError("recalled record refs are not bounded and unique")
        for value in self.recalled_record_refs:
            _ref(value, "recalled record ref")
        if self.arm == "N0_NATIVE_NO_HISTORY" and self.recalled_record_refs:
            raise V2InvariantError("N0 received persistent recalled records")
        if self.clone_lifecycle is not None and (
            type(self.clone_lifecycle) is not CloneLifecycleEvidence
            or self.clone_lifecycle.task_id != self.task_id
            or self.clone_lifecycle.arm != self.arm
        ):
            raise V2InvariantError("clone lifecycle does not bind the attempt")

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "clone_lifecycle_ref": (
                None
                if self.clone_lifecycle is None
                else self.clone_lifecycle.lifecycle_ref
            ),
            "execution_output_tokens": self.execution_output_tokens,
            "execution_prompt_ref": self.execution_prompt_ref,
            "execution_prompt_tokens": self.execution_prompt_tokens,
            "execution_receipt_ref": self.execution_receipt_ref,
            "execution_request_ref": self.execution_request_ref,
            "proposal_admitted": self.proposal_admitted,
            "proposal_generation_ref": self.proposal_generation_ref,
            "proposal_output_tokens": self.proposal_output_tokens,
            "proposal_prompt_ref": self.proposal_prompt_ref,
            "proposal_prompt_tokens": self.proposal_prompt_tokens,
            "proposals": list(self.proposals),
            "prospective_batch_ref": self.prospective_batch_ref,
            "prospective_reservation_ref": self.prospective_reservation_ref,
            "raw_response": self.raw_response,
            "recalled_record_refs": list(self.recalled_record_refs),
            "resolution_ref": self.resolution_ref,
            "response_bound": self.response_bound,
            "response_grammar_class": self.response_grammar_class,
            "selected_grammar_class": self.selected_grammar_class,
            "selected_index": self.selected_index,
            "selected_trace": self.selected_trace,
            "selected_trace_bound": self.selected_trace_bound,
            "task_id": self.task_id,
        }

    @property
    def observation_ref(self) -> str:
        return canonical_ref("attempt-observation", self.to_canonical())

    def pre_feedback_binding(self) -> dict[str, object]:
        payload = self.to_canonical()
        for key in (
            "clone_lifecycle_ref",
            "prospective_batch_ref",
            "prospective_reservation_ref",
            "resolution_ref",
        ):
            payload.pop(key)
        return payload


@dataclass(frozen=True, slots=True)
class StatefulFeedbackApplication:
    """One objective-bound state update, before separate terminalization."""

    observation: AttemptObservation
    clone_terminal: CloneTerminalEvidence | None

    def __post_init__(self) -> None:
        if type(self.observation) is not AttemptObservation:
            raise TypeError("stateful feedback observation differs")
        if (
            not self.observation.proposal_admitted
            or self.observation.arm not in STATEFUL_ARMS
            or any(
                value is None
                for value in (
                    self.observation.prospective_reservation_ref,
                    self.observation.prospective_batch_ref,
                    self.observation.resolution_ref,
                )
            )
            or self.observation.clone_lifecycle is not None
        ):
            raise V2InvariantError("stateful feedback application is incomplete")
        if self.clone_terminal is not None:
            raise V2InvariantError(
                "stateful feedback cannot preempt separate clone terminalization"
            )


def validate_objective_judgment_for_attempt(
    *,
    stage: AttemptStage,
    observation: AttemptObservation,
    attempt_receipt_ref: str,
    judgment: Mapping[str, object],
) -> dict[str, object]:
    """Rejoin the evaluator record before it is allowed to mutate state."""

    if type(stage) is not AttemptStage or type(observation) is not AttemptObservation:
        raise TypeError("objective judgment attempt evidence differs")
    receipt_ref = _ref(attempt_receipt_ref, "objective judgment receipt ref")
    value = _canonical_mapping(judgment, "objective judgment")
    required = {
        "arm",
        "attempt_receipt_ref",
        "disposition",
        "evaluator_record_ref",
        "protocol_identity",
        "proposal_admitted",
        "public_task_ref",
        "raw_response",
        "record_kind",
        "response_commitment",
        "response_conforms",
        "score",
        "success",
        "task_id",
    }
    if set(value) != required:
        raise V2InvariantError("objective judgment fields differ")
    if (
        receipt_ref != stage.attempt_receipt_ref
        or observation.task_id != stage.task_id
        or observation.arm != stage.arm
        or value["task_id"] != stage.task_id
        or value["public_task_ref"] != stage.public_task_ref
        or value["arm"] != stage.arm
        or value["attempt_receipt_ref"] != receipt_ref
        or value["proposal_admitted"] is not observation.proposal_admitted
        or value["raw_response"] != observation.raw_response
    ):
        raise V2InvariantError("objective judgment does not bind the attempt")
    if (
        value["protocol_identity"] != PROTOCOL_IDENTITY
        or value["record_kind"] != "objective-judgment"
        or type(value["proposal_admitted"]) is not bool
        or type(value["response_conforms"]) is not bool
        or type(value["success"]) is not bool
        or type(value["score"]) is not float
        or value["score"] not in (0.0, 1.0)
        or value["success"] is not (value["score"] == 1.0)
        or (value["success"] and not value["response_conforms"])
        or (
            not value["proposal_admitted"]
            and (
                value["raw_response"] != ""
                or value["response_conforms"]
                or value["success"]
                or value["score"] != 0.0
            )
        )
        or value["disposition"]
        != ("SUCCESS" if value["success"] else "UNSUCCESSFUL")
    ):
        raise V2InvariantError("objective judgment value types/disposition differ")
    response_payload = {
        "arm": stage.arm,
        "attempt_receipt_ref": receipt_ref,
        "protocol_identity": PROTOCOL_IDENTITY,
        "raw_response": observation.raw_response,
        "record_kind": "response",
        "task_id": stage.task_id,
    }
    if value["response_commitment"] != domain_ref(
        EVALUATOR_RECORD_DOMAIN, response_payload
    ):
        raise V2InvariantError("objective response commitment differs")
    without_record_ref = dict(value)
    evaluator_record_ref = without_record_ref.pop("evaluator_record_ref")
    if evaluator_record_ref != domain_ref(
        EVALUATOR_RECORD_DOMAIN, without_record_ref
    ):
        raise V2InvariantError("objective evaluator record ref differs")
    return value


@dataclass(frozen=True, slots=True)
class AttemptFinal:
    stage: AttemptStage
    attempt_receipt_ref: str
    terminal_disposition_ref: str
    observation: AttemptObservation
    judgment: dict[str, object]
    witness: ProcedureOutcomeCongruenceWitnessV1

    def __post_init__(self) -> None:
        if type(self.stage) is not AttemptStage:
            raise TypeError("attempt final stage differs")
        _ref(self.attempt_receipt_ref, "attempt final receipt ref")
        _ref(self.terminal_disposition_ref, "attempt terminal disposition ref")
        if self.attempt_receipt_ref != self.stage.attempt_receipt_ref:
            raise V2InvariantError("attempt final receipt does not bind its stage")
        if (
            type(self.observation) is not AttemptObservation
            or self.observation.task_id != self.stage.task_id
            or self.observation.arm != self.stage.arm
        ):
            raise V2InvariantError("attempt observation differs from its stage")
        if type(self.judgment) is not dict:
            raise TypeError("attempt judgment must be an exact canonical object")
        if validate_objective_judgment_for_attempt(
            stage=self.stage,
            observation=self.observation,
            attempt_receipt_ref=self.attempt_receipt_ref,
            judgment=self.judgment,
        ) != self.judgment:
            raise V2InvariantError("objective judgment canonical value changed")
        if (
            self.observation.proposal_prompt_ref != self.stage.proposal_prompt_ref
            or self.observation.proposal_prompt_tokens
            != self.stage.proposal_prompt_tokens
            or (
                self.stage.arm == "N0_NATIVE_NO_HISTORY"
                and self.observation.recalled_record_refs
            )
        ):
            raise V2InvariantError("attempt observation does not bind its staged prompt")
        if (
            type(self.witness) is not ProcedureOutcomeCongruenceWitnessV1
            or self.witness.task_id != self.stage.task_id
            or self.witness.arm != self.stage.arm
            or self.witness.attempt_receipt_ref != self.attempt_receipt_ref
            or self.witness.objective_judgment_ref
            != self.judgment["evaluator_record_ref"]
        ):
            raise V2InvariantError("congruence witness does not bind the judgment")
        expected_selected_ref = (
            None
            if self.observation.selected_trace is None
            else content_ref({"selected_trace": self.observation.selected_trace})
        )
        if (
            self.witness.selected_trace_ref != expected_selected_ref
            or self.witness.response_ref != (
                None
                if not self.observation.proposal_admitted
                else self.judgment["response_commitment"]
            )
            or self.witness.objective_success
            is not (
                None
                if not self.observation.proposal_admitted
                else self.judgment["success"]
            )
            or self.witness.response_conforms
            is not (
                None
                if not self.observation.proposal_admitted
                else self.judgment["response_conforms"]
            )
        ):
            raise V2InvariantError("congruence witness outcome binding differs")
        if self.observation.clone_lifecycle is not None and (
            self.observation.clone_lifecycle.terminal_disposition_ref
            != self.terminal_disposition_ref
        ):
            raise V2InvariantError("clone cleanup does not bind terminal disposition")
        stateful_feedback_required = (
            self.observation.proposal_admitted and self.stage.arm in STATEFUL_ARMS
        )
        prospective_refs = (
            self.observation.prospective_reservation_ref,
            self.observation.prospective_batch_ref,
            self.observation.resolution_ref,
        )
        if stateful_feedback_required != all(value is not None for value in prospective_refs):
            raise V2InvariantError("stateful objective feedback applicability differs")
        if not stateful_feedback_required and any(
            value is not None for value in prospective_refs
        ):
            raise V2InvariantError("stateless/malformed attempt acquired state feedback")
        clone_required = self.stage.arm in STATEFUL_ARMS and self.stage.phase in (
            "development",
            "final",
        )
        if clone_required != (self.observation.clone_lifecycle is not None):
            raise V2InvariantError("disposable clone cleanup applicability differs")
        self.witness.assert_integrity()

    @property
    def final_ref(self) -> str:
        return canonical_ref("attempt-final", self.to_canonical())

    @property
    def success(self) -> bool:
        value = self.judgment["success"]
        if type(value) is not bool:
            raise V2InvariantError("attempt success is not an exact bool")
        return value

    def to_canonical(self) -> dict[str, object]:
        observation = self.observation
        return {
            "arm": self.stage.arm,
            "attempt_receipt_ref": self.attempt_receipt_ref,
            "clone_lifecycle": (
                None
                if observation.clone_lifecycle is None
                else observation.clone_lifecycle.to_canonical()
            ),
            "clone_lifecycle_ref": (
                None
                if observation.clone_lifecycle is None
                else observation.clone_lifecycle.lifecycle_ref
            ),
            "execution_output_tokens": observation.execution_output_tokens,
            "execution_prompt_ref": observation.execution_prompt_ref,
            "execution_prompt_tokens": observation.execution_prompt_tokens,
            "execution_receipt_ref": observation.execution_receipt_ref,
            "execution_request_ref": observation.execution_request_ref,
            "judgment": self.judgment,
            "judgment_artifact_ref": canonical_ref(
                "objective-judgment", self.judgment
            ),
            "observation_ref": observation.observation_ref,
            "phase": self.stage.phase,
            "proposal_admitted": observation.proposal_admitted,
            "proposal_generation_ref": observation.proposal_generation_ref,
            "proposal_output_tokens": observation.proposal_output_tokens,
            "proposal_prompt_ref": observation.proposal_prompt_ref,
            "proposal_prompt_tokens": observation.proposal_prompt_tokens,
            "prospective_batch_ref": observation.prospective_batch_ref,
            "prospective_reservation_ref": observation.prospective_reservation_ref,
            "recalled_record_refs": list(observation.recalled_record_refs),
            "resolution_ref": observation.resolution_ref,
            "schema": ATTEMPT_FINAL_SCHEMA,
            "selected_index": observation.selected_index,
            "selected_trace_ref": (
                None
                if observation.selected_trace is None
                else content_ref({"selected_trace": observation.selected_trace})
            ),
            "stage_ref": self.stage.stage_ref,
            "task_id": self.stage.task_id,
            "terminal_disposition_ref": self.terminal_disposition_ref,
            "witness": self.witness.to_canonical(),
            "witness_ref": self.witness.witness_ref,
        }


class EvidenceLedger:
    """Create-once SQLite ledger for staged and terminal attempt evidence."""

    def __init__(self, path: str | Path, *, create: bool) -> None:
        self.path = Path(path)
        if not self.path.is_absolute():
            raise ValueError("evidence ledger path must be absolute")
        _require_owned_directory(
            self.path.parent,
            expected_mode=0o700,
            label="evidence ledger parent",
        )
        if create:
            flags = os.O_CREAT | os.O_EXCL | os.O_WRONLY
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            descriptor = os.open(self.path, flags, 0o600)
            try:
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
            parent_descriptor = os.open(
                self.path.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                os.fsync(parent_descriptor)
            finally:
                os.close(parent_descriptor)
        metadata = os.lstat(self.path)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or metadata.st_nlink != 1
            or metadata.st_uid != os.geteuid()
            or metadata.st_gid != os.getegid()
        ):
            raise V2InvariantError("evidence ledger metadata differs")
        self._connection = sqlite3.connect(self.path)
        self._connection.execute("PRAGMA journal_mode=DELETE")
        self._connection.execute("PRAGMA synchronous=FULL")
        self._connection.execute("PRAGMA foreign_keys=ON")
        self._connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS attempts (
                task_id TEXT NOT NULL,
                arm TEXT NOT NULL,
                stage_ref TEXT NOT NULL UNIQUE,
                stage_json BLOB NOT NULL,
                receipt_ref TEXT NOT NULL UNIQUE,
                disposition_ref TEXT UNIQUE,
                disposition_json BLOB,
                final_ref TEXT UNIQUE,
                final_json BLOB,
                status INTEGER NOT NULL DEFAULT 0 CHECK(status IN (0,1,2)),
                PRIMARY KEY(task_id, arm),
                CHECK((status=0 AND disposition_ref IS NULL
                                AND disposition_json IS NULL
                                AND final_ref IS NULL AND final_json IS NULL)
                   OR (status=1 AND disposition_ref IS NOT NULL
                                AND disposition_json IS NOT NULL
                                AND final_ref IS NULL AND final_json IS NULL)
                   OR (status=2 AND disposition_ref IS NOT NULL
                                AND disposition_json IS NOT NULL
                                AND final_ref IS NOT NULL AND final_json IS NOT NULL))
            );
            CREATE TABLE IF NOT EXISTS artifacts (
                artifact_ref TEXT PRIMARY KEY,
                kind TEXT NOT NULL,
                canonical_json BLOB NOT NULL
            );
            """
        )
        self._connection.commit()
        self._closed = False
        self._sealed = False

    def _append_artifact_locked(
        self,
        artifact_ref: str,
        kind: str,
        payload: Mapping[str, object],
    ) -> None:
        artifact_ref = _ref(artifact_ref, "ledger artifact ref")
        kind = safe_component(kind, "ledger artifact kind")
        value = dict(payload)
        raw = canonical_json_bytes(value)
        if canonical_ref(kind, value) != artifact_ref:
            raise V2InvariantError("ledger artifact ref/domain differs")
        existing = self._connection.execute(
            "SELECT kind, canonical_json FROM artifacts WHERE artifact_ref=?",
            (artifact_ref,),
        ).fetchone()
        if existing is not None:
            if existing[0] != kind or bytes(existing[1]) != raw:
                raise V2IntegrityStop("ledger artifact ref was rebound")
            return
        self._connection.execute(
            "INSERT INTO artifacts (artifact_ref, kind, canonical_json) VALUES (?,?,?)",
            (artifact_ref, kind, raw),
        )

    def append_artifact(
        self, artifact_ref: str, kind: str, payload: Mapping[str, object]
    ) -> str:
        if self._closed or self._sealed:
            raise RuntimeError("evidence ledger is sealed or closed")
        with self._connection:
            self._append_artifact_locked(artifact_ref, kind, payload)
        return artifact_ref

    def _fsync_current_inode(self) -> None:
        descriptor = os.open(
            self.path,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            opened = os.fstat(descriptor)
            current = os.lstat(self.path)
            if (
                not stat.S_ISREG(opened.st_mode)
                or (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino)
            ):
                raise V2IntegrityStop("evidence ledger inode changed")
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

    def append_artifact_durable(
        self, artifact_ref: str, kind: str, payload: Mapping[str, object]
    ) -> str:
        """Commit and fsync one content-addressed artifact before cleanup."""

        observed = self.append_artifact(artifact_ref, kind, payload)
        self._fsync_current_inode()
        return observed

    def require_artifact(
        self, artifact_ref: str, kind: str, payload: Mapping[str, object]
    ) -> None:
        artifact_ref = _ref(artifact_ref, "required ledger artifact ref")
        kind = safe_component(kind, "required ledger artifact kind")
        raw = canonical_json_bytes(dict(payload))
        row = self._connection.execute(
            "SELECT kind, canonical_json FROM artifacts WHERE artifact_ref=?",
            (artifact_ref,),
        ).fetchone()
        if row is None or row[0] != kind or bytes(row[1]) != raw:
            raise V2IntegrityStop("required durable ledger artifact is absent")

    def require_terminal_disposition(
        self,
        *,
        task_id: str,
        arm: Arm,
        stage_ref: str,
        attempt_receipt_ref: str,
        terminal_disposition_ref: str,
    ) -> None:
        """Require one fsynced terminal disposition before cleanup effects."""

        task_id = _ref(task_id, "required terminal task id")
        arm = validate_arm(arm)
        stage_ref = _ref(stage_ref, "required terminal stage ref")
        attempt_receipt_ref = _ref(
            attempt_receipt_ref, "required terminal receipt ref"
        )
        terminal_disposition_ref = _ref(
            terminal_disposition_ref, "required terminal disposition ref"
        )
        row = self._connection.execute(
            "SELECT disposition_ref, status FROM attempts "
            "WHERE task_id=? AND arm=? AND stage_ref=? AND receipt_ref=?",
            (task_id, arm, stage_ref, attempt_receipt_ref),
        ).fetchone()
        if row != (terminal_disposition_ref, 1):
            raise V2IntegrityStop("required terminal disposition is absent")

    def require_terminal_disposition_ref(
        self,
        *,
        task_id: str,
        arm: Arm,
        terminal_disposition_ref: str,
    ) -> None:
        """Require the unique staged cell closed by an exact disposition ref."""

        task_id = _ref(task_id, "required disposition task id")
        arm = validate_arm(arm)
        terminal_disposition_ref = _ref(
            terminal_disposition_ref, "required disposition ref"
        )
        row = self._connection.execute(
            "SELECT count(*), coalesce(sum(status=1),0) FROM attempts "
            "WHERE task_id=? AND arm=? AND disposition_ref=?",
            (task_id, arm, terminal_disposition_ref),
        ).fetchone()
        if row != (1, 1):
            raise V2IntegrityStop("required terminal disposition ref is absent")

    def require_terminal_disposition_payload(
        self,
        *,
        task_id: str,
        arm: Arm,
        terminal_disposition_ref: str,
        expected_clone_terminal_ref: str | None,
        stage_ref: str | None = None,
        attempt_receipt_ref: str | None = None,
    ) -> None:
        """Rejoin the exact durable disposition payload before destructive cleanup."""

        task_id = _ref(task_id, "required disposition payload task id")
        arm = validate_arm(arm)
        terminal_disposition_ref = _ref(
            terminal_disposition_ref, "required disposition payload ref"
        )
        if expected_clone_terminal_ref is not None:
            expected_clone_terminal_ref = _ref(
                expected_clone_terminal_ref, "required clone terminal ref"
            )
        if stage_ref is not None:
            stage_ref = _ref(stage_ref, "required disposition stage ref")
        if attempt_receipt_ref is not None:
            attempt_receipt_ref = _ref(
                attempt_receipt_ref, "required disposition receipt ref"
            )
        row = self._connection.execute(
            "SELECT stage_ref, receipt_ref, disposition_json, status FROM attempts "
            "WHERE task_id=? AND arm=? AND disposition_ref=?",
            (task_id, arm, terminal_disposition_ref),
        ).fetchone()
        if row is None or row[3] != 1:
            raise V2IntegrityStop("required terminal disposition payload is absent")
        raw = bytes(row[2])
        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise V2IntegrityStop("terminal disposition JSON differs") from error
        if (
            type(payload) is not dict
            or canonical_json_bytes(payload) != raw
            or canonical_ref("attempt-disposition", payload)
            != terminal_disposition_ref
            or payload.get("task_id") != task_id
            or payload.get("arm") != arm
            or payload.get("stage_ref") != row[0]
            or payload.get("attempt_receipt_ref") != row[1]
            or payload.get("clone_terminal_ref") != expected_clone_terminal_ref
            or (stage_ref is not None and row[0] != stage_ref)
            or (attempt_receipt_ref is not None and row[1] != attempt_receipt_ref)
        ):
            raise V2IntegrityStop("terminal disposition payload binding differs")

    def append_stage(self, stage: AttemptStage, prompt_plan: PromptPlan) -> str:
        if self._closed or self._sealed:
            raise RuntimeError("evidence ledger is sealed or closed")
        if (
            type(stage) is not AttemptStage
            or type(prompt_plan) is not PromptPlan
            or prompt_plan.plan_ref != stage.prompt_plan_ref
            or prompt_plan.prompt_ref != stage.proposal_prompt_ref
        ):
            raise TypeError("ledger stage/prompt plan differs")
        raw = canonical_json_bytes(stage.to_canonical())
        try:
            with self._connection:
                self._append_artifact_locked(
                    prompt_plan.history_plan.plan_ref,
                    "history-plan",
                    prompt_plan.history_plan.to_canonical(),
                )
                self._append_artifact_locked(
                    prompt_plan.plan_ref,
                    "prompt-plan",
                    prompt_plan.to_canonical(),
                )
                self._connection.execute(
                    "INSERT INTO attempts "
                    "(task_id, arm, stage_ref, stage_json, receipt_ref) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (
                        stage.task_id,
                        stage.arm,
                        stage.stage_ref,
                        raw,
                        stage.attempt_receipt_ref,
                    ),
                )
        except sqlite3.IntegrityError as error:
            raise V2IntegrityStop("attempt stage was reused") from error
        return stage.attempt_receipt_ref

    def record_terminal_disposition(
        self,
        *,
        stage: AttemptStage,
        attempt_receipt_ref: str,
        pre_feedback_observation_ref: str,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
        witness: ProcedureOutcomeCongruenceWitnessV1,
        clone_terminal: CloneTerminalEvidence | None,
    ) -> str:
        """Durably fsync terminal/hash evidence before disposable cleanup."""

        if self._closed or self._sealed:
            raise RuntimeError("evidence ledger is sealed or closed")
        if (
            type(stage) is not AttemptStage
            or type(observation) is not AttemptObservation
            or type(witness) is not ProcedureOutcomeCongruenceWitnessV1
            or observation.task_id != stage.task_id
            or observation.arm != stage.arm
            or witness.task_id != stage.task_id
            or witness.arm != stage.arm
        ):
            raise V2InvariantError("terminal disposition inputs do not bind")
        attempt_receipt_ref = _ref(
            attempt_receipt_ref, "terminal disposition receipt ref"
        )
        pre_feedback_observation_ref = _ref(
            pre_feedback_observation_ref,
            "terminal pre-feedback observation ref",
        )
        if attempt_receipt_ref != stage.attempt_receipt_ref:
            raise V2InvariantError("terminal disposition receipt differs")
        judgment_payload = dict(judgment)
        judgment_artifact_ref = canonical_ref(
            "objective-judgment", judgment_payload
        )
        self.require_artifact(
            observation.observation_ref,
            "attempt-observation",
            observation.to_canonical(),
        )
        self.require_artifact(
            judgment_artifact_ref,
            "objective-judgment",
            judgment_payload,
        )
        pre_feedback_row = self._connection.execute(
            "SELECT kind FROM artifacts WHERE artifact_ref=?",
            (pre_feedback_observation_ref,),
        ).fetchone()
        if pre_feedback_row != ("attempt-observation",):
            raise V2IntegrityStop("pre-feedback observation artifact is absent")
        if clone_terminal is not None and (
            type(clone_terminal) is not CloneTerminalEvidence
            or clone_terminal.task_id != stage.task_id
            or clone_terminal.arm != stage.arm
        ):
            raise V2InvariantError("terminal clone evidence differs")
        payload = {
            "arm": stage.arm,
            "attempt_receipt_ref": attempt_receipt_ref,
            "clone_terminal": (
                None if clone_terminal is None else clone_terminal.to_canonical()
            ),
            "clone_terminal_ref": (
                None if clone_terminal is None else clone_terminal.terminal_ref
            ),
            "judgment": judgment_payload,
            "judgment_artifact_ref": judgment_artifact_ref,
            "observation": observation.to_canonical(),
            "observation_ref": observation.observation_ref,
            "pre_feedback_observation_ref": pre_feedback_observation_ref,
            "schema": ATTEMPT_DISPOSITION_SCHEMA,
            "stage_ref": stage.stage_ref,
            "task_id": stage.task_id,
            "witness": witness.to_canonical(),
            "witness_ref": witness.witness_ref,
        }
        raw = canonical_json_bytes(payload)
        disposition_ref = canonical_ref("attempt-disposition", payload)
        with self._connection:
            cursor = self._connection.execute(
                "UPDATE attempts SET disposition_ref=?, disposition_json=?, status=1 "
                "WHERE task_id=? AND arm=? AND stage_ref=? AND receipt_ref=? "
                "AND status=0",
                (
                    disposition_ref,
                    raw,
                    stage.task_id,
                    stage.arm,
                    stage.stage_ref,
                    attempt_receipt_ref,
                ),
            )
        if cursor.rowcount != 1:
            raise V2IntegrityStop("terminal disposition does not close one staged row")
        descriptor = os.open(self.path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        try:
            opened = os.fstat(descriptor)
            current = os.lstat(self.path)
            if (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino):
                raise V2IntegrityStop("evidence ledger inode changed before cleanup")
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        return disposition_ref

    def finalize(self, final: AttemptFinal) -> str:
        if self._closed or self._sealed:
            raise RuntimeError("evidence ledger is sealed or closed")
        if type(final) is not AttemptFinal:
            raise TypeError("ledger final differs")
        raw = canonical_json_bytes(final.to_canonical())
        with self._connection:
            cursor = self._connection.execute(
                "UPDATE attempts SET final_ref=?, final_json=?, status=2 "
                "WHERE task_id=? AND arm=? AND stage_ref=? AND receipt_ref=? "
                "AND disposition_ref=? AND status=1",
                (
                    final.final_ref,
                    raw,
                    final.stage.task_id,
                    final.stage.arm,
                    final.stage.stage_ref,
                    final.attempt_receipt_ref,
                    final.terminal_disposition_ref,
                ),
            )
        if cursor.rowcount != 1:
            raise V2IntegrityStop("attempt final does not close one staged row")
        return final.final_ref

    def counts(self) -> tuple[int, int]:
        row = self._connection.execute(
            "SELECT count(*), coalesce(sum(status=2),0) FROM attempts"
        ).fetchone()
        return int(row[0]), int(row[1])

    def close(self) -> None:
        if not self._closed:
            self._connection.commit()
            self._connection.close()
            self._closed = True

    def seal(self, *, expected_attempts: int) -> dict[str, object]:
        expected_attempts = _integer(
            expected_attempts, "expected sealed attempts", minimum=1
        )
        if self._closed or self._sealed:
            raise RuntimeError("evidence ledger is already sealed or closed")
        if self.counts() != (expected_attempts, expected_attempts):
            raise V2IntegrityStop("evidence ledger is incomplete at seal")
        # Seal scientific writes before result construction, but keep the
        # connection readable until lineage owners have verified their exact
        # allocations and detached.  Physical close remains the final step in
        # orchestration cleanup.
        self._connection.commit()
        self._fsync_current_inode()
        self._sealed = True
        return audit_evidence_ledger(self.path, expected_attempts=expected_attempts)

    def __enter__(self) -> "EvidenceLedger":
        return self

    def __exit__(self, *args: object) -> None:
        self.close()


@dataclass(frozen=True, slots=True)
class DisposablePathAllocation:
    """Ledger-first allocation of one disposable runtime and optional scope."""

    purpose: Purpose
    task_id: str
    replicate_commitment: str
    role: str
    runtime_root: str
    cognee_scope_roots: tuple[str, ...]

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        _ref(self.task_id, "path allocation task id")
        _ref(self.replicate_commitment, "path allocation replicate commitment")
        role = safe_component(self.role, "path allocation role")
        if role not in {
            *STATEFUL_ARMS,
            *STATELESS_ARMS,
            "recall-neutral",
            "recall-ordinary",
        }:
            raise ValueError("path allocation role differs")
        expected_scopes = 0 if role in STATELESS_ARMS else 1
        if (
            type(self.cognee_scope_roots) is not tuple
            or len(self.cognee_scope_roots) != expected_scopes
        ):
            raise V2InvariantError("path allocation Cognee scope count differs")
        runtime_parent = STATE_ROOT / f"{purpose}-v1" / "arm-runtime"
        cognee_parent = STATE_ROOT / f"{purpose}-v1" / "cognee-scopes"
        runtime = Path(self.runtime_root)
        scopes = tuple(Path(item) for item in self.cognee_scope_roots)
        if (
            not runtime.is_absolute()
            or runtime.parent != runtime_parent
            or str(runtime) != self.runtime_root
            or not all(
                item.is_absolute()
                and item.parent == cognee_parent
                and str(item) == raw
                for item, raw in zip(scopes, self.cognee_scope_roots, strict=True)
            )
        ):
            raise V2InvariantError("path allocation escapes literal parents")
        safe_component(runtime.name, "runtime allocation name")
        for item in scopes:
            safe_component(item.name, "Cognee allocation name")
        if len({self.runtime_root, *self.cognee_scope_roots}) != 1 + expected_scopes:
            raise V2InvariantError("path allocation targets alias lexically")

    @property
    def allocation_ref(self) -> str:
        return canonical_ref("path-allocation", self.to_canonical())

    @property
    def targets(self) -> tuple[str, ...]:
        return (self.runtime_root, *self.cognee_scope_roots)

    def to_canonical(self) -> dict[str, object]:
        return {
            "cognee_scope_roots": list(self.cognee_scope_roots),
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": self.purpose,
            "replicate_commitment": self.replicate_commitment,
            "role": self.role,
            "runtime_root": self.runtime_root,
            "schema": PATH_ALLOCATION_SCHEMA,
            "task_id": self.task_id,
        }


@dataclass(frozen=True, slots=True)
class RetainedDisposableTargetEvidence:
    """Exact identity and raw tree commitment for one surviving target."""

    target_kind: Literal["runtime-root", "cognee-scope-root"]
    target_path: str
    root_device: int
    root_inode: int
    tree: _RetainedScopeTreeSnapshot

    def __post_init__(self) -> None:
        if self.target_kind not in ("runtime-root", "cognee-scope-root"):
            raise ValueError("retained disposable target kind differs")
        _integer(self.root_device, "retained disposable target device")
        _integer(self.root_inode, "retained disposable target inode", minimum=1)
        if type(self.tree) is not _RetainedScopeTreeSnapshot:
            raise TypeError("retained disposable target tree differs")
        identity = _private_root_identity(
            self.target_path, "retained disposable target root"
        )
        if (
            identity != (self.target_path, self.root_device, self.root_inode)
            or stat.S_IMODE(os.lstat(self.target_path).st_mode) != 0o700
        ):
            raise V2IntegrityStop("retained disposable target identity differs")

    def to_canonical(self) -> dict[str, object]:
        return {
            "root_device": self.root_device,
            "root_inode": self.root_inode,
            "target_kind": self.target_kind,
            "target_path": self.target_path,
            "tree": self.tree.to_canonical(),
        }


@dataclass(frozen=True, slots=True)
class RetainedDisposableAllocationEvidence:
    """Durable terminal ownership of the exact surviving allocation subset."""

    purpose: Purpose
    task_id: str
    replicate_commitment: str
    role: str
    allocation_ref: str
    source_baseline_seal_ref: str | None
    dataset_id: str | None
    stage_ref: str | None
    failure_boundary_code: str
    extant_targets: tuple[RetainedDisposableTargetEvidence, ...]
    absent_targets: tuple[str, ...]
    worker_terminal: bool

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        for value, label in (
            (self.task_id, "retained disposable task id"),
            (
                self.replicate_commitment,
                "retained disposable replicate commitment",
            ),
            (self.allocation_ref, "retained disposable allocation ref"),
        ):
            _ref(value, label)
        role = safe_component(self.role, "retained disposable role")
        if role not in {
            *STATEFUL_ARMS,
            *STATELESS_ARMS,
            "recall-neutral",
            "recall-ordinary",
        }:
            raise ValueError("retained disposable role differs")
        if role in STATELESS_ARMS:
            if self.source_baseline_seal_ref is not None:
                raise V2InvariantError(
                    "stateless retained disposable acquired a source seal"
                )
        else:
            _ref(
                self.source_baseline_seal_ref,
                "retained disposable source baseline seal ref",
            )
        if self.dataset_id is not None:
            _text(self.dataset_id, "retained disposable dataset id", 512)
        if self.stage_ref is not None:
            _ref(self.stage_ref, "retained disposable stage ref")
        if (
            type(self.failure_boundary_code) is not str
            or _BOUNDARY_FAILURE_CODE_RE.fullmatch(self.failure_boundary_code) is None
        ):
            raise ValueError("retained disposable failure boundary code differs")
        if self.worker_terminal is not True:
            raise V2IntegrityStop("retained disposable worker is not terminal")
        if (
            type(self.extant_targets) is not tuple
            or not 1 <= len(self.extant_targets) <= 2
            or any(
                type(item) is not RetainedDisposableTargetEvidence
                for item in self.extant_targets
            )
            or type(self.absent_targets) is not tuple
            or len(self.absent_targets) > 2
        ):
            raise V2InvariantError("retained disposable target inventory differs")
        extant_paths = tuple(item.target_path for item in self.extant_targets)
        if (
            len(set(extant_paths)) != len(extant_paths)
            or len(set(self.absent_targets)) != len(self.absent_targets)
            or set(extant_paths).intersection(self.absent_targets)
            or any(not Path(item).is_absolute() for item in self.absent_targets)
            or len(
                {
                    (item.root_device, item.root_inode)
                    for item in self.extant_targets
                }
            )
            != len(self.extant_targets)
        ):
            raise V2IntegrityStop("retained disposable target partition differs")

    @property
    def evidence_ref(self) -> str:
        return canonical_ref("retained-disposable-allocation", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "absent_targets": list(self.absent_targets),
            "allocation_ref": self.allocation_ref,
            "dataset_id": self.dataset_id,
            "extant_targets": [item.to_canonical() for item in self.extant_targets],
            "failure_boundary_code": self.failure_boundary_code,
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": self.purpose,
            "replicate_commitment": self.replicate_commitment,
            "retention_disposition": "PRESERVED_FAILURE_EVIDENCE",
            "role": self.role,
            "schema": RETAINED_DISPOSABLE_ALLOCATION_SCHEMA,
            "source_baseline_seal_ref": self.source_baseline_seal_ref,
            "stage_ref": self.stage_ref,
            "task_id": self.task_id,
            "worker_terminal": self.worker_terminal,
        }


@dataclass(slots=True)
class PathAllocationRegistry:
    """Global one-run namespace ledger; every target is committed while absent."""

    purpose: Purpose
    ledger: EvidenceLedger = field(repr=False)
    _allocations: dict[str, DisposablePathAllocation] = field(
        default_factory=dict, init=False, repr=False
    )
    _targets: set[str] = field(default_factory=set, init=False, repr=False)
    _closed: set[str] = field(default_factory=set, init=False, repr=False)
    _retained: dict[str, RetainedDisposableAllocationEvidence] = field(
        default_factory=dict, init=False, repr=False
    )

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        if type(self.ledger) is not EvidenceLedger:
            raise TypeError("path allocation registry ledger differs")

    def register(self, allocation: DisposablePathAllocation) -> str:
        if (
            type(allocation) is not DisposablePathAllocation
            or allocation.purpose != self.purpose
            or allocation.allocation_ref in self._allocations
        ):
            raise V2IntegrityStop("path allocation identity was reused")
        resolved_targets: list[str] = []
        for target_text in allocation.targets:
            target = Path(target_text)
            parent_identity = _private_root_identity(
                target.parent, "path allocation parent"
            )
            if (
                parent_identity[0] != str(target.parent)
                or stat.S_IMODE(os.lstat(target.parent).st_mode) != 0o700
            ):
                raise V2IntegrityStop("path allocation parent differs")
            try:
                os.lstat(target)
            except FileNotFoundError:
                pass
            else:
                raise V2IntegrityStop("path allocation target already exists")
            resolved = str(target.resolve(strict=False))
            if resolved != target_text or resolved in self._targets:
                raise V2IntegrityStop("path allocation target aliases or repeats")
            resolved_targets.append(resolved)
        if len(set(resolved_targets)) != len(resolved_targets):
            raise V2IntegrityStop("path allocation targets alias each other")
        self.ledger.append_artifact_durable(
            allocation.allocation_ref,
            "path-allocation",
            allocation.to_canonical(),
        )
        self._allocations[allocation.allocation_ref] = allocation
        self._targets.update(resolved_targets)
        return allocation.allocation_ref

    def _require(self, allocation_ref: object) -> DisposablePathAllocation:
        value = _ref(allocation_ref, "required path allocation ref")
        allocation = self._allocations.get(value)
        if allocation is None:
            raise V2IntegrityStop("path allocation was not ledger-committed")
        self.ledger.require_artifact(
            value, "path-allocation", allocation.to_canonical()
        )
        return allocation

    def require_clone(self, terminal: CloneTerminalEvidence) -> None:
        allocation = self._require(terminal.allocation_ref)
        if (
            allocation.task_id != terminal.task_id
            or allocation.role != terminal.arm
            or allocation.runtime_root != terminal.clone_root
            or allocation.cognee_scope_roots != terminal.cognee_scope_roots
        ):
            raise V2IntegrityStop("clone terminal/path allocation differs")

    def require_capture(self, capture: FrozenRecallCapture) -> None:
        allocation = self._require(capture.allocation_ref)
        if (
            allocation.task_id != capture.task_id
            or allocation.role != f"recall-{capture.kind}"
            or allocation.targets != capture.cleanup_paths
            or allocation.replicate_commitment != capture.replicate_commitment
        ):
            raise V2IntegrityStop("recall capture/path allocation differs")

    def require_stateless(
        self, terminal: StatelessRuntimeTerminalEvidence
    ) -> None:
        if type(terminal) is not StatelessRuntimeTerminalEvidence:
            raise TypeError("stateless terminal allocation evidence differs")
        allocation = self._require(terminal.allocation_ref)
        if (
            allocation.task_id != terminal.task_id
            or allocation.role != terminal.arm
            or allocation.runtime_root != terminal.runtime_root
            or allocation.cognee_scope_roots
        ):
            raise V2IntegrityStop("stateless terminal/path allocation differs")

    def mark_closed(self, allocation_ref: object) -> None:
        allocation = self._require(allocation_ref)
        if allocation.allocation_ref in self._retained:
            raise V2IntegrityStop("retained path allocation cannot be absence-closed")
        for target in allocation.targets:
            try:
                os.lstat(target)
            except FileNotFoundError:
                continue
            raise V2IntegrityStop("allocated disposable target remains")
        self._closed.add(allocation.allocation_ref)

    def _validate_retained(
        self, evidence: RetainedDisposableAllocationEvidence
    ) -> tuple[tuple[int, int], ...]:
        if type(evidence) is not RetainedDisposableAllocationEvidence:
            raise TypeError("retained path allocation evidence differs")
        allocation = self._require(evidence.allocation_ref)
        if (
            evidence.purpose != allocation.purpose
            or evidence.task_id != allocation.task_id
            or evidence.replicate_commitment != allocation.replicate_commitment
            or evidence.role != allocation.role
        ):
            raise V2IntegrityStop("retained path allocation binding differs")
        self.ledger.require_artifact(
            evidence.evidence_ref,
            "retained-disposable-allocation",
            evidence.to_canonical(),
        )
        rows = {item.target_path: item for item in evidence.extant_targets}
        if set(rows).union(evidence.absent_targets) != set(allocation.targets):
            raise V2IntegrityStop("retained path allocation partition differs")
        expected_kinds = {
            allocation.runtime_root: "runtime-root",
            **{
                path: "cognee-scope-root"
                for path in allocation.cognee_scope_roots
            },
        }
        identities: list[tuple[int, int]] = []
        for target in allocation.targets:
            retained = rows.get(target)
            if retained is None:
                try:
                    os.lstat(target)
                except FileNotFoundError:
                    continue
                raise V2IntegrityStop("absent retained disposable target was recreated")
            identity = _private_root_identity(
                target, "revalidated retained disposable target"
            )
            if (
                retained.target_kind != expected_kinds[target]
                or identity != (
                    retained.target_path,
                    retained.root_device,
                    retained.root_inode,
                )
                or stat.S_IMODE(os.lstat(target).st_mode) != 0o700
                or _terminal_scope_tree_snapshot(target) != retained.tree
            ):
                raise V2IntegrityStop("retained disposable target changed")
            identities.append(identity[1:])
        if len(set(identities)) != len(identities):
            raise V2IntegrityStop("retained disposable targets alias")
        return tuple(identities)

    def mark_retained(
        self, evidence: RetainedDisposableAllocationEvidence
    ) -> None:
        allocation = self._require(evidence.allocation_ref)
        if allocation.allocation_ref in self._closed:
            raise V2IntegrityStop("closed path allocation cannot become retained")
        existing = self._retained.get(allocation.allocation_ref)
        if existing is not None and existing != evidence:
            raise V2IntegrityStop("retained path allocation was rebound")
        identities = self._validate_retained(evidence)
        other_identities: set[tuple[int, int]] = set()
        for reference, retained in self._retained.items():
            if reference != allocation.allocation_ref:
                other_identities.update(self._validate_retained(retained))
        if other_identities.intersection(identities):
            raise V2IntegrityStop("retained path allocations alias")
        self._retained[allocation.allocation_ref] = evidence

    def assert_closed(self) -> None:
        if set(self._allocations) != self._closed:
            raise V2IntegrityStop("path allocation registry has live targets")
        for allocation in self._allocations.values():
            for target in allocation.targets:
                try:
                    os.lstat(target)
                except FileNotFoundError:
                    continue
                raise V2IntegrityStop("closed path allocation was recreated")

    def assert_failure_accounted(self) -> None:
        """Accept only absent/disposed or exactly evidenced terminal survivors."""

        accounted = self._closed.union(self._retained)
        if (
            self._closed.intersection(self._retained)
            or set(self._allocations) != accounted
        ):
            raise V2IntegrityStop("path allocation registry is not terminally accounted")
        identities: list[tuple[int, int]] = []
        for allocation_ref in sorted(self._closed):
            allocation = self._require(allocation_ref)
            for target in allocation.targets:
                try:
                    os.lstat(target)
                except FileNotFoundError:
                    continue
                raise V2IntegrityStop("closed path allocation was recreated")
        for allocation_ref in sorted(self._retained):
            identities.extend(self._validate_retained(self._retained[allocation_ref]))
        if len(set(identities)) != len(identities):
            raise V2IntegrityStop("terminal retained path allocations alias")


_LEDGER_ATTEMPT_BINDING_KEYS = frozenset(
    {
        "arm",
        "attempt_receipt_ref",
        "clone_cleanup_verified",
        "disposition_ref",
        "evaluator_record_ref",
        "family",
        "final_ref",
        "phase",
        "proposal_admitted",
        "public_task_ref",
        "replicate",
        "replicate_commitment",
        "resolution_ref",
        "stage_ref",
        "success",
        "task_id",
        "witness_disposition",
        "witness_ref",
    }
)


def _ledger_attempt_binding_from_final(final: AttemptFinal) -> dict[str, object]:
    if type(final) is not AttemptFinal:
        raise TypeError("ledger binding requires an exact AttemptFinal")
    return {
        "arm": final.stage.arm,
        "attempt_receipt_ref": final.attempt_receipt_ref,
        "clone_cleanup_verified": final.observation.clone_lifecycle is not None,
        "disposition_ref": final.terminal_disposition_ref,
        "evaluator_record_ref": final.judgment["evaluator_record_ref"],
        "family": final.stage.family,
        "final_ref": final.final_ref,
        "phase": final.stage.phase,
        "proposal_admitted": final.observation.proposal_admitted,
        "public_task_ref": final.stage.public_task_ref,
        "replicate": final.stage.replicate,
        "replicate_commitment": final.stage.replicate_commitment,
        "resolution_ref": final.observation.resolution_ref,
        "stage_ref": final.stage.stage_ref,
        "success": final.success,
        "task_id": final.stage.task_id,
        "witness_disposition": final.witness.disposition,
        "witness_ref": final.witness.witness_ref,
    }


def audit_evidence_ledger(
    path: str | Path, *, expected_attempts: int
) -> dict[str, object]:
    target = Path(path)
    expected_attempts = _integer(expected_attempts, "expected attempts", minimum=1)
    metadata = os.lstat(target)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_IMODE(metadata.st_mode) != 0o600
        or metadata.st_nlink != 1
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
    ):
        raise V2InvariantError("closed evidence ledger metadata differs")
    connection = sqlite3.connect(f"file:{target}?mode=ro&immutable=1", uri=True)
    try:
        connection.execute("PRAGMA query_only=ON")
        if connection.execute("PRAGMA integrity_check").fetchone() != ("ok",):
            raise V2InvariantError("evidence ledger integrity check failed")
        rows = connection.execute(
            "SELECT task_id, arm, stage_ref, stage_json, receipt_ref, "
            "disposition_ref, disposition_json, final_ref, final_json, status "
            "FROM attempts ORDER BY task_id, arm"
        ).fetchall()
        if len(rows) != expected_attempts:
            raise V2InvariantError("evidence ledger attempt count differs")
        disposition_refs: list[str] = []
        final_refs: list[str] = []
        final_outcome_rows: list[dict[str, object]] = []
        attempt_bindings: list[dict[str, object]] = []
        receipt_refs: list[str] = []
        stage_refs: list[str] = []
        witness_refs: list[str] = []
        witness_dispositions: Counter[str] = Counter()
        referenced_artifacts: set[str] = set()
        for row in rows:
            (
                task_id,
                arm,
                stage_ref,
                stage_json,
                receipt_ref,
                disposition_ref,
                disposition_json,
                final_ref,
                final_json,
                status,
            ) = row
            validate_arm(arm)
            _ref(task_id, "ledger task id")
            _ref(stage_ref, "ledger stage ref")
            _ref(receipt_ref, "ledger receipt ref")
            _ref(disposition_ref, "ledger disposition ref")
            _ref(final_ref, "ledger final ref")
            if int(status) != 2:
                raise V2InvariantError("evidence ledger contains an unfinished attempt")
            stage_payload = json.loads(bytes(stage_json).decode("utf-8"))
            disposition_payload = json.loads(bytes(disposition_json).decode("utf-8"))
            final_payload = json.loads(bytes(final_json).decode("utf-8"))
            final_judgment = final_payload.get("judgment")
            disposition_judgment = disposition_payload.get("judgment")
            final_witness = final_payload.get("witness")
            disposition_witness = disposition_payload.get("witness")
            if (
                type(final_judgment) is not dict
                or disposition_judgment != final_judgment
                or type(final_witness) is not dict
                or disposition_witness != final_witness
            ):
                raise V2InvariantError("evidence ledger terminal payloads differ")
            judgment_artifact_ref = canonical_ref(
                "objective-judgment", final_judgment
            )
            witness_ref = canonical_ref(
                "procedure-outcome-congruence", final_witness
            )
            witness_disposition = final_witness.get("disposition")
            judgment_without_ref = dict(final_judgment)
            evaluator_record_ref = judgment_without_ref.pop(
                "evaluator_record_ref", None
            )
            if witness_disposition not in ("SATISFIED", "UNKNOWN", "VIOLATED"):
                raise V2InvariantError("evidence ledger witness disposition differs")
            if (
                canonical_json_bytes(stage_payload) != bytes(stage_json)
                or canonical_json_bytes(disposition_payload) != bytes(disposition_json)
                or canonical_json_bytes(final_payload) != bytes(final_json)
                or canonical_ref("attempt-stage", stage_payload) != stage_ref
                or canonical_ref("attempt-disposition", disposition_payload)
                != disposition_ref
                or canonical_ref("attempt-final", final_payload) != final_ref
                or final_payload.get("stage_ref") != stage_ref
                or final_payload.get("attempt_receipt_ref") != receipt_ref
                or final_payload.get("terminal_disposition_ref") != disposition_ref
                or disposition_payload.get("stage_ref") != stage_ref
                or disposition_payload.get("attempt_receipt_ref") != receipt_ref
                or final_payload.get("judgment_artifact_ref")
                != judgment_artifact_ref
                or disposition_payload.get("judgment_artifact_ref")
                != judgment_artifact_ref
                or final_payload.get("witness_ref") != witness_ref
                or disposition_payload.get("witness_ref") != witness_ref
                or stage_payload.get("task_id") != task_id
                or stage_payload.get("arm") != arm
                or final_payload.get("task_id") != task_id
                or final_payload.get("arm") != arm
                or disposition_payload.get("task_id") != task_id
                or disposition_payload.get("arm") != arm
                or final_judgment.get("task_id") != task_id
                or final_judgment.get("arm") != arm
                or final_judgment.get("attempt_receipt_ref") != receipt_ref
                or final_judgment.get("public_task_ref")
                != stage_payload.get("public_task_ref")
                or type(final_judgment.get("success")) is not bool
                or evaluator_record_ref
                != domain_ref(EVALUATOR_RECORD_DOMAIN, judgment_without_ref)
                or final_payload.get("proposal_admitted")
                is not final_judgment.get("proposal_admitted")
                or final_witness.get("task_id") != task_id
                or final_witness.get("arm") != arm
                or final_witness.get("attempt_receipt_ref") != receipt_ref
                or final_witness.get("objective_judgment_ref")
                != evaluator_record_ref
            ):
                raise V2InvariantError("evidence ledger canonical binding differs")
            referenced_artifacts.add(
                _ref(stage_payload.get("prompt_plan_ref"), "ledger prompt plan ref")
            )
            history_ref = stage_payload.get("history_plan_ref")
            if history_ref is not None:
                referenced_artifacts.add(_ref(history_ref, "ledger history plan ref"))
            referenced_artifacts.add(judgment_artifact_ref)
            referenced_artifacts.add(
                _ref(
                    disposition_payload.get("observation_ref"),
                    "ledger disposition observation ref",
                )
            )
            referenced_artifacts.add(
                _ref(
                    disposition_payload.get("pre_feedback_observation_ref"),
                    "ledger pre-feedback observation ref",
                )
            )
            phase = validate_phase(stage_payload.get("phase"))
            if final_payload.get("phase") != phase:
                raise V2InvariantError("evidence ledger terminal phase differs")
            family = validate_family(stage_payload.get("family"))
            validate_purpose(stage_payload.get("purpose"))
            public_task_ref_value = _ref(
                stage_payload.get("public_task_ref"), "ledger public task ref"
            )
            replicate_commitment = _ref(
                stage_payload.get("replicate_commitment"),
                "ledger replicate commitment",
            )
            replicate = _text(
                stage_payload.get("replicate"), "ledger replicate label", 32
            )
            if re.fullmatch(r"(?:qualification|replicate)-[0-9]{2}", replicate) is None:
                raise V2InvariantError("evidence ledger replicate label differs")
            proposal_admitted = final_payload.get("proposal_admitted")
            if type(proposal_admitted) is not bool:
                raise V2InvariantError("evidence ledger admission differs")
            resolution_ref = final_payload.get("resolution_ref")
            if resolution_ref is not None:
                resolution_ref = _ref(resolution_ref, "ledger resolution ref")
            attempt_bindings.append(
                {
                    "arm": arm,
                    "attempt_receipt_ref": receipt_ref,
                    "clone_cleanup_verified": final_payload.get("clone_lifecycle")
                    is not None,
                    "disposition_ref": disposition_ref,
                    "evaluator_record_ref": evaluator_record_ref,
                    "family": family,
                    "final_ref": final_ref,
                    "phase": phase,
                    "proposal_admitted": proposal_admitted,
                    "public_task_ref": public_task_ref_value,
                    "replicate": replicate,
                    "replicate_commitment": replicate_commitment,
                    "resolution_ref": resolution_ref,
                    "stage_ref": stage_ref,
                    "success": final_judgment["success"],
                    "task_id": task_id,
                    "witness_disposition": witness_disposition,
                    "witness_ref": witness_ref,
                }
            )
            if phase == "final":
                final_outcome_rows.append(
                    {
                        "arm": arm,
                        "success": final_judgment["success"],
                        "task_id": task_id,
                    }
                )
            disposition_refs.append(disposition_ref)
            final_refs.append(final_ref)
            receipt_refs.append(receipt_ref)
            stage_refs.append(stage_ref)
            witness_refs.append(
                _ref(final_payload.get("witness_ref"), "ledger witness ref")
            )
            witness_dispositions[str(witness_disposition)] += 1
        if (
            len(set(disposition_refs)) != expected_attempts
            or len(set(final_refs)) != expected_attempts
            or len(set(receipt_refs)) != expected_attempts
            or len(set(stage_refs)) != expected_attempts
            or len(set(witness_refs)) != expected_attempts
            or len(
                {
                    (str(item["task_id"]), str(item["arm"]))
                    for item in attempt_bindings
                }
            )
            != expected_attempts
        ):
            raise V2InvariantError("evidence ledger repeats terminal refs")
        artifact_rows = connection.execute(
            "SELECT artifact_ref, kind, canonical_json FROM artifacts "
            "ORDER BY artifact_ref"
        ).fetchall()
        artifact_refs: list[str] = []
        evaluator_metrics_artifact_refs: list[str] = []
        run_provenance_closures: list[dict[str, object]] = []
        for artifact_ref, kind, raw_payload in artifact_rows:
            artifact_ref = _ref(artifact_ref, "ledger stored artifact ref")
            kind = safe_component(kind, "ledger stored artifact kind")
            payload = json.loads(bytes(raw_payload).decode("utf-8"))
            if (
                canonical_json_bytes(payload) != bytes(raw_payload)
                or canonical_ref(kind, payload) != artifact_ref
            ):
                raise V2InvariantError("ledger stored artifact binding differs")
            artifact_refs.append(artifact_ref)
            if kind == "evaluator-final-metrics":
                evaluator_metrics_artifact_refs.append(artifact_ref)
            elif kind == "run-provenance-closure":
                run_provenance_closures.append(
                    {"closure": payload, "closure_ref": artifact_ref}
                )
        if (
            len(evaluator_metrics_artifact_refs) > 1
            or len(run_provenance_closures) > 1
        ):
            raise V2InvariantError("ledger repeats evaluator final metrics")
        if not referenced_artifacts.issubset(set(artifact_refs)):
            raise V2InvariantError("ledger stage references an absent artifact")
    finally:
        connection.close()
    digest, size = sha256_file(target)
    for suffix in ("-journal", "-wal", "-shm"):
        if Path(str(target) + suffix).exists():
            raise V2InvariantError("closed evidence ledger retained a SQLite sidecar")
    return {
        "attempts": expected_attempts,
        "attempt_bindings": sorted(
            attempt_bindings,
            key=lambda item: (str(item["task_id"]), str(item["arm"])),
        ),
        "artifact_refs_sha256": hashlib.sha256(
            canonical_json_bytes(artifact_refs)
        ).hexdigest(),
        "artifacts": len(artifact_refs),
        "evaluator_metrics_artifact_ref": (
            None
            if not evaluator_metrics_artifact_refs
            else evaluator_metrics_artifact_refs[0]
        ),
        "finalized": expected_attempts,
        "final_outcomes_sha256": hashlib.sha256(
            canonical_json_bytes(
                sorted(
                    final_outcome_rows,
                    key=lambda item: (str(item["task_id"]), str(item["arm"])),
                )
            )
        ).hexdigest(),
        "ledger_bytes": size,
        "ledger_sha256": digest,
        "disposition_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(disposition_refs))
        ).hexdigest(),
        "receipt_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(receipt_refs))
        ).hexdigest(),
        "run_provenance_closure": (
            None if not run_provenance_closures else run_provenance_closures[0]
        ),
        "stage_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(stage_refs))
        ).hexdigest(),
        "terminal_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(final_refs))
        ).hexdigest(),
        "witness_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(witness_refs))
        ).hexdigest(),
        "witness_dispositions": {
            name: witness_dispositions.get(name, 0)
            for name in ("SATISFIED", "UNKNOWN", "VIOLATED")
        },
    }


def exact_mcnemar_two_sided(
    left_failure_right_success: int,
    left_success_right_failure: int,
) -> float:
    positive = _integer(
        left_failure_right_success, "left-failure/right-success count"
    )
    negative = _integer(
        left_success_right_failure, "left-success/right-failure count"
    )
    discordant = positive + negative
    if discordant == 0:
        return 1.0
    extreme = min(positive, negative)
    numerator = 2 * sum(math.comb(discordant, index) for index in range(extreme + 1))
    denominator = 1 << discordant
    return min(1.0, numerator / denominator)


def holm_adjusted(p_values: Mapping[str, float]) -> dict[str, float]:
    if not p_values:
        raise ValueError("Holm adjustment requires at least one p-value")
    rows: list[tuple[float, str]] = []
    for name, value in p_values.items():
        _text(name, "contrast name", 512)
        number = _finite(value, "p-value")
        if not 0.0 <= number <= 1.0:
            raise ValueError("p-value is outside zero through one")
        rows.append((number, name))
    rows.sort(key=lambda item: (item[0], item[1]))
    total = len(rows)
    previous = 0.0
    adjusted: dict[str, float] = {}
    for index, (value, name) in enumerate(rows):
        current = min(1.0, (total - index) * value)
        previous = max(previous, current)
        adjusted[name] = previous
    return adjusted


def _direction(numerator: int) -> Literal[
    "OBSERVED_RIGHT_HIGHER", "OBSERVED_LEFT_HIGHER", "OBSERVED_EQUAL"
]:
    if numerator > 0:
        return "OBSERVED_RIGHT_HIGHER"
    if numerator < 0:
        return "OBSERVED_LEFT_HIGHER"
    return "OBSERVED_EQUAL"


def _contrast_name(left: Arm, right: Arm) -> str:
    return f"{left}__TO__{right}"


@dataclass(frozen=True, slots=True)
class ContrastStatistic:
    left_arm: Arm
    right_arm: Arm
    denominator: int
    left_successes: int
    right_successes: int
    left_failure_right_success: int
    left_success_right_failure: int
    tied_failure: int
    tied_success: int
    effect_numerator: int
    direction: str
    exact_mcnemar_two_sided_hex: str
    holm_adjusted_hex: str
    family_strata: tuple[tuple[str, int, int], ...]
    replicate_strata: tuple[tuple[str, int, int], ...]
    recurrent_in_two_families: bool
    recurrent_in_two_replicates: bool
    reversals: tuple[str, ...]

    def __post_init__(self) -> None:
        if (self.left_arm, self.right_arm) not in PRIMARY_CONTRASTS:
            raise ValueError("contrast pair is not preregistered")
        _integer(self.denominator, "contrast denominator", minimum=1)
        counts = (
            self.left_failure_right_success,
            self.left_success_right_failure,
            self.tied_failure,
            self.tied_success,
        )
        if any(type(value) is not int or value < 0 for value in counts):
            raise ValueError("contrast pair counts must be non-negative integers")
        if sum(counts) != self.denominator:
            raise V2InvariantError("contrast pair counts do not close")
        if (
            self.left_successes
            != self.left_success_right_failure + self.tied_success
            or self.right_successes
            != self.left_failure_right_success + self.tied_success
            or self.effect_numerator
            != self.right_successes - self.left_successes
            or self.direction != _direction(self.effect_numerator)
        ):
            raise V2InvariantError("contrast effect arithmetic differs")
        for value in (self.exact_mcnemar_two_sided_hex, self.holm_adjusted_hex):
            number = float.fromhex(value)
            if not math.isfinite(number) or not 0.0 <= number <= 1.0:
                raise ValueError("contrast diagnostic probability differs")
        if (
            len(self.family_strata) != 3
            or {name for name, _, _ in self.family_strata} != set(FAMILIES)
        ):
            raise V2InvariantError("contrast family strata differ")
        if len(self.replicate_strata) != 3:
            raise V2InvariantError("contrast replicate strata differ")
        for _, numerator, denominator in (*self.family_strata, *self.replicate_strata):
            if type(numerator) is not int or type(denominator) is not int or denominator < 1:
                raise ValueError("contrast stratum arithmetic differs")
        if type(self.recurrent_in_two_families) is not bool or type(
            self.recurrent_in_two_replicates
        ) is not bool:
            raise TypeError("contrast recurrence flags must be bool")

    @property
    def name(self) -> str:
        return _contrast_name(self.left_arm, self.right_arm)

    def to_canonical(self) -> dict[str, object]:
        return {
            "denominator": self.denominator,
            "direction": self.direction,
            "effect_numerator": self.effect_numerator,
            "exact_mcnemar_two_sided_hex": self.exact_mcnemar_two_sided_hex,
            "family_strata": [
                {"denominator": denominator, "name": name, "numerator": numerator}
                for name, numerator, denominator in self.family_strata
            ],
            "holm_adjusted_hex": self.holm_adjusted_hex,
            "left_arm": self.left_arm,
            "left_failure_right_success": self.left_failure_right_success,
            "left_success_right_failure": self.left_success_right_failure,
            "left_successes": self.left_successes,
            "recurrent_in_two_families": self.recurrent_in_two_families,
            "recurrent_in_two_replicates": self.recurrent_in_two_replicates,
            "replicate_strata": [
                {"denominator": denominator, "name": name, "numerator": numerator}
                for name, numerator, denominator in self.replicate_strata
            ],
            "reversals": list(self.reversals),
            "right_arm": self.right_arm,
            "right_successes": self.right_successes,
            "tied_failure": self.tied_failure,
            "tied_success": self.tied_success,
        }


def _pair_counts(
    task_ids: Sequence[str],
    cells: Mapping[tuple[str, Arm], AttemptFinal],
    left: Arm,
    right: Arm,
) -> tuple[int, int, int, int]:
    counts = Counter()
    for task_id in task_ids:
        try:
            left_value = cells[(task_id, left)].success
            right_value = cells[(task_id, right)].success
        except KeyError as error:
            raise V2InvariantError("finite cohort is missing one paired arm") from error
        counts[(left_value, right_value)] += 1
    return (
        counts[(False, True)],
        counts[(True, False)],
        counts[(False, False)],
        counts[(True, True)],
    )


def finite_cohort_statistics(
    final_attempts: Sequence[AttemptFinal],
) -> dict[str, object]:
    """Describe the exact 54-task final cohort without a promotion decision."""

    values = tuple(final_attempts)
    if len(values) != 432 or any(
        type(item) is not AttemptFinal
        or item.stage.phase != "final"
        or item.stage.purpose != "evaluation"
        for item in values
    ):
        raise V2InvariantError("finite cohort requires exactly 432 final arm attempts")
    cells: dict[tuple[str, Arm], AttemptFinal] = {}
    task_metadata: dict[str, tuple[Family, str, str]] = {}
    for item in values:
        item.witness.assert_integrity()
        key = (item.stage.task_id, item.stage.arm)
        if key in cells:
            raise V2InvariantError("finite cohort repeats a task/arm cell")
        cells[key] = item
        metadata = (
            item.stage.family,
            item.stage.replicate,
            item.stage.replicate_commitment,
        )
        prior = task_metadata.setdefault(item.stage.task_id, metadata)
        if prior != metadata:
            raise V2InvariantError("finite cohort task metadata differs across arms")
    task_ids = tuple(sorted(task_metadata))
    if len(task_ids) != 54:
        raise V2InvariantError("finite cohort task denominator differs")
    if any(
        {arm for task_id, arm in cells if task_id == selected} != set(ARMS)
        for selected in task_ids
    ):
        raise V2InvariantError("finite cohort does not contain all eight arms")
    family_counts = Counter(family for family, _, _ in task_metadata.values())
    replicate_counts = Counter(
        replicate for _, replicate, _ in task_metadata.values()
    )
    if family_counts != Counter({family: 18 for family in FAMILIES}):
        raise V2InvariantError("finite cohort family denominators differ")
    if replicate_counts != Counter(
        {"replicate-01": 18, "replicate-02": 18, "replicate-03": 18}
    ):
        raise V2InvariantError("finite cohort replicate denominators differ")
    family_replicate_counts = Counter(
        (family, replicate)
        for family, replicate, _ in task_metadata.values()
    )
    if family_replicate_counts != Counter(
        {
            (family, replicate): 6
            for family in FAMILIES
            for replicate in ("replicate-01", "replicate-02", "replicate-03")
        }
    ):
        raise V2InvariantError("finite cohort family/replicate cells differ")
    replicate_commitments: dict[str, str] = {}
    for _family, replicate, commitment in task_metadata.values():
        prior = replicate_commitments.setdefault(replicate, commitment)
        if prior != commitment:
            raise V2InvariantError("finite cohort replicate commitment drifted")
    if len(set(replicate_commitments.values())) != 3:
        raise V2InvariantError("finite cohort replicate commitments are not distinct")
    validate_evaluation_seed_commitments(
        tuple(
            replicate_commitments[label]
            for label in ("replicate-01", "replicate-02", "replicate-03")
        )
    )

    raw_p: dict[str, float] = {}
    raw_rows: dict[tuple[Arm, Arm], tuple[int, int, int, int]] = {}
    for left, right in PRIMARY_CONTRASTS:
        counts = _pair_counts(task_ids, cells, left, right)
        raw_rows[(left, right)] = counts
        raw_p[_contrast_name(left, right)] = exact_mcnemar_two_sided(
            counts[0], counts[1]
        )
    adjusted = holm_adjusted(raw_p)

    contrasts: list[ContrastStatistic] = []
    for left, right in PRIMARY_CONTRASTS:
        positive, negative, tied_failure, tied_success = raw_rows[(left, right)]
        effect = positive - negative
        direction = _direction(effect)
        family_rows: list[tuple[str, int, int]] = []
        replicate_rows: list[tuple[str, int, int]] = []
        reversals: list[str] = []
        for family in FAMILIES:
            selected = tuple(
                task_id
                for task_id in task_ids
                if task_metadata[task_id][0] == family
            )
            b, c, _, _ = _pair_counts(selected, cells, left, right)
            numerator = b - c
            family_rows.append((family, numerator, len(selected)))
            if effect != 0 and numerator != 0 and (numerator > 0) != (effect > 0):
                reversals.append(f"family:{family}")
        for replicate in sorted(replicate_counts):
            selected = tuple(
                task_id
                for task_id in task_ids
                if task_metadata[task_id][1] == replicate
            )
            b, c, _, _ = _pair_counts(selected, cells, left, right)
            numerator = b - c
            replicate_rows.append((replicate, numerator, len(selected)))
            if effect != 0 and numerator != 0 and (numerator > 0) != (effect > 0):
                reversals.append(f"replicate:{replicate}")
        family_recurrence = sum(
            numerator != 0 and effect != 0 and (numerator > 0) == (effect > 0)
            for _, numerator, _ in family_rows
        ) >= 2
        replicate_recurrence = sum(
            numerator != 0 and effect != 0 and (numerator > 0) == (effect > 0)
            for _, numerator, _ in replicate_rows
        ) >= 2
        name = _contrast_name(left, right)
        contrasts.append(
            ContrastStatistic(
                left_arm=left,
                right_arm=right,
                denominator=54,
                left_successes=negative + tied_success,
                right_successes=positive + tied_success,
                left_failure_right_success=positive,
                left_success_right_failure=negative,
                tied_failure=tied_failure,
                tied_success=tied_success,
                effect_numerator=effect,
                direction=direction,
                exact_mcnemar_two_sided_hex=raw_p[name].hex(),
                holm_adjusted_hex=adjusted[name].hex(),
                family_strata=tuple(family_rows),
                replicate_strata=tuple(replicate_rows),
                recurrent_in_two_families=family_recurrence,
                recurrent_in_two_replicates=replicate_recurrence,
                reversals=tuple(sorted(reversals)),
            )
        )

    interaction_numerator = 0
    for task_id in task_ids:
        interaction_numerator += (
            int(cells[(task_id, "IO_FULL_ORDINARY_12")].success)
            - int(cells[(task_id, "O0_ORDINARY_FROZEN_12")].success)
            - int(cells[(task_id, "IN_FULL_NEUTRAL_12")].success)
            + int(cells[(task_id, "F0_NEUTRAL_FORMATTED_12")].success)
        )
    payload = {
        "classification_boundary": (
            "FINITE_COHORT_DIRECTION_ONLY; p-values are descriptive and "
            "independence-uncalibrated; no support/rule-out/promotion disposition"
        ),
        "cohort": [
            {
                "family": task_metadata[task_id][0],
                "replicate": task_metadata[task_id][1],
                "replicate_commitment": task_metadata[task_id][2],
                "successes": {
                    arm: cells[(task_id, arm)].success for arm in ARMS
                },
                "task_id": task_id,
            }
            for task_id in task_ids
        ],
        "contrasts": [item.to_canonical() for item in contrasts],
        "denominator": 54,
        "history_runtime_interaction": {
            "classification": "SECONDARY_DESCRIPTIVE_ONLY",
            "denominator": 54,
            "direction": _direction(interaction_numerator),
            "effect_numerator": interaction_numerator,
            "formula": "(IO-O0)-(IN-F0)",
        },
        "primary_contrast_count": 7,
        "schema": FINITE_COHORT_SCHEMA,
    }
    return {**payload, "statistics_ref": canonical_ref("finite-cohort", payload)}


_RESULT_KEYS = frozenset(
    {
        "accounting",
        "attempts",
        "authorization_ref",
        "claim_boundary",
        "evaluator",
        "frozen_adaptation",
        "identity",
        "integrity",
        "pair_equalities",
        "protocol_identity",
        "purpose",
        "resources",
        "result_ref",
        "schema",
        "statistics",
    }
)


def _evaluator_digest(record_kind: str, payload: Mapping[str, object]) -> str:
    return domain_ref(
        EVALUATOR_RECORD_DOMAIN,
        {
            "protocol_identity": PROTOCOL_IDENTITY,
            "record_kind": _text(record_kind, "evaluator record kind", 128),
            **dict(payload),
        },
    )


def _attempt_result_summary(
    attempts: Sequence[AttemptFinal], *, purpose: Purpose
) -> dict[str, object]:
    purpose = validate_purpose(purpose)
    rows = tuple(attempts)
    expected = 72 if purpose == "qualification" else 918
    if len(rows) != expected or any(
        type(item) is not AttemptFinal or item.stage.purpose != purpose
        for item in rows
    ):
        raise V2InvariantError("result attempt population differs")
    keys = [(item.stage.task_id, item.stage.arm) for item in rows]
    if len(set(keys)) != expected:
        raise V2InvariantError("result repeats a task/arm attempt")
    phase_counts = Counter(item.stage.phase for item in rows)
    expected_phases = (
        EXPECTED_QUALIFICATION_PHASE_ATTEMPTS
        if purpose == "qualification"
        else EXPECTED_EVALUATION_PHASE_ATTEMPTS
    )
    if phase_counts != Counter(expected_phases):
        raise V2InvariantError("result phase attempt denominators differ")
    admitted = sum(item.observation.proposal_admitted for item in rows)
    clone_cleanup = sum(item.observation.clone_lifecycle is not None for item in rows)
    expected_clone_cleanup = sum(
        item.stage.arm in STATEFUL_ARMS
        and item.stage.phase in ("development", "final")
        for item in rows
    )
    if clone_cleanup != expected_clone_cleanup:
        raise V2InvariantError("result clone cleanup denominator differs")
    dispositions = Counter(item.witness.disposition for item in rows)
    for item in rows:
        item.witness.assert_integrity()
    final_outcome_rows = sorted(
        (
            {
                "arm": item.stage.arm,
                "success": item.success,
                "task_id": item.stage.task_id,
            }
            for item in rows
            if item.stage.phase == "final"
        ),
        key=lambda item: (str(item["task_id"]), str(item["arm"])),
    )
    return {
        "admitted": admitted,
        "arm_counts": dict(sorted(Counter(item.stage.arm for item in rows).items())),
        "attempts": expected,
        "clone_cleanup_verified": clone_cleanup,
        "family_counts": dict(
            sorted(Counter(item.stage.family for item in rows).items())
        ),
        "final_outcomes_sha256": hashlib.sha256(
            canonical_json_bytes(final_outcome_rows)
        ).hexdigest(),
        "phase_counts": {phase: phase_counts.get(phase, 0) for phase in PHASES},
        "proposal_malformed": expected - admitted,
        "receipt_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(item.attempt_receipt_ref for item in rows))
        ).hexdigest(),
        "stage_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(item.stage.stage_ref for item in rows))
        ).hexdigest(),
        "successes": sum(item.success for item in rows),
        "terminal_disposition_refs_sha256": hashlib.sha256(
            canonical_json_bytes(
                sorted(item.terminal_disposition_ref for item in rows)
            )
        ).hexdigest(),
        "terminal_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(item.final_ref for item in rows))
        ).hexdigest(),
        "witness_dispositions": {
            name: dispositions.get(name, 0)
            for name in ("SATISFIED", "UNKNOWN", "VIOLATED")
        },
        "witness_refs_sha256": hashlib.sha256(
            canonical_json_bytes(sorted(item.witness.witness_ref for item in rows))
        ).hexdigest(),
    }


def _validate_accounting_resources(
    *,
    purpose: Purpose,
    accounting: Mapping[str, object],
    resources: Mapping[str, object],
) -> tuple[dict[str, object], dict[str, object]]:
    expected_attempts = 72 if purpose == "qualification" else 918
    account = dict(accounting)
    if set(account) != {
        "arm_tasks",
        "execution_attempts",
        "generation_attempts",
        "proposal_attempts",
    }:
        raise V2InvariantError("attempt accounting fields differ")
    for key, value in account.items():
        account[key] = _integer(value, f"attempt accounting {key}")
    if (
        account["arm_tasks"] != expected_attempts
        or account["proposal_attempts"] != expected_attempts
        or account["generation_attempts"]
        != account["proposal_attempts"] + account["execution_attempts"]
        or account["execution_attempts"] > expected_attempts
    ):
        raise V2InvariantError("attempt accounting does not close")
    resource = dict(resources)
    expected_resource_keys = {
        "configured_pools",
        "embedding_rows",
        "generation_calls",
        "mode",
        "output_tokens",
        "peak_cuda_allocated_bytes",
        "peak_cuda_reserved_bytes",
        "peak_processes",
        "peak_rss_bytes",
        "peak_state_scratch_bytes",
        "prompt_tokens",
        "runtime_embedding_rows",
        "samples",
        "schema",
        "wall_seconds",
    }
    if set(resource) != expected_resource_keys:
        raise V2InvariantError("resource result fields differ")
    if resource["schema"] != RESOURCE_SCHEMA or resource["mode"] != purpose:
        raise V2InvariantError("resource result identity differs")
    integer_limits = {
        "configured_pools": MAXIMUM_CONFIGURED_POOLS,
        "embedding_rows": (
            MAXIMUM_QUALIFICATION_EMBEDDING_ROWS
            if purpose == "qualification"
            else MAXIMUM_EVALUATION_EMBEDDING_ROWS
        ),
        "generation_calls": (
            MAXIMUM_QUALIFICATION_GENERATIONS
            if purpose == "qualification"
            else MAXIMUM_EVALUATION_GENERATIONS
        ),
        "output_tokens": None,
        "peak_cuda_allocated_bytes": MAXIMUM_CUDA_BYTES,
        "peak_cuda_reserved_bytes": MAXIMUM_CUDA_BYTES,
        "peak_processes": MAXIMUM_PROCESSES,
        "peak_rss_bytes": MAXIMUM_RSS_BYTES,
        "peak_state_scratch_bytes": MAXIMUM_STATE_SCRATCH_BYTES,
        "prompt_tokens": None,
        "runtime_embedding_rows": (
            MAXIMUM_QUALIFICATION_RUNTIME_EMBEDDING_ROWS
            if purpose == "qualification"
            else MAXIMUM_EVALUATION_RUNTIME_EMBEDDING_ROWS
        ),
        "samples": None,
    }
    for key, limit in integer_limits.items():
        resource[key] = _integer(resource[key], f"resource {key}", maximum=limit)
    wall = _finite(resource["wall_seconds"], "resource wall seconds")
    if wall > MAXIMUM_WALL_SECONDS:
        raise V2IntegrityStop("result wall time exceeds its ceiling")
    resource["wall_seconds"] = wall
    if (
        resource["generation_calls"] != account["generation_attempts"]
        or resource["prompt_tokens"] < resource["generation_calls"]
        or resource["prompt_tokens"] > resource["generation_calls"] * MAXIMUM_INPUT_TOKENS
        or resource["output_tokens"] < resource["generation_calls"]
        or resource["output_tokens"] > resource["generation_calls"] * MAXIMUM_OUTPUT_TOKENS
        or resource["samples"] < 2 * expected_attempts
    ):
        raise V2InvariantError("resource/attempt accounting does not rejoin")
    return account, resource


def build_run_result(
    *,
    purpose: Purpose,
    attempts: Sequence[AttemptFinal],
    pair_equalities: Sequence[PairEqualityEvidence],
    frozen: "FrozenAdaptationState",
    evaluator_commitments: Mapping[str, object],
    evaluator_metrics: Mapping[str, object],
    statistics: Mapping[str, object] | None,
    accounting: Mapping[str, object],
    resources: Mapping[str, object],
    source_seal_ref: str,
    ledger_witness: Mapping[str, object],
    authorization_ref: str,
) -> dict[str, object]:
    """Build the closed, redacted, non-authorizing terminal result."""

    purpose = validate_purpose(purpose)
    if type(frozen) is not FrozenAdaptationState or frozen.purpose != purpose:
        raise V2InvariantError("result frozen adaptation state differs")
    source_seal_ref = _ref(source_seal_ref, "result source seal ref")
    authorization_ref = _ref(authorization_ref, "result run authorization ref")
    if purpose == "qualification":
        if statistics is not None:
            raise V2InvariantError("qualification acquired evaluation-only material")
        identity = QUALIFICATION_IDENTITY
        classification = "TECHNICAL_QUALIFICATION_ONLY"
    else:
        if type(statistics) is not dict:
            statistics = dict(statistics or {})
        if statistics.get("schema") != FINITE_COHORT_SCHEMA:
            raise V2InvariantError("evaluation finite-cohort statistics differ")
        identity = EVALUATION_IDENTITY
        classification = "EXPLORATORY_MECHANISTIC_FINITE_COHORT_ONLY"
    summary = _attempt_result_summary(attempts, purpose=purpose)
    if purpose == "evaluation":
        recomputed_statistics = finite_cohort_statistics(
            tuple(item for item in attempts if item.stage.phase == "final")
        )
        if dict(statistics or {}) != recomputed_statistics:
            raise V2InvariantError(
                "evaluation statistics do not bind the executed final cohort"
            )
    account, resource = _validate_accounting_resources(
        purpose=purpose, accounting=accounting, resources=resources
    )
    expected_runtime_embedding_rows = (
        sum(
            item.observation.proposal_admitted
            and item.stage.arm in STATEFUL_ARMS
            for item in attempts
        )
        * RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
    )
    if resource["runtime_embedding_rows"] != expected_runtime_embedding_rows:
        raise V2InvariantError(
            "stateful runtime embedding accounting does not rejoin attempts"
        )
    pairs = tuple(pair_equalities)
    expected_pairs = 6 if purpose == "qualification" else 162
    if (
        len(pairs) != expected_pairs
        or any(
            type(item) is not PairEqualityEvidence
            or item.proposal_sets_equal is not True
            for item in pairs
        )
        or len({(item.task_id, item.left_arm, item.right_arm) for item in pairs})
        != expected_pairs
    ):
        raise V2InvariantError("paired prompt/proposal equality evidence differs")
    commitments = dict(evaluator_commitments)
    metrics = dict(evaluator_metrics)
    canonical_json_bytes(commitments)
    canonical_json_bytes(metrics)
    if (
        commitments.get("protocol_identity") != PROTOCOL_IDENTITY
        or commitments.get("identity") != identity
        or commitments.get("purpose") != purpose
        or metrics.get("protocol_identity") != PROTOCOL_IDENTITY
        or metrics.get("identity") != identity
        or metrics.get("purpose") != purpose
    ):
        raise V2InvariantError("evaluator commitments/metrics identity differs")
    replicate_labels = commitments.get("replicate_labels")
    replicate_values = commitments.get("replicate_commitments")
    if type(replicate_labels) is not list or type(replicate_values) is not list:
        raise V2InvariantError("evaluator replicate commitments differ")
    if purpose == "qualification":
        if (
            replicate_labels != ["qualification-01"]
            or replicate_values != [qualification_replicate_commitment()]
        ):
            raise V2InvariantError("qualification evaluator lineage differs")
    else:
        if replicate_labels != ["replicate-01", "replicate-02", "replicate-03"]:
            raise V2InvariantError("evaluation evaluator replicate labels differ")
        validate_evaluation_seed_commitments(tuple(replicate_values))
    frozen_commitments = {
        item.replicate_commitment for item in frozen.baseline_seals
    }
    if frozen_commitments != set(replicate_values) or {
        item.replicate_commitment for item in frozen.donor_catalogs
    } != frozen_commitments:
        raise V2InvariantError("evaluator and frozen lineage commitments differ")
    commitment_tasks = commitments.get("tasks")
    if type(commitment_tasks) is not list or any(
        type(item) is not dict for item in commitment_tasks
    ):
        raise V2InvariantError("evaluator task commitment inventory differs")
    by_task = {str(item.get("task_id")): item for item in commitment_tasks}
    attempt_task_ids = {item.stage.task_id for item in attempts}
    if set(by_task) != attempt_task_ids:
        raise V2InvariantError("evaluator and executed task inventories differ")
    for attempt in attempts:
        task = by_task[attempt.stage.task_id]
        if (
            task.get("public_task_ref") != attempt.stage.public_task_ref
            or task.get("replicate") != attempt.stage.replicate
            or task.get("replicate_commitment")
            != attempt.stage.replicate_commitment
            or task.get("family") != attempt.stage.family
            or task.get("phase") != attempt.stage.phase
            or task.get("ordinal") != attempt.stage.task_ordinal
        ):
            raise V2InvariantError("executed stage differs from evaluator commitment")
    commitments_ref = _evaluator_digest("evaluator-commitments", commitments)
    metrics_ref = _evaluator_digest("final-metrics", metrics)
    ledger = dict(ledger_witness)
    expected_ledger_keys = {
        "attempts",
        "attempt_bindings",
        "artifact_refs_sha256",
        "artifacts",
        "disposition_refs_sha256",
        "evaluator_metrics_artifact_ref",
        "finalized",
        "final_outcomes_sha256",
        "ledger_bytes",
        "ledger_sha256",
        "receipt_refs_sha256",
        "run_provenance_closure",
        "stage_refs_sha256",
        "terminal_refs_sha256",
        "witness_dispositions",
        "witness_refs_sha256",
    }
    if set(ledger) != expected_ledger_keys:
        raise V2InvariantError("ledger witness fields differ")
    expected_attempt_bindings = sorted(
        (_ledger_attempt_binding_from_final(item) for item in attempts),
        key=lambda item: (str(item["task_id"]), str(item["arm"])),
    )
    expected_metrics_artifact_ref = canonical_ref(
        "evaluator-final-metrics", metrics
    )
    expected_run_closure = _run_provenance_closure_payload(
        purpose=purpose,
        authorization_ref=authorization_ref,
        source_seal_ref=source_seal_ref,
        evaluator_commitments_ref=commitments_ref,
        frozen_adaptation_ref=frozen.freeze_ref,
        evaluator_metrics_artifact_ref=expected_metrics_artifact_ref,
    )
    if (
        ledger["attempt_bindings"] != expected_attempt_bindings
        or ledger["evaluator_metrics_artifact_ref"]
        != expected_metrics_artifact_ref
        or ledger["run_provenance_closure"]
        != {
            "closure": expected_run_closure,
            "closure_ref": canonical_ref(
                "run-provenance-closure", expected_run_closure
            ),
        }
    ):
        raise V2InvariantError("ledger/result attempt or metric binding differs")
    if ledger["attempts"] != summary["attempts"] or ledger["finalized"] != summary[
        "attempts"
    ]:
        raise V2InvariantError("ledger/result attempt denominators differ")
    if (
        ledger["receipt_refs_sha256"] != summary["receipt_refs_sha256"]
        or ledger["terminal_refs_sha256"] != summary["terminal_refs_sha256"]
        or ledger["stage_refs_sha256"] != summary["stage_refs_sha256"]
        or ledger["disposition_refs_sha256"]
        != summary["terminal_disposition_refs_sha256"]
        or ledger["witness_refs_sha256"] != summary["witness_refs_sha256"]
        or ledger["final_outcomes_sha256"]
        != summary["final_outcomes_sha256"]
        or ledger["witness_dispositions"]
        != summary["witness_dispositions"]
    ):
        raise V2InvariantError("ledger/result terminal inventories differ")
    _raw_digest(ledger["ledger_sha256"], "result ledger SHA-256")
    _raw_digest(ledger["artifact_refs_sha256"], "result artifact inventory SHA-256")
    _integer(ledger["artifacts"], "result artifact count", minimum=1)
    _integer(ledger["ledger_bytes"], "result ledger bytes", minimum=1)
    io_adaptation = tuple(
        sorted(
            (
                item
                for item in attempts
                if item.stage.phase == "adaptation"
                and item.stage.arm == "IO_FULL_ORDINARY_12"
            ),
            key=lambda item: (
                item.stage.replicate,
                item.stage.task_ordinal,
                FAMILIES.index(item.stage.family),
            ),
        )
    )
    expected_io_adaptation = 45 if purpose == "qualification" else 135
    if len(io_adaptation) != expected_io_adaptation:
        raise V2InvariantError("IO adaptation provenance denominator differs")
    adaptation_provenance: list[dict[str, object]] = []
    for item in io_adaptation:
        binding = {
            "attempt_final_ref": item.final_ref,
            "attempt_receipt_ref": item.attempt_receipt_ref,
            "family": item.stage.family,
            "proposal_admitted": item.observation.proposal_admitted,
            "public_task_ref": item.stage.public_task_ref,
            "replicate": item.stage.replicate,
            "replicate_commitment": item.stage.replicate_commitment,
            "resolution_ref": item.observation.resolution_ref,
            "source_adaptation_ordinal": item.stage.task_ordinal,
            "stage_ref": item.stage.stage_ref,
            "task_id": item.stage.task_id,
        }
        adaptation_provenance.append(
            {
                "binding": binding,
                "binding_ref": canonical_ref("adaptation-provenance", binding),
            }
        )
    frozen_payload = {
        "adaptation_provenance": adaptation_provenance,
        "baseline_seals": [
            {"seal": item.to_canonical(), "seal_ref": item.seal_ref}
            for item in frozen.baseline_seals
        ],
        "donor_catalogs": [
            {"catalog": item.to_canonical(), "catalog_ref": item.catalog_ref}
            for item in frozen.donor_catalogs
        ],
        "freeze": frozen.to_canonical(),
        "freeze_ref": frozen.freeze_ref,
    }
    payload: dict[str, object] = {
        "accounting": account,
        "attempts": summary,
        "authorization_ref": authorization_ref,
        "claim_boundary": {
            "classification": classification,
            "integrated_component_attribution": "PROHIBITED",
            "n0_f0_is_bundled": True,
            "promotion_or_capability_disposition": "NOT_PERFORMED",
            "statistical_role": (
                "NOT_APPLICABLE"
                if purpose == "qualification"
                else "FINITE_COHORT_DIRECTION_ONLY"
            ),
        },
        "evaluator": {
            "commitments": commitments,
            "commitments_ref": commitments_ref,
            "metrics": metrics,
            "metrics_ref": metrics_ref,
        },
        "frozen_adaptation": frozen_payload,
        "identity": identity,
        "integrity": {
            "ledger": ledger,
            "source_seal_ref": source_seal_ref,
            "status": "PASS",
        },
        "pair_equalities": {
            "count": expected_pairs,
            "items": [
                {"equality": item.to_canonical(), "equality_ref": item.equality_ref}
                for item in pairs
            ],
            "refs_sha256": hashlib.sha256(
                canonical_json_bytes(sorted(item.equality_ref for item in pairs))
            ).hexdigest(),
        },
        "protocol_identity": PROTOCOL_IDENTITY,
        "purpose": purpose,
        "resources": resource,
        "schema": RESULT_SCHEMA,
        "statistics": None if statistics is None else dict(statistics),
    }
    result = {**payload, "result_ref": canonical_ref("run-result", payload)}
    validate_run_result(result)
    return result


def _closed_result_mapping(
    value: object, keys: set[str] | frozenset[str], label: str
) -> dict[str, object]:
    if type(value) is not dict or set(value) != set(keys):
        raise V2InvariantError(f"{label} fields differ")
    return dict(value)


def _validate_serialized_attempt_summary(
    value: object, purpose: Purpose
) -> dict[str, object]:
    summary = _closed_result_mapping(
        value,
        {
            "admitted",
            "arm_counts",
            "attempts",
            "clone_cleanup_verified",
            "family_counts",
            "final_outcomes_sha256",
            "phase_counts",
            "proposal_malformed",
            "receipt_refs_sha256",
            "stage_refs_sha256",
            "successes",
            "terminal_disposition_refs_sha256",
            "terminal_refs_sha256",
            "witness_dispositions",
            "witness_refs_sha256",
        },
        "result attempt summary",
    )
    expected = 72 if purpose == "qualification" else 918
    expected_phases = dict(
        EXPECTED_QUALIFICATION_PHASE_ATTEMPTS
        if purpose == "qualification"
        else EXPECTED_EVALUATION_PHASE_ATTEMPTS
    )
    for key in (
        "admitted",
        "attempts",
        "clone_cleanup_verified",
        "proposal_malformed",
        "successes",
    ):
        summary[key] = _integer(summary[key], f"result attempts {key}")
    if (
        summary["attempts"] != expected
        or summary["admitted"] + summary["proposal_malformed"] != expected
        or summary["successes"] > summary["admitted"]
        or summary["clone_cleanup_verified"]
        != (6 if purpose == "qualification" else 162)
    ):
        raise V2InvariantError("result attempt arithmetic differs")
    for label, expected_keys in (
        ("arm_counts", set(ARMS)),
        ("family_counts", set(FAMILIES)),
        ("phase_counts", set(PHASES)),
    ):
        row = _closed_result_mapping(summary[label], expected_keys, label)
        row = {
            key: _integer(count, f"{label} {key}") for key, count in row.items()
        }
        if sum(row.values()) != expected:
            raise V2InvariantError(f"{label} denominator differs")
        summary[label] = row
    if summary["phase_counts"] != expected_phases:
        raise V2InvariantError("result phase counts differ")
    expected_arm_counts = {
        arm: (
            (48 if arm == "IO_FULL_ORDINARY_12" else 6 if arm == "IN_FULL_NEUTRAL_12" else 3)
            if purpose == "qualification"
            else (216 if arm in STATEFUL_ARMS else 81)
        )
        for arm in ARMS
    }
    expected_family_counts = {
        family: (24 if purpose == "qualification" else 306)
        for family in FAMILIES
    }
    if (
        summary["arm_counts"] != expected_arm_counts
        or summary["family_counts"] != expected_family_counts
    ):
        raise V2InvariantError("result arm/family denominators differ")
    witness = _closed_result_mapping(
        summary["witness_dispositions"],
        {"SATISFIED", "UNKNOWN", "VIOLATED"},
        "witness disposition counts",
    )
    witness = {
        key: _integer(count, f"witness count {key}")
        for key, count in witness.items()
    }
    if sum(witness.values()) != expected:
        raise V2InvariantError("witness disposition denominator differs")
    summary["witness_dispositions"] = witness
    for key in (
        "final_outcomes_sha256",
        "receipt_refs_sha256",
        "stage_refs_sha256",
        "terminal_disposition_refs_sha256",
        "terminal_refs_sha256",
        "witness_refs_sha256",
    ):
        _raw_digest(summary[key], f"result {key}")
    return summary


def _validate_serialized_evaluator(
    value: object,
    *,
    purpose: Purpose,
    identity: str,
    summary: Mapping[str, object],
) -> tuple[
    dict[str, object],
    tuple[str, ...],
    dict[str, int],
    dict[tuple[str, str], int],
]:
    evaluator = _closed_result_mapping(
        value,
        {"commitments", "commitments_ref", "metrics", "metrics_ref"},
        "result evaluator",
    )
    commitments = _closed_result_mapping(
        evaluator["commitments"],
        {
            "glyph_candidate_commitment",
            "identity",
            "protocol_identity",
            "purpose",
            "qualification_seed",
            "replicate_commitments",
            "replicate_labels",
            "tasks",
        },
        "evaluator commitments",
    )
    if (
        commitments["identity"] != identity
        or commitments["protocol_identity"] != PROTOCOL_IDENTITY
        or commitments["purpose"] != purpose
    ):
        raise V2InvariantError("evaluator commitment identity differs")
    expected_glyph = (
        GLYPH_DEVELOPMENT_CANDIDATE_COMMITMENT
        if purpose == "qualification"
        else GLYPH_FINAL_CANDIDATE_COMMITMENT
    )
    if commitments["glyph_candidate_commitment"] != expected_glyph:
        raise V2InvariantError("glyph candidate commitment differs")
    labels = commitments["replicate_labels"]
    replicate_values = commitments["replicate_commitments"]
    expected_labels = (
        ["qualification-01"]
        if purpose == "qualification"
        else ["replicate-01", "replicate-02", "replicate-03"]
    )
    if type(labels) is not list or labels != expected_labels or type(replicate_values) is not list:
        raise V2InvariantError("evaluator replicate labels differ")
    replicates = tuple(replicate_values)
    if purpose == "qualification":
        if (
            commitments["qualification_seed"] != QUALIFICATION_SEED
            or replicates != (qualification_replicate_commitment(),)
        ):
            raise V2InvariantError("qualification evaluator seed binding differs")
        expected_cells = {"adaptation": 15, "development": 1}
    else:
        if commitments["qualification_seed"] is not None:
            raise V2InvariantError("evaluation exposed a qualification seed")
        validate_evaluation_seed_commitments(replicates)
        expected_cells = {"adaptation": 15, "development": 3, "final": 6}
    tasks = commitments["tasks"]
    expected_task_count = 48 if purpose == "qualification" else 216
    if type(tasks) is not list or len(tasks) != expected_task_count:
        raise V2InvariantError("evaluator task commitment count differs")
    task_keys = {
        "family",
        "ordinal",
        "phase",
        "private_commitment",
        "public_task_ref",
        "replicate",
        "replicate_commitment",
        "task_id",
    }
    identities: list[tuple[str, str, str]] = []
    observed_task_order: list[tuple[str, str, str, int]] = []
    cell_ordinals: dict[tuple[str, str, str], set[int]] = defaultdict(set)
    by_label = dict(zip(expected_labels, replicates, strict=True))
    for raw_task in tasks:
        task = _closed_result_mapping(raw_task, task_keys, "task commitment")
        family = validate_family(task["family"])
        phase = validate_phase(task["phase"])
        label = task["replicate"]
        if label not in by_label or task["replicate_commitment"] != by_label[label]:
            raise V2InvariantError("task commitment lineage differs")
        for key in ("task_id", "public_task_ref", "private_commitment"):
            _ref(task[key], f"task commitment {key}")
        ordinal = _integer(task["ordinal"], "task commitment ordinal")
        if phase not in expected_cells or ordinal >= expected_cells[phase]:
            raise V2InvariantError("task commitment phase/ordinal differs")
        cell_ordinals[(label, family, phase)].add(ordinal)
        if task["task_id"] != domain_ref(
            TASK_ID_DOMAIN,
            {
                "family": family,
                "ordinal": ordinal,
                "phase": phase,
                "protocol_identity": PROTOCOL_IDENTITY,
                "public_task_ref": task["public_task_ref"],
                "replicate": label,
            },
        ):
            raise V2InvariantError("task id/public task commitment differs")
        identities.append(
            (str(task["task_id"]), str(task["public_task_ref"]), str(task["private_commitment"]))
        )
        observed_task_order.append((str(label), family, phase, ordinal))
    if any(len(set(column)) != len(tasks) for column in zip(*identities, strict=True)):
        raise V2InvariantError("evaluator task identities repeat")
    expected_cell_keys = {
        (label, family, phase)
        for label in expected_labels
        for family in FAMILIES
        for phase in expected_cells
    }
    if set(cell_ordinals) != expected_cell_keys or any(
        ordinals != set(range(expected_cells[key[2]]))
        for key, ordinals in cell_ordinals.items()
    ):
        raise V2InvariantError("evaluator task cells differ")
    expected_task_order = [
        (label, family, phase, ordinal)
        for label in expected_labels
        for phase, count in expected_cells.items()
        for ordinal in range(count)
        for family in FAMILIES
    ]
    if observed_task_order != expected_task_order:
        raise V2InvariantError("evaluator task commitment order differs")
    if evaluator["commitments_ref"] != _evaluator_digest(
        "evaluator-commitments", commitments
    ):
        raise V2InvariantError("evaluator commitments ref differs")
    metrics = _closed_result_mapping(
        evaluator["metrics"],
        {"aggregates", "identity", "protocol_identity", "purpose"},
        "evaluator metrics",
    )
    if (
        metrics["identity"] != identity
        or metrics["protocol_identity"] != PROTOCOL_IDENTITY
        or metrics["purpose"] != purpose
        or type(metrics["aggregates"]) is not list
        or not metrics["aggregates"]
    ):
        raise V2InvariantError("evaluator metrics identity differs")
    phase_counts: Counter[str] = Counter()
    family_counts: Counter[str] = Counter()
    arm_counts: Counter[str] = Counter()
    successes = 0
    metric_cells: set[tuple[str, str, str]] = set()
    observed_metric_order: list[tuple[str, str, str]] = []
    observed_metric_attempts: dict[tuple[str, str, str], int] = {}
    final_arm_successes = {arm: 0 for arm in ARMS}
    final_family_arm_successes = {
        (family, arm): 0 for family in FAMILIES for arm in ARMS
    }
    for raw_aggregate in metrics["aggregates"]:
        aggregate = _closed_result_mapping(
            raw_aggregate,
            {
                "arm",
                "attempts",
                "binary_success_total",
                "family",
                "pairwise_agreement_total",
                "phase",
            },
            "evaluator metric aggregate",
        )
        arm = validate_arm(aggregate["arm"])
        family = validate_family(aggregate["family"])
        phase = validate_phase(aggregate["phase"])
        cell = (phase, arm, family)
        if cell in metric_cells:
            raise V2InvariantError("evaluator metric cell repeats")
        metric_cells.add(cell)
        observed_metric_order.append(cell)
        attempts = _integer(aggregate["attempts"], "metric attempts", minimum=1)
        observed_metric_attempts[cell] = attempts
        binary = _integer(aggregate["binary_success_total"], "metric successes")
        if binary > attempts:
            raise V2InvariantError("metric successes exceed attempts")
        pairwise = aggregate["pairwise_agreement_total"]
        if family == "symbolic-demonstration-transfer":
            if type(pairwise) is not float:
                raise V2InvariantError("metric pairwise total must be exact float")
            pairwise = _finite(pairwise, "metric pairwise total")
            if not 0.0 <= pairwise <= float(attempts):
                raise V2InvariantError("metric pairwise total differs")
        elif pairwise is not None:
            raise V2InvariantError("metric pairwise total belongs to symbolic family")
        phase_counts[phase] += attempts
        family_counts[family] += attempts
        arm_counts[arm] += attempts
        successes += binary
        if phase == "final":
            final_arm_successes[arm] += binary
            final_family_arm_successes[(family, arm)] += binary
    expected_metric_attempts: dict[tuple[str, str, str], int] = {}
    for family in FAMILIES:
        if purpose == "qualification":
            expected_metric_attempts[("adaptation", "IN_FULL_NEUTRAL_12", family)] = 1
            expected_metric_attempts[("adaptation", "IO_FULL_ORDINARY_12", family)] = 15
            for arm in ARMS:
                expected_metric_attempts[("development", arm, family)] = 1
        else:
            for arm in STATEFUL_ARMS:
                expected_metric_attempts[("adaptation", arm, family)] = 45
            for phase, attempts in (("development", 9), ("final", 18)):
                for arm in ARMS:
                    expected_metric_attempts[(phase, arm, family)] = attempts
    if (
        observed_metric_attempts != expected_metric_attempts
        or observed_metric_order
        != [
            (phase, arm, family)
            for phase in (
                ("adaptation", "development")
                if purpose == "qualification"
                else PHASES
            )
            for arm in (
                ("IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12")
                if phase == "adaptation"
                else ARMS
            )
            for family in FAMILIES
        ]
        or
        {phase: phase_counts.get(phase, 0) for phase in PHASES}
        != summary["phase_counts"]
        or {family: family_counts.get(family, 0) for family in FAMILIES}
        != summary["family_counts"]
        or {arm: arm_counts.get(arm, 0) for arm in ARMS}
        != summary["arm_counts"]
        or successes != summary["successes"]
        or evaluator["metrics_ref"] != _evaluator_digest("final-metrics", metrics)
    ):
        raise V2InvariantError("evaluator metrics/result summary join differs")
    return evaluator, replicates, final_arm_successes, final_family_arm_successes


def _validate_serialized_frozen_adaptation(
    value: object,
    *,
    purpose: Purpose,
    replicates: tuple[str, ...],
    adaptation_tasks: Mapping[tuple[str, str, int], tuple[str, str]],
    ledger_bindings: Mapping[tuple[str, str], Mapping[str, object]],
    state_root: str | Path | None = None,
) -> dict[str, object]:
    expected_state_root = STATE_ROOT if state_root is None else Path(state_root)
    frozen = _closed_result_mapping(
        value,
        {
            "adaptation_provenance",
            "baseline_seals",
            "donor_catalogs",
            "freeze",
            "freeze_ref",
        },
        "result frozen adaptation",
    )
    provenance_rows = frozen["adaptation_provenance"]
    expected_provenance = 45 if purpose == "qualification" else 135
    if type(provenance_rows) is not list or len(provenance_rows) != expected_provenance:
        raise V2InvariantError("serialized adaptation provenance population differs")
    provenance_keys = {
        "attempt_final_ref",
        "attempt_receipt_ref",
        "family",
        "proposal_admitted",
        "public_task_ref",
        "replicate",
        "replicate_commitment",
        "resolution_ref",
        "source_adaptation_ordinal",
        "stage_ref",
        "task_id",
    }
    provenance: dict[tuple[str, str, int], dict[str, object]] = {}
    provenance_final_refs: set[str] = set()
    provenance_receipt_refs: set[str] = set()
    provenance_resolution_refs: set[str] = set()
    provenance_stage_refs: set[str] = set()
    provenance_task_ids: set[str] = set()
    observed_provenance_order: list[tuple[str, int, int]] = []
    for wrapped in provenance_rows:
        row = _closed_result_mapping(
            wrapped, {"binding", "binding_ref"}, "adaptation provenance wrapper"
        )
        binding = _closed_result_mapping(
            row["binding"], provenance_keys, "adaptation provenance"
        )
        replicate = _ref(
            binding["replicate_commitment"],
            "adaptation provenance replicate commitment",
        )
        family = validate_family(binding["family"])
        ordinal = _integer(
            binding["source_adaptation_ordinal"],
            "adaptation provenance ordinal",
            maximum=14,
        )
        key = (replicate, family, ordinal)
        expected_task = adaptation_tasks.get(key)
        if (
            key in provenance
            or expected_task is None
            or binding["task_id"] != expected_task[0]
            or binding["public_task_ref"] != expected_task[1]
            or type(binding["proposal_admitted"]) is not bool
            or (binding["proposal_admitted"] != (binding["resolution_ref"] is not None))
            or row["binding_ref"]
            != canonical_ref("adaptation-provenance", binding)
        ):
            raise V2InvariantError("serialized adaptation provenance binding differs")
        for name in (
            "attempt_final_ref",
            "attempt_receipt_ref",
            "public_task_ref",
            "stage_ref",
            "task_id",
        ):
            _ref(binding[name], f"adaptation provenance {name}")
        if binding["resolution_ref"] is not None:
            _ref(binding["resolution_ref"], "adaptation provenance resolution ref")
        ledger_binding = ledger_bindings.get(
            (str(binding["task_id"]), "IO_FULL_ORDINARY_12")
        )
        if (
            ledger_binding is None
            or ledger_binding["phase"] != "adaptation"
            or ledger_binding["replicate_commitment"] != replicate
            or ledger_binding["family"] != family
            or ledger_binding["public_task_ref"] != binding["public_task_ref"]
            or ledger_binding["stage_ref"] != binding["stage_ref"]
            or ledger_binding["attempt_receipt_ref"]
            != binding["attempt_receipt_ref"]
            or ledger_binding["final_ref"] != binding["attempt_final_ref"]
            or ledger_binding["proposal_admitted"]
            is not binding["proposal_admitted"]
            or ledger_binding["resolution_ref"] != binding["resolution_ref"]
        ):
            raise V2InvariantError(
                "serialized adaptation provenance is absent from the ledger"
            )
        final_ref = str(binding["attempt_final_ref"])
        receipt_ref = str(binding["attempt_receipt_ref"])
        stage_ref = str(binding["stage_ref"])
        task_id = str(binding["task_id"])
        resolution_ref = binding["resolution_ref"]
        if (
            final_ref in provenance_final_refs
            or receipt_ref in provenance_receipt_refs
            or stage_ref in provenance_stage_refs
            or task_id in provenance_task_ids
            or (
                resolution_ref is not None
                and str(resolution_ref) in provenance_resolution_refs
            )
        ):
            raise V2InvariantError("serialized adaptation provenance refs repeat")
        provenance_final_refs.add(final_ref)
        provenance_receipt_refs.add(receipt_ref)
        provenance_stage_refs.add(stage_ref)
        provenance_task_ids.add(task_id)
        if resolution_ref is not None:
            provenance_resolution_refs.add(str(resolution_ref))
        label = binding["replicate"]
        expected_label = (
            "qualification-01"
            if purpose == "qualification"
            else f"replicate-{replicates.index(replicate) + 1:02d}"
        )
        if label != expected_label:
            raise V2InvariantError("serialized adaptation provenance label differs")
        provenance[key] = binding
        observed_provenance_order.append((str(label), ordinal, FAMILIES.index(family)))
    expected_provenance_order = [
        (
            "qualification-01"
            if purpose == "qualification"
            else f"replicate-{replicate_index + 1:02d}",
            ordinal,
            family_index,
        )
        for replicate_index in range(len(replicates))
        for ordinal in range(15)
        for family_index in range(len(FAMILIES))
    ]
    if (
        set(provenance) != set(adaptation_tasks)
        or observed_provenance_order != expected_provenance_order
    ):
        raise V2InvariantError("serialized adaptation provenance inventory differs")
    baseline_rows = frozen["baseline_seals"]
    catalog_rows = frozen["donor_catalogs"]
    if (
        type(baseline_rows) is not list
        or len(baseline_rows) != 2 * len(replicates)
        or type(catalog_rows) is not list
        or len(catalog_rows) != len(replicates)
    ):
        raise V2InvariantError("frozen adaptation population differs")
    seal_keys = {
        "arm",
        "bootstrap_episode_ref",
        "encoder_ref",
        "genesis_competence_digest",
        "hashes",
        "model_ref",
        "neutral_chain_ref",
        "neutral_episode_refs",
        "purpose",
        "quiescent",
        "replicate_commitment",
        "root",
        "schema",
    }
    baseline_refs: list[str] = []
    baseline_cells: set[tuple[str, str]] = set()
    root_identities: list[tuple[str, int, int]] = []
    neutral_by_replicate: dict[str, tuple[str, ...]] = {}
    common_neutral_refs: tuple[str, ...] | None = None
    foundation_by_replicate: dict[str, tuple[str, str, str, str, str]] = {}
    common_foundation: tuple[str, str, str, str, str] | None = None
    for wrapped in baseline_rows:
        row = _closed_result_mapping(wrapped, {"seal", "seal_ref"}, "baseline wrapper")
        seal = _closed_result_mapping(row["seal"], seal_keys, "baseline seal")
        if (
            seal["schema"] != BASELINE_SEAL_SCHEMA
            or seal["purpose"] != purpose
            or seal["replicate_commitment"] not in replicates
            or seal["arm"] not in STATEFUL_ARMS
            or seal["quiescent"] is not True
        ):
            raise V2InvariantError("serialized baseline identity differs")
        hashes = _closed_result_mapping(seal["hashes"], BASELINE_HASH_NAMES, "baseline hashes")
        _hash_pairs(hashes, "serialized baseline hashes")
        refs = seal["neutral_episode_refs"]
        if type(refs) is not list or len(refs) != 12 or len(set(refs)) != 12:
            raise V2InvariantError("serialized neutral allowlist differs")
        for ref in refs:
            _ref(ref, "serialized neutral episode ref")
        for key in (
            "bootstrap_episode_ref",
            "encoder_ref",
            "genesis_competence_digest",
            "model_ref",
            "neutral_chain_ref",
        ):
            _ref(seal[key], f"serialized baseline {key}")
        if seal["bootstrap_episode_ref"] in refs:
            raise V2InvariantError("serialized neutral allowlist includes bootstrap")
        root = _text(seal["root"], "serialized baseline root", 4096)
        root_identity = _private_root_identity(root, "serialized baseline root")
        if (
            root_identity[0] != root
            or Path(root).parent
            != expected_state_root / f"{purpose}-v1" / "arm-runtime"
            or stat.S_IMODE(os.lstat(root).st_mode) != 0o700
        ):
            raise V2InvariantError("serialized baseline root is not canonical")
        root_identities.append(root_identity)
        seal_ref = canonical_ref("baseline-seal", seal)
        if row["seal_ref"] != seal_ref:
            raise V2InvariantError("serialized baseline ref differs")
        baseline_refs.append(seal_ref)
        cell = (str(seal["replicate_commitment"]), str(seal["arm"]))
        if cell in baseline_cells:
            raise V2InvariantError("serialized baseline cell repeats")
        baseline_cells.add(cell)
        prior = neutral_by_replicate.setdefault(cell[0], tuple(refs))
        if prior != tuple(refs):
            raise V2InvariantError("serialized IN/IO neutral chains differ")
        if common_neutral_refs is None:
            common_neutral_refs = tuple(refs)
        elif common_neutral_refs != tuple(refs):
            raise V2InvariantError("serialized replicate neutral allowlists differ")
        foundation = (
            str(seal["neutral_chain_ref"]),
            str(seal["bootstrap_episode_ref"]),
            str(seal["genesis_competence_digest"]),
            str(seal["model_ref"]),
            str(seal["encoder_ref"]),
        )
        prior_foundation = foundation_by_replicate.setdefault(cell[0], foundation)
        if prior_foundation != foundation:
            raise V2InvariantError("serialized IN/IO foundation bindings differ")
        if common_foundation is None:
            common_foundation = foundation
        elif common_foundation != foundation:
            raise V2InvariantError("serialized replicate foundations differ")
    if baseline_cells != {
        (replicate, arm) for replicate in replicates for arm in STATEFUL_ARMS
    } or len({item[0] for item in root_identities}) != len(root_identities) or len(
        {item[1:] for item in root_identities}
    ) != len(root_identities):
        raise V2InvariantError("serialized baseline inventory/roots differ")
    catalog_refs: list[str] = []
    catalog_replicates: set[str] = set()
    catalog_provenance_keys: set[tuple[str, str, int]] = set()
    global_record_refs: set[str] = set()
    global_acquisition_refs: set[str] = set()
    global_source_refs: set[str] = set()
    global_receipt_refs: set[str] = set()
    catalog_keys = {"entries", "excluded_counts", "replicate_commitment", "schema"}
    entry_keys = {
        "acquired_ordinal",
        "acquisition_ref",
        "attempt_receipt_ref",
        "family",
        "public_record_text_sha256",
        "public_task_ref",
        "record_bytes_sha256",
        "record_ref",
        "replicate_commitment",
        "source_adaptation_ordinal",
        "source_contract",
        "source_ref",
    }
    for wrapped in catalog_rows:
        row = _closed_result_mapping(wrapped, {"catalog", "catalog_ref"}, "catalog wrapper")
        catalog = _closed_result_mapping(row["catalog"], catalog_keys, "donor catalog")
        replicate = catalog["replicate_commitment"]
        if (
            catalog["schema"] != DONOR_CATALOG_SCHEMA
            or replicate not in replicates
            or replicate in catalog_replicates
            or type(catalog["entries"]) is not list
        ):
            raise V2InvariantError("serialized donor catalog identity differs")
        catalog_replicates.add(str(replicate))
        entries: list[tuple[int, str]] = []
        records: set[str] = set()
        acquisitions: set[str] = set()
        acquired_ordinals: set[int] = set()
        source_refs: set[str] = set()
        receipt_refs: set[str] = set()
        public_task_refs: set[str] = set()
        family_ordinals: set[tuple[str, int]] = set()
        family_counts: Counter[str] = Counter()
        for raw_entry in catalog["entries"]:
            entry = _closed_result_mapping(raw_entry, entry_keys, "donor catalog entry")
            if (
                entry["replicate_commitment"] != replicate
                or entry["source_contract"]
                != "ANG-CTR-PROSPECTIVE-RESOLUTION-001@0.1.0"
            ):
                raise V2InvariantError("serialized donor provenance differs")
            family = validate_family(entry["family"])
            ordinal = _integer(entry["source_adaptation_ordinal"], "donor source ordinal", maximum=14)
            acquired = _integer(entry["acquired_ordinal"], "donor acquired ordinal")
            for key in (
                "acquisition_ref",
                "attempt_receipt_ref",
                "public_task_ref",
                "record_ref",
                "source_ref",
            ):
                _ref(entry[key], f"donor {key}")
            for key in ("public_record_text_sha256", "record_bytes_sha256"):
                _raw_digest(entry[key], f"donor {key}")
            if entry["record_ref"] != "sha256:" + str(entry["record_bytes_sha256"]):
                raise V2InvariantError("serialized donor record digest differs")
            records.add(str(entry["record_ref"]))
            acquisitions.add(str(entry["acquisition_ref"]))
            acquired_ordinals.add(acquired)
            source_refs.add(str(entry["source_ref"]))
            receipt_refs.add(str(entry["attempt_receipt_ref"]))
            public_task_refs.add(str(entry["public_task_ref"]))
            family_ordinals.add((family, ordinal))
            family_counts[family] += 1
            entries.append((acquired, str(entry["record_ref"])))
            task_key = (str(replicate), family, ordinal)
            binding = provenance.get(task_key)
            if (
                task_key in catalog_provenance_keys
                or adaptation_tasks.get(task_key) is None
                or adaptation_tasks[task_key][1] != entry["public_task_ref"]
                or binding is None
                or binding["proposal_admitted"] is not True
                or binding["public_task_ref"] != entry["public_task_ref"]
                or binding["attempt_receipt_ref"] != entry["attempt_receipt_ref"]
                or binding["resolution_ref"] != entry["source_ref"]
            ):
                raise V2InvariantError("serialized donor evaluator task binding differs")
            catalog_provenance_keys.add(task_key)
        if (
            entries != sorted(entries)
            or len(records) != len(entries)
            or len(acquisitions) != len(entries)
            or len(acquired_ordinals) != len(entries)
            or len(source_refs) != len(entries)
            or len(receipt_refs) != len(entries)
            or len(public_task_refs) != len(entries)
            or len(family_ordinals) != len(entries)
            or any(family_counts[family] < 12 for family in FAMILIES)
        ):
            raise V2InvariantError("serialized donor catalog population differs")
        if (
            global_record_refs & records
            or global_acquisition_refs & acquisitions
            or global_source_refs & source_refs
            or global_receipt_refs & receipt_refs
        ):
            raise V2InvariantError("serialized donor refs alias across replicates")
        global_record_refs.update(records)
        global_acquisition_refs.update(acquisitions)
        global_source_refs.update(source_refs)
        global_receipt_refs.update(receipt_refs)
        excluded = catalog["excluded_counts"]
        allowed_exclusions = {
            "CONFIDENCE_PRESENT",
            "EPISTEMIC_STATUS",
            "KIND",
            "NOT_ADMITTED_IO_ADAPTATION",
            "SOURCE_CONTRACT",
            "VISIBILITY",
        }
        if (
            type(excluded) is not dict
            or not set(excluded).issubset(allowed_exclusions)
            or any(type(count) is not int or count < 1 for count in excluded.values())
        ):
            raise V2InvariantError("serialized donor exclusions differ")
        admitted_for_replicate = sum(
            binding["proposal_admitted"] is True
            for key, binding in provenance.items()
            if key[0] == replicate
        )
        # Every admitted IO turn appends the proposed dynamics batch and its
        # observed resolution.  Only the resolution is donor-eligible; both
        # acquisitions must close against the complete canonical store head.
        if (
            len(entries) + sum(excluded.values())
            != 13 + (2 * admitted_for_replicate)
        ):
            raise V2InvariantError("serialized donor acquisition-head closure differs")
        catalog_ref = canonical_ref("donor-catalog", catalog)
        if row["catalog_ref"] != catalog_ref:
            raise V2InvariantError("serialized donor catalog ref differs")
        catalog_refs.append(catalog_ref)
    if catalog_replicates != set(replicates):
        raise V2InvariantError("serialized donor replicate inventory differs")
    admitted_provenance = {
        key for key, binding in provenance.items() if binding["proposal_admitted"] is True
    }
    if catalog_provenance_keys != admitted_provenance:
        raise V2InvariantError("serialized donor/admitted IO population differs")
    freeze = _closed_result_mapping(
        frozen["freeze"],
        {"baseline_seal_refs", "donor_catalog_refs", "purpose"},
        "frozen-state receipt",
    )
    if (
        freeze["purpose"] != purpose
        or freeze["baseline_seal_refs"] != sorted(baseline_refs)
        or freeze["donor_catalog_refs"] != sorted(catalog_refs)
        or frozen["freeze_ref"] != canonical_ref("frozen-adaptation-state", freeze)
    ):
        raise V2InvariantError("serialized frozen-state receipt differs")
    return frozen


def _validate_serialized_pairs(
    value: object,
    *,
    purpose: Purpose,
    expected_task_ids: set[str],
) -> dict[str, object]:
    pairs = _closed_result_mapping(
        value, {"count", "items", "refs_sha256"}, "pair equality inventory"
    )
    expected = 6 if purpose == "qualification" else 162
    if (
        _integer(pairs["count"], "pair equality count") != expected
        or type(pairs["items"]) is not list
        or len(pairs["items"]) != expected
    ):
        raise V2InvariantError("pair equality denominator differs")
    equality_keys = {
        "history_text_equal",
        "left_arm",
        "padding_atoms_equal",
        "prompt_bytes_equal",
        "proposal_sets_equal",
        "right_arm",
        "schema",
        "task_id",
        "token_ids_equal",
    }
    refs: list[str] = []
    cells: set[tuple[str, str, str]] = set()
    for wrapped in pairs["items"]:
        row = _closed_result_mapping(wrapped, {"equality", "equality_ref"}, "pair equality wrapper")
        equality = _closed_result_mapping(row["equality"], equality_keys, "pair equality")
        pair = (equality["left_arm"], equality["right_arm"])
        if (
            equality["schema"] != PAIR_EQUALITY_SCHEMA
            or pair
            not in (
                ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"),
                ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"),
            )
            or any(
                equality[key] is not True
                for key in (
                    "history_text_equal",
                    "padding_atoms_equal",
                    "prompt_bytes_equal",
                    "proposal_sets_equal",
                    "token_ids_equal",
                )
            )
        ):
            raise V2InvariantError("serialized pair equality differs")
        task_id = _ref(equality["task_id"], "pair equality task id")
        ref = canonical_ref("pair-equality", equality)
        if row["equality_ref"] != ref or (task_id, *pair) in cells:
            raise V2InvariantError("pair equality ref/cell differs")
        cells.add((task_id, *pair))
        refs.append(ref)
    if pairs["refs_sha256"] != hashlib.sha256(
        canonical_json_bytes(sorted(refs))
    ).hexdigest():
        raise V2InvariantError("pair equality inventory hash differs")
    expected_cells = {
        (task_id, *pair)
        for task_id in expected_task_ids
        for pair in (
            ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"),
            ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"),
        )
    }
    if len(expected_task_ids) != expected // 2 or cells != expected_cells:
        raise V2InvariantError("pair equality task inventory differs")
    return pairs


def _validate_serialized_integrity(
    value: object,
    *,
    authorization_ref: str,
    evaluator: Mapping[str, object],
    frozen_adaptation_ref: str,
    purpose: Purpose,
    summary: Mapping[str, object],
) -> tuple[dict[str, object], dict[tuple[str, str], dict[str, object]]]:
    authorization_ref = _ref(
        authorization_ref, "serialized run authorization ref"
    )
    integrity = _closed_result_mapping(
        value, {"ledger", "source_seal_ref", "status"}, "result integrity"
    )
    if integrity["status"] != "PASS":
        raise V2InvariantError("result integrity status differs")
    _ref(integrity["source_seal_ref"], "result source seal ref")
    ledger = _closed_result_mapping(
        integrity["ledger"],
        {
            "attempts",
            "attempt_bindings",
            "artifact_refs_sha256",
            "artifacts",
            "disposition_refs_sha256",
            "evaluator_metrics_artifact_ref",
            "finalized",
            "final_outcomes_sha256",
            "ledger_bytes",
            "ledger_sha256",
            "receipt_refs_sha256",
            "run_provenance_closure",
            "stage_refs_sha256",
            "terminal_refs_sha256",
            "witness_dispositions",
            "witness_refs_sha256",
        },
        "result ledger witness",
    )
    expected = int(summary["attempts"])
    for key in ("attempts", "artifacts", "finalized", "ledger_bytes"):
        ledger[key] = _integer(ledger[key], f"ledger witness {key}", minimum=1)
    for key in (
        "artifact_refs_sha256",
        "disposition_refs_sha256",
        "final_outcomes_sha256",
        "ledger_sha256",
        "receipt_refs_sha256",
        "stage_refs_sha256",
        "terminal_refs_sha256",
        "witness_refs_sha256",
    ):
        _raw_digest(ledger[key], f"ledger witness {key}")
    witness_dispositions = _closed_result_mapping(
        ledger["witness_dispositions"],
        {"SATISFIED", "UNKNOWN", "VIOLATED"},
        "ledger witness dispositions",
    )
    ledger["witness_dispositions"] = {
        key: _integer(value, f"ledger witness disposition {key}")
        for key, value in witness_dispositions.items()
    }
    raw_bindings = ledger["attempt_bindings"]
    if type(raw_bindings) is not list or len(raw_bindings) != expected:
        raise V2InvariantError("ledger attempt-binding population differs")
    commitment_tasks = evaluator["commitments"]["tasks"]
    tasks = {str(item["task_id"]): item for item in commitment_tasks}
    bindings: dict[tuple[str, str], dict[str, object]] = {}
    observed_order: list[tuple[str, str]] = []
    unique_refs: dict[str, set[str]] = {
        name: set()
        for name in (
            "attempt_receipt_ref",
            "disposition_ref",
            "evaluator_record_ref",
            "final_ref",
            "stage_ref",
            "witness_ref",
        )
    }
    resolution_refs: set[str] = set()
    for raw_binding in raw_bindings:
        binding = _closed_result_mapping(
            raw_binding,
            _LEDGER_ATTEMPT_BINDING_KEYS,
            "ledger attempt binding",
        )
        task_id = _ref(binding["task_id"], "ledger binding task id")
        arm = validate_arm(binding["arm"])
        task = tasks.get(task_id)
        if task is None:
            raise V2InvariantError("ledger binding task is absent from evaluator")
        family = validate_family(binding["family"])
        phase = validate_phase(binding["phase"])
        replicate = _text(binding["replicate"], "ledger binding replicate", 32)
        replicate_commitment = _ref(
            binding["replicate_commitment"],
            "ledger binding replicate commitment",
        )
        public_task = _ref(
            binding["public_task_ref"], "ledger binding public task ref"
        )
        if (
            family != task["family"]
            or phase != task["phase"]
            or replicate != task["replicate"]
            or replicate_commitment != task["replicate_commitment"]
            or public_task != task["public_task_ref"]
        ):
            raise V2InvariantError("ledger binding evaluator metadata differs")
        proposal_admitted = binding["proposal_admitted"]
        success = binding["success"]
        clone_cleanup = binding["clone_cleanup_verified"]
        if (
            type(proposal_admitted) is not bool
            or type(success) is not bool
            or type(clone_cleanup) is not bool
            or (success and not proposal_admitted)
            or clone_cleanup
            is not (arm in STATEFUL_ARMS and phase in ("development", "final"))
            or binding["witness_disposition"]
            not in ("SATISFIED", "UNKNOWN", "VIOLATED")
        ):
            raise V2InvariantError("ledger binding outcome/lifecycle differs")
        for name in unique_refs:
            ref = _ref(binding[name], f"ledger binding {name}")
            if ref in unique_refs[name]:
                raise V2InvariantError("ledger binding terminal ref repeats")
            unique_refs[name].add(ref)
        resolution_ref = binding["resolution_ref"]
        if resolution_ref is not None:
            resolution_ref = _ref(resolution_ref, "ledger binding resolution ref")
            if resolution_ref in resolution_refs:
                raise V2InvariantError("ledger binding resolution ref repeats")
            resolution_refs.add(resolution_ref)
        if (resolution_ref is not None) != (
            proposal_admitted and arm in STATEFUL_ARMS
        ):
            raise V2InvariantError("ledger binding feedback applicability differs")
        cell = (task_id, arm)
        if cell in bindings:
            raise V2InvariantError("ledger binding task/arm cell repeats")
        bindings[cell] = binding
        observed_order.append(cell)
    if observed_order != sorted(observed_order):
        raise V2InvariantError("ledger attempt bindings are not canonical-order")
    expected_cells: set[tuple[str, str]] = set()
    for task_id, task in tasks.items():
        phase = str(task["phase"])
        if phase == "adaptation":
            arms = (
                ("IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12")
                if purpose == "evaluation" or int(task["ordinal"]) == 0
                else ("IO_FULL_ORDINARY_12",)
            )
        else:
            arms = ARMS
        expected_cells.update((task_id, arm) for arm in arms)
    if set(bindings) != expected_cells:
        raise V2InvariantError("ledger binding evaluator cell inventory differs")

    def digest_refs(name: str) -> str:
        return hashlib.sha256(
            canonical_json_bytes(sorted(str(row[name]) for row in bindings.values()))
        ).hexdigest()

    final_outcomes = sorted(
        (
            {
                "arm": row["arm"],
                "success": row["success"],
                "task_id": row["task_id"],
            }
            for row in bindings.values()
            if row["phase"] == "final"
        ),
        key=lambda item: (str(item["task_id"]), str(item["arm"])),
    )
    binding_arm_counts = Counter(str(row["arm"]) for row in bindings.values())
    binding_family_counts = Counter(
        str(row["family"]) for row in bindings.values()
    )
    binding_phase_counts = Counter(str(row["phase"]) for row in bindings.values())
    binding_witness_counts = Counter(
        str(row["witness_disposition"]) for row in bindings.values()
    )
    if (
        dict(sorted(binding_arm_counts.items())) != summary["arm_counts"]
        or dict(sorted(binding_family_counts.items())) != summary["family_counts"]
        or {phase: binding_phase_counts.get(phase, 0) for phase in PHASES}
        != summary["phase_counts"]
        or sum(row["proposal_admitted"] is True for row in bindings.values())
        != summary["admitted"]
        or sum(row["success"] is True for row in bindings.values())
        != summary["successes"]
        or sum(row["clone_cleanup_verified"] is True for row in bindings.values())
        != summary["clone_cleanup_verified"]
        or {
            name: binding_witness_counts.get(name, 0)
            for name in ("SATISFIED", "UNKNOWN", "VIOLATED")
        }
        != summary["witness_dispositions"]
        or digest_refs("attempt_receipt_ref") != summary["receipt_refs_sha256"]
        or digest_refs("stage_ref") != summary["stage_refs_sha256"]
        or digest_refs("disposition_ref")
        != summary["terminal_disposition_refs_sha256"]
        or digest_refs("final_ref") != summary["terminal_refs_sha256"]
        or digest_refs("witness_ref") != summary["witness_refs_sha256"]
        or hashlib.sha256(canonical_json_bytes(final_outcomes)).hexdigest()
        != summary["final_outcomes_sha256"]
    ):
        raise V2InvariantError("ledger bindings/result summary differ")
    metric_cells = {
        (str(row["phase"]), str(row["arm"]), str(row["family"])): (
            int(row["attempts"]),
            int(row["binary_success_total"]),
        )
        for row in evaluator["metrics"]["aggregates"]
    }
    ledger_metric_cells: dict[tuple[str, str, str], tuple[int, int]] = {}
    for phase, arm, family in metric_cells:
        selected = tuple(
            row
            for row in bindings.values()
            if row["phase"] == phase
            and row["arm"] == arm
            and row["family"] == family
        )
        ledger_metric_cells[(phase, arm, family)] = (
            len(selected),
            sum(row["success"] is True for row in selected),
        )
    expected_metrics_artifact_ref = canonical_ref(
        "evaluator-final-metrics", evaluator["metrics"]
    )
    frozen_adaptation_ref = _ref(
        frozen_adaptation_ref, "run provenance frozen adaptation ref"
    )
    expected_run_closure = _run_provenance_closure_payload(
        purpose=purpose,
        authorization_ref=authorization_ref,
        source_seal_ref=str(integrity["source_seal_ref"]),
        evaluator_commitments_ref=str(evaluator["commitments_ref"]),
        frozen_adaptation_ref=frozen_adaptation_ref,
        evaluator_metrics_artifact_ref=expected_metrics_artifact_ref,
    )
    run_closure = _closed_result_mapping(
        ledger["run_provenance_closure"],
        {"closure", "closure_ref"},
        "run provenance closure wrapper",
    )
    closure = _closed_result_mapping(
        run_closure["closure"],
        set(expected_run_closure),
        "run provenance closure",
    )
    if (
        ledger["attempts"] != expected
        or ledger["finalized"] != expected
        or ledger["receipt_refs_sha256"] != summary["receipt_refs_sha256"]
        or ledger["terminal_refs_sha256"] != summary["terminal_refs_sha256"]
        or ledger["stage_refs_sha256"] != summary["stage_refs_sha256"]
        or ledger["disposition_refs_sha256"]
        != summary["terminal_disposition_refs_sha256"]
        or ledger["witness_refs_sha256"] != summary["witness_refs_sha256"]
        or ledger["final_outcomes_sha256"]
        != summary["final_outcomes_sha256"]
        or ledger["witness_dispositions"]
        != summary["witness_dispositions"]
        or metric_cells != ledger_metric_cells
        or ledger["evaluator_metrics_artifact_ref"]
        != expected_metrics_artifact_ref
        or closure != expected_run_closure
        or run_closure["closure_ref"]
        != canonical_ref("run-provenance-closure", closure)
    ):
        raise V2InvariantError("ledger/result terminal join differs")
    integrity["ledger"] = ledger
    return integrity, bindings


def _validate_serialized_statistics(
    value: object,
    *,
    final_arm_successes: Mapping[str, int],
    final_family_arm_successes: Mapping[tuple[str, str], int],
    final_outcomes_sha256: str,
    final_task_metadata: Mapping[str, tuple[str, str, str]],
    ledger_bindings: Mapping[tuple[str, str], Mapping[str, object]],
) -> dict[str, object]:
    statistics = _closed_result_mapping(
        value,
        {
            "classification_boundary",
            "cohort",
            "contrasts",
            "denominator",
            "history_runtime_interaction",
            "primary_contrast_count",
            "schema",
            "statistics_ref",
        },
        "finite cohort statistics",
    )
    boundary = (
        "FINITE_COHORT_DIRECTION_ONLY; p-values are descriptive and "
        "independence-uncalibrated; no support/rule-out/promotion disposition"
    )
    if (
        statistics["schema"] != FINITE_COHORT_SCHEMA
        or statistics["classification_boundary"] != boundary
        or _integer(statistics["denominator"], "finite cohort denominator") != 54
        or _integer(
            statistics["primary_contrast_count"],
            "finite cohort primary contrast count",
        )
        != len(PRIMARY_CONTRASTS)
        or type(statistics["contrasts"]) is not list
        or len(statistics["contrasts"]) != len(PRIMARY_CONTRASTS)
    ):
        raise V2InvariantError("finite cohort header differs")
    contrast_keys = {
        "denominator",
        "direction",
        "effect_numerator",
        "exact_mcnemar_two_sided_hex",
        "family_strata",
        "holm_adjusted_hex",
        "left_arm",
        "left_failure_right_success",
        "left_success_right_failure",
        "left_successes",
        "recurrent_in_two_families",
        "recurrent_in_two_replicates",
        "replicate_strata",
        "reversals",
        "right_arm",
        "right_successes",
        "tied_failure",
        "tied_success",
    }

    def strata(raw: object, expected_names: tuple[str, ...], label: str) -> tuple[tuple[str, int, int], ...]:
        if type(raw) is not list or len(raw) != len(expected_names):
            raise V2InvariantError(f"{label} strata differ")
        rows: list[tuple[str, int, int]] = []
        for item in raw:
            row = _closed_result_mapping(
                item, {"denominator", "name", "numerator"}, f"{label} stratum"
            )
            rows.append(
                (
                    str(row["name"]),
                    _integer(
                        row["numerator"],
                        f"{label} numerator",
                        minimum=-18,
                        maximum=18,
                    ),
                    _integer(row["denominator"], f"{label} denominator", minimum=18, maximum=18),
                )
            )
        if tuple(name for name, _, _ in rows) != expected_names:
            raise V2InvariantError(f"{label} stratum names differ")
        return tuple(rows)

    if set(final_arm_successes) != set(ARMS) or any(
        type(count) is not int or not 0 <= count <= 54
        for count in final_arm_successes.values()
    ):
        raise V2InvariantError("final arm success inventory differs")
    if set(final_family_arm_successes) != {
        (family, arm) for family in FAMILIES for arm in ARMS
    } or any(
        type(count) is not int or not 0 <= count <= 18
        for count in final_family_arm_successes.values()
    ):
        raise V2InvariantError("final family/arm success inventory differs")
    raw_cohort = statistics["cohort"]
    if type(raw_cohort) is not list or len(raw_cohort) != 54:
        raise V2InvariantError("finite cohort serialized population differs")
    cohort_cells: dict[tuple[str, str], bool] = {}
    cohort_metadata: dict[str, tuple[str, str, str]] = {}
    observed_cohort_order: list[str] = []
    for raw_row in raw_cohort:
        row = _closed_result_mapping(
            raw_row,
            {"family", "replicate", "replicate_commitment", "successes", "task_id"},
            "finite cohort task row",
        )
        task_id = _ref(row["task_id"], "finite cohort task id")
        metadata = (
            validate_family(row["family"]),
            _text(row["replicate"], "finite cohort replicate", 32),
            _ref(
                row["replicate_commitment"],
                "finite cohort replicate commitment",
            ),
        )
        if (
            task_id in cohort_metadata
            or final_task_metadata.get(task_id) != metadata
        ):
            raise V2InvariantError("finite cohort evaluator task binding differs")
        successes = _closed_result_mapping(
            row["successes"], set(ARMS), "finite cohort arm successes"
        )
        if any(type(success) is not bool for success in successes.values()):
            raise V2InvariantError("finite cohort success is not exact bool")
        cohort_metadata[task_id] = metadata
        observed_cohort_order.append(task_id)
        for arm in ARMS:
            ledger_binding = ledger_bindings.get((task_id, arm))
            if (
                ledger_binding is None
                or ledger_binding["phase"] != "final"
                or ledger_binding["success"] is not successes[arm]
            ):
                raise V2InvariantError(
                    "finite cohort outcome is absent from the ledger"
                )
            cohort_cells[(task_id, arm)] = successes[arm]  # type: ignore[assignment]
    if (
        set(cohort_metadata) != set(final_task_metadata)
        or observed_cohort_order != sorted(observed_cohort_order)
        or Counter(value[0] for value in cohort_metadata.values())
        != Counter({family: 18 for family in FAMILIES})
        or Counter(value[1] for value in cohort_metadata.values())
        != Counter({f"replicate-{index:02d}": 18 for index in range(1, 4)})
        or Counter((value[0], value[1]) for value in cohort_metadata.values())
        != Counter(
            {
                (family, f"replicate-{index:02d}"): 6
                for family in FAMILIES
                for index in range(1, 4)
            }
        )
    ):
        raise V2InvariantError("finite cohort task strata differ")
    observed_arm_successes = {
        arm: sum(cohort_cells[(task_id, arm)] for task_id in cohort_metadata)
        for arm in ARMS
    }
    observed_family_arm_successes = {
        (family, arm): sum(
            cohort_cells[(task_id, arm)]
            for task_id, metadata in cohort_metadata.items()
            if metadata[0] == family
        )
        for family in FAMILIES
        for arm in ARMS
    }
    observed_final_outcomes_sha256 = hashlib.sha256(
        canonical_json_bytes(
            sorted(
                (
                    {
                        "arm": arm,
                        "success": cohort_cells[(task_id, arm)],
                        "task_id": task_id,
                    }
                    for task_id in cohort_metadata
                    for arm in ARMS
                ),
                key=lambda item: (str(item["task_id"]), str(item["arm"])),
            )
        )
    ).hexdigest()
    if (
        observed_arm_successes != dict(final_arm_successes)
        or observed_family_arm_successes != dict(final_family_arm_successes)
        or observed_final_outcomes_sha256
        != _raw_digest(
            final_outcomes_sha256,
            "finite cohort final outcome inventory SHA-256",
        )
    ):
        raise V2InvariantError("finite cohort/evaluator success totals differ")
    parsed: list[ContrastStatistic] = []
    effects: dict[tuple[str, str], int] = {}
    raw_p: dict[str, float] = {}
    for index, raw_contrast in enumerate(statistics["contrasts"]):
        row = _closed_result_mapping(raw_contrast, contrast_keys, "finite contrast")
        pair = (row["left_arm"], row["right_arm"])
        if pair != PRIMARY_CONTRASTS[index]:
            raise V2InvariantError("finite contrast order differs")
        reversals = row["reversals"]
        allowed_reversals = {
            *(f"family:{family}" for family in FAMILIES),
            *(f"replicate:replicate-{index:02d}" for index in range(1, 4)),
        }
        if (
            type(reversals) is not list
            or reversals != sorted(set(reversals))
            or not set(reversals).issubset(allowed_reversals)
        ):
            raise V2InvariantError("finite contrast reversals differ")
        item = ContrastStatistic(
            left_arm=pair[0],
            right_arm=pair[1],
            denominator=_integer(row["denominator"], "contrast denominator", minimum=1),
            left_successes=_integer(row["left_successes"], "left successes"),
            right_successes=_integer(row["right_successes"], "right successes"),
            left_failure_right_success=_integer(row["left_failure_right_success"], "positive discordance"),
            left_success_right_failure=_integer(row["left_success_right_failure"], "negative discordance"),
            tied_failure=_integer(row["tied_failure"], "tied failures"),
            tied_success=_integer(row["tied_success"], "tied successes"),
            effect_numerator=_integer(
                row["effect_numerator"],
                "effect numerator",
                minimum=-54,
                maximum=54,
            ),
            direction=str(row["direction"]),
            exact_mcnemar_two_sided_hex=str(row["exact_mcnemar_two_sided_hex"]),
            holm_adjusted_hex=str(row["holm_adjusted_hex"]),
            family_strata=strata(row["family_strata"], FAMILIES, "family"),
            replicate_strata=strata(
                row["replicate_strata"],
                ("replicate-01", "replicate-02", "replicate-03"),
                "replicate",
            ),
            recurrent_in_two_families=row["recurrent_in_two_families"],
            recurrent_in_two_replicates=row["recurrent_in_two_replicates"],
            reversals=tuple(reversals),
        )
        if item.denominator != 54 or item.to_canonical() != row:
            raise V2InvariantError("finite contrast canonical bytes differ")
        joint = Counter(
            (
                cohort_cells[(task_id, item.left_arm)],
                cohort_cells[(task_id, item.right_arm)],
            )
            for task_id in cohort_metadata
        )
        expected_family_strata = tuple(
            (
                family,
                sum(
                    int(cohort_cells[(task_id, item.right_arm)])
                    - int(cohort_cells[(task_id, item.left_arm)])
                    for task_id, metadata in cohort_metadata.items()
                    if metadata[0] == family
                ),
                18,
            )
            for family in FAMILIES
        )
        expected_replicate_strata = tuple(
            (
                replicate,
                sum(
                    int(cohort_cells[(task_id, item.right_arm)])
                    - int(cohort_cells[(task_id, item.left_arm)])
                    for task_id, metadata in cohort_metadata.items()
                    if metadata[1] == replicate
                ),
                18,
            )
            for replicate in ("replicate-01", "replicate-02", "replicate-03")
        )
        expected_reversals = sorted(
            [
                *(f"family:{name}" for name, numerator, _ in item.family_strata
                  if item.effect_numerator != 0
                  and numerator != 0
                  and (numerator > 0) != (item.effect_numerator > 0)),
                *(f"replicate:{name}" for name, numerator, _ in item.replicate_strata
                  if item.effect_numerator != 0
                  and numerator != 0
                  and (numerator > 0) != (item.effect_numerator > 0)),
            ]
        )
        expected_family_recurrence = sum(
            item.effect_numerator != 0
            and numerator != 0
            and (numerator > 0) == (item.effect_numerator > 0)
            for _, numerator, _ in item.family_strata
        ) >= 2
        expected_replicate_recurrence = sum(
            item.effect_numerator != 0
            and numerator != 0
            and (numerator > 0) == (item.effect_numerator > 0)
            for _, numerator, _ in item.replicate_strata
        ) >= 2
        if (
            sum(numerator for _, numerator, _ in item.family_strata)
            != item.effect_numerator
            or sum(numerator for _, numerator, _ in item.replicate_strata)
            != item.effect_numerator
            or item.recurrent_in_two_families is not expected_family_recurrence
            or item.recurrent_in_two_replicates is not expected_replicate_recurrence
            or list(item.reversals) != expected_reversals
            or item.left_successes != final_arm_successes[item.left_arm]
            or item.right_successes != final_arm_successes[item.right_arm]
            or (
                item.left_failure_right_success,
                item.left_success_right_failure,
                item.tied_failure,
                item.tied_success,
            )
            != (
                joint[(False, True)],
                joint[(True, False)],
                joint[(False, False)],
                joint[(True, True)],
            )
            or item.family_strata != expected_family_strata
            or item.replicate_strata != expected_replicate_strata
            or any(
                numerator
                != final_family_arm_successes[(family, item.right_arm)]
                - final_family_arm_successes[(family, item.left_arm)]
                for family, numerator, _ in item.family_strata
            )
        ):
            raise V2InvariantError("finite contrast strata/evaluator join differs")
        expected_p = exact_mcnemar_two_sided(
            item.left_failure_right_success,
            item.left_success_right_failure,
        )
        if item.exact_mcnemar_two_sided_hex != expected_p.hex():
            raise V2InvariantError("finite contrast McNemar value differs")
        raw_p[item.name] = expected_p
        parsed.append(item)
        effects[pair] = item.effect_numerator
    adjusted = holm_adjusted(raw_p)
    if any(item.holm_adjusted_hex != adjusted[item.name].hex() for item in parsed):
        raise V2InvariantError("finite contrast Holm values differ")
    interaction = _closed_result_mapping(
        statistics["history_runtime_interaction"],
        {"classification", "denominator", "direction", "effect_numerator", "formula"},
        "history/runtime interaction",
    )
    effect = _integer(
        interaction["effect_numerator"],
        "interaction numerator",
        minimum=-108,
        maximum=108,
    )
    if (
        interaction["classification"] != "SECONDARY_DESCRIPTIVE_ONLY"
        or interaction["denominator"] != 54
        or interaction["formula"] != "(IO-O0)-(IN-F0)"
        or interaction["direction"] != _direction(effect)
        or effect
        != effects[("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12")]
        - effects[("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12")]
        or effect
        != sum(
            int(cohort_cells[(task_id, "IO_FULL_ORDINARY_12")])
            - int(cohort_cells[(task_id, "O0_ORDINARY_FROZEN_12")])
            - int(cohort_cells[(task_id, "IN_FULL_NEUTRAL_12")])
            + int(cohort_cells[(task_id, "F0_NEUTRAL_FORMATTED_12")])
            for task_id in cohort_metadata
        )
    ):
        raise V2InvariantError("history/runtime interaction differs")
    payload = dict(statistics)
    observed_ref = payload.pop("statistics_ref")
    if observed_ref != canonical_ref("finite-cohort", payload):
        raise V2InvariantError("finite cohort statistics ref differs")
    return statistics


def validate_run_result(
    result: Mapping[str, object],
    *,
    state_root: str | Path | None = None,
) -> dict[str, object]:
    value = dict(result)
    if set(value) != _RESULT_KEYS or value.get("schema") != RESULT_SCHEMA:
        raise V2InvariantError("result top-level schema differs")
    purpose = validate_purpose(value.get("purpose"))
    authorization_ref = _ref(
        value.get("authorization_ref"), "result run authorization ref"
    )
    expected_identity = (
        QUALIFICATION_IDENTITY if purpose == "qualification" else EVALUATION_IDENTITY
    )
    if (
        value.get("protocol_identity") != PROTOCOL_IDENTITY
        or value.get("identity") != expected_identity
    ):
        raise V2InvariantError("result identity differs")
    result_ref = _ref(value.get("result_ref"), "result ref")
    without_ref = dict(value)
    without_ref.pop("result_ref")
    if result_ref != canonical_ref("run-result", without_ref):
        raise V2InvariantError("result ref does not bind canonical result bytes")
    encoded = canonical_json_bytes(value)
    if len(encoded) > MAXIMUM_RESULT_BYTES:
        raise V2IntegrityStop("result exceeds the frozen byte ceiling")
    forbidden_keys = {
        "answer",
        "expected_answer",
        "prompt",
        "proposals",
        "raw_response",
        "raw_seed",
        "raw_seeds",
        "seed",
        "seed_bytes",
        "seed_hex",
        "seeds",
        "selected_trace",
        "solution",
    }

    def walk(node: object) -> None:
        if type(node) is dict:
            if set(node) & forbidden_keys or any(
                type(key) is str and key.startswith("raw_") for key in node
            ):
                raise V2InvariantError("result exposes raw/private material")
            for child in node.values():
                walk(child)
        elif type(node) is list:
            for child in node:
                walk(child)

    walk(value)
    summary = _validate_serialized_attempt_summary(value["attempts"], purpose)
    (
        evaluator,
        replicates,
        final_arm_successes,
        final_family_arm_successes,
    ) = _validate_serialized_evaluator(
        value["evaluator"],
        purpose=purpose,
        identity=expected_identity,
        summary=summary,
    )
    raw_frozen_adaptation = value["frozen_adaptation"]
    if type(raw_frozen_adaptation) is not dict:
        raise V2InvariantError("result frozen adaptation is not an object")
    _, ledger_bindings = _validate_serialized_integrity(
        value["integrity"],
        authorization_ref=authorization_ref,
        evaluator=evaluator,
        frozen_adaptation_ref=_ref(
            raw_frozen_adaptation.get("freeze_ref"),
            "result frozen adaptation ref",
        ),
        purpose=purpose,
        summary=summary,
    )
    adaptation_tasks = {
        (
            str(task["replicate_commitment"]),
            str(task["family"]),
            int(task["ordinal"]),
        ): (str(task["task_id"]), str(task["public_task_ref"]))
        for task in evaluator["commitments"]["tasks"]
        if task["phase"] == "adaptation"
    }
    _validate_serialized_frozen_adaptation(
        value["frozen_adaptation"],
        purpose=purpose,
        replicates=replicates,
        adaptation_tasks=adaptation_tasks,
        ledger_bindings=ledger_bindings,
        state_root=state_root,
    )
    expected_pair_task_ids = {
        str(task["task_id"])
        for task in evaluator["commitments"]["tasks"]
        if task["phase"] != "adaptation"
    }
    final_task_metadata = {
        str(task["task_id"]): (
            str(task["family"]),
            str(task["replicate"]),
            str(task["replicate_commitment"]),
        )
        for task in evaluator["commitments"]["tasks"]
        if task["phase"] == "final"
    }
    _validate_serialized_pairs(
        value["pair_equalities"],
        purpose=purpose,
        expected_task_ids=expected_pair_task_ids,
    )
    account, resources = _validate_accounting_resources(
        purpose=purpose,
        accounting=_canonical_mapping(value["accounting"], "result accounting"),
        resources=_canonical_mapping(value["resources"], "result resources"),
    )
    if (
        account != value["accounting"]
        or resources != value["resources"]
        or account["execution_attempts"] != summary["admitted"]
        or resources["runtime_embedding_rows"]
        != sum(
            binding["proposal_admitted"] is True
            and binding["arm"] in STATEFUL_ARMS
            for binding in ledger_bindings.values()
        )
        * RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
    ):
        raise V2InvariantError("result accounting/resource join differs")
    claim = _closed_result_mapping(
        value["claim_boundary"],
        {
            "classification",
            "integrated_component_attribution",
            "n0_f0_is_bundled",
            "promotion_or_capability_disposition",
            "statistical_role",
        },
        "result claim boundary",
    )
    expected_claim = {
        "classification": (
            "TECHNICAL_QUALIFICATION_ONLY"
            if purpose == "qualification"
            else "EXPLORATORY_MECHANISTIC_FINITE_COHORT_ONLY"
        ),
        "integrated_component_attribution": "PROHIBITED",
        "n0_f0_is_bundled": True,
        "promotion_or_capability_disposition": "NOT_PERFORMED",
        "statistical_role": (
            "NOT_APPLICABLE"
            if purpose == "qualification"
            else "FINITE_COHORT_DIRECTION_ONLY"
        ),
    }
    if claim != expected_claim:
        raise V2InvariantError("result claim boundary differs")
    if claim["n0_f0_is_bundled"] is not True:
        raise V2InvariantError("result bundled-contrast flag is not exact bool")
    if purpose == "qualification":
        if value["statistics"] is not None:
            raise V2InvariantError("qualification result contains evaluation material")
    else:
        _validate_serialized_statistics(
            value["statistics"],
            final_arm_successes=final_arm_successes,
            final_family_arm_successes=final_family_arm_successes,
            final_outcomes_sha256=str(summary["final_outcomes_sha256"]),
            final_task_metadata=final_task_metadata,
            ledger_bindings=ledger_bindings,
        )
    return value


def publish_run_result_create_once(
    path: str | Path,
    result: Mapping[str, object],
) -> dict[str, object]:
    """Publish one canonical result directly with exclusive-create semantics."""

    target = Path(path)
    value = validate_run_result(result)
    expected = (
        QUALIFICATION_RESULT_PATH
        if value["purpose"] == "qualification"
        else EVALUATION_RESULT_PATH
    )
    if not target.is_absolute() or target != expected:
        raise V2InvariantError("result publication path differs")

    def current_authorization() -> tuple[str, str, str]:
        manifest, manifest_sha256, source_seal = load_source_manifest()
        source_seal_ref = _ref(
            source_seal["source_seal_ref"], "publication source seal"
        )
        if value["integrity"]["source_seal_ref"] != source_seal_ref:
            raise V2IntegrityStop("result publication source seal differs")
        if value["purpose"] == "qualification":
            release, release_sha256 = load_qualification_release_claim(
                manifest, manifest_sha256, source_seal
            )
            authorization_ref = _ref(
                release["release_ref"], "qualification publication authorization"
            )
            authorization_sha256 = release_sha256
        else:
            admission, admission_sha256 = load_evaluation_admission_claim()
            authorization_ref = _ref(
                admission["admission_ref"], "evaluation publication authorization"
            )
            authorization_sha256 = admission_sha256
        if value["authorization_ref"] != authorization_ref:
            raise V2IntegrityStop("result publication authorization differs")
        return source_seal_ref, authorization_ref, authorization_sha256

    authorization_before = current_authorization()
    ledger_path = (
        QUALIFICATION_EVIDENCE_LEDGER_PATH
        if value["purpose"] == "qualification"
        else EVALUATION_EVIDENCE_LEDGER_PATH
    )
    live_ledger = audit_evidence_ledger(
        ledger_path,
        expected_attempts=(72 if value["purpose"] == "qualification" else 918),
    )
    if live_ledger != value["integrity"]["ledger"]:
        raise V2IntegrityStop("result publication ledger witness differs")
    raw = canonical_json_bytes(value)
    if len(raw) > MAXIMUM_RESULT_BYTES:
        raise V2IntegrityStop("result publication exceeds the byte ceiling")
    parent_identity = _require_owned_directory(
        target.parent,
        expected_mode=0o755,
        label="result publication parent",
    )
    flags = (
        os.O_CREAT
        | os.O_EXCL
        | os.O_WRONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor = os.open(target, flags, 0o600)
    created_identity: tuple[int, int] | None = None
    try:
        created = os.fstat(descriptor)
        created_identity = (int(created.st_dev), int(created.st_ino))
        view = memoryview(raw)
        while view:
            written = os.write(descriptor, view)
            if written <= 0:
                raise OSError("short result write")
            view = view[written:]
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    metadata = os.lstat(target)
    reopened = os.open(target, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        reopened_metadata = os.fstat(reopened)
        observed = bytearray()
        while len(observed) <= MAXIMUM_RESULT_BYTES:
            block = os.read(
                reopened,
                min(
                    1024 * 1024,
                    MAXIMUM_RESULT_BYTES + 1 - len(observed),
                ),
            )
            if not block:
                break
            observed.extend(block)
    finally:
        os.close(reopened)
    if (
        created_identity is None
        or (metadata.st_dev, metadata.st_ino) != created_identity
        or (reopened_metadata.st_dev, reopened_metadata.st_ino) != created_identity
        or not stat.S_ISREG(metadata.st_mode)
        or stat.S_IMODE(metadata.st_mode) != 0o600
        or metadata.st_nlink != 1
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
        or bytes(observed) != raw
    ):
        raise V2IntegrityStop("published result metadata/bytes changed")
    parent_descriptor = os.open(
        target.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    )
    try:
        os.fsync(parent_descriptor)
    finally:
        os.close(parent_descriptor)
    if (
        _require_owned_directory(
            target.parent,
            expected_mode=0o755,
            label="result publication parent closure",
        )
        != parent_identity
    ):
        raise V2IntegrityStop("result publication parent changed")
    if current_authorization() != authorization_before:
        raise V2IntegrityStop("result publication authorization changed")
    return {
        "bytes": len(raw),
        "path": str(target),
        "result_ref": value["result_ref"],
        "sha256": hashlib.sha256(raw).hexdigest(),
    }


@dataclass(frozen=True, slots=True)
class FrozenRecallCapture:
    """One pre-arm canonical recall capture and its destroyed capture clone."""

    task_id: str
    public_task_ref: str
    replicate_commitment: str
    kind: Literal["neutral", "ordinary"]
    query_ref: str
    backend_binding_ref: str
    source_baseline_seal_ref: str
    capture_clone_ref: str
    presentations: tuple[HistoryPresentation, ...]
    rejected_refs: tuple[str, ...]
    capture_quiescent: bool
    capture_disposed: bool
    cleanup_absence_verified: bool
    cleanup_paths: tuple[str, ...] = ()
    source_root: str | None = None
    source_hashes: tuple[tuple[str, str], ...] = ()
    capture_terminal_hashes: tuple[tuple[str, str], ...] = ()
    allocation_ref: str | None = None

    def __post_init__(self) -> None:
        for label, value in (
            ("recall task id", self.task_id),
            ("recall public task ref", self.public_task_ref),
            ("recall replicate commitment", self.replicate_commitment),
            ("recall query ref", self.query_ref),
            ("recall backend binding ref", self.backend_binding_ref),
            ("recall baseline seal ref", self.source_baseline_seal_ref),
            ("recall capture clone ref", self.capture_clone_ref),
        ):
            _ref(value, label)
        if self.kind not in ("neutral", "ordinary"):
            raise ValueError("recall capture kind differs")
        if (
            type(self.presentations) is not tuple
            or len(self.presentations) != 12
            or tuple(item.slot for item in self.presentations) != tuple(range(12))
            or len({item.record_ref for item in self.presentations}) != 12
            or any(
                item.neutral != (self.kind == "neutral")
                for item in self.presentations
            )
            or any(item.padding_atoms != 0 for item in self.presentations)
        ):
            raise V2InvariantError("recall capture presentation inventory differs")
        if type(self.rejected_refs) is not tuple:
            raise TypeError("recall rejected refs must be a tuple")
        for value in self.rejected_refs:
            _ref(value, "recall rejected ref")
        if (
            self.capture_quiescent is not True
            or (self.capture_disposed, self.cleanup_absence_verified)
            not in ((False, False), (True, True))
        ):
            raise V2IntegrityStop("recall capture clone state is inconsistent")
        if (
            type(self.cleanup_paths) is not tuple
            or len(set(self.cleanup_paths)) != len(self.cleanup_paths)
        ):
            raise V2InvariantError("recall capture cleanup paths differ")
        for value in self.cleanup_paths:
            path = Path(value)
            if not path.is_absolute() or str(path) != value or ".." in path.parts:
                raise V2InvariantError("recall cleanup path is not canonical")
        if self.source_root is not None:
            source = Path(self.source_root)
            if (
                not source.is_absolute()
                or str(source) != self.source_root
                or ".." in source.parts
                or self.source_hashes
                != _hash_pairs(dict(self.source_hashes), "recall source hashes")
            ):
                raise V2InvariantError("recall capture source binding differs")
        elif self.source_hashes:
            raise V2InvariantError("recall capture hashes lack a source root")
        if self.capture_terminal_hashes != _hash_pairs(
            dict(self.capture_terminal_hashes), "recall capture terminal hashes"
        ):
            raise V2InvariantError("recall capture terminal hashes are not canonical")
        if self.cleanup_paths and (
            self.source_root is None
            or not self.source_hashes
            or self.capture_terminal_hashes != self.source_hashes
        ):
            raise V2IntegrityStop("recall capture terminal/source hashes differ")
        if self.allocation_ref is not None:
            _ref(self.allocation_ref, "recall path allocation ref")

    @property
    def terminal_payload(self) -> dict[str, object]:
        """Immutable pre-cleanup evidence that must be durable before disposal."""

        return {
            "backend_binding_ref": self.backend_binding_ref,
            "allocation_ref": self.allocation_ref,
            "capture_clone_ref": self.capture_clone_ref,
            "capture_quiescent": self.capture_quiescent,
            "capture_terminal_hashes": dict(self.capture_terminal_hashes),
            "cleanup_paths": list(self.cleanup_paths),
            "kind": self.kind,
            "presentations": [item.to_canonical() for item in self.presentations],
            "public_task_ref": self.public_task_ref,
            "query_ref": self.query_ref,
            "rejected_refs": list(self.rejected_refs),
            "replicate_commitment": self.replicate_commitment,
            "source_baseline_seal_ref": self.source_baseline_seal_ref,
            "source_hashes": dict(self.source_hashes),
            "source_root": self.source_root,
            "task_id": self.task_id,
        }

    @property
    def terminal_ref(self) -> str:
        return canonical_ref("recall-capture-terminal", self.terminal_payload)

    @property
    def cleanup_complete(self) -> bool:
        return self.capture_disposed and self.cleanup_absence_verified

    @property
    def cleanup_payload(self) -> dict[str, object]:
        if not self.cleanup_complete:
            raise V2IntegrityStop("recall capture cleanup is incomplete")
        return {
            "allocation_ref": self.allocation_ref,
            "capture_disposed": self.capture_disposed,
            "cleanup_absence_verified": self.cleanup_absence_verified,
            "cleanup_paths": list(self.cleanup_paths),
            "terminal_ref": self.terminal_ref,
        }

    @property
    def cleanup_ref(self) -> str:
        return canonical_ref("recall-capture-cleanup", self.cleanup_payload)

    @property
    def capture_ref(self) -> str:
        return canonical_ref("frozen-recall-capture", self.to_canonical())

    def validates_plan(self, plan: HistoryPlan) -> None:
        if type(plan) is not HistoryPlan or plan.task_id != self.task_id:
            raise V2InvariantError("recall capture/history task differs")
        expected_arms = (
            {"F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"}
            if self.kind == "neutral"
            else {"O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"}
        )
        if plan.arm not in expected_arms:
            raise V2InvariantError("recall capture/history arm differs")
        for index, (captured, presented) in enumerate(
            zip(self.presentations, plan.presentations, strict=True)
        ):
            if (
                captured.record_ref != presented.record_ref
                or captured.acquisition_ref != presented.acquisition_ref
                or captured.source_ref != presented.source_ref
                or captured.raw_record_sha256 != presented.raw_record_sha256
                or captured.neutral is not presented.neutral
                or presented.presented_text
                != captured.presented_text
                + PADDING_ATOM * presented.padding_atoms
                or (index != RECALL_SLOTS - 1 and presented.padding_atoms != 0)
            ):
                raise V2InvariantError("frozen recall capture/history bytes differ")
        if plan.presentations[-1].padding_atoms > MAXIMUM_PADDING_ATOMS:
            raise V2InvariantError("frozen recall capture/history bytes differ")

    def to_canonical(self) -> dict[str, object]:
        return {
            "backend_binding_ref": self.backend_binding_ref,
            "allocation_ref": self.allocation_ref,
            "capture_clone_ref": self.capture_clone_ref,
            "capture_disposed": self.capture_disposed,
            "capture_quiescent": self.capture_quiescent,
            "capture_terminal_hashes": dict(self.capture_terminal_hashes),
            "cleanup_absence_verified": self.cleanup_absence_verified,
            "cleanup_paths": list(self.cleanup_paths),
            "kind": self.kind,
            "presentations": [item.to_canonical() for item in self.presentations],
            "public_task_ref": self.public_task_ref,
            "query_ref": self.query_ref,
            "rejected_refs": list(self.rejected_refs),
            "replicate_commitment": self.replicate_commitment,
            "source_baseline_seal_ref": self.source_baseline_seal_ref,
            "source_hashes": dict(self.source_hashes),
            "source_root": self.source_root,
            "task_id": self.task_id,
            "terminal_ref": self.terminal_ref,
        }


def freeze_recall_capture(
    *,
    task: object,
    kind: Literal["neutral", "ordinary"],
    recall_batch: object,
    query_ref: str,
    backend_binding_ref: str,
    source_baseline_seal_ref: str,
    capture_clone_ref: str,
    capture_quiescent: bool,
    capture_disposed: bool,
    cleanup_absence_verified: bool,
    cleanup_paths: Sequence[str] = (),
    source_root: str | None = None,
    source_hashes: Mapping[str, str] | None = None,
    capture_terminal_hashes: Mapping[str, str] | None = None,
    allocation_ref: str | None = None,
) -> FrozenRecallCapture:
    canonical = _task_canonical(task)
    items = getattr(recall_batch, "items", None)
    rejected = getattr(recall_batch, "rejected", ())
    if type(items) is not tuple or len(items) != 12 or type(rejected) is not tuple:
        raise V2InvariantError("recall capture batch shape differs")
    presentations: list[HistoryPresentation] = []
    for index, item in enumerate(items):
        record = getattr(item, "record", None)
        record_ref = getattr(item, "record_ref", None)
        acquisition_ref = getattr(item, "acquisition_ref", None)
        raw = _canonical_object_bytes(record, "recall capture canonical record")
        if getattr(record, "record_ref", None) != record_ref:
            raise V2InvariantError("recall capture item/record ref differs")
        presentations.append(
            HistoryPresentation(
                slot=index,
                record_ref=record_ref,
                acquisition_ref=acquisition_ref,
                source_ref=_ref(
                    getattr(item, "source_ref", None),
                    "recall capture source ref",
                ),
                raw_record_sha256=hashlib.sha256(raw).hexdigest(),
                presented_text=(
                    neutral_presentation(index)
                    if kind == "neutral"
                    else _text(getattr(item, "text", None), "ordinary recall text")
                ),
                neutral=(kind == "neutral"),
            )
        )
    return FrozenRecallCapture(
        task_id=str(canonical["task_id"]),
        public_task_ref=public_task_ref(canonical),
        replicate_commitment=str(canonical["replicate_commitment"]),
        kind=kind,
        query_ref=query_ref,
        backend_binding_ref=backend_binding_ref,
        source_baseline_seal_ref=source_baseline_seal_ref,
        capture_clone_ref=capture_clone_ref,
        presentations=tuple(presentations),
        rejected_refs=tuple(rejected),
        capture_quiescent=capture_quiescent,
        capture_disposed=capture_disposed,
        cleanup_absence_verified=cleanup_absence_verified,
        cleanup_paths=tuple(cleanup_paths),
        source_root=source_root,
        source_hashes=(
            ()
            if source_hashes is None
            else _hash_pairs(source_hashes, "recall source hashes")
        ),
        capture_terminal_hashes=(
            _hash_pairs(
                source_hashes or {}, "recall capture terminal hashes"
            )
            if capture_terminal_hashes is None
            else _hash_pairs(
                capture_terminal_hashes, "recall capture terminal hashes"
            )
        ),
        allocation_ref=allocation_ref,
    )


@dataclass(frozen=True, slots=True)
class PrivateRecallReplay:
    """Exact in-memory reference hits and canonical batch for one IO replay."""

    capture: FrozenRecallCapture
    hits: tuple[object, ...] = field(repr=False)
    batch: object = field(repr=False)

    def __post_init__(self) -> None:
        if type(self.capture) is not FrozenRecallCapture or self.capture.kind != "ordinary":
            raise V2InvariantError("private recall replay requires ordinary capture")
        from angler.memory.cognitive_acquisition_graph import (
            AcquisitionRecallBatch,
            AcquisitionReferenceHit,
        )

        if (
            type(self.hits) is not tuple
            or len(self.hits) != 12
            or any(type(item) is not AcquisitionReferenceHit for item in self.hits)
            or type(self.batch) is not AcquisitionRecallBatch
            or type(self.batch.items) is not tuple
            or len(self.batch.items) != 12
            or self.batch.rejected != ()
        ):
            raise V2IntegrityStop("private ordinary recall population differs")
        hit_refs = tuple(item.record_ref for item in self.hits)
        item_refs = tuple(item.record_ref for item in self.batch.items)
        capture_refs = tuple(item.record_ref for item in self.capture.presentations)
        if (
            hit_refs != item_refs
            or item_refs != capture_refs
            or len(set(hit_refs)) != 12
            or self._batch_binding(self.batch) != self._capture_binding()
        ):
            raise V2IntegrityStop("private ordinary recall order/content differs")

    def _capture_binding(self) -> tuple[tuple[str, str, str, str, str], ...]:
        return tuple(
            (
                item.record_ref,
                item.acquisition_ref,
                item.source_ref,
                item.raw_record_sha256,
                hashlib.sha256(item.presented_text.encode("utf-8")).hexdigest(),
            )
            for item in self.capture.presentations
        )

    @staticmethod
    def _batch_binding(batch: object) -> tuple[tuple[str, str, str, str, str], ...]:
        return tuple(
            (
                item.record_ref,
                item.acquisition_ref,
                item.source_ref,
                hashlib.sha256(
                    _canonical_object_bytes(item.record, "private recall record")
                ).hexdigest(),
                hashlib.sha256(
                    _text(item.text, "private recall text").encode("utf-8")
                ).hexdigest(),
            )
            for item in batch.items
        )

    @property
    def hit_material_sha256(self) -> str:
        rows = [
            {
                "adjacent_record_refs": list(item.adjacent_record_refs),
                "backend_ref": item.backend_ref,
                "record_ref": item.record_ref,
                "score": item.score,
            }
            for item in self.hits
        ]
        return hashlib.sha256(canonical_json_bytes(rows)).hexdigest()

    @property
    def replay_ref(self) -> str:
        return canonical_ref(
            "private-recall-replay",
            {
                "capture_terminal_ref": self.capture.terminal_ref,
                "hit_count": len(self.hits),
                "hit_material_sha256": self.hit_material_sha256,
            },
        )

    def replay(self, acquisition_memory: object) -> object:
        method = getattr(acquisition_memory, "recall_from_hits", None)
        if not callable(method):
            raise TypeError("private recall target lacks recall_from_hits")
        observed = method(self.hits, limit=12, frozen_origin=True)
        if (
            type(observed) is not type(self.batch)
            or getattr(observed, "rejected", None) != ()
            or self._batch_binding(observed) != self._capture_binding()
        ):
            raise V2IntegrityStop("private ordinary recall replay changed")
        return observed


@dataclass(frozen=True, slots=True)
class PreparedTaskBlock:
    """All task histories/prompts frozen before the first arm generation."""

    task_id: str
    public_task_ref: str
    replicate_commitment: str
    frozen_state_ref: str
    baseline_seal_refs: tuple[tuple[str, str], ...]
    neutral_episode_refs: tuple[str, ...]
    donor_catalog_ref: str
    prompt_plans: tuple[tuple[Arm, PromptPlan], ...]
    pair_equalities: tuple[PairEqualityEvidence, PairEqualityEvidence]
    neutral_recall: FrozenRecallCapture
    ordinary_recall: FrozenRecallCapture
    ordinary_private_replay: PrivateRecallReplay | None = field(
        default=None, repr=False, compare=False
    )
    frozen_before_generation: bool = True

    def __post_init__(self) -> None:
        _ref(self.task_id, "prepared task id")
        _ref(self.public_task_ref, "prepared public task ref")
        _ref(self.replicate_commitment, "prepared replicate commitment")
        _ref(self.frozen_state_ref, "prepared frozen-state ref")
        _ref(self.donor_catalog_ref, "prepared donor catalog ref")
        if (
            type(self.baseline_seal_refs) is not tuple
            or tuple(name for name, _ in self.baseline_seal_refs)
            != ("IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12")
        ):
            raise V2InvariantError("prepared baseline seal inventory differs")
        for _arm, value in self.baseline_seal_refs:
            _ref(value, "prepared baseline seal ref")
        if (
            type(self.prompt_plans) is not tuple
            or tuple(arm for arm, _ in self.prompt_plans) != ARMS
            or any(
                type(plan) is not PromptPlan
                or plan.arm != arm
                or plan.task_id != self.task_id
                for arm, plan in self.prompt_plans
            )
        ):
            raise V2InvariantError("prepared task prompt matrix differs")
        if (
            type(self.pair_equalities) is not tuple
            or len(self.pair_equalities) != 2
            or tuple(
                (item.left_arm, item.right_arm) for item in self.pair_equalities
            )
            != (
                ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"),
                ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"),
            )
            or any(item.task_id != self.task_id for item in self.pair_equalities)
        ):
            raise V2InvariantError("prepared task equality evidence differs")
        if (
            type(self.neutral_recall) is not FrozenRecallCapture
            or type(self.ordinary_recall) is not FrozenRecallCapture
            or self.neutral_recall.kind != "neutral"
            or self.ordinary_recall.kind != "ordinary"
        ):
            raise V2InvariantError("prepared frozen recall captures differ")
        for capture in (self.neutral_recall, self.ordinary_recall):
            if (
                capture.task_id != self.task_id
                or capture.public_task_ref != self.public_task_ref
                or capture.replicate_commitment != self.replicate_commitment
            ):
                raise V2InvariantError("prepared recall capture task/lineage differs")
        if self.ordinary_private_replay is not None and (
            type(self.ordinary_private_replay) is not PrivateRecallReplay
            or self.ordinary_private_replay.capture.capture_ref
            != self.ordinary_recall.capture_ref
        ):
            raise V2InvariantError("prepared private ordinary recall differs")
        plans = dict(self.prompt_plans)
        for arm in ("F0_NEUTRAL_FORMATTED_12", "IN_FULL_NEUTRAL_12"):
            self.neutral_recall.validates_plan(plans[arm].history_plan)
        for arm in ("O0_ORDINARY_FROZEN_12", "IO_FULL_ORDINARY_12"):
            self.ordinary_recall.validates_plan(plans[arm].history_plan)
        baseline_refs = dict(self.baseline_seal_refs)
        if (
            self.neutral_recall.source_baseline_seal_ref
            != baseline_refs["IN_FULL_NEUTRAL_12"]
            or self.ordinary_recall.source_baseline_seal_ref
            != baseline_refs["IO_FULL_ORDINARY_12"]
        ):
            raise V2InvariantError("prepared recall capture baseline differs")
        if (
            type(self.neutral_episode_refs) is not tuple
            or len(self.neutral_episode_refs) != 12
            or tuple(item.source_ref for item in self.neutral_recall.presentations)
            != self.neutral_episode_refs
        ):
            raise V2InvariantError("prepared neutral recall allowlist differs")
        if self.frozen_before_generation is not True:
            raise V2InvariantError("task histories were not frozen before generation")

    @classmethod
    def create(
        cls,
        *,
        task: object,
        prompt_plans: Mapping[Arm, PromptPlan],
        pair_equalities: Sequence[PairEqualityEvidence],
        frozen: "FrozenAdaptationState",
        neutral_recall: FrozenRecallCapture,
        ordinary_recall: FrozenRecallCapture,
        ordinary_private_replay: PrivateRecallReplay | None = None,
    ) -> "PreparedTaskBlock":
        canonical = _task_canonical(task)
        if type(frozen) is not FrozenAdaptationState:
            raise TypeError("prepared task frozen state differs")
        replicate_commitment = str(canonical["replicate_commitment"])
        baselines = frozen.baselines_for(replicate_commitment)
        catalog = frozen.catalog_for(replicate_commitment)
        plans = dict(prompt_plans)
        if set(plans) != set(ARMS):
            raise V2InvariantError("prepared task requires all eight prompt plans")
        return cls(
            task_id=str(canonical["task_id"]),
            public_task_ref=public_task_ref(canonical),
            replicate_commitment=replicate_commitment,
            frozen_state_ref=frozen.freeze_ref,
            baseline_seal_refs=tuple(
                (arm, baselines[arm].seal_ref) for arm in (
                    "IN_FULL_NEUTRAL_12",
                    "IO_FULL_ORDINARY_12",
                )
            ),
            neutral_episode_refs=baselines[
                "IN_FULL_NEUTRAL_12"
            ].neutral_episode_refs,
            donor_catalog_ref=catalog.catalog_ref,
            prompt_plans=tuple((arm, plans[arm]) for arm in ARMS),
            pair_equalities=tuple(pair_equalities),  # type: ignore[arg-type]
            neutral_recall=neutral_recall,
            ordinary_recall=ordinary_recall,
            ordinary_private_replay=ordinary_private_replay,
        )

    def prompt_for(self, arm: Arm) -> PromptPlan:
        arm = validate_arm(arm)
        return dict(self.prompt_plans)[arm]

    @property
    def preparation_ref(self) -> str:
        """Stable across the mandatory post-ledger capture cleanup transition."""

        return canonical_ref(
            "prepared-task-material",
            {
                "baseline_seal_refs": dict(self.baseline_seal_refs),
                "donor_catalog_ref": self.donor_catalog_ref,
                "frozen_before_generation": self.frozen_before_generation,
                "frozen_state_ref": self.frozen_state_ref,
                "neutral_episode_refs": list(self.neutral_episode_refs),
                "neutral_recall_terminal_ref": self.neutral_recall.terminal_ref,
                "ordinary_recall_terminal_ref": self.ordinary_recall.terminal_ref,
                "ordinary_private_replay_ref": (
                    None
                    if self.ordinary_private_replay is None
                    else self.ordinary_private_replay.replay_ref
                ),
                "pair_equalities": [
                    item.to_canonical() for item in self.pair_equalities
                ],
                "prompt_plans": [
                    plan.to_canonical() for _, plan in self.prompt_plans
                ],
                "public_task_ref": self.public_task_ref,
                "replicate_commitment": self.replicate_commitment,
                "task_id": self.task_id,
            },
        )

    @property
    def block_ref(self) -> str:
        return canonical_ref("prepared-task-block", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "frozen_before_generation": self.frozen_before_generation,
            "frozen_state_ref": self.frozen_state_ref,
            "baseline_seal_refs": dict(self.baseline_seal_refs),
            "neutral_episode_refs": list(self.neutral_episode_refs),
            "donor_catalog_ref": self.donor_catalog_ref,
            "neutral_recall": self.neutral_recall.to_canonical(),
            "neutral_recall_ref": self.neutral_recall.capture_ref,
            "ordinary_recall": self.ordinary_recall.to_canonical(),
            "ordinary_recall_ref": self.ordinary_recall.capture_ref,
            "ordinary_private_replay_ref": (
                None
                if self.ordinary_private_replay is None
                else self.ordinary_private_replay.replay_ref
            ),
            "pair_equalities": [
                item.to_canonical() for item in self.pair_equalities
            ],
            "prompt_plans": [plan.to_canonical() for _, plan in self.prompt_plans],
            "public_task_ref": self.public_task_ref,
            "preparation_ref": self.preparation_ref,
            "replicate_commitment": self.replicate_commitment,
            "task_id": self.task_id,
        }


@dataclass(frozen=True, slots=True)
class FrozenAdaptationState:
    purpose: Purpose
    baseline_seals: tuple[BaselineSeal, ...]
    donor_catalogs: tuple[DonorCatalog, ...]

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        expected_replicates = 1 if purpose == "qualification" else 3
        if (
            type(self.baseline_seals) is not tuple
            or len(self.baseline_seals) != 2 * expected_replicates
            or any(type(item) is not BaselineSeal for item in self.baseline_seals)
        ):
            raise V2InvariantError("frozen adaptation baseline inventory differs")
        keys = tuple(
            (item.replicate_commitment, item.arm) for item in self.baseline_seals
        )
        if len(set(keys)) != len(keys):
            raise V2InvariantError("frozen adaptation repeats a lineage")
        identities = tuple(
            _private_root_identity(item.root, "frozen adaptation baseline root")
            for item in self.baseline_seals
        )
        if (
            len({item[0] for item in identities}) != len(identities)
            or len({item[1:] for item in identities}) != len(identities)
        ):
            raise V2InvariantError("frozen adaptation lineages alias mutable roots")
        by_replicate: dict[str, list[BaselineSeal]] = defaultdict(list)
        for item in self.baseline_seals:
            if item.purpose != purpose:
                raise V2InvariantError("baseline seal purpose differs")
            by_replicate[item.replicate_commitment].append(item)
        if len(by_replicate) != expected_replicates:
            raise V2InvariantError("frozen adaptation replicate count differs")
        for rows in by_replicate.values():
            if {row.arm for row in rows} != STATEFUL_ARMS:
                raise V2InvariantError("frozen adaptation lacks IN/IO pair")
            if len({row.neutral_episode_refs for row in rows}) != 1:
                raise V2InvariantError("IN/IO neutral fixture chains differ")
            if len(
                {
                    (
                        row.neutral_chain_ref,
                        row.bootstrap_episode_ref,
                        row.genesis_competence_digest,
                        row.model_ref,
                        row.encoder_ref,
                    )
                    for row in rows
                }
            ) != 1:
                raise V2InvariantError("IN/IO genesis/foundation bindings differ")
        if (
            type(self.donor_catalogs) is not tuple
            or len(self.donor_catalogs) != expected_replicates
            or any(type(item) is not DonorCatalog for item in self.donor_catalogs)
            or {item.replicate_commitment for item in self.donor_catalogs}
            != set(by_replicate)
        ):
            raise V2InvariantError("frozen adaptation donor catalogs differ")

    @property
    def freeze_ref(self) -> str:
        return canonical_ref("frozen-adaptation-state", self.to_canonical())

    def baselines_for(self, replicate_commitment: str) -> dict[str, BaselineSeal]:
        replicate_commitment = _ref(
            replicate_commitment, "frozen-state replicate commitment"
        )
        rows = {
            item.arm: item
            for item in self.baseline_seals
            if item.replicate_commitment == replicate_commitment
        }
        if set(rows) != STATEFUL_ARMS:
            raise V2InvariantError("frozen state lacks the replicate's IN/IO baselines")
        return rows

    def catalog_for(self, replicate_commitment: str) -> DonorCatalog:
        replicate_commitment = _ref(
            replicate_commitment, "frozen catalog replicate commitment"
        )
        rows = tuple(
            item
            for item in self.donor_catalogs
            if item.replicate_commitment == replicate_commitment
        )
        if len(rows) != 1:
            raise V2InvariantError("frozen state lacks one replicate donor catalog")
        return rows[0]

    def to_canonical(self) -> dict[str, object]:
        return {
            "baseline_seal_refs": sorted(
                item.seal_ref for item in self.baseline_seals
            ),
            "donor_catalog_refs": sorted(
                item.catalog_ref for item in self.donor_catalogs
            ),
            "purpose": self.purpose,
        }


V2AcquisitionScopeKind: TypeAlias = Literal[
    "persistent-adaptation",
    "neutral-recall-capture",
    "ordinary-recall-capture",
    "disposable-attempt",
]


@dataclass(frozen=True, slots=True)
class V2AcquisitionScopeSpec:
    """One V2-owned Cognee namespace with no predecessor experiment identity."""

    purpose: Purpose
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    scope_kind: V2AcquisitionScopeKind
    state_root: str
    task_id: str | None = None

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        _ref(self.replicate_commitment, "V2 acquisition replicate commitment")
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("V2 acquisition scope arm differs")
        if self.scope_kind not in (
            "persistent-adaptation",
            "neutral-recall-capture",
            "ordinary-recall-capture",
            "disposable-attempt",
        ):
            raise ValueError("V2 acquisition scope kind differs")
        if (self.scope_kind == "persistent-adaptation") != (self.task_id is None):
            raise V2InvariantError("V2 acquisition task identity differs")
        if self.task_id is not None:
            _ref(self.task_id, "V2 acquisition task id")
        root = Path(self.state_root)
        if (
            not root.is_absolute()
            or str(root) != self.state_root
            or "." in root.parts
            or ".." in root.parts
            or root.name != self.dataset_name
        ):
            raise V2InvariantError("V2 acquisition scope root differs")

    @classmethod
    def create(
        cls,
        *,
        purpose: Purpose,
        replicate_commitment: str,
        arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
        scope_kind: V2AcquisitionScopeKind,
        state_parent: str | Path,
        task_id: str | None = None,
    ) -> "V2AcquisitionScopeSpec":
        purpose = validate_purpose(purpose)
        replicate_commitment = _ref(
            replicate_commitment, "V2 acquisition replicate commitment"
        )
        if arm not in STATEFUL_ARMS:
            raise ValueError("V2 acquisition scope arm differs")
        if scope_kind not in (
            "persistent-adaptation",
            "neutral-recall-capture",
            "ordinary-recall-capture",
            "disposable-attempt",
        ):
            raise ValueError("V2 acquisition scope kind differs")
        if task_id is not None:
            task_id = _ref(task_id, "V2 acquisition task id")
        parent = Path(state_parent)
        if (
            not parent.is_absolute()
            or parent.resolve(strict=False) != parent
            or "." in parent.parts
            or ".." in parent.parts
        ):
            raise ValueError("V2 acquisition scope parent differs")
        identity = canonical_ref(
            "v2-acquisition-scope-name",
            {
                "arm": arm,
                "protocol_identity": PROTOCOL_IDENTITY,
                "purpose": purpose,
                "replicate_commitment": replicate_commitment,
                "scope_kind": scope_kind,
                "task_id": task_id,
            },
        ).removeprefix("sha256:")[:24]
        dataset_name = f"v2-hc-{identity}"
        return cls(
            purpose=purpose,
            replicate_commitment=replicate_commitment,
            arm=arm,
            scope_kind=scope_kind,
            state_root=str(parent / dataset_name),
            task_id=task_id,
        )

    @property
    def dataset_name(self) -> str:
        identity = canonical_ref(
            "v2-acquisition-scope-name",
            {
                "arm": self.arm,
                "protocol_identity": PROTOCOL_IDENTITY,
                "purpose": self.purpose,
                "replicate_commitment": self.replicate_commitment,
                "scope_kind": self.scope_kind,
                "task_id": self.task_id,
            },
        ).removeprefix("sha256:")[:24]
        return f"v2-hc-{identity}"

    @property
    def tenant_name(self) -> str:
        return f"{self.dataset_name}-tenant"

    @property
    def node_set_name(self) -> str:
        return f"{self.dataset_name}-records"

    @property
    def scope_ref(self) -> str:
        return canonical_ref("v2-acquisition-scope", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "dataset_name": self.dataset_name,
            "node_set_name": self.node_set_name,
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": self.purpose,
            "replicate_commitment": self.replicate_commitment,
            "scope_kind": self.scope_kind,
            "state_root": self.state_root,
            "task_id": self.task_id,
            "tenant_name": self.tenant_name,
        }

    def runtime_scope(self) -> object:
        from angler.memory.cognee_worker_protocol import CogneeWorkerScope

        return CogneeWorkerScope(
            dataset_name=self.dataset_name,
            tenant_name=self.tenant_name,
            node_set_name=self.node_set_name,
            state_root=self.state_root,
        )


@dataclass(frozen=True, slots=True)
class RetainedPreparationScopeEvidence:
    """Durable ownership of one terminal worker's preserved failure scope."""

    purpose: Purpose
    task_id: str
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    allocation_ref: str
    scope_ref: str
    state_root: str
    dataset_id: str | None
    root_device: int
    root_inode: int
    lineage_root: str
    lineage_root_device: int
    lineage_root_inode: int
    lineage_hashes: tuple[tuple[str, str], ...]
    lineage_tree: _RetainedScopeTreeSnapshot
    scope_tree: _RetainedScopeTreeSnapshot
    stage_ref: str | None
    worker_terminal: bool
    reason_code: str

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        for value, label in (
            (self.task_id, "retained preparation task id"),
            (
                self.replicate_commitment,
                "retained preparation replicate commitment",
            ),
            (self.allocation_ref, "retained preparation allocation ref"),
            (self.scope_ref, "retained preparation scope ref"),
        ):
            _ref(value, label)
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("retained preparation arm differs")
        if self.dataset_id is not None:
            _text(self.dataset_id, "retained preparation dataset id", 512)
        if self.lineage_hashes != _retained_lineage_hash_pairs(
            dict(self.lineage_hashes), "retained preparation lineage hashes"
        ):
            raise V2InvariantError("retained preparation lineage hashes differ")
        if (
            type(self.lineage_tree) is not _RetainedScopeTreeSnapshot
            or type(self.scope_tree) is not _RetainedScopeTreeSnapshot
        ):
            raise TypeError("retained preparation tree commitment differs")
        if self.worker_terminal is not True:
            raise V2IntegrityStop("retained preparation worker is not terminal")
        if self.stage_ref is not None:
            _ref(self.stage_ref, "retained persistent stage ref")
        if self.reason_code not in (
            "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED",
            "V2_PERSISTENT_ATTEMPT_POST_STAGE_FAILED",
        ) or (self.stage_ref is None) != (
            self.reason_code == "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED"
        ):
            raise V2InvariantError("retained preparation reason differs")
        identity = _private_root_identity(
            self.state_root, "retained preparation scope root"
        )
        lineage_identity = _private_root_identity(
            self.lineage_root, "retained preparation lineage root"
        )
        if (
            identity != (self.state_root, self.root_device, self.root_inode)
            or stat.S_IMODE(os.lstat(self.state_root).st_mode) != 0o700
            or lineage_identity
            != (
                self.lineage_root,
                self.lineage_root_device,
                self.lineage_root_inode,
            )
            or stat.S_IMODE(os.lstat(self.lineage_root).st_mode) != 0o700
        ):
            raise V2IntegrityStop("retained preparation scope identity differs")

    @property
    def evidence_ref(self) -> str:
        return canonical_ref("retained-preparation-scope", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "allocation_ref": self.allocation_ref,
            "arm": self.arm,
            "dataset_id": self.dataset_id,
            "lineage_hashes": dict(self.lineage_hashes),
            "lineage_root": self.lineage_root,
            "lineage_root_device": self.lineage_root_device,
            "lineage_root_inode": self.lineage_root_inode,
            "lineage_tree": self.lineage_tree.to_canonical(),
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": self.purpose,
            "reason_code": self.reason_code,
            "replicate_commitment": self.replicate_commitment,
            "retention_disposition": "PRESERVED_FAILURE_EVIDENCE",
            "root_device": self.root_device,
            "root_inode": self.root_inode,
            "schema": RETAINED_PREPARATION_SCOPE_SCHEMA,
            "scope_ref": self.scope_ref,
            "scope_tree": self.scope_tree.to_canonical(),
            "stage_ref": self.stage_ref,
            "state_root": self.state_root,
            "task_id": self.task_id,
            "worker_terminal": self.worker_terminal,
        }


_V2_COGNEE_EXPECTED_PROCESS_NODES = 4
_V2_COGNEE_CAPTURE_PROCESS_NODES = MAXIMUM_PROCESSES
_V2_COGNEE_GRACEFUL_CLOSE_SECONDS = 3.0
_V2_COGNEE_TERM_SECONDS = 1.5
_V2_COGNEE_KILL_SECONDS = 5.0
_V2_PROC_CMDLINE_BYTES = 131_072
_V2_CAPABILITY_STATUS_FIELDS = (
    "CapInh",
    "CapPrm",
    "CapEff",
    "CapBnd",
    "CapAmb",
)
_V2_ZERO_CAPABILITY_SET = "0000000000000000"


def _validate_v2_inherited_parent_attestation(
    value: Mapping[str, object],
    *,
    expected_network_namespace: str | None = None,
) -> dict[str, object]:
    receipt = dict(value)
    expected_keys = {
        "capabilities",
        "gids",
        "groups",
        "interfaces",
        "ipv4_route_count",
        "ipv6_route_count",
        "loopback_operstate",
        "network_namespace",
        "no_new_privileges",
        "uids",
    }
    capabilities = receipt.get("capabilities")
    namespace = receipt.get("network_namespace")
    if (
        set(receipt) != expected_keys
        or type(capabilities) is not dict
        or capabilities
        != {
            name: _V2_ZERO_CAPABILITY_SET
            for name in _V2_CAPABILITY_STATUS_FIELDS
        }
        or receipt.get("uids") != [1000, 1000, 1000, 1000]
        or receipt.get("gids") != [1000, 1000, 1000, 1000]
        or receipt.get("groups") != []
        or receipt.get("no_new_privileges") is not True
        or receipt.get("interfaces") != [[1, "lo"]]
        or receipt.get("ipv4_route_count") != 0
        or type(receipt.get("ipv6_route_count")) is not int
        or receipt["ipv6_route_count"] < 1
        or receipt.get("loopback_operstate") != "unknown"
        or type(namespace) is not str
        or re.fullmatch(r"net:\[[1-9][0-9]*\]", namespace) is None
        or (
            expected_network_namespace is not None
            and namespace != expected_network_namespace
        )
    ):
        raise V2IntegrityStop("V2 inherited Cognee parent attestation differs")
    return json.loads(canonical_json_bytes(receipt))


def _attest_v2_inherited_worker_parent(
    expected_network_namespace: str | None = None,
    *,
    attestor: Callable[..., Mapping[str, object]] | None = None,
    **attestor_kwargs: object,
) -> dict[str, object]:
    if attestor is None:
        from angler.memory.cognee_worker_protocol import (
            attest_inherited_worker_parent_boundary,
        )

        attestor = attest_inherited_worker_parent_boundary
    if not callable(attestor):
        raise TypeError("V2 inherited Cognee parent attestor differs")
    try:
        value = attestor(expected_network_namespace, **attestor_kwargs)
        return _validate_v2_inherited_parent_attestation(
            value,
            expected_network_namespace=expected_network_namespace,
        )
    except V2IntegrityStop:
        raise
    except BaseException as error:
        raise V2IntegrityStop(
            "V2 inherited Cognee parent attestation failed"
        ) from error


@dataclass(frozen=True, slots=True)
class _V2UnresolvedCogneeBinding:
    binding: object = field(repr=False)
    process: object = field(repr=False)
    pipe_identities: tuple[tuple[int, int], ...] | None = field(repr=False)


_UNRESOLVED_V2_COGNEE_HANDLES: dict[int, object] = {}
_UNRESOLVED_V2_COGNEE_BINDINGS: dict[int, _V2UnresolvedCogneeBinding] = {}
_UNRESOLVED_V2_COGNEE_STARTS: dict[str, object] = {}


@dataclass(frozen=True, slots=True)
class _V2WorkerProcessIdentity:
    """Immutable procfs identity plus non-reusable signal/wait authority."""

    pid: int
    ppid: int
    starttime: int
    executable: str | None
    uids: tuple[int, int, int, int]
    argv: tuple[str, ...]
    depth: int
    pidfd: int = field(repr=False, compare=False)
    gids: tuple[int, ...] = ()
    groups: tuple[int, ...] = ()
    no_new_privileges: bool = False
    capabilities: tuple[tuple[str, str], ...] = ()
    network_namespace: str = ""

    @property
    def identity(self) -> tuple[object, ...]:
        return (
            self.pid,
            self.ppid,
            self.starttime,
            self.executable,
            self.uids,
            self.gids,
            self.groups,
            self.no_new_privileges,
            self.capabilities,
            self.network_namespace,
            self.argv,
            self.depth,
        )


@dataclass(frozen=True, slots=True)
class _V2WorkerGraphExpectation:
    """Exact allowed exec-collapse chain for one worker subprocess."""

    root_argv: tuple[str, ...]
    worker_argv: tuple[str, ...]
    allowed_intermediate_argv: tuple[tuple[str, ...], ...]
    root_executable: str
    worker_executable: str
    root_uids: tuple[int, int, int, int]
    worker_uids: tuple[int, int, int, int]
    maximum_nodes: int = _V2_COGNEE_EXPECTED_PROCESS_NODES

    def __post_init__(self) -> None:
        if (
            type(self.root_argv) is not tuple
            or not self.root_argv
            or type(self.worker_argv) is not tuple
            or not self.worker_argv
            or type(self.allowed_intermediate_argv) is not tuple
            or any(
                type(item) is not tuple
                or not item
                or any(type(part) is not str or not part for part in item)
                for item in (
                    self.root_argv,
                    self.worker_argv,
                    *self.allowed_intermediate_argv,
                )
            )
            or type(self.root_executable) is not str
            or not Path(self.root_executable).is_absolute()
            or type(self.worker_executable) is not str
            or not Path(self.worker_executable).is_absolute()
            or type(self.root_uids) is not tuple
            or len(self.root_uids) != 4
            or type(self.worker_uids) is not tuple
            or len(self.worker_uids) != 4
            or any(
                type(item) is not int or item < 0
                for item in (*self.root_uids, *self.worker_uids)
            )
            or type(self.maximum_nodes) is not int
            or not 1 <= self.maximum_nodes <= _V2_COGNEE_CAPTURE_PROCESS_NODES
        ):
            raise V2InvariantError("V2 worker graph expectation differs")


def _resolved_executable(path: str, label: str) -> str:
    if type(path) is not str or not Path(path).is_absolute():
        raise V2IntegrityStop(f"{label} executable differs")
    try:
        return str(Path(path).resolve(strict=True))
    except OSError as error:
        raise V2IntegrityStop(f"{label} executable is unavailable") from error


def _read_v2_process_identity(
    pid: int,
    *,
    depth: int,
    pidfd: int,
) -> _V2WorkerProcessIdentity:
    pid = _integer(pid, "V2 worker pid", minimum=1)
    depth = _integer(depth, "V2 worker depth", minimum=0)
    if type(pidfd) is not int:
        raise TypeError("V2 worker pidfd differs")
    root = Path("/proc") / str(pid)
    try:
        raw_command = (root / "cmdline").read_bytes()
        raw_stat = (root / "stat").read_text(encoding="ascii")
        raw_status = (root / "status").read_text(encoding="ascii")
    except (OSError, UnicodeError) as error:
        raise V2IntegrityStop("V2 worker process receipt is unavailable") from error
    try:
        executable: str | None = os.readlink(root / "exe")
    except PermissionError:
        # Linux intentionally denies /proc/<setuid-sudo>/exe to the invoking
        # user.  The frozen root argv, uid tuple, ancestry, starttime and pidfd
        # remain exact; the unprivileged Python worker leaf must expose exe.
        executable = None
    except OSError as error:
        raise V2IntegrityStop("V2 worker executable receipt is unavailable") from error
    try:
        network_namespace = os.readlink(root / "ns/net")
    except OSError as error:
        raise V2IntegrityStop(
            "V2 worker network namespace receipt is unavailable"
        ) from error
    if (
        not raw_command
        or len(raw_command) > _V2_PROC_CMDLINE_BYTES
        or not raw_command.endswith(b"\x00")
    ):
        raise V2IntegrityStop("V2 worker command line differs")
    try:
        argv = tuple(
            item.decode("utf-8", errors="strict")
            for item in raw_command[:-1].split(b"\x00")
        )
    except UnicodeError as error:
        raise V2IntegrityStop("V2 worker command line encoding differs") from error
    if not argv or any(type(item) is not str or not item for item in argv):
        raise V2IntegrityStop("V2 worker command line fields differ")
    suffix = raw_stat.rsplit(") ", 1)
    if len(suffix) != 2:
        raise V2IntegrityStop("V2 worker process stat differs")
    fields = suffix[1].split()
    if len(fields) < 20:
        raise V2IntegrityStop("V2 worker process stat is truncated")
    try:
        ppid = int(fields[1])
        starttime = int(fields[19])
    except ValueError as error:
        raise V2IntegrityStop("V2 worker process stat fields differ") from error
    if ppid < 0 or starttime <= 0:
        raise V2IntegrityStop("V2 worker process identity differs")
    status_fields: dict[str, str] = {}
    for line in raw_status.splitlines():
        if ":" not in line:
            continue
        name, raw_value = line.split(":", 1)
        if name in status_fields:
            raise V2IntegrityStop("V2 worker status repeats a field")
        status_fields[name] = raw_value.strip()
    try:
        uids = tuple(int(item) for item in status_fields["Uid"].split())
        gids = tuple(int(item) for item in status_fields["Gid"].split())
        groups = tuple(int(item) for item in status_fields["Groups"].split())
    except ValueError as error:
        raise V2IntegrityStop("V2 worker privilege fields differ") from error
    except KeyError as error:
        raise V2IntegrityStop("V2 worker privilege receipt differs") from error
    capabilities = tuple(
        (name, status_fields.get(name, ""))
        for name in _V2_CAPABILITY_STATUS_FIELDS
    )
    if (
        len(uids) != 4
        or len(gids) != 4
        or any(item < 0 for item in (*uids, *gids, *groups))
        or status_fields.get("NoNewPrivs") not in ("0", "1")
        or any(
            re.fullmatch(r"[0-9a-f]{16}", value) is None
            for _name, value in capabilities
        )
        or re.fullmatch(r"net:\[[1-9][0-9]*\]", network_namespace) is None
    ):
        raise V2IntegrityStop("V2 worker privilege identity differs")
    return _V2WorkerProcessIdentity(
        pid=pid,
        ppid=ppid,
        starttime=starttime,
        executable=(
            None
            if executable is None
            else str(Path(executable).resolve(strict=False))
        ),
        uids=uids,
        argv=argv,
        depth=depth,
        pidfd=pidfd,
        gids=gids,
        groups=groups,
        no_new_privileges=status_fields["NoNewPrivs"] == "1",
        capabilities=capabilities,
        network_namespace=network_namespace,
    )


def _v2_proc_parent_map() -> dict[int, int]:
    parents: dict[int, int] = {}
    try:
        entries = tuple(os.scandir("/proc"))
    except OSError as error:
        raise V2IntegrityStop("V2 worker process inventory is unavailable") from error
    for entry in entries:
        if not entry.name.isdecimal():
            continue
        pid = int(entry.name)
        try:
            raw_stat = Path(entry.path, "stat").read_text(encoding="ascii")
            suffix = raw_stat.rsplit(") ", 1)
            if len(suffix) != 2:
                continue
            fields = suffix[1].split()
            if len(fields) < 2:
                continue
            parents[pid] = int(fields[1])
        except (OSError, UnicodeError, ValueError):
            continue
    return parents


def _v2_descendant_depths(root_pid: int) -> dict[int, int]:
    root_pid = _integer(root_pid, "V2 worker root pid", minimum=1)
    parents = _v2_proc_parent_map()
    if root_pid not in parents:
        raise V2IntegrityStop("V2 worker root process is absent")
    children: dict[int, list[int]] = defaultdict(list)
    for pid, ppid in parents.items():
        children[ppid].append(pid)
    depths = {root_pid: 0}
    frontier = [root_pid]
    while frontier:
        parent = frontier.pop(0)
        for child in sorted(children.get(parent, ())):
            if child in depths:
                raise V2IntegrityStop("V2 worker process ancestry cycles")
            depths[child] = depths[parent] + 1
            frontier.append(child)
            if len(depths) > _V2_COGNEE_CAPTURE_PROCESS_NODES:
                raise V2IntegrityStop("V2 worker process inventory exceeds ceiling")
    return depths


def _close_v2_pidfds(processes: Sequence[_V2WorkerProcessIdentity]) -> None:
    for item in processes:
        try:
            os.close(item.pidfd)
        except OSError:
            pass


def _validate_v2_rooted_process_ancestry(
    root_pid: int,
    processes: Sequence[_V2WorkerProcessIdentity],
) -> None:
    """Prove the pidfd-bound rows still form our direct-child process tree."""

    rows = tuple(processes)
    by_pid = {item.pid: item for item in rows}
    root = by_pid.get(root_pid)
    if (
        not rows
        or len(by_pid) != len(rows)
        or root is None
        or root.depth != 0
        or root.ppid != os.getpid()
        or any(item.depth < 0 for item in rows)
    ):
        raise V2IntegrityStop("V2 worker captured ancestry is not rooted")
    for item in rows:
        if item is root:
            continue
        parent = by_pid.get(item.ppid)
        if parent is None or item.depth != parent.depth + 1:
            raise V2IntegrityStop("V2 worker captured ancestry changed")


def _capture_v2_process_graph(root_pid: int) -> tuple[_V2WorkerProcessIdentity, ...]:
    if not hasattr(os, "pidfd_open") or not hasattr(signal, "pidfd_send_signal"):
        raise V2IntegrityStop("V2 worker pidfd support is unavailable")
    depths = _v2_descendant_depths(root_pid)
    captured: list[_V2WorkerProcessIdentity] = []
    try:
        for pid, depth in sorted(depths.items(), key=lambda item: (item[1], item[0])):
            pidfd = os.pidfd_open(pid, 0)
            try:
                first = _read_v2_process_identity(pid, depth=depth, pidfd=pidfd)
                second = _read_v2_process_identity(pid, depth=depth, pidfd=pidfd)
                if (
                    first.identity != second.identity
                    or _v2_pidfd_terminal(pidfd)
                ):
                    raise V2IntegrityStop("V2 worker process changed during capture")
            except BaseException:
                os.close(pidfd)
                raise
            captured.append(second)
        _validate_v2_rooted_process_ancestry(root_pid, captured)
    except BaseException:
        _close_v2_pidfds(captured)
        raise
    return tuple(captured)


def _v2_process_matches_owned_role(
    process: _V2WorkerProcessIdentity,
    expectation: _V2WorkerGraphExpectation,
) -> bool:
    if (
        process.argv == expectation.worker_argv
        and process.executable == expectation.worker_executable
        and process.uids == expectation.worker_uids
    ):
        return True
    if process.argv not in expectation.allowed_intermediate_argv:
        return False
    if process.uids not in (
        expectation.root_uids,
        expectation.worker_uids,
        (0, 0, 0, 0),
    ):
        return False
    expected_executable = _resolved_executable(
        process.argv[0], "V2 worker holder role"
    )
    return process.executable in (None, expected_executable)


def _capture_v2_terminal_authority(
    root_pid: int,
    pipe_identities: tuple[tuple[int, int], ...],
    expectation: _V2WorkerGraphExpectation,
) -> tuple[
    tuple[_V2WorkerProcessIdentity, ...],
    tuple[_V2WorkerProcessIdentity, ...],
    tuple[tuple[int, int, tuple[tuple[int, int], ...]], ...],
    bool,
]:
    """Capture the exact tree, or at least every discoverable pipe holder.

    The second value is false when the semantic graph could not be captured.
    That false capability is cleanup-only: it can never authorize use, but it
    prevents a post-create validation failure from losing terminal authority.
    """

    try:
        captured_graph = _capture_v2_process_graph(root_pid)
    except BaseException:
        captured_graph = ()
    holder_inventory = _v2_pipe_holder_inventory(pipe_identities)
    captured: list[_V2WorkerProcessIdentity] = list(captured_graph)
    untrusted: list[_V2WorkerProcessIdentity] = []
    by_key = {(item.pid, item.starttime): item for item in captured_graph}
    bindings: list[tuple[int, int, tuple[tuple[int, int], ...]]] = []
    semantic_graph_captured = bool(captured_graph)
    maximum_depth = max((item.depth for item in captured_graph), default=0)
    try:
        for pid, expected_held in holder_inventory.items():
            candidates = tuple(item for item in captured if item.pid == pid)
            existing = max(candidates, key=lambda item: item.starttime) if candidates else None
            stable = _capture_v2_stable_pipe_holder(
                pid,
                depth=(existing.depth if existing is not None else maximum_depth + 1),
                expected_held=expected_held,
                pipe_identities=pipe_identities,
            )
            if stable is None:
                semantic_graph_captured = False
                continue
            observed, held = stable
            retained = by_key.get((observed.pid, observed.starttime))
            if retained is not None:
                os.close(observed.pidfd)
                bound = retained
                if retained.identity != observed.identity:
                    semantic_graph_captured = False
            elif _v2_process_matches_owned_role(observed, expectation):
                captured.append(observed)
                by_key[(observed.pid, observed.starttime)] = observed
                bound = observed
                semantic_graph_captured = False
            else:
                untrusted.append(observed)
                bound = observed
                semantic_graph_captured = False
            bindings.append((pid, bound.starttime, held))
        if not any(item.pid == root_pid for item in captured):
            try:
                pidfd = os.pidfd_open(root_pid, 0)
            except ProcessLookupError:
                pidfd = -1
            if pidfd >= 0:
                try:
                    first = _read_v2_process_identity(
                        root_pid, depth=0, pidfd=pidfd
                    )
                    second = _read_v2_process_identity(
                        root_pid, depth=0, pidfd=pidfd
                    )
                    if first.identity != second.identity:
                        raise V2IntegrityStop(
                            "V2 worker root changed during fallback capture"
                        )
                    if _v2_pidfd_terminal(pidfd):
                        raise V2IntegrityStop(
                            "V2 worker root exited during fallback capture"
                        )
                except BaseException:
                    os.close(pidfd)
                    raise
                if (
                    second.ppid == os.getpid()
                    and _v2_process_matches_owned_role(second, expectation)
                ):
                    captured.append(second)
                    by_key[(second.pid, second.starttime)] = second
                else:
                    # Numeric root-PID reuse is evidence of uncertainty, never
                    # authority to signal the newly observed process.
                    untrusted.append(second)
                semantic_graph_captured = False
        if len(captured) + len(untrusted) > _V2_COGNEE_CAPTURE_PROCESS_NODES:
            raise V2IntegrityStop("V2 worker terminal authority exceeds ceiling")
    except BaseException:
        _close_v2_pidfds((*captured, *untrusted))
        raise
    if not captured and not untrusted:
        raise V2IntegrityStop("V2 worker terminal authority is unavailable")
    graph_keys = {(item.pid, item.starttime) for item in captured_graph}
    if any((pid, starttime) not in graph_keys for pid, starttime, _ in bindings):
        semantic_graph_captured = False
    if untrusted:
        semantic_graph_captured = False
    return (
        tuple(captured),
        tuple(untrusted),
        tuple(sorted(bindings)),
        semantic_graph_captured,
    )


def _v2_asyncio_pipe_identities(
    process: asyncio.subprocess.Process,
) -> tuple[tuple[int, int], ...]:
    process_transport = getattr(process, "_transport", None)
    identities: list[tuple[int, int]] = []
    for descriptor in (0, 1, 2):
        try:
            pipe_transport = process_transport.get_pipe_transport(descriptor)
            pipe = pipe_transport.get_extra_info("pipe")
            metadata = os.fstat(pipe.fileno())
        except (AttributeError, OSError, TypeError, ValueError) as error:
            raise V2IntegrityStop("V2 worker parent pipe identity differs") from error
        if not stat.S_ISFIFO(metadata.st_mode):
            raise V2IntegrityStop("V2 worker stdio is not an exact pipe")
        identities.append((int(metadata.st_dev), int(metadata.st_ino)))
    if len(set(identities)) != 3:
        raise V2IntegrityStop("V2 worker stdio pipe identities alias")
    return tuple(identities)


def _v2_worker_pipe_identities(pid: int) -> tuple[tuple[int, int], ...]:
    identities: list[tuple[int, int]] = []
    for descriptor in (0, 1, 2):
        try:
            metadata = os.stat(Path("/proc") / str(pid) / "fd" / str(descriptor))
        except OSError as error:
            raise V2IntegrityStop("V2 worker child pipe identity differs") from error
        if not stat.S_ISFIFO(metadata.st_mode):
            raise V2IntegrityStop("V2 worker child stdio is not an exact pipe")
        identities.append((int(metadata.st_dev), int(metadata.st_ino)))
    return tuple(identities)


def _validate_v2_process_graph(
    processes: Sequence[_V2WorkerProcessIdentity],
    expectation: _V2WorkerGraphExpectation,
    pipe_identities: tuple[tuple[int, int], ...],
) -> None:
    if (
        type(processes) not in (tuple, list)
        or not processes
        or len(processes) > expectation.maximum_nodes
        or type(pipe_identities) is not tuple
        or len(pipe_identities) != 3
    ):
        raise V2IntegrityStop("V2 worker process graph size differs")
    rows = tuple(processes)
    if any(type(item) is not _V2WorkerProcessIdentity for item in rows):
        raise V2IntegrityStop("V2 worker process graph rows differ")
    by_pid = {item.pid: item for item in rows}
    if len(by_pid) != len(rows):
        raise V2IntegrityStop("V2 worker process graph repeats a pid")
    roots = tuple(item for item in rows if item.depth == 0)
    if (
        len(roots) != 1
        or roots[0].ppid != os.getpid()
        or roots[0].argv != expectation.root_argv
        or roots[0].executable not in (None, expectation.root_executable)
        or roots[0].uids != expectation.root_uids
    ):
        raise V2IntegrityStop("V2 worker root launch identity differs")
    children: dict[int, list[_V2WorkerProcessIdentity]] = defaultdict(list)
    for item in rows:
        if item.depth > 0:
            parent = by_pid.get(item.ppid)
            if parent is None or item.depth != parent.depth + 1:
                raise V2IntegrityStop("V2 worker process ancestry differs")
            children[item.ppid].append(item)
    leaves = tuple(item for item in rows if not children.get(item.pid))
    workers = tuple(
        item
        for item in rows
        if item.argv == expectation.worker_argv
        and item.executable == expectation.worker_executable
    )
    if len(leaves) != 1 or len(workers) != 1 or leaves[0] is not workers[0]:
        raise V2IntegrityStop("V2 worker leaf identity differs")
    if workers[0].uids != expectation.worker_uids:
        raise V2IntegrityStop("V2 worker leaf uid identity differs")
    for item in rows:
        if item is workers[0]:
            continue
        if (
            item.argv not in expectation.allowed_intermediate_argv
            or item.uids
            not in (
                expectation.root_uids,
                expectation.worker_uids,
                (0, 0, 0, 0),
            )
            or (
                item.executable is not None
                and item.executable
                != _resolved_executable(item.argv[0], "V2 worker intermediate")
            )
            or len(children.get(item.pid, ())) != 1
        ):
            raise V2IntegrityStop("V2 worker intermediate identity differs")
    if _v2_worker_pipe_identities(workers[0].pid) != pipe_identities:
        raise V2IntegrityStop("V2 worker stdio capability differs")


def _validate_v2_inherited_worker_process_graph(
    processes: Sequence[_V2WorkerProcessIdentity],
    parent_attestation: Mapping[str, object],
) -> None:
    receipt = _validate_v2_inherited_parent_attestation(parent_attestation)
    rows = tuple(processes)
    expected_capabilities = tuple(
        (name, _V2_ZERO_CAPABILITY_SET)
        for name in _V2_CAPABILITY_STATUS_FIELDS
    )
    if (
        len(rows) != 1
        or rows[0].depth != 0
        or rows[0].ppid != os.getpid()
        or rows[0].uids != tuple(receipt["uids"])
        or rows[0].gids != tuple(receipt["gids"])
        or rows[0].groups != tuple(receipt["groups"])
        or rows[0].no_new_privileges is not True
        or rows[0].capabilities != expected_capabilities
        or rows[0].network_namespace != receipt["network_namespace"]
    ):
        raise V2IntegrityStop("V2 inherited Cognee direct child differs")


def _merge_v2_process_graph(
    retained: Sequence[_V2WorkerProcessIdentity],
    observed: Sequence[_V2WorkerProcessIdentity],
) -> tuple[_V2WorkerProcessIdentity, ...]:
    merged = list(retained)
    retained_by_identity = {
        (item.pid, item.starttime): item for item in retained
    }
    retained_by_pid = {item.pid: item for item in retained}
    for item in observed:
        existing = retained_by_identity.get((item.pid, item.starttime))
        if existing is not None:
            if existing.identity != item.identity:
                _close_v2_pidfds((item,))
                raise V2IntegrityStop("V2 worker retained identity changed")
            _close_v2_pidfds((item,))
            continue
        if item.pid in retained_by_pid:
            merged.append(item)
            raise V2IntegrityStop("V2 worker pid was reused before close")
        merged.append(item)
    return tuple(merged)


def _capture_v2_pipe_holder_authority(
    pipe_identities: tuple[tuple[int, int], ...],
    retained: Sequence[_V2WorkerProcessIdentity],
    retained_untrusted: Sequence[_V2WorkerProcessIdentity],
    expectation: _V2WorkerGraphExpectation,
) -> tuple[
    tuple[_V2WorkerProcessIdentity, ...],
    tuple[_V2WorkerProcessIdentity, ...],
    tuple[tuple[int, int, tuple[tuple[int, int], ...]], ...],
    bool,
]:
    inventory = _v2_pipe_holder_inventory(pipe_identities)
    retained_by_key = {(item.pid, item.starttime): item for item in retained}
    untrusted_by_key = {
        (item.pid, item.starttime): item for item in retained_untrusted
    }
    merged = list(retained)
    merged_untrusted = list(retained_untrusted)
    drift = False
    opened: list[_V2WorkerProcessIdentity] = []
    bindings: list[tuple[int, int, tuple[tuple[int, int], ...]]] = []
    maximum_depth = max((item.depth for item in retained), default=0)
    try:
        for pid, expected_held in inventory.items():
            candidates = tuple(
                item
                for item in (*retained, *retained_untrusted)
                if item.pid == pid
            )
            existing = max(candidates, key=lambda item: item.starttime) if candidates else None
            stable = _capture_v2_stable_pipe_holder(
                pid,
                depth=(existing.depth if existing is not None else maximum_depth + 1),
                expected_held=expected_held,
                pipe_identities=pipe_identities,
            )
            if stable is None:
                drift = True
                continue
            observed, held = stable
            key = (observed.pid, observed.starttime)
            retained_owned = retained_by_key.get(key)
            retained_unknown = untrusted_by_key.get(key)
            if retained_owned is not None:
                os.close(observed.pidfd)
                bindings.append((pid, retained_owned.starttime, held))
                if retained_owned.identity != observed.identity:
                    drift = True
                continue
            if retained_unknown is not None:
                os.close(observed.pidfd)
                bindings.append((pid, retained_unknown.starttime, held))
                drift = True
                continue
            opened.append(observed)
            if _v2_process_matches_owned_role(observed, expectation):
                merged.append(observed)
            else:
                merged_untrusted.append(observed)
            bindings.append((pid, observed.starttime, held))
            drift = True
        if (
            len(merged) + len(merged_untrusted)
            > _V2_COGNEE_CAPTURE_PROCESS_NODES
        ):
            raise V2IntegrityStop("V2 worker pipe-holder count exceeds ceiling")
    except BaseException:
        _close_v2_pidfds(opened)
        raise
    return (
        tuple(merged),
        tuple(merged_untrusted),
        tuple(sorted(bindings)),
        drift,
    )


def _validate_v2_pipe_holder_bindings(
    processes: Sequence[_V2WorkerProcessIdentity],
    bindings: tuple[tuple[int, int, tuple[tuple[int, int], ...]], ...],
    pipe_identities: tuple[tuple[int, int], ...],
) -> None:
    expected_pipes = set(pipe_identities)
    process_keys = {(item.pid, item.starttime) for item in processes}
    seen: set[tuple[int, int]] = set()
    if type(bindings) is not tuple:
        raise V2IntegrityStop("V2 worker pipe-holder bindings differ")
    for binding in bindings:
        if (
            type(binding) is not tuple
            or len(binding) != 3
            or type(binding[0]) is not int
            or type(binding[1]) is not int
            or type(binding[2]) is not tuple
            or not binding[2]
            or any(item not in expected_pipes for item in binding[2])
            or tuple(sorted(set(binding[2]))) != binding[2]
        ):
            raise V2IntegrityStop("V2 worker pipe-holder binding fields differ")
        key = (binding[0], binding[1])
        if key in seen or key not in process_keys:
            raise V2IntegrityStop("V2 worker pipe-holder identity differs")
        seen.add(key)


def _v2_pidfd_terminal(pidfd: int) -> bool:
    selector = selectors.DefaultSelector()
    try:
        selector.register(pidfd, selectors.EVENT_READ)
        return bool(selector.select(timeout=0))
    except (OSError, ValueError) as error:
        raise V2IntegrityStop("V2 worker pidfd readiness differs") from error
    finally:
        selector.close()


async def _wait_v2_pidfds(
    processes: Sequence[_V2WorkerProcessIdentity],
    timeout_seconds: float,
) -> tuple[_V2WorkerProcessIdentity, ...]:
    deadline = time.monotonic() + timeout_seconds
    while True:
        live = tuple(item for item in processes if not _v2_pidfd_terminal(item.pidfd))
        if not live or time.monotonic() >= deadline:
            return live
        await asyncio.sleep(min(0.02, max(0.0, deadline - time.monotonic())))


async def _wait_v2_pidfds_fail_closed(
    processes: Sequence[_V2WorkerProcessIdentity],
    timeout_seconds: float,
    code: str,
) -> tuple[tuple[_V2WorkerProcessIdentity, ...], V2IntegrityStop | None]:
    try:
        return await _wait_v2_pidfds(processes, timeout_seconds), None
    except BaseException as error:
        return tuple(processes), _redacted_failure(error, code)


async def _wait_v2_asyncio_process_exit(
    process: asyncio.subprocess.Process,
    timeout_seconds: float,
) -> bool:
    deadline = time.monotonic() + timeout_seconds
    while process.returncode is None and time.monotonic() < deadline:
        await asyncio.sleep(min(0.02, max(0.0, deadline - time.monotonic())))
    return process.returncode is not None


def _signal_v2_processes_leaf_first(
    processes: Sequence[_V2WorkerProcessIdentity],
    signal_number: int,
) -> list[V2IntegrityStop]:
    failures: list[V2IntegrityStop] = []
    for item in sorted(processes, key=lambda row: (row.depth, row.pid), reverse=True):
        try:
            if _v2_pidfd_terminal(item.pidfd):
                continue
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_PIDFD_READINESS_FAILED")
            )
            continue
        try:
            signal.pidfd_send_signal(item.pidfd, signal_number, None, 0)
        except ProcessLookupError:
            pass
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_PIDFD_SIGNAL_FAILED")
            )
    return failures


def _v2_process_pipe_holdings(
    pid: int,
    pipe_identities: tuple[tuple[int, int], ...],
) -> tuple[tuple[int, int], ...]:
    expected = set(pipe_identities)
    held: set[tuple[int, int]] = set()
    fd_root = Path("/proc") / str(pid) / "fd"
    try:
        descriptors = tuple(os.scandir(fd_root))
    except (FileNotFoundError, PermissionError, ProcessLookupError):
        return ()
    except OSError:
        return ()
    for descriptor in descriptors:
        if not descriptor.name.isdecimal():
            continue
        try:
            metadata = os.stat(descriptor.path)
        except (FileNotFoundError, PermissionError, ProcessLookupError):
            continue
        except OSError:
            continue
        identity = (int(metadata.st_dev), int(metadata.st_ino))
        if identity in expected:
            held.add(identity)
    return tuple(sorted(held))


def _capture_v2_stable_pipe_holder(
    pid: int,
    *,
    depth: int,
    expected_held: tuple[tuple[int, int], ...],
    pipe_identities: tuple[tuple[int, int], ...],
) -> tuple[_V2WorkerProcessIdentity, tuple[tuple[int, int], ...]] | None:
    try:
        pidfd = os.pidfd_open(pid, 0)
    except ProcessLookupError:
        return None
    try:
        first = _read_v2_process_identity(pid, depth=depth, pidfd=pidfd)
        second = _read_v2_process_identity(pid, depth=depth, pidfd=pidfd)
        held = _v2_process_pipe_holdings(pid, pipe_identities)
        third = _read_v2_process_identity(pid, depth=depth, pidfd=pidfd)
        if (
            first.identity != second.identity
            or second.identity != third.identity
            or not held
            or not set(held).issubset(expected_held)
            or _v2_pidfd_terminal(pidfd)
        ):
            os.close(pidfd)
            return None
    except BaseException:
        os.close(pidfd)
        return None
    return third, held


def _v2_pipe_holder_inventory(
    pipe_identities: tuple[tuple[int, int], ...],
) -> dict[int, tuple[tuple[int, int], ...]]:
    holders: dict[int, tuple[tuple[int, int], ...]] = {}
    current_pid = os.getpid()
    try:
        entries = tuple(os.scandir("/proc"))
    except OSError as error:
        raise V2IntegrityStop("V2 worker pipe-holder inventory is unavailable") from error
    for entry in entries:
        if not entry.name.isdecimal():
            continue
        pid = int(entry.name)
        if pid == current_pid:
            continue
        held = _v2_process_pipe_holdings(pid, pipe_identities)
        if held:
            holders[pid] = held
    return dict(sorted(holders.items()))


def _v2_pipe_holders(
    pipe_identities: tuple[tuple[int, int], ...],
) -> tuple[int, ...]:
    return tuple(_v2_pipe_holder_inventory(pipe_identities))


def _v2_cognee_graph_expectation(
    scope_spec: V2AcquisitionScopeSpec,
    inherited_network_namespace: str,
) -> _V2WorkerGraphExpectation:
    from angler.memory import cognee_subprocess_bindings as bindings_module
    from angler.memory.cognee_worker_protocol import (
        COGNEE_PYTHON,
        worker_scope_launch_arguments,
    )

    runtime_scope = scope_spec.runtime_scope()
    if (
        type(inherited_network_namespace) is not str
        or re.fullmatch(
            r"net:\[[1-9][0-9]*\]", inherited_network_namespace
        )
        is None
    ):
        raise V2IntegrityStop("V2 worker inherited network namespace differs")
    root_argv = tuple(
        bindings_module.cognee_worker_launch_argv(
            runtime_scope,
            inherited_network_namespace=inherited_network_namespace,
        )
    )
    worker_argv = (
        COGNEE_PYTHON,
        "-m",
        bindings_module._WORKER_MODULE,
        *worker_scope_launch_arguments(runtime_scope),
    )
    if root_argv != worker_argv:
        raise V2IntegrityStop("V2 inherited worker launch is not direct")
    return _V2WorkerGraphExpectation(
        root_argv=root_argv,
        worker_argv=worker_argv,
        allowed_intermediate_argv=(),
        root_executable=_resolved_executable(root_argv[0], "V2 worker root"),
        worker_executable=_resolved_executable(worker_argv[0], "V2 worker leaf"),
        root_uids=(1000, 1000, 1000, 1000),
        worker_uids=(1000, 1000, 1000, 1000),
        maximum_nodes=1,
    )


def _v2_process_key_snapshot() -> dict[tuple[int, int], int]:
    snapshot: dict[tuple[int, int], int] = {}
    try:
        entries = tuple(os.scandir("/proc"))
    except OSError as error:
        raise V2IntegrityStop("V2 prelaunch process inventory is unavailable") from error
    for entry in entries:
        if not entry.name.isdecimal():
            continue
        try:
            raw_stat = Path(entry.path, "stat").read_text(encoding="ascii")
            suffix = raw_stat.rsplit(") ", 1)
            fields = suffix[1].split() if len(suffix) == 2 else ()
            if len(fields) < 20:
                continue
            pid = int(entry.name)
            ppid = int(fields[1])
            starttime = int(fields[19])
        except (OSError, UnicodeError, ValueError):
            continue
        if pid > 0 and ppid >= 0 and starttime > 0:
            snapshot[(pid, starttime)] = ppid
    return snapshot


def _v2_exact_root_role(
    process: _V2WorkerProcessIdentity,
    expectation: _V2WorkerGraphExpectation,
) -> bool:
    return (
        process.argv == expectation.root_argv
        and process.executable in (None, expectation.root_executable)
        and process.uids == expectation.root_uids
        and process.ppid == os.getpid()
    )


def _v2_filtered_cmdline(pid: int) -> tuple[str, ...] | None:
    try:
        raw = (Path("/proc") / str(pid) / "cmdline").read_bytes()
    except OSError:
        return None
    if (
        not raw
        or len(raw) > _V2_PROC_CMDLINE_BYTES
        or not raw.endswith(b"\x00")
    ):
        return None
    try:
        value = tuple(
            item.decode("utf-8", errors="strict")
            for item in raw[:-1].split(b"\x00")
        )
    except UnicodeError:
        return None
    return value if value and all(value) else None


def _v2_owned_delta_keys(
    current: Mapping[tuple[int, int], int],
    baseline: frozenset[tuple[int, int]],
    expectation: _V2WorkerGraphExpectation,
) -> tuple[tuple[int, int], ...]:
    delta = set(current) - set(baseline)
    allowed_argv = {
        expectation.root_argv,
        expectation.worker_argv,
        *expectation.allowed_intermediate_argv,
    }
    role_keys = {
        key
        for key in delta
        if _v2_filtered_cmdline(key[0]) in allowed_argv
    }
    root_pids = {
        pid
        for pid, starttime in role_keys
        if current[(pid, starttime)] == os.getpid()
        and _v2_filtered_cmdline(pid) == expectation.root_argv
    }
    descendant_keys: set[tuple[int, int]] = set()
    changed = True
    descendant_pids = set(root_pids)
    while changed:
        changed = False
        for key in delta:
            if key in descendant_keys:
                continue
            if current[key] in descendant_pids:
                descendant_keys.add(key)
                descendant_pids.add(key[0])
                changed = True
    return tuple(sorted(role_keys | descendant_keys))


def _capture_v2_postlaunch_delta(
    baseline: frozenset[tuple[int, int]],
    expectation: _V2WorkerGraphExpectation,
) -> tuple[
    tuple[_V2WorkerProcessIdentity, ...],
    tuple[_V2WorkerProcessIdentity, ...],
]:
    current = _v2_process_key_snapshot()
    delta = _v2_owned_delta_keys(current, baseline, expectation)
    if len(delta) > _V2_COGNEE_CAPTURE_PROCESS_NODES:
        raise V2IntegrityStop("V2 failed-start process delta exceeds ceiling")
    captured: list[_V2WorkerProcessIdentity] = []
    try:
        for pid, expected_starttime in delta:
            try:
                pidfd = os.pidfd_open(pid, 0)
            except ProcessLookupError:
                continue
            if _v2_pidfd_terminal(pidfd):
                os.close(pidfd)
                continue
            try:
                first = _read_v2_process_identity(pid, depth=0, pidfd=pidfd)
                second = _read_v2_process_identity(pid, depth=0, pidfd=pidfd)
                if (
                    first.identity != second.identity
                    or second.starttime != expected_starttime
                    or _v2_pidfd_terminal(pidfd)
                ):
                    raise V2IntegrityStop(
                        "V2 failed-start process changed during capture"
                    )
            except BaseException:
                os.close(pidfd)
                raise
            captured.append(second)
    except BaseException:
        _close_v2_pidfds(captured)
        raise
    by_pid = {item.pid: item for item in captured}
    exact_roots = {
        item.pid for item in captured if _v2_exact_root_role(item, expectation)
    }

    def ancestry_depth(item: _V2WorkerProcessIdentity) -> int | None:
        depth = 0
        current_item = item
        seen: set[int] = set()
        while current_item.pid not in exact_roots:
            if current_item.pid in seen:
                return None
            seen.add(current_item.pid)
            parent = by_pid.get(current_item.ppid)
            if parent is None:
                return None
            current_item = parent
            depth += 1
        return depth

    authorized: list[_V2WorkerProcessIdentity] = []
    untrusted: list[_V2WorkerProcessIdentity] = []
    for item in captured:
        depth = ancestry_depth(item)
        # A matching argv/uid/executable is not launch authority: another local
        # actor can start the same exact scope after our baseline.  Failed-start
        # cleanup may signal only the root we observed as our direct child and
        # identities connected to that root by the captured ancestry chain.
        owned = depth is not None
        normalized = replace(
            item,
            depth=(
                depth
                if depth is not None
                else (1 if item.argv == expectation.worker_argv else 0)
            ),
        )
        (authorized if owned else untrusted).append(normalized)
    return tuple(authorized), tuple(untrusted)


def _assert_no_preexisting_v2_scope_process(
    expectation: _V2WorkerGraphExpectation,
) -> None:
    authorized, untrusted = _capture_v2_postlaunch_delta(
        frozenset(), expectation
    )
    try:
        if authorized or untrusted:
            raise V2IntegrityStop("V2 Cognee scope process already exists")
    finally:
        _close_v2_pidfds((*authorized, *untrusted))


@dataclass(slots=True)
class _V2FailedStartAuthority:
    scope_ref: str
    baseline: frozenset[tuple[int, int]]
    expectation: _V2WorkerGraphExpectation
    parent_attestation: Mapping[str, object] | None = field(
        default=None, repr=False
    )
    authorized: tuple[_V2WorkerProcessIdentity, ...] = field(
        default=(), repr=False
    )
    untrusted: tuple[_V2WorkerProcessIdentity, ...] = field(
        default=(), repr=False
    )
    terminal: bool = field(default=False, init=False)

    def __post_init__(self) -> None:
        _ref(self.scope_ref, "V2 failed-start scope ref")
        if (
            type(self.baseline) is not frozenset
            or type(self.expectation) is not _V2WorkerGraphExpectation
        ):
            raise V2InvariantError("V2 failed-start authority differs")
        if self.parent_attestation is not None:
            self.parent_attestation = MappingProxyType(
                _validate_v2_inherited_parent_attestation(
                    self.parent_attestation
                )
            )

    def _refresh(self) -> list[V2IntegrityStop]:
        failures: list[V2IntegrityStop] = []
        if self.parent_attestation is not None:
            try:
                current_parent = _attest_v2_inherited_worker_parent(
                    str(self.parent_attestation["network_namespace"])
                )
                if current_parent != dict(self.parent_attestation):
                    raise V2IntegrityStop(
                        "V2 failed-start parent attestation changed"
                    )
            except BaseException as error:
                failures.append(
                    _redacted_failure(
                        error, "V2_COGNEE_FAILED_START_PARENT_REJOIN_FAILED"
                    )
                )
        try:
            authorized, untrusted = _capture_v2_postlaunch_delta(
                self.baseline, self.expectation
            )
        except BaseException as error:
            return [
                _redacted_failure(error, "V2_COGNEE_FAILED_START_CAPTURE_FAILED")
            ]
        retained = {
            (item.pid, item.starttime): item
            for item in (*self.authorized, *self.untrusted)
        }
        owned_keys = {
            (item.pid, item.starttime) for item in self.authorized
        }
        for owned, rows in ((True, authorized), (False, untrusted)):
            for item in rows:
                key = (item.pid, item.starttime)
                existing = retained.get(key)
                if existing is not None:
                    os.close(item.pidfd)
                    if existing.identity != item.identity:
                        failures.append(
                            V2IntegrityStop(
                                "V2_COGNEE_FAILED_START_IDENTITY_DRIFT"
                            )
                        )
                    if owned != (key in owned_keys):
                        failures.append(
                            V2IntegrityStop(
                                "V2_COGNEE_FAILED_START_AUTHORITY_DRIFT"
                            )
                        )
                    continue
                retained[key] = item
                if owned:
                    self.authorized += (item,)
                    owned_keys.add(key)
                else:
                    self.untrusted += (item,)
        return failures

    async def close_terminal(self) -> None:
        if self.terminal:
            return
        failures = self._refresh()
        live, wait_failure = await _wait_v2_pidfds_fail_closed(
            self.authorized,
            0.0,
            "V2_COGNEE_FAILED_START_INITIAL_WAIT_FAILED",
        )
        if wait_failure is not None:
            failures.append(wait_failure)
        if live:
            failures.extend(_signal_v2_processes_leaf_first(live, signal.SIGTERM))
            live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.authorized,
                _V2_COGNEE_TERM_SECONDS,
                "V2_COGNEE_FAILED_START_TERM_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
        failures.extend(self._refresh())
        live, wait_failure = await _wait_v2_pidfds_fail_closed(
            self.authorized,
            0.0,
            "V2_COGNEE_FAILED_START_PRE_KILL_WAIT_FAILED",
        )
        if wait_failure is not None:
            failures.append(wait_failure)
        if live:
            failures.extend(_signal_v2_processes_leaf_first(live, signal.SIGKILL))
            live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.authorized,
                _V2_COGNEE_KILL_SECONDS,
                "V2_COGNEE_FAILED_START_KILL_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
        failures.extend(self._refresh())
        live, wait_failure = await _wait_v2_pidfds_fail_closed(
            self.authorized,
            0.0,
            "V2_COGNEE_FAILED_START_FINAL_WAIT_FAILED",
        )
        if wait_failure is not None:
            failures.append(wait_failure)
        untrusted_live, wait_failure = await _wait_v2_pidfds_fail_closed(
            self.untrusted,
            0.0,
            "V2_COGNEE_FAILED_START_UNTRUSTED_WAIT_FAILED",
        )
        if wait_failure is not None:
            failures.append(wait_failure)
        if live:
            failures.append(V2IntegrityStop("V2_COGNEE_FAILED_START_PROCESS_REMAINS"))
        if untrusted_live:
            failures.append(
                V2IntegrityStop("V2_COGNEE_FAILED_START_UNTRUSTED_REMAINS")
            )
        if not live and not untrusted_live:
            current = _v2_process_key_snapshot()
            final_delta = _v2_owned_delta_keys(
                current, self.baseline, self.expectation
            )
            if final_delta:
                failures.append(
                    V2IntegrityStop("V2_COGNEE_FAILED_START_DELTA_REMAINS")
                )
            else:
                self.terminal = True
                _close_v2_pidfds((*self.authorized, *self.untrusted))
                _UNRESOLVED_V2_COGNEE_STARTS.pop(self.scope_ref, None)
        if not self.terminal:
            _UNRESOLVED_V2_COGNEE_STARTS[self.scope_ref] = self
        if len(failures) == 1:
            raise failures[0]
        if failures:
            raise ExceptionGroup("V2 Cognee failed-start cleanup failed", failures) from None


@dataclass(slots=True)
class _V2CogneeWorkerHandle:
    """Exact non-destructive terminal authority for a bounded worker tree."""

    binding: object = field(repr=False)
    transport: object = field(repr=False)
    process: asyncio.subprocess.Process = field(repr=False)
    scope_spec: V2AcquisitionScopeSpec
    pid: int
    process_graph: tuple[_V2WorkerProcessIdentity, ...] = field(repr=False)
    untrusted_processes: tuple[_V2WorkerProcessIdentity, ...] = field(repr=False)
    graph_expectation: _V2WorkerGraphExpectation = field(repr=False)
    pipe_identities: tuple[tuple[int, int], ...] = field(repr=False)
    pipe_holder_bindings: tuple[
        tuple[int, int, tuple[tuple[int, int], ...]], ...
    ] = field(repr=False)
    semantic_graph_captured: bool = field(repr=False)
    parent_attestation: Mapping[str, object] | None = field(
        default=None, repr=False
    )
    terminal: bool = field(default=False, init=False)

    @classmethod
    def _capture_terminal_capability(
        cls,
        binding: object,
        scope_spec: V2AcquisitionScopeSpec,
        parent_attestation: Mapping[str, object],
    ) -> "_V2CogneeWorkerHandle":
        from angler.memory import cognee_subprocess_bindings as bindings_module

        transport = getattr(binding, "_transport", None)
        process = getattr(transport, "_process", None)
        pid = getattr(process, "pid", None)
        if (
            type(scope_spec) is not V2AcquisitionScopeSpec
            or type(binding) is not bindings_module.CogneeSubprocessBindings
            or type(transport) is not bindings_module._SubprocessTransport
            or type(process) is not asyncio.subprocess.Process
            or type(pid) is not int
            or pid <= 0
        ):
            raise V2IntegrityStop("live Cognee worker handle differs")
        bound_parent = _validate_v2_inherited_parent_attestation(
            parent_attestation
        )
        namespace = str(bound_parent["network_namespace"])
        if _attest_v2_inherited_worker_parent(namespace) != bound_parent:
            raise V2IntegrityStop(
                "live Cognee worker parent changed before capture"
            )
        pipe_identities = _v2_asyncio_pipe_identities(process)
        graph_expectation = _v2_cognee_graph_expectation(
            scope_spec, namespace
        )
        (
            process_graph,
            untrusted_processes,
            pipe_holder_bindings,
            semantic_graph_captured,
        ) = _capture_v2_terminal_authority(
            pid, pipe_identities, graph_expectation
        )
        return cls(
            binding=binding,
            transport=transport,
            process=process,
            scope_spec=scope_spec,
            pid=pid,
            process_graph=process_graph,
            untrusted_processes=untrusted_processes,
            graph_expectation=graph_expectation,
            pipe_identities=pipe_identities,
            pipe_holder_bindings=pipe_holder_bindings,
            semantic_graph_captured=semantic_graph_captured,
            parent_attestation=MappingProxyType(bound_parent),
        )

    @classmethod
    def capture(
        cls,
        binding: object,
        scope_spec: V2AcquisitionScopeSpec,
        parent_attestation: Mapping[str, object],
    ) -> "_V2CogneeWorkerHandle":
        value = cls._capture_terminal_capability(
            binding, scope_spec, parent_attestation
        )
        try:
            if (
                getattr(binding, "scope", None) != scope_spec.runtime_scope()
                or getattr(binding, "_closed", None) is not False
                or getattr(binding, "_usable", None) is not True
                or getattr(value.transport, "_closed", None) is not False
                or value.process.returncode is not None
                or not value.semantic_graph_captured
            ):
                raise V2IntegrityStop("live Cognee worker launch identity differs")
            _validate_v2_process_graph(
                value.process_graph,
                value.graph_expectation,
                value.pipe_identities,
            )
            _validate_v2_inherited_worker_process_graph(
                value.process_graph,
                value.parent_attestation,
            )
            _validate_v2_pipe_holder_bindings(
                (*value.process_graph, *value.untrusted_processes),
                value.pipe_holder_bindings,
                value.pipe_identities,
            )
        except BaseException:
            _close_v2_pidfds(
                (*value.process_graph, *value.untrusted_processes)
            )
            raise
        return value

    def _rejoin_parent_attestation(self) -> None:
        if self.parent_attestation is None:
            return
        expected = dict(self.parent_attestation)
        current = _attest_v2_inherited_worker_parent(
            str(expected["network_namespace"])
        )
        if current != expected:
            raise V2IntegrityStop(
                "live Cognee worker parent attestation changed"
            )

    def _assert_identity(self, *, require_scope: bool) -> None:
        if (
            getattr(self.binding, "_transport", None) is not self.transport
            or getattr(self.transport, "_process", None) is not self.process
            or self.process.pid != self.pid
            or (
                require_scope
                and getattr(self.binding, "scope", None)
                != self.scope_spec.runtime_scope()
            )
        ):
            raise V2IntegrityStop("live Cognee worker identity changed")

    def _rescan_merge_before_close(self) -> list[V2IntegrityStop]:
        failures: list[V2IntegrityStop] = []
        observed: tuple[_V2WorkerProcessIdentity, ...] = ()
        try:
            self._rejoin_parent_attestation()
        except BaseException as error:
            failures.append(
                _redacted_failure(
                    error, "V2_COGNEE_PARENT_REJOIN_FAILED"
                )
            )
        try:
            (
                observed,
                observed_untrusted,
                observed_bindings,
                semantic_graph_captured,
            ) = _capture_v2_terminal_authority(
                self.pid,
                self.pipe_identities,
                self.graph_expectation,
            )
            retained_roots = tuple(
                item
                for item in self.process_graph
                if item.pid == self.pid and item.depth == 0
            )
            observed_roots = tuple(
                item
                for item in observed
                if item.pid == self.pid and item.depth == 0
            )
            root_reused = bool(observed_roots) and (
                len(retained_roots) != 1
                or len(observed_roots) != 1
                or observed_roots[0].starttime != retained_roots[0].starttime
            )
            if root_reused:
                failures.append(V2IntegrityStop("V2_COGNEE_ROOT_PID_REUSED"))
                retained = {
                    (item.pid, item.starttime): item
                    for item in self.process_graph
                }
                demoted: list[_V2WorkerProcessIdentity] = list(
                    observed_untrusted
                )
                for item in observed:
                    existing = retained.get((item.pid, item.starttime))
                    if existing is None:
                        demoted.append(item)
                    else:
                        os.close(item.pidfd)
                        if existing.identity != item.identity:
                            failures.append(
                                V2IntegrityStop(
                                    "V2_COGNEE_RETAINED_IDENTITY_DRIFT"
                                )
                            )
                observed = ()
                observed_untrusted = tuple(demoted)
                semantic_graph_captured = False
            else:
                try:
                    merged = _merge_v2_process_graph(
                        self.process_graph, observed
                    )
                except BaseException as error:
                    failures.append(
                        _redacted_failure(
                            error, "V2_COGNEE_PROCESS_MERGE_FAILED"
                        )
                    )
                    # With the original root still bound, a replacement child
                    # remains a descendant of our captured launch authority.
                    known = {
                        (item.pid, item.starttime)
                        for item in self.process_graph
                    }
                    self.process_graph = self.process_graph + tuple(
                        item
                        for item in observed
                        if (item.pid, item.starttime) not in known
                    )
                else:
                    self.process_graph = merged
            known_untrusted = {
                (item.pid, item.starttime): item
                for item in self.untrusted_processes
            }
            for item in observed_untrusted:
                existing = known_untrusted.get((item.pid, item.starttime))
                if existing is None:
                    self.untrusted_processes += (item,)
                    known_untrusted[(item.pid, item.starttime)] = item
                else:
                    os.close(item.pidfd)
                    if existing.identity != item.identity:
                        failures.append(
                            V2IntegrityStop(
                                "V2_COGNEE_UNTRUSTED_HOLDER_IDENTITY_DRIFT"
                            )
                        )
            try:
                if root_reused:
                    raise V2IntegrityStop("V2 worker root pid was reused")
                _validate_v2_process_graph(
                    observed,
                    self.graph_expectation,
                    self.pipe_identities,
                )
                if self.parent_attestation is not None:
                    _validate_v2_inherited_worker_process_graph(
                        observed,
                        self.parent_attestation,
                    )
                _validate_v2_pipe_holder_bindings(
                    (*observed, *observed_untrusted),
                    observed_bindings,
                    self.pipe_identities,
                )
                if not semantic_graph_captured:
                    raise V2IntegrityStop("V2 worker process graph gained a holder")
            except BaseException as error:
                failures.append(
                    _redacted_failure(error, "V2_COGNEE_PROCESS_GRAPH_DRIFT")
                )
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_PROCESS_RESCAN_FAILED")
            )
        return failures

    def _merge_pipe_holders(self) -> list[V2IntegrityStop]:
        try:
            self._rejoin_parent_attestation()
            graph, untrusted, bindings, drift = _capture_v2_pipe_holder_authority(
                self.pipe_identities,
                self.process_graph,
                self.untrusted_processes,
                self.graph_expectation,
            )
            self.process_graph = graph
            self.untrusted_processes = untrusted
            self.pipe_holder_bindings = bindings
            _validate_v2_pipe_holder_bindings(
                (*graph, *untrusted), bindings, self.pipe_identities
            )
            if drift:
                raise V2IntegrityStop("V2 worker pipe-holder graph drifted")
        except BaseException as error:
            return [
                _redacted_failure(error, "V2_COGNEE_PIPE_HOLDER_CAPTURE_FAILED")
            ]
        return []

    async def close_terminal(self, *, require_scope: bool = True) -> None:
        """Close gracefully, then terminate every exact captured descendant."""

        if type(require_scope) is not bool:
            raise TypeError("Cognee terminal-close scope flag differs")
        self._assert_identity(require_scope=require_scope)
        if self.terminal:
            if self.process.returncode is None:
                raise V2IntegrityStop("terminal Cognee worker became live")
            return
        failures = self._rescan_merge_before_close()
        failures.extend(self._merge_pipe_holders())
        graceful_task: asyncio.Task[object] | None = None
        try:
            graceful_task = asyncio.create_task(
                _maybe_await(self.binding.close())
            )
            await asyncio.wait_for(
                asyncio.shield(graceful_task),
                timeout=_V2_COGNEE_GRACEFUL_CLOSE_SECONDS,
            )
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_GRACEFUL_CLOSE_FAILED")
            )
            if graceful_task is not None and not graceful_task.done():
                graceful_task.cancel()
        finally:
            process = self.process
            if process.stdin is not None:
                try:
                    process.stdin.close()
                except BaseException as error:
                    failures.append(
                        _redacted_failure(error, "V2_COGNEE_STDIN_CLOSE_FAILED")
                    )
            live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.process_graph,
                0.0,
                "V2_COGNEE_INITIAL_PIDFD_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
            if live:
                failures.extend(
                    _signal_v2_processes_leaf_first(live, signal.SIGTERM)
                )
                live, wait_failure = await _wait_v2_pidfds_fail_closed(
                    self.process_graph,
                    _V2_COGNEE_TERM_SECONDS,
                    "V2_COGNEE_TERM_PIDFD_WAIT_FAILED",
                )
                if wait_failure is not None:
                    failures.append(wait_failure)
            failures.extend(self._merge_pipe_holders())
            live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.process_graph,
                0.0,
                "V2_COGNEE_PRE_KILL_PIDFD_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
            if live:
                failures.extend(
                    _signal_v2_processes_leaf_first(live, signal.SIGKILL)
                )
                live, wait_failure = await _wait_v2_pidfds_fail_closed(
                    self.process_graph,
                    _V2_COGNEE_KILL_SECONDS,
                    "V2_COGNEE_KILL_PIDFD_WAIT_FAILED",
                )
                if wait_failure is not None:
                    failures.append(wait_failure)
            failures.extend(self._merge_pipe_holders())
            late_live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.process_graph,
                0.0,
                "V2_COGNEE_LATE_PIDFD_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
            if late_live:
                failures.extend(
                    _signal_v2_processes_leaf_first(late_live, signal.SIGKILL)
                )
                late_live, wait_failure = await _wait_v2_pidfds_fail_closed(
                    self.process_graph,
                    1.0,
                    "V2_COGNEE_FINAL_PIDFD_WAIT_FAILED",
                )
                if wait_failure is not None:
                    failures.append(wait_failure)
            live = late_live
            untrusted_live, wait_failure = await _wait_v2_pidfds_fail_closed(
                self.untrusted_processes,
                0.0,
                "V2_COGNEE_UNTRUSTED_PIDFD_WAIT_FAILED",
            )
            if wait_failure is not None:
                failures.append(wait_failure)
            if untrusted_live:
                failures.append(
                    V2IntegrityStop("V2_COGNEE_UNTRUSTED_PIPE_HOLDER_REMAINS")
                )
            if not live:
                try:
                    if not await _wait_v2_asyncio_process_exit(process, 0.5):
                        raise V2IntegrityStop(
                            "V2_COGNEE_DIRECT_CHILD_REAP_TIMEOUT"
                        )
                    await asyncio.wait_for(process.wait(), timeout=0.25)
                except BaseException as error:
                    failures.append(
                        _redacted_failure(
                            error, "V2_COGNEE_DIRECT_CHILD_REAP_FAILED"
                        )
                    )
            if graceful_task is not None:
                if not graceful_task.done():
                    graceful_task.cancel()
                try:
                    await asyncio.wait_for(
                        asyncio.shield(
                            asyncio.gather(graceful_task, return_exceptions=True)
                        ),
                        timeout=0.25,
                    )
                except BaseException:
                    pass
            stderr_task = getattr(self.transport, "_stderr_task", None)
            if isinstance(stderr_task, asyncio.Task) and not stderr_task.done():
                stderr_task.cancel()
                try:
                    await asyncio.gather(stderr_task, return_exceptions=True)
                except BaseException as error:
                    failures.append(
                        _redacted_failure(error, "V2_COGNEE_STDERR_DRAIN_FAILED")
                    )
            if live or untrusted_live or process.returncode is None:
                failures.append(V2IntegrityStop("V2_COGNEE_WORKER_NOT_TERMINAL"))
            else:
                try:
                    holders = _v2_pipe_holders(self.pipe_identities)
                except BaseException as error:
                    failures.append(
                        _redacted_failure(
                            error, "V2_COGNEE_FINAL_PIPE_SCAN_FAILED"
                        )
                    )
                    holders = (-1,)
                if holders:
                    failures.append(
                        V2IntegrityStop("V2_COGNEE_PIPE_HOLDER_REMAINS")
                    )
                else:
                    self.terminal = True
                    setattr(self.transport, "_closed", True)
                    setattr(self.binding, "_closed", True)
                    setattr(self.binding, "_usable", False)
                    _close_v2_pidfds(
                        (*self.process_graph, *self.untrusted_processes)
                    )
                    _UNRESOLVED_V2_COGNEE_HANDLES.pop(self.pid, None)
            if not self.terminal:
                _UNRESOLVED_V2_COGNEE_HANDLES[self.pid] = self
        if len(failures) == 1:
            raise failures[0]
        if failures:
            raise ExceptionGroup("V2 Cognee terminal close failed", failures) from None


async def _close_v2_acquisition_binding_preserving_state(
    binding: object,
    *,
    worker_handle: _V2CogneeWorkerHandle | None = None,
) -> None:
    """Stop one rejected worker without erasing its consumed scope identity."""

    if worker_handle is not None:
        if (
            type(worker_handle) is not _V2CogneeWorkerHandle
            or worker_handle.binding is not binding
        ):
            raise V2IntegrityStop("V2 rejected worker handle differs")
        await worker_handle.close_terminal()
        return
    # Exact live construction always transfers a `_V2CogneeWorkerHandle` with
    # the binding.  The no-handle path is retained for two deliberately
    # separate cases: (a) an exact live binding rejected before that transfer,
    # which needs the strict process/pipe fallback below, and (b) the explicit
    # injected-test opener, whose binding has no live process authority to
    # prove.  Never put an injected binding into the live unresolved-worker
    # registries merely because it (correctly) has no asyncio subprocess.
    from angler.memory.cognee_subprocess_bindings import (
        CogneeSubprocessBindings,
    )

    if type(binding) is not CogneeSubprocessBindings:
        injected_close = getattr(binding, "close", None)
        if not callable(injected_close):
            raise V2IntegrityStop(
                "V2_INJECTED_COGNEE_BINDING_CLOSE_UNAVAILABLE"
            )
        injected_task: asyncio.Task[object] | None = None
        injected_failure: V2IntegrityStop | None = None
        try:
            injected_task = asyncio.create_task(
                _maybe_await(injected_close())
            )
            await asyncio.wait_for(
                asyncio.shield(injected_task),
                timeout=_V2_COGNEE_GRACEFUL_CLOSE_SECONDS,
            )
        except BaseException as error:
            if injected_task is not None and not injected_task.done():
                injected_task.cancel()
                try:
                    await asyncio.wait_for(
                        asyncio.shield(
                            asyncio.gather(
                                injected_task, return_exceptions=True
                            )
                        ),
                        timeout=0.25,
                    )
                except BaseException:
                    pass
            injected_failure = _redacted_cleanup_failure(
                error, "V2_INJECTED_COGNEE_BINDING_CLOSE_FAILED"
            )
        if injected_failure is not None:
            raise injected_failure from None
        return
    close = getattr(binding, "close", None)
    if not callable(close):
        raise V2IntegrityStop("V2_COGNEE_REJECTED_BINDING_CLOSE_UNAVAILABLE")
    close_task: asyncio.Task[object] | None = None
    failures: list[V2IntegrityStop] = []
    transport = getattr(binding, "_transport", None)
    process = getattr(transport, "_process", None)
    pipe_identities: tuple[tuple[int, int], ...] | None = None
    if type(process) is asyncio.subprocess.Process:
        prior_unresolved = _UNRESOLVED_V2_COGNEE_BINDINGS.get(process.pid)
        try:
            pipe_identities = _v2_asyncio_pipe_identities(process)
        except BaseException as error:
            if (
                type(prior_unresolved) is _V2UnresolvedCogneeBinding
                and prior_unresolved.binding is binding
                and prior_unresolved.process is process
                and prior_unresolved.pipe_identities is not None
            ):
                pipe_identities = prior_unresolved.pipe_identities
            else:
                failures.append(
                    _redacted_failure(
                        error, "V2_COGNEE_REJECTED_PIPE_CAPTURE_FAILED"
                    )
                )
    else:
        failures.append(V2IntegrityStop("V2_COGNEE_REJECTED_PROCESS_UNAVAILABLE"))
    try:
        close_task = asyncio.create_task(_maybe_await(close()))
        await asyncio.wait_for(
            asyncio.shield(close_task),
            timeout=_V2_COGNEE_GRACEFUL_CLOSE_SECONDS,
        )
    except BaseException as error:
        failures.append(
            _redacted_failure(
                error, "V2_COGNEE_REJECTED_BINDING_CLOSE_FAILED"
            )
        )
        if close_task is not None and not close_task.done():
            close_task.cancel()
    if type(process) is asyncio.subprocess.Process and process.returncode is None:
        try:
            process.terminate()
        except ProcessLookupError:
            pass
        except BaseException as error:
            failures.append(
                _redacted_failure(
                    error, "V2_COGNEE_REJECTED_PROCESS_TERMINATE_FAILED"
                )
            )
        try:
            terminal = await _wait_v2_asyncio_process_exit(
                process, _V2_COGNEE_TERM_SECONDS
            )
            if not terminal:
                raise asyncio.TimeoutError
        except asyncio.TimeoutError:
            try:
                process.kill()
            except ProcessLookupError:
                pass
            except BaseException as error:
                failures.append(
                    _redacted_failure(
                        error, "V2_COGNEE_REJECTED_PROCESS_KILL_FAILED"
                    )
                )
            try:
                terminal = await _wait_v2_asyncio_process_exit(
                    process, _V2_COGNEE_KILL_SECONDS
                )
                if not terminal:
                    raise asyncio.TimeoutError
            except BaseException as error:
                failures.append(
                    _redacted_failure(
                        error, "V2_COGNEE_REJECTED_PROCESS_WAIT_FAILED"
                    )
                )
        except BaseException as error:
            failures.append(
                _redacted_failure(
                    error, "V2_COGNEE_REJECTED_PROCESS_WAIT_FAILED"
                )
            )
    if type(process) is asyncio.subprocess.Process and process.returncode is None:
        failures.append(V2IntegrityStop("V2_COGNEE_REJECTED_PROCESS_NOT_TERMINAL"))
    remaining_holders: tuple[int, ...] = ()
    if pipe_identities is not None:
        try:
            remaining_holders = _v2_pipe_holders(pipe_identities)
        except BaseException as error:
            failures.append(
                _redacted_failure(
                    error, "V2_COGNEE_REJECTED_PIPE_SCAN_FAILED"
                )
            )
            remaining_holders = (-1,)
        if remaining_holders:
            failures.append(
                V2IntegrityStop("V2_COGNEE_REJECTED_PIPE_HOLDER_REMAINS")
            )
    if close_task is not None:
        if not close_task.done():
            close_task.cancel()
        try:
            await asyncio.wait_for(
                asyncio.shield(asyncio.gather(close_task, return_exceptions=True)),
                timeout=0.25,
            )
        except BaseException:
            pass
    if type(process) is asyncio.subprocess.Process:
        if (
            process.returncode is None
            or pipe_identities is None
            or remaining_holders
        ):
            _UNRESOLVED_V2_COGNEE_BINDINGS[process.pid] = (
                _V2UnresolvedCogneeBinding(
                    binding=binding,
                    process=process,
                    pipe_identities=pipe_identities,
                )
            )
        else:
            _UNRESOLVED_V2_COGNEE_BINDINGS.pop(process.pid, None)
    else:
        opaque_key = -id(binding)
        _UNRESOLVED_V2_COGNEE_BINDINGS[opaque_key] = (
            _V2UnresolvedCogneeBinding(
                binding=binding,
                process=process,
                pipe_identities=None,
            )
        )
    if len(failures) == 1:
        raise failures[0]
    if failures:
        raise ExceptionGroup("V2 rejected binding close failed", failures) from None


async def _drain_unresolved_v2_cognee_workers() -> None:
    """Retry exact retained terminal authorities; never erase live scopes."""

    failures: list[V2IntegrityStop] = []
    for pid, raw_handle in tuple(_UNRESOLVED_V2_COGNEE_HANDLES.items()):
        if type(raw_handle) is not _V2CogneeWorkerHandle or raw_handle.pid != pid:
            failures.append(V2IntegrityStop("V2_COGNEE_RETAINED_HANDLE_INVALID"))
            continue
        try:
            await raw_handle.close_terminal(require_scope=False)
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_RETAINED_HANDLE_CLOSE_FAILED")
            )
        if raw_handle.terminal:
            _UNRESOLVED_V2_COGNEE_HANDLES.pop(pid, None)
    for pid, record in tuple(_UNRESOLVED_V2_COGNEE_BINDINGS.items()):
        if (
            type(record) is not _V2UnresolvedCogneeBinding
            or (
                type(record.process) is asyncio.subprocess.Process
                and record.process.pid != pid
            )
            or (
                type(record.process) is not asyncio.subprocess.Process
                and pid != -id(record.binding)
            )
        ):
            failures.append(V2IntegrityStop("V2_COGNEE_RETAINED_BINDING_INVALID"))
            continue
        try:
            await _close_v2_acquisition_binding_preserving_state(record.binding)
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_RETAINED_BINDING_CLOSE_FAILED")
            )
    for scope_ref, raw_authority in tuple(
        _UNRESOLVED_V2_COGNEE_STARTS.items()
    ):
        if (
            type(raw_authority) is not _V2FailedStartAuthority
            or raw_authority.scope_ref != scope_ref
        ):
            failures.append(V2IntegrityStop("V2_COGNEE_RETAINED_START_INVALID"))
            continue
        try:
            await raw_authority.close_terminal()
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_RETAINED_START_CLOSE_FAILED")
            )
    if (
        _UNRESOLVED_V2_COGNEE_HANDLES
        or _UNRESOLVED_V2_COGNEE_BINDINGS
        or _UNRESOLVED_V2_COGNEE_STARTS
    ):
        failures.append(V2IntegrityStop("V2_COGNEE_RETAINED_WORKER_REMAINS"))
    if len(failures) == 1:
        raise failures[0]
    if failures:
        raise ExceptionGroup("V2 retained Cognee cleanup failed", failures) from None


def _assert_no_unresolved_v2_cognee_workers() -> None:
    if (
        _UNRESOLVED_V2_COGNEE_HANDLES
        or _UNRESOLVED_V2_COGNEE_BINDINGS
        or _UNRESOLVED_V2_COGNEE_STARTS
    ):
        raise V2IntegrityStop("V2_COGNEE_RETAINED_WORKER_REMAINS")


async def open_v2_acquisition_scope_live(
    scope_spec: V2AcquisitionScopeSpec,
    *,
    expected_dataset_id: str | None = None,
) -> object:
    """Open only the stable product Cognee binding and acquisition adapter."""

    if type(scope_spec) is not V2AcquisitionScopeSpec:
        raise TypeError("V2 live acquisition scope spec differs")
    from angler.memory.cognee_acquisition_adapter import CogneeAcquisitionAdapter
    from angler.memory.cognee_subprocess_bindings import CogneeSubprocessBindings

    _assert_no_unresolved_v2_cognee_workers()
    parent_attestation = _attest_v2_inherited_worker_parent()
    network_namespace = str(parent_attestation["network_namespace"])
    graph_expectation = _v2_cognee_graph_expectation(
        scope_spec, network_namespace
    )
    _assert_no_preexisting_v2_scope_process(graph_expectation)
    prelaunch = frozenset(_v2_process_key_snapshot())
    try:
        if (
            _attest_v2_inherited_worker_parent(network_namespace)
            != parent_attestation
        ):
            raise V2IntegrityStop(
                "V2 Cognee parent changed before worker start"
            )
        binding = await CogneeSubprocessBindings.start(
            scope=scope_spec.runtime_scope(),
            expected_dataset_id=expected_dataset_id,
            timeout_seconds=30.0,
            inherited_network_namespace=network_namespace,
        )
    except BaseException as error:
        primary = _redacted_failure(error, "V2_COGNEE_BINDING_START_FAILED")
        authority = _V2FailedStartAuthority(
            scope_ref=scope_spec.scope_ref,
            baseline=prelaunch,
            expectation=graph_expectation,
            parent_attestation=parent_attestation,
        )
        _UNRESOLVED_V2_COGNEE_STARTS[scope_spec.scope_ref] = authority
        try:
            await authority.close_terminal()
        except BaseException as cleanup_error:
            raise ExceptionGroup(
                "V2 Cognee start and descendant cleanup failed",
                [
                    primary,
                    _redacted_failure(
                        cleanup_error,
                        "V2_COGNEE_BINDING_START_CLEANUP_FAILED",
                    ),
                ],
            ) from None
        raise primary from None
    worker_handle: _V2CogneeWorkerHandle | None = None
    try:
        worker_handle = _V2CogneeWorkerHandle.capture(
            binding, scope_spec, parent_attestation
        )
        backend = CogneeAcquisitionAdapter(
            bindings=binding,
            tenant_id=binding.tenant_id,
            dataset_id=binding.dataset_id,
            dataset_name=binding.dataset_name,
            node_set_name=binding.node_set_name,
            local_embeddings_configured=True,
            external_embedding_calls_authorized=False,
            telemetry_authorized=False,
        )
        return V2AcquisitionSession(
            scope_spec,
            binding,
            backend,
            binding.dataset_id,
            _worker_handle=worker_handle,
        )
    except BaseException as error:
        primary = _redacted_failure(error, "V2_COGNEE_SESSION_CREATE_FAILED")
        cleanup: V2IntegrityStop | None = None
        try:
            if worker_handle is None:
                try:
                    worker_handle = (
                        _V2CogneeWorkerHandle._capture_terminal_capability(
                            binding, scope_spec, parent_attestation
                        )
                    )
                except BaseException as capture_error:
                    capture_failure = _redacted_failure(
                        capture_error, "V2_COGNEE_HANDLE_CAPTURE_FAILED"
                    )
                    await _close_v2_acquisition_binding_preserving_state(binding)
                    raise capture_failure
                else:
                    await worker_handle.close_terminal(require_scope=False)
            else:
                await _close_v2_acquisition_binding_preserving_state(
                    binding, worker_handle=worker_handle
                )
        except BaseException as close_error:
            cleanup = _redacted_failure(
                close_error, "V2_COGNEE_BINDING_CREATE_CLEANUP_FAILED"
            )
        binding = None
        if cleanup is not None:
            raise ExceptionGroup(
                "V2 Cognee adapter construction and cleanup failed",
                [primary, cleanup],
            ) from None
        raise primary from None


V2AcquisitionOpener: TypeAlias = Callable[..., Awaitable[object] | object]


@dataclass(slots=True)
class V2AcquisitionSession:
    """Own one V2 Cognee namespace through forget, close, and tree cleanup."""

    scope_spec: V2AcquisitionScopeSpec
    binding: object = field(repr=False)
    backend: object = field(repr=False)
    dataset_id: str
    _worker_handle: _V2CogneeWorkerHandle | None = field(
        default=None, repr=False, compare=False
    )
    _closed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        if type(self.scope_spec) is not V2AcquisitionScopeSpec:
            raise TypeError("V2 acquisition session scope differs")
        self.dataset_id = _text(
            self.dataset_id, "V2 acquisition dataset id", 512
        )
        if not callable(getattr(self.binding, "close", None)):
            raise TypeError("V2 acquisition binding lacks close")
        if self._worker_handle is not None and (
            type(self._worker_handle) is not _V2CogneeWorkerHandle
            or self._worker_handle.binding is not self.binding
            or self._worker_handle.scope_spec != self.scope_spec
        ):
            raise V2IntegrityStop("V2 acquisition worker handle differs")
        for method in ("project", "search", "forget_namespace"):
            if not callable(getattr(self.backend, method, None)):
                raise TypeError(f"V2 acquisition backend lacks {method}")
        expected = {
            "dataset_name": self.scope_spec.dataset_name,
            "tenant_name": self.scope_spec.tenant_name,
            "node_set_name": self.scope_spec.node_set_name,
        }
        if any(getattr(self.binding, name, None) != value for name, value in expected.items()):
            raise V2IntegrityStop("V2 acquisition binding scope differs")

    async def forget_close_and_remove(self) -> None:
        if self._closed:
            raise V2IntegrityStop("V2 acquisition session is already closed")
        failures: list[V2IntegrityStop] = []
        forgotten = False
        closed = False
        try:
            await _maybe_await(self.backend.forget_namespace())
            forgotten = True
        except BaseException as error:
            failures.append(
                _redacted_failure(error, "V2_COGNEE_NAMESPACE_FORGET_FAILED")
            )
        try:
            await _close_v2_acquisition_binding_preserving_state(
                self.binding,
                worker_handle=self._worker_handle,
            )
            closed = True
        except BaseException as error:
            closed = False
            failures.append(
                _redacted_failure(error, "V2_COGNEE_BINDING_CLOSE_FAILED")
            )
        if forgotten and closed:
            try:
                root = Path(self.scope_spec.state_root)
                _remove_exact_private_tree(root, expected_parent=root.parent)
            except BaseException as error:
                failures.append(
                    _redacted_failure(error, "V2_COGNEE_SCOPE_REMOVE_FAILED")
                )
        if not failures:
            self._closed = True
            self.binding = None
            self.backend = None
            return
        if len(failures) == 1:
            raise failures[0]
        raise ExceptionGroup("V2 Cognee cleanup failed", failures) from None

    async def close_preserving_state(self) -> None:
        """Stop the worker while retaining every already-created scope byte."""

        if self._closed:
            return
        failure: V2IntegrityStop | None = None
        try:
            await _close_v2_acquisition_binding_preserving_state(
                self.binding,
                worker_handle=self._worker_handle,
            )
        except BaseException as error:
            failure = _redacted_failure(
                error, "V2_COGNEE_PRESERVING_CLOSE_FAILED"
            )
        terminal = (
            self._worker_handle.terminal
            if self._worker_handle is not None
            else failure is None
        )
        if terminal:
            self._closed = True
            self.binding = None
            self.backend = None
            self._worker_handle = None
        if failure is not None:
            raise failure from None


async def _open_v2_acquisition_session(
    scope_spec: V2AcquisitionScopeSpec,
    *,
    opener: V2AcquisitionOpener,
    expected_dataset_id: str | None = None,
) -> V2AcquisitionSession:
    if type(scope_spec) is not V2AcquisitionScopeSpec or not callable(opener):
        raise TypeError("V2 acquisition opener inputs differ")
    value = await _maybe_await(
        opener(scope_spec, expected_dataset_id=expected_dataset_id)
    )
    if type(value) is V2AcquisitionSession:
        if value.scope_spec != scope_spec or (
            expected_dataset_id is not None
            and value.dataset_id != expected_dataset_id
        ):
            primary = V2IntegrityStop(
                "opened V2 acquisition session identity differs"
            )
            try:
                await value.close_preserving_state()
            except BaseException as error:
                cleanup = _redacted_failure(
                    error, "V2_COGNEE_MISMATCHED_SESSION_CLEANUP_FAILED"
                )
                raise ExceptionGroup(
                    "mismatched V2 Cognee session and cleanup failed",
                    [primary, cleanup],
                ) from None
            raise primary
        return value
    if type(value) is not tuple or len(value) != 2:
        raise TypeError("V2 acquisition opener must return one binding/backend pair")
    binding, backend = value
    try:
        dataset_id = _text(
            getattr(binding, "dataset_id", None),
            "opened V2 acquisition dataset id",
            512,
        )
        if expected_dataset_id is not None and dataset_id != expected_dataset_id:
            raise V2IntegrityStop("reopened V2 acquisition dataset id differs")
        return V2AcquisitionSession(scope_spec, binding, backend, dataset_id)
    except BaseException as error:
        primary = _redacted_failure(error, "V2_COGNEE_SESSION_VALIDATE_FAILED")
        try:
            await _close_v2_acquisition_binding_preserving_state(binding)
        except BaseException as close_error:
            cleanup = _redacted_failure(
                close_error, "V2_COGNEE_SESSION_VALIDATE_CLEANUP_FAILED"
            )
            raise ExceptionGroup(
                "V2 Cognee session validation and cleanup failed",
                [primary, cleanup],
            ) from None
        raise primary from None


@dataclass(frozen=True, slots=True)
class V2LineageMechanics:
    """Private injectable seam for CPU-only owner tests; live wrappers fix it."""

    restore_genesis: Callable[..., object]
    clone_paths_factory: Callable[..., object]
    transaction_store_factory: Callable[[Path], object]
    journal_factory: Callable[[Path], object]
    bootstrap_episode_factory: Callable[[str, object], object]
    memory_factory: Callable[..., object]
    closed_hashes: Callable[..., Mapping[str, str]]
    assert_quiescent: Callable[..., None]

    def __post_init__(self) -> None:
        if any(
            not callable(value)
            for value in (
                self.restore_genesis,
                self.clone_paths_factory,
                self.transaction_store_factory,
                self.journal_factory,
                self.bootstrap_episode_factory,
                self.memory_factory,
                self.closed_hashes,
                self.assert_quiescent,
            )
        ):
            raise TypeError("V2 lineage mechanics contain a non-callable")


def _live_v2_lineage_mechanics() -> V2LineageMechanics:
    helpers = _load_approved_r2_low_level_helpers()
    from angler.memory.cognitive_acquisition_graph import AcquisitionSituatedMemory
    from angler.runtime.cognitive_transaction_store import CognitiveTransactionStore
    from angler.runtime.qwen_cognitive import SQLiteQwenExecutionJournal

    return V2LineageMechanics(
        restore_genesis=helpers["restore_fresh_cpu_genesis"],
        clone_paths_factory=helpers["ClonePaths"],
        transaction_store_factory=CognitiveTransactionStore,
        journal_factory=SQLiteQwenExecutionJournal,
        bootstrap_episode_factory=helpers["_qualified_unrelated_bootstrap_episode"],
        memory_factory=AcquisitionSituatedMemory,
        closed_hashes=helpers["_closed_baseline_hashes"],
        assert_quiescent=helpers["_assert_successor_quiescent"],
    )


@dataclass(slots=True)
class V2LineageOwner:
    """One persistent IN or IO lineage beginning from the exact V2 neutral genesis."""

    purpose: Purpose
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    root: Path
    paths: object = field(repr=False)
    learner: object = field(repr=False)
    store: object = field(repr=False)
    journal: object = field(repr=False)
    scope_spec: V2AcquisitionScopeSpec
    allocation_ref: str
    allocation: "V2PersistentLineageAllocation" = field(repr=False)
    ledger: EvidenceLedger = field(repr=False, compare=False)
    bootstrap_episode_ref: str
    neutral_episode_refs: tuple[str, ...]
    neutral_chain_ref: str
    genesis_competence_digest: str
    model_ref: str
    encoder_ref: str
    initial_hashes: tuple[tuple[str, str], ...]
    _mechanics: V2LineageMechanics = field(repr=False, compare=False)
    _seal: BaselineSeal | None = field(default=None, init=False, repr=False)
    _bound_identities: dict[str, tuple[str, int, int]] = field(
        default_factory=dict, init=False, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        _ref(self.replicate_commitment, "V2 lineage replicate commitment")
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("V2 lineage arm differs")
        if (
            not isinstance(self.root, Path)
            or not self.root.is_absolute()
            or _private_root_identity(self.root, "V2 lineage root")[0]
            != str(self.root)
        ):
            raise V2InvariantError("V2 lineage root differs")
        if (
            type(self.scope_spec) is not V2AcquisitionScopeSpec
            or self.scope_spec.purpose != self.purpose
            or self.scope_spec.replicate_commitment != self.replicate_commitment
            or self.scope_spec.arm != self.arm
            or self.scope_spec.scope_kind != "persistent-adaptation"
        ):
            raise V2InvariantError("V2 lineage acquisition scope differs")
        for value, label in (
            (self.allocation_ref, "V2 lineage allocation ref"),
            (self.bootstrap_episode_ref, "V2 lineage bootstrap episode ref"),
            (self.neutral_chain_ref, "V2 lineage neutral chain ref"),
            (self.genesis_competence_digest, "V2 lineage genesis digest"),
            (self.model_ref, "V2 lineage model ref"),
            (self.encoder_ref, "V2 lineage encoder ref"),
        ):
            _ref(value, label)
        if (
            type(self.neutral_episode_refs) is not tuple
            or len(self.neutral_episode_refs) != RECALL_SLOTS
            or len(set(self.neutral_episode_refs)) != RECALL_SLOTS
            or self.bootstrap_episode_ref in self.neutral_episode_refs
        ):
            raise V2InvariantError("V2 lineage neutral episode refs differ")
        for value in self.neutral_episode_refs:
            _ref(value, "V2 lineage neutral episode ref")
        if self.initial_hashes != _hash_pairs(
            dict(self.initial_hashes), "V2 lineage initial hashes"
        ):
            raise V2InvariantError("V2 lineage initial hashes differ")
        if type(self._mechanics) is not V2LineageMechanics:
            raise TypeError("V2 lineage mechanics differ")
        if (
            type(self.allocation) is not V2PersistentLineageAllocation
            or self.allocation.allocation_ref != self.allocation_ref
            or self.allocation.purpose != self.purpose
            or self.allocation.replicate_commitment != self.replicate_commitment
            or self.allocation.arm != self.arm
            or self.allocation.runtime_root != str(self.root)
            or self.allocation.cognee_scope_root != self.scope_spec.state_root
            or type(self.ledger) is not EvidenceLedger
            or self.ledger._closed
        ):
            raise V2IntegrityStop("V2 lineage immutable allocation binding differs")
        self.ledger.require_artifact(
            self.allocation_ref,
            "persistent-lineage-allocation",
            self.allocation.to_canonical(),
        )
        self._capture_bound_identities()

    def _capture_bound_identities(self) -> None:
        expected = {
            "root": self.root,
            "store": self.root / "cognitive.sqlite3",
            "journal": self.root / "qwen-execution-journal.sqlite3",
            "learner": self.root / "learner-state.bin",
        }
        if (
            getattr(self.paths, "root", None) != expected["root"]
            or getattr(self.paths, "store", None) != expected["store"]
            or getattr(self.paths, "journal", None) != expected["journal"]
            or getattr(self.paths, "learner", None) != expected["learner"]
            or getattr(self.store, "path", None) != expected["store"]
            or getattr(self.journal, "path", None) != expected["journal"]
        ):
            raise V2IntegrityStop("V2 lineage direct-child owner paths differ")
        identities: dict[str, tuple[str, int, int]] = {
            "root": _private_root_identity(expected["root"], "V2 lineage root"),
        }
        for name in ("store", "journal", "learner"):
            _require_owned_regular_file(
                expected[name], expected_mode=0o600, label=f"V2 lineage {name}"
            )
            metadata = os.lstat(expected[name])
            identities[name] = (
                str(expected[name]),
                int(metadata.st_dev),
                int(metadata.st_ino),
            )
        self._bound_identities = identities

    def _assert_binding(self) -> None:
        if (
            type(self.allocation) is not V2PersistentLineageAllocation
            or self.allocation.allocation_ref != self.allocation_ref
            or self.allocation.runtime_root != str(self.root)
            or self.allocation.cognee_scope_root != self.scope_spec.state_root
            or self.ledger._closed
        ):
            raise V2IntegrityStop("V2 lineage allocation binding changed")
        self.ledger.require_artifact(
            self.allocation_ref,
            "persistent-lineage-allocation",
            self.allocation.to_canonical(),
        )
        expected_paths = {
            "root": self.root,
            "store": self.root / "cognitive.sqlite3",
            "journal": self.root / "qwen-execution-journal.sqlite3",
            "learner": self.root / "learner-state.bin",
        }
        if (
            getattr(self.paths, "root", None) != expected_paths["root"]
            or getattr(self.paths, "store", None) != expected_paths["store"]
            or getattr(self.paths, "journal", None) != expected_paths["journal"]
            or getattr(self.paths, "learner", None) != expected_paths["learner"]
            or getattr(self.store, "path", None) != expected_paths["store"]
            or getattr(self.journal, "path", None) != expected_paths["journal"]
            or set(self._bound_identities) != set(expected_paths)
        ):
            raise V2IntegrityStop("V2 lineage owner path binding changed")
        for name, path in expected_paths.items():
            metadata = os.lstat(path)
            identity = (str(path), int(metadata.st_dev), int(metadata.st_ino))
            if identity != self._bound_identities[name]:
                raise V2IntegrityStop(f"V2 lineage {name} inode changed")

    @classmethod
    async def create_from_allocated_root(
        cls,
        root: str | Path,
        *,
        purpose: Purpose,
        replicate_commitment: str,
        arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
        genesis: object,
        manifest: object,
        scope_spec: V2AcquisitionScopeSpec,
        allocation: "V2PersistentLineageAllocation",
        ledger: EvidenceLedger,
        acquisition_opener: V2AcquisitionOpener,
        mechanics: V2LineageMechanics,
    ) -> "V2LineageOwner":
        target = Path(root)
        purpose = validate_purpose(purpose)
        replicate_commitment = _ref(
            replicate_commitment, "V2 lineage replicate commitment"
        )
        if arm not in STATEFUL_ARMS:
            raise ValueError("V2 lineage arm differs")
        if type(allocation) is not V2PersistentLineageAllocation or (
            allocation.purpose,
            allocation.replicate_commitment,
            allocation.arm,
            allocation.runtime_root,
            allocation.cognee_scope_root,
        ) != (
            purpose,
            replicate_commitment,
            arm,
            str(target),
            scope_spec.state_root,
        ):
            raise V2IntegrityStop("V2 lineage allocation capability differs")
        if type(ledger) is not EvidenceLedger or ledger._closed:
            raise TypeError("V2 lineage allocation ledger differs")
        ledger.require_artifact(
            allocation.allocation_ref,
            "persistent-lineage-allocation",
            allocation.to_canonical(),
        )
        if type(scope_spec) is not V2AcquisitionScopeSpec or (
            scope_spec.purpose,
            scope_spec.replicate_commitment,
            scope_spec.arm,
            scope_spec.scope_kind,
            scope_spec.task_id,
        ) != (
            purpose,
            replicate_commitment,
            arm,
            "persistent-adaptation",
            None,
        ):
            raise V2InvariantError("V2 lineage scope allocation differs")
        _require_owned_directory(
            target,
            expected_mode=0o700,
            empty=True,
            label="allocated V2 lineage root",
        )
        _require_absent(Path(scope_spec.state_root), "allocated V2 lineage Cognee scope")
        if type(mechanics) is not V2LineageMechanics:
            raise TypeError("V2 lineage mechanics differ")
        paths = mechanics.clone_paths_factory(
            root=target,
            store=target / "cognitive.sqlite3",
            journal=target / "qwen-execution-journal.sqlite3",
            learner=target / "learner-state.bin",
        )
        learner = mechanics.restore_genesis(genesis, prospective_lesion=False)
        snapshot = learner.capture_state()
        state_digest = _ref(
            learner.state_digest(), "V2 lineage genesis competence digest"
        )
        if (
            type(snapshot) is not bytes
            or not 1 <= len(snapshot) <= MAXIMUM_LINEAGE_SNAPSHOT_BYTES
            or state_digest != QUALIFIED_INITIAL_COMPETENCE_DIGEST
        ):
            raise V2IntegrityStop("V2 lineage learner genesis differs")
        model_ref = _ref(getattr(manifest, "model_ref", None), "V2 lineage model ref")
        encoder_ref = _ref(
            getattr(manifest, "encoder_ref", None), "V2 lineage encoder ref"
        )
        store = mechanics.transaction_store_factory(paths.store)
        store.initialize(
            state_digest,
            snapshot,
            model_ref=model_ref,
            encoder_ref=encoder_ref,
        )
        bootstrap = mechanics.bootstrap_episode_factory(state_digest, manifest)
        bootstrap_commit = store.commit_episode(
            bootstrap,
            snapshot,
            expected_parent_digest=state_digest,
        )
        bootstrap_episode_ref = _ref(
            getattr(bootstrap_commit, "episode_ref", None),
            "V2 lineage bootstrap episode ref",
        )
        if (
            getattr(bootstrap_commit, "sequence", None)
            != QUALIFIED_BOOTSTRAP_TRANSACTION_SEQUENCE
            or getattr(getattr(bootstrap_commit, "head", None), "sequence", None)
            != QUALIFIED_BOOTSTRAP_TRANSACTION_SEQUENCE
            or getattr(getattr(bootstrap_commit, "head", None), "state_digest", None)
            != state_digest
        ):
            raise V2IntegrityStop("V2 lineage bootstrap transaction differs")
        neutral_episodes = build_neutral_fixture_chain(
            bootstrap_episode_ref=bootstrap_episode_ref,
            competence_state_digest=state_digest,
            model_ref=model_ref,
            encoder_ref=encoder_ref,
        )
        neutral_payload = validate_neutral_fixture_chain(
            neutral_episodes,
            bootstrap_episode_ref=bootstrap_episode_ref,
            competence_state_digest=state_digest,
            model_ref=model_ref,
            encoder_ref=encoder_ref,
        )
        neutral_refs: list[str] = []
        for index, episode in enumerate(neutral_episodes):
            commit = store.commit_episode(
                episode,
                snapshot,
                expected_parent_digest=state_digest,
            )
            expected_sequence = QUALIFIED_BOOTSTRAP_TRANSACTION_SEQUENCE + index + 1
            if (
                getattr(commit, "sequence", None) != expected_sequence
                or getattr(getattr(commit, "head", None), "sequence", None)
                != expected_sequence
                or getattr(getattr(commit, "head", None), "state_digest", None)
                != state_digest
                or getattr(commit, "episode_ref", None) != episode.episode_ref
            ):
                raise V2IntegrityStop("V2 neutral fixture transaction differs")
            neutral_refs.append(episode.episode_ref)
        head = store.audit_integrity()
        if (
            getattr(head, "sequence", None) != QUALIFIED_NEUTRAL_TERMINAL_SEQUENCE
            or getattr(head, "episode_ref", None) != neutral_refs[-1]
            or getattr(head, "state_digest", None) != state_digest
            or store.load_head_state() != snapshot
        ):
            raise V2IntegrityStop("V2 neutral lineage terminal head differs")
        journal = mechanics.journal_factory(paths.journal)
        journal.audit_integrity()
        os.chmod(paths.store, 0o600)
        os.chmod(paths.journal, 0o600)
        _write_private_bytes_create_once(
            paths.learner,
            snapshot,
            maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
        )
        _fsync_directory(target)
        session = await _open_v2_acquisition_session(
            scope_spec,
            opener=acquisition_opener,
        )
        primary: V2IntegrityStop | None = None
        try:
            memory = mechanics.memory_factory(source=store, backend=session.backend)
            await _maybe_await(memory.rebuild(limit=MAXIMUM_PROJECTION_RETRY))
            await _maybe_await(
                memory.retry_pending_projections(limit=MAXIMUM_PROJECTION_RETRY)
            )
            memory.assert_synchronized(store.acquisition_head())
            if store.pending_acquisition_projections(limit=1):
                raise V2IntegrityStop("V2 neutral lineage projection outbox remains")
        except BaseException as error:
            primary = _redacted_failure(error, "V2_LINEAGE_PROJECTION_FAILED")
        cleanup: V2IntegrityStop | None = None
        try:
            if primary is None:
                await session.forget_close_and_remove()
            else:
                await session.close_preserving_state()
        except BaseException as error:
            cleanup = _redacted_failure(
                error,
                (
                    "V2_LINEAGE_SCOPE_CLEANUP_FAILED"
                    if primary is None
                    else "V2_LINEAGE_FAILURE_WORKER_CLOSE_FAILED"
                ),
            )
        memory = None
        session = None
        if primary is not None and cleanup is not None:
            raise ExceptionGroup(
                "V2 lineage projection and cleanup failed", [primary, cleanup]
            ) from None
        if primary is not None:
            raise primary from None
        if cleanup is not None:
            raise cleanup from None
        mechanics.assert_quiescent(
            learner=learner,
            store=store,
            journal=journal,
        )
        hashes = dict(
            mechanics.closed_hashes(
                paths,
                store=store,
                journal=journal,
            )
        )
        return cls(
            purpose=purpose,
            replicate_commitment=replicate_commitment,
            arm=arm,
            root=target,
            paths=paths,
            learner=learner,
            store=store,
            journal=journal,
            scope_spec=scope_spec,
            allocation_ref=allocation.allocation_ref,
            allocation=allocation,
            ledger=ledger,
            bootstrap_episode_ref=bootstrap_episode_ref,
            neutral_episode_refs=tuple(neutral_refs),
            neutral_chain_ref=_ref(
                neutral_payload["chain_ref"], "V2 neutral chain ref"
            ),
            genesis_competence_digest=state_digest,
            model_ref=model_ref,
            encoder_ref=encoder_ref,
            initial_hashes=_hash_pairs(hashes, "V2 lineage initial hashes"),
            _mechanics=mechanics,
        )

    def hashes(self) -> dict[str, str]:
        self._assert_binding()
        return dict(
            self._mechanics.closed_hashes(
                self.paths,
                store=self.store,
                journal=self.journal,
            )
        )

    def persist_quiescent(self, *, cycle: object | None = None) -> None:
        if self._seal is not None:
            raise V2IntegrityStop("frozen V2 lineage cannot persist again")
        self._assert_binding()
        self._mechanics.assert_quiescent(
            learner=self.learner,
            store=self.store,
            journal=self.journal,
            cycle=cycle,
        )
        snapshot = self.learner.capture_state()
        head = self.store.audit_integrity()
        if (
            type(snapshot) is not bytes
            or not 1 <= len(snapshot) <= MAXIMUM_LINEAGE_SNAPSHOT_BYTES
            or getattr(head, "state_digest", None) != self.learner.state_digest()
            or self.store.load_head_state() != snapshot
            or self.store.pending_acquisition_projections(limit=1)
        ):
            raise V2IntegrityStop("V2 lineage state is not persistable")
        self.journal.audit_integrity()
        _replace_private_bytes_durable(
            self.paths.learner,
            snapshot,
            maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
        )
        metadata = os.lstat(self.paths.learner)
        self._bound_identities["learner"] = (
            str(self.paths.learner),
            int(metadata.st_dev),
            int(metadata.st_ino),
        )
        self._assert_binding()

    def persist_and_seal(self, *, cycle: object | None = None) -> BaselineSeal:
        if self._seal is not None:
            if cycle is not None or self.hashes() != dict(self._seal.hashes):
                raise V2IntegrityStop("sealed V2 lineage changed")
            return self._seal
        self.persist_quiescent(cycle=cycle)
        hashes = _hash_pairs(self.hashes(), "V2 lineage sealed hashes")
        self._seal = BaselineSeal(
            purpose=self.purpose,
            replicate_commitment=self.replicate_commitment,
            arm=self.arm,
            root=str(self.root),
            hashes=hashes,
            neutral_episode_refs=self.neutral_episode_refs,
            neutral_chain_ref=self.neutral_chain_ref,
            bootstrap_episode_ref=self.bootstrap_episode_ref,
            genesis_competence_digest=self.genesis_competence_digest,
            model_ref=self.model_ref,
            encoder_ref=self.encoder_ref,
            quiescent=True,
        )
        return self._seal

    def verify_seal(self) -> BaselineSeal:
        if self._seal is None:
            raise V2IntegrityStop("V2 lineage has not been frozen")
        self._assert_binding()
        self._mechanics.assert_quiescent(
            learner=self.learner,
            store=self.store,
            journal=self.journal,
        )
        if self.hashes() != dict(self._seal.hashes):
            raise V2IntegrityStop("frozen V2 lineage bytes changed")
        return self._seal


@dataclass(frozen=True, slots=True)
class V2PersistentLineageAllocation:
    """Ledger-first path commitment for one persistent adaptation lineage."""

    purpose: Purpose
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    runtime_root: str
    cognee_scope_root: str
    injected_paths: bool = field(default=False, repr=False)

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        _ref(self.replicate_commitment, "persistent allocation replicate")
        if self.arm not in STATEFUL_ARMS:
            raise ValueError("persistent allocation arm differs")
        if type(self.injected_paths) is not bool:
            raise TypeError("persistent allocation injection flag differs")
        runtime = Path(self.runtime_root)
        scope = Path(self.cognee_scope_root)
        if (
            not runtime.is_absolute()
            or not scope.is_absolute()
            or str(runtime) != self.runtime_root
            or str(scope) != self.cognee_scope_root
            or "." in runtime.parts
            or ".." in runtime.parts
            or "." in scope.parts
            or ".." in scope.parts
            or runtime == scope
        ):
            raise V2InvariantError("persistent allocation paths differ")
        safe_component(runtime.name, "persistent runtime allocation name")
        safe_component(scope.name, "persistent Cognee allocation name")
        if not self.injected_paths and (
            runtime.parent != STATE_ROOT / f"{purpose}-v1" / "arm-runtime"
            or scope.parent != STATE_ROOT / f"{purpose}-v1" / "cognee-scopes"
        ):
            raise V2InvariantError("persistent allocation escapes literal parents")

    @property
    def allocation_ref(self) -> str:
        return canonical_ref("persistent-lineage-allocation", self.to_canonical())

    def to_canonical(self) -> dict[str, object]:
        return {
            "arm": self.arm,
            "cognee_scope_root": self.cognee_scope_root,
            "path_boundary": "INJECTED_TEST_ONLY" if self.injected_paths else "LITERAL",
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": self.purpose,
            "replicate_commitment": self.replicate_commitment,
            "runtime_root": self.runtime_root,
        }


def _v2_lineage_slug(
    purpose: Purpose,
    replicate_commitment: str,
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
) -> str:
    purpose = validate_purpose(purpose)
    replicate_commitment = _ref(
        replicate_commitment, "V2 lineage slug replicate commitment"
    )
    if arm not in STATEFUL_ARMS:
        raise ValueError("V2 lineage slug arm differs")
    digest = canonical_ref(
        "persistent-lineage-path",
        {
            "arm": arm,
            "protocol_identity": PROTOCOL_IDENTITY,
            "purpose": purpose,
            "replicate_commitment": replicate_commitment,
        },
    ).removeprefix("sha256:")[:24]
    return f"lineage-{digest}"


def _bounded_acquisition_inventory(store: object) -> tuple[object, ...]:
    head = store.acquisition_head()
    next_ordinal = _integer(
        getattr(head, "next_ordinal", None),
        "V2 acquisition inventory head",
        minimum=1,
        maximum=256,
    )
    rows: list[object] = []
    after = -1
    while len(rows) < next_ordinal:
        page = tuple(store.acquisition_items(after_ordinal=after, limit=64))
        if not page or len(page) > 64:
            raise V2IntegrityStop("V2 acquisition inventory page differs")
        for item in page:
            ordinal = getattr(item, "ordinal", None)
            if type(ordinal) is not int or ordinal != len(rows):
                raise V2IntegrityStop("V2 acquisition inventory is not contiguous")
            rows.append(item)
            after = ordinal
        if len(page) < 64:
            break
    if len(rows) != next_ordinal:
        raise V2IntegrityStop("V2 acquisition inventory does not reach its head")
    return tuple(rows)


def _neutral_reference_hits(
    store: object,
    neutral_episode_refs: Sequence[str],
) -> tuple[object, ...]:
    """Resolve the exact legacy-episode allowlist to derived memory-record hits."""

    from angler.memory.cognitive_acquisition import (
        LEGACY_COGNITIVE_EPISODE_CONTRACT,
    )
    from angler.memory.cognitive_acquisition_graph import AcquisitionReferenceHit

    sources = tuple(neutral_episode_refs)
    if (
        len(sources) != RECALL_SLOTS
        or len(set(sources)) != RECALL_SLOTS
    ):
        raise V2InvariantError("neutral source allowlist differs")
    for value in sources:
        _ref(value, "neutral source episode ref")
    by_source: dict[str, str] = {}
    for item in _bounded_acquisition_inventory(store):
        acquisition = getattr(item, "acquisition", None)
        source_ref = getattr(acquisition, "source_ref", None)
        source_contract = getattr(acquisition, "source_contract", None)
        record_ref = getattr(item, "record_ref", None)
        if source_contract != LEGACY_COGNITIVE_EPISODE_CONTRACT:
            continue
        if source_ref in sources:
            if source_ref in by_source:
                raise V2IntegrityStop("neutral source joins multiple records")
            by_source[source_ref] = _ref(
                record_ref, "neutral derived memory-record ref"
            )
    if set(by_source) != set(sources):
        raise V2IntegrityStop("neutral source allowlist is not fully acquired")
    return tuple(
        AcquisitionReferenceHit(record_ref=by_source[source_ref])
        for source_ref in sources
    )


def _validated_reference_hits(
    hits: Sequence[object],
    *,
    label: str,
) -> tuple[object, ...]:
    from angler.memory.cognitive_acquisition_graph import AcquisitionReferenceHit

    rows = tuple(hits)
    if (
        len(rows) != RECALL_SLOTS
        or any(type(item) is not AcquisitionReferenceHit for item in rows)
        or len({item.record_ref for item in rows}) != RECALL_SLOTS
    ):
        raise V2IntegrityStop(f"{label} reference-hit population differs")
    return rows


async def _bounded_ordinary_recall(
    *,
    query: str,
    store: object,
    backend: object,
    memory: object,
    frozen_origin: bool,
    label: str,
) -> tuple[tuple[object, ...], object]:
    """Return the first 12 policy-eligible hits after a full canonical rejoin.

    A prospective batch is intentionally learner-visible reference material but
    remains PROPOSED/COUNTERFACTUAL until its separate resolution is acquired.
    Searching only 12 backend rows can therefore yield 11 ordinary memories.
    Search the complete bounded acquisition population, prove every returned
    reference and adjacency against canonical state first, and only then apply
    the ordinary OBSERVED/VALIDATED presentation policy.
    """

    from angler.cognition.contracts import (
        CognitiveMemoryKind,
        EpistemicStatus,
    )
    from angler.memory.cognitive_acquisition import (
        PROSPECTIVE_DYNAMICS_BATCH_CONTRACT,
    )
    from angler.memory.cognitive_acquisition_graph import (
        AcquisitionRecallBatch,
        AcquisitionReferenceHit,
    )

    query = _text(query, f"{label} query", 16_384)
    inventory = _bounded_acquisition_inventory(store)
    if getattr(memory, "source", None) is not store or getattr(
        memory, "backend", None
    ) is not backend:
        raise V2IntegrityStop(f"{label} canonical memory binding differs")
    resolver = getattr(memory, "_resolve_record", None)
    neighbor_refs = getattr(memory, "_canonical_neighbor_refs", None)
    if not callable(resolver) or not callable(neighbor_refs):
        raise V2IntegrityStop(f"{label} canonical rejoin capability differs")
    memory.assert_synchronized(store.acquisition_head())

    inventory_by_record: dict[str, object] = {}
    for item in inventory:
        _ref(
            getattr(item, "acquisition_ref", None),
            f"{label} inventory acquisition ref",
        )
        record_ref = _ref(
            getattr(item, "record_ref", None),
            f"{label} inventory record ref",
        )
        if record_ref in inventory_by_record:
            raise V2IntegrityStop(f"{label} canonical inventory repeats a record")
        inventory_by_record[record_ref] = item

    rows = tuple(
        await _maybe_await(backend.search(query, limit=len(inventory)))
    )
    if (
        len(rows) != len(inventory)
        or any(type(hit) is not AcquisitionReferenceHit for hit in rows)
        or len({hit.record_ref for hit in rows}) != len(inventory)
        or {hit.record_ref for hit in rows} != set(inventory_by_record)
    ):
        raise V2IntegrityStop(f"{label} full reference-hit population differs")
    previous_score: float | None = None
    for hit in rows:
        score = hit.score
        if (
            type(score) not in (int, float)
            or not math.isfinite(float(score))
            or (previous_score is not None and float(score) < previous_score)
        ):
            raise V2IntegrityStop(f"{label} lower-is-better score order differs")
        previous_score = float(score)

    # This broader status set is used only to prove canonical identity,
    # temporal binding, and adjacency.  It does not make PROPOSED material
    # eligible for ordinary presentation.
    integrity_statuses = frozenset(EpistemicStatus)
    integrity_visibilities = frozenset(
        getattr(getattr(item, "acquisition", None), "record", None).visibility
        for item in inventory
    )
    resolved_by_record: dict[str, tuple[object, object]] = {}
    expected_denied: list[str] = []
    for hit in rows:
        resolved = resolver(
            hit.record_ref,
            allowed_visibility=integrity_visibilities,
            admitted_epistemic_statuses=integrity_statuses,
        )
        if not isinstance(resolved, tuple) or len(resolved) != 2:
            raise V2IntegrityStop(f"{label} primary canonical rejoin failed")
        record, acquisition = resolved
        item = inventory_by_record[hit.record_ref]
        if (
            getattr(item, "acquisition", None) != acquisition
            or getattr(item, "acquisition_ref", None)
            != getattr(acquisition, "acquisition_ref", None)
            or getattr(item, "record_ref", None)
            != getattr(record, "record_ref", None)
        ):
            raise V2IntegrityStop(f"{label} inventory canonical rejoin differs")

        canonical_neighbors = frozenset(neighbor_refs(record))
        if hit.adjacent_record_refs != tuple(sorted(canonical_neighbors)):
            raise V2IntegrityStop(f"{label} exact canonical adjacency differs")
        generic_relation_refs = frozenset(
            relation.target_ref for relation in record.relations
        )
        dedicated_record_refs = frozenset(
            {*record.supersedes_refs, *record.tombstone_refs}
        )
        for adjacent_ref in hit.adjacent_record_refs:
            adjacent = resolver(
                adjacent_ref,
                allowed_visibility=integrity_visibilities,
                admitted_epistemic_statuses=integrity_statuses,
                allow_missing_external_relation=(
                    adjacent_ref in generic_relation_refs
                    and adjacent_ref not in dedicated_record_refs
                ),
            )
            if isinstance(adjacent, str):
                raise V2IntegrityStop(f"{label} adjacent canonical rejoin failed")
            if adjacent is None and (
                adjacent_ref not in generic_relation_refs
                or adjacent_ref in dedicated_record_refs
            ):
                raise V2IntegrityStop(f"{label} adjacent canonical rejoin differs")

        if record.epistemic_status is EpistemicStatus.PROPOSED:
            if (
                acquisition.source_contract
                != PROSPECTIVE_DYNAMICS_BATCH_CONTRACT
                or record.kind is not CognitiveMemoryKind.COUNTERFACTUAL
                or record.visibility != "LEARNER_VISIBLE"
            ):
                raise V2IntegrityStop(f"{label} proposed policy exclusion differs")
            expected_denied.append(hit.record_ref)
        elif (
            record.epistemic_status
            not in (EpistemicStatus.OBSERVED, EpistemicStatus.VALIDATED)
            or record.visibility != "LEARNER_VISIBLE"
        ):
            raise V2IntegrityStop(f"{label} ordinary eligibility differs")
        resolved_by_record[hit.record_ref] = (record, acquisition)

    batch = memory.recall_from_hits(
        rows,
        limit=len(inventory),
        frozen_origin=frozen_origin,
    )
    if type(batch) is not AcquisitionRecallBatch or batch.rejected != (
        "REFERENCE_EPISTEMIC_STATUS_DENIED",
    ) * len(expected_denied):
        raise V2IntegrityStop(f"{label} ordinary policy rejection differs")
    denied_refs = frozenset(expected_denied)
    eligible_hits = tuple(hit for hit in rows if hit.record_ref not in denied_refs)
    if tuple(item.record_ref for item in batch.items) != tuple(
        hit.record_ref for hit in eligible_hits
    ):
        raise V2IntegrityStop(f"{label} ordinary ranked rejoin differs")
    if len(eligible_hits) < RECALL_SLOTS:
        raise V2IntegrityStop(f"{label} has fewer than 12 eligible memories")
    for item in batch.items:
        record, acquisition = resolved_by_record[item.record_ref]
        if (
            item.record != record
            or item.acquisition_ref != acquisition.acquisition_ref
            or item.source_contract != acquisition.source_contract
            or item.source_ref != acquisition.source_ref
            or item.epistemic_status
            not in (EpistemicStatus.OBSERVED.value, EpistemicStatus.VALIDATED.value)
            or item.visibility != "LEARNER_VISIBLE"
        ):
            raise V2IntegrityStop(f"{label} ordinary presentation differs")

    final_inventory = _bounded_acquisition_inventory(store)
    if final_inventory != inventory:
        raise V2IntegrityStop(f"{label} canonical inventory changed during recall")
    memory.assert_synchronized(store.acquisition_head())
    return (
        eligible_hits[:RECALL_SLOTS],
        AcquisitionRecallBatch(
            items=batch.items[:RECALL_SLOTS],
            rejected=(),
        ),
    )


def _close_unfrozen_lineage_owner_preserving_state(
    owner: V2LineageOwner,
) -> None:
    """Prove one construction-only owner quiescent, then sever its handles."""

    if type(owner) is not V2LineageOwner or owner._seal is not None:
        raise V2IntegrityStop("unfrozen lineage cleanup owner differs")
    owner._assert_binding()
    owner._mechanics.assert_quiescent(
        learner=owner.learner,
        store=owner.store,
        journal=owner.journal,
    )
    if (
        _hash_pairs(owner.hashes(), "unfrozen lineage cleanup hashes")
        != owner.initial_hashes
    ):
        raise V2IntegrityStop("unfrozen lineage changed before cleanup")
    try:
        os.lstat(owner.scope_spec.state_root)
    except FileNotFoundError:
        pass
    else:
        raise V2IntegrityStop("unfrozen lineage Cognee scope remains")
    _detach_unfrozen_lineage_owner(owner)


def _detach_unfrozen_lineage_owner(owner: V2LineageOwner) -> None:
    """Sever one already-validated unfrozen lineage without disposal claims."""

    owner.paths = None
    owner.learner = None
    owner.store = None
    owner.journal = None
    owner.ledger = None
    owner._bound_identities.clear()


def _failed_scope_parent_inventory(
    parent: Path,
    *,
    maximum_entries: int,
) -> tuple[tuple[str, int, int], ...]:
    """Capture one bounded, fd-relative, no-follow direct-child inventory."""

    limit = _integer(
        maximum_entries,
        "failed scope parent entry ceiling",
        minimum=0,
        maximum=MAXIMUM_RETAINED_SCOPE_ENTRIES,
    )
    identity = _private_root_identity(parent, "failed scope parent")
    if identity[0] != str(parent) or stat.S_IMODE(os.lstat(parent).st_mode) != 0o700:
        raise V2IntegrityStop("failed scope parent identity differs")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    try:
        descriptor = os.open(parent, flags)
    except OSError as error:
        raise V2IntegrityStop("failed scope parent changed") from error

    def metadata_row(value: os.stat_result) -> tuple[int, ...]:
        return (
            int(value.st_dev),
            int(value.st_ino),
            int(value.st_mode),
            int(value.st_uid),
            int(value.st_gid),
            int(value.st_nlink),
            int(value.st_size),
            int(value.st_mtime_ns),
            int(value.st_ctime_ns),
        )

    try:
        parent_before = os.fstat(descriptor)
        if (
            metadata_row(parent_before) != metadata_row(os.lstat(parent))
            or (int(parent_before.st_dev), int(parent_before.st_ino))
            != identity[1:]
        ):
            raise V2IntegrityStop("failed scope parent changed before inventory")
        rows: list[tuple[str, int, int]] = []
        seen: set[tuple[int, int]] = set()
        try:
            with os.scandir(descriptor) as iterator:
                for entry in iterator:
                    if len(rows) >= limit:
                        raise V2IntegrityStop(
                            "failed lineage scope inventory exceeds its bound"
                        )
                    name = entry.name
                    try:
                        encoded = name.encode("utf-8")
                    except (AttributeError, UnicodeEncodeError) as error:
                        raise V2IntegrityStop(
                            "failed lineage scope child name differs"
                        ) from error
                    if (
                        type(name) is not str
                        or name in ("", ".", "..")
                        or "/" in name
                        or name != unicodedata.normalize("NFC", name)
                        or not 1 <= len(encoded) <= 255
                    ):
                        raise V2IntegrityStop(
                            "failed lineage scope child name differs"
                        )
                    before = entry.stat(follow_symlinks=False)
                    if (
                        not stat.S_ISDIR(before.st_mode)
                        or stat.S_ISLNK(before.st_mode)
                        or stat.S_IMODE(before.st_mode) != 0o700
                        or (before.st_uid, before.st_gid)
                        != (os.geteuid(), os.getegid())
                        or int(before.st_dev) != identity[1]
                    ):
                        raise V2IntegrityStop(
                            "failed lineage scope inventory contains an alias"
                        )
                    child_fd = os.open(name, flags, dir_fd=descriptor)
                    try:
                        opened = os.fstat(child_fd)
                        current = os.stat(
                            name, dir_fd=descriptor, follow_symlinks=False
                        )
                        if (
                            metadata_row(before) != metadata_row(opened)
                            or metadata_row(opened) != metadata_row(current)
                            or not stat.S_ISDIR(opened.st_mode)
                        ):
                            raise V2IntegrityStop(
                                "failed lineage scope child changed"
                            )
                        child_identity = (
                            int(opened.st_dev),
                            int(opened.st_ino),
                        )
                        if child_identity in seen:
                            raise V2IntegrityStop(
                                "failed lineage scope children alias"
                            )
                        seen.add(child_identity)
                        rows.append((name, *child_identity))
                    finally:
                        os.close(child_fd)
        except OSError as error:
            raise V2IntegrityStop(
                "failed scope parent inventory changed"
            ) from error
        parent_after = os.fstat(descriptor)
        if (
            metadata_row(parent_before) != metadata_row(parent_after)
            or metadata_row(parent_after) != metadata_row(os.lstat(parent))
        ):
            raise V2IntegrityStop("failed scope parent changed during inventory")
        return tuple(sorted(rows, key=lambda row: os.fsencode(row[0])))
    finally:
        os.close(descriptor)


def _validate_failed_lineage_owner_preserving_state(
    owner: V2LineageOwner,
    retained_scope: RetainedPreparationScopeEvidence | None,
) -> None:
    """Prove a partial-run lineage quiescent and its surviving scope owned."""

    if type(owner) is not V2LineageOwner or owner._seal is not None:
        raise V2IntegrityStop("failed lineage preservation owner differs")
    owner._assert_binding()
    lineage_identity, current_hashes, lineage_tree = (
        _raw_retained_lineage_state(owner)
    )
    if retained_scope is None:
        try:
            os.lstat(owner.scope_spec.state_root)
        except FileNotFoundError:
            return
        raise V2IntegrityStop("failed lineage has an unowned Cognee scope")
    if (
        type(retained_scope) is not RetainedPreparationScopeEvidence
        or retained_scope.purpose != owner.purpose
        or retained_scope.replicate_commitment != owner.replicate_commitment
        or retained_scope.arm != owner.arm
        or retained_scope.allocation_ref != owner.allocation_ref
        or retained_scope.scope_ref != owner.scope_spec.scope_ref
        or retained_scope.state_root != owner.scope_spec.state_root
        or retained_scope.lineage_root != str(owner.root)
        or (
            retained_scope.lineage_root_device,
            retained_scope.lineage_root_inode,
        )
        != lineage_identity[1:]
        or retained_scope.lineage_hashes != current_hashes
        or retained_scope.lineage_tree != lineage_tree
    ):
        raise V2IntegrityStop("retained preparation scope/lineage binding differs")
    identity = _private_root_identity(
        retained_scope.state_root, "retained failed lineage scope"
    )
    if identity != (
        retained_scope.state_root,
        retained_scope.root_device,
        retained_scope.root_inode,
    ) or _terminal_scope_tree_snapshot(
        retained_scope.state_root
    ) != retained_scope.scope_tree:
        raise V2IntegrityStop("retained failed lineage scope identity changed")
    owner.ledger.require_artifact(
        retained_scope.evidence_ref,
        "retained-preparation-scope",
        retained_scope.to_canonical(),
    )


@dataclass(slots=True)
class V2LineageSetOwner:
    """Own every persistent IN/IO lineage for one qualification or evaluation."""

    purpose: Purpose
    replicate_commitments: tuple[str, ...]
    owners: tuple[V2LineageOwner, ...]
    arm_runtime_parent: Path
    cognee_scope_parent: Path
    _closed: bool = field(default=False, init=False, repr=False)
    _failed_frozen_close_ref: str | None = field(
        default=None, init=False, repr=False
    )

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        expected_replicates = 1 if purpose == "qualification" else 3
        if (
            type(self.replicate_commitments) is not tuple
            or len(self.replicate_commitments) != expected_replicates
            or len(set(self.replicate_commitments)) != expected_replicates
        ):
            raise V2InvariantError("V2 lineage-set replicate inventory differs")
        for value in self.replicate_commitments:
            _ref(value, "V2 lineage-set replicate commitment")
        if (
            type(self.owners) is not tuple
            or len(self.owners) != 2 * expected_replicates
            or any(type(item) is not V2LineageOwner for item in self.owners)
        ):
            raise V2InvariantError("V2 lineage-set owner inventory differs")
        keys = {(item.replicate_commitment, item.arm) for item in self.owners}
        if keys != {
            (replicate, arm)
            for replicate in self.replicate_commitments
            for arm in STATEFUL_ARMS
        }:
            raise V2InvariantError("V2 lineage-set key inventory differs")
        if any(item.purpose != purpose for item in self.owners):
            raise V2InvariantError("V2 lineage-set purpose differs")
        identities = tuple(
            _private_root_identity(item.root, "V2 lineage-set root")
            for item in self.owners
        )
        if (
            len({item[0] for item in identities}) != len(identities)
            or len({item[1:] for item in identities}) != len(identities)
        ):
            raise V2IntegrityStop("V2 lineage-set roots alias")
        foundations = {
            (
                item.bootstrap_episode_ref,
                item.neutral_episode_refs,
                item.neutral_chain_ref,
                item.genesis_competence_digest,
                item.model_ref,
                item.encoder_ref,
                item.initial_hashes,
            )
            for item in self.owners
        }
        if len(foundations) != 1:
            raise V2IntegrityStop("V2 persistent lineages do not share exact genesis")
        for parent, label in (
            (self.arm_runtime_parent, "V2 arm runtime parent"),
            (self.cognee_scope_parent, "V2 Cognee scope parent"),
        ):
            _require_owned_directory(parent, expected_mode=0o700, label=label)
        if next(self.cognee_scope_parent.iterdir(), None) is not None:
            raise V2IntegrityStop("V2 persistent Cognee scopes remain after genesis")

    @classmethod
    async def create_from_phase_parents(
        cls,
        *,
        purpose: Purpose,
        replicate_commitments: Sequence[str],
        arm_runtime_parent: str | Path,
        cognee_scope_parent: str | Path,
        genesis: object,
        manifest: object,
        ledger: EvidenceLedger,
        acquisition_opener: V2AcquisitionOpener,
        mechanics: V2LineageMechanics,
        injected_paths: bool = False,
    ) -> "V2LineageSetOwner":
        purpose = validate_purpose(purpose)
        replicates = tuple(replicate_commitments)
        expected_replicates = 1 if purpose == "qualification" else 3
        if (
            len(replicates) != expected_replicates
            or len(set(replicates)) != expected_replicates
        ):
            raise V2InvariantError("V2 lineage construction replicates differ")
        for value in replicates:
            _ref(value, "V2 lineage construction replicate")
        if type(ledger) is not EvidenceLedger or ledger._closed:
            raise TypeError("V2 lineage construction ledger differs")
        if type(mechanics) is not V2LineageMechanics:
            raise TypeError("V2 lineage construction mechanics differ")
        if type(injected_paths) is not bool:
            raise TypeError("V2 lineage construction injection flag differs")
        runtime_parent = Path(arm_runtime_parent)
        scope_parent = Path(cognee_scope_parent)
        for parent, label in (
            (runtime_parent, "V2 lineage construction runtime parent"),
            (scope_parent, "V2 lineage construction scope parent"),
        ):
            _require_owned_directory(
                parent,
                expected_mode=0o700,
                empty=True,
                label=label,
            )
        if not injected_paths and (
            runtime_parent != STATE_ROOT / f"{purpose}-v1" / "arm-runtime"
            or scope_parent != STATE_ROOT / f"{purpose}-v1" / "cognee-scopes"
        ):
            raise V2InvariantError("V2 live lineage parents differ")
        owners: list[V2LineageOwner] = []
        try:
            for replicate in replicates:
                for arm in (
                    "IN_FULL_NEUTRAL_12",
                    "IO_FULL_ORDINARY_12",
                ):
                    slug = _v2_lineage_slug(purpose, replicate, arm)
                    scope_spec = V2AcquisitionScopeSpec.create(
                        purpose=purpose,
                        replicate_commitment=replicate,
                        arm=arm,
                        scope_kind="persistent-adaptation",
                        state_parent=scope_parent,
                    )
                    allocation = V2PersistentLineageAllocation(
                        purpose=purpose,
                        replicate_commitment=replicate,
                        arm=arm,
                        runtime_root=str(runtime_parent / slug),
                        cognee_scope_root=scope_spec.state_root,
                        injected_paths=injected_paths,
                    )
                    ledger.append_artifact_durable(
                        allocation.allocation_ref,
                        "persistent-lineage-allocation",
                        allocation.to_canonical(),
                    )
                    root = _create_private_directory_once(runtime_parent / slug)
                    owner = await V2LineageOwner.create_from_allocated_root(
                        root,
                        purpose=purpose,
                        replicate_commitment=replicate,
                        arm=arm,
                        genesis=genesis,
                        manifest=manifest,
                        scope_spec=scope_spec,
                        allocation=allocation,
                        ledger=ledger,
                        acquisition_opener=acquisition_opener,
                        mechanics=mechanics,
                    )
                    owners.append(owner)
            return cls(
                purpose=purpose,
                replicate_commitments=replicates,
                owners=tuple(owners),
                arm_runtime_parent=runtime_parent,
                cognee_scope_parent=scope_parent,
            )
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_LINEAGE_SET_CONSTRUCTION_FAILED"
            )
            failures: list[V2IntegrityStop] = []
            for owner in reversed(owners):
                try:
                    _close_unfrozen_lineage_owner_preserving_state(owner)
                except BaseException as close_error:
                    failures.append(
                        _redacted_failure(
                            close_error,
                            "V2_PARTIAL_LINEAGE_OWNER_CLOSE_FAILED",
                        )
                    )
            try:
                await _drain_unresolved_v2_cognee_workers()
                _assert_no_unresolved_v2_cognee_workers()
            except BaseException as close_error:
                failures.append(
                    _redacted_failure(
                        close_error,
                        "V2_PARTIAL_LINEAGE_WORKER_DRAIN_FAILED",
                    )
                )
            if failures:
                raise ExceptionGroup(
                    "V2 lineage-set construction and cleanup failed",
                    [primary, *failures],
                ) from None
            raise primary from None

    def owner_for(
        self,
        replicate_commitment: str,
        arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
    ) -> V2LineageOwner:
        if self._closed:
            raise V2IntegrityStop("V2 lineage set is closed")
        replicate_commitment = _ref(
            replicate_commitment, "V2 lineage lookup replicate"
        )
        if arm not in STATEFUL_ARMS:
            raise ValueError("V2 lineage lookup arm differs")
        rows = tuple(
            item
            for item in self.owners
            if item.replicate_commitment == replicate_commitment and item.arm == arm
        )
        if len(rows) != 1:
            raise V2IntegrityStop("V2 lineage lookup is not unique")
        return rows[0]

    def freeze(self, adaptation_attempts: Sequence[AttemptFinal]) -> FrozenAdaptationState:
        if self._closed:
            raise V2IntegrityStop("V2 lineage set is closed")
        attempts = tuple(adaptation_attempts)
        if any(type(item) is not AttemptFinal for item in attempts):
            raise TypeError("V2 adaptation freeze attempts differ")
        expected_attempts = 48 if self.purpose == "qualification" else 270
        if len(attempts) != expected_attempts:
            raise V2InvariantError("V2 adaptation freeze attempt count differs")
        seals = tuple(item.persist_and_seal() for item in self.owners)
        catalogs: list[DonorCatalog] = []
        for replicate in self.replicate_commitments:
            io_owner = self.owner_for(replicate, "IO_FULL_ORDINARY_12")
            admitted = tuple(
                item
                for item in attempts
                if item.stage.replicate_commitment == replicate
                and item.stage.arm == "IO_FULL_ORDINARY_12"
                and item.observation.proposal_admitted
            )
            acquisition_items = _bounded_acquisition_inventory(io_owner.store)
            catalogs.append(
                build_donor_catalog(
                    acquisition_items,
                    admitted,
                    replicate_commitment=replicate,
                    expected_next_ordinal=len(acquisition_items),
                )
            )
        if next(self.cognee_scope_parent.iterdir(), None) is not None:
            raise V2IntegrityStop("V2 Cognee scopes remain at adaptation freeze")
        return FrozenAdaptationState(
            purpose=self.purpose,
            baseline_seals=seals,
            donor_catalogs=tuple(catalogs),
        )

    def verify_frozen(self, frozen: FrozenAdaptationState) -> str:
        if self._closed or type(frozen) is not FrozenAdaptationState:
            raise V2IntegrityStop("V2 frozen lineage owner differs")
        if frozen.purpose != self.purpose:
            raise V2IntegrityStop("V2 frozen lineage purpose differs")
        observed = tuple(item.verify_seal() for item in self.owners)
        if {item.seal_ref for item in observed} != {
            item.seal_ref for item in frozen.baseline_seals
        }:
            raise V2IntegrityStop("V2 frozen lineage seals differ")
        if next(self.cognee_scope_parent.iterdir(), None) is not None:
            raise V2IntegrityStop("V2 Cognee scope parent is not empty")
        return frozen.freeze_ref

    def close_frozen_failed_preserving_disposable_state(
        self,
        frozen: FrozenAdaptationState,
        retained_allocations: Sequence[RetainedDisposableAllocationEvidence],
    ) -> None:
        """Detach frozen lineages only around an exact evidenced survivor set."""

        if type(frozen) is not FrozenAdaptationState:
            raise V2IntegrityStop("V2 frozen failed-run lineage owner differs")
        rows = tuple(retained_allocations)
        if not rows or any(
            type(item) is not RetainedDisposableAllocationEvidence for item in rows
        ):
            raise TypeError("retained disposable allocation inventory differs")
        by_allocation = {item.allocation_ref: item for item in rows}
        if len(by_allocation) != len(rows):
            raise V2IntegrityStop("retained disposable allocation identity repeats")
        close_ref = canonical_ref(
            "frozen-failed-lineage-close",
            {
                "freeze_ref": frozen.freeze_ref,
                "retained_disposable_evidence_refs": sorted(
                    item.evidence_ref for item in rows
                ),
            },
        )
        if self._closed:
            if self._failed_frozen_close_ref == close_ref:
                return
            raise V2IntegrityStop("V2 frozen failed-run close identity differs")
        if frozen.purpose != self.purpose or any(
            item.purpose != self.purpose for item in rows
        ):
            raise V2IntegrityStop("retained disposable purpose differs")

        observed_seals = tuple(item.verify_seal() for item in self.owners)
        if {item.seal_ref for item in observed_seals} != {
            item.seal_ref for item in frozen.baseline_seals
        }:
            raise V2IntegrityStop("V2 frozen failed-run lineage seals differ")
        owners_by_key = {
            (item.replicate_commitment, item.arm): item for item in self.owners
        }
        ledger = self.owners[0].ledger
        runtime_rows: list[tuple[str, int, int]] = [
            (
                item.root.name,
                *_private_root_identity(
                    item.root, "frozen failed-run lineage root"
                )[1:],
            )
            for item in self.owners
        ]
        scope_rows: list[tuple[str, int, int]] = []
        retained_identities: set[tuple[int, int]] = set()
        for evidence in rows:
            ledger.require_artifact(
                evidence.evidence_ref,
                "retained-disposable-allocation",
                evidence.to_canonical(),
            )
            all_targets = {
                *(item.target_path for item in evidence.extant_targets),
                *evidence.absent_targets,
            }
            runtime_targets = tuple(
                item for item in all_targets if Path(item).parent == self.arm_runtime_parent
            )
            scope_targets = tuple(
                item for item in all_targets if Path(item).parent == self.cognee_scope_parent
            )
            expected_scopes = 0 if evidence.role in STATELESS_ARMS else 1
            if (
                len(runtime_targets) != 1
                or len(scope_targets) != expected_scopes
                or len(all_targets) != 1 + expected_scopes
            ):
                raise V2IntegrityStop("retained disposable parent binding differs")
            allocation_payload = {
                "cognee_scope_roots": list(scope_targets),
                "protocol_identity": PROTOCOL_IDENTITY,
                "purpose": evidence.purpose,
                "replicate_commitment": evidence.replicate_commitment,
                "role": evidence.role,
                "runtime_root": runtime_targets[0],
                "schema": PATH_ALLOCATION_SCHEMA,
                "task_id": evidence.task_id,
            }
            if (
                canonical_ref("path-allocation", allocation_payload)
                != evidence.allocation_ref
            ):
                raise V2IntegrityStop("retained disposable allocation ref differs")
            ledger.require_artifact(
                evidence.allocation_ref,
                "path-allocation",
                allocation_payload,
            )
            expected_arm = {
                "recall-neutral": "IN_FULL_NEUTRAL_12",
                "recall-ordinary": "IO_FULL_ORDINARY_12",
            }.get(evidence.role, evidence.role)
            if evidence.role in STATELESS_ARMS:
                if evidence.source_baseline_seal_ref is not None:
                    raise V2IntegrityStop(
                        "retained stateless allocation has a source seal"
                    )
            else:
                source = owners_by_key.get(
                    (evidence.replicate_commitment, expected_arm)
                )
                if (
                    source is None
                    or source.verify_seal().seal_ref
                    != evidence.source_baseline_seal_ref
                ):
                    raise V2IntegrityStop(
                        "retained disposable source baseline differs"
                    )
            extant_by_path = {
                item.target_path: item for item in evidence.extant_targets
            }
            for target in all_targets:
                retained = extant_by_path.get(target)
                if retained is None:
                    try:
                        os.lstat(target)
                    except FileNotFoundError:
                        continue
                    raise V2IntegrityStop(
                        "absent retained disposable target was recreated"
                    )
                identity = _private_root_identity(
                    target, "frozen failed-run retained target"
                )
                if (
                    identity
                    != (target, retained.root_device, retained.root_inode)
                    or _terminal_scope_tree_snapshot(target) != retained.tree
                ):
                    raise V2IntegrityStop(
                        "frozen failed-run retained target changed"
                    )
                if identity[1:] in retained_identities:
                    raise V2IntegrityStop(
                        "frozen failed-run retained targets alias"
                    )
                retained_identities.add(identity[1:])
                inventory_row = (Path(target).name, *identity[1:])
                if retained.target_kind == "runtime-root":
                    runtime_rows.append(inventory_row)
                elif retained.target_kind == "cognee-scope-root":
                    scope_rows.append(inventory_row)
                else:
                    raise V2IntegrityStop(
                        "frozen failed-run retained target kind differs"
                    )

        expected_runtime = tuple(
            sorted(runtime_rows, key=lambda row: os.fsencode(row[0]))
        )
        expected_scopes = tuple(
            sorted(scope_rows, key=lambda row: os.fsencode(row[0]))
        )
        combined_identities = tuple(
            (device, inode)
            for _name, device, inode in (*expected_runtime, *expected_scopes)
        )
        if len(set(combined_identities)) != len(combined_identities):
            raise V2IntegrityStop("frozen failed-run survivor inventory aliases")
        observed_runtime = _failed_scope_parent_inventory(
            self.arm_runtime_parent,
            maximum_entries=len(expected_runtime),
        )
        observed_scopes = _failed_scope_parent_inventory(
            self.cognee_scope_parent,
            maximum_entries=len(expected_scopes),
        )
        if (
            observed_runtime != expected_runtime
            or observed_scopes != expected_scopes
        ):
            raise V2IntegrityStop("frozen failed-run survivor inventory differs")
        final_seals = tuple(item.verify_seal() for item in self.owners)
        if final_seals != observed_seals:
            raise V2IntegrityStop("frozen failed-run source seals changed")
        if (
            _failed_scope_parent_inventory(
                self.arm_runtime_parent,
                maximum_entries=len(expected_runtime),
            )
            != observed_runtime
            or _failed_scope_parent_inventory(
                self.cognee_scope_parent,
                maximum_entries=len(expected_scopes),
            )
            != observed_scopes
        ):
            raise V2IntegrityStop(
                "frozen failed-run survivor inventory changed before detach"
            )
        self.owners = ()
        self._failed_frozen_close_ref = close_ref
        self._closed = True

    def close_unfrozen_preserving_state(self) -> None:
        """Close a fully constructed owner before any adaptation begins."""

        if self._closed:
            return
        if any(item._seal is not None for item in self.owners):
            raise V2IntegrityStop("frozen lineage set requires frozen close")
        for owner in reversed(self.owners):
            _close_unfrozen_lineage_owner_preserving_state(owner)
        _assert_no_unresolved_v2_cognee_workers()
        if next(self.cognee_scope_parent.iterdir(), None) is not None:
            raise V2IntegrityStop("unfrozen lineage scope parent is not empty")
        self.owners = ()
        self._closed = True

    def close_failed_preserving_state(
        self,
        retained_scopes: Sequence[RetainedPreparationScopeEvidence],
    ) -> None:
        """Close a partial run while retaining only durably owned failure scopes."""

        if self._closed:
            return
        rows = tuple(retained_scopes)
        if any(type(item) is not RetainedPreparationScopeEvidence for item in rows):
            raise TypeError("retained preparation scope inventory differs")
        by_allocation = {item.allocation_ref: item for item in rows}
        if len(by_allocation) != len(rows):
            raise V2IntegrityStop("retained preparation scope identity repeats")
        owners_by_allocation = {item.allocation_ref: item for item in self.owners}
        if not set(by_allocation).issubset(owners_by_allocation):
            raise V2IntegrityStop("retained preparation scope owner is absent")
        if any(item._seal is not None for item in self.owners):
            raise V2IntegrityStop("frozen lineage set requires frozen close")

        runtime_identities = tuple(
            _private_root_identity(item.root, "failed lineage runtime root")
            for item in self.owners
        )
        expected_runtime_inventory = tuple(
            sorted(
                (
                    (Path(path).name, device, inode)
                    for path, device, inode in runtime_identities
                ),
                key=lambda row: os.fsencode(row[0]),
            )
        )
        if (
            any(
                Path(path).parent != self.arm_runtime_parent
                or str(self.arm_runtime_parent / Path(path).name) != path
                for path, _device, _inode in runtime_identities
            )
            or len({(device, inode) for _name, device, inode in expected_runtime_inventory})
            != len(expected_runtime_inventory)
        ):
            raise V2IntegrityStop("failed lineage runtime-root binding differs")
        observed_runtime_inventory = _failed_scope_parent_inventory(
            self.arm_runtime_parent,
            maximum_entries=len(self.owners),
        )
        if observed_runtime_inventory != expected_runtime_inventory:
            raise V2IntegrityStop("failed lineage runtime inventory differs")

        expected_inventory = tuple(
            sorted(
                (
                    (
                        Path(item.state_root).name,
                        item.root_device,
                        item.root_inode,
                    )
                    for item in rows
                ),
                key=lambda row: os.fsencode(row[0]),
            )
        )
        if (
            any(
                Path(item.state_root).parent != self.cognee_scope_parent
                or str(self.cognee_scope_parent / Path(item.state_root).name)
                != item.state_root
                for item in rows
            )
            or len(set(expected_inventory)) != len(expected_inventory)
        ):
            raise V2IntegrityStop("failed lineage retained-root binding differs")
        observed_inventory = _failed_scope_parent_inventory(
            self.cognee_scope_parent,
            maximum_entries=len(rows),
        )
        if observed_inventory != expected_inventory:
            raise V2IntegrityStop("failed lineage scope inventory differs")
        for owner in self.owners:
            _validate_failed_lineage_owner_preserving_state(
                owner, by_allocation.get(owner.allocation_ref)
            )
        _assert_no_unresolved_v2_cognee_workers()
        final_inventory = _failed_scope_parent_inventory(
            self.cognee_scope_parent,
            maximum_entries=len(rows),
        )
        final_runtime_inventory = _failed_scope_parent_inventory(
            self.arm_runtime_parent,
            maximum_entries=len(self.owners),
        )
        if final_runtime_inventory != observed_runtime_inventory:
            raise V2IntegrityStop(
                "failed lineage runtime inventory changed before detach"
            )
        if final_inventory != observed_inventory:
            raise V2IntegrityStop(
                "failed lineage scope inventory changed before detach"
            )
        for owner in reversed(self.owners):
            _detach_unfrozen_lineage_owner(owner)
        self.owners = ()
        self._closed = True

    def close(self, frozen: FrozenAdaptationState) -> None:
        if self._closed:
            return
        self.verify_frozen(frozen)
        self.owners = ()
        self._closed = True


def _render_v2_public_task(task: object) -> str:
    canonical = _task_canonical(task)
    from experiments.evaluators.high_level_multidomain_v2_history_conditioning import (
        PublicEvaluationTask,
        render_public_task,
    )

    public = PublicEvaluationTask(
        task_id=canonical["task_id"],
        replicate=canonical["replicate"],
        replicate_commitment=canonical["replicate_commitment"],
        family=canonical["family"],
        phase=canonical["phase"],
        ordinal=canonical["ordinal"],
        payload_json=canonical_json_bytes(canonical["payload"]).decode("utf-8"),
        public_commitment=canonical["public_task_ref"],
    )
    rendered = render_public_task(public)
    if type(rendered) is not str or rendered != public.payload_json:
        raise V2IntegrityStop("V2 public task rendering differs")
    return rendered


async def _build_stateful_product_runtime(
    *,
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"],
    task_text: str,
    history_plan: HistoryPlan,
    frozen_hits: Sequence[object],
    io: object,
    manifest: object,
    guard: GuardedLocalQwenBoundary,
    learner: object,
    store: object,
    journal: object,
    canonical_memory: object,
    session: V2AcquisitionSession,
    replay_frozen_origin: bool = False,
) -> "V2AttemptExecutionRuntime":
    from angler.runtime.cognitive_cycle import CognitiveCycle
    from angler.runtime.prospective_observation import (
        QwenReceiptObservedStateEncoderV1,
    )
    from angler.runtime.qwen_cognitive import (
        FrozenQwenCognitiveExecutorV1,
        FrozenQwenProcedureAdapterV1,
        FrozenQwenProcedureRelationAdapterV1,
    )

    if arm not in STATEFUL_ARMS or history_plan.arm != arm:
        raise V2InvariantError("stateful product arm/history differs")
    if (
        type(session) is not V2AcquisitionSession
        or session._closed
        or session.scope_spec.arm != arm
    ):
        raise V2IntegrityStop("stateful product acquisition session differs")
    if (
        getattr(canonical_memory, "source", None) is not store
        or getattr(canonical_memory, "backend", None) is not session.backend
    ):
        raise V2IntegrityStop("stateful canonical memory identity differs")
    canonical_memory.assert_synchronized(store.acquisition_head())
    if store.pending_acquisition_projections(limit=1):
        raise V2IntegrityStop("stateful product began with a pending outbox")
    refs = tuple(item.record_ref for item in history_plan.presentations)
    frozen_memory = _FrozenHitAcquisitionMemory(
        canonical_memory,
        expected_query=task_text,
        hits=frozen_hits,
        expected_record_refs=refs,
        expected_presentations=history_plan.presentations,
        replay_frozen_origin=replay_frozen_origin,
    )
    presented_memory = AcquisitionMemoryPresentationProxy(
        frozen_memory,
        history_plan,
        expected_record_refs=refs,
    )
    text_adapter = FrozenQwenProcedureAdapterV1(io, manifest)
    relation_adapter = FrozenQwenProcedureRelationAdapterV1(io, manifest)
    executor = FrozenQwenCognitiveExecutorV1(io, manifest, journal)
    observation_encoder = QwenReceiptObservedStateEncoderV1(
        model_ref=manifest.model_ref,
        encoder_ref=manifest.encoder_ref,
        manifest_ref=manifest.manifest_ref,
        latent_width=manifest.latent_width,
    )
    cycle = CognitiveCycle(
        text_adapter=text_adapter,
        relation_adapter=relation_adapter,
        learner=learner,
        memory=presented_memory,
        executor=executor,
        transaction_store=store,
        model_ref=manifest.model_ref,
        encoder_ref=manifest.encoder_ref,
        agent_ref=V2_CYCLE_AGENT_REF,
        world_ref=V2_CYCLE_WORLD_REF,
        recall_limit=RECALL_SLOTS,
        proposal_count=PROPOSAL_COUNT,
        successor_mode=True,
        reality_mode="SIMULATED",
        subject_ref=V2_CYCLE_SUBJECT_REF,
        scope_ref=V2_CYCLE_SCOPE_REF,
        bootstrap_evidence_refs=V2_CYCLE_BOOTSTRAP_REFS,
        observation_encoder=observation_encoder,
        removal_condition="FULL",
        frozen_recall_hits=(),
    )
    return V2AttemptExecutionRuntime(
        arm=arm,
        proposal_adapter=text_adapter,
        relation_adapter=relation_adapter,
        executor=executor,
        journal=journal,
        guard=guard,
        cycle=cycle,
        learner=learner,
        store=store,
        memory=presented_memory,
        session=session,
    )


def _build_stateless_product_runtime(
    *,
    arm: Arm,
    io: object,
    manifest: object,
    guard: GuardedLocalQwenBoundary,
    allocation: DisposablePathAllocation,
    path_registry: PathAllocationRegistry,
) -> "V2AttemptExecutionRuntime":
    from angler.runtime.qwen_cognitive import (
        FrozenQwenCognitiveExecutorV1,
        FrozenQwenProcedureAdapterV1,
        SQLiteQwenExecutionJournal,
    )

    if arm not in STATELESS_ARMS or allocation.role != arm:
        raise V2InvariantError("stateless product allocation differs")
    if path_registry._require(allocation.allocation_ref) != allocation:
        raise V2IntegrityStop("stateless product lacks its ledger capability")
    root = Path(allocation.runtime_root)
    _require_owned_directory(
        root,
        expected_mode=0o700,
        empty=True,
        label="stateless product runtime root",
    )
    journal = SQLiteQwenExecutionJournal(
        root / "qwen-execution-journal.sqlite3"
    )
    os.chmod(journal.path, 0o600)
    text_adapter = FrozenQwenProcedureAdapterV1(io, manifest)
    executor = FrozenQwenCognitiveExecutorV1(io, manifest, journal)
    return V2AttemptExecutionRuntime(
        arm=arm,
        proposal_adapter=text_adapter,
        relation_adapter=None,
        executor=executor,
        journal=journal,
        guard=guard,
        runtime_root=root,
        allocation_ref=allocation.allocation_ref,
        allocation=allocation,
        path_registry=path_registry,
    )


@dataclass(slots=True)
class V2AttemptExecutionRuntime:
    """One exact product runtime through proposal/execution, never feedback."""

    arm: Arm
    proposal_adapter: object = field(repr=False)
    relation_adapter: object | None = field(repr=False)
    executor: object = field(repr=False)
    journal: object = field(repr=False)
    guard: GuardedLocalQwenBoundary = field(repr=False)
    cycle: object | None = field(default=None, repr=False)
    learner: object | None = field(default=None, repr=False)
    store: object | None = field(default=None, repr=False)
    memory: object | None = field(default=None, repr=False)
    session: V2AcquisitionSession | None = field(default=None, repr=False)
    runtime_root: Path | None = field(default=None, repr=False)
    allocation_ref: str | None = field(default=None, repr=False)
    allocation: DisposablePathAllocation | None = field(default=None, repr=False)
    path_registry: PathAllocationRegistry | None = field(default=None, repr=False)
    _turn: object | None = field(default=None, init=False, repr=False)
    _completed: object | None = field(default=None, init=False, repr=False)
    _last_observation_ref: str | None = field(default=None, init=False, repr=False)
    _journal_identity: tuple[str, int, int] | None = field(
        default=None, init=False, repr=False
    )

    def __post_init__(self) -> None:
        from angler.runtime.qwen_cognitive import (
            FrozenQwenCognitiveExecutorV1,
            FrozenQwenProcedureAdapterV1,
            FrozenQwenProcedureRelationAdapterV1,
            SQLiteQwenExecutionJournal,
        )

        arm = validate_arm(self.arm)
        if (
            type(self.proposal_adapter) is not FrozenQwenProcedureAdapterV1
            or type(self.executor) is not FrozenQwenCognitiveExecutorV1
            or type(self.journal) is not SQLiteQwenExecutionJournal
        ):
            raise TypeError("V2 attempt runtime requires exact frozen Qwen products")
        if not callable(
            getattr(self.proposal_adapter, "propose_procedure_traces", None)
        ):
            raise TypeError("V2 proposal adapter differs")
        if not callable(getattr(self.executor, "execute", None)):
            raise TypeError("V2 executor differs")
        if not callable(getattr(self.journal, "get", None)):
            raise TypeError("V2 execution journal differs")
        if type(self.guard) is not GuardedLocalQwenBoundary:
            raise TypeError("V2 guarded Qwen boundary differs")
        guarded_io = self.guard.io
        proposal_manifest = getattr(self.proposal_adapter, "manifest", None)
        executor_manifest = getattr(self.executor, "manifest", None)
        if (
            getattr(self.proposal_adapter, "io", None) is not guarded_io
            or getattr(self.executor, "io", None) is not guarded_io
            or getattr(self.executor, "journal", None) is not self.journal
            or proposal_manifest is None
            or executor_manifest is not proposal_manifest
        ):
            raise V2IntegrityStop("V2 Qwen product graph bypasses its guard")
        if arm in STATEFUL_ARMS:
            from angler.runtime.cognitive_cycle import CognitiveCycle
            from angler.runtime.prospective_observation import (
                QwenReceiptObservedStateEncoderV1,
            )

            if not all(
                callable(getattr(self.cycle, name, None))
                for name in (
                    "begin_turn",
                    "execute_turn",
                    "record_outcome",
                    "retry_pending_projections",
                )
            ) or any(
                value is None
                for value in (
                    self.learner,
                    self.store,
                    self.memory,
                    self.session,
                    self.relation_adapter,
                )
            ):
                raise TypeError("V2 stateful attempt runtime is incomplete")
            if (
                type(self.cycle) is not CognitiveCycle
                or type(self.relation_adapter)
                is not FrozenQwenProcedureRelationAdapterV1
                or type(getattr(self.cycle, "_observation_encoder", None))
                is not QwenReceiptObservedStateEncoderV1
            ):
                raise TypeError("V2 stateful runtime product types differ")
            situated_context = getattr(self.cycle, "_situated_context", None)
            if (
                getattr(self.cycle, "text_adapter", None) is not self.proposal_adapter
                or getattr(self.cycle, "relation_adapter", None)
                is not self.relation_adapter
                or getattr(self.relation_adapter, "io", None) is not guarded_io
                or getattr(self.relation_adapter, "manifest", None)
                is not proposal_manifest
                or getattr(self.cycle, "executor", None) is not self.executor
                or getattr(self.cycle, "learner", None) is not self.learner
                or getattr(self.cycle, "transaction_store", None) is not self.store
                or getattr(self.cycle, "memory", None) is not self.memory
                or getattr(self.memory, "source", None) is not self.store
                or getattr(self.memory, "backend", None) is not self.session.backend
                or getattr(self.cycle, "proposal_count", None) != PROPOSAL_COUNT
                or getattr(self.cycle, "recall_limit", None) != RECALL_SLOTS
                or getattr(self.cycle, "_successor_mode", None) is not True
                or getattr(self.cycle, "_removal_condition", None) != "FULL"
                or getattr(
                    getattr(situated_context, "reality_mode", None),
                    "value",
                    getattr(situated_context, "reality_mode", None),
                )
                != "SIMULATED"
            ):
                raise V2IntegrityStop("V2 stateful product graph identity differs")
        elif any(
            value is not None
            for value in (
                self.cycle,
                self.learner,
                self.store,
                self.memory,
                self.session,
                self.relation_adapter,
            )
        ):
            raise V2InvariantError("V2 stateless runtime acquired mutable lineage")
        if arm in STATELESS_ARMS:
            if (
                not isinstance(self.runtime_root, Path)
                or not self.runtime_root.is_absolute()
                or _private_root_identity(
                    self.runtime_root, "V2 stateless runtime root"
                )[0]
                != str(self.runtime_root)
                or self.allocation_ref is None
                or type(self.allocation) is not DisposablePathAllocation
                or type(self.path_registry) is not PathAllocationRegistry
            ):
                raise V2InvariantError("V2 stateless runtime allocation differs")
            _ref(self.allocation_ref, "V2 stateless runtime allocation ref")
            journal_path = self.runtime_root / "qwen-execution-journal.sqlite3"
            if (
                self.allocation.allocation_ref != self.allocation_ref
                or self.allocation.purpose != self.path_registry.purpose
                or self.allocation.role != arm
                or self.allocation.runtime_root != str(self.runtime_root)
                or self.allocation.cognee_scope_roots
                or getattr(self.journal, "path", None) != journal_path
            ):
                raise V2InvariantError("V2 stateless journal path differs")
            committed = self.path_registry._require(self.allocation_ref)
            if committed != self.allocation:
                raise V2IntegrityStop("V2 stateless allocation capability differs")
            _require_owned_regular_file(
                journal_path,
                expected_mode=0o600,
                label="V2 stateless journal",
            )
            journal_metadata = os.lstat(journal_path)
            self._journal_identity = (
                str(journal_path),
                int(journal_metadata.st_dev),
                int(journal_metadata.st_ino),
            )
        elif self.allocation is not None or self.path_registry is not None:
            raise V2InvariantError("V2 stateful runtime acquired stateless allocation")

    @property
    def stateful(self) -> bool:
        return self.arm in STATEFUL_ARMS

    def _assert_successor_quiescent(self) -> None:
        if not self.stateful:
            raise V2IntegrityStop("stateless V2 runtime has no successor state")
        if (
            getattr(self.cycle, "pending_turn", None) is not None
            or getattr(self.cycle, "executed_turn", None) is not None
            or getattr(self.cycle, "_beginning", None) is not False
            or getattr(self.cycle, "_executing", None) is not False
            or getattr(self.learner, "pending_decision", None) is not None
            or getattr(self.learner, "pending_prospective_material", None)
            is not None
            or self.store.active_prospective_turn() is not None
            or self.store.pending_acquisition_projections(limit=1)
        ):
            raise V2IntegrityStop("malformed V2 successor runtime is not quiescent")
        head = self.store.audit_integrity()
        snapshot = self.learner.capture_state()
        if (
            head is None
            or getattr(head, "state_digest", None) != self.learner.state_digest()
            or self.store.load_head_state() != snapshot
        ):
            raise V2IntegrityStop("malformed V2 successor state binding differs")
        self.journal.audit_integrity()

    async def execute_observation(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        prompt_plan: PromptPlan,
        permit: AttemptGenerationPermit,
    ) -> AttemptObservation:
        if (
            type(scheduled) is not ScheduledAttempt
            or type(stage) is not AttemptStage
            or type(prompt_plan) is not PromptPlan
            or type(permit) is not AttemptGenerationPermit
            or scheduled.arm != self.arm
            or stage.arm != self.arm
            or prompt_plan.arm != self.arm
            or scheduled.task_id != stage.task_id
            or stage.task_id != prompt_plan.task_id
            or self._turn is not None
            or self._completed is not None
            or self._last_observation_ref is not None
        ):
            raise V2IntegrityStop("V2 attempt runtime invocation differs")
        if not self.stateful and (
            self.allocation.task_id != stage.task_id
            or self.allocation.replicate_commitment
            != stage.replicate_commitment
            or self.allocation.purpose != stage.purpose
            or self.allocation.role != stage.arm
            or self.path_registry._require(self.allocation_ref) != self.allocation
        ):
            raise V2IntegrityStop("V2 stateless attempt allocation differs")
        rendered_task = _render_v2_public_task(scheduled.task)
        malformed = False
        proposals: tuple[str, ...] = ()
        turn: object | None = None
        completed: object | None = None
        proposal_generation: object | None = None
        execution_request: object | None = None
        execution_receipt: object | None = None
        execution_generation: object | None = None
        with self.guard.attempt(
            task_id=stage.task_id,
            arm=stage.arm,
            stage_ref=stage.stage_ref,
            proposal_prompt_ref=prompt_plan.prompt_ref,
            maximum_generation_calls=2,
            maximum_embedding_rows=(
                RUNTIME_EMBEDDING_ROWS_PER_STATEFUL_ATTEMPT
                if self.stateful
                else 0
            ),
        ):
            permit.before_proposal_generation()
            try:
                if self.stateful:
                    turn = await _maybe_await(
                        self.cycle.begin_turn(  # type: ignore[union-attr]
                            stage.task_id,
                            rendered_task,
                        )
                    )
                    proposals = tuple(turn.decision.proposals)
                else:
                    evidence = (
                        (NO_PERSISTENT_RECALLED_EVIDENCE_V1,)
                        if self.arm == "N0_NATIVE_NO_HISTORY"
                        else prompt_plan.history_plan.evidence_texts
                    )
                    proposals = tuple(
                        self.proposal_adapter.propose_procedure_traces(
                            rendered_task,
                            evidence,
                            count=PROPOSAL_COUNT,
                        )
                    )
            except ValueError as error:
                proposal_generation = getattr(
                    self.proposal_adapter, "last_proposal_generation", None
                )
                if proposal_generation is None:
                    raise
                from angler.runtime.qwen_cognitive import (
                    parse_qwen_procedure_proposals,
                )

                try:
                    parse_qwen_procedure_proposals(
                        getattr(proposal_generation, "response", None),
                        count=PROPOSAL_COUNT,
                    )
                except ValueError as parse_error:
                    _clear_exception_retention(parse_error)
                    malformed = True
                    turn = None
                    proposals = ()
                else:
                    raise
                finally:
                    _clear_exception_retention(error)
            proposal_generation = getattr(
                self.proposal_adapter, "last_proposal_generation", None
            )
            if proposal_generation is None:
                raise V2IntegrityStop("V2 proposal generation evidence is absent")
            if not malformed:
                if (
                    len(proposals) != PROPOSAL_COUNT
                    or len(set(proposals)) != PROPOSAL_COUNT
                ):
                    raise V2IntegrityStop("V2 admitted proposal set differs")
                permit.before_execution_generation()
                if self.stateful:
                    if turn is None:
                        raise V2IntegrityStop("V2 stateful proposal lacks a turn")
                    completed = await _maybe_await(
                        self.cycle.execute_turn(  # type: ignore[union-attr]
                            turn,
                            observations=(
                                "No hidden or external observation is available.",
                            ),
                        )
                    )
                    execution_request = completed.execution_request
                    execution_receipt = completed.execution_receipt
                    key = turn.reservation.idempotency_key
                else:
                    from angler.cognition.prospective import CognitiveExecutionRequest

                    selected_index = control_selection_index(
                        stage.public_task_ref, PROPOSAL_COUNT
                    )
                    selected_trace = proposals[selected_index]
                    control_ref = canonical_ref(
                        "v2-stateless-selection",
                        {
                            "arm": self.arm,
                            "proposal_generation_ref": getattr(
                                proposal_generation, "generation_ref", None
                            ),
                            "proposals": list(proposals),
                            "public_task_ref": stage.public_task_ref,
                            "selected_index": selected_index,
                            "task_id": stage.task_id,
                        },
                    )
                    execution_request = CognitiveExecutionRequest(
                        reservation_ref=control_ref,
                        commitment_ref=control_ref,
                        idempotency_key=control_ref,
                        task_id=stage.task_id,
                        request=rendered_task,
                        selected_trace=selected_trace,
                        input_observations=(
                            "No hidden or external observation is available.",
                        ),
                    )
                    await _maybe_await(self.executor.execute(execution_request))
                    key = control_ref
                journal_entry = self.journal.get(key)
                if journal_entry is None:
                    raise V2IntegrityStop("V2 admitted execution was not journaled")
                execution_generation = getattr(journal_entry, "generation", None)
                journal_request = getattr(journal_entry, "request", None)
                journal_receipt = getattr(journal_entry, "receipt", None)
                if (
                    journal_request != execution_request
                    or (
                        execution_receipt is not None
                        and journal_receipt != execution_receipt
                    )
                ):
                    raise V2IntegrityStop("V2 journaled execution evidence differs")
                execution_receipt = journal_receipt

        proposal_generation_ref = _ref(
            getattr(proposal_generation, "generation_ref", None),
            "V2 proposal generation ref",
        )
        proposal_prompt_ref = _ref(
            getattr(proposal_generation, "prompt_ref", None),
            "V2 proposal prompt ref",
        )
        proposal_prompt_tokens = _integer(
            getattr(proposal_generation, "prompt_tokens", None),
            "V2 proposal prompt tokens",
            minimum=1,
            maximum=MAXIMUM_INPUT_TOKENS,
        )
        proposal_ids = tuple(
            getattr(proposal_generation, "generated_token_ids", ())
        )
        proposal_output_tokens = _integer(
            len(proposal_ids),
            "V2 proposal output tokens",
            minimum=1,
            maximum=MAXIMUM_OUTPUT_TOKENS,
        )
        if malformed:
            if self.stateful:
                self._assert_successor_quiescent()
            observation = AttemptObservation(
                task_id=stage.task_id,
                arm=stage.arm,
                proposal_admitted=False,
                proposals=(),
                selected_index=None,
                selected_trace=None,
                raw_response="",
                proposal_generation_ref=proposal_generation_ref,
                proposal_prompt_ref=proposal_prompt_ref,
                proposal_prompt_tokens=proposal_prompt_tokens,
                proposal_output_tokens=proposal_output_tokens,
                execution_request_ref=None,
                execution_receipt_ref=None,
                execution_prompt_ref=None,
                execution_prompt_tokens=None,
                execution_output_tokens=None,
                selected_trace_bound=None,
                response_bound=None,
                selected_grammar_class=None,
                response_grammar_class=None,
                recalled_record_refs=tuple(
                    item.record_ref
                    for item in prompt_plan.history_plan.presentations
                ),
            )
        else:
            if execution_request is None or execution_receipt is None:
                raise V2IntegrityStop("V2 admitted execution evidence is incomplete")
            execution_prompt_ref = _ref(
                getattr(execution_generation, "prompt_ref", None),
                "V2 execution prompt ref",
            )
            execution_prompt_tokens = _integer(
                getattr(execution_generation, "prompt_tokens", None),
                "V2 execution prompt tokens",
                minimum=1,
                maximum=MAXIMUM_INPUT_TOKENS,
            )
            execution_ids = tuple(
                getattr(execution_generation, "generated_token_ids", ())
            )
            execution_output_tokens = _integer(
                len(execution_ids),
                "V2 execution output tokens",
                minimum=1,
                maximum=MAXIMUM_OUTPUT_TOKENS,
            )
            selected_index = (
                turn.decision.selected_index
                if self.stateful
                else control_selection_index(stage.public_task_ref, PROPOSAL_COUNT)
            )
            selected_trace = proposals[selected_index]
            raw_response = getattr(execution_receipt, "response", None)
            if type(raw_response) is not str:
                raise V2IntegrityStop("V2 execution response differs")
            recalled_refs = (
                tuple(getattr(turn, "recalled_refs", ()))
                if self.stateful
                else tuple(
                    item.record_ref
                    for item in prompt_plan.history_plan.presentations
                )
            )
            observation = AttemptObservation(
                task_id=stage.task_id,
                arm=stage.arm,
                proposal_admitted=True,
                proposals=proposals,
                selected_index=selected_index,
                selected_trace=selected_trace,
                raw_response=raw_response,
                proposal_generation_ref=proposal_generation_ref,
                proposal_prompt_ref=proposal_prompt_ref,
                proposal_prompt_tokens=proposal_prompt_tokens,
                proposal_output_tokens=proposal_output_tokens,
                execution_request_ref=_ref(
                    getattr(execution_request, "execution_request_ref", None),
                    "V2 execution request ref",
                ),
                execution_receipt_ref=_ref(
                    getattr(execution_receipt, "execution_receipt_ref", None),
                    "V2 execution receipt ref",
                ),
                execution_prompt_ref=execution_prompt_ref,
                execution_prompt_tokens=execution_prompt_tokens,
                execution_output_tokens=execution_output_tokens,
                selected_trace_bound=(
                    getattr(execution_receipt, "executed_trace", None)
                    == selected_trace
                ),
                response_bound=(
                    getattr(execution_receipt, "response", None) == raw_response
                ),
                selected_grammar_class=None,
                response_grammar_class=None,
                recalled_record_refs=recalled_refs,
            )
        self._turn = turn
        self._completed = completed
        self._last_observation_ref = observation.observation_ref
        return observation

    async def apply_objective_feedback(
        self,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
    ) -> StatefulFeedbackApplication:
        if (
            not self.stateful
            or type(observation) is not AttemptObservation
            or observation.observation_ref != self._last_observation_ref
            or not observation.proposal_admitted
            or self._turn is None
            or self._completed is None
        ):
            raise V2IntegrityStop("V2 objective feedback runtime state differs")
        value = _canonical_judgment(judgment)
        score = value.get("score")
        if type(score) is not float or score not in (0.0, 1.0):
            raise V2IntegrityStop("V2 learner-visible objective score differs")
        feedback_source_ref = _ref(
            value.get("evaluator_record_ref"), "V2 feedback source ref"
        )
        committed = await _maybe_await(
            self.cycle.record_outcome(  # type: ignore[union-attr]
                self._completed,
                reservation_ref=self._turn.reservation.reservation_ref,
                task_id=observation.task_id,
                outcome="success" if score == 1.0 else "failure",
                feedback_text=(
                    "The isolated objective evaluator returned its declared "
                    "binary disposition."
                ),
                feedback_source_ref=feedback_source_ref,
            )
        )
        record = self.store.prospective_turn_for_episode(  # type: ignore[union-attr]
            committed.episode_ref
        )
        resolution = getattr(record, "resolution", None)
        wrapper = getattr(self._turn, "successor_reservation", None)
        batch = getattr(wrapper, "batch", None)
        updated = replace(
            observation,
            prospective_reservation_ref=_ref(
                getattr(wrapper, "reservation_ref", None),
                "V2 prospective reservation ref",
            ),
            prospective_batch_ref=_ref(
                getattr(batch, "batch_ref", None),
                "V2 prospective batch ref",
            ),
            resolution_ref=_ref(
                getattr(resolution, "resolution_ref", None),
                "V2 prospective resolution ref",
            ),
        )
        self._last_observation_ref = updated.observation_ref
        return StatefulFeedbackApplication(updated, None)

    def dispose_stateless_durable(
        self,
        *,
        stage: AttemptStage,
        terminal_disposition_ref: str,
        ledger: EvidenceLedger,
    ) -> StatelessRuntimeCleanupEvidence:
        if (
            self.stateful
            or self.runtime_root is None
            or self.allocation_ref is None
            or type(ledger) is not EvidenceLedger
            or ledger._closed
            or type(self.allocation) is not DisposablePathAllocation
            or type(self.path_registry) is not PathAllocationRegistry
            or self.path_registry.ledger is not ledger
            or type(stage) is not AttemptStage
            or self.allocation.task_id != stage.task_id
            or self.allocation.replicate_commitment
            != stage.replicate_commitment
            or self.allocation.purpose != stage.purpose
            or self.allocation.role != self.arm
            or stage.arm != self.arm
            or self.allocation.runtime_root != str(self.runtime_root)
            or self.allocation.allocation_ref != self.allocation_ref
        ):
            raise V2IntegrityStop("V2 stateless cleanup boundary differs")
        terminal_disposition_ref = _ref(
            terminal_disposition_ref, "V2 stateless cleanup disposition ref"
        )
        ledger.require_terminal_disposition_payload(
            task_id=stage.task_id,
            arm=stage.arm,
            terminal_disposition_ref=terminal_disposition_ref,
            expected_clone_terminal_ref=None,
            stage_ref=stage.stage_ref,
            attempt_receipt_ref=stage.attempt_receipt_ref,
        )
        self.journal.audit_integrity()
        journal_path = self.runtime_root / "qwen-execution-journal.sqlite3"
        journal_metadata = os.lstat(journal_path)
        if (
            self._journal_identity
            != (
                str(journal_path),
                int(journal_metadata.st_dev),
                int(journal_metadata.st_ino),
            )
            or self.path_registry._require(self.allocation_ref) != self.allocation
        ):
            raise V2IntegrityStop("V2 stateless cleanup allocation/inode changed")
        digest, size = sha256_file(journal_path)
        terminal = StatelessRuntimeTerminalEvidence(
            task_id=stage.task_id,
            arm=self.arm,
            runtime_root=str(self.runtime_root),
            journal_path=str(journal_path),
            journal_sha256=digest,
            journal_bytes=size,
            allocation_ref=self.allocation_ref,
            terminal_disposition_ref=terminal_disposition_ref,
        )
        ledger.append_artifact_durable(
            terminal.terminal_ref,
            "stateless-runtime-terminal",
            terminal.to_canonical(),
        )
        self.path_registry.require_stateless(terminal)
        runtime_root = self.runtime_root
        _remove_exact_private_tree(
            runtime_root,
            expected_parent=runtime_root.parent,
        )
        try:
            os.lstat(runtime_root)
        except FileNotFoundError:
            pass
        else:
            raise V2IntegrityStop("V2 stateless runtime remains after cleanup")
        cleanup = StatelessRuntimeCleanupEvidence(
            terminal=terminal,
            disposed=True,
            cleanup_absence_verified=True,
        )
        ledger.append_artifact_durable(
            cleanup.cleanup_ref,
            "stateless-runtime-cleanup",
            cleanup.to_canonical(),
        )
        self.proposal_adapter = None
        self.relation_adapter = None
        self.executor = None
        self.journal = None
        self.guard = None
        self.cycle = None
        self.learner = None
        self.store = None
        self.memory = None
        self.session = None
        self.runtime_root = None
        self.allocation_ref = None
        self.allocation = None
        self.path_registry = None
        self._turn = None
        self._completed = None
        self._last_observation_ref = None
        self._journal_identity = None
        return cleanup


@dataclass(slots=True)
class V2StatefulAttemptOwner:
    """Own one persistent adaptation session or one disposable full-runtime clone."""

    runtime: V2AttemptExecutionRuntime | None = field(repr=False)
    source_owner: V2LineageOwner = field(repr=False)
    ledger: EvidenceLedger = field(repr=False)
    quiesce_runtime: Callable[..., Awaitable[None] | None] = field(repr=False)
    source_seal: BaselineSeal | None = None
    clone_paths: object | None = field(default=None, repr=False)
    clone_before: tuple[tuple[str, str], ...] = ()
    allocation: DisposablePathAllocation | None = field(default=None, repr=False)
    path_registry: PathAllocationRegistry | None = field(default=None, repr=False)
    _terminal: CloneTerminalEvidence | None = field(
        default=None, init=False, repr=False
    )
    _closed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        if (
            type(self.runtime) is not V2AttemptExecutionRuntime
            or not self.runtime.stateful
            or type(self.source_owner) is not V2LineageOwner
            or type(self.ledger) is not EvidenceLedger
            or self.ledger is not self.source_owner.ledger
            or not callable(self.quiesce_runtime)
        ):
            raise TypeError("V2 stateful attempt owner inputs differ")
        persistent = self.source_seal is None
        if persistent:
            if any(
                value is not None
                for value in (
                    self.clone_paths,
                    self.allocation,
                    self.path_registry,
                )
            ) or self.clone_before:
                raise V2InvariantError("persistent V2 attempt acquired clone state")
            if (
                self.runtime.arm != self.source_owner.arm
                or self.runtime.session.scope_spec.arm != self.source_owner.arm
                or self.runtime.session.scope_spec.purpose
                != self.source_owner.purpose
                or self.runtime.session.scope_spec.replicate_commitment
                != self.source_owner.replicate_commitment
                or self.runtime.session.scope_spec.scope_kind
                != "persistent-adaptation"
                or self.runtime.session.scope_spec.task_id is not None
                or self.runtime.learner is not self.source_owner.learner
                or self.runtime.store is not self.source_owner.store
                or self.runtime.journal is not self.source_owner.journal
                or self.runtime.session.scope_spec != self.source_owner.scope_spec
            ):
                raise V2IntegrityStop("persistent V2 attempt lineage differs")
        else:
            if (
                type(self.source_seal) is not BaselineSeal
                or self.source_seal.seal_ref
                != self.source_owner.verify_seal().seal_ref
                or self.source_seal.arm != self.runtime.arm
                or self.source_owner.arm != self.runtime.arm
                or self.runtime.session.scope_spec.arm != self.runtime.arm
                or self.runtime.session.scope_spec.purpose
                != self.source_owner.purpose
                or self.runtime.session.scope_spec.replicate_commitment
                != self.source_owner.replicate_commitment
                or self.runtime.session.scope_spec.scope_kind
                != "disposable-attempt"
                or self.runtime.session.scope_spec.task_id
                != self.allocation.task_id
                or self.allocation.purpose != self.source_owner.purpose
                or self.allocation.replicate_commitment
                != self.source_owner.replicate_commitment
                or self.clone_paths is None
                or type(self.allocation) is not DisposablePathAllocation
                or type(self.path_registry) is not PathAllocationRegistry
                or self.path_registry.ledger is not self.ledger
                or self.allocation.role != self.runtime.arm
                or self.allocation.runtime_root
                != str(getattr(self.clone_paths, "root", None))
                or self.allocation.cognee_scope_roots
                != (self.runtime.session.scope_spec.state_root,)
                or self.clone_before
                != _hash_pairs(dict(self.clone_before), "V2 clone initial hashes")
                or self.clone_before != self.source_seal.hashes
            ):
                raise V2IntegrityStop("disposable V2 attempt clone binding differs")
            if self.path_registry._require(self.allocation.allocation_ref) != self.allocation:
                raise V2IntegrityStop("disposable V2 attempt lacks path capability")

    @property
    def persistent(self) -> bool:
        return self.source_seal is None

    async def execute_observation(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        prompt_plan: PromptPlan,
        permit: AttemptGenerationPermit,
    ) -> AttemptObservation:
        if self._closed or self.runtime is None:
            raise V2IntegrityStop("V2 stateful attempt owner is closed")
        expected_persistent = scheduled.phase == "adaptation"
        if (
            type(scheduled) is not ScheduledAttempt
            or type(stage) is not AttemptStage
            or type(prompt_plan) is not PromptPlan
            or expected_persistent is not self.persistent
            or scheduled.task_id != stage.task_id
            or scheduled.arm != stage.arm
            or stage.arm != self.runtime.arm
            or prompt_plan.arm != self.runtime.arm
            or scheduled.replicate_commitment
            != self.source_owner.replicate_commitment
            or stage.replicate_commitment
            != self.source_owner.replicate_commitment
        ):
            raise V2IntegrityStop("V2 stateful attempt schedule capability differs")
        if self.persistent:
            if self.runtime.session.scope_spec.task_id is not None:
                raise V2IntegrityStop("persistent V2 scope acquired a task id")
        elif (
            scheduled.phase not in ("development", "final")
            or self.allocation.task_id != stage.task_id
            or self.allocation.replicate_commitment != stage.replicate_commitment
            or self.allocation.purpose != stage.purpose
            or self.runtime.session.scope_spec.task_id != stage.task_id
        ):
            raise V2IntegrityStop("disposable V2 attempt capability differs")
        return await self.runtime.execute_observation(
            scheduled, stage, prompt_plan, permit
        )

    async def apply_objective_feedback(
        self,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
    ) -> StatefulFeedbackApplication:
        if self._closed or self.runtime is None:
            raise V2IntegrityStop("V2 stateful attempt owner is closed")
        return await self.runtime.apply_objective_feedback(observation, judgment)

    async def _quiesce(self) -> None:
        if self._closed or self.runtime is None:
            raise V2IntegrityStop("V2 stateful attempt owner is closed")
        quiescence_failure: V2IntegrityStop | None = None
        try:
            await _maybe_await(
                self.quiesce_runtime(
                    cycle=self.runtime.cycle,
                    learner=self.runtime.learner,
                    store=self.runtime.store,
                    journal=self.runtime.journal,
                    memory=self.runtime.memory,
                )
            )
        except BaseException as error:
            quiescence_failure = _redacted_cleanup_failure(
                error, "V2_STATEFUL_RUNTIME_QUIESCENCE_FAILED"
            )
        if quiescence_failure is not None:
            raise quiescence_failure from None

    def _detach_after_cleanup(self) -> None:
        if self.runtime is None:
            return
        self.runtime.proposal_adapter = None
        self.runtime.relation_adapter = None
        self.runtime.executor = None
        self.runtime.journal = None
        self.runtime.cycle = None
        self.runtime.learner = None
        self.runtime.store = None
        self.runtime.memory = None
        self.runtime.session = None
        self.runtime.guard = None
        self.runtime = None
        self._closed = True

    def _detach_model_graph_preserving_session(self) -> None:
        """Release all foundation references while retaining one worker handle."""

        if self.runtime is None:
            return
        self.runtime.proposal_adapter = None
        self.runtime.relation_adapter = None
        self.runtime.executor = None
        self.runtime.journal = None
        self.runtime.cycle = None
        self.runtime.learner = None
        self.runtime.store = None
        self.runtime.memory = None
        self.runtime.guard = None

    async def finalize_persistent(
        self,
        *,
        stage: AttemptStage,
        attempt_receipt_ref: str,
        terminal_disposition_ref: str,
        feedback_applied: bool,
    ) -> PersistentRuntimeCleanupEvidence:
        if not self.persistent or self.runtime is None:
            raise V2IntegrityStop("persistent V2 attempt finalization differs")
        if (
            type(stage) is not AttemptStage
            or stage.phase != "adaptation"
            or stage.arm != self.runtime.arm
            or stage.replicate_commitment
            != self.source_owner.replicate_commitment
        ):
            raise V2IntegrityStop("persistent V2 attempt stage differs")
        attempt_receipt_ref = _ref(
            attempt_receipt_ref, "persistent V2 attempt receipt ref"
        )
        terminal_disposition_ref = _ref(
            terminal_disposition_ref,
            "persistent V2 attempt terminal disposition ref",
        )
        if attempt_receipt_ref != stage.attempt_receipt_ref:
            raise V2IntegrityStop("persistent V2 attempt receipt differs")
        if type(feedback_applied) is not bool:
            raise TypeError("persistent V2 feedback flag differs")
        self.ledger.require_terminal_disposition(
            task_id=stage.task_id,
            arm=stage.arm,
            stage_ref=stage.stage_ref,
            attempt_receipt_ref=attempt_receipt_ref,
            terminal_disposition_ref=terminal_disposition_ref,
        )
        self.ledger.require_terminal_disposition_payload(
            task_id=stage.task_id,
            arm=stage.arm,
            terminal_disposition_ref=terminal_disposition_ref,
            expected_clone_terminal_ref=None,
            stage_ref=stage.stage_ref,
            attempt_receipt_ref=attempt_receipt_ref,
        )
        await self._quiesce()
        self.source_owner.persist_quiescent(cycle=self.runtime.cycle)
        terminal = PersistentRuntimeTerminalEvidence(
            task_id=stage.task_id,
            arm=self.runtime.arm,
            replicate_commitment=self.source_owner.replicate_commitment,
            stage_ref=stage.stage_ref,
            attempt_receipt_ref=attempt_receipt_ref,
            terminal_disposition_ref=terminal_disposition_ref,
            runtime_root=str(self.source_owner.root),
            cognee_scope_root=self.runtime.session.scope_spec.state_root,
            allocation_ref=self.source_owner.allocation_ref,
            dataset_id=self.runtime.session.dataset_id,
            hashes=_hash_pairs(
                self.source_owner.hashes(), "persistent V2 terminal hashes"
            ),
            feedback_applied=feedback_applied,
            quiescent=True,
        )
        self.ledger.append_artifact_durable(
            terminal.terminal_ref,
            "persistent-runtime-terminal",
            terminal.to_canonical(),
        )
        session = self.runtime.session
        await session.forget_close_and_remove()
        try:
            os.lstat(terminal.cognee_scope_root)
        except FileNotFoundError:
            pass
        else:
            raise V2IntegrityStop("persistent V2 Cognee scope remains")
        cleanup = PersistentRuntimeCleanupEvidence(
            terminal=terminal,
            scope_disposed=True,
            cleanup_absence_verified=True,
        )
        self.ledger.append_artifact_durable(
            cleanup.cleanup_ref,
            "persistent-runtime-cleanup",
            cleanup.to_canonical(),
        )
        self._detach_after_cleanup()
        return cleanup

    async def terminalize_clone(
        self,
        *,
        task_id: str,
    ) -> CloneTerminalEvidence:
        if self.persistent or self.runtime is None or self._terminal is not None:
            raise V2IntegrityStop("disposable V2 terminalization differs")
        task_id = _ref(task_id, "disposable V2 task id")
        if self.allocation.task_id != task_id:
            raise V2IntegrityStop("disposable V2 allocation task differs")
        if self.source_owner.verify_seal().seal_ref != self.source_seal.seal_ref:
            raise V2IntegrityStop("disposable V2 source seal changed")
        await self._quiesce()
        snapshot = self.runtime.learner.capture_state()
        if type(snapshot) is not bytes or not 1 <= len(snapshot) <= MAXIMUM_LINEAGE_SNAPSHOT_BYTES:
            raise V2IntegrityStop("disposable V2 learner snapshot differs")
        _replace_private_bytes_durable(
            self.clone_paths.learner,
            snapshot,
            maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
        )
        source = self.source_owner.verify_seal()
        source_before = _hash_pairs(
            dict(self.source_seal.hashes), "disposable source before"
        )
        source_after = _hash_pairs(
            self.source_owner.hashes(), "disposable source after"
        )
        clone_terminal = _hash_pairs(
            self.source_owner._mechanics.closed_hashes(
                self.clone_paths,
                store=self.runtime.store,
                journal=self.runtime.journal,
            ),
            "disposable clone terminal",
        )
        if source.seal_ref != self.source_seal.seal_ref:
            raise V2IntegrityStop("disposable V2 source seal changed")
        terminal = CloneTerminalEvidence(
            task_id=task_id,
            arm=self.runtime.arm,
            source_root=self.source_seal.root,
            clone_root=str(self.clone_paths.root),
            source_before=source_before,
            source_after=source_after,
            clone_before=self.clone_before,
            clone_terminal=clone_terminal,
            quiescent=True,
            cognee_scope_roots=self.allocation.cognee_scope_roots,
            allocation_ref=self.allocation.allocation_ref,
        )
        self._terminal = terminal
        return terminal

    async def dispose_clone(
        self,
        terminal: CloneTerminalEvidence,
        terminal_disposition_ref: str,
    ) -> CloneLifecycleEvidence:
        if (
            self.persistent
            or self.runtime is None
            or terminal != self._terminal
            or self.path_registry._require(terminal.allocation_ref) != self.allocation
        ):
            raise V2IntegrityStop("disposable V2 cleanup boundary differs")
        terminal_disposition_ref = _ref(
            terminal_disposition_ref, "disposable V2 disposition ref"
        )
        self.ledger.require_terminal_disposition_payload(
            task_id=terminal.task_id,
            arm=terminal.arm,
            terminal_disposition_ref=terminal_disposition_ref,
            expected_clone_terminal_ref=terminal.terminal_ref,
        )
        if self.source_owner.verify_seal().seal_ref != self.source_seal.seal_ref:
            raise V2IntegrityStop("disposable V2 source seal changed before cleanup")
        await self.runtime.session.forget_close_and_remove()
        root = Path(terminal.clone_root)
        _remove_exact_private_tree(root, expected_parent=root.parent)
        for target in (root, *(Path(item) for item in terminal.cognee_scope_roots)):
            try:
                os.lstat(target)
            except FileNotFoundError:
                continue
            raise V2IntegrityStop("disposable V2 cleanup target remains")
        lifecycle = CloneLifecycleEvidence(
            terminal=terminal,
            terminal_disposition_ref=terminal_disposition_ref,
            disposed=True,
            cleanup_absence_verified=True,
        )
        self.source_owner.verify_seal()
        self.ledger.append_artifact_durable(
            lifecycle.lifecycle_ref,
            "clone-lifecycle",
            lifecycle.to_canonical(),
        )
        self._detach_after_cleanup()
        return lifecycle


@dataclass(slots=True)
class _V2OpenedClone:
    """Private ownership bundle for one already ledger-allocated baseline clone."""

    source_owner: V2LineageOwner = field(repr=False)
    source_seal: BaselineSeal
    allocation: DisposablePathAllocation
    paths: object = field(repr=False)
    learner: object = field(repr=False)
    store: object = field(repr=False)
    journal: object = field(repr=False)
    session: V2AcquisitionSession = field(repr=False)
    memory: object = field(repr=False)
    clone_before: tuple[tuple[str, str], ...]

    def __post_init__(self) -> None:
        if (
            type(self.source_owner) is not V2LineageOwner
            or type(self.source_seal) is not BaselineSeal
            or type(self.allocation) is not DisposablePathAllocation
            or type(self.session) is not V2AcquisitionSession
            or self.source_owner.verify_seal().seal_ref != self.source_seal.seal_ref
            or self.allocation.role != self.source_seal.arm
            and not self.allocation.role.startswith("recall-")
            or self.allocation.runtime_root != str(getattr(self.paths, "root", None))
            or self.allocation.cognee_scope_roots
            != (self.session.scope_spec.state_root,)
            or self.clone_before != self.source_seal.hashes
            or getattr(self.store, "path", None) != getattr(self.paths, "store", None)
            or getattr(self.journal, "path", None)
            != getattr(self.paths, "journal", None)
            or getattr(self.memory, "source", None) is not self.store
            or getattr(self.memory, "backend", None) is not self.session.backend
        ):
            raise V2IntegrityStop("opened V2 clone ownership differs")


async def _open_v2_disposable_clone(
    *,
    source_owner: V2LineageOwner,
    allocation: DisposablePathAllocation,
    scope_spec: V2AcquisitionScopeSpec,
    path_registry: PathAllocationRegistry,
    genesis: object,
    acquisition_opener: V2AcquisitionOpener,
    mechanics: V2LineageMechanics,
) -> _V2OpenedClone:
    """Byte-clone one sealed baseline, then rebuild its disposable projection."""

    if (
        type(source_owner) is not V2LineageOwner
        or type(allocation) is not DisposablePathAllocation
        or type(scope_spec) is not V2AcquisitionScopeSpec
        or type(path_registry) is not PathAllocationRegistry
        or type(mechanics) is not V2LineageMechanics
        or path_registry.ledger is not source_owner.ledger
        or path_registry._require(allocation.allocation_ref) != allocation
        or allocation.runtime_root == str(source_owner.root)
        or allocation.cognee_scope_roots != (scope_spec.state_root,)
        or scope_spec.purpose != source_owner.purpose
        or scope_spec.replicate_commitment != source_owner.replicate_commitment
        or scope_spec.arm != source_owner.arm
        or scope_spec.task_id != allocation.task_id
    ):
        raise V2IntegrityStop("V2 disposable clone construction boundary differs")
    expected_role_scope = {
        ("IN_FULL_NEUTRAL_12", "disposable-attempt"): "IN_FULL_NEUTRAL_12",
        ("IO_FULL_ORDINARY_12", "disposable-attempt"): "IO_FULL_ORDINARY_12",
        ("IN_FULL_NEUTRAL_12", "neutral-recall-capture"): "recall-neutral",
        ("IO_FULL_ORDINARY_12", "ordinary-recall-capture"): "recall-ordinary",
    }
    if expected_role_scope.get(
        (source_owner.arm, scope_spec.scope_kind)
    ) != allocation.role:
        raise V2IntegrityStop("V2 disposable role/scope capability differs")
    source_seal = source_owner.verify_seal()
    root = Path(allocation.runtime_root)
    _require_absent(root, "V2 disposable clone root")
    _require_absent(Path(scope_spec.state_root), "V2 disposable clone Cognee scope")
    paths = mechanics.clone_paths_factory(
        root=root,
        store=root / "cognitive.sqlite3",
        journal=root / "qwen-execution-journal.sqlite3",
        learner=root / "learner-state.bin",
    )
    session: V2AcquisitionSession | None = None
    try:
        helpers = _load_approved_r2_low_level_helpers()
        _call_r2_low_level(
            helpers["clone_closed_baseline"],
            source_owner.paths,
            paths,
            {
                name: digest
                for name, digest in source_seal.hashes
                if name in {"journal", "learner", "store"}
            },
        )
        snapshot = _read_private_bytes_bounded(
            paths.learner,
            maximum_bytes=MAXIMUM_LINEAGE_SNAPSHOT_BYTES,
            label="V2 disposable learner snapshot",
        )
        store = mechanics.transaction_store_factory(paths.store)
        head = store.audit_integrity()
        if (
            head is None
            or store.load_head_state() != snapshot
            or getattr(head, "snapshot_sha256", None)
            != "sha256:" + hashlib.sha256(snapshot).hexdigest()
        ):
            raise V2IntegrityStop("V2 disposable clone store/snapshot differs")
        learner = mechanics.restore_genesis(genesis, prospective_lesion=False)
        learner.restore_state(snapshot)
        if (
            learner.capture_state() != snapshot
            or learner.state_digest() != getattr(head, "state_digest", None)
        ):
            raise V2IntegrityStop("V2 disposable learner restore differs")
        journal = mechanics.journal_factory(paths.journal)
        journal.audit_integrity()
        session = await _open_v2_acquisition_session(
            scope_spec,
            opener=acquisition_opener,
        )
        memory = mechanics.memory_factory(source=store, backend=session.backend)
        await _maybe_await(memory.rebuild(limit=MAXIMUM_PROJECTION_RETRY))
        await _maybe_await(
            memory.retry_pending_projections(limit=MAXIMUM_PROJECTION_RETRY)
        )
        memory.assert_synchronized(store.acquisition_head())
        if store.pending_acquisition_projections(limit=1):
            raise V2IntegrityStop("V2 disposable clone projection outbox remains")
        clone_before = _hash_pairs(
            mechanics.closed_hashes(paths, store=store, journal=journal),
            "V2 disposable clone initial hashes",
        )
        if clone_before != source_seal.hashes:
            raise V2IntegrityStop("V2 disposable clone differs from its baseline")
        source_owner.verify_seal()
        return _V2OpenedClone(
            source_owner=source_owner,
            source_seal=source_seal,
            allocation=allocation,
            paths=paths,
            learner=learner,
            store=store,
            journal=journal,
            session=session,
            memory=memory,
            clone_before=clone_before,
        )
    except BaseException as error:
        primary = _redacted_failure(error, "V2_DISPOSABLE_CLONE_OPEN_FAILED")
        cleanup: list[V2IntegrityStop] = []
        if session is not None:
            try:
                await session.close_preserving_state()
            except BaseException as close_error:
                cleanup.append(
                    _redacted_failure(
                        close_error, "V2_DISPOSABLE_CLONE_WORKER_CLOSE_FAILED"
                    )
                )
        session = None
        if cleanup:
            raise ExceptionGroup(
                "V2 disposable clone construction preserving-close failed",
                [primary, *cleanup],
            ) from None
        raise primary from None


@dataclass(slots=True)
class _V2RecallCaptureOwner:
    opened: _V2OpenedClone | None = field(repr=False)
    capture: FrozenRecallCapture
    hits: tuple[object, ...] = field(repr=False)
    batch: object = field(repr=False)
    ledger: EvidenceLedger = field(repr=False)
    path_registry: PathAllocationRegistry = field(repr=False)

    def __post_init__(self) -> None:
        if (
            type(self.opened) is not _V2OpenedClone
            or type(self.capture) is not FrozenRecallCapture
            or type(self.ledger) is not EvidenceLedger
            or type(self.path_registry) is not PathAllocationRegistry
            or self.path_registry.ledger is not self.ledger
            or self.capture.cleanup_complete
            or self.capture.allocation_ref != self.opened.allocation.allocation_ref
            or self.capture.source_baseline_seal_ref
            != self.opened.source_seal.seal_ref
            or self.capture.cleanup_paths != self.opened.allocation.targets
        ):
            raise V2IntegrityStop("V2 recall capture owner binding differs")
        _validated_reference_hits(self.hits, label="V2 capture")
        self._verify_terminal_state()

    def _verify_terminal_state(self) -> tuple[tuple[str, str], ...]:
        if self.opened is None:
            raise V2IntegrityStop("V2 recall capture clone is unavailable")
        opened = self.opened
        if opened.source_owner.verify_seal().seal_ref != opened.source_seal.seal_ref:
            raise V2IntegrityStop("V2 recall capture source seal changed")
        opened.store.audit_integrity()
        opened.journal.audit_integrity()
        opened.memory.assert_synchronized(opened.store.acquisition_head())
        if opened.store.pending_acquisition_projections(limit=1):
            raise V2IntegrityStop("V2 recall capture projection outbox remains")
        opened.source_owner._mechanics.assert_quiescent(
            learner=opened.learner,
            store=opened.store,
            journal=opened.journal,
        )
        hashes = _hash_pairs(
            opened.source_owner._mechanics.closed_hashes(
                opened.paths,
                store=opened.store,
                journal=opened.journal,
            ),
            "V2 recall capture terminal hashes",
        )
        if (
            hashes != opened.clone_before
            or hashes != opened.source_seal.hashes
            or hashes != self.capture.capture_terminal_hashes
        ):
            raise V2IntegrityStop("V2 recall capture bytes changed")
        return hashes

    async def dispose_after_terminal(
        self, terminal_ref: str
    ) -> FrozenRecallCapture:
        if self.opened is None or terminal_ref != self.capture.terminal_ref:
            raise V2IntegrityStop("V2 recall capture cleanup boundary differs")
        self._verify_terminal_state()
        self.ledger.require_artifact(
            terminal_ref,
            "recall-capture-terminal",
            self.capture.terminal_payload,
        )
        opened = self.opened
        opened.source_owner.verify_seal()
        await opened.session.forget_close_and_remove()
        root = Path(opened.allocation.runtime_root)
        _remove_exact_private_tree(root, expected_parent=root.parent)
        for target in opened.allocation.targets:
            try:
                os.lstat(target)
            except FileNotFoundError:
                continue
            raise V2IntegrityStop("V2 recall capture cleanup target remains")
        updated = replace(
            self.capture,
            capture_disposed=True,
            cleanup_absence_verified=True,
        )
        self.opened = None
        self.capture = updated
        self.ledger.append_artifact_durable(
            updated.cleanup_ref,
            "recall-capture-cleanup",
            updated.cleanup_payload,
        )
        return updated


@dataclass(slots=True)
class _PendingPersistentScopeRetention:
    """In-memory recovery authority until one failed scope is durably bound."""

    task_id: str
    replicate_commitment: str
    arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"]
    allocation_ref: str
    scope_ref: str
    state_root: str
    source_owner: V2LineageOwner = field(repr=False)
    reason_code: str = "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED"
    stage_ref: str | None = None
    session: V2AcquisitionSession | None = field(default=None, repr=False)

    def __post_init__(self) -> None:
        for value, label in (
            (self.task_id, "pending retained task id"),
            (self.replicate_commitment, "pending retained replicate"),
            (self.allocation_ref, "pending retained allocation"),
            (self.scope_ref, "pending retained scope"),
        ):
            _ref(value, label)
        source = self.source_owner
        if self.stage_ref is not None:
            _ref(self.stage_ref, "pending retained stage ref")
        if (
            self.arm not in STATEFUL_ARMS
            or type(source) is not V2LineageOwner
            or source.replicate_commitment != self.replicate_commitment
            or source.arm != self.arm
            or source.allocation_ref != self.allocation_ref
            or source.scope_spec.scope_ref != self.scope_ref
            or source.scope_spec.state_root != self.state_root
            or self.reason_code
            not in (
                "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED",
                "V2_PERSISTENT_ATTEMPT_POST_STAGE_FAILED",
            )
            or (self.stage_ref is None)
            != (
                self.reason_code
                == "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED"
            )
        ):
            raise V2IntegrityStop("pending retained scope authority differs")
        if self.session is not None and (
            type(self.session) is not V2AcquisitionSession
            or self.session.scope_spec != source.scope_spec
        ):
            raise V2IntegrityStop("pending retained session authority differs")


@dataclass(slots=True)
class _PendingDisposableAllocationRetention:
    """Recovery authority until one failed allocation is durably partitioned."""

    allocation: DisposablePathAllocation
    source_owner: V2LineageOwner | None = field(repr=False)
    source_seal: BaselineSeal | None
    failure_boundary_code: str
    stage_ref: str | None = None
    session: V2AcquisitionSession | None = field(default=None, repr=False)

    def __post_init__(self) -> None:
        if type(self.allocation) is not DisposablePathAllocation:
            raise TypeError("pending disposable allocation differs")
        if (
            type(self.failure_boundary_code) is not str
            or _BOUNDARY_FAILURE_CODE_RE.fullmatch(self.failure_boundary_code) is None
        ):
            raise ValueError("pending disposable failure boundary differs")
        if self.stage_ref is not None:
            _ref(self.stage_ref, "pending disposable stage ref")
        stateless = self.allocation.role in STATELESS_ARMS
        if stateless:
            if self.source_owner is not None or self.source_seal is not None:
                raise V2InvariantError(
                    "pending stateless allocation acquired source authority"
                )
        else:
            expected_arm = {
                "recall-neutral": "IN_FULL_NEUTRAL_12",
                "recall-ordinary": "IO_FULL_ORDINARY_12",
            }.get(self.allocation.role, self.allocation.role)
            if (
                type(self.source_owner) is not V2LineageOwner
                or type(self.source_seal) is not BaselineSeal
                or self.source_owner.arm != expected_arm
                or self.source_owner.purpose != self.allocation.purpose
                or self.source_owner.replicate_commitment
                != self.allocation.replicate_commitment
                or self.source_owner.verify_seal().seal_ref
                != self.source_seal.seal_ref
            ):
                raise V2IntegrityStop("pending disposable source authority differs")
        if self.session is not None and (
            type(self.session) is not V2AcquisitionSession
            or self.allocation.cognee_scope_roots
            != (self.session.scope_spec.state_root,)
        ):
            raise V2IntegrityStop("pending disposable session authority differs")


@dataclass(slots=True)
class V2ProductRuntimeOwner:
    """Single-owner production composition for V2 lineage, recall, and attempts."""

    purpose: Purpose
    foundation: V2FoundationOwner = field(repr=False)
    genesis: object = field(repr=False)
    lineages: V2LineageSetOwner = field(repr=False)
    ledger: EvidenceLedger = field(repr=False)
    path_registry: PathAllocationRegistry = field(repr=False)
    resources: ResourceLedger = field(repr=False)
    acquisition_opener: V2AcquisitionOpener = field(repr=False)
    mechanics: V2LineageMechanics = field(repr=False)
    arm_runtime_parent: Path
    cognee_scope_parent: Path
    _frozen: FrozenAdaptationState | None = field(
        default=None, init=False, repr=False
    )
    _adaptation_owners: dict[tuple[str, Arm], V2StatefulAttemptOwner] = field(
        default_factory=dict, init=False, repr=False
    )
    _active_by_stage: dict[str, object] = field(
        default_factory=dict, init=False, repr=False
    )
    _active_cells: dict[tuple[str, Arm], str] = field(
        default_factory=dict, init=False, repr=False
    )
    _clone_terminal_stages: dict[str, str] = field(
        default_factory=dict, init=False, repr=False
    )
    _capture_owners: dict[str, _V2RecallCaptureOwner] = field(
        default_factory=dict, init=False, repr=False
    )
    _record_embedding_cache: dict[
        str, tuple[str, dict[str, tuple[float, ...]]]
    ] = field(default_factory=dict, init=False, repr=False)
    _retained_preparation_scopes: dict[
        str, RetainedPreparationScopeEvidence
    ] = field(default_factory=dict, init=False, repr=False)
    _pending_scope_retentions: dict[
        str, _PendingPersistentScopeRetention
    ] = field(default_factory=dict, init=False, repr=False)
    _retained_disposable_allocations: dict[
        str, RetainedDisposableAllocationEvidence
    ] = field(default_factory=dict, init=False, repr=False)
    _pending_disposable_retentions: dict[
        str, _PendingDisposableAllocationRetention
    ] = field(default_factory=dict, init=False, repr=False)
    _closed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        if (
            type(self.foundation) is not V2FoundationOwner
            or self.foundation._closed
            or type(self.foundation.guard) is not GuardedLocalQwenBoundary
            or self.foundation.guard.resources is not self.resources
            or type(self.lineages) is not V2LineageSetOwner
            or self.lineages._closed
            or self.lineages.purpose != purpose
            or type(self.ledger) is not EvidenceLedger
            or self.ledger._closed
            or type(self.path_registry) is not PathAllocationRegistry
            or self.path_registry.ledger is not self.ledger
            or self.path_registry.purpose != purpose
            or type(self.resources) is not ResourceLedger
            or self.resources.mode.value != purpose
            or not callable(self.acquisition_opener)
            or type(self.mechanics) is not V2LineageMechanics
            or self.lineages.arm_runtime_parent != self.arm_runtime_parent
            or self.lineages.cognee_scope_parent != self.cognee_scope_parent
            or any(item.ledger is not self.ledger for item in self.lineages.owners)
            or any(
                item._mechanics != self.mechanics for item in self.lineages.owners
            )
        ):
            raise V2IntegrityStop("V2 product-runtime owner inputs differ")
        for parent, label in (
            (self.arm_runtime_parent, "V2 product arm-runtime parent"),
            (self.cognee_scope_parent, "V2 product Cognee-scope parent"),
        ):
            _require_owned_directory(parent, expected_mode=0o700, label=label)
        manifest = self.foundation.manifest
        if any(
            item.model_ref != getattr(manifest, "model_ref", None)
            or item.encoder_ref != getattr(manifest, "encoder_ref", None)
            for item in self.lineages.owners
        ):
            raise V2IntegrityStop("V2 lineage/foundation identity differs")
        validate = getattr(self.genesis, "validate_artifacts", None)
        genesis_root = getattr(self.genesis, "root", None)
        expected_genesis_root = self.arm_runtime_parent.parent / "genesis"
        injected_flags = {
            item.allocation.injected_paths for item in self.lineages.owners
        }
        if (
            not callable(validate)
            or genesis_root != expected_genesis_root
            or len(injected_flags) != 1
        ):
            raise TypeError("V2 product owner genesis differs")
        validate()
        if injected_flags == {False}:
            helpers = _load_approved_r2_low_level_helpers()
            if (
                type(self.genesis) is not helpers["FreshGenesisBundle"]
                or self.acquisition_opener is not open_v2_acquisition_scope_live
                or self.mechanics != _live_v2_lineage_mechanics()
                or self.arm_runtime_parent
                != STATE_ROOT / f"{purpose}-v1" / "arm-runtime"
                or self.cognee_scope_parent
                != STATE_ROOT / f"{purpose}-v1" / "cognee-scopes"
            ):
                raise V2IntegrityStop("V2 live product capability differs")

    @property
    def _guard(self) -> GuardedLocalQwenBoundary:
        if self._closed or type(self.foundation.guard) is not GuardedLocalQwenBoundary:
            raise V2IntegrityStop("V2 product owner foundation is unavailable")
        return self.foundation.guard

    def _tokenize_prompt(self, prompt: str) -> tuple[int, ...]:
        loaded = self.foundation.loaded
        tokenizer = getattr(loaded, "tokenizer", None)
        return frozen_qwen_chat_token_ids(
            tokenizer,
            prompt,
            enable_thinking=False,
        )

    def _allocation_slug(
        self,
        *,
        task_id: str,
        replicate_commitment: str,
        role: str,
    ) -> str:
        digest = canonical_ref(
            "v2-disposable-path",
            {
                "protocol_identity": PROTOCOL_IDENTITY,
                "purpose": self.purpose,
                "replicate_commitment": replicate_commitment,
                "role": role,
                "task_id": task_id,
            },
        ).removeprefix("sha256:")[:24]
        return f"attempt-{digest}"

    def _register_disposable(
        self,
        *,
        task_id: str,
        replicate_commitment: str,
        role: str,
        source_arm: Literal[
            "IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"
        ]
        | None = None,
        scope_kind: V2AcquisitionScopeKind | None = None,
    ) -> tuple[DisposablePathAllocation, V2AcquisitionScopeSpec | None]:
        if self._closed:
            raise V2IntegrityStop("V2 product owner is closed")
        task_id = _ref(task_id, "V2 disposable task id")
        replicate_commitment = _ref(
            replicate_commitment, "V2 disposable replicate"
        )
        if (source_arm is None) != (scope_kind is None):
            raise V2InvariantError("V2 disposable scope inputs differ")
        slug = self._allocation_slug(
            task_id=task_id,
            replicate_commitment=replicate_commitment,
            role=role,
        )
        scope_spec: V2AcquisitionScopeSpec | None = None
        scopes: tuple[str, ...] = ()
        if source_arm is not None and scope_kind is not None:
            scope_spec = V2AcquisitionScopeSpec.create(
                purpose=self.purpose,
                replicate_commitment=replicate_commitment,
                arm=source_arm,
                scope_kind=scope_kind,
                state_parent=self.cognee_scope_parent,
                task_id=task_id,
            )
            scopes = (scope_spec.state_root,)
        allocation = DisposablePathAllocation(
            purpose=self.purpose,
            task_id=task_id,
            replicate_commitment=replicate_commitment,
            role=role,
            runtime_root=str(self.arm_runtime_parent / slug),
            cognee_scope_roots=scopes,
        )
        self.path_registry.register(allocation)
        return allocation, scope_spec

    def _retain_failed_preparation_scope(
        self,
        *,
        pending: _PendingPersistentScopeRetention,
    ) -> RetainedPreparationScopeEvidence | None:
        """Durably bind exact terminal scope/lineage bytes without disposal."""

        source = pending.source_owner
        session = pending.session
        if (
            type(pending) is not _PendingPersistentScopeRetention
            or source.ledger is not self.ledger
            or self.ledger._closed
            or (
                session is not None
                and (
                    session._closed is not True
                    or session.binding is not None
                    or session.backend is not None
                    or session._worker_handle is not None
                    or session.scope_spec != source.scope_spec
                )
            )
        ):
            raise V2IntegrityStop("retained preparation scope authority differs")
        try:
            identity = _private_root_identity(
                source.scope_spec.state_root,
                "failed preparation retained scope",
            )
        except FileNotFoundError:
            return None
        lineage_identity, hashes, lineage_tree = _raw_retained_lineage_state(
            source
        )
        scope_tree = _terminal_scope_tree_snapshot(identity[0])
        evidence = RetainedPreparationScopeEvidence(
            purpose=self.purpose,
            task_id=pending.task_id,
            replicate_commitment=source.replicate_commitment,
            arm=source.arm,
            allocation_ref=source.allocation_ref,
            scope_ref=source.scope_spec.scope_ref,
            state_root=identity[0],
            dataset_id=None if session is None else session.dataset_id,
            root_device=identity[1],
            root_inode=identity[2],
            lineage_root=lineage_identity[0],
            lineage_root_device=lineage_identity[1],
            lineage_root_inode=lineage_identity[2],
            lineage_hashes=hashes,
            lineage_tree=lineage_tree,
            scope_tree=scope_tree,
            stage_ref=pending.stage_ref,
            worker_terminal=True,
            reason_code=pending.reason_code,
        )
        existing = self._retained_preparation_scopes.get(evidence.scope_ref)
        if existing is not None and existing != evidence:
            raise V2IntegrityStop("retained preparation scope was rebound")
        self.ledger.append_artifact_durable(
            evidence.evidence_ref,
            "retained-preparation-scope",
            evidence.to_canonical(),
        )
        self._retained_preparation_scopes[evidence.scope_ref] = evidence
        return evidence

    def _queue_failed_disposable_allocation(
        self,
        *,
        allocation: DisposablePathAllocation,
        source_owner: V2LineageOwner | None,
        source_seal: BaselineSeal | None,
        failure_boundary_code: str,
        stage_ref: str | None,
        session: V2AcquisitionSession | None,
    ) -> _PendingDisposableAllocationRetention:
        pending = _PendingDisposableAllocationRetention(
            allocation=allocation,
            source_owner=source_owner,
            source_seal=source_seal,
            failure_boundary_code=failure_boundary_code,
            stage_ref=stage_ref,
            session=session,
        )
        existing = self._pending_disposable_retentions.get(
            allocation.allocation_ref
        )
        if existing is not None:
            if (
                existing.allocation != pending.allocation
                or existing.source_owner is not pending.source_owner
                or existing.source_seal != pending.source_seal
                or existing.failure_boundary_code != pending.failure_boundary_code
                or existing.stage_ref != pending.stage_ref
            ):
                raise V2IntegrityStop("pending disposable allocation was rebound")
            if existing.session is None:
                existing.session = session
            elif session is not None and existing.session is not session:
                raise V2IntegrityStop("pending disposable session was rebound")
            return existing
        if allocation.allocation_ref in self._retained_disposable_allocations:
            raise V2IntegrityStop("retained disposable allocation was requeued")
        self._pending_disposable_retentions[allocation.allocation_ref] = pending
        return pending

    async def _retain_failed_disposable_allocation(
        self,
        pending: _PendingDisposableAllocationRetention,
    ) -> RetainedDisposableAllocationEvidence | None:
        """Terminalize workers, partition targets, then durably bind survivors."""

        if (
            type(pending) is not _PendingDisposableAllocationRetention
            or self._pending_disposable_retentions.get(
                pending.allocation.allocation_ref
            )
            is not pending
            or self.path_registry._require(pending.allocation.allocation_ref)
            != pending.allocation
            or self.ledger._closed
        ):
            raise V2IntegrityStop("pending disposable retention authority differs")
        session = pending.session
        if session is not None and not session._closed:
            await session.close_preserving_state()
        await _drain_unresolved_v2_cognee_workers()
        _assert_no_unresolved_v2_cognee_workers()
        if session is not None and (
            session._closed is not True
            or session.binding is not None
            or session.backend is not None
            or session._worker_handle is not None
        ):
            raise V2IntegrityStop("retained disposable session is not terminal")
        if pending.source_owner is not None:
            if (
                pending.source_seal is None
                or pending.source_owner.verify_seal().seal_ref
                != pending.source_seal.seal_ref
            ):
                raise V2IntegrityStop("retained disposable source seal changed")

        extant: list[RetainedDisposableTargetEvidence] = []
        absent: list[str] = []
        for index, target_text in enumerate(pending.allocation.targets):
            try:
                identity = _private_root_identity(
                    target_text, "failed disposable retained target"
                )
            except FileNotFoundError:
                absent.append(target_text)
                continue
            extant.append(
                RetainedDisposableTargetEvidence(
                    target_kind=(
                        "runtime-root" if index == 0 else "cognee-scope-root"
                    ),
                    target_path=identity[0],
                    root_device=identity[1],
                    root_inode=identity[2],
                    tree=_terminal_scope_tree_snapshot(identity[0]),
                )
            )
        if not extant:
            self.path_registry.mark_closed(pending.allocation.allocation_ref)
            self._pending_disposable_retentions.pop(
                pending.allocation.allocation_ref
            )
            return None
        evidence = RetainedDisposableAllocationEvidence(
            purpose=pending.allocation.purpose,
            task_id=pending.allocation.task_id,
            replicate_commitment=pending.allocation.replicate_commitment,
            role=pending.allocation.role,
            allocation_ref=pending.allocation.allocation_ref,
            source_baseline_seal_ref=(
                None
                if pending.source_seal is None
                else pending.source_seal.seal_ref
            ),
            dataset_id=None if session is None else session.dataset_id,
            stage_ref=pending.stage_ref,
            failure_boundary_code=pending.failure_boundary_code,
            extant_targets=tuple(extant),
            absent_targets=tuple(absent),
            worker_terminal=True,
        )
        existing = self._retained_disposable_allocations.get(
            evidence.allocation_ref
        )
        if existing is not None and existing != evidence:
            raise V2IntegrityStop("retained disposable allocation was rebound")
        self.ledger.append_artifact_durable(
            evidence.evidence_ref,
            "retained-disposable-allocation",
            evidence.to_canonical(),
        )
        self.path_registry.mark_retained(evidence)
        self._retained_disposable_allocations[evidence.allocation_ref] = evidence
        self._pending_disposable_retentions.pop(evidence.allocation_ref)
        return evidence

    async def _retain_failed_disposable_or_raise(
        self,
        *,
        primary: V2IntegrityStop,
        pending: _PendingDisposableAllocationRetention,
        message: str,
    ) -> None:
        try:
            await self._retain_failed_disposable_allocation(pending)
        except BaseException as error:
            cleanup = _redacted_cleanup_failure(
                error, "V2_RETAINED_DISPOSABLE_EVIDENCE_APPEND_FAILED"
            )
            raise ExceptionGroup(message, [primary, cleanup]) from None

    async def _open_persistent_adaptation(
        self,
        scheduled: ScheduledAttempt,
    ) -> tuple[PromptPlan, V2StatefulAttemptOwner]:
        if scheduled.phase != "adaptation" or scheduled.arm not in STATEFUL_ARMS:
            raise V2InvariantError("persistent V2 preparation differs")
        source = self.lineages.owner_for(
            scheduled.replicate_commitment, scheduled.arm
        )
        source._assert_binding()
        if source._seal is not None:
            raise V2IntegrityStop("frozen V2 lineage cannot adapt")
        pending = _PendingPersistentScopeRetention(
            task_id=scheduled.task_id,
            replicate_commitment=source.replicate_commitment,
            arm=source.arm,
            allocation_ref=source.allocation_ref,
            scope_ref=source.scope_spec.scope_ref,
            state_root=source.scope_spec.state_root,
            source_owner=source,
        )
        if pending.scope_ref in self._pending_scope_retentions:
            raise V2IntegrityStop("persistent preparation scope is already pending")
        self._pending_scope_retentions[pending.scope_ref] = pending
        session: V2AcquisitionSession | None = None
        try:
            session = await _open_v2_acquisition_session(
                source.scope_spec,
                opener=self.acquisition_opener,
            )
            pending.session = session
            memory = self.mechanics.memory_factory(
                source=source.store, backend=session.backend
            )
            await _maybe_await(memory.rebuild(limit=MAXIMUM_PROJECTION_RETRY))
            await _maybe_await(
                memory.retry_pending_projections(limit=MAXIMUM_PROJECTION_RETRY)
            )
            memory.assert_synchronized(source.store.acquisition_head())
            task_text = _render_v2_public_task(scheduled.task)
            if scheduled.arm == "IN_FULL_NEUTRAL_12":
                hits = _neutral_reference_hits(
                    source.store, source.neutral_episode_refs
                )
                batch = memory.recall_from_hits(
                    hits,
                    limit=RECALL_SLOTS,
                    frozen_origin=False,
                )
                if getattr(batch, "rejected", None) != ():
                    raise V2IntegrityStop("V2 adaptation recall rejected a hit")
            else:
                hits, batch = await _bounded_ordinary_recall(
                    query=task_text,
                    store=source.store,
                    backend=session.backend,
                    memory=memory,
                    frozen_origin=False,
                    label="V2 adaptation ordinary",
                )
            history = _history_plan_from_recall_batch(
                task_id=scheduled.task_id,
                arm=scheduled.arm,
                batch=batch,
            )
            if scheduled.arm == "IN_FULL_NEUTRAL_12" and tuple(
                item.source_ref for item in history.presentations
            ) != source.neutral_episode_refs:
                raise V2IntegrityStop("V2 adaptation neutral source order differs")
            prompt = _unpadded_prompt_plan(
                task_text=task_text,
                history_plan=history,
                tokenize_chat_prompt=self._tokenize_prompt,
            )
            runtime = await _build_stateful_product_runtime(
                arm=scheduled.arm,
                task_text=task_text,
                history_plan=history,
                frozen_hits=hits,
                io=self.foundation.io,
                manifest=self.foundation.manifest,
                guard=self._guard,
                learner=source.learner,
                store=source.store,
                journal=source.journal,
                canonical_memory=memory,
                session=session,
                replay_frozen_origin=False,
            )
            owner = V2StatefulAttemptOwner(
                runtime=runtime,
                source_owner=source,
                ledger=self.ledger,
                quiesce_runtime=_load_approved_r2_low_level_helpers()[
                    "_quiesce_successor_runtime"
                ],
            )
            return prompt, owner
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED"
            )
            cleanup: list[V2IntegrityStop] = []
            if session is not None and not session._closed:
                try:
                    await session.close_preserving_state()
                except BaseException as cleanup_error:
                    cleanup.append(
                        _redacted_failure(
                            cleanup_error,
                            "V2_PERSISTENT_PREPARATION_WORKER_CLOSE_FAILED",
                        )
                    )
            if session is None or not session._closed:
                try:
                    await _drain_unresolved_v2_cognee_workers()
                    _assert_no_unresolved_v2_cognee_workers()
                    if session is not None and not session._closed:
                        await session.close_preserving_state()
                except BaseException as cleanup_error:
                    cleanup.append(
                        _redacted_failure(
                            cleanup_error,
                            "V2_PERSISTENT_PREPARATION_WORKER_DRAIN_FAILED",
                        )
                    )
            terminal = session._closed if session is not None else not (
                _UNRESOLVED_V2_COGNEE_HANDLES
                or _UNRESOLVED_V2_COGNEE_BINDINGS
                or _UNRESOLVED_V2_COGNEE_STARTS
            )
            if terminal:
                try:
                    _assert_no_unresolved_v2_cognee_workers()
                    try:
                        os.lstat(pending.state_root)
                    except FileNotFoundError:
                        self._pending_scope_retentions.pop(pending.scope_ref)
                    else:
                        self._retain_failed_preparation_scope(pending=pending)
                        self._pending_scope_retentions.pop(pending.scope_ref)
                except BaseException as retention_error:
                    cleanup.append(
                        _redacted_failure(
                            retention_error,
                            "V2_PERSISTENT_PREPARATION_RETENTION_FAILED",
                        )
                    )
            if cleanup:
                raise ExceptionGroup(
                    "V2 persistent preparation and retention failed",
                    [primary, *cleanup],
                ) from None
            raise primary from None

    async def prepare_adaptation_attempt(
        self, scheduled: ScheduledAttempt
    ) -> PromptPlan:
        key = scheduled.attempt_key
        if self._frozen is not None or key in self._adaptation_owners:
            raise V2IntegrityStop("V2 adaptation attempt preparation was reused")
        prompt, owner = await self._open_persistent_adaptation(scheduled)
        self._adaptation_owners[key] = owner
        pending = self._pending_scope_retentions.pop(
            owner.source_owner.scope_spec.scope_ref, None
        )
        if pending is None or pending.session is not owner.runtime.session:
            self._adaptation_owners.pop(key, None)
            raise V2IntegrityStop("persistent preparation authority was lost")
        return prompt

    def _embedding_rows(
        self,
        *,
        task_id: str,
        planning_ref: str,
        texts: Sequence[str],
    ) -> tuple[tuple[float, ...], ...]:
        frozen_texts = tuple(texts)
        if not frozen_texts or any(type(item) is not str for item in frozen_texts):
            raise TypeError("V2 planning texts differ")
        value: object | None = None
        with self._guard.planning(
            task_id=task_id,
            planning_ref=planning_ref,
            maximum_embedding_rows=len(frozen_texts),
        ):
            value = self.foundation.io.embed(frozen_texts)
        try:
            detach = getattr(value, "detach", None)
            if callable(detach):
                value = detach()
            cpu = getattr(value, "cpu", None)
            if callable(cpu):
                value = cpu()
            tolist = getattr(value, "tolist", None)
            rows = tolist() if callable(tolist) else value
            if type(rows) not in (tuple, list) or len(rows) != len(frozen_texts):
                raise V2IntegrityStop("V2 planning embedding matrix differs")
            output = tuple(
                _vector(row, "V2 planning embedding row") for row in rows
            )
            if len({len(row) for row in output}) != 1:
                raise V2IntegrityStop("V2 planning embedding widths differ")
            return output
        finally:
            value = None

    def _catalog_embeddings(
        self,
        *,
        task_id: str,
        catalog: DonorCatalog,
    ) -> dict[str, tuple[float, ...]]:
        cached = self._record_embedding_cache.get(catalog.replicate_commitment)
        if cached is not None:
            if cached[0] != catalog.catalog_ref:
                raise V2IntegrityStop("V2 cached catalog identity changed")
            return dict(cached[1])
        texts = tuple(item.public_record_text for item in catalog.entries)
        rows = self._embedding_rows(
            task_id=task_id,
            planning_ref=canonical_ref(
                "v2-catalog-embedding-plan",
                {"catalog_ref": catalog.catalog_ref, "task_id": task_id},
            ),
            texts=texts,
        )
        mapping = {
            item.record_ref: row
            for item, row in zip(catalog.entries, rows, strict=True)
        }
        self._record_embedding_cache[catalog.replicate_commitment] = (
            catalog.catalog_ref,
            mapping,
        )
        return dict(mapping)

    async def _capture_recall(
        self,
        *,
        task: dict[str, object],
        context: TaskPreparationContext,
        kind: Literal["neutral", "ordinary"],
    ) -> tuple[_V2RecallCaptureOwner, HistoryPlan]:
        arm: Literal["IN_FULL_NEUTRAL_12", "IO_FULL_ORDINARY_12"] = (
            "IN_FULL_NEUTRAL_12" if kind == "neutral" else "IO_FULL_ORDINARY_12"
        )
        source = self.lineages.owner_for(context.replicate_commitment, arm)
        expected_seal = context.in_baseline if kind == "neutral" else context.io_baseline
        if source.verify_seal().seal_ref != expected_seal.seal_ref:
            raise V2IntegrityStop("V2 capture source seal differs")
        scope_kind: V2AcquisitionScopeKind = (
            "neutral-recall-capture"
            if kind == "neutral"
            else "ordinary-recall-capture"
        )
        allocation, scope_spec = self._register_disposable(
            task_id=context.task_id,
            replicate_commitment=context.replicate_commitment,
            role=f"recall-{kind}",
            source_arm=arm,
            scope_kind=scope_kind,
        )
        assert scope_spec is not None
        try:
            opened = await _open_v2_disposable_clone(
                source_owner=source,
                allocation=allocation,
                scope_spec=scope_spec,
                path_registry=self.path_registry,
                genesis=self.genesis,
                acquisition_opener=self.acquisition_opener,
                mechanics=self.mechanics,
            )
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_DISPOSABLE_CLONE_OPEN_FAILED"
            )
            pending = self._queue_failed_disposable_allocation(
                allocation=allocation,
                source_owner=source,
                source_seal=expected_seal,
                failure_boundary_code="V2_DISPOSABLE_CLONE_OPEN_FAILED",
                stage_ref=None,
                session=None,
            )
            await self._retain_failed_disposable_or_raise(
                primary=primary,
                pending=pending,
                message="V2 recall clone open and retention failed",
            )
            raise primary from None
        try:
            task_text = _render_v2_public_task(task)
            if kind == "neutral":
                hits = _neutral_reference_hits(
                    opened.store, expected_seal.neutral_episode_refs
                )
                hits = _validated_reference_hits(
                    hits, label=f"V2 {kind} capture"
                )
                batch = opened.memory.recall_from_hits(
                    hits,
                    limit=RECALL_SLOTS,
                    frozen_origin=True,
                )
            else:
                hits, batch = await _bounded_ordinary_recall(
                    query=task_text,
                    store=opened.store,
                    backend=opened.session.backend,
                    memory=opened.memory,
                    frozen_origin=True,
                    label="V2 frozen ordinary",
                )
            if (
                getattr(batch, "rejected", None) != ()
                or len(getattr(batch, "items", ())) != RECALL_SLOTS
            ):
                raise V2IntegrityStop("V2 frozen recall capture differs")
            source.verify_seal()
            opened.store.audit_integrity()
            opened.journal.audit_integrity()
            opened.memory.assert_synchronized(opened.store.acquisition_head())
            if opened.store.pending_acquisition_projections(limit=1):
                raise V2IntegrityStop("V2 capture projection outbox remains")
            self.mechanics.assert_quiescent(
                learner=opened.learner,
                store=opened.store,
                journal=opened.journal,
            )
            terminal_hashes = _hash_pairs(
                self.mechanics.closed_hashes(
                    opened.paths,
                    store=opened.store,
                    journal=opened.journal,
                ),
                "V2 recall capture terminal hashes",
            )
            if (
                terminal_hashes != opened.clone_before
                or terminal_hashes != expected_seal.hashes
            ):
                raise V2IntegrityStop("V2 recall capture changed its clone")
            capture = freeze_recall_capture(
                task=task,
                kind=kind,
                recall_batch=batch,
                query_ref=content_ref({"query": task_text}),
                backend_binding_ref=canonical_ref(
                    "v2-capture-backend-binding",
                    {
                        "dataset_id": opened.session.dataset_id,
                        "scope_ref": opened.session.scope_spec.scope_ref,
                    },
                ),
                source_baseline_seal_ref=expected_seal.seal_ref,
                capture_clone_ref=canonical_ref(
                    "v2-recall-capture-clone",
                    {
                        "allocation_ref": allocation.allocation_ref,
                        "clone_before": dict(opened.clone_before),
                    },
                ),
                capture_quiescent=True,
                capture_disposed=False,
                cleanup_absence_verified=False,
                cleanup_paths=allocation.targets,
                source_root=expected_seal.root,
                source_hashes=dict(expected_seal.hashes),
                capture_terminal_hashes=dict(terminal_hashes),
                allocation_ref=allocation.allocation_ref,
            )
            if kind == "neutral" and tuple(
                item.source_ref for item in capture.presentations
            ) != expected_seal.neutral_episode_refs:
                raise V2IntegrityStop("V2 neutral capture source refs differ")
            plan = recall_history_plan(
                context.task_id,
                arm,
                capture,
                neutral=kind == "neutral",
            )
            owner = _V2RecallCaptureOwner(
                opened=opened,
                capture=capture,
                hits=hits,
                batch=batch,
                ledger=self.ledger,
                path_registry=self.path_registry,
            )
            self.ledger.append_artifact_durable(
                capture.terminal_ref,
                "recall-capture-terminal",
                capture.terminal_payload,
            )
            self._capture_owners[capture.terminal_ref] = owner
            return owner, plan
        except BaseException as error:
            primary = _redacted_failure(error, "V2_RECALL_CAPTURE_FAILED")
            pending = self._queue_failed_disposable_allocation(
                allocation=allocation,
                source_owner=source,
                source_seal=expected_seal,
                failure_boundary_code="V2_RECALL_CAPTURE_FAILED",
                stage_ref=None,
                session=opened.session,
            )
            await self._retain_failed_disposable_or_raise(
                primary=primary,
                pending=pending,
                message="V2 recall capture and retention failed",
            )
            raise primary from None

    async def prepare_task_block(
        self,
        task: dict[str, object],
        context: TaskPreparationContext,
    ) -> PreparedTaskBlock:
        if (
            self._closed
            or type(context) is not TaskPreparationContext
            or self._frozen is None
            or context.frozen_state_ref != self._frozen.freeze_ref
            or context.task_id != _task_canonical(task)["task_id"]
        ):
            raise V2IntegrityStop("V2 product task preparation boundary differs")
        neutral_owner, neutral_stateful = await self._capture_recall(
            task=task, context=context, kind="neutral"
        )
        ordinary_owner, ordinary_stateful = await self._capture_recall(
            task=task, context=context, kind="ordinary"
        )
        in_source = self.lineages.owner_for(
            context.replicate_commitment, "IN_FULL_NEUTRAL_12"
        )
        neutral_episodes = tuple(
            in_source.store.get_episode(ref)
            for ref in context.in_baseline.neutral_episode_refs
        )
        catalog_embeddings = self._catalog_embeddings(
            task_id=context.task_id,
            catalog=context.donor_catalog,
        )
        task_text = _render_v2_public_task(task)
        task_embedding = self._embedding_rows(
            task_id=context.task_id,
            planning_ref=canonical_ref(
                "v2-task-embedding-plan",
                {
                    "catalog_ref": context.donor_catalog.catalog_ref,
                    "public_task_ref": context.public_task_ref,
                },
            ),
            texts=(task_text,),
        )[0]
        selection_plans = {
            mode: build_ranked_selection_plan(
                task=task,
                catalog=context.donor_catalog,
                mode=mode,
                task_embedding=task_embedding,
                record_embeddings=catalog_embeddings,
            )
            for mode in ("cross-low", "same-low", "same-high")
        }
        validate_disjoint_same_family_selections(
            selection_plans["same-low"].selected,
            selection_plans["same-high"].selected,
        )
        history_plans: dict[Arm, HistoryPlan] = {
            "F0_NEUTRAL_FORMATTED_12": recall_history_plan(
                context.task_id,
                "F0_NEUTRAL_FORMATTED_12",
                neutral_owner.capture,
                neutral=True,
            ),
            "IN_FULL_NEUTRAL_12": neutral_stateful,
            "O0_ORDINARY_FROZEN_12": recall_history_plan(
                context.task_id,
                "O0_ORDINARY_FROZEN_12",
                ordinary_owner.capture,
                neutral=False,
            ),
            "IO_FULL_ORDINARY_12": ordinary_stateful,
        }
        for arm, mode in (
            ("X0_CROSS_FAMILY_LOW_6_NEUTRAL_6", "cross-low"),
            ("S0_SAME_FAMILY_LOW_6_NEUTRAL_6", "same-low"),
            ("S1_SAME_FAMILY_HIGH_6_NEUTRAL_6", "same-high"),
        ):
            history_plans[arm] = ranked_control_history_plan(
                context.task_id,
                arm,
                selection_plans[mode],
                neutral_episodes,
            )
        padded, equalities = plan_equalized_prompts(
            task_text=task_text,
            history_plans=history_plans,
            tokenize_chat_prompt=self._tokenize_prompt,
        )
        prompts: dict[Arm, PromptPlan] = dict(padded)
        prompts["N0_NATIVE_NO_HISTORY"] = native_prompt_plan(
            task_id=context.task_id,
            task_text=task_text,
            tokenize_chat_prompt=self._tokenize_prompt,
        )
        replay = PrivateRecallReplay(
            ordinary_owner.capture,
            ordinary_owner.hits,
            ordinary_owner.batch,
        )
        return PreparedTaskBlock.create(
            task=task,
            prompt_plans=prompts,
            pair_equalities=equalities,
            frozen=self._frozen,
            neutral_recall=neutral_owner.capture,
            ordinary_recall=ordinary_owner.capture,
            ordinary_private_replay=replay,
        )

    async def dispose_recall_captures(
        self,
        pending: PreparedTaskBlock,
        terminal_refs: tuple[str, str],
    ) -> PreparedTaskBlock:
        if terminal_refs != (
            pending.neutral_recall.terminal_ref,
            pending.ordinary_recall.terminal_ref,
        ):
            raise V2IntegrityStop("V2 recall cleanup terminal order differs")
        owners = tuple(self._capture_owners.get(ref) for ref in terminal_refs)
        if any(type(item) is not _V2RecallCaptureOwner for item in owners):
            raise V2IntegrityStop("V2 recall cleanup owner is absent")
        neutral = await owners[0].dispose_after_terminal(terminal_refs[0])  # type: ignore[union-attr]
        ordinary = await owners[1].dispose_after_terminal(terminal_refs[1])  # type: ignore[union-attr]
        replay_owner = owners[1]
        replay = PrivateRecallReplay(
            ordinary,
            replay_owner.hits,  # type: ignore[union-attr]
            replay_owner.batch,  # type: ignore[union-attr]
        )
        for ref in terminal_refs:
            self._capture_owners.pop(ref)
        return replace(
            pending,
            neutral_recall=neutral,
            ordinary_recall=ordinary,
            ordinary_private_replay=replay,
        )

    async def _open_disposable_stateful_attempt(
        self,
        *,
        scheduled: ScheduledAttempt,
        stage_ref: str,
        prompt_plan: PromptPlan,
        arm_context: ArmExecutionContext,
    ) -> V2StatefulAttemptOwner:
        if (
            scheduled.phase not in ("development", "final")
            or scheduled.arm not in STATEFUL_ARMS
            or arm_context.arm != scheduled.arm
            or type(arm_context.baseline) is not BaselineSeal
        ):
            raise V2InvariantError("V2 disposable stateful preparation differs")
        stage_ref = _ref(stage_ref, "V2 disposable stateful stage ref")
        source = self.lineages.owner_for(
            scheduled.replicate_commitment, scheduled.arm
        )
        source_seal = source.verify_seal()
        if arm_context.baseline.seal_ref != source_seal.seal_ref:
            raise V2IntegrityStop("V2 disposable stateful baseline differs")
        allocation, scope_spec = self._register_disposable(
            task_id=scheduled.task_id,
            replicate_commitment=scheduled.replicate_commitment,
            role=scheduled.arm,
            source_arm=scheduled.arm,
            scope_kind="disposable-attempt",
        )
        assert scope_spec is not None
        try:
            opened = await _open_v2_disposable_clone(
                source_owner=source,
                allocation=allocation,
                scope_spec=scope_spec,
                path_registry=self.path_registry,
                genesis=self.genesis,
                acquisition_opener=self.acquisition_opener,
                mechanics=self.mechanics,
            )
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_DISPOSABLE_CLONE_OPEN_FAILED"
            )
            pending = self._queue_failed_disposable_allocation(
                allocation=allocation,
                source_owner=source,
                source_seal=source_seal,
                failure_boundary_code="V2_DISPOSABLE_CLONE_OPEN_FAILED",
                stage_ref=stage_ref,
                session=None,
            )
            await self._retain_failed_disposable_or_raise(
                primary=primary,
                pending=pending,
                message="V2 stateful clone open and retention failed",
            )
            raise primary from None
        try:
            if scheduled.arm == "IN_FULL_NEUTRAL_12":
                if tuple(
                    item.source_ref
                    for item in prompt_plan.history_plan.presentations
                ) != source_seal.neutral_episode_refs:
                    raise V2IntegrityStop("V2 IN prompt source allowlist differs")
                from angler.memory.cognitive_acquisition_graph import (
                    AcquisitionReferenceHit,
                )

                hits = tuple(
                    AcquisitionReferenceHit(record_ref=item.record_ref)
                    for item in prompt_plan.history_plan.presentations
                )
                replay_frozen_origin = True
            else:
                replay = arm_context.ordinary_private_replay
                if type(replay) is not PrivateRecallReplay:
                    raise V2IntegrityStop("V2 IO private replay is absent")
                hits = replay.hits
                if tuple(
                    item.record_ref
                    for item in prompt_plan.history_plan.presentations
                ) != tuple(item.record_ref for item in hits):
                    raise V2IntegrityStop("V2 IO prompt/private hit order differs")
                replay.replay(opened.memory)
                replay_frozen_origin = True
            hits = _validated_reference_hits(
                hits, label="V2 disposable stateful"
            )
            runtime = await _build_stateful_product_runtime(
                arm=scheduled.arm,
                task_text=_render_v2_public_task(scheduled.task),
                history_plan=prompt_plan.history_plan,
                frozen_hits=hits,
                io=self.foundation.io,
                manifest=self.foundation.manifest,
                guard=self._guard,
                learner=opened.learner,
                store=opened.store,
                journal=opened.journal,
                canonical_memory=opened.memory,
                session=opened.session,
                replay_frozen_origin=replay_frozen_origin,
            )
            return V2StatefulAttemptOwner(
                runtime=runtime,
                source_owner=source,
                ledger=self.ledger,
                quiesce_runtime=_load_approved_r2_low_level_helpers()[
                    "_quiesce_successor_runtime"
                ],
                source_seal=source_seal,
                clone_paths=opened.paths,
                clone_before=opened.clone_before,
                allocation=allocation,
                path_registry=self.path_registry,
            )
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_DISPOSABLE_STATEFUL_BUILD_FAILED"
            )
            pending = self._queue_failed_disposable_allocation(
                allocation=allocation,
                source_owner=source,
                source_seal=source_seal,
                failure_boundary_code="V2_DISPOSABLE_STATEFUL_BUILD_FAILED",
                stage_ref=stage_ref,
                session=opened.session,
            )
            await self._retain_failed_disposable_or_raise(
                primary=primary,
                pending=pending,
                message="V2 stateful construction and retention failed",
            )
            raise primary from None

    async def _open_stateless_attempt(
        self,
        *,
        scheduled: ScheduledAttempt,
        stage_ref: str,
    ) -> V2AttemptExecutionRuntime:
        if scheduled.arm not in STATELESS_ARMS:
            raise V2InvariantError("V2 stateless preparation arm differs")
        if self._frozen is None:
            raise V2IntegrityStop("V2 stateless attempt requires frozen adaptation")
        stage_ref = _ref(stage_ref, "V2 stateless stage ref")
        allocation, scope_spec = self._register_disposable(
            task_id=scheduled.task_id,
            replicate_commitment=scheduled.replicate_commitment,
            role=scheduled.arm,
        )
        if scope_spec is not None:
            raise V2IntegrityStop("V2 stateless attempt acquired a scope")
        root = Path(allocation.runtime_root)
        try:
            _create_private_directory_once(root)
            return _build_stateless_product_runtime(
                arm=scheduled.arm,
                io=self.foundation.io,
                manifest=self.foundation.manifest,
                guard=self._guard,
                allocation=allocation,
                path_registry=self.path_registry,
            )
        except BaseException as error:
            primary = _redacted_failure(error, "V2_STATELESS_BUILD_FAILED")
            pending = self._queue_failed_disposable_allocation(
                allocation=allocation,
                source_owner=None,
                source_seal=None,
                failure_boundary_code="V2_STATELESS_BUILD_FAILED",
                stage_ref=stage_ref,
                session=None,
            )
            await self._retain_failed_disposable_or_raise(
                primary=primary,
                pending=pending,
                message="V2 stateless construction and retention failed",
            )
            raise primary from None

    async def execute_attempt(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        prompt_plan: PromptPlan,
        permit: AttemptGenerationPermit,
        resources: ResourceLedger,
        arm_context: ArmExecutionContext | None,
    ) -> AttemptObservation:
        if (
            self._closed
            or resources is not self.resources
            or scheduled.task_id != stage.task_id
            or scheduled.arm != stage.arm
            or scheduled.phase != stage.phase
            or prompt_plan.plan_ref != stage.prompt_plan_ref
            or stage.stage_ref in self._active_by_stage
            or scheduled.attempt_key in self._active_cells
            or (scheduled.phase == "adaptation") != (self._frozen is None)
        ):
            raise V2IntegrityStop("V2 product attempt invocation differs")
        owner: object
        if scheduled.phase == "adaptation":
            if arm_context is not None:
                raise V2IntegrityStop("V2 adaptation acquired an arm context")
            owner = self._adaptation_owners.get(scheduled.attempt_key)
            if type(owner) is not V2StatefulAttemptOwner:
                raise V2IntegrityStop("V2 adaptation runtime was not prepared")
        elif scheduled.arm in STATEFUL_ARMS:
            if type(arm_context) is not ArmExecutionContext:
                raise V2IntegrityStop("V2 stateful clone lacks its capability")
            owner = await self._open_disposable_stateful_attempt(
                scheduled=scheduled,
                stage_ref=stage.stage_ref,
                prompt_plan=prompt_plan,
                arm_context=arm_context,
            )
        else:
            if arm_context is None or type(arm_context) is not ArmExecutionContext:
                raise V2IntegrityStop("V2 stateless attempt lacks its context")
            owner = await self._open_stateless_attempt(
                scheduled=scheduled,
                stage_ref=stage.stage_ref,
            )
        self._active_by_stage[stage.stage_ref] = owner
        self._active_cells[scheduled.attempt_key] = stage.stage_ref
        if type(owner) is V2StatefulAttemptOwner:
            return await owner.execute_observation(
                scheduled, stage, prompt_plan, permit
            )
        if type(owner) is V2AttemptExecutionRuntime:
            return await owner.execute_observation(
                scheduled, stage, prompt_plan, permit
            )
        raise V2IntegrityStop("V2 active attempt owner type differs")

    def _active_owner(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
    ) -> object:
        if self._active_cells.get(scheduled.attempt_key) != stage.stage_ref:
            raise V2IntegrityStop("V2 active attempt cell differs")
        owner = self._active_by_stage.get(stage.stage_ref)
        if owner is None:
            raise V2IntegrityStop("V2 active attempt is absent")
        return owner

    async def apply_objective_feedback(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
        resources: ResourceLedger,
    ) -> StatefulFeedbackApplication:
        owner = self._active_owner(scheduled, stage)
        if type(owner) is not V2StatefulAttemptOwner or resources is not self.resources:
            raise V2IntegrityStop("V2 stateful feedback owner differs")
        return await owner.apply_objective_feedback(observation, judgment)

    async def finalize_persistent_stateful_attempt(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
        feedback_applied: bool,
        terminal_disposition_ref: str,
        resources: ResourceLedger,
    ) -> PersistentRuntimeCleanupEvidence:
        owner = self._active_owner(scheduled, stage)
        if (
            type(owner) is not V2StatefulAttemptOwner
            or not owner.persistent
            or resources is not self.resources
            or observation.task_id != stage.task_id
            or judgment.get("evaluator_record_ref") is None
        ):
            raise V2IntegrityStop("V2 persistent finalization owner differs")
        cleanup = await owner.finalize_persistent(
            stage=stage,
            attempt_receipt_ref=stage.attempt_receipt_ref,
            terminal_disposition_ref=terminal_disposition_ref,
            feedback_applied=feedback_applied,
        )
        self._active_by_stage.pop(stage.stage_ref)
        self._active_cells.pop(scheduled.attempt_key)
        self._adaptation_owners.pop(scheduled.attempt_key)
        return cleanup

    async def terminalize_stateful_attempt(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        observation: AttemptObservation,
        judgment: Mapping[str, object],
        feedback_applied: bool,
        resources: ResourceLedger,
    ) -> CloneTerminalEvidence:
        owner = self._active_owner(scheduled, stage)
        if (
            type(owner) is not V2StatefulAttemptOwner
            or owner.persistent
            or resources is not self.resources
            or observation.task_id != stage.task_id
            or type(feedback_applied) is not bool
            or judgment.get("evaluator_record_ref") is None
        ):
            raise V2IntegrityStop("V2 clone terminal owner differs")
        terminal = await owner.terminalize_clone(task_id=stage.task_id)
        self._clone_terminal_stages[terminal.terminal_ref] = stage.stage_ref
        return terminal

    async def dispose_clone(
        self,
        terminal: CloneTerminalEvidence,
        terminal_disposition_ref: str,
    ) -> CloneLifecycleEvidence:
        stage_ref = self._clone_terminal_stages.get(terminal.terminal_ref)
        owner = None if stage_ref is None else self._active_by_stage.get(stage_ref)
        if type(owner) is not V2StatefulAttemptOwner or owner.persistent:
            raise V2IntegrityStop("V2 clone disposal owner differs")
        lifecycle = await owner.dispose_clone(
            terminal, terminal_disposition_ref
        )
        self._clone_terminal_stages.pop(terminal.terminal_ref)
        self._active_by_stage.pop(stage_ref)
        self._active_cells.pop((terminal.task_id, terminal.arm))
        return lifecycle

    async def dispose_stateless_attempt(
        self,
        scheduled: ScheduledAttempt,
        stage: AttemptStage,
        observation: AttemptObservation,
        terminal_disposition_ref: str,
    ) -> StatelessRuntimeCleanupEvidence:
        stage_ref = self._active_cells.get(scheduled.attempt_key)
        owner = None if stage_ref is None else self._active_by_stage.get(stage_ref)
        if (
            type(owner) is not V2AttemptExecutionRuntime
            or owner.stateful
            or observation.task_id != scheduled.task_id
            or stage.task_id != scheduled.task_id
            or stage.arm != scheduled.arm
        ):
            raise V2IntegrityStop("V2 stateless disposal owner differs")
        cleanup = owner.dispose_stateless_durable(
            stage=stage,
            terminal_disposition_ref=terminal_disposition_ref,
            ledger=self.ledger,
        )
        self._active_by_stage.pop(stage_ref)
        self._active_cells.pop(scheduled.attempt_key)
        return cleanup

    def freeze_adaptation(
        self, attempts: tuple[AttemptFinal, ...]
    ) -> FrozenAdaptationState:
        if (
            self._frozen is not None
            or self._adaptation_owners
            or self._active_by_stage
            or self._active_cells
        ):
            raise V2IntegrityStop("V2 adaptation cannot freeze with active owners")
        frozen = self.lineages.freeze(attempts)
        self._frozen = frozen
        return frozen

    def verify_frozen_adaptation(self, frozen: FrozenAdaptationState) -> str:
        if self._frozen is None or frozen.freeze_ref != self._frozen.freeze_ref:
            raise V2IntegrityStop("V2 product frozen state differs")
        return self.lineages.verify_frozen(frozen)

    async def close(self) -> None:
        if self._closed:
            return
        failures: list[V2IntegrityStop] = []
        failed_owner_ids: set[int] = set()
        clean = not (
            self._adaptation_owners
            or self._active_by_stage
            or self._active_cells
            or self._capture_owners
            or self._clone_terminal_stages
            or self._pending_scope_retentions
            or self._pending_disposable_retentions
            or self._retained_disposable_allocations
        )
        all_workers_terminal = True
        persistent_owners: list[V2StatefulAttemptOwner] = []
        if not clean:
            # A failed one-use run preserves disposable bytes, but all worker/model
            # object references are still severed before foundation release.
            seen: set[int] = set()
            for owner in (
                *self._adaptation_owners.values(),
                *self._active_by_stage.values(),
            ):
                if id(owner) in seen:
                    continue
                seen.add(id(owner))
                if type(owner) is V2StatefulAttemptOwner and owner.runtime is not None:
                    session = owner.runtime.session
                    if owner.persistent:
                        keys = tuple(
                            key
                            for key, value in self._adaptation_owners.items()
                            if value is owner
                        )
                        if len(keys) != 1 or type(session) is not V2AcquisitionSession:
                            failed_owner_ids.add(id(owner))
                            failures.append(
                                V2IntegrityStop(
                                    "V2_FAILED_PERSISTENT_OWNER_AUTHORITY_DIFFERS"
                                )
                            )
                            owner._detach_model_graph_preserving_session()
                            continue
                        task_id, arm = keys[0]
                        active_stage_refs = tuple(
                            stage_ref
                            for stage_ref, value in self._active_by_stage.items()
                            if value is owner
                        )
                        cell_stage_ref = self._active_cells.get(keys[0])
                        if not active_stage_refs and cell_stage_ref is None:
                            reason_code = (
                                "V2_PERSISTENT_ATTEMPT_PREPARATION_FAILED"
                            )
                            stage_ref = None
                        elif (
                            len(active_stage_refs) == 1
                            and cell_stage_ref == active_stage_refs[0]
                            and tuple(
                                key
                                for key, value in self._active_cells.items()
                                if value == cell_stage_ref
                            )
                            == (keys[0],)
                        ):
                            reason_code = (
                                "V2_PERSISTENT_ATTEMPT_POST_STAGE_FAILED"
                            )
                            stage_ref = active_stage_refs[0]
                        else:
                            failed_owner_ids.add(id(owner))
                            failures.append(
                                V2IntegrityStop(
                                    "V2_FAILED_PERSISTENT_STAGE_AUTHORITY_DIFFERS"
                                )
                            )
                            owner._detach_model_graph_preserving_session()
                            continue
                        source = owner.source_owner
                        pending = self._pending_scope_retentions.get(
                            source.scope_spec.scope_ref
                        )
                        if pending is None:
                            pending = _PendingPersistentScopeRetention(
                                task_id=task_id,
                                replicate_commitment=source.replicate_commitment,
                                arm=arm,
                                allocation_ref=source.allocation_ref,
                                scope_ref=source.scope_spec.scope_ref,
                                state_root=source.scope_spec.state_root,
                                source_owner=source,
                                reason_code=reason_code,
                                stage_ref=stage_ref,
                                session=session,
                            )
                            self._pending_scope_retentions[pending.scope_ref] = pending
                        elif (
                            pending.source_owner is not source
                            or pending.task_id != task_id
                            or pending.arm != arm
                            or pending.reason_code != reason_code
                            or pending.stage_ref != stage_ref
                        ):
                            failed_owner_ids.add(id(owner))
                            failures.append(
                                V2IntegrityStop(
                                    "V2_FAILED_PERSISTENT_SCOPE_REBOUND"
                                )
                            )
                            owner._detach_model_graph_preserving_session()
                            continue
                        else:
                            pending.session = session
                        persistent_owners.append(owner)
                    else:
                        active_stage_refs = tuple(
                            stage_ref
                            for stage_ref, value in self._active_by_stage.items()
                            if value is owner
                        )
                        if (
                            len(active_stage_refs) != 1
                            or type(owner.allocation) is not DisposablePathAllocation
                            or type(owner.source_seal) is not BaselineSeal
                        ):
                            failures.append(
                                V2IntegrityStop(
                                    "V2_FAILED_DISPOSABLE_OWNER_AUTHORITY_DIFFERS"
                                )
                            )
                        else:
                            try:
                                self._queue_failed_disposable_allocation(
                                    allocation=owner.allocation,
                                    source_owner=owner.source_owner,
                                    source_seal=owner.source_seal,
                                    failure_boundary_code=(
                                        "V2_DISPOSABLE_STATEFUL_ATTEMPT_FAILED"
                                    ),
                                    stage_ref=active_stage_refs[0],
                                    session=session,
                                )
                            except BaseException as error:
                                failures.append(
                                    _redacted_failure(
                                        error,
                                        "V2_FAILED_DISPOSABLE_OWNER_AUTHORITY_DIFFERS",
                                    )
                                )
                    if type(session) is V2AcquisitionSession and not session._closed:
                        try:
                            await session.close_preserving_state()
                        except BaseException as error:
                            failed_owner_ids.add(id(owner))
                            failures.append(
                                _redacted_cleanup_failure(
                                    error, "V2_FAILED_ATTEMPT_SCOPE_CLOSE_FAILED"
                                )
                            )
                    if not session._closed:
                        all_workers_terminal = False
                    if not owner.persistent:
                        if session._closed:
                            owner._detach_after_cleanup()
                        else:
                            owner._detach_model_graph_preserving_session()
                elif type(owner) is V2AttemptExecutionRuntime:
                    active_stage_refs = tuple(
                        stage_ref
                        for stage_ref, value in self._active_by_stage.items()
                        if value is owner
                    )
                    if (
                        owner.stateful
                        or len(active_stage_refs) != 1
                        or type(owner.allocation) is not DisposablePathAllocation
                    ):
                        failures.append(
                            V2IntegrityStop(
                                "V2_FAILED_DISPOSABLE_OWNER_AUTHORITY_DIFFERS"
                            )
                        )
                    else:
                        try:
                            self._queue_failed_disposable_allocation(
                                allocation=owner.allocation,
                                source_owner=None,
                                source_seal=None,
                                failure_boundary_code="V2_STATELESS_ATTEMPT_FAILED",
                                stage_ref=active_stage_refs[0],
                                session=None,
                            )
                        except BaseException as error:
                            failures.append(
                                _redacted_failure(
                                    error,
                                    "V2_FAILED_DISPOSABLE_OWNER_AUTHORITY_DIFFERS",
                                )
                            )
                    owner.proposal_adapter = None
                    owner.relation_adapter = None
                    owner.executor = None
                    owner.journal = None
                    owner.cycle = None
                    owner.learner = None
                    owner.store = None
                    owner.memory = None
                    owner.guard = None
            for capture_owner in self._capture_owners.values():
                opened = capture_owner.opened
                if opened is not None:
                    try:
                        self._queue_failed_disposable_allocation(
                            allocation=opened.allocation,
                            source_owner=opened.source_owner,
                            source_seal=opened.source_seal,
                            failure_boundary_code="V2_RECALL_CAPTURE_FAILED",
                            stage_ref=None,
                            session=opened.session,
                        )
                    except BaseException as error:
                        failures.append(
                            _redacted_failure(
                                error,
                                "V2_FAILED_DISPOSABLE_OWNER_AUTHORITY_DIFFERS",
                            )
                        )
                if opened is not None and not opened.session._closed:
                    try:
                        await opened.session.close_preserving_state()
                    except BaseException as error:
                        failures.append(
                            _redacted_cleanup_failure(
                                error, "V2_FAILED_CAPTURE_SCOPE_CLOSE_FAILED"
                            )
                        )
                if opened is not None:
                    if opened.session._closed:
                        capture_owner.opened = None
                    else:
                        all_workers_terminal = False
        try:
            await _drain_unresolved_v2_cognee_workers()
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "V2_RETAINED_COGNEE_DRAIN_FAILED"
                )
            )
        if (
            _UNRESOLVED_V2_COGNEE_HANDLES
            or _UNRESOLVED_V2_COGNEE_BINDINGS
            or _UNRESOLVED_V2_COGNEE_STARTS
        ):
            all_workers_terminal = False
        for allocation_ref, pending in tuple(
            self._pending_disposable_retentions.items()
        ):
            try:
                await self._retain_failed_disposable_allocation(pending)
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error,
                        "V2_RETAINED_DISPOSABLE_EVIDENCE_APPEND_FAILED",
                    )
                )
            if allocation_ref in self._pending_disposable_retentions:
                session = pending.session
                if session is not None and not session._closed:
                    all_workers_terminal = False
        for scope_ref, pending in tuple(self._pending_scope_retentions.items()):
            source = pending.source_owner
            session = pending.session
            if session is not None and not session._closed:
                try:
                    await session.close_preserving_state()
                except BaseException as error:
                    failed_owner_ids.add(
                        id(
                            next(
                                (
                                    owner
                                    for owner in persistent_owners
                                    if owner.source_owner is source
                                ),
                                source,
                            )
                        )
                    )
                    failures.append(
                        _redacted_cleanup_failure(
                            error, "V2_RETAINED_SCOPE_SESSION_CLOSE_FAILED"
                        )
                    )
            terminal = (
                session._closed
                if session is not None
                else not (
                    _UNRESOLVED_V2_COGNEE_HANDLES
                    or _UNRESOLVED_V2_COGNEE_BINDINGS
                    or _UNRESOLVED_V2_COGNEE_STARTS
                )
            )
            if not terminal:
                all_workers_terminal = False
                continue
            try:
                try:
                    os.lstat(pending.state_root)
                except FileNotFoundError:
                    self._pending_scope_retentions.pop(scope_ref)
                    continue
                self._retain_failed_preparation_scope(pending=pending)
                self._pending_scope_retentions.pop(scope_ref)
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "V2_RETAINED_SCOPE_EVIDENCE_APPEND_FAILED"
                    )
                )
        for owner in persistent_owners:
            if owner.runtime is None:
                continue
            session = owner.runtime.session
            scope_ref = owner.source_owner.scope_spec.scope_ref
            if (
                type(session) is V2AcquisitionSession
                and session._closed
                and scope_ref not in self._pending_scope_retentions
            ):
                if id(owner) in failed_owner_ids:
                    owner._detach_model_graph_preserving_session()
                else:
                    owner._detach_after_cleanup()
            else:
                all_workers_terminal = False
                owner._detach_model_graph_preserving_session()
        if self._pending_scope_retentions:
            failures.append(V2IntegrityStop("V2_RETAINED_SCOPE_EVIDENCE_UNRESOLVED"))
        if self._pending_disposable_retentions:
            failures.append(
                V2IntegrityStop("V2_RETAINED_DISPOSABLE_EVIDENCE_UNRESOLVED")
            )
        if not failures and all_workers_terminal:
            if self._frozen is not None:
                try:
                    if self._retained_disposable_allocations:
                        self.lineages.close_frozen_failed_preserving_disposable_state(
                            self._frozen,
                            tuple(self._retained_disposable_allocations.values()),
                        )
                    else:
                        self.lineages.close(self._frozen)
                except BaseException as error:
                    failures.append(
                        _redacted_cleanup_failure(
                            error, "V2_LINEAGE_OWNER_CLOSE_FAILED"
                        )
                    )
            else:
                try:
                    self.lineages.close_failed_preserving_state(
                        tuple(self._retained_preparation_scopes.values())
                    )
                except BaseException as error:
                    failures.append(
                        _redacted_cleanup_failure(
                            error, "V2_FAILED_LINEAGE_OWNER_CLOSE_FAILED"
                        )
                    )
        if not failures and all_workers_terminal:
            try:
                if self._retained_disposable_allocations:
                    self.path_registry.assert_failure_accounted()
                else:
                    self.path_registry.assert_closed()
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "V2_PATH_REGISTRY_POSTCLOSE_FAILED"
                    )
                )
        if not failures and all_workers_terminal:
            self._adaptation_owners.clear()
            self._active_by_stage.clear()
            self._active_cells.clear()
            self._clone_terminal_stages.clear()
            self._capture_owners.clear()
            self._record_embedding_cache.clear()
        try:
            self.foundation.close()
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "V2_PRODUCT_FOUNDATION_CLOSE_FAILED"
                )
            )
        if not failures and all_workers_terminal:
            try:
                _assert_no_unresolved_v2_cognee_workers()
            except BaseException as error:
                failures.append(
                    _redacted_cleanup_failure(
                        error, "V2_RETAINED_COGNEE_ASSERTION_FAILED"
                    )
                )
        if not failures and all_workers_terminal:
            self._closed = True
        elif not all_workers_terminal and not failures:
            failures.append(V2IntegrityStop("V2_COGNEE_WORKER_CLOSE_UNRESOLVED"))
        if len(failures) == 1:
            raise failures[0]
        if failures:
            raise ExceptionGroup("V2 product runtime close failed", failures) from None


@dataclass(frozen=True, slots=True)
class TaskPreparationContext:
    """Least-authority preparation view for exactly one replicate/task."""

    task_id: str
    public_task_ref: str
    replicate_commitment: str
    frozen_state_ref: str
    in_baseline: BaselineSeal
    io_baseline: BaselineSeal
    donor_catalog: DonorCatalog

    def __post_init__(self) -> None:
        for value, label in (
            (self.task_id, "preparation task id"),
            (self.public_task_ref, "preparation public task ref"),
            (self.replicate_commitment, "preparation replicate commitment"),
            (self.frozen_state_ref, "preparation frozen state ref"),
        ):
            _ref(value, label)
        if (
            type(self.in_baseline) is not BaselineSeal
            or type(self.io_baseline) is not BaselineSeal
            or type(self.donor_catalog) is not DonorCatalog
            or self.in_baseline.arm != "IN_FULL_NEUTRAL_12"
            or self.io_baseline.arm != "IO_FULL_ORDINARY_12"
            or {
                self.in_baseline.replicate_commitment,
                self.io_baseline.replicate_commitment,
                self.donor_catalog.replicate_commitment,
            }
            != {self.replicate_commitment}
        ):
            raise V2InvariantError("task preparation lineage differs")

    @classmethod
    def create(
        cls, task: object, frozen: FrozenAdaptationState
    ) -> "TaskPreparationContext":
        canonical = _task_canonical(task)
        replicate_commitment = str(canonical["replicate_commitment"])
        baselines = frozen.baselines_for(replicate_commitment)
        return cls(
            task_id=str(canonical["task_id"]),
            public_task_ref=public_task_ref(canonical),
            replicate_commitment=replicate_commitment,
            frozen_state_ref=frozen.freeze_ref,
            in_baseline=baselines["IN_FULL_NEUTRAL_12"],
            io_baseline=baselines["IO_FULL_ORDINARY_12"],
            donor_catalog=frozen.catalog_for(replicate_commitment),
        )


@dataclass(frozen=True, slots=True)
class ArmExecutionContext:
    """Per-arm capability view; private IO recall never reaches sibling arms."""

    task_id: str
    arm: Arm
    preparation_ref: str
    baseline: BaselineSeal | None = field(default=None, repr=False)
    neutral_episode_refs: tuple[str, ...] = ()
    ordinary_private_replay: PrivateRecallReplay | None = field(
        default=None, repr=False, compare=False
    )

    def __post_init__(self) -> None:
        _ref(self.task_id, "arm context task id")
        arm = validate_arm(self.arm)
        _ref(self.preparation_ref, "arm context preparation ref")
        if arm == "IN_FULL_NEUTRAL_12":
            if (
                type(self.baseline) is not BaselineSeal
                or self.baseline.arm != arm
                or self.neutral_episode_refs != self.baseline.neutral_episode_refs
                or self.ordinary_private_replay is not None
            ):
                raise V2InvariantError("IN execution capability differs")
        elif arm == "IO_FULL_ORDINARY_12":
            if (
                type(self.baseline) is not BaselineSeal
                or self.baseline.arm != arm
                or self.neutral_episode_refs
                or type(self.ordinary_private_replay) is not PrivateRecallReplay
            ):
                raise V2InvariantError("IO execution capability differs")
        elif (
            self.baseline is not None
            or self.neutral_episode_refs
            or self.ordinary_private_replay is not None
        ):
            raise V2InvariantError("stateless arm acquired runtime/private capability")


@dataclass(slots=True)
class AttemptGenerationPermit:
    budget: AttemptBudget
    task_id: str
    arm: Arm
    _proposal_consumed: bool = field(default=False, init=False)
    _execution_consumed: bool = field(default=False, init=False)

    def __post_init__(self) -> None:
        if type(self.budget) is not AttemptBudget:
            raise TypeError("generation permit budget differs")
        _ref(self.task_id, "generation permit task id")
        validate_arm(self.arm)

    def before_proposal_generation(self) -> None:
        if self._proposal_consumed:
            raise V2IntegrityStop("proposal generation permit was reused")
        self.budget.consume_proposal(self.task_id, self.arm)
        self._proposal_consumed = True

    def before_execution_generation(self) -> None:
        if not self._proposal_consumed or self._execution_consumed:
            raise V2IntegrityStop("execution permit ordering differs")
        self.budget.consume_execution(self.task_id, self.arm)
        self._execution_consumed = True

    def validate_observation(self, observation: AttemptObservation) -> None:
        if (
            type(observation) is not AttemptObservation
            or observation.task_id != self.task_id
            or observation.arm != self.arm
        ):
            raise V2InvariantError("generation permit observation differs")
        if not self._proposal_consumed:
            raise V2IntegrityStop("attempt returned without consuming proposal permit")
        if self._execution_consumed != observation.proposal_admitted:
            raise V2IntegrityStop("execution permit/admission evidence differs")


async def _maybe_await(value: object) -> object:
    if inspect.isawaitable(value):
        return await value
    return value


def _canonical_judgment(value: object) -> dict[str, object]:
    result = _canonical_mapping(value, "objective judgment")
    forbidden = frozenset(
        {
            "answer",
            "expected_answer",
            "hidden",
            "private_binding",
            "solution",
        }
    )
    if set(result) & forbidden:
        raise V2InvariantError("objective judgment exposed evaluator-private material")
    return result


def _ipc_envelope(kind: str, request_id: int, payload: object) -> dict[str, object]:
    return {
        "kind": _text(kind, "evaluator IPC kind", 64),
        "payload": payload,
        "request_id": _integer(request_id, "evaluator IPC request id"),
        "schema": EVALUATOR_IPC_SCHEMA,
    }


def _write_ipc_line(stream: object, value: Mapping[str, object]) -> None:
    raw = canonical_json_bytes(dict(value)) + b"\n"
    if len(raw) > MAXIMUM_EVALUATOR_IPC_BYTES:
        raise V2IntegrityStop("evaluator IPC message exceeds its bound")
    write = getattr(stream, "write", None)
    flush = getattr(stream, "flush", None)
    if not callable(write) or not callable(flush):
        raise TypeError("evaluator IPC stream is not writable")
    write(raw)
    flush()


def _read_ipc_line(stream: object, *, timeout: float) -> dict[str, object]:
    timeout = _finite(timeout, "evaluator IPC timeout")
    if timeout <= 0.0:
        raise ValueError("evaluator IPC timeout must be positive")
    fileno = getattr(stream, "fileno", None)
    if not callable(fileno):
        raise TypeError("evaluator IPC stream is not readable")
    descriptor = fileno()
    if type(descriptor) is not int or descriptor < 0:
        raise TypeError("evaluator IPC descriptor differs")
    deadline = time.monotonic() + timeout
    chunks = bytearray()
    selector = selectors.DefaultSelector()
    try:
        selector.register(descriptor, selectors.EVENT_READ)
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0.0 or not selector.select(remaining):
                raise TimeoutError("evaluator worker response timed out")
            try:
                block = os.read(
                    descriptor,
                    min(
                        64 * 1024,
                        MAXIMUM_EVALUATOR_IPC_BYTES + 1 - len(chunks),
                    ),
                )
            except InterruptedError:
                continue
            if not block:
                raise V2IntegrityStop("evaluator worker response is absent")
            chunks.extend(block)
            newline = chunks.find(b"\n")
            if newline >= 0:
                if newline != len(chunks) - 1:
                    raise V2IntegrityStop(
                        "evaluator worker emitted more than one response frame"
                    )
                break
            if len(chunks) > MAXIMUM_EVALUATOR_IPC_BYTES:
                raise V2IntegrityStop("evaluator worker response is oversized")
    finally:
        selector.close()
    raw = bytes(chunks)
    if not raw or len(raw) > MAXIMUM_EVALUATOR_IPC_BYTES:
        raise V2IntegrityStop("evaluator worker response is absent or oversized")
    if not raw.endswith(b"\n"):
        raise V2IntegrityStop("evaluator worker response is not line-framed")
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise V2IntegrityStop("evaluator worker response is not canonical JSON") from error
    if type(value) is not dict or canonical_json_bytes(value) + b"\n" != raw:
        raise V2IntegrityStop("evaluator worker response is not canonical")
    return value


def _seed_receipt_from_artifact(
    artifact: Mapping[str, object],
    raw: bytes,
    metadata: os.stat_result,
    *,
    artifact_path: str | Path = SEALED_SEED_PATH,
) -> dict[str, object]:
    value = dict(artifact)
    target = Path(artifact_path)
    if not target.is_absolute():
        raise ValueError("seed receipt artifact path must be absolute")
    rows = value.get("replicates")
    if type(rows) is not list or len(rows) != 3:
        raise V2IntegrityStop("seed artifact receipt population differs")
    commitments = [
        row.get("commitment") if type(row) is dict else None for row in rows
    ]
    validate_evaluation_seed_commitments(commitments)
    payload = {
        "preseed_boundary_ref": value.get("preseed_boundary_ref"),
        "artifact_bytes": len(raw),
        "artifact_device": int(metadata.st_dev),
        "artifact_inode": int(metadata.st_ino),
        "artifact_mode": "0600",
        "artifact_path": str(target),
        "artifact_sha256": hashlib.sha256(raw).hexdigest(),
        "commitments": commitments,
        "evaluator_commitments_ref": value.get("evaluator_commitments_ref"),
        "identity": EVALUATION_IDENTITY,
        "manifest_ref": value.get("manifest_ref"),
        "manifest_sha256": value.get("manifest_sha256"),
        "protocol_identity": PROTOCOL_IDENTITY,
        "qualification_release_ref": value.get("qualification_release_ref"),
        "qualification_result_ref": value.get("qualification_result_ref"),
        "qualification_result_sha256": value.get("qualification_result_sha256"),
        "schema": SEED_SEAL_RECEIPT_SCHEMA,
        "source_seal_ref": value.get("source_seal_ref"),
    }
    return {
        **payload,
        "seed_seal_ref": canonical_ref("evaluation-seed-seal", payload),
    }


def _load_sealed_evaluation_seeds_for_worker(
    path: str | Path,
    expected_commitments: Sequence[str],
    expected_receipt: Mapping[str, object],
) -> tuple[tuple[bytes, bytes, bytes], dict[str, object]]:
    """Read the V2 seed artifact only inside the isolated evaluator worker."""

    target = Path(path)
    expected = validate_evaluation_seed_commitments(expected_commitments)
    if target != SEALED_SEED_PATH or not target.is_absolute():
        raise V2IntegrityStop("evaluator seed path differs")
    try:
        if target.resolve(strict=True) != target:
            raise V2IntegrityStop("evaluator seed path aliases another path")
        descriptor = os.open(
            target,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
    except OSError as error:
        raise V2IntegrityStop("sealed evaluator seeds are unavailable") from error
    try:
        opened = os.fstat(descriptor)
        current = os.lstat(target)
        if (
            not stat.S_ISREG(opened.st_mode)
            or stat.S_IMODE(opened.st_mode) != 0o600
            or opened.st_nlink != 1
            or opened.st_uid != os.geteuid()
            or opened.st_gid != os.getegid()
            or (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino)
            or not 1 <= opened.st_size <= MAXIMUM_SEALED_SEED_BYTES
        ):
            raise V2IntegrityStop("sealed evaluator seed metadata differs")
        chunks = bytearray()
        while len(chunks) <= MAXIMUM_SEALED_SEED_BYTES:
            block = os.read(
                descriptor,
                min(4096, MAXIMUM_SEALED_SEED_BYTES + 1 - len(chunks)),
            )
            if not block:
                break
            chunks.extend(block)
        after = os.fstat(descriptor)
        latest = os.lstat(target)
        if (
            len(chunks) != opened.st_size
            or len(chunks) > MAXIMUM_SEALED_SEED_BYTES
            or (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns)
            != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
            or (after.st_dev, after.st_ino) != (latest.st_dev, latest.st_ino)
        ):
            raise V2IntegrityStop("sealed evaluator seeds changed while read")
    finally:
        os.close(descriptor)
    raw = bytes(chunks)
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise V2IntegrityStop("sealed evaluator seeds are not canonical JSON") from error
    if type(value) is not dict or canonical_json_bytes(value) != raw:
        raise V2IntegrityStop("sealed evaluator seeds are not canonical")
    if set(value) != {
        "preseed_boundary_ref",
        "evaluator_commitments_ref",
        "identity",
        "manifest_ref",
        "manifest_sha256",
        "protocol_identity",
        "qualification_release_ref",
        "qualification_result_ref",
        "qualification_result_sha256",
        "replicates",
        "schema",
        "source_seal_ref",
    }:
        raise V2IntegrityStop("sealed evaluator seed fields differ")
    if (
        value["schema"] != SEALED_EVALUATION_SEEDS_SCHEMA
        or value["identity"] != EVALUATION_IDENTITY
        or value["protocol_identity"] != PROTOCOL_IDENTITY
    ):
        raise V2IntegrityStop("sealed evaluator seed identity differs")
    for name in (
        "preseed_boundary_ref",
        "evaluator_commitments_ref",
        "manifest_ref",
        "qualification_release_ref",
        "qualification_result_ref",
        "source_seal_ref",
    ):
        _ref(value[name], f"sealed evaluator seed {name}")
    for name in ("manifest_sha256", "qualification_result_sha256"):
        _raw_digest(value[name], f"sealed evaluator seed {name}")
    rows = value["replicates"]
    if type(rows) is not list or len(rows) != 3:
        raise V2IntegrityStop("sealed evaluator seed population differs")
    seeds: list[bytes] = []
    observed: list[str] = []
    for index, row in enumerate(rows, start=1):
        if type(row) is not dict or set(row) != {"commitment", "label", "seed_hex"}:
            raise V2IntegrityStop("sealed evaluator seed row fields differ")
        if row["label"] != f"replicate-{index:02d}":
            raise V2IntegrityStop("sealed evaluator seed labels differ")
        encoded = row["seed_hex"]
        if type(encoded) is not str or re.fullmatch(r"[0-9a-f]{64}", encoded) is None:
            raise V2IntegrityStop("sealed evaluator seed encoding differs")
        seed = bytes.fromhex(encoded)
        commitment = seed_commitment(seed)
        if row["commitment"] != commitment:
            raise V2IntegrityStop("sealed evaluator seed commitment differs")
        seeds.append(seed)
        observed.append(commitment)
    if tuple(observed) != expected or len(set(seeds)) != 3:
        raise V2IntegrityStop("sealed evaluator seeds differ from commitments")
    receipt = _seed_receipt_from_artifact(value, raw, opened)
    boundary = {
        name: receipt[name]
        for name in (
            "preseed_boundary_ref",
            "identity",
            "manifest_ref",
            "manifest_sha256",
            "protocol_identity",
            "qualification_release_ref",
            "qualification_result_ref",
            "qualification_result_sha256",
            "source_seal_ref",
        )
    }
    validated_receipt = _validate_seed_seal_receipt(
        receipt, boundary=boundary
    )
    if validated_receipt != dict(expected_receipt):
        raise V2IntegrityStop("sealed evaluator seed receipt differs")
    return (seeds[0], seeds[1], seeds[2]), validated_receipt


_EVALUATION_SEED_VERIFIER_PROCESS_ARGV = (
    str(ANGLER_PYTHON),
    str(RUNNER_PATH),
    "--evaluation-seed-verifier-worker",
)


def _evaluation_seed_verification_payload(
    admission: Mapping[str, object], admission_sha256: str
) -> dict[str, object]:
    value = dict(admission)
    receipt = _canonical_mapping(
        value.get("seed_seal_receipt"), "seed verification receipt"
    )
    return {
        "admission_ref": _ref(
            value.get("admission_ref"), "seed verification admission"
        ),
        "admission_sha256": _raw_digest(
            admission_sha256, "seed verification admission digest"
        ),
        "artifact_sha256": _raw_digest(
            receipt.get("artifact_sha256"), "seed verification artifact digest"
        ),
        "seed_seal_ref": _ref(
            receipt.get("seed_seal_ref"), "seed verification seal"
        ),
    }


def evaluation_seed_verifier_worker_main() -> int:
    """Privately verify the sealed raw seeds and emit only their public receipt."""

    raw_seeds: tuple[bytes, ...] = ()
    try:
        durable = _validate_private_worker_boundary(
            require_qualification_result=True
        )
        request = _read_ipc_line(sys.stdin.buffer, timeout=120.0)
        if (
            request.get("schema") != EVALUATOR_IPC_SCHEMA
            or request.get("kind") != "verify-sealed-evaluation-seeds"
            or request.get("request_id") != 0
            or type(request.get("payload")) is not dict
        ):
            return 2
        admission, admission_sha256 = load_evaluation_admission_claim()
        manifest = durable.get("manifest")
        release = durable.get("qualification_release")
        qualification = durable.get("qualification_result")
        source_seal = durable.get("source_seal")
        if not all(
            type(item) is dict
            for item in (manifest, release, qualification, source_seal)
        ):
            return 2
        boundary = _evaluation_admission_boundary(
            manifest_ref=manifest["manifest_ref"],
            manifest_sha256=durable["manifest_sha256"],
            qualification_result_ref=qualification["result_ref"],
            qualification_result_sha256=durable[
                "qualification_result_sha256"
            ],
            qualification_release_ref=release["release_ref"],
            source_seal_ref=source_seal["source_seal_ref"],
        )
        if any(
            admission.get(name) != expected
            for name, expected in boundary.items()
        ):
            return 2
        expected_payload = _evaluation_seed_verification_payload(
            admission, admission_sha256
        )
        if request["payload"] != expected_payload:
            return 2
        _rejoin_sealed_seed_artifact_metadata(
            admission["seed_seal_receipt"]
        )
        raw_seeds, verified_receipt = _load_sealed_evaluation_seeds_for_worker(
            SEALED_SEED_PATH,
            admission["seed_commitments"],
            admission["seed_seal_receipt"],
        )
        raw_seeds = ()
        if (
            verified_receipt["seed_seal_ref"]
            != expected_payload["seed_seal_ref"]
            or verified_receipt["artifact_sha256"]
            != expected_payload["artifact_sha256"]
        ):
            return 2
        _write_ipc_line(
            sys.stdout.buffer,
            _ipc_envelope("ok", 0, expected_payload),
        )
        return 0
    except BaseException:
        raw_seeds = ()
        return 2


def verify_evaluation_seed_artifact_isolated(
    admission: Mapping[str, object],
    admission_sha256: str,
    *,
    cwd: str | Path = EVALUATOR_CWD,
    tmpdir: str | Path = EVALUATOR_TMP,
) -> dict[str, object]:
    """Verify raw seed bytes in a bounded one-shot private subprocess."""

    value = _canonical_mapping(admission, "seed verification admission")
    boundary = {
        name: value.get(name)
        for name in (
            "preseed_boundary_ref",
            "identity",
            "manifest_ref",
            "manifest_sha256",
            "protocol_identity",
            "qualification_release_ref",
            "qualification_result_ref",
            "qualification_result_sha256",
            "source_seal_ref",
        )
    }
    validated = validate_evaluation_admission_claim(
        value,
        boundary=boundary,
        seed_receipt=_canonical_mapping(
            value.get("seed_seal_receipt"), "seed verification receipt"
        ),
        evaluator_commitments=_canonical_mapping(
            value.get("evaluator_commitments"),
            "seed verification evaluator commitments",
        ),
    )
    expected_payload = _evaluation_seed_verification_payload(
        validated, admission_sha256
    )
    _rejoin_sealed_seed_artifact_metadata(
        validated["seed_seal_receipt"]
    )
    working = Path(cwd)
    temporary = Path(tmpdir)
    if working != EVALUATOR_CWD or temporary != EVALUATOR_TMP:
        raise V2InvariantError("seed verifier paths differ from literal scope")
    _require_empty_evaluator_private_paths(cwd=working, tmpdir=temporary)
    environment = _frozen_evaluator_environment()
    environment["TMPDIR"] = str(temporary)
    process = subprocess.Popen(
        list(_EVALUATION_SEED_VERIFIER_PROCESS_ARGV),
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        cwd=working,
        env=environment,
        close_fds=True,
    )
    primary: V2IntegrityStop | None = None
    proof: dict[str, object] | None = None
    try:
        if process.stdin is None or process.stdout is None:
            raise V2IntegrityStop("seed verifier pipes are absent")
        process_receipt = _evaluator_process_receipt(process.pid)
        expected_command = b"\x00".join(
            item.encode("utf-8")
            for item in _EVALUATION_SEED_VERIFIER_PROCESS_ARGV
        ) + b"\x00"
        if (
            tuple(process.args) != _EVALUATION_SEED_VERIFIER_PROCESS_ARGV
            or process_receipt[1] != str(working)
            or Path(process_receipt[2]).resolve(strict=True)
            != ANGLER_PYTHON.resolve(strict=True)
            or process_receipt[3] != expected_command
        ):
            raise V2IntegrityStop("seed verifier process receipt differs")
        _write_ipc_line(
            process.stdin,
            _ipc_envelope(
                "verify-sealed-evaluation-seeds", 0, expected_payload
            ),
        )
        response = _read_ipc_line(
            process.stdout, timeout=EVALUATOR_REQUEST_TIMEOUT_SECONDS
        )
        if response != _ipc_envelope("ok", 0, expected_payload):
            raise V2IntegrityStop("seed verifier response differs")
        proof = expected_payload
    except BaseException as error:
        primary = _redacted_failure(
            error, "V2_EVALUATION_SEED_VERIFICATION_FAILED"
        )
    cleanup: V2IntegrityStop | None = None
    try:
        _close_evaluator_process_terminal(process)
    except BaseException as error:
        cleanup = _redacted_failure(
            error, "V2_EVALUATION_SEED_VERIFIER_CLOSE_FAILED"
        )
    if process.poll() not in (0,):
        exit_failure = V2IntegrityStop(
            "V2_EVALUATION_SEED_VERIFIER_EXIT_FAILED"
        )
        if primary is None:
            primary = exit_failure
        elif cleanup is None:
            cleanup = exit_failure
    if primary is not None and cleanup is not None:
        raise ExceptionGroup(
            "evaluation seed verification and cleanup failed",
            [primary, cleanup],
        ) from None
    if primary is not None:
        raise primary from None
    if cleanup is not None:
        raise cleanup from None
    if proof is None:
        raise V2IntegrityStop("evaluation seed verification proof is absent")
    _require_empty_evaluator_private_paths(cwd=working, tmpdir=temporary)
    return proof


def evaluation_commitment_worker_main() -> int:
    """Hidden one-use seed sealer; raw seeds never cross this process."""

    request_stream = sys.stdin.buffer
    response_stream = sys.stdout.buffer
    raw_seeds: tuple[bytes, ...] = ()
    artifact: dict[str, object] = {}
    try:
        durable = _validate_private_worker_boundary(
            require_qualification_result=True
        )
        validate_live_phase_topology("pre-seed")
        request = _read_ipc_line(request_stream, timeout=120.0)
        if (
            request.get("schema") != EVALUATOR_IPC_SCHEMA
            or request.get("kind") != "seal-evaluation-seeds"
            or request.get("request_id") != 0
            or type(request.get("payload")) is not dict
        ):
            return 2
        body = request["payload"]
        result = durable["qualification_result"]
        release = durable["qualification_release"]
        manifest = durable["manifest"]
        source_seal = durable["source_seal"]
        if not all(type(item) is dict for item in (result, release, manifest, source_seal)):
            return 2
        expected_boundary = _evaluation_admission_boundary(
            manifest_ref=manifest["manifest_ref"],
            manifest_sha256=durable["manifest_sha256"],
            qualification_result_ref=result["result_ref"],
            qualification_result_sha256=durable["qualification_result_sha256"],
            qualification_release_ref=release["release_ref"],
            source_seal_ref=source_seal["source_seal_ref"],
        )
        boundary = _validated_evaluation_admission_boundary(body)
        if boundary != expected_boundary:
            return 2
        assert_all_live_paths_absent(
            (
                SEALED_SEED_PATH,
                EVALUATION_ADMISSION_CLAIM_PATH,
                EVALUATION_RUNTIME_ROOT,
                EVALUATION_RESULT_PATH,
            )
        )
        raw_seeds = tuple(os.urandom(32) for _ in range(3))
        commitments = validate_evaluation_seed_commitments(
            tuple(seed_commitment(seed) for seed in raw_seeds)
        )
        from experiments.evaluators.high_level_multidomain_v2_history_conditioning import (
            make_evaluation_evaluator,
        )

        evaluator = make_evaluation_evaluator(
            raw_seeds,
            commitments,
            boundary["preseed_boundary_ref"],
        )
        evaluator_commitments = _canonical_mapping(
            getattr(evaluator, "commitments", None),
            "seed worker evaluator commitments",
        )
        evaluator_commitments_ref = canonical_ref(
            "evaluator-commitments", evaluator_commitments
        )
        if (
            evaluator_commitments.get("identity") != EVALUATION_IDENTITY
            or evaluator_commitments.get("protocol_identity") != PROTOCOL_IDENTITY
            or evaluator_commitments.get("purpose") != "evaluation"
            or evaluator_commitments.get("replicate_commitments")
            != list(commitments)
        ):
            return 2
        artifact = {
            "preseed_boundary_ref": boundary["preseed_boundary_ref"],
            "evaluator_commitments_ref": evaluator_commitments_ref,
            "identity": EVALUATION_IDENTITY,
            "manifest_ref": boundary["manifest_ref"],
            "manifest_sha256": boundary["manifest_sha256"],
            "protocol_identity": PROTOCOL_IDENTITY,
            "qualification_release_ref": boundary["qualification_release_ref"],
            "qualification_result_ref": boundary["qualification_result_ref"],
            "qualification_result_sha256": boundary["qualification_result_sha256"],
            "replicates": [
                {
                    "commitment": commitment,
                    "label": f"replicate-{index:02d}",
                    "seed_hex": seed.hex(),
                }
                for index, (seed, commitment) in enumerate(
                    zip(raw_seeds, commitments, strict=True), start=1
                )
            ],
            "schema": SEALED_EVALUATION_SEEDS_SCHEMA,
            "source_seal_ref": boundary["source_seal_ref"],
        }
        _publish_canonical_create_once(
            SEALED_SEED_PATH,
            artifact,
            expected_path=SEALED_SEED_PATH,
            mode=0o600,
            expected_parent_mode=0o700,
            maximum_bytes=MAXIMUM_SEALED_SEED_BYTES,
            label="sealed evaluation seeds",
        )
        raw = canonical_json_bytes(artifact)
        metadata = os.lstat(SEALED_SEED_PATH)
        receipt = _seed_receipt_from_artifact(artifact, raw, metadata)
        validated_receipt = _validate_seed_seal_receipt(
            receipt, boundary=boundary
        )
        response = {
            "evaluator_commitments": evaluator_commitments,
            "seed_seal_receipt": validated_receipt,
        }
        raw_seeds = ()
        artifact = {}
        evaluator = None
        _write_ipc_line(response_stream, _ipc_envelope("ok", 0, response))
        revalidate = _read_ipc_line(request_stream, timeout=120.0)
        if (
            revalidate.get("schema") != EVALUATOR_IPC_SCHEMA
            or revalidate.get("kind") != "revalidate-sealed-evaluation-seeds"
            or revalidate.get("request_id") != 1
            or type(revalidate.get("payload")) is not dict
            or set(revalidate["payload"]) != {"final_admission_ref"}
        ):
            return 2
        final_admission_ref = _ref(
            revalidate["payload"]["final_admission_ref"],
            "seed worker final admission",
        )
        reopened_seeds, reopened_receipt = _load_sealed_evaluation_seeds_for_worker(
            SEALED_SEED_PATH,
            commitments,
            validated_receipt,
        )
        evaluator = make_evaluation_evaluator(
            reopened_seeds,
            commitments,
            final_admission_ref,
        )
        reopened_commitments = _canonical_mapping(
            getattr(evaluator, "commitments", None),
            "revalidated evaluator commitments",
        )
        reopened_seeds = ()
        evaluator = None
        if (
            reopened_receipt != validated_receipt
            or reopened_commitments != evaluator_commitments
        ):
            return 2
        _write_ipc_line(
            response_stream,
            _ipc_envelope(
                "ok",
                1,
                {
                    "evaluator_commitments_ref": evaluator_commitments_ref,
                    "seed_seal_ref": validated_receipt["seed_seal_ref"],
                },
            ),
        )
        close = _read_ipc_line(request_stream, timeout=120.0)
        if (
            close.get("schema") != EVALUATOR_IPC_SCHEMA
            or close.get("kind") != "close-seed-worker"
            or close.get("request_id") != 2
            or close.get("payload") != {}
        ):
            return 2
        _write_ipc_line(response_stream, _ipc_envelope("ok", 2, None))
        return 0
    except BaseException:
        raw_seeds = ()
        artifact = {}
        return 2


@dataclass(slots=True)
class EvaluationCommitmentWorker:
    process: subprocess.Popen[bytes] = field(repr=False)
    boundary: dict[str, object]
    seed_receipt: dict[str, object]
    evaluator_commitments: dict[str, object]
    _revalidated_admission_ref: str | None = field(default=None, init=False, repr=False)
    _closed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        self.boundary = _validated_evaluation_admission_boundary(self.boundary)
        self.seed_receipt = _validate_seed_seal_receipt(
            self.seed_receipt, boundary=self.boundary
        )
        self.evaluator_commitments = _canonical_mapping(
            self.evaluator_commitments, "commitment worker evaluator commitments"
        )
        if (
            canonical_ref("evaluator-commitments", self.evaluator_commitments)
            != self.seed_receipt["evaluator_commitments_ref"]
            or self.process.stdin is None
            or self.process.stdout is None
        ):
            raise V2IntegrityStop("commitment worker construction differs")

    def revalidate(self, final_admission_ref: str) -> None:
        if self._closed or self._revalidated_admission_ref is not None:
            raise V2IntegrityStop("commitment worker revalidation is one-use")
        final_ref = _ref(final_admission_ref, "final evaluation admission")
        assert self.process.stdin is not None and self.process.stdout is not None
        _write_ipc_line(
            self.process.stdin,
            _ipc_envelope(
                "revalidate-sealed-evaluation-seeds",
                1,
                {"final_admission_ref": final_ref},
            ),
        )
        response = _read_ipc_line(
            self.process.stdout, timeout=EVALUATOR_REQUEST_TIMEOUT_SECONDS
        )
        expected_payload = {
            "evaluator_commitments_ref": self.seed_receipt[
                "evaluator_commitments_ref"
            ],
            "seed_seal_ref": self.seed_receipt["seed_seal_ref"],
        }
        if (
            set(response) != {"kind", "payload", "request_id", "schema"}
            or response.get("schema") != EVALUATOR_IPC_SCHEMA
            or response.get("kind") != "ok"
            or response.get("request_id") != 1
            or response.get("payload") != expected_payload
        ):
            raise V2IntegrityStop("commitment worker revalidation differs")
        self._revalidated_admission_ref = final_ref

    def close(self) -> None:
        if self._closed:
            return
        if self._revalidated_admission_ref is None:
            self.process.kill()
            self.process.wait(timeout=10.0)
            self._closed = True
            raise V2IntegrityStop("commitment worker closed before revalidation")
        assert self.process.stdin is not None and self.process.stdout is not None
        try:
            _write_ipc_line(
                self.process.stdin,
                _ipc_envelope("close-seed-worker", 2, {}),
            )
            response = _read_ipc_line(
                self.process.stdout, timeout=EVALUATOR_REQUEST_TIMEOUT_SECONDS
            )
            if (
                response
                != _ipc_envelope("ok", 2, None)
            ):
                raise V2IntegrityStop("commitment worker close receipt differs")
        except BaseException:
            self.process.kill()
            self.process.wait(timeout=10.0)
            self._closed = True
            raise
        finally:
            if self.process.stdin is not None:
                self.process.stdin.close()
            if self.process.stdout is not None:
                self.process.stdout.close()
        if self.process.wait(timeout=10.0) != 0:
            self._closed = True
            raise V2IntegrityStop("commitment worker exit status differs")
        self._closed = True


def create_evaluation_seed_seal_isolated(
    boundary: Mapping[str, object],
    *,
    cwd: str | Path = EVALUATOR_CWD,
    tmpdir: str | Path = EVALUATOR_TMP,
) -> EvaluationCommitmentWorker:
    """Create seeds in a hidden worker and return only public commitments."""

    validated_boundary = _validated_evaluation_admission_boundary(boundary)
    working = Path(cwd)
    temporary = Path(tmpdir)
    if working != EVALUATOR_CWD or temporary != EVALUATOR_TMP:
        raise V2InvariantError("seed worker paths differ from literal scope")
    identities = (
        _private_root_identity(working, "seed worker cwd"),
        _private_root_identity(temporary, "seed worker tmp"),
    )
    if (
        identities[0][0] != str(working)
        or identities[1][0] != str(temporary)
        or identities[0][1:] == identities[1][1:]
        or any(stat.S_IMODE(os.lstat(path).st_mode) != 0o700 for path in (working, temporary))
    ):
        raise V2InvariantError("seed worker private paths differ")
    try:
        os.lstat(SEALED_SEED_PATH)
    except FileNotFoundError:
        pass
    else:
        raise V2IntegrityStop("sealed evaluation seed identity is consumed")
    environment = _frozen_evaluator_environment()
    environment["TMPDIR"] = str(temporary)
    process = subprocess.Popen(
        [str(ANGLER_PYTHON), str(RUNNER_PATH), "--evaluation-commitment-worker"],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        cwd=working,
        env=environment,
        close_fds=True,
    )
    try:
        if process.stdin is None or process.stdout is None:
            raise V2IntegrityStop("seed worker pipes are absent")
        _write_ipc_line(
            process.stdin,
            _ipc_envelope("seal-evaluation-seeds", 0, validated_boundary),
        )
        response = _read_ipc_line(
            process.stdout, timeout=EVALUATOR_REQUEST_TIMEOUT_SECONDS
        )
        if (
            set(response) != {"kind", "payload", "request_id", "schema"}
            or response.get("schema") != EVALUATOR_IPC_SCHEMA
            or response.get("kind") != "ok"
            or response.get("request_id") != 0
            or type(response.get("payload")) is not dict
        ):
            raise V2IntegrityStop("seed worker response differs")
        payload = response["payload"]
        if set(payload) != {"evaluator_commitments", "seed_seal_receipt"}:
            raise V2IntegrityStop("seed worker response fields differ")
        receipt = _validate_seed_seal_receipt(
            _canonical_mapping(payload["seed_seal_receipt"], "seed seal receipt"),
            boundary=validated_boundary,
        )
        commitments = _canonical_mapping(
            payload["evaluator_commitments"], "seed worker commitments"
        )
        if (
            canonical_ref("evaluator-commitments", commitments)
            != receipt["evaluator_commitments_ref"]
            or commitments.get("replicate_commitments") != receipt["commitments"]
        ):
            raise V2IntegrityStop("seed worker commitment receipt differs")
        metadata = os.lstat(SEALED_SEED_PATH)
        if (
            not stat.S_ISREG(metadata.st_mode)
            or stat.S_IMODE(metadata.st_mode) != 0o600
            or metadata.st_nlink != 1
            or metadata.st_uid != os.geteuid()
            or metadata.st_gid != os.getegid()
            or int(metadata.st_dev) != receipt["artifact_device"]
            or int(metadata.st_ino) != receipt["artifact_inode"]
            or int(metadata.st_size) != receipt["artifact_bytes"]
        ):
            raise V2IntegrityStop("seed worker artifact metadata differs")
    except BaseException:
        process.kill()
        process.wait(timeout=10.0)
        raise
    return EvaluationCommitmentWorker(
        process=process,
        boundary=validated_boundary,
        seed_receipt=receipt,
        evaluator_commitments=commitments,
    )


_EVALUATOR_PROCESS_CONSTRUCTION_CAPABILITY = object()
_EVALUATOR_PROCESS_ARGV = (
    str(ANGLER_PYTHON),
    str(RUNNER_PATH),
    "--evaluator-worker",
)
_UNRESOLVED_EVALUATOR_PROCESSES: dict[int, subprocess.Popen[bytes]] = {}
_UNRESOLVED_LIVE_ORCHESTRATION_OWNERS: dict[int, tuple[object, ...]] = {}


def _live_orchestration_key(evaluator: object) -> int:
    process = (
        evaluator
        if type(evaluator) is subprocess.Popen
        else getattr(evaluator, "process", None)
    )
    pid = getattr(process, "pid", None)
    return pid if type(pid) is int and pid > 0 else id(evaluator)


def _evaluator_process_receipt(pid: int) -> tuple[int, str, str, bytes]:
    pid = _integer(pid, "evaluator worker pid", minimum=1)
    root = Path("/proc") / str(pid)
    try:
        command = (root / "cmdline").read_bytes()
        cwd = os.readlink(root / "cwd")
        executable = os.readlink(root / "exe")
        process_stat = (root / "stat").read_text(encoding="ascii")
    except (OSError, UnicodeError) as error:
        raise V2IntegrityStop("evaluator worker process receipt is unavailable") from error
    suffix = process_stat.rsplit(") ", 1)
    if len(suffix) != 2:
        raise V2IntegrityStop("evaluator worker process stat differs")
    fields = suffix[1].split()
    if len(fields) < 20:
        raise V2IntegrityStop("evaluator worker process stat is truncated")
    try:
        starttime = int(fields[19])
    except ValueError as error:
        raise V2IntegrityStop("evaluator worker starttime differs") from error
    return starttime, cwd, executable, command


def _close_evaluator_process_terminal(
    process: subprocess.Popen[bytes],
) -> None:
    """Bound every evaluator close path and retain an unproven process handle."""

    if type(process) is not subprocess.Popen or type(process.pid) is not int:
        raise V2IntegrityStop("evaluator terminal-close process differs")
    failures: list[V2IntegrityStop] = []
    for stream, code in (
        (process.stdin, "V2_EVALUATOR_STDIN_CLOSE_FAILED"),
        (process.stdout, "V2_EVALUATOR_STDOUT_CLOSE_FAILED"),
    ):
        if stream is None:
            continue
        try:
            stream.close()
        except BaseException as error:
            failures.append(_redacted_cleanup_failure(error, code))
    if process.poll() is None:
        try:
            process.wait(timeout=0.5)
        except subprocess.TimeoutExpired:
            pass
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "V2_EVALUATOR_INITIAL_WAIT_FAILED"
                )
            )
    if process.poll() is None:
        try:
            process.terminate()
        except ProcessLookupError:
            pass
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(error, "V2_EVALUATOR_TERMINATE_FAILED")
            )
        try:
            process.wait(timeout=1.5)
        except subprocess.TimeoutExpired:
            pass
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(
                    error, "V2_EVALUATOR_TERMINATE_WAIT_FAILED"
                )
            )
    if process.poll() is None:
        try:
            process.kill()
        except ProcessLookupError:
            pass
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(error, "V2_EVALUATOR_KILL_FAILED")
            )
        try:
            process.wait(timeout=5.0)
        except BaseException as error:
            failures.append(
                _redacted_cleanup_failure(error, "V2_EVALUATOR_KILL_WAIT_FAILED")
            )
    if process.poll() is None:
        _UNRESOLVED_EVALUATOR_PROCESSES[process.pid] = process
        failures.append(V2IntegrityStop("V2_EVALUATOR_PROCESS_NOT_TERMINAL"))
    else:
        _UNRESOLVED_EVALUATOR_PROCESSES.pop(process.pid, None)
    if len(failures) == 1:
        raise failures[0]
    if failures:
        raise ExceptionGroup("V2 evaluator terminal close failed", failures) from None


@dataclass(slots=True)
class EvaluatorProcessClient:
    """One-use isolated V2 evaluator; raw seeds remain inside its pipe/process."""

    process: subprocess.Popen[bytes] = field(repr=False)
    purpose: Purpose
    identity: str
    commitments: dict[str, object]
    expected_seed_commitments: tuple[str, ...]
    expected_final_admission: str | None
    expected_seed_receipt: dict[str, object] | None
    expected_evaluator_commitments: dict[str, object] | None
    timeout_seconds: float = EVALUATOR_REQUEST_TIMEOUT_SECONDS
    protocol_identity: str = PROTOCOL_IDENTITY
    _request_id: int = field(default=1, init=False, repr=False)
    _closed: bool = field(default=False, init=False, repr=False)
    _construction_capability: object | None = field(
        default=None, init=False, repr=False
    )
    _worker_cwd: Path | None = field(default=None, init=False, repr=False)
    _worker_tmpdir: Path | None = field(default=None, init=False, repr=False)
    _worker_starttime: int | None = field(default=None, init=False, repr=False)
    _stdin_identity: tuple[int, int] | None = field(
        default=None, init=False, repr=False
    )
    _stdout_identity: tuple[int, int] | None = field(
        default=None, init=False, repr=False
    )

    def __post_init__(self) -> None:
        validate_purpose(self.purpose)
        expected = (
            QUALIFICATION_IDENTITY
            if self.purpose == "qualification"
            else EVALUATION_IDENTITY
        )
        if self.identity != expected or self.protocol_identity != PROTOCOL_IDENTITY:
            raise V2InvariantError("evaluator process identity differs")
        canonical_json_bytes(self.commitments)
        commitments = self.commitments.get("replicate_commitments")
        if (
            type(commitments) is not list
            or tuple(commitments) != self.expected_seed_commitments
            or self.commitments.get("identity") != self.identity
            or self.commitments.get("protocol_identity") != PROTOCOL_IDENTITY
            or self.commitments.get("purpose") != self.purpose
        ):
            raise V2InvariantError("evaluator process commitments differ")
        if self.purpose == "qualification":
            if (
                self.expected_seed_commitments
                != (qualification_replicate_commitment(),)
                or self.expected_final_admission is not None
                or self.expected_seed_receipt is not None
                or self.expected_evaluator_commitments is not None
            ):
                raise V2InvariantError("qualification evaluator binding differs")
        else:
            validate_evaluation_seed_commitments(self.expected_seed_commitments)
            _ref(self.expected_final_admission, "evaluator final admission")
            if self.expected_seed_receipt is None:
                raise V2InvariantError("evaluation evaluator lacks a seed receipt")
            if self.expected_evaluator_commitments != self.commitments:
                raise V2IntegrityStop("evaluation evaluator commitments changed")
        if self.process.stdin is None or self.process.stdout is None:
            raise V2InvariantError("evaluator process pipes are absent")

    @classmethod
    def start(
        cls,
        *,
        purpose: Purpose,
        expected_seed_commitments: Sequence[str],
        expected_final_admission: str | None,
        sealed_seed_path: str | Path | None = None,
        expected_seed_receipt: Mapping[str, object] | None = None,
        expected_evaluator_commitments: Mapping[str, object] | None = None,
        cwd: str | Path = EVALUATOR_CWD,
        tmpdir: str | Path = EVALUATOR_TMP,
    ) -> "EvaluatorProcessClient":
        purpose = validate_purpose(purpose)
        expected = tuple(expected_seed_commitments)
        if purpose == "qualification":
            if (
                sealed_seed_path is not None
                or expected_seed_receipt is not None
                or expected_evaluator_commitments is not None
                or expected != (
                qualification_replicate_commitment(),
                )
            ):
                raise V2InvariantError("qualification evaluator seed boundary differs")
            if expected_final_admission is not None:
                raise V2InvariantError("qualification evaluator acquired admission")
        else:
            validate_evaluation_seed_commitments(expected)
            _ref(expected_final_admission, "evaluator final admission")
            if sealed_seed_path is None or Path(sealed_seed_path) != SEALED_SEED_PATH:
                raise V2InvariantError("evaluation evaluator seed path differs")
            if expected_seed_receipt is None or expected_evaluator_commitments is None:
                raise V2InvariantError("evaluation evaluator public seal differs")
            expected_commitments_mapping = _canonical_mapping(
                expected_evaluator_commitments,
                "expected evaluator commitments",
            )
            expected_receipt_mapping = _canonical_mapping(
                expected_seed_receipt,
                "expected evaluator seed receipt",
            )
        working = Path(cwd)
        temporary = Path(tmpdir)
        if working != EVALUATOR_CWD or temporary != EVALUATOR_TMP:
            raise V2InvariantError("evaluator worker paths differ from literal scope")
        working_identity = _private_root_identity(working, "evaluator worker cwd")
        temporary_identity = _private_root_identity(temporary, "evaluator worker tmp")
        if (
            working_identity[0] != str(working)
            or temporary_identity[0] != str(temporary)
            or working_identity[1:] == temporary_identity[1:]
        ):
            raise V2InvariantError("evaluator worker paths alias")
        for path in (working, temporary):
            if stat.S_IMODE(os.lstat(path).st_mode) != 0o700:
                raise V2InvariantError("evaluator worker path mode differs")
        environment = _frozen_evaluator_environment()
        environment["TMPDIR"] = str(temporary)
        process = subprocess.Popen(
            list(_EVALUATOR_PROCESS_ARGV),
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            cwd=working,
            env=environment,
            close_fds=True,
        )
        try:
            assert process.stdin is not None and process.stdout is not None
            process_receipt = _evaluator_process_receipt(process.pid)
            stdin_metadata = os.fstat(process.stdin.fileno())
            stdout_metadata = os.fstat(process.stdout.fileno())
            construct = {
                "expected_final_admission": expected_final_admission,
                "expected_seed_commitments": list(expected),
                "purpose": purpose,
                "seed_seal_receipt": (
                    None
                    if expected_seed_receipt is None
                    else expected_receipt_mapping
                ),
                "sealed_seed_path": (
                    None if sealed_seed_path is None else str(sealed_seed_path)
                ),
            }
            _write_ipc_line(process.stdin, _ipc_envelope("construct", 0, construct))
            response = _read_ipc_line(
                process.stdout, timeout=EVALUATOR_REQUEST_TIMEOUT_SECONDS
            )
            if (
                set(response) != {"kind", "payload", "request_id", "schema"}
                or response.get("schema") != EVALUATOR_IPC_SCHEMA
                or response.get("kind") != "ok"
                or response.get("request_id") != 0
                or type(response.get("payload")) is not dict
            ):
                raise V2IntegrityStop("evaluator worker handshake failed")
            payload = response["payload"]
            if set(payload) != {
                "commitments",
                "expected_final_admission",
                "identity",
                "protocol_identity",
                "purpose",
                "seed_seal_ref",
            }:
                raise V2IntegrityStop("evaluator worker handshake fields differ")
            if payload["expected_final_admission"] != expected_final_admission:
                raise V2IntegrityStop("evaluator worker admission binding differs")
            expected_seed_seal_ref = (
                None
                if expected_seed_receipt is None
                else expected_receipt_mapping["seed_seal_ref"]
            )
            if payload["seed_seal_ref"] != expected_seed_seal_ref:
                raise V2IntegrityStop("evaluator worker seed seal differs")
            commitments = _canonical_mapping(
                payload["commitments"], "evaluator handshake commitments"
            )
            if commitments.get("replicate_commitments") != list(expected):
                raise V2IntegrityStop("evaluator worker seed commitments differ")
            if (
                expected_evaluator_commitments is not None
                and commitments != expected_commitments_mapping
            ):
                raise V2IntegrityStop("evaluator worker commitments changed")
            client = cls(
                process=process,
                purpose=purpose,
                identity=str(payload["identity"]),
                commitments=commitments,
                expected_seed_commitments=expected,
                expected_final_admission=expected_final_admission,
                expected_seed_receipt=(
                    None
                    if expected_seed_receipt is None
                    else expected_receipt_mapping
                ),
                expected_evaluator_commitments=(
                    None
                    if expected_evaluator_commitments is None
                    else expected_commitments_mapping
                ),
                protocol_identity=str(payload["protocol_identity"]),
            )
            client._construction_capability = (
                _EVALUATOR_PROCESS_CONSTRUCTION_CAPABILITY
            )
            client._worker_cwd = working
            client._worker_tmpdir = temporary
            client._worker_starttime = process_receipt[0]
            client._stdin_identity = (
                int(stdin_metadata.st_dev),
                int(stdin_metadata.st_ino),
            )
            client._stdout_identity = (
                int(stdout_metadata.st_dev),
                int(stdout_metadata.st_ino),
            )
            client._assert_live_product_boundary()
            return client
        except BaseException as error:
            primary = _redacted_failure(
                error, "V2_EVALUATOR_PROCESS_START_FAILED"
            )
            try:
                _close_evaluator_process_terminal(process)
            except BaseException as close_error:
                cleanup = _redacted_failure(
                    close_error, "V2_EVALUATOR_PROCESS_START_CLEANUP_FAILED"
                )
                raise ExceptionGroup(
                    "V2 evaluator start and cleanup failed",
                    [primary, cleanup],
                ) from None
            raise primary from None

    def _assert_live_product_boundary(self) -> None:
        process = self.process
        expected_command = b"\x00".join(
            item.encode("utf-8") for item in _EVALUATOR_PROCESS_ARGV
        ) + b"\x00"
        receipt = _evaluator_process_receipt(process.pid)
        stdin_identity: tuple[int, int] | None = None
        stdout_identity: tuple[int, int] | None = None
        if process.stdin is not None and process.stdout is not None:
            stdin_metadata = os.fstat(process.stdin.fileno())
            stdout_metadata = os.fstat(process.stdout.fileno())
            stdin_identity = (
                int(stdin_metadata.st_dev),
                int(stdin_metadata.st_ino),
            )
            stdout_identity = (
                int(stdout_metadata.st_dev),
                int(stdout_metadata.st_ino),
            )
        if (
            self._construction_capability
            is not _EVALUATOR_PROCESS_CONSTRUCTION_CAPABILITY
            or type(process) is not subprocess.Popen
            or tuple(process.args) != _EVALUATOR_PROCESS_ARGV
            or self._worker_cwd != EVALUATOR_CWD
            or self._worker_tmpdir != EVALUATOR_TMP
            or self._worker_starttime != receipt[0]
            or receipt[1] != str(EVALUATOR_CWD)
            or Path(receipt[2]).resolve(strict=True)
            != ANGLER_PYTHON.resolve(strict=True)
            or receipt[3] != expected_command
            or self._closed
            or process.poll() is not None
            or type(process.pid) is not int
            or process.pid <= 0
            or process.stdin is None
            or process.stdout is None
            or process.stderr is not None
            or not callable(getattr(process.stdin, "fileno", None))
            or not callable(getattr(process.stdout, "fileno", None))
            or stdin_identity != self._stdin_identity
            or stdout_identity != self._stdout_identity
        ):
            raise V2IntegrityStop("evaluator live-process capability differs")

    def _call(self, operation: str, payload: Mapping[str, object]) -> object:
        self._assert_live_product_boundary()
        request_id = self._request_id
        self._request_id += 1
        assert self.process.stdin is not None and self.process.stdout is not None
        _write_ipc_line(
            self.process.stdin,
            _ipc_envelope(
                "request",
                request_id,
                {"operation": _text(operation, "evaluator operation", 64), **dict(payload)},
            ),
        )
        response = _read_ipc_line(self.process.stdout, timeout=self.timeout_seconds)
        if (
            set(response) != {"kind", "payload", "request_id", "schema"}
            or response.get("schema") != EVALUATOR_IPC_SCHEMA
            or response.get("request_id") != request_id
        ):
            raise V2IntegrityStop("evaluator worker response envelope differs")
        if response.get("kind") != "ok":
            raise V2IntegrityStop("evaluator worker rejected the operation")
        return response.get("payload")

    def release_phase(self, phase: Phase) -> tuple[dict[str, object], ...]:
        value = self._call("release_phase", {"phase": validate_phase(phase)})
        if type(value) is not list:
            raise V2IntegrityStop("evaluator release response differs")
        return tuple(_task_canonical(item) for item in value)

    def complete_phase(self, phase: Phase) -> None:
        if self._call("complete_phase", {"phase": validate_phase(phase)}) is not None:
            raise V2IntegrityStop("evaluator completion response differs")

    def admit_final(self, admission_digest: str) -> None:
        if self._call(
            "admit_final", {"admission_digest": _ref(admission_digest, "admission")}
        ) is not None:
            raise V2IntegrityStop("evaluator admission response differs")

    def record_attempt(
        self,
        task_id: str,
        arm: Arm,
        attempt_receipt_ref: str,
        raw_response: str,
        *,
        proposal_admitted: bool,
    ) -> dict[str, object]:
        value = self._call(
            "record_attempt",
            {
                "arm": validate_arm(arm),
                "attempt_receipt_ref": _ref(
                    attempt_receipt_ref, "evaluator attempt receipt"
                ),
                "proposal_admitted": proposal_admitted,
                "raw_response": raw_response,
                "task_id": _ref(task_id, "evaluator task id"),
            },
        )
        return _canonical_judgment(value)

    def final_metrics(self) -> dict[str, object]:
        return _canonical_mapping(self._call("final_metrics", {}), "evaluator metrics")

    def close(self) -> None:
        if self._closed:
            return
        primary: V2IntegrityStop | None = None
        try:
            self._call("close", {})
        except BaseException as error:
            primary = _redacted_cleanup_failure(
                error, "V2_EVALUATOR_GRACEFUL_CLOSE_FAILED"
            )
        cleanup: V2IntegrityStop | None = None
        try:
            _close_evaluator_process_terminal(self.process)
        except BaseException as error:
            cleanup = _redacted_cleanup_failure(
                error, "V2_EVALUATOR_TERMINAL_CLOSE_FAILED"
            )
        returncode = self.process.poll()
        if returncode is not None:
            self._closed = True
            self._construction_capability = None
        if returncode is not None and returncode != 0 and primary is None:
            primary = V2IntegrityStop("V2_EVALUATOR_EXIT_STATUS_FAILED")
        if primary is not None and cleanup is not None:
            raise ExceptionGroup(
                "V2 evaluator close and terminal cleanup failed",
                [primary, cleanup],
            ) from None
        if primary is not None:
            raise primary from None
        if cleanup is not None:
            raise cleanup from None


def _evaluator_terminal_is_proven(evaluator: object) -> bool:
    """Return true only when a failed/strict close has terminal process proof."""

    if type(evaluator) is EvaluatorProcessClient:
        process = evaluator.process
        try:
            return (
                evaluator._closed
                and process.poll() is not None
                and process.pid not in _UNRESOLVED_EVALUATOR_PROCESSES
            )
        except BaseException:
            return False
    marker = getattr(evaluator, "terminally_closed", None)
    if callable(marker):
        try:
            marker = marker()
        except BaseException:
            return False
    return marker is True


def _retain_unresolved_live_orchestration(
    evaluator: object, *owners: object | None
) -> None:
    """Boundedly retain model/runtime ownership when evaluator reap is unproven."""

    key = _live_orchestration_key(evaluator)
    if (
        _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS
        and key not in _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS
    ):
        raise V2IntegrityStop("another unresolved live orchestration is retained")
    prior = _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS.get(key, ())
    if prior and prior[0] is not evaluator:
        raise V2IntegrityStop("retained live orchestration identity was rebound")
    retained_rows = list(prior or (evaluator,))
    for owner in owners:
        if owner is not None and all(owner is not item for item in retained_rows):
            retained_rows.append(owner)
    if len(retained_rows) > 8:
        raise V2IntegrityStop("retained live orchestration owner bound exceeded")
    retained = tuple(retained_rows)
    _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS[key] = retained


def _release_retained_live_orchestration(
    evaluator: object, dependencies: object
) -> None:
    key = _live_orchestration_key(evaluator)
    retained = _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS.get(key)
    if retained is None:
        return
    if retained[0] is not evaluator or all(
        item is not dependencies for item in retained
    ):
        raise V2IntegrityStop("retained live orchestration authority differs")
    _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS.pop(key)


def evaluator_worker_main() -> int:
    """Private subprocess entrypoint; never emits raw seeds or exceptions."""

    evaluator: object | None = None
    request_stream = sys.stdin.buffer
    response_stream = sys.stdout.buffer
    try:
        construct = _read_ipc_line(request_stream, timeout=120.0)
        if (
            construct.get("schema") != EVALUATOR_IPC_SCHEMA
            or construct.get("kind") != "construct"
            or construct.get("request_id") != 0
            or type(construct.get("payload")) is not dict
        ):
            return 2
        payload = construct["payload"]
        if set(payload) != {
            "expected_final_admission",
            "expected_seed_commitments",
            "purpose",
            "seed_seal_receipt",
            "sealed_seed_path",
        }:
            return 2
        purpose = validate_purpose(payload["purpose"])
        durable = _validate_private_worker_boundary(
            require_qualification_result=(purpose == "evaluation")
        )
        _validate_evaluator_launch_topology(
            purpose, tuple(payload["expected_seed_commitments"])
        )
        from experiments.evaluators.high_level_multidomain_v2_history_conditioning import (
            make_evaluation_evaluator,
            make_qualification_evaluator,
        )

        if purpose == "qualification":
            assert_all_live_paths_absent(
                (
                    QUALIFICATION_RESULT_PATH,
                    SEALED_SEED_PATH,
                    EVALUATION_ADMISSION_CLAIM_PATH,
                    EVALUATION_RUNTIME_ROOT,
                    EVALUATION_RESULT_PATH,
                )
            )
            if (
                payload["sealed_seed_path"] is not None
                or payload["seed_seal_receipt"] is not None
                or payload["expected_final_admission"] is not None
                or tuple(payload["expected_seed_commitments"])
                != (qualification_replicate_commitment(),)
            ):
                return 2
            evaluator = make_qualification_evaluator()
        else:
            expected_commitments = tuple(payload["expected_seed_commitments"])
            if type(payload["sealed_seed_path"]) is not str:
                return 2
            if type(payload["seed_seal_receipt"]) is not dict:
                return 2
            admission, _admission_sha256 = load_evaluation_admission_claim()
            durable_manifest = durable["manifest"]
            durable_release = durable["qualification_release"]
            durable_result = durable["qualification_result"]
            durable_seal = durable["source_seal"]
            if not all(
                type(item) is dict
                for item in (
                    durable_manifest,
                    durable_release,
                    durable_result,
                    durable_seal,
                )
            ):
                return 2
            expected_boundary = _evaluation_admission_boundary(
                manifest_ref=durable_manifest["manifest_ref"],
                manifest_sha256=durable["manifest_sha256"],
                qualification_result_ref=durable_result["result_ref"],
                qualification_result_sha256=durable[
                    "qualification_result_sha256"
                ],
                qualification_release_ref=durable_release["release_ref"],
                source_seal_ref=durable_seal["source_seal_ref"],
            )
            if any(
                admission.get(name) != value
                for name, value in expected_boundary.items()
            ):
                return 2
            if (
                payload["expected_final_admission"] != admission["admission_ref"]
                or payload["seed_seal_receipt"]
                != admission["seed_seal_receipt"]
                or list(expected_commitments) != admission["seed_commitments"]
            ):
                return 2
            raw_seeds, verified_seed_receipt = (
                _load_sealed_evaluation_seeds_for_worker(
                    payload["sealed_seed_path"],
                    expected_commitments,
                    payload["seed_seal_receipt"],
                )
            )
            evaluator = make_evaluation_evaluator(
                raw_seeds,
                expected_commitments,
                payload["expected_final_admission"],
            )
            raw_seeds = ()
            payload["sealed_seed_path"] = None
            payload["seed_seal_receipt"] = None
            observed_commitments = _canonical_mapping(
                getattr(evaluator, "commitments", None),
                "worker evaluation commitments",
            )
            if observed_commitments != admission["evaluator_commitments"]:
                return 2
        handshake = {
            "commitments": _canonical_mapping(
                getattr(evaluator, "commitments", None), "worker commitments"
            ),
            "expected_final_admission": payload["expected_final_admission"],
            "identity": getattr(evaluator, "identity", None),
            "protocol_identity": getattr(evaluator, "protocol_identity", None),
            "purpose": purpose,
            "seed_seal_ref": (
                None
                if purpose == "qualification"
                else verified_seed_receipt["seed_seal_ref"]
            ),
        }
        _write_ipc_line(response_stream, _ipc_envelope("ok", 0, handshake))
        while True:
            request = _read_ipc_line(request_stream, timeout=MAXIMUM_WALL_SECONDS)
            request_id = request.get("request_id")
            try:
                if (
                    request.get("schema") != EVALUATOR_IPC_SCHEMA
                    or request.get("kind") != "request"
                    or type(request_id) is not int
                    or type(request.get("payload")) is not dict
                ):
                    raise ValueError("invalid request envelope")
                body = request["payload"]
                operation = body.pop("operation", None)
                if operation == "release_phase" and set(body) == {"phase"}:
                    result = [
                        _task_canonical(item)
                        for item in evaluator.release_phase(body["phase"])
                    ]
                elif operation == "complete_phase" and set(body) == {"phase"}:
                    evaluator.complete_phase(body["phase"])
                    result = None
                elif operation == "admit_final" and set(body) == {
                    "admission_digest"
                }:
                    evaluator.admit_final(body["admission_digest"])
                    result = None
                elif operation == "record_attempt" and set(body) == {
                    "arm",
                    "attempt_receipt_ref",
                    "proposal_admitted",
                    "raw_response",
                    "task_id",
                }:
                    result = _canonical_mapping(
                        evaluator.record_attempt(
                            body["task_id"],
                            body["arm"],
                            body["attempt_receipt_ref"],
                            body["raw_response"],
                            proposal_admitted=body["proposal_admitted"],
                        ),
                        "worker judgment",
                    )
                elif operation == "final_metrics" and not body:
                    result = _canonical_mapping(
                        evaluator.final_metrics(), "worker metrics"
                    )
                elif operation == "close" and not body:
                    _write_ipc_line(
                        response_stream, _ipc_envelope("ok", request_id, None)
                    )
                    return 0
                else:
                    raise ValueError("unknown evaluator operation")
                _write_ipc_line(
                    response_stream, _ipc_envelope("ok", request_id, result)
                )
            except BaseException:
                _write_ipc_line(
                    response_stream,
                    _ipc_envelope("error", int(request_id or 0), "OPERATION_FAILED"),
                )
                return 3
    except BaseException:
        return 2


MAXIMUM_STATE_SCRATCH_ENTRIES = 262_144


def _fresh_source_seal_verifier(
    manifest: Mapping[str, object],
    manifest_sha256: str,
    source_seal: Mapping[str, object],
    *,
    loader: Callable[[], tuple[dict[str, object], str, dict[str, object]]] = (
        load_source_manifest
    ),
) -> Callable[[], str]:
    """Return one identity-stable callback that reopens every frozen source."""

    expected_manifest = dict(manifest)
    expected_manifest_bytes = canonical_json_bytes(expected_manifest)
    expected_sha256 = _raw_digest(
        manifest_sha256, "live source manifest digest"
    )
    expected_seal = dict(source_seal)
    expected_seal_bytes = canonical_json_bytes(expected_seal)
    expected_ref = _ref(
        expected_seal.get("source_seal_ref"), "live source seal ref"
    )
    if not callable(loader):
        raise TypeError("live source manifest loader differs")

    def verify() -> str:
        observed_manifest, observed_sha256, observed_seal = loader()
        if (
            canonical_json_bytes(observed_manifest) != expected_manifest_bytes
            or observed_sha256 != expected_sha256
            or canonical_json_bytes(observed_seal) != expected_seal_bytes
            or observed_seal.get("source_seal_ref") != expected_ref
        ):
            raise V2IntegrityStop("live source manifest or seal changed")
        return expected_ref

    if verify() != expected_ref:
        raise V2IntegrityStop("live source verifier did not close")
    return verify


def _bounded_no_follow_state_scratch_bytes(
    state_root: str | Path = STATE_ROOT,
    scratch_root: str | Path = SCRATCH_ROOT,
    *,
    maximum_bytes: int = MAXIMUM_STATE_SCRATCH_BYTES,
    maximum_entries: int = MAXIMUM_STATE_SCRATCH_ENTRIES,
) -> int:
    """Measure owned regular bytes without following links or crossing mounts."""

    byte_ceiling = _integer(
        maximum_bytes, "state/scratch byte ceiling", minimum=1
    )
    entry_ceiling = _integer(
        maximum_entries, "state/scratch entry ceiling", minimum=2
    )
    roots = (Path(state_root), Path(scratch_root))
    if (
        any(
            not root.is_absolute()
            or "." in root.parts
            or ".." in root.parts
            for root in roots
        )
        or len(set(roots)) != 2
    ):
        raise V2InvariantError("state/scratch measurement roots differ")
    owner = (os.geteuid(), os.getegid())
    seen: set[tuple[int, int]] = set()
    entries = 0
    total = 0

    def validate_metadata(metadata: os.stat_result, label: str) -> None:
        if (
            (metadata.st_uid, metadata.st_gid) != owner
            or stat.S_ISLNK(metadata.st_mode)
            or stat.S_IMODE(metadata.st_mode) & 0o022
        ):
            raise V2IntegrityStop(f"{label} metadata differs")

    def add_identity(metadata: os.stat_result, label: str) -> None:
        nonlocal entries
        identity = (int(metadata.st_dev), int(metadata.st_ino))
        if identity in seen:
            raise V2IntegrityStop(f"{label} inode aliases another entry")
        seen.add(identity)
        entries += 1
        if entries > entry_ceiling:
            raise V2IntegrityStop("state/scratch entry ceiling exceeded")

    def walk(directory_fd: int, root_device: int) -> None:
        nonlocal total
        try:
            iterator = os.scandir(directory_fd)
        except OSError as error:
            raise V2IntegrityStop(
                "state/scratch directory scan failed"
            ) from error
        with iterator:
            for entry in iterator:
                try:
                    before = entry.stat(follow_symlinks=False)
                except OSError as error:
                    raise V2IntegrityStop(
                        "state/scratch entry changed before inspection"
                    ) from error
                validate_metadata(before, "state/scratch entry")
                if int(before.st_dev) != root_device:
                    raise V2IntegrityStop(
                        "state/scratch traversal crossed a mount"
                    )
                if stat.S_ISDIR(before.st_mode):
                    flags = (
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_DIRECTORY", 0)
                        | getattr(os, "O_NOFOLLOW", 0)
                    )
                    try:
                        child_fd = os.open(
                            entry.name, flags, dir_fd=directory_fd
                        )
                    except OSError as error:
                        raise V2IntegrityStop(
                            "state/scratch directory changed while opening"
                        ) from error
                    try:
                        opened = os.fstat(child_fd)
                        if (
                            (opened.st_dev, opened.st_ino)
                            != (before.st_dev, before.st_ino)
                            or not stat.S_ISDIR(opened.st_mode)
                        ):
                            raise V2IntegrityStop(
                                "state/scratch directory inode changed"
                            )
                        add_identity(opened, "state/scratch directory")
                        walk(child_fd, root_device)
                    finally:
                        os.close(child_fd)
                elif stat.S_ISREG(before.st_mode):
                    flags = (
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_NOFOLLOW", 0)
                    )
                    try:
                        file_fd = os.open(
                            entry.name, flags, dir_fd=directory_fd
                        )
                    except OSError as error:
                        raise V2IntegrityStop(
                            "state/scratch file changed while opening"
                        ) from error
                    try:
                        opened = os.fstat(file_fd)
                        if (
                            (opened.st_dev, opened.st_ino)
                            != (before.st_dev, before.st_ino)
                            or not stat.S_ISREG(opened.st_mode)
                            or opened.st_nlink != 1
                            or opened.st_size < 0
                        ):
                            raise V2IntegrityStop(
                                "state/scratch regular file differs"
                            )
                        add_identity(opened, "state/scratch regular file")
                        total += int(opened.st_size)
                        if total > byte_ceiling:
                            raise V2IntegrityStop(
                                "state/scratch byte ceiling exceeded"
                            )
                    finally:
                        os.close(file_fd)
                else:
                    raise V2IntegrityStop(
                        "state/scratch contains a special filesystem entry"
                    )

    root_flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    for root in roots:
        try:
            root_fd = os.open(root, root_flags)
        except OSError as error:
            raise V2IntegrityStop(
                "state/scratch root is unavailable"
            ) from error
        try:
            opened = os.fstat(root_fd)
            current = os.lstat(root)
            validate_metadata(opened, "state/scratch root")
            if (
                not stat.S_ISDIR(opened.st_mode)
                or stat.S_IMODE(opened.st_mode) != 0o700
                or (opened.st_dev, opened.st_ino)
                != (current.st_dev, current.st_ino)
                or root.resolve(strict=True) != root
            ):
                raise V2IntegrityStop("state/scratch root identity differs")
            add_identity(opened, "state/scratch root")
            walk(root_fd, int(opened.st_dev))
        finally:
            os.close(root_fd)
    return total


def _live_gpu_probe(
    *,
    torch_module: object | None = None,
    gpu_inventory_runner: Callable[..., object] = subprocess.run,
    gpu_process_runner: Callable[..., object] = subprocess.run,
    environment: Mapping[str, str] | None = None,
) -> dict[str, object]:
    """Rejoin the exact physical/logical GPU assignment at every call seam."""

    if not callable(gpu_inventory_runner) or not callable(gpu_process_runner):
        raise TypeError("live GPU probe runners differ")
    observed_environment = dict(os.environ if environment is None else environment)
    if observed_environment.get("CUDA_VISIBLE_DEVICES") != ASSIGNED_GPU_UUID:
        raise V2IntegrityStop("live GPU visibility differs")
    inventory = gpu_inventory_runner(
        (
            "/usr/bin/nvidia-smi",
            "--query-gpu=uuid,name,pci.bus_id,compute_cap",
            "--format=csv,noheader,nounits",
        ),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    output = getattr(inventory, "stdout", None)
    if type(output) is not str:
        raise V2IntegrityStop("live physical GPU inventory is absent")
    physical: dict[str, tuple[str, str, str]] = {}
    for line in output.splitlines():
        fields = tuple(item.strip() for item in line.split(","))
        if len(fields) != 4 or fields[0] in physical:
            raise V2IntegrityStop("live physical GPU inventory differs")
        physical[fields[0]] = (fields[1], fields[2], fields[3])
    expected = {
        ASSIGNED_GPU_UUID: (
            "NVIDIA GeForce RTX 5080",
            "00000000:01:00.0",
            "12.0",
        ),
        UNASSIGNED_GPU_UUID: (
            "NVIDIA GeForce RTX 5070",
            "00000000:05:00.0",
            "12.0",
        ),
    }
    if physical != expected:
        raise V2IntegrityStop("live physical GPU identity changed")
    processes = gpu_process_runner(
        (
            "/usr/bin/nvidia-smi",
            "--query-compute-apps=gpu_uuid,pid",
            "--format=csv,noheader,nounits",
        ),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    process_output = getattr(processes, "stdout", None)
    if type(process_output) is not str:
        raise V2IntegrityStop("live GPU process inventory is absent")
    observed_compute_rows: set[tuple[str, int]] = set()
    assigned_processes = 0
    unassigned_processes = 0
    for line in process_output.splitlines():
        if not line.strip():
            continue
        fields = tuple(item.strip() for item in line.split(","))
        if len(fields) != 2 or fields[0] not in expected:
            raise V2IntegrityStop("live GPU process inventory differs")
        try:
            pid = int(fields[1])
        except ValueError as error:
            raise V2IntegrityStop("live GPU process PID differs") from error
        if pid < 1:
            raise V2IntegrityStop("live GPU process PID differs")
        row = (fields[0], pid)
        if row in observed_compute_rows:
            raise V2IntegrityStop("live GPU process inventory repeats a row")
        observed_compute_rows.add(row)
        if fields[0] == ASSIGNED_GPU_UUID:
            if pid != os.getpid():
                raise V2IntegrityStop(
                    "RTX 5080 has another compute-process owner"
                )
            assigned_processes += 1
        else:
            unassigned_processes += 1
    if assigned_processes > 1:
        raise V2IntegrityStop("RTX 5080 compute-process inventory differs")
    if unassigned_processes:
        raise V2IntegrityStop("RTX 5070 acquired a compute process")
    if torch_module is None:
        import torch as torch_module  # type: ignore[no-redef]
    cuda = getattr(torch_module, "cuda", None)
    if (
        cuda is None
        or not cuda.is_available()
        or cuda.device_count() != 1
        or cuda.current_device() != 0
        or cuda.get_device_name(0) != expected[ASSIGNED_GPU_UUID][0]
    ):
        raise V2IntegrityStop("live logical GPU identity changed")
    return {
        "assigned_name": expected[ASSIGNED_GPU_UUID][0],
        "assigned_uuid": ASSIGNED_GPU_UUID,
        "logical_device_count": 1,
        "logical_device_index": 0,
        "unassigned_compute_processes": 0,
        "unassigned_name": expected[UNASSIGNED_GPU_UUID][0],
        "unassigned_uuid": UNASSIGNED_GPU_UUID,
    }


def _exact_live_resource_sample(
    *,
    torch_module: object,
    configured_pools: int,
    measure_state_scratch_bytes: Callable[[], int],
) -> dict[str, int]:
    """Capture one exact arm-boundary sample without hidden retries."""

    configured = _integer(
        configured_pools,
        "live configured pools",
        minimum=1,
        maximum=MAXIMUM_CONFIGURED_POOLS,
    )
    if configured != MAXIMUM_CONFIGURED_POOLS or not callable(
        measure_state_scratch_bytes
    ):
        raise V2IntegrityStop("live configured pool boundary differs")
    if os.environ != _frozen_parent_environment():
        raise V2IntegrityStop("live resource environment changed")
    if (
        torch_module.get_num_threads() != 2
        or torch_module.get_num_interop_threads() != 1
    ):
        raise V2IntegrityStop("live Torch CPU pools changed")
    cuda = getattr(torch_module, "cuda", None)
    if cuda is None or cuda.device_count() != 1 or cuda.current_device() != 0:
        raise V2IntegrityStop("live CUDA resource boundary differs")
    process_count = 1 + len(_v2_descendant_depths(os.getpid()))
    state_scratch_bytes = measure_state_scratch_bytes()
    values = {
        "configured_pools": configured,
        "cuda_allocated_bytes": int(cuda.memory_allocated(0)),
        "cuda_reserved_bytes": int(cuda.memory_reserved(0)),
        "process_count": process_count,
        "rss_bytes": _peak_process_rss_bytes(),
        "state_scratch_bytes": state_scratch_bytes,
    }
    if any(type(value) is not int or value < 0 for value in values.values()):
        raise V2IntegrityStop("live resource sample differs")
    return values


@dataclass(frozen=True, slots=True)
class LiveBoundaryCallbacks:
    """Identity-stable live callbacks shared by guard and orchestration."""

    manifest_sha256: str
    source_seal_ref: str
    configured_pools: int
    verify_source_seal: Callable[[], str] = field(repr=False, compare=False)
    probe_gpu: Callable[[], Mapping[str, object]] = field(
        repr=False, compare=False
    )
    measure_state_scratch_bytes: Callable[[], int] = field(
        repr=False, compare=False
    )
    sample_resources: Callable[[], Mapping[str, int]] = field(
        repr=False, compare=False
    )

    def __post_init__(self) -> None:
        _raw_digest(self.manifest_sha256, "live callback manifest digest")
        _ref(self.source_seal_ref, "live callback source seal")
        if self.configured_pools != MAXIMUM_CONFIGURED_POOLS:
            raise V2IntegrityStop("live callback pool count differs")
        callbacks = (
            self.verify_source_seal,
            self.probe_gpu,
            self.measure_state_scratch_bytes,
            self.sample_resources,
        )
        if any(not callable(item) for item in callbacks) or len(
            {id(item) for item in callbacks}
        ) != len(callbacks):
            raise TypeError("live callback identity inventory differs")

    @classmethod
    def create_live(
        cls,
        *,
        manifest: Mapping[str, object],
        manifest_sha256: str,
        source_seal: Mapping[str, object],
        torch_module: object | None = None,
        parent_boundary_validator: Callable[..., Mapping[str, object]] = (
            validate_live_parent_boundary
        ),
        manifest_loader: Callable[
            [], tuple[dict[str, object], str, dict[str, object]]
        ] = load_source_manifest,
        gpu_inventory_runner: Callable[..., object] = subprocess.run,
        gpu_process_runner: Callable[..., object] = subprocess.run,
        state_root: str | Path = STATE_ROOT,
        scratch_root: str | Path = SCRATCH_ROOT,
    ) -> "LiveBoundaryCallbacks":
        if not callable(parent_boundary_validator):
            raise TypeError("live parent boundary validator differs")
        if torch_module is None:
            import torch as torch_module  # type: ignore[no-redef]
        parent = dict(
            parent_boundary_validator(
                require_unassigned_zero_processes=True,
                gpu_inventory_runner=gpu_inventory_runner,
                gpu_process_runner=gpu_process_runner,
                torch_module=torch_module,
            )
        )
        if (
            parent.get("configured_pool_sum") != MAXIMUM_CONFIGURED_POOLS
            or parent.get("unassigned_compute_processes") != 0
        ):
            raise V2IntegrityStop("live parent callback boundary differs")
        verifier = _fresh_source_seal_verifier(
            manifest,
            manifest_sha256,
            source_seal,
            loader=manifest_loader,
        )

        def probe_gpu() -> dict[str, object]:
            return _live_gpu_probe(
                torch_module=torch_module,
                gpu_inventory_runner=gpu_inventory_runner,
                gpu_process_runner=gpu_process_runner,
            )

        def measure_state_scratch_bytes() -> int:
            return _bounded_no_follow_state_scratch_bytes(
                state_root,
                scratch_root,
            )

        def sample_resources() -> dict[str, int]:
            return _exact_live_resource_sample(
                torch_module=torch_module,
                configured_pools=MAXIMUM_CONFIGURED_POOLS,
                measure_state_scratch_bytes=measure_state_scratch_bytes,
            )

        callbacks = cls(
            manifest_sha256=manifest_sha256,
            source_seal_ref=_ref(
                source_seal.get("source_seal_ref"),
                "live callback source seal",
            ),
            configured_pools=MAXIMUM_CONFIGURED_POOLS,
            verify_source_seal=verifier,
            probe_gpu=probe_gpu,
            measure_state_scratch_bytes=measure_state_scratch_bytes,
            sample_resources=sample_resources,
        )
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop("live callback source closure differs")
        callbacks.probe_gpu()
        callbacks.sample_resources()
        return callbacks


@dataclass(slots=True)
class _LivePhaseRuntime:
    """Create-once phase roots and accounting objects before model loading."""

    purpose: Purpose
    runtime_root: Path
    arm_runtime_parent: Path
    cognee_scope_parent: Path
    genesis: object = field(repr=False)
    ledger: EvidenceLedger = field(repr=False)
    path_registry: PathAllocationRegistry = field(repr=False)
    resources: ResourceLedger = field(repr=False)

    def __post_init__(self) -> None:
        purpose = validate_purpose(self.purpose)
        if (
            self.runtime_root / "arm-runtime" != self.arm_runtime_parent
            or self.runtime_root / "cognee-scopes"
            != self.cognee_scope_parent
            or type(self.ledger) is not EvidenceLedger
            or self.ledger._closed
            or type(self.path_registry) is not PathAllocationRegistry
            or self.path_registry.purpose != purpose
            or self.path_registry.ledger is not self.ledger
            or type(self.resources) is not ResourceLedger
            or self.resources.mode.value != purpose
        ):
            raise V2IntegrityStop("live phase runtime binding differs")


async def _create_live_phase_runtime(
    purpose: Purpose,
    *,
    runtime_root: str | Path | None = None,
    genesis_factory: Callable[[Path], object] | None = None,
    ledger_factory: Callable[..., EvidenceLedger] = EvidenceLedger,
    injected_paths: bool = False,
) -> _LivePhaseRuntime:
    """Consume one phase root and construct only CPU/accounting ownership."""

    purpose = validate_purpose(purpose)
    if type(injected_paths) is not bool or not callable(ledger_factory):
        raise TypeError("live phase runtime factory boundary differs")
    expected_root = (
        QUALIFICATION_RUNTIME_ROOT
        if purpose == "qualification"
        else EVALUATION_RUNTIME_ROOT
    )
    target = expected_root if runtime_root is None else Path(runtime_root)
    if (
        not target.is_absolute()
        or "." in target.parts
        or ".." in target.parts
        or (not injected_paths and target != expected_root)
    ):
        raise V2InvariantError("live phase runtime root differs")
    if genesis_factory is None:
        genesis_factory = _load_approved_r2_low_level_helpers()[
            "reconstruct_fresh_cpu_genesis"
        ]
    if not callable(genesis_factory):
        raise TypeError("live genesis factory differs")
    ledger: EvidenceLedger | None = None
    try:
        _create_private_directory_once(target)
        arm_runtime = _create_private_directory_once(target / "arm-runtime")
        cognee_scopes = _create_private_directory_once(
            target / "cognee-scopes"
        )
        genesis = await _maybe_await(genesis_factory(target / "genesis"))
        validate_genesis = getattr(genesis, "validate_artifacts", None)
        if (
            not callable(validate_genesis)
            or getattr(genesis, "root", None) != target / "genesis"
        ):
            raise V2IntegrityStop("live phase genesis differs")
        validate_genesis()
        if not injected_paths and type(genesis) is not (
            _load_approved_r2_low_level_helpers()["FreshGenesisBundle"]
        ):
            raise V2IntegrityStop("live phase genesis type differs")
        ledger = ledger_factory(target / "attempt-evidence.sqlite3", create=True)
        if type(ledger) is not EvidenceLedger or ledger._closed:
            raise V2IntegrityStop("live phase evidence ledger differs")
        _exact_child_names(
            target,
            {
                "arm-runtime",
                "attempt-evidence.sqlite3",
                "cognee-scopes",
                "genesis",
            },
            "live phase runtime",
        )
        resources = ResourceLedger(RunMode(purpose))
        registry = PathAllocationRegistry(purpose, ledger)
        return _LivePhaseRuntime(
            purpose=purpose,
            runtime_root=target,
            arm_runtime_parent=arm_runtime,
            cognee_scope_parent=cognee_scopes,
            genesis=genesis,
            ledger=ledger,
            path_registry=registry,
            resources=resources,
        )
    except BaseException as error:
        primary = _redacted_failure(
            error, "V2_PHASE_RUNTIME_CONSTRUCTION_FAILED"
        )
        cleanup: V2IntegrityStop | None = None
        if ledger is not None:
            try:
                ledger.close()
            except BaseException as close_error:
                cleanup = _redacted_failure(
                    close_error, "V2_PHASE_LEDGER_PARTIAL_CLOSE_FAILED"
                )
        if cleanup is not None:
            raise ExceptionGroup(
                "live phase construction and cleanup failed",
                [primary, cleanup],
            ) from None
        raise primary from None


@dataclass(slots=True)
class OrchestrationDependencies:
    mode: RunMode
    evaluator: object
    ledger: EvidenceLedger
    path_allocations: PathAllocationRegistry
    attempt_budget: AttemptBudget
    resources: ResourceLedger
    prepare_adaptation_attempt: Callable[
        [ScheduledAttempt], Awaitable[PromptPlan] | PromptPlan
    ] = field(repr=False)
    freeze_adaptation: Callable[
        [tuple[AttemptFinal, ...]],
        Awaitable[FrozenAdaptationState] | FrozenAdaptationState,
    ] = field(repr=False)
    prepare_task_block: Callable[
        [dict[str, object], TaskPreparationContext],
        Awaitable[PreparedTaskBlock] | PreparedTaskBlock,
    ] = field(repr=False)
    dispose_recall_captures: Callable[
        [PreparedTaskBlock, tuple[str, str]],
        Awaitable[PreparedTaskBlock] | PreparedTaskBlock,
    ] = field(repr=False)
    execute_attempt: Callable[
        [
            ScheduledAttempt,
            AttemptStage,
            PromptPlan,
            AttemptGenerationPermit,
            ResourceLedger,
            ArmExecutionContext | None,
        ],
        Awaitable[AttemptObservation] | AttemptObservation,
    ] = field(repr=False)
    apply_objective_feedback: Callable[
        [
            ScheduledAttempt,
            AttemptStage,
            AttemptObservation,
            Mapping[str, object],
            ResourceLedger,
        ],
        Awaitable[StatefulFeedbackApplication] | StatefulFeedbackApplication,
    ] = field(repr=False)
    finalize_persistent_stateful_attempt: Callable[
        [
            ScheduledAttempt,
            AttemptStage,
            AttemptObservation,
            Mapping[str, object],
            bool,
            str,
            ResourceLedger,
        ],
        Awaitable[PersistentRuntimeCleanupEvidence]
        | PersistentRuntimeCleanupEvidence,
    ] = field(repr=False)
    terminalize_stateful_attempt: Callable[
        [
            ScheduledAttempt,
            AttemptStage,
            AttemptObservation,
            Mapping[str, object],
            bool,
            ResourceLedger,
        ],
        Awaitable[CloneTerminalEvidence] | CloneTerminalEvidence,
    ] = field(repr=False)
    dispose_clone: Callable[
        [CloneTerminalEvidence, str],
        Awaitable[CloneLifecycleEvidence] | CloneLifecycleEvidence,
    ] = field(repr=False)
    dispose_stateless_attempt: Callable[
        [ScheduledAttempt, AttemptStage, AttemptObservation, str],
        Awaitable[StatelessRuntimeCleanupEvidence]
        | StatelessRuntimeCleanupEvidence,
    ] = field(repr=False)
    verify_frozen_adaptation: Callable[
        [FrozenAdaptationState], Awaitable[str] | str
    ] = field(repr=False)
    sample_resources: Callable[[], Mapping[str, int]] = field(repr=False)
    verify_source_seal: Callable[[], Awaitable[str] | str] = field(repr=False)
    close_runtime: Callable[[], Awaitable[None] | None] = field(repr=False)

    def __post_init__(self) -> None:
        if type(self.mode) is not RunMode:
            self.mode = RunMode(self.mode)
        if type(self.ledger) is not EvidenceLedger:
            raise TypeError("orchestration ledger differs")
        if (
            type(self.path_allocations) is not PathAllocationRegistry
            or self.path_allocations.ledger is not self.ledger
            or self.path_allocations.purpose != self.mode.value
            or type(self.attempt_budget) is not AttemptBudget
            or self.attempt_budget.mode is not self.mode
            or type(self.resources) is not ResourceLedger
            or self.resources.mode is not self.mode
        ):
            raise V2InvariantError("orchestration accounting mode differs")
        for value in (
            self.prepare_adaptation_attempt,
            self.freeze_adaptation,
            self.prepare_task_block,
            self.dispose_recall_captures,
            self.execute_attempt,
            self.apply_objective_feedback,
            self.finalize_persistent_stateful_attempt,
            self.terminalize_stateful_attempt,
            self.dispose_clone,
            self.dispose_stateless_attempt,
            self.verify_frozen_adaptation,
            self.sample_resources,
            self.verify_source_seal,
            self.close_runtime,
        ):
            if not callable(value):
                raise TypeError("orchestration dependency is not callable")
        if getattr(self.evaluator, "protocol_identity", None) != PROTOCOL_IDENTITY:
            raise V2InvariantError("evaluator protocol identity differs")
        expected_identity = (
            QUALIFICATION_IDENTITY
            if self.mode is RunMode.QUALIFICATION
            else EVALUATION_IDENTITY
        )
        if getattr(self.evaluator, "identity", None) != expected_identity:
            raise V2InvariantError("evaluator child identity differs")


def make_product_orchestration_dependencies(
    *,
    owner: V2ProductRuntimeOwner,
    evaluator: object,
    attempt_budget: AttemptBudget,
    sample_resources: Callable[[], Mapping[str, int]],
    verify_source_seal: Callable[[], Awaitable[str] | str],
) -> OrchestrationDependencies:
    """Bind the exact aggregate product owner into the closed run protocol."""

    if type(evaluator) is not EvaluatorProcessClient:
        raise V2IntegrityStop("V2 product evaluator type differs")
    evaluator._assert_live_product_boundary()
    if (
        type(owner) is not V2ProductRuntimeOwner
        or owner._closed
        or evaluator._closed
        or evaluator.purpose != owner.purpose
        or evaluator.expected_seed_commitments
        != owner.lineages.replicate_commitments
        or tuple(evaluator.commitments.get("replicate_commitments", ()))
        != owner.lineages.replicate_commitments
        or type(attempt_budget) is not AttemptBudget
        or attempt_budget.mode.value != owner.purpose
        or not callable(sample_resources)
        or not callable(verify_source_seal)
        or sample_resources is not owner.foundation.guard.sample_resources
        or verify_source_seal is not owner.foundation.guard.verify_source_seal
    ):
        raise V2IntegrityStop("V2 product orchestration binding differs")
    return OrchestrationDependencies(
        mode=RunMode(owner.purpose),
        evaluator=evaluator,
        ledger=owner.ledger,
        path_allocations=owner.path_registry,
        attempt_budget=attempt_budget,
        resources=owner.resources,
        prepare_adaptation_attempt=owner.prepare_adaptation_attempt,
        freeze_adaptation=owner.freeze_adaptation,
        prepare_task_block=owner.prepare_task_block,
        dispose_recall_captures=owner.dispose_recall_captures,
        execute_attempt=owner.execute_attempt,
        apply_objective_feedback=owner.apply_objective_feedback,
        finalize_persistent_stateful_attempt=(
            owner.finalize_persistent_stateful_attempt
        ),
        terminalize_stateful_attempt=owner.terminalize_stateful_attempt,
        dispose_clone=owner.dispose_clone,
        dispose_stateless_attempt=owner.dispose_stateless_attempt,
        verify_frozen_adaptation=owner.verify_frozen_adaptation,
        sample_resources=sample_resources,
        verify_source_seal=verify_source_seal,
        close_runtime=owner.close,
    )


async def _create_live_orchestration(
    purpose: Purpose,
    *,
    callbacks: LiveBoundaryCallbacks,
    replicate_commitments: Sequence[str],
    final_admission_ref: str | None = None,
    seed_receipt: Mapping[str, object] | None = None,
    evaluator_commitments: Mapping[str, object] | None = None,
    evaluator_factory: Callable[..., object] = EvaluatorProcessClient.start,
    phase_factory: Callable[..., object] = _create_live_phase_runtime,
    foundation_factory: Callable[..., object] = V2FoundationOwner.create_live,
    lineage_factory: Callable[..., object] = (
        V2LineageSetOwner.create_from_phase_parents
    ),
    product_factory: Callable[..., object] = V2ProductRuntimeOwner,
    mechanics_factory: Callable[[], object] = _live_v2_lineage_mechanics,
    dependency_factory: Callable[..., object] = (
        make_product_orchestration_dependencies
    ),
    injected_factories: bool = False,
) -> OrchestrationDependencies:
    """Build phase through product, then evaluator, with total cleanup."""

    purpose = validate_purpose(purpose)
    if type(callbacks) is not LiveBoundaryCallbacks:
        raise TypeError("live orchestration callbacks differ")
    if (
        _UNRESOLVED_LIVE_ORCHESTRATION_OWNERS
        or _UNRESOLVED_EVALUATOR_PROCESSES
    ):
        raise V2IntegrityStop("an unresolved live orchestration is retained")
    if type(injected_factories) is not bool or any(
        not callable(value)
        for value in (
            evaluator_factory,
            phase_factory,
            foundation_factory,
            lineage_factory,
            product_factory,
            mechanics_factory,
            dependency_factory,
        )
    ):
        raise TypeError("live orchestration factory inventory differs")
    replicates = tuple(replicate_commitments)
    if purpose == "qualification":
        if (
            replicates != (qualification_replicate_commitment(),)
            or final_admission_ref is not None
            or seed_receipt is not None
            or evaluator_commitments is not None
        ):
            raise V2InvariantError("live qualification evaluator binding differs")
    else:
        validate_evaluation_seed_commitments(replicates)
        _ref(final_admission_ref, "live evaluation admission")
        if seed_receipt is None or evaluator_commitments is None:
            raise V2InvariantError("live evaluation evaluator seal is absent")
    if callbacks.verify_source_seal() != callbacks.source_seal_ref:
        raise V2IntegrityStop("live orchestration source seal differs")

    evaluator: object | None = None
    phase: object | None = None
    foundation: object | None = None
    lineages: object | None = None
    product: object | None = None
    try:
        phase = await _maybe_await(phase_factory(purpose))
        if not injected_factories and type(phase) is not _LivePhaseRuntime:
            raise V2IntegrityStop("live phase owner differs")
        resources = getattr(phase, "resources", None)
        ledger = getattr(phase, "ledger", None)
        registry = getattr(phase, "path_registry", None)
        genesis = getattr(phase, "genesis", None)
        arm_runtime = getattr(phase, "arm_runtime_parent", None)
        cognee_scopes = getattr(phase, "cognee_scope_parent", None)
        if (
            type(resources) is not ResourceLedger
            or type(ledger) is not EvidenceLedger
            or type(registry) is not PathAllocationRegistry
            or registry.ledger is not ledger
        ):
            raise V2IntegrityStop("live phase accounting owner differs")
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop("live source changed after phase construction")

        foundation = await _maybe_await(
            foundation_factory(
                resources=resources,
                verify_source_seal=callbacks.verify_source_seal,
                expected_source_seal_ref=callbacks.source_seal_ref,
                sample_resources=callbacks.sample_resources,
                probe_gpu=callbacks.probe_gpu,
            )
        )
        if not injected_factories and type(foundation) is not V2FoundationOwner:
            raise V2IntegrityStop("live foundation owner differs")
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop(
                "live source changed after foundation construction"
            )
        mechanics = mechanics_factory()
        if not injected_factories and type(mechanics) is not V2LineageMechanics:
            raise V2IntegrityStop("live lineage mechanics differ")
        lineages = await _maybe_await(
            lineage_factory(
                purpose=purpose,
                replicate_commitments=replicates,
                arm_runtime_parent=arm_runtime,
                cognee_scope_parent=cognee_scopes,
                genesis=genesis,
                manifest=getattr(foundation, "manifest", None),
                ledger=ledger,
                acquisition_opener=open_v2_acquisition_scope_live,
                mechanics=mechanics,
                injected_paths=injected_factories,
            )
        )
        if not injected_factories and type(lineages) is not V2LineageSetOwner:
            raise V2IntegrityStop("live lineage-set owner differs")
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop("live source changed after lineage construction")
        product = await _maybe_await(
            product_factory(
                purpose=purpose,
                foundation=foundation,
                genesis=genesis,
                lineages=lineages,
                ledger=ledger,
                path_registry=registry,
                resources=resources,
                acquisition_opener=open_v2_acquisition_scope_live,
                mechanics=mechanics,
                arm_runtime_parent=arm_runtime,
                cognee_scope_parent=cognee_scopes,
            )
        )
        if not injected_factories and type(product) is not V2ProductRuntimeOwner:
            raise V2IntegrityStop("live product-runtime owner differs")
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop("live source changed before evaluator start")
        evaluator = await _maybe_await(
            evaluator_factory(
                purpose=purpose,
                expected_seed_commitments=replicates,
                expected_final_admission=final_admission_ref,
                sealed_seed_path=(
                    None if purpose == "qualification" else SEALED_SEED_PATH
                ),
                expected_seed_receipt=seed_receipt,
                expected_evaluator_commitments=evaluator_commitments,
            )
        )
        if not injected_factories and type(evaluator) is not EvaluatorProcessClient:
            raise V2IntegrityStop("live evaluator owner differs")
        if (
            getattr(evaluator, "purpose", None) != purpose
            or tuple(
                getattr(evaluator, "expected_seed_commitments", ())
            )
            != replicates
        ):
            raise V2IntegrityStop("live evaluator commitment owner differs")
        if callbacks.verify_source_seal() != callbacks.source_seal_ref:
            raise V2IntegrityStop("live source changed after evaluator start")
        dependencies = await _maybe_await(
            dependency_factory(
                owner=product,
                evaluator=evaluator,
                attempt_budget=AttemptBudget(RunMode(purpose)),
                sample_resources=callbacks.sample_resources,
                verify_source_seal=callbacks.verify_source_seal,
            )
        )
        if type(dependencies) is not OrchestrationDependencies:
            raise V2IntegrityStop("live orchestration dependencies differ")
        if (
            dependencies.sample_resources is not callbacks.sample_resources
            or dependencies.verify_source_seal is not callbacks.verify_source_seal
        ):
            raise V2IntegrityStop("live callback identity changed in composition")
        return dependencies
    except BaseException as error:
        primary = _redacted_failure(
            error, "V2_LIVE_ORCHESTRATION_CONSTRUCTION_FAILED"
        )
        failures: list[V2IntegrityStop] = []

        async def close_owned(value: object | None, code: str) -> None:
            if value is None:
                return
            close = getattr(value, "close", None)
            if not callable(close):
                failures.append(V2IntegrityStop(code))
                return
            try:
                await _maybe_await(close())
            except BaseException as close_error:
                failures.append(_redacted_failure(close_error, code))

        evaluator_close_failed = False
        if evaluator is not None:
            close_evaluator = getattr(evaluator, "close", None)
            if not callable(close_evaluator):
                evaluator_close_failed = True
                failures.append(
                    V2IntegrityStop("V2_PARTIAL_EVALUATOR_CLOSE_FAILED")
                )
            else:
                try:
                    await _maybe_await(close_evaluator())
                except BaseException as close_error:
                    evaluator_close_failed = True
                    failures.append(
                        _redacted_failure(
                            close_error, "V2_PARTIAL_EVALUATOR_CLOSE_FAILED"
                        )
                    )
            if (
                evaluator_close_failed
                or type(evaluator) is EvaluatorProcessClient
            ) and not _evaluator_terminal_is_proven(evaluator):
                _retain_unresolved_live_orchestration(
                    evaluator, product, lineages, foundation, phase
                )
                failures.append(
                    V2IntegrityStop("V2_PARTIAL_EVALUATOR_REAP_UNPROVEN")
                )
                raise ExceptionGroup(
                    "live orchestration construction and cleanup failed",
                    [primary, *failures],
                ) from None
        if _UNRESOLVED_EVALUATOR_PROCESSES:
            unresolved = tuple(_UNRESOLVED_EVALUATOR_PROCESSES.values())
            _retain_unresolved_live_orchestration(
                unresolved[0],
                *unresolved[1:],
                evaluator,
                product,
                lineages,
                foundation,
                phase,
            )
            failures.append(
                V2IntegrityStop("V2_PARTIAL_EVALUATOR_FACTORY_REAP_UNPROVEN")
            )
            raise ExceptionGroup(
                "live orchestration construction and cleanup failed",
                [primary, *failures],
            ) from None
        # Product/model ownership is released only after evaluator terminality.
        if product is not None:
            await close_owned(product, "V2_PARTIAL_PRODUCT_CLOSE_FAILED")
        else:
            if lineages is not None:
                close_unfrozen = getattr(
                    lineages, "close_unfrozen_preserving_state", None
                )
                if not callable(close_unfrozen):
                    failures.append(
                        V2IntegrityStop("V2_PARTIAL_LINEAGE_CLOSE_FAILED")
                    )
                else:
                    try:
                        await _maybe_await(close_unfrozen())
                    except BaseException as close_error:
                        failures.append(
                            _redacted_failure(
                                close_error,
                                "V2_PARTIAL_LINEAGE_CLOSE_FAILED",
                            )
                        )
            await close_owned(
                foundation, "V2_PARTIAL_FOUNDATION_CLOSE_FAILED"
            )
        phase_ledger = getattr(phase, "ledger", None)
        if phase_ledger is not None:
            await close_owned(
                phase_ledger, "V2_PARTIAL_PHASE_LEDGER_CLOSE_FAILED"
            )
        if failures:
            raise ExceptionGroup(
                "live orchestration construction and cleanup failed",
                [primary, *failures],
            ) from None
        raise primary from None


async def _sample_resource_boundary(dependencies: OrchestrationDependencies) -> None:
    row = dict(dependencies.sample_resources())
    expected = {
        "configured_pools",
        "cuda_allocated_bytes",
        "cuda_reserved_bytes",
        "process_count",
        "rss_bytes",
        "state_scratch_bytes",
    }
    if set(row) != expected:
        raise V2InvariantError("resource sampler fields differ")
    dependencies.resources.sample_boundary(**row)


async def _release_phase(
    evaluator: object, phase: Phase
) -> tuple[dict[str, object], ...]:
    method = getattr(evaluator, "release_phase", None)
    if not callable(method):
        raise TypeError("evaluator lacks release_phase")
    values = await _maybe_await(method(phase))
    if type(values) not in (tuple, list):
        raise TypeError("evaluator release must be one bounded sequence")
    return tuple(_task_canonical(item) for item in values)


async def _complete_phase(evaluator: object, phase: Phase) -> None:
    method = getattr(evaluator, "complete_phase", None)
    if not callable(method):
        raise TypeError("evaluator lacks complete_phase")
    await _maybe_await(method(phase))


async def _record_objective_attempt(
    evaluator: object,
    observation: AttemptObservation,
    attempt_receipt_ref: str,
) -> dict[str, object]:
    method = getattr(evaluator, "record_attempt", None)
    if not callable(method):
        raise TypeError("evaluator lacks record_attempt")
    judgment = await _maybe_await(
        method(
            observation.task_id,
            observation.arm,
            attempt_receipt_ref,
            observation.raw_response,
            proposal_admitted=observation.proposal_admitted,
        )
    )
    return _canonical_judgment(judgment)


def _validate_observation_against_plan(
    scheduled: ScheduledAttempt,
    observation: AttemptObservation,
    prompt_plan: PromptPlan,
) -> None:
    if (
        observation.task_id != scheduled.task_id
        or observation.arm != scheduled.arm
    ):
        raise V2InvariantError("attempt executor returned another scheduled cell")
    if (
        observation.proposal_prompt_ref != prompt_plan.prompt_ref
        or observation.proposal_prompt_tokens != len(prompt_plan.token_ids)
        or tuple(observation.recalled_record_refs)
        != tuple(item.record_ref for item in prompt_plan.history_plan.presentations)
    ):
        raise V2InvariantError("attempt observation differs from its frozen prompt plan")
    if any(
        value is not None
        for value in (
            observation.prospective_reservation_ref,
            observation.prospective_batch_ref,
            observation.resolution_ref,
            observation.clone_lifecycle,
        )
    ):
        raise V2InvariantError("attempt executor crossed the objective-feedback boundary")
    if observation.proposal_admitted and scheduled.arm in STATELESS_ARMS:
        expected = control_selection_index(
            public_task_ref(scheduled.task), len(observation.proposals)
        )
        if observation.selected_index != expected:
            raise V2IntegrityStop("stateless selection differs from arm-blind control index")


def _validate_feedback_application(
    scheduled: ScheduledAttempt,
    before: AttemptObservation,
    application: StatefulFeedbackApplication,
) -> None:
    if (
        type(application) is not StatefulFeedbackApplication
        or application.observation.pre_feedback_binding()
        != before.pre_feedback_binding()
        or application.clone_terminal is not None
    ):
        raise V2IntegrityStop("objective feedback changed pre-feedback evidence")


async def _execute_one_attempt(
    dependencies: OrchestrationDependencies,
    scheduled: ScheduledAttempt,
    prompt_plan: PromptPlan,
    arm_context: ArmExecutionContext | None = None,
) -> AttemptFinal:
    if (scheduled.phase == "adaptation") != (arm_context is None):
        raise V2InvariantError("attempt preparation phase differs")
    if arm_context is not None and (
        type(arm_context) is not ArmExecutionContext
        or arm_context.task_id != scheduled.task_id
        or arm_context.arm != scheduled.arm
    ):
        raise V2IntegrityStop("attempt arm capability differs")
    await _sample_resource_boundary(dependencies)
    stage = AttemptStage.from_schedule(scheduled, prompt_plan)
    receipt_ref = dependencies.ledger.append_stage(stage, prompt_plan)
    permit = AttemptGenerationPermit(
        dependencies.attempt_budget,
        stage.task_id,
        stage.arm,
    )
    observation = await _maybe_await(
        dependencies.execute_attempt(
            scheduled,
            stage,
            prompt_plan,
            permit,
            dependencies.resources,
            arm_context,
        )
    )
    if type(observation) is not AttemptObservation:
        raise TypeError("attempt executor must return exact AttemptObservation")
    permit.validate_observation(observation)
    _validate_observation_against_plan(scheduled, observation, prompt_plan)
    pre_feedback_observation_ref = observation.observation_ref
    dependencies.ledger.append_artifact_durable(
        pre_feedback_observation_ref,
        "attempt-observation",
        observation.to_canonical(),
    )
    dependencies.resources.record_generation(
        observation.proposal_prompt_tokens,
        observation.proposal_output_tokens,
    )
    if observation.proposal_admitted:
        dependencies.resources.record_generation(
            observation.execution_prompt_tokens,  # type: ignore[arg-type]
            observation.execution_output_tokens,  # type: ignore[arg-type]
        )
    judgment = await _record_objective_attempt(
        dependencies.evaluator, observation, receipt_ref
    )
    judgment = validate_objective_judgment_for_attempt(
        stage=stage,
        observation=observation,
        attempt_receipt_ref=receipt_ref,
        judgment=judgment,
    )
    dependencies.ledger.append_artifact_durable(
        canonical_ref("objective-judgment", judgment),
        "objective-judgment",
        judgment,
    )
    clone_terminal: CloneTerminalEvidence | None = None
    feedback_applied = False
    if observation.proposal_admitted and scheduled.arm in STATEFUL_ARMS:
        application = await _maybe_await(
            dependencies.apply_objective_feedback(
                scheduled,
                stage,
                observation,
                judgment,
                dependencies.resources,
            )
        )
        if type(application) is not StatefulFeedbackApplication:
            raise TypeError("stateful feedback callback returned another type")
        _validate_feedback_application(scheduled, observation, application)
        observation = application.observation
        feedback_applied = True
        dependencies.ledger.append_artifact_durable(
            observation.observation_ref,
            "attempt-observation",
            observation.to_canonical(),
        )
    clone_required = scheduled.arm in STATEFUL_ARMS and scheduled.phase in (
        "development",
        "final",
    )
    if clone_required:
        clone_terminal = await _maybe_await(
            dependencies.terminalize_stateful_attempt(
                scheduled,
                stage,
                observation,
                judgment,
                feedback_applied,
                dependencies.resources,
            )
        )
        if (
            type(clone_terminal) is not CloneTerminalEvidence
            or clone_terminal.task_id != stage.task_id
            or clone_terminal.arm != stage.arm
            or not clone_terminal.cognee_scope_roots
        ):
            raise V2IntegrityStop("stateful clone terminal evidence differs")
        dependencies.path_allocations.require_clone(clone_terminal)
    witness = make_congruence_witness(
        task_id=stage.task_id,
        arm=stage.arm,
        attempt_receipt_ref=receipt_ref,
        selected_trace_ref=(
            None
            if observation.selected_trace is None
            else content_ref({"selected_trace": observation.selected_trace})
        ),
        execution_request_ref=observation.execution_request_ref,
        execution_receipt_ref=observation.execution_receipt_ref,
        response_ref=(
            None
            if not observation.proposal_admitted
            else _ref(judgment.get("response_commitment"), "judged response commitment")
        ),
        objective_judgment_ref=_ref(
            judgment.get("evaluator_record_ref"), "objective judgment ref"
        ),
        selected_trace_bound=observation.selected_trace_bound,
        response_bound=observation.response_bound,
        response_conforms=(
            None
            if not observation.proposal_admitted
            else bool(judgment.get("response_conforms"))
        ),
        objective_success=(
            None
            if not observation.proposal_admitted
            else bool(judgment.get("success"))
        ),
        selected_grammar_class=observation.selected_grammar_class,
        response_grammar_class=observation.response_grammar_class,
    )
    witness.assert_integrity()
    terminal_disposition_ref = dependencies.ledger.record_terminal_disposition(
        stage=stage,
        attempt_receipt_ref=receipt_ref,
        pre_feedback_observation_ref=pre_feedback_observation_ref,
        observation=observation,
        judgment=judgment,
        witness=witness,
        clone_terminal=clone_terminal,
    )
    if scheduled.phase == "adaptation" and scheduled.arm in STATEFUL_ARMS:
        persistent_cleanup = await _maybe_await(
            dependencies.finalize_persistent_stateful_attempt(
                scheduled,
                stage,
                observation,
                judgment,
                feedback_applied,
                terminal_disposition_ref,
                dependencies.resources,
            )
        )
        terminal = getattr(persistent_cleanup, "terminal", None)
        if (
            type(persistent_cleanup) is not PersistentRuntimeCleanupEvidence
            or type(terminal) is not PersistentRuntimeTerminalEvidence
            or terminal.task_id != stage.task_id
            or terminal.arm != stage.arm
            or terminal.replicate_commitment != stage.replicate_commitment
            or terminal.stage_ref != stage.stage_ref
            or terminal.attempt_receipt_ref != receipt_ref
            or terminal.terminal_disposition_ref != terminal_disposition_ref
            or terminal.feedback_applied is not feedback_applied
        ):
            raise V2IntegrityStop("persistent V2 runtime cleanup receipt differs")
        dependencies.ledger.require_artifact(
            terminal.terminal_ref,
            "persistent-runtime-terminal",
            terminal.to_canonical(),
        )
        dependencies.ledger.require_artifact(
            persistent_cleanup.cleanup_ref,
            "persistent-runtime-cleanup",
            persistent_cleanup.to_canonical(),
        )
    if clone_terminal is not None:
        lifecycle = await _maybe_await(
            dependencies.dispose_clone(clone_terminal, terminal_disposition_ref)
        )
        if (
            type(lifecycle) is not CloneLifecycleEvidence
            or lifecycle.terminal != clone_terminal
            or lifecycle.terminal_disposition_ref != terminal_disposition_ref
        ):
            raise V2IntegrityStop("clone cleanup receipt differs")
        dependencies.ledger.require_artifact(
            lifecycle.lifecycle_ref,
            "clone-lifecycle",
            lifecycle.to_canonical(),
        )
        for target in (
            Path(clone_terminal.clone_root),
            *(Path(item) for item in clone_terminal.cognee_scope_roots),
        ):
            try:
                os.lstat(target)
            except FileNotFoundError:
                continue
            raise V2IntegrityStop("disposable clone cleanup target remains")
        dependencies.path_allocations.mark_closed(clone_terminal.allocation_ref)
        source_identity = _private_root_identity(
            clone_terminal.source_root, "post-cleanup source baseline"
        )
        if source_identity[0] != clone_terminal.source_root:
            raise V2IntegrityStop("post-cleanup source baseline path changed")
        observation = replace(observation, clone_lifecycle=lifecycle)
    elif scheduled.arm in STATELESS_ARMS:
        cleanup = await _maybe_await(
            dependencies.dispose_stateless_attempt(
                scheduled,
                stage,
                observation,
                terminal_disposition_ref,
            )
        )
        if (
            type(cleanup) is not StatelessRuntimeCleanupEvidence
            or cleanup.terminal.task_id != stage.task_id
            or cleanup.terminal.arm != stage.arm
            or cleanup.terminal.terminal_disposition_ref
            != terminal_disposition_ref
        ):
            raise V2IntegrityStop("stateless runtime cleanup receipt differs")
        dependencies.ledger.require_artifact(
            cleanup.terminal.terminal_ref,
            "stateless-runtime-terminal",
            cleanup.terminal.to_canonical(),
        )
        dependencies.ledger.require_artifact(
            cleanup.cleanup_ref,
            "stateless-runtime-cleanup",
            cleanup.to_canonical(),
        )
        dependencies.path_allocations.require_stateless(cleanup.terminal)
        try:
            os.lstat(cleanup.terminal.runtime_root)
        except FileNotFoundError:
            pass
        else:
            raise V2IntegrityStop("stateless runtime root remains after cleanup")
        dependencies.path_allocations.mark_closed(
            cleanup.terminal.allocation_ref
        )
    final = AttemptFinal(
        stage=stage,
        attempt_receipt_ref=receipt_ref,
        terminal_disposition_ref=terminal_disposition_ref,
        observation=observation,
        judgment=judgment,
        witness=witness,
    )
    dependencies.ledger.finalize(final)
    dependencies.attempt_budget.finish(stage.task_id, stage.arm)
    await _sample_resource_boundary(dependencies)
    return final


def _paired_generation_equality(
    initial: PairEqualityEvidence,
    left: AttemptFinal,
    right: AttemptFinal,
) -> PairEqualityEvidence:
    if (
        left.observation.proposal_generation_ref
        != right.observation.proposal_generation_ref
    ):
        raise V2IntegrityStop("paired greedy proposal generation identity differs")
    admission_pair = (
        left.observation.proposal_admitted,
        right.observation.proposal_admitted,
    )
    if admission_pair == (False, False):
        if left.observation.proposals or right.observation.proposals:
            raise V2IntegrityStop("paired malformed generation exposed proposals")
        return replace(initial, proposal_sets_equal=True)
    if admission_pair != (True, True):
        raise V2IntegrityStop("paired identical generation admission differs")
    return bind_paired_proposal_sets(
        initial,
        left.observation.proposals,
        right.observation.proposals,
    )


async def _execute_prepared_task_block(
    dependencies: OrchestrationDependencies,
    scheduled: Sequence[ScheduledAttempt],
    frozen: FrozenAdaptationState,
) -> tuple[tuple[AttemptFinal, ...], tuple[PairEqualityEvidence, PairEqualityEvidence]]:
    rows = tuple(scheduled)
    if len(rows) != 8 or len({item.task_id for item in rows}) != 1 or {
        item.arm for item in rows
    } != set(ARMS):
        raise V2InvariantError("prepared task execution requires one eight-arm block")
    task = rows[0].task
    preparation_context = TaskPreparationContext.create(task, frozen)
    pending = await _maybe_await(
        dependencies.prepare_task_block(task, preparation_context)
    )
    if (
        type(pending) is not PreparedTaskBlock
        or pending.task_id != rows[0].task_id
        or pending.public_task_ref != public_task_ref(task)
        or pending.replicate_commitment != rows[0].replicate_commitment
        or pending.frozen_state_ref != frozen.freeze_ref
    ):
        raise V2InvariantError("prepared task block does not bind the schedule")
    expected_baselines = frozen.baselines_for(rows[0].replicate_commitment)
    if dict(pending.baseline_seal_refs) != {
        arm: expected_baselines[arm].seal_ref for arm in STATEFUL_ARMS
    } or pending.donor_catalog_ref != frozen.catalog_for(
        rows[0].replicate_commitment
    ).catalog_ref:
        raise V2InvariantError("prepared task block does not bind its lineage")
    if pending.ordinary_private_replay is None:
        raise V2IntegrityStop("prepared task lacks exact private ordinary recall hits")
    pending_captures = (pending.neutral_recall, pending.ordinary_recall)
    capture_baselines = (
        expected_baselines["IN_FULL_NEUTRAL_12"],
        expected_baselines["IO_FULL_ORDINARY_12"],
    )
    for capture, baseline in zip(
        pending_captures, capture_baselines, strict=True
    ):
        if (
            capture.source_baseline_seal_ref != baseline.seal_ref
            or capture.source_root != baseline.root
            or capture.source_hashes
            != _hash_pairs(dict(baseline.hashes), "capture baseline hashes")
        ):
            raise V2IntegrityStop("recall capture source does not rejoin baseline")
        dependencies.path_allocations.require_capture(capture)
    if any(
        item.cleanup_complete or len(item.cleanup_paths) < 2
        for item in pending_captures
    ):
        raise V2IntegrityStop(
            "recall capture cleanup inventory/order differs"
        )
    cleanup_identities: set[tuple[int, int]] = set()
    for capture in pending_captures:
        for target in capture.cleanup_paths:
            identity = _private_root_identity(target, "pending recall cleanup root")
            if identity[0] != target or identity[1:] in cleanup_identities:
                raise V2IntegrityStop("pending recall cleanup roots alias")
            cleanup_identities.add(identity[1:])
    terminal_refs = tuple(item.terminal_ref for item in pending_captures)
    for capture in pending_captures:
        dependencies.ledger.append_artifact_durable(
            capture.terminal_ref,
            "recall-capture-terminal",
            capture.terminal_payload,
        )
    prepared = await _maybe_await(
        dependencies.dispose_recall_captures(pending, terminal_refs)
    )
    if (
        type(prepared) is not PreparedTaskBlock
        or prepared.preparation_ref != pending.preparation_ref
        or tuple(
            item.terminal_ref
            for item in (prepared.neutral_recall, prepared.ordinary_recall)
        )
        != terminal_refs
        or any(
            not item.cleanup_complete
            for item in (prepared.neutral_recall, prepared.ordinary_recall)
        )
    ):
        raise V2IntegrityStop("recall capture cleanup evidence differs")
    for capture in (prepared.neutral_recall, prepared.ordinary_recall):
        dependencies.ledger.require_artifact(
            capture.terminal_ref,
            "recall-capture-terminal",
            capture.terminal_payload,
        )
        dependencies.ledger.require_artifact(
            capture.cleanup_ref,
            "recall-capture-cleanup",
            capture.cleanup_payload,
        )
        for target in capture.cleanup_paths:
            try:
                os.lstat(target)
            except FileNotFoundError:
                continue
            raise V2IntegrityStop("disposed recall capture path remains")
        dependencies.path_allocations.mark_closed(capture.allocation_ref)
    pre_generation_freeze = await _maybe_await(
        dependencies.verify_frozen_adaptation(frozen)
    )
    if pre_generation_freeze != frozen.freeze_ref:
        raise V2IntegrityStop("frozen adaptation changed before task generation")
    for _arm, plan in prepared.prompt_plans:
        dependencies.ledger.append_artifact(
            plan.history_plan.plan_ref,
            "history-plan",
            plan.history_plan.to_canonical(),
        )
        dependencies.ledger.append_artifact(
            plan.plan_ref, "prompt-plan", plan.to_canonical()
        )
    for capture in (prepared.neutral_recall, prepared.ordinary_recall):
        dependencies.ledger.append_artifact(
            capture.capture_ref,
            "frozen-recall-capture",
            capture.to_canonical(),
        )
    dependencies.ledger.append_artifact(
        prepared.block_ref, "prepared-task-block", prepared.to_canonical()
    )
    results: list[AttemptFinal] = []
    for scheduled_attempt in rows:
        if scheduled_attempt.arm == "IN_FULL_NEUTRAL_12":
            arm_context = ArmExecutionContext(
                task_id=prepared.task_id,
                arm=scheduled_attempt.arm,
                preparation_ref=prepared.preparation_ref,
                baseline=expected_baselines[scheduled_attempt.arm],
                neutral_episode_refs=prepared.neutral_episode_refs,
            )
        elif scheduled_attempt.arm == "IO_FULL_ORDINARY_12":
            arm_context = ArmExecutionContext(
                task_id=prepared.task_id,
                arm=scheduled_attempt.arm,
                preparation_ref=prepared.preparation_ref,
                baseline=expected_baselines[scheduled_attempt.arm],
                ordinary_private_replay=prepared.ordinary_private_replay,
            )
        else:
            arm_context = ArmExecutionContext(
                task_id=prepared.task_id,
                arm=scheduled_attempt.arm,
                preparation_ref=prepared.preparation_ref,
            )
        final = await _execute_one_attempt(
            dependencies,
            scheduled_attempt,
            prepared.prompt_for(scheduled_attempt.arm),
            arm_context,
        )
        results.append(final)
        if scheduled_attempt.arm in STATEFUL_ARMS:
            post_cleanup_freeze = await _maybe_await(
                dependencies.verify_frozen_adaptation(frozen)
            )
            if post_cleanup_freeze != frozen.freeze_ref:
                raise V2IntegrityStop(
                    "frozen adaptation changed during stateful clone cleanup"
                )
    for final in results:
        if final.stage.arm not in STATEFUL_ARMS:
            continue
        baseline = expected_baselines[final.stage.arm]
        lifecycle = final.observation.clone_lifecycle
        expected_hashes = _hash_pairs(dict(baseline.hashes), "sealed baseline")
        if (
            lifecycle is None
            or lifecycle.terminal.source_root != baseline.root
            or lifecycle.terminal.source_before != expected_hashes
            or lifecycle.terminal.source_after != expected_hashes
            or final.stage.replicate_commitment != baseline.replicate_commitment
        ):
            raise V2IntegrityStop(
                "disposable clone does not rejoin its exact frozen baseline"
            )
    by_arm = {item.stage.arm: item for item in results}
    pair_rows = (
        _paired_generation_equality(
            prepared.pair_equalities[0],
            by_arm["F0_NEUTRAL_FORMATTED_12"],
            by_arm["IN_FULL_NEUTRAL_12"],
        ),
        _paired_generation_equality(
            prepared.pair_equalities[1],
            by_arm["O0_ORDINARY_FROZEN_12"],
            by_arm["IO_FULL_ORDINARY_12"],
        ),
    )
    for item in pair_rows:
        dependencies.ledger.append_artifact(
            item.equality_ref, "pair-equality", item.to_canonical()
        )
    observed_freeze = await _maybe_await(
        dependencies.verify_frozen_adaptation(frozen)
    )
    if observed_freeze != frozen.freeze_ref:
        raise V2IntegrityStop("frozen adaptation state changed after a task block")
    return tuple(results), pair_rows


def _schedule_blocks(
    scheduled: Sequence[ScheduledAttempt],
) -> tuple[tuple[ScheduledAttempt, ...], ...]:
    rows = tuple(scheduled)
    output: list[tuple[ScheduledAttempt, ...]] = []
    cursor = 0
    while cursor < len(rows):
        block = rows[cursor : cursor + 8]
        if len(block) != 8 or len({item.task_id for item in block}) != 1:
            raise V2InvariantError("eight-arm schedule is not task-contiguous")
        output.append(block)
        cursor += 8
    return tuple(output)


def _materialize_frozen_state(
    ledger: EvidenceLedger, frozen: FrozenAdaptationState
) -> None:
    if type(ledger) is not EvidenceLedger or type(frozen) is not FrozenAdaptationState:
        raise TypeError("frozen-state materialization inputs differ")
    for item in frozen.baseline_seals:
        ledger.append_artifact(item.seal_ref, "baseline-seal", item.to_canonical())
    for item in frozen.donor_catalogs:
        ledger.append_artifact(item.catalog_ref, "donor-catalog", item.to_canonical())
    ledger.append_artifact(
        frozen.freeze_ref, "frozen-adaptation-state", frozen.to_canonical()
    )


def _materialize_evaluator_metrics(
    ledger: EvidenceLedger, metrics: Mapping[str, object]
) -> str:
    if type(ledger) is not EvidenceLedger:
        raise TypeError("evaluator metrics ledger differs")
    payload = _canonical_mapping(metrics, "evaluator final metrics artifact")
    artifact_ref = canonical_ref("evaluator-final-metrics", payload)
    ledger.append_artifact_durable(
        artifact_ref,
        "evaluator-final-metrics",
        payload,
    )
    return artifact_ref


def _run_provenance_closure_payload(
    *,
    purpose: Purpose,
    authorization_ref: str,
    source_seal_ref: str,
    evaluator_commitments_ref: str,
    frozen_adaptation_ref: str,
    evaluator_metrics_artifact_ref: str,
) -> dict[str, object]:
    return {
        "authorization_ref": _ref(
            authorization_ref, "run provenance authorization ref"
        ),
        "evaluator_commitments_ref": _ref(
            evaluator_commitments_ref,
            "run provenance evaluator commitments ref",
        ),
        "evaluator_metrics_artifact_ref": _ref(
            evaluator_metrics_artifact_ref,
            "run provenance evaluator metrics artifact ref",
        ),
        "frozen_adaptation_ref": _ref(
            frozen_adaptation_ref, "run provenance frozen adaptation ref"
        ),
        "protocol_identity": PROTOCOL_IDENTITY,
        "purpose": validate_purpose(purpose),
        "schema": RUN_PROVENANCE_CLOSURE_SCHEMA,
        "source_seal_ref": _ref(
            source_seal_ref, "run provenance source seal ref"
        ),
    }


def _materialize_run_provenance_closure(
    ledger: EvidenceLedger,
    *,
    purpose: Purpose,
    authorization_ref: str,
    source_seal_ref: str,
    evaluator_commitments: Mapping[str, object],
    frozen: FrozenAdaptationState,
    evaluator_metrics_artifact_ref: str,
) -> str:
    if type(ledger) is not EvidenceLedger:
        raise TypeError("run provenance ledger differs")
    purpose = validate_purpose(purpose)
    authorization_ref = _ref(
        authorization_ref, "run provenance authorization ref"
    )
    source_seal_ref = _ref(source_seal_ref, "run provenance source seal ref")
    evaluator_metrics_artifact_ref = _ref(
        evaluator_metrics_artifact_ref,
        "run provenance evaluator metrics artifact ref",
    )
    commitments = _canonical_mapping(
        evaluator_commitments, "run provenance evaluator commitments"
    )
    if type(frozen) is not FrozenAdaptationState or frozen.purpose != purpose:
        raise V2InvariantError("run provenance frozen adaptation differs")
    payload = _run_provenance_closure_payload(
        purpose=purpose,
        authorization_ref=authorization_ref,
        source_seal_ref=source_seal_ref,
        evaluator_commitments_ref=_evaluator_digest(
            "evaluator-commitments", commitments
        ),
        frozen_adaptation_ref=frozen.freeze_ref,
        evaluator_metrics_artifact_ref=evaluator_metrics_artifact_ref,
    )
    artifact_ref = canonical_ref("run-provenance-closure", payload)
    ledger.append_artifact_durable(
        artifact_ref,
        "run-provenance-closure",
        payload,
    )
    return artifact_ref


async def _close_orchestration(
    dependencies: OrchestrationDependencies,
    *,
    failure_mode: bool = False,
) -> None:
    if type(failure_mode) is not bool:
        raise TypeError("orchestration failure mode differs")
    errors: list[BaseException] = []
    provisional_preclose: V2IntegrityStop | None = None
    try:
        dependencies.path_allocations.assert_closed()
    except BaseException as error:
        preclose = _redacted_cleanup_failure(
            error, "V2_PATH_REGISTRY_PRECLOSE_FAILED"
        )
        if failure_mode:
            provisional_preclose = preclose
        else:
            errors.append(preclose)

    def retain_provisional_preclose() -> None:
        nonlocal provisional_preclose
        if provisional_preclose is not None:
            errors.append(provisional_preclose)
            provisional_preclose = None

    close_evaluator = getattr(dependencies.evaluator, "close", None)
    evaluator_close_failed = False
    if callable(close_evaluator):
        try:
            await _maybe_await(close_evaluator())
        except BaseException as error:
            evaluator_close_failed = True
            errors.append(
                _redacted_cleanup_failure(error, "V2_EVALUATOR_CLOSE_FAILED")
            )
    else:
        evaluator_close_failed = True
        errors.append(V2IntegrityStop("V2_EVALUATOR_CLOSE_FAILED"))
    if (
        evaluator_close_failed
        or type(dependencies.evaluator) is EvaluatorProcessClient
    ) and not _evaluator_terminal_is_proven(dependencies.evaluator):
        retain_provisional_preclose()
        _retain_unresolved_live_orchestration(
            dependencies.evaluator, dependencies
        )
        errors.append(V2IntegrityStop("V2_EVALUATOR_REAP_UNPROVEN"))
        raise ExceptionGroup("V2 cleanup failed", errors) from None
    if _UNRESOLVED_EVALUATOR_PROCESSES:
        retain_provisional_preclose()
        unresolved = tuple(_UNRESOLVED_EVALUATOR_PROCESSES.values())
        _retain_unresolved_live_orchestration(
            unresolved[0], *unresolved[1:], dependencies
        )
        errors.append(V2IntegrityStop("V2_EVALUATOR_FACTORY_REAP_UNPROVEN"))
        raise ExceptionGroup("V2 cleanup failed", errors) from None
    try:
        await _maybe_await(dependencies.close_runtime())
    except BaseException as error:
        retain_provisional_preclose()
        errors.append(
            _redacted_cleanup_failure(error, "V2_RUNTIME_CLOSE_FAILED")
        )
        try:
            _retain_unresolved_live_orchestration(
                dependencies.evaluator, dependencies
            )
        except BaseException as retention_error:
            errors.append(
                _redacted_cleanup_failure(
                    retention_error,
                    "V2_RUNTIME_CLOSE_AUTHORITY_RETENTION_FAILED",
                )
            )
        raise ExceptionGroup("V2 cleanup failed", errors) from None
    postclose_failed = False
    try:
        assert_postclose = (
            getattr(
                dependencies.path_allocations,
                "assert_failure_accounted",
                None,
            )
            if failure_mode
            else None
        )
        if not callable(assert_postclose):
            assert_postclose = dependencies.path_allocations.assert_closed
        assert_postclose()
    except BaseException as error:
        postclose_failed = True
        retain_provisional_preclose()
        errors.append(
            _redacted_cleanup_failure(
                error, "V2_PATH_REGISTRY_POSTCLOSE_FAILED"
            )
        )
    if postclose_failed:
        try:
            _retain_unresolved_live_orchestration(
                dependencies.evaluator, dependencies
            )
        except BaseException as retention_error:
            errors.append(
                _redacted_cleanup_failure(
                    retention_error,
                    "V2_POSTCLOSE_AUTHORITY_RETENTION_FAILED",
                )
            )
        raise ExceptionGroup("V2 cleanup failed", errors) from None
    provisional_preclose = None
    try:
        dependencies.ledger.close()
    except BaseException as error:
        errors.append(
            _redacted_cleanup_failure(error, "V2_LEDGER_CLOSE_FAILED")
        )
        try:
            _retain_unresolved_live_orchestration(
                dependencies.evaluator, dependencies
            )
        except BaseException as retention_error:
            errors.append(
                _redacted_cleanup_failure(
                    retention_error,
                    "V2_LEDGER_CLOSE_AUTHORITY_RETENTION_FAILED",
                )
            )
        raise ExceptionGroup("V2 cleanup failed", errors) from None
    _release_retained_live_orchestration(
        dependencies.evaluator, dependencies
    )
    if errors:
        raise ExceptionGroup("V2 cleanup failed", errors) from None


async def _finish_injected_run(
    dependencies: OrchestrationDependencies,
    *,
    result: dict[str, object] | None,
    primary: V2IntegrityStop | None,
) -> dict[str, object]:
    cleanup: V2IntegrityStop | None = None
    try:
        await _close_orchestration(
            dependencies,
            failure_mode=primary is not None,
        )
    except BaseException as error:
        cleanup = _redacted_cleanup_failure(error, "V2_RUN_CLEANUP_FAILED")
    if primary is not None and cleanup is not None:
        raise ExceptionGroup(
            "V2 run and cleanup failed", [primary, cleanup]
        ) from None
    if primary is not None:
        raise primary from None
    if cleanup is not None:
        raise cleanup from None
    if type(result) is not dict:
        raise V2IntegrityStop("V2 run produced no terminal result")
    integrity = result.get("integrity")
    expected_ledger = (
        None if type(integrity) is not dict else integrity.get("ledger")
    )
    expected_attempts = (
        72
        if dependencies.mode is RunMode.QUALIFICATION
        else 918
        if dependencies.mode is RunMode.EVALUATION
        else None
    )
    if (
        type(expected_ledger) is not dict
        or expected_attempts is None
        or not dependencies.ledger._sealed
        or not dependencies.ledger._closed
        or audit_evidence_ledger(
            dependencies.ledger.path,
            expected_attempts=expected_attempts,
        )
        != expected_ledger
    ):
        raise V2IntegrityStop("V2 final evidence-ledger rejoin differs")
    return result


async def run_qualification_injected(
    dependencies: OrchestrationDependencies,
    *,
    qualification_release_ref: str,
) -> dict[str, object]:
    """Execute the exact 72-attempt technical qualification with fakes/live deps."""

    if type(dependencies) is not OrchestrationDependencies:
        raise TypeError("dependencies must be exact OrchestrationDependencies")
    if dependencies.mode is not RunMode.QUALIFICATION:
        raise V2InvariantError("qualification dependencies use another mode")
    qualification_release_ref = _ref(
        qualification_release_ref, "qualification run authorization"
    )
    attempts: list[AttemptFinal] = []
    adaptation_attempts: list[AttemptFinal] = []
    pair_equalities: list[PairEqualityEvidence] = []
    result: dict[str, object] | None = None
    primary: V2IntegrityStop | None = None
    try:
        source_seal = await _maybe_await(dependencies.verify_source_seal())
        _ref(source_seal, "qualification source seal")
        adaptation = await _release_phase(dependencies.evaluator, "adaptation")
        if len(adaptation) != EXPECTED_QUALIFICATION_PHASE_TASKS["adaptation"]:
            raise V2InvariantError("qualification adaptation task count differs")
        for scheduled in adaptation_schedule(adaptation, purpose="qualification"):
            prompt = await _maybe_await(
                dependencies.prepare_adaptation_attempt(scheduled)
            )
            if type(prompt) is not PromptPlan:
                raise TypeError("adaptation prompt preparation differs")
            final = await _execute_one_attempt(dependencies, scheduled, prompt)
            attempts.append(final)
            adaptation_attempts.append(final)
        await _complete_phase(dependencies.evaluator, "adaptation")
        frozen = await _maybe_await(
            dependencies.freeze_adaptation(tuple(adaptation_attempts))
        )
        if type(frozen) is not FrozenAdaptationState or frozen.purpose != "qualification":
            raise V2InvariantError("qualification adaptation freeze differs")
        _materialize_frozen_state(dependencies.ledger, frozen)
        development = await _release_phase(dependencies.evaluator, "development")
        if len(development) != EXPECTED_QUALIFICATION_PHASE_TASKS["development"]:
            raise V2InvariantError("qualification development task count differs")
        schedule = development_final_schedule(
            development, purpose="qualification", phase="development"
        )
        for block in _schedule_blocks(schedule):
            finals, equality = await _execute_prepared_task_block(
                dependencies, block, frozen
            )
            attempts.extend(finals)
            pair_equalities.extend(equality)
        await _complete_phase(dependencies.evaluator, "development")
        if len(attempts) != 72:
            raise V2InvariantError("qualification attempt count differs")
        metrics_method = getattr(dependencies.evaluator, "final_metrics", None)
        if not callable(metrics_method):
            raise TypeError("qualification evaluator lacks final_metrics")
        metrics = _canonical_mapping(
            await _maybe_await(metrics_method()), "qualification final metrics"
        )
        final_source_seal = await _maybe_await(dependencies.verify_source_seal())
        if final_source_seal != source_seal:
            raise V2IntegrityStop("qualification source seal changed during execution")
        accounting = dependencies.attempt_budget.snapshot()
        if accounting["arm_tasks"] != 72:
            raise V2InvariantError("qualification attempt budget did not close")
        evaluator_commitments = _canonical_mapping(
            getattr(dependencies.evaluator, "commitments", None),
            "qualification evaluator commitments",
        )
        metrics_artifact_ref = _materialize_evaluator_metrics(
            dependencies.ledger, metrics
        )
        _materialize_run_provenance_closure(
            dependencies.ledger,
            purpose="qualification",
            authorization_ref=qualification_release_ref,
            source_seal_ref=source_seal,
            evaluator_commitments=evaluator_commitments,
            frozen=frozen,
            evaluator_metrics_artifact_ref=metrics_artifact_ref,
        )
        ledger_witness = dependencies.ledger.seal(expected_attempts=72)
        result = build_run_result(
            purpose="qualification",
            attempts=attempts,
            pair_equalities=pair_equalities,
            frozen=frozen,
            evaluator_commitments=evaluator_commitments,
            evaluator_metrics=metrics,
            statistics=None,
            accounting=accounting,
            resources=dependencies.resources.to_canonical(),
            source_seal_ref=source_seal,
            ledger_witness=ledger_witness,
            authorization_ref=qualification_release_ref,
        )
    except BaseException as error:
        primary = _redacted_failure(error, "V2_QUALIFICATION_RUN_FAILED")
    return await _finish_injected_run(
        dependencies, result=result, primary=primary
    )


async def run_evaluation_injected(
    dependencies: OrchestrationDependencies,
    *,
    admission_ref: str,
) -> dict[str, object]:
    """Execute the exact 918-attempt evaluation without an operator gap."""

    if type(dependencies) is not OrchestrationDependencies:
        raise TypeError("dependencies must be exact OrchestrationDependencies")
    if dependencies.mode is not RunMode.EVALUATION:
        raise V2InvariantError("evaluation dependencies use another mode")
    admission_ref = _ref(admission_ref, "evaluation run authorization")
    attempts: list[AttemptFinal] = []
    adaptation_attempts: list[AttemptFinal] = []
    pair_equalities: list[PairEqualityEvidence] = []
    result: dict[str, object] | None = None
    primary: V2IntegrityStop | None = None
    try:
        source_seal = await _maybe_await(dependencies.verify_source_seal())
        _ref(source_seal, "evaluation source seal")
        adaptation = await _release_phase(dependencies.evaluator, "adaptation")
        if len(adaptation) != EXPECTED_EVALUATION_PHASE_TASKS["adaptation"]:
            raise V2InvariantError("evaluation adaptation task count differs")
        for scheduled in adaptation_schedule(adaptation, purpose="evaluation"):
            prompt = await _maybe_await(
                dependencies.prepare_adaptation_attempt(scheduled)
            )
            if type(prompt) is not PromptPlan:
                raise TypeError("adaptation prompt preparation differs")
            final = await _execute_one_attempt(dependencies, scheduled, prompt)
            attempts.append(final)
            adaptation_attempts.append(final)
        await _complete_phase(dependencies.evaluator, "adaptation")
        frozen = await _maybe_await(
            dependencies.freeze_adaptation(tuple(adaptation_attempts))
        )
        if type(frozen) is not FrozenAdaptationState or frozen.purpose != "evaluation":
            raise V2InvariantError("evaluation adaptation freeze differs")
        _materialize_frozen_state(dependencies.ledger, frozen)

        development = await _release_phase(dependencies.evaluator, "development")
        if len(development) != EXPECTED_EVALUATION_PHASE_TASKS["development"]:
            raise V2InvariantError("evaluation development task count differs")
        schedule = development_final_schedule(
            development, purpose="evaluation", phase="development"
        )
        for block in _schedule_blocks(schedule):
            finals, equality = await _execute_prepared_task_block(
                dependencies, block, frozen
            )
            attempts.extend(finals)
            pair_equalities.extend(equality)
        await _complete_phase(dependencies.evaluator, "development")

        pre_admission_source_seal = await _maybe_await(
            dependencies.verify_source_seal()
        )
        if pre_admission_source_seal != source_seal:
            raise V2IntegrityStop("evaluation source seal changed before admission")
        admit = getattr(dependencies.evaluator, "admit_final", None)
        if not callable(admit):
            raise TypeError("evaluation evaluator lacks admit_final")
        await _maybe_await(admit(admission_ref))
        final_tasks = await _release_phase(dependencies.evaluator, "final")
        if len(final_tasks) != EXPECTED_EVALUATION_PHASE_TASKS["final"]:
            raise V2InvariantError("evaluation final task count differs")
        schedule = development_final_schedule(
            final_tasks, purpose="evaluation", phase="final"
        )
        final_attempts: list[AttemptFinal] = []
        for block in _schedule_blocks(schedule):
            finals, equality = await _execute_prepared_task_block(
                dependencies, block, frozen
            )
            attempts.extend(finals)
            final_attempts.extend(finals)
            pair_equalities.extend(equality)
        await _complete_phase(dependencies.evaluator, "final")
        if len(attempts) != 918 or len(final_attempts) != 432:
            raise V2InvariantError("evaluation attempt denominator differs")
        metrics_method = getattr(dependencies.evaluator, "final_metrics", None)
        if not callable(metrics_method):
            raise TypeError("evaluation evaluator lacks final_metrics")
        metrics = _canonical_mapping(
            await _maybe_await(metrics_method()), "evaluation final metrics"
        )
        statistics = finite_cohort_statistics(final_attempts)
        accounting = dependencies.attempt_budget.snapshot()
        if accounting["arm_tasks"] != 918:
            raise V2InvariantError("evaluation attempt budget did not close")
        final_source_seal = await _maybe_await(dependencies.verify_source_seal())
        if final_source_seal != source_seal:
            raise V2IntegrityStop("evaluation source seal changed during execution")
        evaluator_commitments = _canonical_mapping(
            getattr(dependencies.evaluator, "commitments", None),
            "evaluation evaluator commitments",
        )
        metrics_artifact_ref = _materialize_evaluator_metrics(
            dependencies.ledger, metrics
        )
        _materialize_run_provenance_closure(
            dependencies.ledger,
            purpose="evaluation",
            authorization_ref=admission_ref,
            source_seal_ref=source_seal,
            evaluator_commitments=evaluator_commitments,
            frozen=frozen,
            evaluator_metrics_artifact_ref=metrics_artifact_ref,
        )
        ledger_witness = dependencies.ledger.seal(expected_attempts=918)
        result = build_run_result(
            purpose="evaluation",
            attempts=attempts,
            pair_equalities=pair_equalities,
            frozen=frozen,
            evaluator_commitments=evaluator_commitments,
            evaluator_metrics=metrics,
            statistics=statistics,
            accounting=accounting,
            resources=dependencies.resources.to_canonical(),
            source_seal_ref=source_seal,
            ledger_witness=ledger_witness,
            authorization_ref=admission_ref,
        )
    except BaseException as error:
        primary = _redacted_failure(error, "V2_EVALUATION_RUN_FAILED")
    return await _finish_injected_run(
        dependencies, result=result, primary=primary
    )


def _validate_result_publication_rejoin(
    *,
    expected_result: Mapping[str, object],
    loaded_result: Mapping[str, object],
    publication_receipt: Mapping[str, object],
    result_path: Path,
    result_sha256: str,
) -> None:
    """Bind a create-once publication receipt to its reopened canonical result."""

    if dict(loaded_result) != dict(expected_result):
        raise V2IntegrityStop("published result bytes differ from run result")
    canonical = canonical_json_bytes(dict(loaded_result))
    expected_receipt = {
        "bytes": len(canonical),
        "path": str(result_path),
        "result_ref": loaded_result.get("result_ref"),
        "sha256": _raw_digest(result_sha256, "published result digest"),
    }
    if dict(publication_receipt) != expected_receipt:
        raise V2IntegrityStop("published result receipt differs")


async def run_live_qualification() -> dict[str, object]:
    """Authorize, execute, close, rejoin, and publish one live qualification."""

    validate_live_phase_topology("pre-qualification")
    manifest, manifest_sha256, source_seal = load_source_manifest()
    precreate_host = validate_live_parent_boundary(
        require_unassigned_zero_processes=True,
        temporary_directory_state="absent",
        activate_cuda_runtime=False,
    )
    validate_live_phase_topology("pre-qualification")
    current_manifest, current_sha256, current_seal = load_source_manifest()
    if (
        current_manifest != manifest
        or current_sha256 != manifest_sha256
        or current_seal != source_seal
    ):
        raise V2IntegrityStop("qualification source changed before root creation")
    create_qualification_live_roots_once()
    host = validate_live_parent_boundary(
        require_unassigned_zero_processes=True
    )
    validate_live_parent_boundary_rejoin(precreate_host, host)
    current_manifest, current_sha256, current_seal = load_source_manifest()
    if (
        current_manifest != manifest
        or current_sha256 != manifest_sha256
        or current_seal != source_seal
    ):
        raise V2IntegrityStop("qualification source changed during root creation")
    callbacks = LiveBoundaryCallbacks.create_live(
        manifest=manifest,
        manifest_sha256=manifest_sha256,
        source_seal=source_seal,
    )
    release = build_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    published_release, release_sha256 = (
        publish_qualification_release_claim_create_once(
            release, manifest, manifest_sha256, source_seal
        )
    )
    loaded_release, loaded_release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    if (
        published_release != release
        or loaded_release != release
        or loaded_release_sha256 != release_sha256
    ):
        raise V2IntegrityStop("qualification release publication differs")
    dependencies = await _create_live_orchestration(
        "qualification",
        callbacks=callbacks,
        replicate_commitments=(qualification_replicate_commitment(),),
    )
    result = await run_qualification_injected(
        dependencies,
        qualification_release_ref=release["release_ref"],
    )
    current_manifest, current_sha256, current_seal = load_source_manifest()
    current_release, current_release_sha256 = load_qualification_release_claim(
        current_manifest, current_sha256, current_seal
    )
    if (
        current_manifest != manifest
        or current_sha256 != manifest_sha256
        or current_seal != source_seal
        or current_release != release
        or current_release_sha256 != release_sha256
    ):
        raise V2IntegrityStop("qualification chain changed before publication")
    _require_empty_evaluator_private_paths()
    published = publish_run_result_create_once(QUALIFICATION_RESULT_PATH, result)
    loaded, result_sha256 = load_qualification_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_qualification_release_ref=release["release_ref"],
    )
    _validate_result_publication_rejoin(
        expected_result=result,
        loaded_result=loaded,
        publication_receipt=published,
        result_path=QUALIFICATION_RESULT_PATH,
        result_sha256=result_sha256,
    )
    validate_live_phase_topology("pre-seed")
    return {
        "host_environment_sha256": host["environment_sha256"],
        "qualification_release_ref": release["release_ref"],
        "result_path": str(QUALIFICATION_RESULT_PATH),
        "result_ref": published["result_ref"],
        "result_sha256": result_sha256,
        "source_seal_ref": source_seal["source_seal_ref"],
    }


async def run_live_evaluation() -> dict[str, object]:
    """Execute and publish one admitted live evaluation without an operator gap."""

    host = validate_live_parent_boundary(require_unassigned_zero_processes=True)
    validate_live_phase_topology("pre-evaluation")
    manifest, manifest_sha256, source_seal = load_source_manifest()
    release, release_sha256 = load_qualification_release_claim(
        manifest, manifest_sha256, source_seal
    )
    qualification, qualification_sha256 = load_qualification_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_qualification_release_ref=release["release_ref"],
    )
    admission, admission_sha256 = load_evaluation_admission_claim()
    expected_boundary = _evaluation_admission_boundary(
        manifest_ref=manifest["manifest_ref"],
        manifest_sha256=manifest_sha256,
        qualification_result_ref=qualification["result_ref"],
        qualification_result_sha256=qualification_sha256,
        qualification_release_ref=release["release_ref"],
        source_seal_ref=source_seal["source_seal_ref"],
    )
    if any(admission.get(name) != value for name, value in expected_boundary.items()):
        raise V2IntegrityStop("evaluation admission chain differs")
    verify_evaluation_seed_artifact_isolated(admission, admission_sha256)
    callbacks = LiveBoundaryCallbacks.create_live(
        manifest=manifest,
        manifest_sha256=manifest_sha256,
        source_seal=source_seal,
    )
    commitments = validate_evaluation_seed_commitments(
        admission["seed_commitments"]
    )
    dependencies = await _create_live_orchestration(
        "evaluation",
        callbacks=callbacks,
        replicate_commitments=commitments,
        final_admission_ref=admission["admission_ref"],
        seed_receipt=admission["seed_seal_receipt"],
        evaluator_commitments=admission["evaluator_commitments"],
    )
    result = await run_evaluation_injected(
        dependencies,
        admission_ref=admission["admission_ref"],
    )
    current_manifest, current_sha256, current_seal = load_source_manifest()
    current_release, current_release_sha256 = load_qualification_release_claim(
        current_manifest, current_sha256, current_seal
    )
    current_qualification, current_qualification_sha256 = load_qualification_result(
        expected_source_seal_ref=current_seal["source_seal_ref"],
        expected_qualification_release_ref=current_release["release_ref"],
    )
    current_admission, current_admission_sha256 = load_evaluation_admission_claim()
    if (
        current_manifest != manifest
        or current_sha256 != manifest_sha256
        or current_seal != source_seal
        or current_release != release
        or current_release_sha256 != release_sha256
        or current_qualification != qualification
        or current_qualification_sha256 != qualification_sha256
        or current_admission != admission
        or current_admission_sha256 != admission_sha256
    ):
        raise V2IntegrityStop("evaluation chain changed before publication")
    verify_evaluation_seed_artifact_isolated(
        current_admission, current_admission_sha256
    )
    published = publish_run_result_create_once(EVALUATION_RESULT_PATH, result)
    loaded, result_sha256 = load_evaluation_result(
        expected_source_seal_ref=source_seal["source_seal_ref"],
        expected_admission_ref=admission["admission_ref"],
    )
    _validate_result_publication_rejoin(
        expected_result=result,
        loaded_result=loaded,
        publication_receipt=published,
        result_path=EVALUATION_RESULT_PATH,
        result_sha256=result_sha256,
    )
    terminal = validate_live_terminal_topology()
    if (
        terminal["evaluation_result_ref"] != published["result_ref"]
        or terminal["evaluation_result_sha256"] != result_sha256
    ):
        raise V2IntegrityStop("evaluation terminal topology result differs")
    return {
        "admission_ref": admission["admission_ref"],
        "host_environment_sha256": host["environment_sha256"],
        "result_path": str(EVALUATION_RESULT_PATH),
        "result_ref": published["result_ref"],
        "result_sha256": result_sha256,
        "source_seal_ref": source_seal["source_seal_ref"],
    }


def _read_cli_canonical_mapping(*, maximum_bytes: int) -> dict[str, object]:
    maximum = _integer(maximum_bytes, "CLI input byte ceiling", minimum=1)
    raw = sys.stdin.buffer.read(maximum + 1)
    if not raw or len(raw) > maximum:
        raise V2IntegrityStop("CLI canonical input is absent or exceeds its bound")
    try:
        value = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise V2IntegrityStop("CLI canonical input is malformed") from error
    return _canonical_mapping(value, "CLI canonical input")


def _write_cli_canonical(value: Mapping[str, object]) -> None:
    sys.stdout.buffer.write(canonical_json_bytes(dict(value)) + b"\n")
    sys.stdout.buffer.flush()


def main(argv: Sequence[str] | None = None) -> None:
    parser = argparse.ArgumentParser(
        description="Project Angler V2 history isolation",
        allow_abbrev=False,
    )
    actions = parser.add_mutually_exclusive_group(required=True)
    actions.add_argument(
        "--evaluator-worker", action="store_true", help=argparse.SUPPRESS
    )
    actions.add_argument(
        "--evaluation-commitment-worker",
        action="store_true",
        help=argparse.SUPPRESS,
    )
    actions.add_argument(
        "--evaluation-seed-verifier-worker",
        action="store_true",
        help=argparse.SUPPRESS,
    )
    actions.add_argument(
        "--foundation-mirror-preflight-root",
        action="store_true",
        help=argparse.SUPPRESS,
    )
    actions.add_argument(
        "--foundation-mirror-preflight-child",
        nargs=2,
        metavar=("PARENT_MOUNT_NAMESPACE", "PARENT_NETWORK_NAMESPACE"),
        help=argparse.SUPPRESS,
    )
    actions.add_argument(
        "--foundation-mirror-preflight",
        action="store_true",
        help="run the isolated read-only foundation mirror preflight",
    )
    actions.add_argument(
        "--source-manifest-candidate",
        action="store_true",
        help="build a source manifest candidate from a receipt on stdin",
    )
    actions.add_argument(
        "--publish-reviewed-source-manifest",
        metavar="SHA256",
        help="publish the reviewed candidate using a receipt on stdin",
    )
    actions.add_argument(
        "--qualification",
        action="store_true",
        help="execute the one-use live technical qualification",
    )
    actions.add_argument(
        "--prepare-evaluation-admission",
        action="store_true",
        help="seal evaluation seeds and publish their admission",
    )
    actions.add_argument(
        "--evaluation",
        action="store_true",
        help="execute the one-use admitted live evaluation",
    )
    arguments = parser.parse_args(argv)
    if arguments.evaluator_worker:
        raise SystemExit(evaluator_worker_main())
    if arguments.evaluation_commitment_worker:
        raise SystemExit(evaluation_commitment_worker_main())
    if arguments.evaluation_seed_verifier_worker:
        raise SystemExit(evaluation_seed_verifier_worker_main())
    if arguments.foundation_mirror_preflight_root:
        raise SystemExit(foundation_mirror_preflight_root_main())
    if arguments.foundation_mirror_preflight_child is not None:
        parent_mount_namespace, parent_network_namespace = (
            arguments.foundation_mirror_preflight_child
        )
        raise SystemExit(
            foundation_mirror_preflight_child_main(
                parent_mount_namespace,
                parent_network_namespace,
            )
        )
    if arguments.foundation_mirror_preflight:
        _write_cli_canonical(run_foundation_mirror_preflight_live())
        return
    if arguments.source_manifest_candidate:
        receipt = _read_cli_canonical_mapping(
            maximum_bytes=FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES
        )
        _write_cli_canonical(build_source_manifest_candidate(receipt))
        return
    if arguments.publish_reviewed_source_manifest is not None:
        receipt = _read_cli_canonical_mapping(
            maximum_bytes=FOUNDATION_PREFLIGHT_MAXIMUM_OUTPUT_BYTES
        )
        _write_cli_canonical(
            publish_reviewed_source_manifest(
                arguments.publish_reviewed_source_manifest, receipt
            )
        )
        return
    if arguments.qualification:
        _write_cli_canonical(asyncio.run(run_live_qualification()))
        return
    if arguments.prepare_evaluation_admission:
        _write_cli_canonical(prepare_evaluation_admission_live())
        return
    if arguments.evaluation:
        _write_cli_canonical(asyncio.run(run_live_evaluation()))
        return
    parser.error("no authorized V2 action was selected")


if __name__ == "__main__":
    main()
